INSERT INTO #PVC VALUES (7621, N'123307', N'81043245', N'Pressão Rápida', NULL, N'Others/Outros', N' mangueira  curta, não possuía bico e não apresentava pressão adequada, o que dificultava significativamente a atividade de limpeza.', N'Produtividade', N'10054', N'01 - Imagens/01 - Antes/7621.jpeg', N' mangueira  curta, não possuía bico e não apresentava pressão adequada, o que dificultava significativamente a atividade de limpeza.', N'01 - Imagens/02 - Depois/7621.jpeg', N' Substituída mangueira adequada com bico para alta pressão,  para melhor execução da tarefa, o que garantiu produtividade pa ', NULL, N'Sim, substituído mangueira adequada com bico para alta pressão,  para execução da tarefa.', N'Produtividade', 0, NULL, N'Melhoria', '2026-01-22T00:00:00.000', '2026-01-24T11:12:58.000', N'123307', NULL, 1);
