INSERT INTO #PVC VALUES (7731, N'460346', N'81023780', N'Backwash Solids Storage', NULL, N'Refining/Refino', N'Storage is required for our backwash press solids in cobalt SX', N'Make storage', N'0', N'01 - Imagens/01 - Antes/7731.jpeg', N'Recently our backwash filter press in Co is producing more solids and this required us to modify how we empty it and create solids storage.  The picture is of the tote without the label', N'01 - Imagens/02 - Depois/7731.jpeg', N'We made an area to store the clean pack for solids and labelled it as such, as shown in the attached photos', NULL, N'Yes', N'Change management ', 0, NULL, N'Segurança operacional', '2026-01-28T00:00:00.000', '2026-01-29T04:49:03.000', N'460346', NULL, 1);
INSERT INTO #PVC VALUES (7732, N'81054991', N'81017050', N'5S', NULL, N'Projects/Projetos', N'ausência de identificação das mesas', N'5S organização', N'0', N'01 - Imagens/01 - Antes/7732.jpeg', N'as mesas se encontravam sem identificação ou fora do padrão', N'01 - Imagens/02 - Depois/7732.jpeg', N'agora com a identificação as mesas ficaram mais organizadas', NULL, N'sim', N'5S', 0, NULL, N'SIM', '2026-01-28T00:00:00.000', '2026-01-29T04:51:35.000', N'81054991', NULL, 1);
INSERT INTO #PVC VALUES (7733, N'460346', N'1014901', N'H2S line signage', NULL, N'Refining/Refino', N'H2S lines in Cd run above the Nitrogen bank', N'Add signage to alert of H2S in lines above', N'0', N'01 - Imagens/01 - Antes/7733.jpeg', N'H2S lines run over the Nitrogen bank and storage area.  ', N'01 - Imagens/02 - Depois/7733.jpeg', N'Signage add to ensure people moving the nitrogen bank know to be careful when adding and removing cylinders', NULL, N'YES', N'More information is better', 0, NULL, N'Após a implantação, as equipes de manutenção e operação relataram maior confiança na realização das atividades, além de uma percepção clara de redução de riscos associados à baixa visibilidade. A solução também contribuiu para maior conformidade com padrões de segurança e boas práticas industriais, elevando o nível de controle operacional no setor.', '2026-01-28T00:00:00.000', '2026-01-29T05:04:58.000', N'460346', NULL, 1);
INSERT INTO #PVC VALUES (7734, N'81039718', N'81039718', N'Mill Lube Program PM Optimization - Phase 1', NULL, N'Underground/Subterrâneo', N'The current PMs that are scheduled for Mill Lube Techs are not efficient and schedule loading was sub-optimal.', N'To optimize Mill Lube Tech planned routes.', N'10096', N'01 - Imagens/01 - Antes/7734.jpeg', N'- Many lube routes were not defined with tasks or procedures.
