INSERT INTO #PVC VALUES (7745, N'81047115', N'81040288', N'suporte para mangueiras', NULL, N'Others/Outros', N'AMBIENTE DEZORGANIZADO E MANGUEIRAS ESPALHADAS  ', N'organização do ambiente', N'10362', N'01 - Imagens/01 - Antes/7745.jpeg', N'AMBIENTE DEZORGANIZADO E MANGUEIRAS ESPALHADAS  ', N'01 - Imagens/02 - Depois/7745.jpeg', N'FABRICADO SUPORTE PARA ORGANIZAÇÃO DAS MANGUEIRAS E MELHORIAS ASCPECTO VISUAL DO AMBIENTE', NULL, N'SIM', N'MELHORIA CONTINUA', 0, NULL, N'A aquisição de um suporte comercial demandaria um tempo elevado para verificação, compra e entrega, o que atrasaria na instalação do painel.', '2026-01-28T00:00:00.000', '2026-01-29T14:53:36.000', N'81047115', NULL, 1);
INSERT INTO #PVC VALUES (7746, N'499302', N'538357', N'Kaizen - Iluminação Inteligente', NULL, N'Others/Outros', N'A baixa iluminação em áreas da indústria durante a execução de atividades de limpeza, inspeção e manutenção representa um risco significativo para a integridade física dos trabalhadores e para a continuidade operacional. Esse problema ocorre principalmente em locais confinados, galerias, áreas subterrâneas, plantas industriais com iluminação insuficiente ou durante intervenções noturnas e emergenciais, onde a iluminação fixa não é adequada.
INSERT INTO #PVC VALUES (7747, N'81005006', N'81005006', N'acesso do portão do CTM', NULL, N'No Replication/Sem replicação', N'acesso não apropriado para passagem da paleteira  elétrica devido desgastes e grades de ferros .
INSERT INTO #PVC VALUES (7748, N'81055953', N'81055953', N'Belt Filter ', NULL, N'Others/Outros', N'Belt filter cloth alignment system not working. operations called to replace it for start up after DFR.', N'Get belt filter back online safely', N'0', N'01 - Imagens/01 - Antes/7748.jpeg', N'Operations called with a YEM request that Belt filter 3 could not come back online due to alignment system not working and needed to be replaced.', N'01 - Imagens/02 - Depois/7748.jpeg', N'Before ordering parts to replace system, myself and instrumentation technician went to inspect and troubleshoot system. we found that there was concentrate build up inside the  shifter that had hardened causing it to seize. after we removed the concentrate, the shifter worked perfectly.', NULL, N'yes ', N'Inspect before repair', 1500, 3, N'Atendimento aos padrões de ergonomia,Eliminação do improviso na montagem do bebedouro,Maior durabilidade e facilidade de limpeza.', '2026-01-18T00:00:00.000', '2026-01-29T15:30:19.000', N'81055953', NULL, 1);
