INSERT INTO #PVC VALUES (7926, N'1008564', N'1009524', N'Longer screws on table', NULL, N'Refining/Refino', N'Longer screws on table on the Maintenance Crane for laying the Anodes on when doing cell maintenance.', N'Better to hold down the top of the table.', N'0', N'01 - Imagens/01 - Antes/7926.jpeg', N'Screws were too short', N'01 - Imagens/02 - Depois/7926.jpeg', N'Longer screws', NULL, N'Yes', N'Needed longer screws', 0, NULL, N'eliminado o risco ergonômico, facilitando o trabalho com empilhadeira. ', '2026-02-02T00:00:00.000', '2026-02-03T17:06:11.000', N'1008564', NULL, 1);
