INSERT INTO #PVC VALUES (7973, N'81013885', N'81013885', N'SUPORTE SECADOR', NULL, N'No Replication/Sem replicação', N'ANTES EQUIPAMENTO NAO TINHA UMA BASE ADEQUADA, DEIXANDO O EQUIPAMENTO EM CONDIÇÕES DE DESGASTE.', N'CONFIABILIDADE DO EQUIPAMENTO', N'10362', N'01 - Imagens/01 - Antes/7973.jpeg', N'ANTES EQUIPAMENTO NAO TINHA UMA BASE ADEQUADA, DEIXANDO O EQUIPAMENTO EM CONDIÇÕES DE DESGASTE.', N'01 - Imagens/02 - Depois/7973.jpeg', N'DEPOIS FOI FABRICADO UMA BASE METALICA E FEITO A INSTALAÇÃO DO EQUIPAMENTO NO LOCAL, TENDO O GANHO DE CONFIABILIDADE E PRODUÇAO DO MESMO.', NULL, N'SIM, COM A INTALAÇAO DA BASE O EQUIPAMENTO TEM O GANHO DE CONFIABILADE OPERACIOANAL.', N'QUALIDADE NO EQUIPAMENTO', 0, NULL, N'Problema identificado:
