INSERT INTO #PVC VALUES (7975, N'496092', N'496092', N'ALINHAMNETO DA CORREIA', NULL, N'No Replication/Sem replicação', N'DESALINHAMENTO CONSTATE DA CORREIA,  IMPACTANDO NA PARADA DO EQUIPAMENTO DEVIDO A CORREIA FACIAR NA ESTRUTURA METALICA.', N'MELHORAR ALINHAMENTO DA CORREIA, PARA NAO PEGAR NA ESTRUTURA', N'10280', N'01 - Imagens/01 - Antes/7975.jpeg', N'DESALINHAMENTO CONSTATE DA CORREIA,  IMPACTANDO NA PARADA DO EQUIPAMENTO DEVIDO A CORREIA FACIAR NA ESTRUTURA METALICA, COM ISSO HAVIA NESCESSIDADE DA EQUIPE MANUTENÇÃO SER ACIONADA PARA REALIZAR O ALINHAMENTO DA CORREIA.
INSERT INTO #PVC VALUES (7976, N'200463', N'200463', N'PCR -Lab Oven sample management', NULL, N'Others/Outros', N'Use new oven for AgCl and LOI', N'Products in cleaner environment', N'10019', N'01 - Imagens/01 - Antes/7976.jpeg', N'Possible contamination from process samples for high purity samples.', N'01 - Imagens/02 - Depois/7976.jpeg', N'cleaner oven with less contamination.', NULL, N'Yes', N'None', 0, NULL, N'Melhor forma de acondicionar folhas de papel com informações importante relacionado a saúde e segurança.', '2026-02-04T00:00:00.000', '2026-02-05T16:12:42.000', N'200463', NULL, 1);
INSERT INTO #PVC VALUES (7977, N'81040073', N'547828', N'CAÇAMBA DE SUCATA', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE NÃO TINHA UMA CAÇAMBA ADEQUADA PARA DESCARTE DE SUCATAS DE FERRO NA AREA DE FABRICAÇÃO.', N'ORGANIZAÇÃO DA AREA', N'10044', N'01 - Imagens/01 - Antes/7977.jpeg', N'ANTERIORMENTE NÃO TINHA UMA CAÇAMBA ADEQUADA PARA DESCARTE DE SUCATAS DE FERRO NA AREA DE FABRICAÇÃO. SENDO REALIZADO DESCARTE EM LOCAL INADEQUADO.', N'01 - Imagens/02 - Depois/7977.jpeg', N'FOI FABRICADO UMA CAÇAMBA PARA DESCARTE EM LOCAL ADEQUADO DE INSUMOS E SUCATAS.', NULL, N'SIM, POIS O DESCARTE ESTA SENDO REALIZADO NO LOCAL CORRETO, E FACILIDADE PARA DESCARTE DAS SUCATAS.', N'DESCARTE DE MATERIAL NO LOCAL ADEQUADO É MAIS SEGURO', 0, NULL, N'Melhoria de segurança, redução de tempo, redução de custo, aumento de produção e melhoria de processo.', '2026-01-29T00:00:00.000', '2026-02-05T16:13:41.000', N'81040073', NULL, 1);
INSERT INTO #PVC VALUES (7978, N'1010730', N'1010730', N'Boot Brush Replacement', NULL, N'Refining/Refino', N'Boot brushes are required at entrances in 221, 222, and 226 CPL buildings to prevent contamination of walkways outside and in the annex. Currently, the conifiguration creates mess around the boot brush itself. Additionally, sourcing replacement parts and new boot brushes has become excessively expensive due to suppliers being located in the US.', N'Find an alternative boot brush that can be sourced locally and creates less of a mess at entry ways ', N'0', N'01 - Imagens/01 - Antes/7978.jpeg', N'Original set up of boot brush from several years ago. Only cleans bottom of boots and has potential to spray user. Dirt gathers in bottom of grating and needs to be washed down after a handful of uses on heavily soiled boots. Bristles have to be replaced quite often.
INSERT INTO #PVC VALUES (7979, N'81040073', N'81046945', N'PROTEÇÃO ESMERIL', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE NÃO HAVIA PROTEÇÃO NO ESMERIL PODENDO OCASIONAR EM UM ACIEDENTE DEVIDO A FALTA DE PROTEÇÃO.', N'REDUZIR ESPOSIÇÃO HOMEM/ MAQUINAS', N'10044', N'01 - Imagens/01 - Antes/7979.jpeg', N'ANTERIORMENTE NÃO HAVIA PROTEÇÃO NO ESMERIL PODENDO OCASIONAR EM UM ACIEDENTE DEVIDO A FALTA DE PROTEÇÃO.', N'01 - Imagens/02 - Depois/7979.jpeg', N'FOI FABRICADO PROTEÇÃO PARA AMBOS LADOS DO ESMERIL BI-PARTIDOS PARA QUE NO USO DE UM LADO O OUTRO LADO ESTEJA FECHADO. EVITANDO RISCO DE CONTATO COM A MAQUINA.', NULL, N'SIM. FOI REDUZIDO EM 80% DO RISCO DE ACIDENTE NA REALIZAÇÃO DO USO DA MAQUINA.', N'NÃO UTILIZAR EQUIPAMENTOS SEM PROTEÇÃO ', 0, NULL, N'Grande ganho de tempo na obtenção da informação correta e assertiva uma média de 2 horas pra 10 minutos.', '2026-01-27T00:00:00.000', '2026-02-05T16:33:58.000', N'81040073', NULL, 1);
INSERT INTO #PVC VALUES (7980, N'81057538', N'81057538', N'IDENTIFICAÇÃO DE BATERIAS E CARREGADOR', NULL, N'Others/Outros', N'ESTAVA DESORGANIZADOS, DIFICULTANDO A IDENTICAÇÃO DE QUAL BATERIAS ESTAVA CARREGADAS', N'MANTER O CONTROLE DAS BATERIAS CARREGADAS E DESCARREGADAS', N'10235', N'01 - Imagens/01 - Antes/7980.jpeg', N'ESTAVA DESORGANIZADOS, DIFICULTANDO A IDENTICAÇÃO DE QUAL BATERIAS ESTAVA CARREGADAS', N'01 - Imagens/02 - Depois/7980.jpeg', N'COM A MELHORIA NA IDENTIFICAÇAO, CONSEGUIMOS CONTROLAR QUAIS BATERIAS PRECISAVA RECARREGAR', NULL, N'SIM', N'ORGANIZAÇÃO', 0, NULL, N'O kit de emergência ambiental permite uma intervenção eficiente e segura até a chegada de suporte especializado.', '2026-02-04T00:00:00.000', '2026-02-05T18:52:55.000', N'81057538', NULL, 1);
INSERT INTO #PVC VALUES (7981, N'81004462', N'81004462', N'Revisão da Estratégia Troca Tela de Retorno Tanque Hidráulico PC5500', NULL, N'No Replication/Sem replicação', N'Elevado custo de manutenção preventiva, com a troca do filtro tela, sendo que não temos registros de ocorrências de obstrução ou sujeira acumulada nas telas do tanque', N'Otimização de custo e DF', N'10015', N'01 - Imagens/01 - Antes/7981.jpeg', N'Tempo elevado de manutenção para troca do filtro tela do tanque hidráulico da PC5500 e elevado custo de manutenção preventiva, com a troca do filtro tela, sendo que não temos registros de ocorrências de obstrução ou sujeira acumulada nas telas do tanque.
INSERT INTO #PVC VALUES (7982, N'81004462', N'81004462', N'Revisão Atividades Sistemáticas X Condicionais dos Planos Prev. 797F', NULL, N'No Replication/Sem replicação', N'Elevado custo e tempo de manutenção da frota de caminhão 797F', N'Otimização de Custo e melhoria de processo', N'10015', N'01 - Imagens/01 - Antes/7982.jpeg', N'Tempos elevados de parada de manutenção preventiva mecânica, impactando na DF da frota ao longo do ano;
INSERT INTO #PVC VALUES (7983, N'430793', N'430793', N'Adição de corrente na tela principal do sistema de controle', NULL, N'No Replication/Sem replicação', N'Não haviam valores de corrente das SFR’s na tela principal e era necessário abertura de faceplates para visualização', N'Redução de tempo, ganho melhor visibilidade para monitoramento na tela principal', N'10013', N'01 - Imagens/01 - Antes/7983.jpeg', N'Não haviam valores de corrente das SFR’s na tela principal e era necessário abertura de faceplates para visualização. 
INSERT INTO #PVC VALUES (7984, N'524302', N'524302', N'Suporte de teste da bomba sulzer', NULL, N'Crusher/Britadeira', N'Não era possível testar a bomba após a conclusão de reforma, se houvesse qualquer anormalidade só seria possível diagnosticar após a instalação da bomba.', N'Desenvolver algo que permitisse fixar a bomba para realizar o teste.', N'10249', N'01 - Imagens/01 - Antes/7984.jpeg', N'Não era possível testar a bomba', N'01 - Imagens/02 - Depois/7984.jpeg', N'Feito dispositivo para posicionar a bomba no torno e realizar o teste com segurança e qualidade.', NULL, N'Problema foi resolvido, pois agora conseguimos testar as bombas sulzer. ', N'Que é possível testar a bomba.', 0, NULL, N'We are now using an electronic logbook which is more visual and able to find items/errors more swiftly ', '2026-01-15T00:00:00.000', '2026-02-06T04:26:35.000', N'524302', NULL, 1);
