INSERT INTO #PVC VALUES (8995, N'550925', N'550925', N'Melhoria no sistema de escoamento de água do filtro prensa', NULL, N'Others/Outros', N'Ao realizarmos a filtragem das amostras no filtro prensa o mesmo possui duas saídas de escoamento da água tendo que ser colocado baldes abaixo de cada ponto para a captura da água, esvaziando os baldes todas vez que enche, pois a sala não possui uma contenção para o filtro, gerando esforço físico e uma locomoção maior.', N'Concentrar o escoamento da água em um só ponto.', N'10363', N'01 - Imagens/01 - Antes/8995.jpeg', N'Ao realizarmos a filtragem das amostras no filtro prensa o mesmo possui duas saídas de escoamento da água tendo que ser colocado baldes abaixo de cada ponto para a captura da água, pois a sala não possui uma contenção para o filtro, gerando esforço físico e uma locomoção maior.', N'01 - Imagens/02 - Depois/8995.jpeg', N'Instalado uma tubulação gerando apenas um ponto de escoamento da água, reduzindo o esforço físico, a locomoção para descarregamento dos baldes sendo apenas um agora para a coleta da água.  ', NULL, N'Sim. Com a instalação da tubulação reduziu o esforço físico e a locomoção reduzindo também o risco de queda.', N'Redução de esforço físico e locomoção', 0, NULL, N'We are now able to know how the remill should flow within the lab. When certain elements are required only certain steps are needed, this eliminates any extra work.  ', '2026-03-26T00:00:00.000', '2026-03-27T14:25:05.000', N'550925', NULL, NULL);
INSERT INTO #PVC VALUES (8996, N'81047115', N'81046197', N'Transporte seguro ', NULL, N'Others/Outros', N'Antes não havia suporte, oque dificultava o transporte da bomba 
INSERT INTO #PVC VALUES (8997, N'81055952', N'81055952', N'Feluwa Work Tables', NULL, N'Projects/Projetos', N'New Proper tables for Feluwa rebuilds', N'Provide clean and sturdy work front for Feluwa Parts', N'0', N'01 - Imagens/01 - Antes/8997.jpeg', N'Crews at port were using a very lightweight table and not practical', N'01 - Imagens/02 - Depois/8997.jpeg', N'Solid wooden tables fabricated with Teflon tops for working on pump parts', NULL, N'Problem Solved', N'no Shortcuts', 0, NULL, N'O resultado esperado com a melhoria é assegurar que o suporte para alavancas permaneça em condições adequadas de uso, promovendo segurança, confiabilidade e organização, além de prevenir falhas futuras e reduzir a necessidade de intervenções corretivas.', '2026-03-26T00:00:00.000', '2026-03-27T14:54:18.000', N'81055952', NULL, NULL);
INSERT INTO #PVC VALUES (8998, N'484341', N'484341', N'REDUÇÃO DE CUSTO ', NULL, N'Open Pit/Poço aberto', N'Identificado na Ordem a solicitação indevida do grupo completo da transmissão. 
INSERT INTO #PVC VALUES (8999, N'550925', N'550925', N'Movimentação filtro prensa', NULL, N'Others/Outros', N'O local de instalação do filtro prensa não possuía ponto de água próximo para a lavagem do tambor a cada troca de amostra, sendo necessário a lavagem na pia que possui na sala que não ficava próximo ao filtro.', N'Reduzir movimento', N'10363', N'01 - Imagens/01 - Antes/8999.jpeg', N'O local de instalação do filtro prensa não possuía ponto de água próximo para a lavagem do tambor a cada troca de amostra, sendo necessário a lavagem na pia que possui na sala que não ficava próximo ao filtro, havendo um desperdício de movimento, esforço físico com o peso aproximado do filtro de 9kg e risco de escorrego, pois ao lavar o tambor o mesmo escorria água durante o trajeto.', N'01 - Imagens/02 - Depois/8999.jpeg', N'Foi realizado a movimentação do filtro para próximo a pia para reduzir o movimento, esforço físico e escorrego facilitando o manuseio do tambor. ', NULL, N'Sim. Foi realizado a movimentação do filtro para próximo a pia para reduzir o movimento, esforço físico e escorrego facilitando o manuseio do tambor. ', N'Redução de movimento e esforço', 0, NULL, N'eliminação de risco de colisão ', '2026-03-26T00:00:00.000', '2026-03-27T15:24:30.000', N'550925', NULL, NULL);
INSERT INTO #PVC VALUES (9000, N'81049566', N'502163', N'Identificação extratores', NULL, N'Crusher/Britadeira', N'Ausência de identificação padrão dos extratores de sucata da rebritagem ', N'Identificar , padronizar TAG dos ativos .', N'10362', N'01 - Imagens/01 - Antes/9000.jpeg', N'Ausência de tag padronizado nos equipamentos 2301EX01, 2301EX02, 2301EX03 na rebritagem. ', N'01 - Imagens/02 - Depois/9000.jpeg', N'Identificado os equipamentos com Tag refletivo no padrão de identificação. ', NULL, N'Ativos identificados conforme padrão. ', N'Melhorar o 5s da aréa.', 0, NULL, N'Produzimos um material de maior qualidade e confiança, com menos tempo agregado a tarefa', '2026-03-23T00:00:00.000', '2026-03-27T17:44:19.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9001, N'81049566', N'502163', N'Identificação do 2202AL02', NULL, N'Crusher/Britadeira', N'Ausencia de TAG padronizado no equipamento 2202AL02. ', N'Identificar o ATIVO COM PLACA REFLETIVA, conforme padrão.', N'10362', N'01 - Imagens/01 - Antes/9001.jpeg', N'Tag feito com marcador industrial, fora de padrão. ', N'01 - Imagens/02 - Depois/9001.jpeg', N'Identificado o ativo com TAG PADRONIZADO.', NULL, N'Ativo com fácil identificação por todos após instalação de TAG adequado .', N'Melhor identificação do ativo.', 0, NULL, N'Eliminado risco de parada da correia por sobrecarga de material  e desprendimento de rolos e cavaletes.', '2026-03-23T00:00:00.000', '2026-03-27T17:50:37.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9002, N'81049566', N'502163', N'Identificação 2202AL03', NULL, N'Crusher/Britadeira', N'Ausencia de tag de identificação para o ativo 2202AL03.', N'Identificar o ativo conforme padrão .', N'10362', N'01 - Imagens/01 - Antes/9002.jpeg', N'Equipamento identificado com TAG FEITO DE MARCADOR INDUSTRIAL, sem padronização.', N'01 - Imagens/02 - Depois/9002.jpeg', N'Identificado com tag padronizado. ', NULL, N'Ativo identificado conforme padrão. ', N'Melhor identificação por todos do ativo ', 0, NULL, N'Decrease in lost time looking for pump disconnect', '2026-03-23T00:00:00.000', '2026-03-27T17:55:44.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9003, N'521673', N'81034873', N'Cadeira na sala de concentrado', NULL, N'No Replication/Sem replicação', N'Durante a utilização do computador na sala do concentrado, o posto de trabalho não dispunha de cadeira, configurando condição inadequada de ergonomia.', N'Minimizar o impacto ergonômico durante o uso do computador.', N'10366', N'01 - Imagens/01 - Antes/9003.jpeg', N'Verificou-se que, durante a utilização do computador na sala do concentrado, o posto de trabalho não dispunha de cadeira, configurando condição inadequada de ergonomia.', N'01 - Imagens/02 - Depois/9003.jpeg', N'Após a disponibilização da cadeira na sala do concentrado, observou-se melhoria significativa nas condições ergonômicas do posto de trabalho, possibilitando ao colaborador adotar postura adequada durante o uso do computador. A medida contribuiu para a redução do esforço físico desnecessário, principalmente em coluna, pernas e braços, tornando a atividade de informar no sistema os resultados, mais confortável e proporcionando melhores condições de trabalho ao colaborador.', NULL, N'Sim, Diminuiu o risco de dores lombares, fadiga muscular e desconfortos posturais. Contribuiu para a prevenção de afastamentos por queixas ergonômicas.', N'contribuição para a redução do esforço físico desnecessário', 0, NULL, N'APOS A CONFECÇÃO DAS ALÇAS DA TAMPA DO BLOCO, CONSTATOU-SE MAIOR FACILIDADE DURANTE A REMOÇÃO DA MESMA.', '2026-03-22T00:00:00.000', '2026-03-27T20:57:41.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (9004, N'81054319', N'81054319', N'Standardization of POL/LRT Shift Handover using OneNote', NULL, N'Refining/Refino', N'Shift handovers in POL were previously completed using Excel spreadsheets, which limited real-time collaboration, version control, and accessibility across crews. Some sections were never properly utilized, updated, and crowd the handover. Ultimately increasing the risk of miscommunication of ongoing priorities and new work notifications.', N'To improve clarity, consistency, and accessibility of POL shift handovers by implementing a standardized, real-time OneNote platform.', N'0', N'01 - Imagens/01 - Antes/9004.jpeg', N'Handover information was recorded in Excel with ineffective formatting, limited accessibility, and risk of version control issues, leading to potential miscommunication between shifts. ', N'01 - Imagens/02 - Depois/9004.jpeg', N'OneNote provides a centralized, structured, and real-time handover system, improving visibility, consistency, and communication across all crews. 
INSERT INTO #PVC VALUES (9005, N'81009270', N'81009270', N'Treated Effluent Sample point Improvements ', NULL, N'Others/Outros', N'Sampling of the treated effluent by TWM and Environment is difficult due to potential cross contamination of the sample. It is also difficult to handle the sample pails while trying to sample.', N'Improve conditions and ergonomics for sampling', N'10311', N'01 - Imagens/01 - Antes/9005.jpeg', N'The treated effluent sample point is corroded causing a risk of cross contamination of samples collected. The position of the sample point also required 20L sample buckets to be either placed down into the sump or balanced/held by the person sampling causing strains/MSDS injuries.  ', N'01 - Imagens/02 - Depois/9005.jpeg', N'The corroded section of the sample line was replaced with a new ball valve and hose. The fittings on the hose are stainless steel. A platform with grating was added to place buckets on to make handling the buckets easier.', NULL, N'Potential contamination from corroded sample point was eliminated. Eliminates the need to balance sample pails while filling decreasing risk of stains/MSDS injury.  ', N'Potential contamination of samples risks impacting regulatory results and must be minimized. ', 0, NULL, N'GARANTIR A LUBRIFICAÇÃO DO EMBUICHAMENTO DO GIRO DO GRIPPER E REDUZIR CUSTOS DE MANUITENÇÃO.', '2026-03-27T00:00:00.000', '2026-03-28T09:17:38.000', N'81009270', NULL, NULL);
INSERT INTO #PVC VALUES (9006, N'81009270', N'81009270', N'Portable flowmeter', NULL, N'Projects/Projetos', N'As part of an ongoing engineering project it was determine that the flowrate of lime to the tailings tank was required. The lime loop in the mill is not equipped with a flowmeter. To install a flowmeter on this line it would require new parts to be ordered, support from fixed plant maintenance to install, and DCS support. This became a costly and time consuming process for a one off installation. ', N'To measure flows of pipelines not equipped with flowmters', N'10311', N'01 - Imagens/01 - Antes/9006.jpeg', N'As part of an ongoing engineering project it was determine that the flowrate of lime to the tailings tank was required. The lime loop in the mill is not equipped with a flowmeter. To install a flowmeter on this line it would require new parts to be ordered, support from fixed plant maintenance to install, and DCS support. The cost and time to install a flowmeter was deemed to great for a one time measurement. Expected costs was >$30K for materials and hours worked for install.', N'01 - Imagens/02 - Depois/9006.jpeg', N'A portable flowmeter was procured to provide a non-invasive way to measure flows that can be completed in a short time. The portable flowmeter was cheaper than a typical flow tube that would be installed on a pipeline($7k vs $20K). The portable flow meter can also be used on any pipeline rather then a permanent install on a single pipeline.', NULL, N'The portable flowmeter was used to provide a flow of lime to the tailings tank in support of an ongoing project. It was less invasive and did not require a new install. The portable flowmeter has also been used to support other work in the mill on pipelines without flowmeters.', N'Available technology should be evaluated when considering new instrumentation installs. ', 23000, 3, N'APÓS O CLAVICULARIO SER INSTALADO EM UM LOCAL DE MELHOR ACESSO, RESULTAOU EM FACILIDADE E MELHOR MOBILIDADE DURANTE OS ATENDIMENTOS NA FERRAMENTARIA.', '2026-03-05T00:00:00.000', '2026-03-28T09:44:58.000', N'81009270', NULL, NULL);
INSERT INTO #PVC VALUES (9007, N'1009280', N'1009280', N'Shift Expectations', NULL, N'Others/Outros', N'When the technicians are on reduced protocols there was inconsistency on which analysis were required and which ones could be pushed to the next shift. ', N'To ensure the reduced protocol expectations are explained', N'0', N'01 - Imagens/01 - Antes/9007.jpeg', N'When the technicians are on reduced protocols there was inconsistency on which analysis were required and which ones could be pushed to the next shift. ', N'01 - Imagens/02 - Depois/9007.jpeg', N'By creating a visual chart that was added to the FMDS board it showed what the expectations were for the shift including all of the protocols. This ensured that the customer was receiving the data appropriately.  ', NULL, N'There are now a clear set of expectations for when on reduced or full protocols ', N'Visual aids for communication ', 0, NULL, N'Resultado esperado:
INSERT INTO #PVC VALUES (9008, N'1009280', N'1009280', N'Remill Process', NULL, N'Others/Outros', N'When Co and Ni samples required for a remill it was unclear what the process should be. ', N'Consistency', N'0', N'01 - Imagens/01 - Antes/9008.jpeg', N'The lab would communicate with the plant on which element needed to be re-assayed, then we would communicate with the chemists/senior chemists to figure out how the sample should flow. ', N'01 - Imagens/02 - Depois/9008.jpeg', N'By creating a chart it allowed any one to see how the remill flow should work. This means proper digestions/ pickling/ y-coll when necessary. ', NULL, N'We are now able to know how the remill should flow within the lab. When certain elements are required only certain steps are needed, this eliminates any extra work.  ', N'Visual aids', 0, NULL, NULL, '2026-03-12T00:00:00.000', '2026-03-28T10:17:03.000', N'1009280', NULL, NULL);
INSERT INTO #PVC VALUES (9009, N'1007278', N'1007278', N'Soda Ash lineleak repair', NULL, N'No Replication/Sem replicação', N'Work required the use of AWP and Maintenance had no one qualified to use AWP', N'Repair Soda Ash line leaks', N'0', N'01 - Imagens/01 - Antes/9009.jpeg', N'Soda ash line was frozen due to heat trace off and when heat trace was turned on, line developed 2 leaks. Work required the use of an AWP to execute, Maintenance had no one qualified. Operations completed work.', N'01 - Imagens/02 - Depois/9009.jpeg', N'Operations isolated soda ash system, replaced gaskets on leaking flange and deisolated. System put back in service', NULL, N'Leaks were repaired and system put back in service', N'Line frozen, ensure heat trace is on to prevent from freezing', 3000, 3, N'Eliminação total do risco de contato.
INSERT INTO #PVC VALUES (9010, N'81034398', N'81016922', N'melhoria no suporte das alavancas ', NULL, N'Others/Outros', N'Não tinha um suporte adequado para as alavancas', N'confeccionar um suporte adequado para as alavancas', N'10139', N'01 - Imagens/01 - Antes/9010.jpeg', N'O suporte apresentava sinais de desgaste e oxidação na estrutura interna, podendo comprometer a integridade das alavancas, dificultar o armazenamento adequado e gerar risco de queda ou danos ao equipamento.', N'01 - Imagens/02 - Depois/9010.jpeg', N'O suporte passou por adequação estrutural e pintura, proporcionando melhor acomodação das alavancas, maior durabilidade do conjunto e melhor condição visual para identificação e utilização correta do dispositivo', NULL, N'Sim,Comparando a condição inicial com a situação atual, verifica-se que o problema foi resolvido de forma eficaz, atendendo à meta proposta', N'A atuação preventiva reduz custos com substituição de componentes danificados', 0, NULL, N'Dispor de um banco de dados confiável e padronizado de substituições de componentes, suportando controle operacional, análises técnicas e evolução da maturidade em manutenção e confiabilidade.', '2026-03-24T00:00:00.000', '2026-03-28T14:19:46.000', N'81034398', NULL, NULL);
INSERT INTO #PVC VALUES (9011, N'81034398', N'81034398', N'Adequação da Tampa de Acesso a propulsora de graxa na pá carregadeira ', NULL, N'Others/Outros', N'para acessar a propulsora de graxa era necessário remover os parafusos de fixação da tampa', N'eliminar a dificuldade de acesso a propulsora de graxa', N'10139', N'01 - Imagens/01 - Antes/9011.jpeg', N'Para acessar a propulsora de graxa era necessário remover a tampa , através da remoção dos parafusos de fixação , o que ocasionava risco ergonômico devido posição inadequada na hora de remover a tampa, além do tempo demorado para remover a tampa ', N'01 - Imagens/02 - Depois/9011.jpeg', N'Foi realizado a melhoria na tampa , através da aplicação de dobradiças e a aplicação de um pegador, assim diminuindo o risco ergonômico e reduzindo o tempo para acessar a propulsora de graxa ', NULL, N'Sim , com a instalação das dobradiças foi eliminado a dificuldade de acessar a propulsora de graxa', N'A cultura de melhoria contínua (Kaizen) fortalece o compromisso com segurança, organização e confiabilidade dos equipamentos.', 0, NULL, N'Garantir que todos os novos componentes sejam corretamente cadastrados e avaliados no Painel de Risco de Frota desde a sua inclusão, fortalecendo a gestão de risco e a confiabilidade dos ativos.', '2026-03-26T00:00:00.000', '2026-03-28T14:36:01.000', N'81034398', NULL, NULL);
INSERT INTO #PVC VALUES (9012, N'81049978', N'81049978', N'fabricação de suporte para o giro flex', NULL, N'Others/Outros', N'problema antes tínhamos dificuldade de visibilidade do equipamento na área operacional, por não ter uma base para instalação do giro flex. não tinha o sensor, solução foi fabricado o suporte e instalado o giro flex. evitando colisões na área operacional e melhoria na segurança', N'fabricar suporte para sinalização do equipamento moveis', N'10108', N'01 - Imagens/01 - Antes/9012.jpeg', N'Foi realizada a fabricação de um suporte para instalação do sensor e do giroflex na pá carregadeira, com o objetivo de melhorar a sinalização e reduzir o risco de colisões durante a operação.
INSERT INTO #PVC VALUES (9013, N'550842', N'550842', N'Relatório Integrado para Análise de Alertas Vermelhos - VBM', NULL, N'Others/Outros', N'Não havia um relatório integrado, com as informações chave avaliando o impacto dos alertas direcionado as necessidades de metais básicos ', N'Facilitar o acesso a informação, gerar KPI´S e garantir acesso ao histórico de dados', N'10268', N'01 - Imagens/01 - Antes/9013.jpeg', N'conforme demanda se calculava os indicadores de forma manual e repetitiva a cada nova extração, um visual de ferrosos era consultado, mas perdeu atualizações recorrentes', N'01 - Imagens/02 - Depois/9013.jpeg', N'Com a criação de um dashboard na ferramenta PowerBi, o acesso é simplificado com KPI´S já definidos e histórico construído para tomada de decisão assertiva de todos os pontos monitorados VBM', NULL, N'Com a iniciativa se facilitou o acesso a informação por link único, gerar KPI´S de forma padronizada pelos cálculos na plataforma foi atingindo e a garantir acesso ao histórico de dados foi assegurada conforme o padrão ano ano', N'Padronização e Otimização de processos', 0, NULL, N'Manter o Painel Custo Evitado sempre atualizado, automatizado e confiável, garantindo suporte contínuo à tomada de decisão.', '2026-02-27T00:00:00.000', '2026-03-28T15:25:19.000', N'550842', NULL, NULL);
INSERT INTO #PVC VALUES (9014, N'123307', N'513430', N'VELOCIDADE FOI A CHAVE DO PROBLEMA', NULL, N'Others/Outros', N'O sistema de controle não tem uma proteção de parada dos alimentadores se reduzir a rotação da 2202 TC 01.
INSERT INTO #PVC VALUES (9015, N'1008427', N'1008427', N'Updated P2W Description for IR1 Flash Cooling Vacuum Pump #1', NULL, N'Others/Outros', N'312-PXE-004 IR1 Flash Cooling Vacuum Pump #1 has no local disconnect and need to be isolated in the ERoom. Where its a IR1 Pump, the assumption would be that it''s located in the IR1 ERoom. Leaving unfamiliar isolators hopelessly looking for an Electrical Disconnected that is located in WLN ERoom. 
INSERT INTO #PVC VALUES (9016, N'81030117', N'81002626', N'ALÇA DA TAMPA DO BLOCO RHS', NULL, N'Others/Outros', N'PRENSAMENTO DE DEDOS E DIFICULDADE NA REMOÇÃO DA TAMPA DO BLOCO RHS', N'FACILITAR E GARANTIR SEGURANÇA DURANTE A REMOÇÃO DA TAMPA DO BLOCO RHS', N'10324', N'01 - Imagens/01 - Antes/9016.jpeg', N'PRENSAMENTO DE DEDOS E DIFICULDADE NA REMOÇÃO DA TAMPA DO BLOCO RHS.', N'01 - Imagens/02 - Depois/9016.jpeg', N'APOS A CONFECÇÃO DAS ALÇAS DA TAMPA DO BLOCO, CONSTATOU-SE MAIOR FACILIDADE DURANTE A REMOÇÃO DA MESMA.', NULL, N'SIM, APOS A CONFECÇÃO DAS ALÇAS DA TAMPA DO BLOCO, CONSTATOU-SE MAIOR FACILIDADE DURANTE A REMOÇÃO DA MESMA.', N'SEGURANÇA', 0, NULL, N'Time saved and risk reduced by upgrade', '2026-03-21T00:00:00.000', '2026-03-29T11:52:10.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (9017, N'81030117', N'81002626', N'SUPORTE DA MANGUEIRA DO GIRO DO GRIPPER', NULL, N'Others/Outros', N'QUEBRAS CONSTANTES DAS CONEXÕES E DIFICULDADE NA REMOÇÃO DAS MANGUEIRAS DO GIRO DO GRIPPER.', N'FACILIDADE NA REMOÇÃO E REDUÇÃO DE AVARIAS.', N'10324', N'01 - Imagens/01 - Antes/9017.jpeg', N'QUEBRAS CONSTANTES DAS CONEXÕES E DIFICULDADE NA REMOÇÃO DAS MANGUEIRAS DO GIRO DO GRIPPER.', N'01 - Imagens/02 - Depois/9017.jpeg', N'CONFECCIONADO SUPORTE E CONEXÕES DE FACIL REMOÇÃO E DIVISÃO DAS LINHAS HIDRAULICAS DE MOVIMENTAÇÃO DO GIRO DO GRIPPER, ASSIM MELHORANDO O DESEMPENHO DO EQUIPAMENTO SEM FALHA RECORRENTES DE QUEBRA DE MANGUEIRAS E CONEXÕES.', NULL, N'MELHORIA NO DESEMPENHO DO EQUIPAMENTO, SEM FALHA RECORRENTES DE QUEBRA DE MANGUEIRAS E CONEXÕES.', N'MELHORIA', 0, NULL, N'Proper colour coded labelling applied to piping in order to better identify it.', '2026-03-22T00:00:00.000', '2026-03-29T11:58:53.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (9018, N'81030117', N'81002626', N'SUPORTE DE ACOMPANHAMENTO DAS LINHAS DE LUBRIFICAÇÃO DO GIRO DO GRIPPER', NULL, N'Others/Outros', N'QUEBRA DAS LINHAS DE LUBRIFICAÇÃO E DIFICULDADE NA LUBRIFICAÇÃO DO EMBUCHAMENTO DO GRIPPER', N'GARANTIR A LUBRIFICAÇÃO DO EMBUICHAMENTO DO GIRO DO GRIPPER E REDUZIR CUSTOS DE MANUITENÇÃO.', N'10324', N'01 - Imagens/01 - Antes/9018.jpeg', N'QUEBRA DAS LINHAS DE LUBRIFICAÇÃO E DIFICULDADE NA LUBRIFICAÇÃO DO EMBUCHAMENTO DO GRIPPER.', N'01 - Imagens/02 - Depois/9018.jpeg', N'GARANTIR A LUBRIFICAÇÃO DO EMBUICHAMENTO DO GIRO DO GRIPPER E REDUZIR CUSTOS DE MANUITENÇÃO.', NULL, N'SIM POIS GARANTIU A LUBRIFICAÇÃO DO EMBUICHAMENTO DO GIRO DO GRIPPER E REDUZIU CUSTOS DE MANUITENÇÃO.', N'MELHORIAS', 0, NULL, N'Disponibilizar informações de Análise de Óleo de forma mais frequente, confiável e performática para suporte à tomada de decisão operacional.', '2026-03-23T00:00:00.000', '2026-03-29T12:13:57.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (9019, N'81030117', N'81030117', N'CLAVICULARIO', NULL, N'Others/Outros', N'DIFICULDADE DE ACESSO AO CALVICULARIO, POIS O MESMO ESTAVA EM UM LOCAL INDEVIDO PARA ACESSO FREQUENTE.', N'MELHORIA ERGONOMICA', N'10324', N'01 - Imagens/01 - Antes/9019.jpeg', N'CLAVICULARIO FICAVA INSTALADO ACIMA DO COMPUTADOR, ASSIM DIFICULTANDO O ACESSO AO MESMO.', N'01 - Imagens/02 - Depois/9019.jpeg', N'CLAVICULARIO INSTALADO EM UM LOCAL DE MELHOR ACESSO, RESULTANDO EM FACILIDADE E MELHOR MOBILIDADE DURANTE OS ATENDIMENTOS NA FERRAMENTARIA.', NULL, N'SIM, APÓS O CLAVICULARIO SER INSTALADO EM UM LOCAL DE MELHOR ACESSO, RESULTAOU EM FACILIDADE E MELHOR MOBILIDADE DURANTE OS ATENDIMENTOS NA FERRAMENTARIA.', N'MELHORIA ERGONOMICA', 0, NULL, N'Disponibilizar informações de consumo de óleo lubrificante de forma confiável, performática e padronizada, apoiando a tomada de decisão operacional e a gestão de confiabilidade.', '2026-03-15T00:00:00.000', '2026-03-29T12:23:34.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (9020, N'81006946', N'81048624', N'SUPORTE PARA HASTES DE BANDEIROLAS', NULL, N'Others/Outros', N'Não ter um local adequado para guardar as hastes de bandeirolas dos equipamentos gera uma série de problemas operacionais e de organização.', N'GARANTIR O ARMAZENAMENTO ADEQUADO', N'10139', N'01 - Imagens/01 - Antes/9020.jpeg', N'Tínhamos uma série de problemas operacionais e de organização.
INSERT INTO #PVC VALUES (9021, N'81046919', N'472940', N'Substituição de grades de piso .', NULL, N'Crusher/Britadeira', N'Chapa de piso danificada, com deformações e desnível, gerando risco de acidentes e dificultando a circulação.', N'Evitar quedas,', N'10362', N'01 - Imagens/01 - Antes/9021.jpeg', N'Durante inspeção na área operacional, foi constatado que a chapa de piso encontra-se danificada, apresentando deformações, desgaste e desnível. Essa condição compromete a segurança dos colaboradores, aumentando o risco de tropeços, quedas e acidentes, além de dificultar a circulação de equipamentos e impactar negativamente a eficiência e ergonomia do ambiente de trabalho.', N'01 - Imagens/02 - Depois/9021.jpeg', N'Após a intervenção e troca da grade de piso :
INSERT INTO #PVC VALUES (9022, N'81044534', N'964502', N'Proteção da Mola de Carga da PN‑2305SA‑02', NULL, N'Others/Outros', N'Durante a operação, a mola de carga permanece exposta, o que representa risco de fratura, esmagamento ou até amputação de membros, caso ocorra contato acidental com o componente em movimento.', N'Eliminar o risco de contato com a mola de carga exposta durante a operação.', N'10089', N'01 - Imagens/01 - Antes/9022.jpeg', N'Antes, durante a inspeção no peneiramento, era necessário mover ou elevar manualmente a saia lateral das molas de impacto para realizar a verificação visual interna do equipamento. Essa prática expunha os trabalhadores a um risco constante de prensamento, aumentando significativamente a possibilidade de lesões graves, fraturas ou amputação de membros.', N'01 - Imagens/02 - Depois/9022.jpeg', N'Depois, foi realizada a instalação de uma proteção com grades, permitindo que as inspeções visuais fossem feitas sem contato físico com o equipamento. A nova proteção elimina a necessidade de mover ou elevar a saia lateral e, consequentemente, elimina o risco de prensamento, lesões graves, fraturas ou amputação de membros durante a operação e inspeção do conjunto.', NULL, N'sim', N'Partes móveis exposta, representam riscos graves', 0, NULL, N'Manter todas as solicitações de demandas registradas, organizadas e rastreáveis, garantindo controle, histórico e melhor gestão das atividades de Sistemas e BI.', '2026-03-28T00:00:00.000', '2026-03-29T15:37:00.000', N'81044534', NULL, NULL);
INSERT INTO #PVC VALUES (9023, N'92000576', N'92000576', N'Implantação de Formulário Padronizado para Registro de Substituição de Componentes no CMA', NULL, N'Projects/Projetos', N'Atualmente, as substituições de componentes realizadas em campo não possuem um registro padronizado e estruturado, o que dificulta o controle das trocas realizadas, a rastreabilidade dos motivos das substituições, a consolidação de dados técnicos e a realização de análises de confiabilidade e RAF, além de limitar o uso das informações para inteligência artificial do CMA.', N'Criar um formulário padronizado para registrar todas as substituições de componentes, garantindo rastreabilidade, padronização e centralização das informações em banco de dados do CMA, possibilitando controle operacional, análises de falha, melhoria contínua e uso futuro em inteligência artificial do CMA.', N'10015', N'01 - Imagens/01 - Antes/9023.jpeg', N'Antes do projeto, as substituições de componentes eram registradas de forma descentralizada e sem padrão definido, muitas vezes apenas em notas ou sistemas sem campos específicos. Isso dificultava o controle das substituições, a identificação dos motivos das trocas, a análise de sintomas, o acompanhamento de horímetros, custos, impactos operacionais e a estruturação das informações para análises de falha e confiabilidade.', N'01 - Imagens/02 - Depois/9023.jpeg', N'Foi desenvolvido um formulário digital (Forms) com campos padronizados para que técnicos e analistas registrem todas as substituições de componentes realizadas. As informações são armazenadas em banco de dados do CMA, permitindo rastreabilidade por TAG, equipamento e componente, suporte à RAF, análises de confiabilidade e alimentação futura de modelos de inteligência artificial do CMA.', N'https://globalvale.sharepoint.com/:l:/s/BASE_DADOS_/JAAsmvT_RUGmTbwGChWyvSG4AR2Fz3RBTuma_Mew6WIv4jY?nav=NTE0MzgzOTQtZTk3NS00ZGFjLWI2MDgtYWJkNmRkMjMzYmYw', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9024, N'92000576', N'92000576', N'Padronização da Solicitação de Inclusão de Componentes no Painel de Risco de Frota', NULL, N'Projects/Projetos', N'As solicitações de inclusão de novos componentes no Painel de Risco de Frota eram realizadas de forma informal e centralizadas em uma única pessoa, sem um processo padronizado. Frequentemente, as informações necessárias para cadastro, como local de instalação até o 6º nível, modelo do componente e ciclo não eram fornecidas corretamente, exigindo retrabalho e buscas junto a diferentes responsáveis por frota.', N'Padronizar e descentralizar o processo de solicitação de inclusão de componentes no Painel de Risco de Frota, garantindo que todas as informações técnicas necessárias sejam registradas corretamente pelos responsáveis desde a origem.', N'10015', N'01 - Imagens/01 - Antes/9024.jpeg', N'Antes da melhoria, todas as solicitações de inclusão de componentes no Painel de Risco de Frota eram feitas diretamente ao responsável pelo cadastro. As informações chegavam incompletas ou inconsistentes, como ausência de local de instalação até o 6º nível, modelo correto do componente ou ciclo aplicável. Como cada frota possui responsáveis diferentes, era necessário buscar essas informações com várias pessoas, aumentando o tempo de resposta e o retrabalho.', N'01 - Imagens/02 - Depois/9024.jpeg', N'Foi implementado um processo padronizado no qual os responsáveis pelos novos equipamentos são obrigados a registrar os componentes no momento da inclusão, preenchendo todas as informações técnicas necessárias, como local de instalação até o 6º nível, TAG, modelo e ciclo do componente. Dessa forma, o CMA já recebe os dados completos e confiáveis, permitindo a inclusão direta dos componentes no Painel de Risco de Frota.', N'https://globalvale.sharepoint.com/:l:/s/BASE_DADOS_/JADXHZQ6WfpfQo4qBzb6EEJkAWRiG3tJ-53hHkl_LK0Vbkw?nav=NzE3ZWJlNGQtOWFmZS00MmUyLTkzM2ItMWU2YTZhNTBhYmNh', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9025, N'81053930', N'81053930', N'Scaffold Platform Crud Removal', NULL, N'Refining/Refino', N'Pulling crud from a small area', N'Pull more crud over a larger area', N'10004', N'01 - Imagens/01 - Antes/9025.jpeg', N'With a larger settler we could only pull crud from a small surface area causing issues in the circuit ', N'01 - Imagens/02 - Depois/9025.jpeg', N'Building a scaffold deck that allows us to access more than 75% of the settler. We can now walk around the settler allowing us to pull crud from almost anywhere and really reach the problem area. ', NULL, N'yes, allows us to pull crud from almost anywhere in the settler where crud may be held up.', N'Covering a larger area helps with crud problems ', 0, NULL, N'Less time wasted.', '2026-03-01T00:00:00.000', '2026-03-29T16:15:03.000', N'81053930', NULL, NULL);
INSERT INTO #PVC VALUES (9026, N'92000576', N'92000576', N'Automatização da Atualização do Painel Custo Evitado', NULL, N'Others/Outros', N'O Painel de Custo Evitado dependia de atualização manual devido ao alto volume e processamento de dados necessários para viabilizar visualizações com imagens. Essa limitação impedia o agendamento de atualização automática no Power BI Service, exigindo abertura manual do arquivo PBIX para atualização, tornando o processo dependente de intervenção humana e sujeito a atrasos.', N'Reduzir o processamento de dados do Painel Custo Evitado, viabilizando a atualização automática e agendada no Power BI Service, garantindo que as informações estejam sempre atualizadas sem necessidade de intervenção manual.', N'10015', N'01 - Imagens/01 - Antes/9026.jpeg', N'Antes da melhoria, os registros de custo evitado eram realizados via Forms e conectados a um painel no Power BI. Entretanto, devido ao grande processamento de dados necessário para permitir visualizações com imagens, o painel não permitia atualização automática no Power BI Service. Com isso, a atualização precisava ser feita manualmente através da abertura do arquivo PBIX, dificultando a disponibilidade contínua de dados atualizados.', N'01 - Imagens/02 - Depois/9026.jpeg', N'Foi realizada a otimização do processamento e da modelagem de dados do Painel Custo Evitado, reduzindo significativamente a carga computacional. Com isso, tornou-se possível habilitar o agendamento de atualização automática no Power BI Service. Atualmente, o painel é atualizado várias vezes ao dia de forma automática, permanecendo sempre conectado à fonte de dados do Forms, sem necessidade de qualquer intervenção manual.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/3acefc23-89b6-4c88-9162-c4a3ae4cc4fa/604701136673135e5339?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9027, N'607148', N'300582', N'Troubleshooting Matrix', NULL, N'Refining/Refino', N'There were too many offspec Co lots at PCR in 2025.', N'Reduce Risk Offspec Product', N'10275', N'01 - Imagens/01 - Antes/9027.jpeg', N'There were too many offspec Cobalt lots at PCR in 2025 mainly due to Sulfur which ops was not familiar as to the cause.', N'01 - Imagens/02 - Depois/9027.jpeg', N'A new Impurity troubleshooting matrix was created and posted on the Cobalt Refinery management teams channel so the knowledge is available to existing and future team members.', NULL, N'System created', N'Systemization Is Critical', 0, NULL, N'Foi criado um dispositivo capaz de organizar e transporta as fitas de forma que não venha a se perder, e danificar durante o transporte.! ', '2026-03-02T00:00:00.000', '2026-03-29T16:54:20.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (9028, N'607148', N'81032308', N'PO Status Search Application', NULL, N'Refining/Refino', N'Determining the status of incoming materials purchased using a requisition was difficult. It required querying the ME5A T Code and using an estimated date range, as well as the requisitioner number to determine if the material had been ordered. 
INSERT INTO #PVC VALUES (9029, N'607148', N'300582', N'Anolyte Transfer Line', NULL, N'Refining/Refino', N'Maintenance Personnel were required to work at heights to complete the disconnection/ re-connection when operations were processing external feeds.', N'Safety', N'10275', N'01 - Imagens/01 - Antes/9029.jpeg', N'Maintenance Personnel were required to work at heights to complete the disconnection/ re-connection when operations were processing external feeds.', N'01 - Imagens/02 - Depois/9029.jpeg', N'Additional piping was added to allow for operations to manipulate hand valves and direct material as needed without the need for Maintenance’s involvement.', NULL, N'Time saved and risk reduced by upgrade', N'Time saved and risk reduced by upgrade', 0, NULL, NULL, '2026-03-04T00:00:00.000', '2026-03-29T17:06:33.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (9030, N'607148', N'607306', N'Labelling SO2 lines', NULL, N'Refining/Refino', N'Lines not clearly identifiable', N'5s', N'10275', N'01 - Imagens/01 - Antes/9030.jpeg', N'Lines not clearly identifiable', N'01 - Imagens/02 - Depois/9030.jpeg', N'Proper colour coded labelling applied to piping in order to better identify it.', NULL, N'Proper colour coded labelling applied to piping in order to better identify it.', N'5s importance', 0, NULL, N'To have all the parts we need codified in the warehouse.', '2026-03-05T00:00:00.000', '2026-03-29T17:12:02.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (9031, N'92000576', N'92000576', N'Otimização da Arquitetura do Painel de Análise de Óleo', NULL, N'Projects/Projetos', N'O painel de Análise de Óleo utilizava como fonte de dados uma lista do SharePoint, realizando todo o tratamento, transformação e modelagem diretamente no Power BI. Esse cenário gerava alto consumo de processamento durante as atualizações no Power BI Service, com tempo de refresh elevado, reclamações recorrentes da equipe de TI e limitação na quantidade de atualizações diárias, reduzindo a disponibilidade de informações atualizadas para a área operacional.', N'Otimizar a arquitetura de dados do Painel de Análise de Óleo, reduzindo o consumo de processamento no Power BI Service, melhorando o desempenho das atualizações e permitindo maior frequência de refresh de forma estável e automática.', N'10015', N'01 - Imagens/01 - Antes/9031.jpeg', N'Anteriormente, o painel de Análise de Óleo consumia diretamente uma lista do SharePoint, realizando todo o ETL, tratamento e modelagem dentro do Power BI. Esse modelo resultava em alto consumo de recursos durante o refresh, com tempos de atualização variando entre 15 e 25 minutos, além de gerar reclamações recorrentes da equipe de TI e restringir significativamente a quantidade de agendamentos de atualização permitidos ao longo do dia.', N'01 - Imagens/02 - Depois/9031.jpeg', N'Foi realizada uma mudança na arquitetura de dados do painel. Os dados passaram a ser extraídos da lista do SharePoint e carregados no banco de dados SQL Server (CMA). A partir disso, foi criada uma view dedicada no SQL, responsável por todo o processo de ETL, entregando ao Power BI uma tabela final estruturada, padronizada e pronta para consumo. Com isso, o Power BI passou a ser utilizado exclusivamente para consumo e visualização dos dados, reduzindo drasticamente o esforço de processamento durante as atualizações.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/6a952f52-44d9-42bd-be74-265606b19d6c/4446ccdfa95b668c8002?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9032, N'92000576', N'92000576', N'Otimização da Arquitetura do Painel de Consumo de Óleo Lubrificante', NULL, N'Projects/Projetos', N'O Painel de Consumo de Óleo Lubrificante não possuía sua fonte de dados integrada ao banco de dados corporativo do CMA, o que limitava a padronização, o tratamento centralizado das informações e a escalabilidade do painel. O processamento e tratamento dos dados não estavam concentrados em uma arquitetura otimizada para consumo analítico.', N'Centralizar a fonte de dados do Painel de Consumo de Óleo Lubrificante no banco de dados do CMA, realizando todo o tratamento, padronização e modelagem dos dados em uma view dedicada no SQL Server, entregando ao Power BI dados prontos para consumo, com maior performance, confiabilidade e governança.', N'10015', N'01 - Imagens/01 - Antes/9032.jpeg', N'Antes da melhoria, o Painel de Consumo de Óleo Lubrificante não consumia dados diretamente do banco de dados do CMA. O tratamento e a organização das informações não estavam centralizados em uma camada de dados estruturada, dificultando a padronização, a escalabilidade e a otimização do consumo pelo Power BI.', N'01 - Imagens/02 - Depois/9032.jpeg', N'Os dados de consumo de óleo lubrificante passaram a ser disponibilizados no banco de dados do CMA (SQL Server). Foi criada uma view dedicada, responsável por todo o processo de extração, limpeza, tratamento e padronização dos dados, entregando ao Power BI uma base final pronta para consumo. Com isso, o Power BI passou a atuar exclusivamente na visualização das informações, garantindo melhor performance, confiabilidade e governança dos dados.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/e45759b0-4591-4fad-be98-28eaf8392ef0/3b9da7baf64f85579ebd?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9033, N'92000576', N'92000576', N'Otimização da Arquitetura de Dados do VisionLink para Painéis Operacionais', NULL, N'Projects/Projetos', N'Os dados provenientes do sistema VisionLink, responsável pelo armazenamento de eventos e informações operacionais dos equipamentos Caterpillar, não estavam integrados de forma estruturada ao banco de dados do CMA. Isso limitava o tratamento centralizado, a padronização das informações e a escalabilidade dos painéis operacionais, além de concentrar esforços de transformação fora da camada ideal de dados.', N'Integrar os dados do VisionLink ao banco de dados do CMA, centralizando o tratamento, padronização e modelagem em uma view dedicada no SQL Server, entregando dados prontos para consumo aos painéis operacionais, com maior performance, confiabilidade e governança.', N'10015', N'01 - Imagens/01 - Antes/9033.jpeg', N'Antes da melhoria, os dados de eventos e telemetria dos equipamentos Caterpillar, oriundos do VisionLink, não estavam estruturados em uma camada de dados otimizada no banco CMA. O tratamento e a organização dessas informações não seguiam um modelo padronizado e escalável, dificultando o consumo eficiente pelos painéis operacionais e a consolidação das informações de forma confiável.', N'01 - Imagens/02 - Depois/9033.jpeg', N'Foi criada uma view dedicada responsável por todo o processo de ETL, entregando dados estruturados, padronizados e prontos para consumo. Os painéis Eventos Operacionais e Telemetria Unificada passaram a consumir diretamente essa view, utilizando o Power BI exclusivamente para visualização das informações, garantindo melhor performance, confiabilidade e governança dos dados.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/3620e441-bc06-4389-9562-9ac5bb38ee12/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9034, N'486809', N'486809', N'identificação dos módulos de fibra ótica dos inversores.', NULL, N'Others/Outros', N'antes havia dificuldade da equipe na identificação dos módulos de fase com o cartões de fibra, em relação a suas posições no equipamento.', N'facilitar a identificação dos módulos de fibra ótica dos inversores.', N'10140', N'01 - Imagens/01 - Antes/9034.jpeg', N'antes havia dificuldade da equipe na identificação dos módulos de fase com o cartões de fibra, em relação a suas posições no equipamento.', N'01 - Imagens/02 - Depois/9034.jpeg', N'Instalamos um adesivo com informação do manual, que facilita a identificação dos módulos de fases com cartões de fibra ótica e inversores.
INSERT INTO #PVC VALUES (9035, N'92000576', N'92000576', N'Forms de Solicitação de Demandas – Equipe de Dados', NULL, N'Projects/Projetos', N'As solicitações de demandas relacionadas a alterações, correções ou criação de painéis e sistemas (Power BI, Power Apps e outros) eram realizadas de forma informal e descentralizada, sem um canal único de registro. Isso dificultava o controle das demandas recebidas, o acompanhamento das atividades executadas e a manutenção de um histórico confiável do trabalho realizado pela equipe de dados.', N'Criar um processo padronizado para registro, controle e histórico de todas as solicitações de demandas relacionadas a sistemas e BI, garantindo visibilidade, rastreabilidade e organização das atividades realizadas no dia a dia pela equipe.', N'10015', N'01 - Imagens/01 - Antes/9035.jpeg', N'Antes da melhoria, as demandas eram solicitadas diretamente aos responsáveis, de forma verbal, por mensagens ou outros meios informais. Não havia um controle centralizado das solicitações recebidas, tampouco um registro histórico das demandas atendidas ao longo do tempo. Isso dificultava a organização do trabalho, a priorização das atividades e a visibilidade do volume real de demandas executadas pela equipe.', N'01 - Imagens/02 - Depois/9035.jpeg', N'Foi criado um formulário padronizado de Solicitação de Demandas, Gestão de Sistemas / BI, onde todas as áreas passaram a registrar qualquer tipo de solicitação relacionada a painéis, sistemas ou manutenções. O formulário passou a ser utilizado tanto como canal oficial de entrada das demandas quanto como base histórica de todas as atividades executadas pela equipe de dados, garantindo rastreabilidade e organização.', N'https://globalvale.sharepoint.com/sites/BASE_DADOS_/_layouts/15/listforms.aspx?cid=ZDhjZTAwMDEtZTk1Yy00NjZjLTg0YjUtNzBkNjY0ZjViMzY4&ct=1774816803971&or=Teams-HL&nav=NGFlMzMyMWQtMTJhMi00YWQzLWJjZGQtODlmOTI4OGJjMmU3&LOF=1', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9036, N'81058052', N'81058052', N'calha suporte de mangueiras hidráulicas[comboio diesel)', NULL, N'Others/Outros', N'danos recorrente a mangueiras hidráulicas DE CAMINHÕES DE ABASTECIMENTO DIESEL (CV-52) por atrito/resultava sempre em paradas não programadas para substituição e contaminação do solo demandando  uso de material de mitigação como mantas, serragem etc./O problema foi identificado realizando analise de causa e contatando que as mangueiras ficavam despeças na parte inferior do equipamento roçando umas nas outras vindo a furar vazando óleo para o solo e gerando retrabalhos e paradas recorrentes do equipamento.', N'acomodar mangueiras hidráulicas de espessura entre 1" a 3" polegadas .Foi elaborada com objetivo de mitigar o desgaste prematuro e eventos  recorrentes em que a vibração ocasiona atrito entre as mangueiras e a estrutura do veiculo ,reduzindo assim o tempo de paradas para substituição de mangueiras sempre que o mesmo ocorria.', N'10139', N'01 - Imagens/01 - Antes/9036.jpeg', N'MANGUEIRAS DESPERÇAS AMARRADAS COM ABRAÇADEIRAS PLASTICAS COM UM PESSIMO ASPECTO VISUAL ROÇANDO NA EXTRUTURA DO EQUIPAMENTO VINDO A FURAR.', N'01 - Imagens/02 - Depois/9036.jpeg', N'A MELHORIA FEFLETIU POSITIVAMENTE EM UMA MAIOR DISPONIBILIDADE DO EQUIPAMENTO PARA OPERAÇÃO SEM MAIS PARADAS PARA SUBSTITUIÇÃO DAS MANGUEIRAS DA PARTE INFERIOR DO EQUIPAMENTO E TAMBEM MELHORANDO A QUESTÃO ESTETICA,ELIMINAÇÃO DE ATRITO,VIBRAÇÃO E REDUZINDO CORTES DE MANGUIRAS EM CANTOS VIVOS OU ARESTAS.
INSERT INTO #PVC VALUES (9037, N'81058052', N'81058052', N'conecxão de carregamento de radio comunicador em guindastes ', NULL, N'Others/Outros', N'Foi identificado que equipamentos periféricos como radio comunicadores tinham seus respectivos carregadores instalados de forma precária nos bornes positivos e negativos de uma bateria do equipamento ,sem isolação ou cuidados com eventuais curto-circuitos. Foi identificado também que apenas uma das baterias do equipamento estava descarregando de forma recorrente devido a ligação  parasita  nos seus respectivos bornes no que acabava por saturar a mesma .', N'meta: eliminar ligações paralelas a bateria do equipamento sem padronização e ordenação de cabos/Objetivo:reduzir ou eliminar o desgaste prematuro de baterias chumbo acidas por ligações paralelas inadequadas pop via de apenas uma bateria com ligações precarias sem isolação com risco de curto circuito as partes elétricas e eletrônicas do guindaste. ', N'10139', N'01 - Imagens/01 - Antes/9037.jpeg', N'Anteriormente os carregadores de radio estavam instalados com sua suplementação direto em uma das baterias vindo a exaurir a mesma de forma recorrente e levando ao seu desgaste prematuro, os cabos ficavam dispersos e sem ordenação adequada por vezes encostando no chassis do equipamento e saturando fusíveis danificando carregadores. ', N'01 - Imagens/02 - Depois/9037.jpeg', N'Foi realizada a instalação de conectores macho e receptáculo padrão  tipo (acendedor) , substituição dos cabos dos carregadores por cabos flexíveis obs: mesmos utilizados em giroflex já utilizamos no site e retirados de componentes queimados aproveitando seus conectores e cabos.', NULL, N'Após a implementação da melhoria não houveram outros  relatos de descarga de apenas uma das bateria com necessidade de substituição das mesmas nem saturação de cabos e fusíveis.', N'mitigar os desperdícios por via da melhoria continua sempre é  possível', 2000, 1, N'Eliminação do risco de contato acidental com as gaxetas e melhoria das condições de segurança do equipamento.
INSERT INTO #PVC VALUES (9038, N'1010008', N'1010008', N'Field Headlamp Battery Charging Station', NULL, N'No Replication/Sem replicação', N'PPT Headlamp batteries need to be charged by leaving the whole hard hat with the charger.  Portable charging stations with replacement batteries in the field saves techs time and now no longer need to leave hard hat in the annex to charge', N'Save Time', N'0', N'01 - Imagens/01 - Antes/9038.jpeg', N'In order to charge their headlamp, PPT needed to leave their hardhat in the annex to charge.  Having a charging station for headlamp batteries with spare batteries in the field saves time and inconvenience. ', N'01 - Imagens/02 - Depois/9038.jpeg', N'Having a charging station for headlamp batteries in the field (Sat Lab) saves time waiting for the battery to charge.  2 hours+ per charge.', NULL, N'Problem solved.', N'Time Saved', 0, NULL, N'CRIAÇÃO DE GESTÃO A VISTA PARA MAIOR DOMINÂNCIA DO PROCESSO', '2026-03-28T00:00:00.000', '2026-03-30T01:47:07.000', N'1010008', NULL, NULL);
INSERT INTO #PVC VALUES (9039, N'81013122', N'81013122', N'Moved RSA Decant sample point closer to sump', NULL, N'Projects/Projetos', N'Sample point was on the floor and not in an ideal location.  Moved sample point closer to the sump for easier access', N'Make it easier to take the RSA decant sample', N'0', N'01 - Imagens/01 - Antes/9039.jpeg', N'RSA decant sample point was on the floor and in the middle of a walkway.  It was not in an ideal location and was a tripping hazard.', N'01 - Imagens/02 - Depois/9039.jpeg', N'Added an extra length of hose and setup the sample point behind a nearby sump. ', NULL, N'The problem was solved by moving the sample point behind the sump in an easy to access area.', N'area is safer', 1, 3, N'Alcance de metas estratégicas através das atividades desenvolvidas, com foco em aumento de produtividade, melhoria de processos, aumento da produtividade e otimização da gestão de mudanças, garantindo processos internos mais ágeis.', '2026-03-29T00:00:00.000', '2026-03-30T02:06:04.000', N'81013122', NULL, NULL);
INSERT INTO #PVC VALUES (9040, N'81006588', N'81006588', N'Porta Abraçadeiras', NULL, N'Others/Outros', N'Abraçadeiras transportada de forma inadequada, com risco de perdas e avarias.', N'Organização ', N'10245', N'01 - Imagens/01 - Antes/9040.jpeg', N'Abraçadeiras eram transportada de forma inadequada gerando perdas e avarias das mesmas.', N'01 - Imagens/02 - Depois/9040.jpeg', N'Foi criado um dispositivo capaz de organizar e transporta as fitas de forma que não venha a se perder, e danificar durante o transporte.! ', NULL, N'Sim. agora temos total organização das fitas.', N'5S', 500, 1, N'potential production loss avoided ', '2026-03-29T00:00:00.000', '2026-03-30T02:36:30.000', N'81006588', NULL, NULL);
INSERT INTO #PVC VALUES (9041, N'537635', N'537635', N'A Revolução na Iluminação da Subestação.', 3, N'Others/Outros', N'Foi identificada baixa eficiência na iluminação externa. Em inspeção nas luminárias, foi constatado que algumas estavam queimadas devido ao acúmulo de água.', N'Eliminar a condição insegura.', N'10245', N'01 - Imagens/01 - Antes/9041.jpeg', N'Foi identificada uma baixa eficiência na iluminação externa da subestação de bombeamento de rejeito. Durante uma inspeção nas luminárias, constatou-se que algumas estavam queimadas devido ao acúmulo de água, o que comprometeu a segurança operacional e a visibilidade na área.', N'01 - Imagens/02 - Depois/9041.jpeg', N'Como medida de melhoria, foram instalados cinco refletores ao redor da subestação, priorizando a área de acesso. Essa intervenção visa aprimorar a iluminação e, consequentemente, aumentar a segurança operacional na região.', NULL, N'Sim, o problema foi resolvido e ate o momento tudo foi solucionado. ', N'Ver e Agir.', 0, NULL, N'potential production loss avoided and or cost of repairs ', '2026-03-29T00:00:00.000', '2026-03-30T04:42:51.000', N'537635', NULL, NULL);
INSERT INTO #PVC VALUES (9042, N'1008368', N'1008368', N'Replacing Steam Trap', NULL, N'No Replication/Sem replicação', N'Steam Trap 0080 is passing High Pressure steam not forming condensate which could be reused in boiler room. Steam entering the condensate Vessel is lost as it escapes to atmosphere through Vent on Vessel.', N'Replace Steam Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/9042.jpeg', N'Steam Trap 0080 is passing High Pressure steam not forming condensate which could be reused in boiler room. Steam entering the condensate Vessel is lost as it escapes to atmosphere through Vent on Vessel.', N'01 - Imagens/02 - Depois/9042.jpeg', N'New Trap installed allowing steam to change to condensate for reuse rather than steam venting through stack', NULL, N'Problem solved New steam trap installed without involving maintenance ', N'Having operations complete the task removes the cost of having maintenance to do it.', 3000, 3, N'Esse Kaizen resolveu uma dor antiga: no meio de muitas compras de manutenção, a gente não tinha um filtro confiável pra separar o que é crítico de verdade. A prioridade da OM ajuda, mas às vezes vem classificada incorreta — e quem melhor sabe o que “mata” é o time de execução.
INSERT INTO #PVC VALUES (9043, N'81048127', N'81048127', N'Parts issues', NULL, N'Refining/Refino', N'Parts we need for high pressure pumps are ZK not stocked. ', N'To get ZK items changed to ZM', N'0', N'01 - Imagens/01 - Antes/9043.jpeg', N'Parts we need are ZK and order on demand. We need to change that so we have them readily available', N'01 - Imagens/02 - Depois/9043.jpeg', N'I have a list of parts done up that we have to send to procurement to get changed and stock the part', NULL, N'When this gets approved it will help with downtime on the pumps', N'Need parts here', 0, NULL, N'Reducing the number of vehicles we operate also reduces green house gas emissions sitewide', '2026-03-26T00:00:00.000', '2026-03-30T07:57:36.000', N'81048127', NULL, NULL);
INSERT INTO #PVC VALUES (9044, N'1013315', N'1013315', N'Unsanitary Ear Plug Dispensers', NULL, N'No Replication/Sem replicação', N'During an OHS inspection unsanitary ear plug dispensers were observed. ', N'Provide Sanitary Ear Plugs - EW', N'0', N'01 - Imagens/01 - Antes/9044.jpeg', N'Due to the environment in EW the type of dispenser being used can introduce contaminants to the hearing protection prior to use, increasing the risk of ear irritation, infections, and reduced effectiveness of noise protection.', N'01 - Imagens/02 - Depois/9044.jpeg', N'An alternative solution of individually wrapped ear plugs has been sourced for this area. This will provide a clean sanitary solution for the employees working in this area.', NULL, N'Yes, with sourcing of individually wrapped ear plugs the risk of ear plug contamination prior to use has been eliminated.', N'Regular inspections, and employee awareness to ensure protective equipment remains safe and fit for use.', 0, NULL, N'less hydraulic fluid spilled means less potential for slips and falls ', '2026-03-25T00:00:00.000', '2026-03-30T08:06:39.000', N'1013315', NULL, NULL);
INSERT INTO #PVC VALUES (9045, N'81007346', N'81007346', N'Bulkhead filter replacement', NULL, N'Underground/Subterrâneo', N'New Bulkheads are installed that require oversized filters. Currently not available from inventory and have been using bulk medium as replacement.
INSERT INTO #PVC VALUES (9046, N'81014495', N'81014495', N'Business Intelligence (BI) para otimização do Working Capital SSG', NULL, N'Others/Outros', N'Necessidade de base para acompanhamento dos resultados obtidos no trabalho de otimização do parque MRO da planta de Sossego. Trabalho esse, cujo o objetivo macro é otimizar o fluxo de caixa livre de VBM ( AIP 2026).', N'Ter acompanhamento facilitados dos resultados obtidos no trabalho de otimização do parque MRO da planta de Sossego', N'10081', N'01 - Imagens/01 - Antes/9046.jpeg', N'Havia apenas uma planilha em Excel com os dados à serem trabalhados.', N'01 - Imagens/02 - Depois/9046.jpeg', N'Um Dashboard de Power BI foi criado para acompanhamento dos resultados, com curva ABC, Paretos, classificação e status em relação à meta.', NULL, N'O problema foi resolvido.', N'Necessidade de um bom tratamento de dados', 3000000, 3, N'we are always making sure our new hires are fully aware of all tasks and how they are done properly. This encourages them to feel more confident.', '2026-03-27T00:00:00.000', '2026-03-30T09:59:29.000', N'81014495', NULL, NULL);
INSERT INTO #PVC VALUES (9047, N'81045248', N'81052061', N'Whip check storage area', NULL, N'No Replication/Sem replicação', N'in order to ensure the safety of all personnel, we want to keep whip checks at all times available. 
INSERT INTO #PVC VALUES (9048, N'81011217', N'81011217', N'Consolidação de Indicadores de Custo e Performance de Ativos por Faixa de Horímetro', NULL, N'Open Pit/Poço aberto', N'As informações de custo, manutenção e performance dos ativos estavam dispersas em múltiplas fontes, sem padronização temporal ou por estágio de vida do equipamento. Isso dificultava:
INSERT INTO #PVC VALUES (9049, N'81042856', N'81042856', N'Integração das condições dos equipamentos por técnica', NULL, N'Others/Outros', N'Atualmente, as condições dos equipamentos são registradas de forma descentralizada e, em alguns casos, incompleta ou sem padronização entre os técnicos. Essa falta de integração e uniformidade dificulta a análise das condições reais dos ativos, impacta o planejamento da manutenção, aumenta o risco de falhas inesperadas e gera retrabalho na consolidação das informações.', N'Padronizar e integrar o registro das condições dos equipamentos por técnica, garantindo maior confiabilidade das informações, redução de falhas não identificadas, aumento da eficiência da manutenção e suporte à tomada de decisão baseada em dados.', N'10015', N'01 - Imagens/01 - Antes/9049.jpeg', N'Antes da implementação deste Kaizen, o registro das condições dos equipamentos era realizado de forma não padronizada entre os técnicos, utilizando diferentes meios (anotações manuais, planilhas individuais ou registros incompletos no sistema). As informações nem sempre eram registradas no momento da inspeção e, em alguns casos, careciam de critérios técnicos uniformes.
INSERT INTO #PVC VALUES (9050, N'81044674', N'473401', N'Montagem da proteção de gaxetas da BP 2017-19', NULL, N'No Replication/Sem replicação', N'Foi identificado que a bomba BP 2017-19 operava sem proteção nas gaxetas, expondo partes móveis e podendo ocasionar contato acidental durante a operação ou inspeção, com risco de acidente.', N'Implementar proteção adequada nas gaxetas da BP 2017-19, garantindo a eliminação do risco de acidente e promovendo a melhoria contínua em segurança.', N'10031', N'01 - Imagens/01 - Antes/9050.jpeg', N'O equipamento operava sem proteção nas gaxetas, deixando partes móveis expostas e suscetíveis a contato acidental durante atividades operacionais e de inspeção.
INSERT INTO #PVC VALUES (9051, N'542336', N'542336', N'MAPA DE TUBULAÇÕES', NULL, N'Others/Outros', N'FALTA DE GESTÃO A VISTA SOBRE AS TUBULAÇÕES A SEREM REFORMADAS', N'ACOMPANHAMENTO DAS TUBULAÇÕES A REFORMAR', N'10154', N'01 - Imagens/01 - Antes/9051.jpeg', N'AUSENCIA DE CONTROLE E DOMINÃNCIA', N'01 - Imagens/02 - Depois/9051.jpeg', N'CRIAÇÃO DE GESTÃO A VISTA PARA MAIOR DOMINÂNCIA DO PROCESSO.', NULL, N'Problema inicial:
INSERT INTO #PVC VALUES (9052, N'81006670', N'127050', N'Carrinho/Suporte para transporte de água', NULL, N'Others/Outros', N'Fardos de garrafinhas de água, eram manuseados na mão.', N'Melhoria ergonômica e maior quantidade de manuseio', N'10144', N'01 - Imagens/01 - Antes/9052.jpeg', N'Antes, as águas para consumo da oficina eram transportadas em um caixa de papelão manualmente, em que além de inadequado gerava um certo risco de rasgar e causar algum acidente ou incidente, postura incorreta e também de alguma água cair e furar a garrafa trazendo a perca da mesma.', N'01 - Imagens/02 - Depois/9052.jpeg', N'Com o novo suporte fica mais eficiente podendo ser transportado pela empilhadeira com mais segurança e também pode ser locomovido por pessoas devido o mesmo ter rodas e alça isso gera melhoria praticidade e segurança.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Atribuída ao uso de sistemas de controle, monitoramento contínuo e engajamento da equipe, permitindo ajustes conforme a realidade.', N'Transformar experiências práticas em barreiras contra acidentes.', 0, NULL, N'By coating these components we have extended the life and replacement by at leat an additional 2 years in some areas, and much more in less contaminated areas. Each track system costs approx 5000 for hardware.', '2026-03-25T00:00:00.000', '2026-03-30T10:57:00.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (9053, N'81057902', N'81057902', N'heat trace escalation process document ', NULL, N'Others/Outros', N'clear process needed for escalating heat trace issues ', N'develop clear procedure for heat trace reporting ', N'0', N'01 - Imagens/01 - Antes/9053.jpeg', N'No clear process to report critical heat trace issues ', N'01 - Imagens/02 - Depois/9053.jpeg', N'developed a clear process on how to escalate and report heat trace issues ', NULL, N'yes. escalation process distributed ', N'process needed ', 100000, 3, N'all hoses and attachments should be using cotter pins where applicable to ensure nothing comes lose or apart unnecessarily ', '2026-03-26T00:00:00.000', '2026-03-30T10:58:27.000', N'81057902', NULL, NULL);
INSERT INTO #PVC VALUES (9054, N'81057902', N'1010414', N'cobalt rectifier inspection ', NULL, N'Refining/Refino', N'cobalt rectifier drawing unbalanced current causing substantial heat. issue could have caused transformer damage', N'inspect, find, and repair issue ', N'0', N'01 - Imagens/01 - Antes/9054.jpeg', N'cobalt rectifier with excess heat potentially causing damage to transformer. heat caused by unbalanced load ', N'01 - Imagens/02 - Depois/9054.jpeg', N'did an emergency inspection where 3 scr firing boards were seen to be failed. replaced boards and rectifier is working as it should. triggered conversation in inspect the rest of the rectifiers and audit warehouse stock.', NULL, N'issues repaired and rectifier is working as it should ', N'audit current draw on rectifiers ', 1000000, 3, N'The work force has expressed that the overall ramp conditions have improved with the automation, and we have eliminated costs of products that were previously used.', '2026-03-26T00:00:00.000', '2026-03-30T11:08:31.000', N'81057902', NULL, NULL);
INSERT INTO #PVC VALUES (9055, N'81002116', N'81002116', N'Integração e Controle – TOP 10 Materiais Críticos', NULL, N'Others/Outros', N'Hoje existe um “universo” de solicitações de compra de manutenção, mas não havia um mecanismo simples e confiável para destacar, dentro desse volume, quais itens o time de execução considera de fato críticos (os que “matam” a operação).
INSERT INTO #PVC VALUES (9056, N'1007997', N'1007997', N'Optimize Maintenance Light Vehicle Fleet', NULL, N'Others/Outros', N'Large quantity of contractor vehicles on site, resulting in a large contractor/rental cost for vehicles', N'Optimize and reduce cost', N'0', N'01 - Imagens/01 - Antes/9056.jpeg', N'Maintenance utilized 41 light vehicles on site in 2025.  20 of these were rented from DFB contractor.  This resulted in a significant rental cost throughout this year.', N'01 - Imagens/02 - Depois/9056.jpeg', N'Maintenance optimized their vehicle inventory and reduced from 41 to 23 vehicles (44% reduction).  21 of the remaining vehicles are owned by Vale with no rental costs.  Only 2 of the 20 Contractor vehicles remain on site.   This results in over a $275,000 annual savings on rentals and estimated $50,000-$100,000 in fuel savings/reductions. Totaling over $350,000 annual savings.  This also reduces our greenhouse gas emissions sitewide.', NULL, N'Yes', N'Optimizing the way we work can reduce costs substantially', 350000, 3, N'Already very safe workers now have easier access to key safety equipment', '2026-02-28T00:00:00.000', '2026-03-30T11:24:07.000', N'1007997', NULL, NULL);
INSERT INTO #PVC VALUES (9057, N'81045248', N'81052061', N'Spill Tray for Hydraulic Fluid', NULL, N'No Replication/Sem replicação', N'we sometimes have to top up the hydraulic fluid for the Bin Whip at the top of 212. There is potential for fluid to spill as we are pouring from the bucket into the pour bottle. ', N'Minimize spilling ', N'0', N'01 - Imagens/01 - Antes/9057.jpeg', N'this is where the bin whip motor is located and where the hydraulic fluid gets added to the motor. Prior to the spill tray there was potential for spillage as we poured fluid from the bucket into the bottle used for pouring. ', N'01 - Imagens/02 - Depois/9057.jpeg', N'a spill tray was used for unsure that there was no hydraulic fluid spilling on the grating or onto the levels below this area. 
INSERT INTO #PVC VALUES (9058, N'81044674', N'81053358', N'Troca de bomba e adequação do sistema de mangueiras', NULL, N'No Replication/Sem replicação', N'Foi identificado vazamento recorrente nas mangueiras do sistema, ocasionado pelo ressecamento precoce após intervenções de manutenção, além de falhas constantes na bomba em operação.
INSERT INTO #PVC VALUES (9059, N'81045248', N'81062684', N'SMD discharge piping sign ', NULL, N'No Replication/Sem replicação', N'For new hires, it can be a little confusing when taking samples to know which piping comes from which SMD. One of our new hires put up a sign to help anyone who is not certain, ensure they are taking samples from the correct SMD.', N'Sign for Discharge piping ', N'0', N'01 - Imagens/01 - Antes/9059.jpeg', N'there are 3 pipes leading from each SMD into the discharge tanks before pumping to the CST. 
INSERT INTO #PVC VALUES (9060, N'81044674', N'81038896', N'Adequação de Válvulas na Tubulação de Água de Selagem', NULL, N'No Replication/Sem replicação', N'Durante atividade de manutenção, foi identificado que a tubulação de água de selagem não possuía válvula de controle instalada.
INSERT INTO #PVC VALUES (9061, N'81002116', N'81002116', N'Painel de Acompanhamento de PGU – Materiais (Usina)', NULL, N'Others/Outros', N'As ordens de manutenção dependentes de Parada Geral da Usina (PGU) estão diluídas em meio a um grande universo de compras de materiais, sem um mecanismo claro que permita identificar rapidamente o que é PGU, o que já foi comprado, o que chegou e o que ainda representa risco para a parada.
INSERT INTO #PVC VALUES (9062, N'81037019', N'520770', N'IDENTIFICAÇÃO DE EQUIPAMENTOS', NULL, N'Others/Outros', N'EQUIPAMENTOS SEM IDENTIFICAÇÃO E TAGS', N'CONFIABILIDADE NO TAGS DOS EQUIPAMENTOS', N'10031', N'01 - Imagens/01 - Antes/9062.jpeg', N'SEM AS DEVIDAS IDENTIFICAÇÕES, PODENDO GERAR DUVIDAS NO MOMENTO DE PARAR OU ATE MESMO IDENTIFICAR O EQUIPAMENTO', N'01 - Imagens/02 - Depois/9062.jpeg', N'REALIZADO A IDENTIFICAÇÃO DO ATIVO', NULL, N'AGORA CONSEGUIMOS IDENFICAR O EQUIPAMENTO VISUALMENTE COM FACILIDADE', N'PROMOVER SEMPRE A MELHORIA CONTINUA', 0, NULL, N'Esse Kaizen trouxe clareza para a análise de custos da manutenção. Antes, o esforço estava em montar a informação; agora, está em tomar decisão. O painel mostra de forma direta onde economizamos, onde estouramos e quais contas precisam de atenção, elevando o nível da discussão de custo para algo realmente gerencial.', '2026-03-27T00:00:00.000', '2026-03-30T12:29:49.000', N'81037019', NULL, NULL);
INSERT INTO #PVC VALUES (9063, N'81011163', N'536809', N'Instalação de Grelha Híbrida FLSMIDTH', NULL, N'No Replication/Sem replicação', N'DF da moagem impactada para troca preventiva de grelhas do moinho SAG.', N'Aumento vida útil da grelha para 7 Mton', N'10081', N'01 - Imagens/01 - Antes/9063.jpeg', N'As grelhas atualmente utilizadas apresentam fechamento prematuro dos slots no início da campanha. Esse comportamento exige a realização de paradas trimestrais para substituição das grelhas — um total de quatro intervenções anuais — cada uma com impacto aproximado de 43 horas de indisponibilidade.', N'01 - Imagens/02 - Depois/9063.jpeg', N'As grelhas híbridas da FLSmidth não apresentam fechamento dos slots ao longo da campanha e demonstram maior vida útil, alcançando cerca de 7 Mton processadas em 6 meses de operação. Com esse desempenho, foi possível eliminar duas paradas anuais anteriormente necessárias para a troca de grelhas, aumentando a disponibilidade operacional e reduzindo intervenções de manutenção.', NULL, N'Sim, as medidas dos slots permaneceram intactas durante o inicio da campanha, ou seja, não apresentaram fechamento. Os dados de desgaste demonstram alinhamento com os parâmetros especificados.', N'A avaliação crítica do comportamento das grelhas ao longo da campanha é essencial para identificar modos de falha precoces; Reduzir o número de paradas planejadas impacta positivamente o custo operacional e a segurança das equipes', 0, NULL, N'MELHOROU O CONTROLE DE PEÇAS E COMPONENTES', '2026-03-01T00:00:00.000', '2026-03-30T13:24:36.000', N'81011163', NULL, NULL);
INSERT INTO #PVC VALUES (9064, N'81045885', N'81045885', N'PROCEDIMENTO A VISTA: TORQUEAMENTO ANEL DE CONTRAÇÃO', NULL, N'Others/Outros', N'EM UMA ANÁLISE DE FALHAS REFERENTE A AVARIA DO SEMIEIXO E DO EIXO OCO DO REDUTOR DO 2551AG01, VERIFICOU-SE QUE UMA DAS CAUSAS POTENCIAIS CAUSAS DA FALHA FOI O TORQUEAMENTO INCORRETO DOS PARAFUSOS DO ANEL DE CONTRAÇÃO.', N'CORREÇÃO DE MÉTODO DE TORQUEAMENTO E REPLICAR MÉTODO CORRETO', N'10081', N'01 - Imagens/01 - Antes/9064.jpeg', N'ANTES OS COLABORADORES DA OFICINA ESTAVAM REALIZANDO O TORQUEAMENTO DO ANEL DE CONTRAÇÃO QUE FIXA O EIXO OCO DO REDUTOR DO AGITADOR 2551AG10, DE FORA DO PROCEDIMENTO DO FABRICANTE. E ISSO FOI UM FATOR POTENCIAL PARA A FALHA OCORRIDO NO MESMO EM FEVEREIRO DE 2026.', N'01 - Imagens/02 - Depois/9064.jpeg', N'COMO SOLUÇÃO PARA O PROBLEMA EM QUESTÃO FOI REALIZADO A ORIENTAÇÃO DOS COLABORADORES DA OFICINA E FIXADO NO PAINEL, PRESENTE NA OFICINA DE SOSSEGO, UM PROCEDIMENTO SIMPLICADO.', NULL, N'OS COLABORADORES AGORA CONHECEM O MÉTODO CORRETO A SER APLICADO E ASSIM FUTUROS MECANISMOS DE DANO EM EQUIPAMENTOS PODEM SER MITIGADAS.', N'METODOLOGIA CORRETA REPLICADA AO TIME', 0, NULL, NULL, '2026-03-27T00:00:00.000', '2026-03-30T13:39:37.000', N'81045885', NULL, NULL);
INSERT INTO #PVC VALUES (9065, N'81043460', N'81043460', N'Festoon Track Coatings', NULL, N'Others/Outros', N'Festoon tracks were failing prematurely due to the corrosive environment', N'eliminate waste, extend lifespan of materials', N'0', N'01 - Imagens/01 - Antes/9065.jpeg', N'Festoon channel, couplings and end caps become heavily corroded preventing carriers and bearings from moving freely within the track. This causes issues with the trolley functions, casuing the trolley motors to stall due to the buildup', N'01 - Imagens/02 - Depois/9065.jpeg', N'Multiple coats of and insulated epoxy has been used on all track components internal and external to reduce and resist rust and heavy contaminates, extend the life of the components as well as make it much easier for cleaning in the future.', NULL, N'Yes.', N'Coating was tested and proved successful to prevent corrosion', 5000, 3, N'Esse Kaizen trouxe transparência para um problema silencioso. Antes, o PCM era cobrado por não performar, mas não havia visibilidade sobre o volume de demandas emergenciais que desviavam nossa mão de obra. Hoje conseguimos mostrar, com dados, onde o tempo foi consumido e como isso impactou a rotina, permitindo uma discussão mais justa e orientada à decisão.', '2026-03-27T00:00:00.000', '2026-03-30T13:48:15.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (9066, N'1014251', N'1014251', N'Cotter Pin storage ', NULL, N'No Replication/Sem replicação', N'we use cotter pins for attaching hoses and other attachments ', N'make cotter pins easily accessible ', N'0', N'01 - Imagens/01 - Antes/9066.jpeg', N'we use cotter pins to safely secure air hoses and other attachments. they need to be readily available for all employees so that there is no excuse not to have them attached ', N'01 - Imagens/02 - Depois/9066.jpeg', N'a storage container was placed in our lime lay-down area next to the whip check storage container so that they can be taken out together if needed. ', NULL, N'no excuses to not have cotter pins attached because they are in plain view for everyone ', N'make everyone safer ', 0, NULL, N'reduce the potential for muscle and back strains ', '2026-03-29T00:00:00.000', '2026-03-30T13:55:27.000', N'1014251', NULL, NULL);
INSERT INTO #PVC VALUES (9067, N'81031571', N'607702', N'Automation of water boxes', NULL, N'Underground/Subterrâneo', N'During Haulage activities on ramps, dusty conditions are created and the current method of manually operating the water boxes for dust suppression was not adequate .  
INSERT INTO #PVC VALUES (9068, N'81044674', N'81038934', N'Suporte Para Secesor De Válvula  Equip/ Tag: BP-2017-24', NULL, N'No Replication/Sem replicação', N'Erros recorrentes no acionamento das válvulas guilhotina devido à ausência de suporte para os sensores de posição, gerando falhas de abertura no sistema.', N'Foi verificado pela sala de controle erros recorrentes ao acionarem a abertura da válvula, as mesmas acusava erro de abertura no sistema devido a ausência de um suporte para censores de acionamento na abertura e fechamento das válvulas guilhotina.', N'10031', N'01 - Imagens/01 - Antes/9068.jpeg', N'Válvulas sem suporte para sensores, causando falhas de leitura e acionamento.', N'01 - Imagens/02 - Depois/9068.jpeg', N'Instalação de suportes para sensores das válvulas, garantindo leitura correta e eliminando falhas no sistema.
INSERT INTO #PVC VALUES (9069, N'81041052', N'81041052', N'Easy to Access Safety Tags', NULL, N'Underground/Subterrâneo', N'Safety Tags holder on shop floor was inaccessible and needed to be relocated', N'Improve compliance with safey tag usage', N'10117', N'01 - Imagens/01 - Antes/9069.jpeg', N'Access to the safety tag holder on the shop floor was often blocked by equipment and difficult to access. This made the tags hard to see and difficult to reach which in turn discouraged compliance. ', N'01 - Imagens/02 - Depois/9069.jpeg', N'Moved the holder to a central area that is highly visible, clearly indicated, accessible at all times, and will not be blocked by equipment. This encourages compliance to safety for all.', NULL, N'Yes. The new location works well for the entire shop and as an added bonus it clearly shows when tags need to be replenished before we run out at the shop.', N'easy to reach safety equipment is key to compliance', 0, NULL, N'Garantia de segurança no ativo da empresa.', '2026-03-29T00:00:00.000', '2026-03-30T14:00:30.000', N'81041052', NULL, NULL);
INSERT INTO #PVC VALUES (9070, N'81044674', N'504114', N'Suporte para Sensores de Válvula', NULL, N'No Replication/Sem replicação', N'Falhas recorrentes no acionamento das válvulas guilhotina, identificadas pela sala de controle, devido à ausência de suporte para sensores de posição (abertura/fechamento).', N'Eliminar falhas de acionamento e aumentar a confiabilidade operacional.', N'10031', N'01 - Imagens/01 - Antes/9070.jpeg', N'Válvulas sem suporte para sensores, causando erros de leitura e falhas no sistema.', N'01 - Imagens/02 - Depois/9070.jpeg', N'Fabricação e instalação de suportes para sensores das válvulas, garantindo leitura correta e eliminando falhas de acionamento.
INSERT INTO #PVC VALUES (9071, N'81031571', N'607702', N'Water Management upgrade', NULL, N'Underground/Subterrâneo', N'Multiple  Sumps in the lower part of the mine. 
INSERT INTO #PVC VALUES (9072, N'81042856', N'81042856', N'Controle de Instalação e Material Dynamox', NULL, N'Others/Outros', N'Atualmente, o controle de materiais utilizados na instalação do sistema Dynamox é realizado de forma descentralizada e pouco padronizada, gerando falhas de rastreabilidade, divergências entre material instalado e estoque, dificuldades de auditoria e retrabalho na consolidação das informações. A ausência de um controle estruturado impacta diretamente a confiabilidade dos dados, o planejamento da manutenção e o acompanhamento das OMs associadas às instalações.', N'Padronizar o registro do material utilizado nas instalações do sistema Dynamox. Garantir rastreabilidade completa dos sensores, chips e gateways instalados por equipamento (TAG). Reduzir falhas de controle e inconsistências de informação. Facilitar auditorias, análises técnicas e gestão de ativos. Melhorar a confiabilidade dos dados para suporte à manutenção preditiva.', N'10015', N'01 - Imagens/01 - Antes/9072.jpeg', N'Antes da implementação do formulário padronizado, o controle de materiais utilizados na instalação do sistema Dynamox era realizado de forma manual e descentralizada, por meio de anotações informais, planilhas individuais ou troca de informações verbais.
INSERT INTO #PVC VALUES (9073, N'81044674', N'527014', N' Fabricacao de alçapão pra montagem e desmontar da bóia de nível de material da cf-2017-07', NULL, N'No Replication/Sem replicação', N'Foi realizado a fabricação de um alçapão que facilita a montagem e desmontagem da bóia de nível sem deixar vao aberto ', N'Eliminacao riscos de vão aberto e queda de níveis diferentes ', N'10031', N'01 - Imagens/01 - Antes/9073.jpeg', N'Equipamentos operando com vão aberto nocivo a queda de nível diferente entre outros', N'01 - Imagens/02 - Depois/9073.jpeg', N'Fabricado alçapão pra fechar vão aberto e facilitar na troca da bóia de nivel', NULL, N'sim.
INSERT INTO #PVC VALUES (9074, N'81048226', N'81048226', N'Instalação de corte (Chanfro) na extremidades das pranchas de madeiras na carreta Hércules EE-28', NULL, N'Projects/Projetos', N'Quebra dos pranchões de madeira da plataforma da carreta hércules EE-28.', N'Eliminar a a quebra dos pranchões de madeira da carreta hércules EE-28.', N'10139', N'01 - Imagens/01 - Antes/9074.jpeg', N'No processo de embarque e desembarque de equipamento na plataforma da carreta Hércules EE-28, durante a movimentação das esteiras na movimentação de embarque e desembarque.
INSERT INTO #PVC VALUES (9075, N'81002116', N'81002116', N'Análise Mensal de Custos da Manutenção – Orçado x Realizado', NULL, N'Others/Outros', N'A análise do custo realizado versus custo orçado da manutenção era trabalhosa, pouco intuitiva e altamente dependente de consolidações manuais.
INSERT INTO #PVC VALUES (9076, N'81033365', N'81033365', N'Controle de solicitação', NULL, N'Others/Outros', N'não havia um controle de peças e componentes vinculado ao inspetor.', N'melhoria de processo', N'10139', N'01 - Imagens/01 - Antes/9076.jpeg', N'FOI IDENTIFICADO QUE NÃO HAVIA UM CONTROLE PARA SOLICITAÇÃO DE PEÇAS E COMPONENTE PARA EQUIPE DE INSPEÇÃO. ONDE A EQUIPE DE EXECUÇÃO NÃO TINHA O CONHECIMENTO DO QUE ERA SOLICITADO.', N'01 - Imagens/02 - Depois/9076.jpeg', N'FOI COLOCADO NO QUADRO DE FMDS UM CONTROLE DE COMPONENTES PARA EXECUÇÃO INFORMAR AS PEÇAS PARA O INSPETOR REALIZAR A SOLICITAÇÃO.', NULL, N'MELHOROU O CONTROLE DE PEÇAS E COMPONENTES', N'MELHORIA DE CONTROLE', 0, NULL, NULL, '2026-03-26T00:00:00.000', '2026-03-30T15:33:19.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9077, N'983254', N'983254', N'Portão dos trafos da moagem', NULL, N'Others/Outros', N'Ausência de identificação visual quanto ao portão dos trafos da subestação do prédio da moagem.  ', N'Destaque visual quanto ao risco na área dos trafos da moagem.', N'10054', N'01 - Imagens/01 - Antes/9077.jpeg', N'Novos portões em frente aos trafos sem sinalização visual de indicativo de área de risco.', N'01 - Imagens/02 - Depois/9077.jpeg', N'Pintura de faixa amarelo nos novos portões em frente aos trafos, indicando área de risco. Acrescentado de placas de condição específica do local de instalação dos trafos da moagem. ', NULL, N'Meta alcançada com condição de risco minimizada. ', N'Gestão de Riscos', 5000, 1, NULL, '2026-03-25T00:00:00.000', '2026-03-30T15:33:48.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (9078, N'81002116', N'81002116', N'Acompanhamento de Demandas Emergenciais – Desvios de Mão de Obra do PCM', NULL, N'Others/Outros', N'O time de Planejamento e Controle da Manutenção (PCM) era frequentemente cobrado por baixa performance nas demandas obrigatórias, sem que houvesse visibilidade sobre o volume de atividades emergenciais e extra curriculares que consumiam a mão de obra do planejamento.
INSERT INTO #PVC VALUES (9079, N'81045248', N'81052061', N'Dolly for Ball Mill Reject Grease ', NULL, N'No Replication/Sem replicação', N'Underneath the Ball Mill there is a small area where a table is set up. On that table is a bucket. This bucket collects the rejected grease the Ball Mill excretes. 
INSERT INTO #PVC VALUES (9080, N'983254', N'983254', N'Puxadores de portões ', NULL, N'Others/Outros', N'Dificuldade para abertura dos portões em frente aos trafos.', N'Sistema para facilitar abertura dos portões em frente aos trafos', N'10054', N'01 - Imagens/01 - Antes/9080.jpeg', N'Ausência pontos para auxiliar na abertura do portão em frente aos trafos. ', N'01 - Imagens/02 - Depois/9080.jpeg', N'Instalação de dois puxadores nos portões em frente aos trafos da moagem facilitando a abertura.', NULL, N'Meta alcançada, com a instalação facilitou e reduziu os esforços para abertura do portão.', N'Redução de riscos', 0, NULL, N'Bloqueio automático do fluxo em caso de ruptura da mangueira
INSERT INTO #PVC VALUES (9081, N'493280', N'81033881', N'Dispositivo para verificar abertura do britador MP800', NULL, N'Crusher/Britadeira', N'O processo de verificação da abertura do britador MP800 apresentava ineficiências operacionais e riscos elevados à segurança, decorrentes do uso de uma plataforma não padronizada e de um método manual restrito de medição. A atividade exigia esforço físico adicional, deslocamentos desnecessários, limitação de pontos de medição e exposição do operador a situações inseguras, caracterizando desperdícios de movimento, espera, processo excessivo e sobrecarga, além de risco ergonômico.', N'Implantar um método seguro, eficiente e padronizado para a medição da abertura do britador MP800, permitindo a verificação em todos os pontos necessários, eliminando a necessidade de acesso a plataformas fora de padrão e reduzindo a exposição dos operadores a riscos.', N'10081', N'01 - Imagens/01 - Antes/9081.jpeg', N'Os colaboradores precisavam subir em uma plataforma improvisada e fora de padrão;
INSERT INTO #PVC VALUES (9082, N'485654', N'500001', N'Controle pressão GLP', NULL, N'No Replication/Sem replicação', N'Ausencia de  controle de regulagem de pressão de GLP.', N'regulador de pressão de GLP', N'10227', N'01 - Imagens/01 - Antes/9082.jpeg', N'A linha de fornecimento de GLP, insumo indispensável para produção de ferro níquel, não tinha dispositivo de segurança de controle de regulagem de pressão de GLP.', N'01 - Imagens/02 - Depois/9082.jpeg', N'Implementado reguladores de pressão de GLP, proporcionando mais segurança para o processo de fornecimento do insumos crítico para produção de onça puma.', NULL, N'Problema resolvido, garantido a interrupção do fornecimento quando detectado baixa de pressão da linha, indicando possivel vazamento de GLP', N'Controle com segurança', 0, NULL, N'Organização da área
INSERT INTO #PVC VALUES (9083, N'543555', N'543555', N'DISPOSITIVOPARA AUXILIAR NA ORGANIZAÇÃO DOS FRASCOS DE DESCARTE', NULL, N'Others/Outros', N'ANTES NÃO TINHAMOS UM DISPOSITIVO PARA AUXILIAR NA ORGANIZAÇÃO DOS FRASCOS DENTRO DA CAÇAMBA DE DESCARTE, SENDO NECESSARIOS REPOSIONAR UM A UM, PARA QUE NÃO HOUVESSE ACUMULO NA BORDA DA CAÇAMBA.', N'Eliminação', N'10366', N'01 - Imagens/01 - Antes/9083.jpeg', N'NÃO TINHAMOS UM DISPOSITIVO PARA AUXILIAR NA ORGANIZAÇÃO DOS FRASCOS DENTRO DA CAÇAMBA DE DESCARTE DE FRASCOS, SENDO NECESSARIO REPOSIONAR UM A UM, PARA QUE NÃO HOUVESSE ACUMULO NA BORDA DA CAÇAMBA.', N'01 - Imagens/02 - Depois/9083.jpeg', N'FOI DISPONIBILIZADO UM DISPOSITIVO (RODO) PARA AUXILIAR NA ORGANIZAÇÃO E REDISTRIBUIÇÃO DOS FRASCO AO LONGO DA CAÇAMBA, COM ESSE DISPOSITIVO TIVEMOS GANHO NA REDUÇÃO DE MOVIMENTO E CORREÇÃO DA POSTURA AO REALIZAR A ATIVIDADE.', NULL, N'O PROBLEMA FOI SOLUCIONADO COM A DISPONIBILIZAÇÃO DO DISPOSITIVO.', N'CUIDADO ATIVO GENUINO', 0, NULL, N'não havia lavador adequado.', '2026-03-29T00:00:00.000', '2026-03-30T23:31:50.000', N'543555', NULL, NULL);
INSERT INTO #PVC VALUES (9084, N'479248', N'479248', N'Água limpa na lavagem dos tecidos e placas', NULL, N'Open Pit/Poço aberto', N'Foi identificado que o sistema de lavagem dos tecidos e das placas dos filtros SLB01, SLB02 e SLB03 apresenta baixa eficiência em função da elevada concentração de particulado em suspensão proveniente da água de processo utilizada. Essa água é oriunda do overflow do espessador e bombeada pelas bombas de água BA05, BA21 e BA31, a partir da Caixa 01.
INSERT INTO #PVC VALUES (9085, N'81058052', N'81058052', N'informativo posições de pneus e check list reutilizavel', NULL, N'Others/Outros', N'A falha na identificação precisa da posição do pneu avariado quando reportado para manutenção pelo operador via radio  geralmente não refletia a condição correta dos pneus e existiam inconsistências e falha de comunicação.', N'padronizar a indentificação das posições de pneus dos caminhões,facilitando a comunicação entre condutores e manutenção ,garantindo rapidez no atendimento,segurança operacional e redução de tempo de equipamento parado', N'10139', N'01 - Imagens/01 - Antes/9085.jpeg', N'ANTERIORMENTE O REPORTE DE AVARIAS DE PNEUS ERA FEITO VIA RADIO PELO OPERADOR QUE FORNECIA INFORMAÇÕES SUPERFICIAIS E INCOERENTES QUE GERALMENTE NÃO REFLETIA A CONDIÇÃO REAL E POSIÇÃO CORRETA DOS PNEUS AVARIADOS ,SEM CRITERIOS PRÉ ESTABELECIDOS PARA QUE O OPERADOR PUDESSE AGILIZAR A ENTRADA DO EQUIPAMENTO EM MANUTENÇÃO COM A DEVIDA ORDEM DE MNUTENÇÃO ABERTA PELA MANUTENSÃO E DESCRIÇÃO COERENTE.', N'01 - Imagens/02 - Depois/9085.jpeg', N'APÓS CRIAÇÃO DO INFORME COM DESCRIÇÃO DETALHAD DAS POSIÇÕES DOS PNEUS ,CRITERIOS PARA INDENTIFICAÇÃO DE FALHAS,PADRÃO PARA COMUNICAÇÃO DE EVENTOS COM PNEUS JUNTO A MANUTENÇÃO E CHECK LISTE NA PARTE TRAZEIRA PLASTIFICADA POSSIBILITANDO A REUTILIZAÇÃO POR PARTE DA OPERAÇÃO DO MESMO, COM INSTRUÇÕES DE USO,POSSIBILITOU A MELHORA NA COMUNICAÇÃO E DIAGNOSTICOS DE AVARIAS EM PNEUS .', NULL, N'O PROBLEMA FOI RESOLVIDO DE FORMA OBJETIVA', N'SEMPRE TER OLHAR CRITICO PARA SOLUÇÕES PRATICAS  E OBJETIVAS ', 0, NULL, NULL, '2026-03-30T00:00:00.000', '2026-03-31T01:03:27.000', N'81058052', NULL, NULL);
INSERT INTO #PVC VALUES (9086, N'81059721', N'365593', N'SACA LUVA DA UNIDADE INJETORA', NULL, N'Others/Outros', N'O serviço não era executado, por conta de não ter esta ferramenta no site. 
INSERT INTO #PVC VALUES (9087, N'81033184', N'81033184', N'Carbon unload ', NULL, N'Projects/Projetos', N'while having the bag hoisted with the crane and putting your arm under a suspended load to untie the bag is a big crushing hazard. The load can fall due sling or rigging failure. Equipment malfunction, Load shifting unexpectedly.', N'Not reaching in under suspended load ', N'0', N'01 - Imagens/01 - Antes/9087.jpeg', N'while having the bag hoisted with the crane and putting your body under a suspended load to untie the bag is a big crushing hazard. The load can fall due sling or rigging failure. Equipment malfunction, Load shifting unexpectedly.', N'01 - Imagens/02 - Depois/9087.jpeg', N'using a hay knife keeps operators out of the line of fire. Youre not putting your hands under a suspended load 
INSERT INTO #PVC VALUES (9088, N'81059721', N'365593', N'OTIMIZAÇÃO DO PROCESSO DE DRENAGEM DOS ÓLEOS PF1202', NULL, N'Others/Outros', N'A falta de uma identificação no equipamento PF1202 fazia com que falhas acontecessem, além dos riscos de contaminação, retrabalhos, perda de tempo.', N'Otimizar, padronizar', N'10144', N'01 - Imagens/01 - Antes/9088.jpeg', N'equipamento parado sem produzir, necessitando de compra emergencial. o que aumenta o custo com a compra e manutenção.
INSERT INTO #PVC VALUES (9089, N'1008375', N'1008375', N'Gengard Pipe Repair', NULL, N'Others/Outros', N'Gengard piping was leaking.', N'OPS repair leaking pipe to free up maintenance resources.', N'0', N'01 - Imagens/01 - Antes/9089.jpeg', N'Gengard piping was leaking at the cooling tower building 242, causing the loss of chemical to the containment bund.', N'01 - Imagens/02 - Depois/9089.jpeg', N'OPS sourced replacement cpvc piping and fittings. OPS then isolated and repaired the piping.', NULL, N'Yes, OPS repaired piping reducing the need to maintenance resources to be scheduled to complete the task.', N'n/a', 1000, 3, N'Better communication with other departments receiving the same daily safety message.', '2026-03-02T00:00:00.000', '2026-03-31T04:42:15.000', N'1008375', NULL, NULL);
INSERT INTO #PVC VALUES (9090, N'477830', N'81041794', N'Burner Controller Logic Optimization', NULL, N'Others/Outros', N'Recurrent burner instability during winter operations caused repeated troubleshooting, increased monitoring, production losses, and excessive gas consumption due to non‑optimized control logic.', N' Improve Reliability', N'0', N'01 - Imagens/01 - Antes/9090.jpeg', N'During the winter period, the burner system experienced recurring stability issues related to burner control logic. These issues resulted in multiple PSL call‑outs, increased daily monitoring requirements, and a loss of approximately half a day of production. Burner fire rate fluctuations reduced system reliability and led to higher than necessary natural gas consumption. The lack of optimized and stable control logic increased operational risk, maintenance effort, and energy costs.', N'01 - Imagens/02 - Depois/9090.jpeg', N'The burner controller logic was reviewed and optimized by Paul Zanetti and Steph Dubuc with support from PSL to address recurring burner and fan instability experienced during winter operations. Control parameters were adjusted to achieve a more stable operation. The proposed logic changes were reviewed and approved by Central Engineering prior to implementation. Post‑implementation trend analysis attached confirms improved fire rate stability, increased system reliability, reduced maintenance intervention and call‑outs, elimination of production losses related to burner issues, and reduced natural gas consumption.', NULL, N'Yes. The recurring burner instability was reduced by optimizing the burner controller logic.', N'Controller Adjusment', 5000, 3, N'Eliminação dos riscos associados à baixa iluminação;
INSERT INTO #PVC VALUES (9091, N'541142', N'498011', N'Válvula de limpeza flotação / Banco Rougher', NULL, N'Others/Outros', N'Ausência de ponto de água de serviço para realização de limpeza do piso do banco rougher da flotação.', N'Reduzir impactos e perdas no processo produtivo', N'10209', N'01 - Imagens/01 - Antes/9091.jpeg', N'Ausência de ponto adequado de água exigia improvisos ou longos deslocamentos, impacto negativo na organização e no padrão de limpeza da planta.', N'01 - Imagens/02 - Depois/9091.jpeg', N'A instalação da válvula possibilita controle mais adequado do uso de água e atendimento a requisitos de limpeza e organização (5S).', NULL, N'Otimização na realização de limpezas , melhora significativa do 5S da área. ', N' Perdas / Impacto produtivo / 5S', 0, NULL, N'Diminuição de tempo na realização da atividade evitando a exposição maior de trabalho em altura. ', '2026-03-30T00:00:00.000', '2026-03-31T08:23:03.000', N'541142', NULL, NULL);
INSERT INTO #PVC VALUES (9092, N'485654', N'485654', N'Check Lançamento insumos SAP', NULL, N'No Replication/Sem replicação', N'Dificuldade em verificar os aporntamentos de consumo de insumos no SAP.', N'Otimizar a verificação de apontamento de consumo de insumos no SAP', N'10227', N'01 - Imagens/01 - Antes/9092.jpeg', N'Durante fechamento de mês para apontamento do consumo dos insumos no SAP, há necessidade verificar os apontamentos no sistema, visando confiabilidade e controle de estoque. Essa consulta demandava diversas consultas na tela do SAP para comparação com o controle interno em planilhas.', N'01 - Imagens/02 - Depois/9092.jpeg', N'Criado controle de validação de dados de apontamento dos insumos no SAP, através de baixa de relatórios do sistema e confronto com controles internos, reduzindo significativamente o tempo de verificação dos dados e garantia das informações.', NULL, N'Alcançado a expectativa com sucesso.', N'Otimização de tempo e confiabilidade', 0, NULL, N'Redução no tempo de propagação das análises de produção, com a criação do banco de dados ', '2026-03-02T00:00:00.000', '2026-03-31T08:27:19.000', N'485654', NULL, NULL);
INSERT INTO #PVC VALUES (9093, N'541142', N'498011', N'Instalação de dispositivo anti chicoteamento ', NULL, N'Others/Outros', N'Ausência de dispositivo de anti chicoteamento nas válvulas de alta pressão da linha de água de serviço da flotação.', N'Eliminar condição insegura', N'10209', N'01 - Imagens/01 - Antes/9093.jpeg', N'Maior risco de chicoteamento de mangueiras em caso de rompimento
INSERT INTO #PVC VALUES (9094, N'81011396', N'81011396', N'Melhoria na modificação do Status do Sistema dos Locais de Instalação', NULL, N'Projects/Projetos', N'O processo de baixa de ativos de mina prevê a alteração do Status do Sistema dos Locais de Instalação de aproximadamente 70 ativos anualmente o que representa cerca de 880 locais de instalação. Atualmente a alteração dos Status Do Sistema é feita de forma manual com uma duração de aproximadamente 40 segundos por local de instalação.', N' Agilidade no processamento de dados', N'10015', N'01 - Imagens/01 - Antes/9094.jpeg', N'O processo de baixa de ativos de mina prevê a alteração do Status do Sistema dos Locais de Instalação de aproximadamente 70 ativos anualmente o que representa cerca de 880 locais de instalação. Atualmente a alteração dos Status Do Sistema é feita de forma manual com uma duração de aproximadamente 40 segundos por local de instalação, o que representa uma carga de trabalho de 10h anuais.', N'01 - Imagens/02 - Depois/9094.jpeg', N'Foi desenvolvido uma macro em excel que consegue alterar os dados do SAP de forma automática. A melhoria trouxe agilidade na alteração do campo Status do Sistema dos Locais de instalação através de uma macro cuja carga em massa atualiza de forma automática esse campo e reduziu em quatro vezes o tempo necessário para a modificação da informação no sistema.', NULL, N'Sim, resolvido. Pois, com o aumento da 
INSERT INTO #PVC VALUES (9095, N'541142', N'541142', N'Dispositivo acumulador / dreno de água', NULL, N'Others/Outros', N'Ausência de um dispositivo acumulador de água da linha de dreno das centrais de ar condicionado do prédio da manutenção .', N'Eliminar condição insegura ', N'10209', N'01 - Imagens/01 - Antes/9095.jpeg', N'O acumulo de água proveniente das centrais de ar condicionado, estava sendo direcionado para a passagem de pessoas ( caminho seguro ) onde além de deixar o piso escorregadio , gerava o acumulo próximo da área de manobra de ônibus e de forma recorrente contribuía para o surgimento de buracos na via .  ', N'01 - Imagens/02 - Depois/9095.jpeg', N'Após a canalização da água a faixa destinada a passagem de pessoas ( caminho seguro ) deixou de ficar com o piso escorregadio e também não houve mais acumulo de poças próximo da área de manobras de ônibus da rodoviária da usina   ', NULL, N'Após a canalização da água a faixa destinada a passagem de pessoas ( caminho seguro ) deixou de ficar com o piso escorregadio e também não houve mais acumulo de poças próximo da área de manobras de ônibus da rodoviária da usina', N'Resolução de problemas / Organização da área', 0, NULL, N'mangueira no seu devido local apropriada e em suporte padrão', '2026-03-30T00:00:00.000', '2026-03-31T09:23:37.000', N'541142', NULL, NULL);
INSERT INTO #PVC VALUES (9096, N'81033365', N'81048572', N'lavador de peças', NULL, N'Others/Outros', N'antes realizávamos lavagem no local inadequado', N'melhoria de processo', N'10139', N'01 - Imagens/01 - Antes/9096.jpeg', N'Foi identificado que não havia um local adequado para realizar lavagem de peças na oficina.', N'01 - Imagens/02 - Depois/9096.jpeg', N'Foi disponibilizado um sistema de lavador adequado para lavar peças na oficina.', NULL, N'não havia lavador adequado.', N'adequação no processo de lavagem', 0, NULL, N'This initiative delivered a standardized, visual system that clearly identifies scaffold areas that are fully inspected and approved for use, eliminating ambiguity across complex, multi‑level scaffolding. Enhanced tagging, joint inspections, and daily communication significantly reduced the risk of accessing incomplete or unsafe scaffold areas while improving shift‑to‑shift continuity. As a result, worker safety, accountability, and operational efficiency were measurably strengthened.', '2026-03-25T00:00:00.000', '2026-03-31T09:59:12.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9097, N'81050014', N'81050014', N'Controle inicial', NULL, N'Others/Outros', N'EQUIPAMENTO ENCONTRAVA-SE NA ÁREA EM SEM CODIFICAÇÃO, SEM PLANOS ATIVOS E OCORRENDO CONSTANTES AÇÕES CORRETIVAS', N'REALIZAR O CONTROLE INICIAL DO EQUIPAMENTO', N'10178', N'01 - Imagens/01 - Antes/9097.jpeg', N'Foi identificado que o compressor e secador não possuem codificação atualizada no sistema (list boom desatualizada), o que compromete o controle e rastreabilidade dos ativos. O equipamento encontra-se em operação na área sem planos preventivos definidos, sem sobressalentes disponíveis e sem classificação adequada como crítico, apesar de ser essencial para manter a ETBR em funcionamento contínuo.
INSERT INTO #PVC VALUES (9098, N'81055953', N'1008798', N'using available resources', NULL, N'Projects/Projetos', N'Workers fabricated a new spool which needed to be hydro tested for QC. this spool had Victaulic fitting which made impossible to hydro', N'cost saving', N'0', N'01 - Imagens/01 - Antes/9098.jpeg', N'Fabrication team welded a spool which needed to be hydroid to pass QC. with one end being a Victaulic fitting, this made it difficult to hydro and would possibly need to be X-ray tested. X-ray testing can be expensive especially on weekends where we would need to pay OT rates.  ', N'01 - Imagens/02 - Depois/9098.jpeg', N'Had fab team weld another flange to victaulic pipe which we could the connect to newly fabricated spool and hydro properly as per QC requests. we then stored this new fitting in hydro cabinet to use in future.', NULL, N'Yes. new spool fabricated to avoid bringing in 3rd party contractor to X-ray spools when we can hydro them on site ourselves.', N'preperation', 2500, 3, N'Com a criação da planilha automatizada para elaboração dos textos das requisições SPOT, o processo passou a ser padronizado, mais rápido e com menor índice de erros.
INSERT INTO #PVC VALUES (9099, N'81057613', N'81057613', N'Homologação de Kit de Emenda para Cabos de Média Tensão', NULL, N'Open Pit/Poço aberto', N'Identificado reincidência de falha dos cabos elétricos que foram reparados com o kit emenda de baixa qualidade e de maior complexibilidade de aplicação, ocasionando parada corretivas não programadas.', N'Elevar qualidade do kit emenda aplicado, confiabilidade e reduzir tempo de intervenção e MTTR', N'10293', N'01 - Imagens/01 - Antes/9099.jpeg', N'Eram utilizados kit emenda de baixa qualidade e maior complexidade de aplicação havendo constante reincidência de falhas nos pontos reparados nos cabos. O tempo de aplicação do kit emenda anterior era de aproximadamente 01h30min.', N'01 - Imagens/02 - Depois/9099.jpeg', N'Foi realizada a homologação de um novo kit de emenda para cabos de média tensão, com melhor qualidade construtiva, menor complexidade de aplicação e padronização do método.
INSERT INTO #PVC VALUES (9100, N'81033365', N'81048572', N'suporte de cilindros', NULL, N'Others/Outros', N'ausência de suporte adequado', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/9100.jpeg', N'Foi identificado que os cilindros estavam armazenados de forma inadequada e de forma insegura.', N'01 - Imagens/02 - Depois/9100.jpeg', N'Foi fabricado um suporte de cilindro para facilitar o manuseio de forma segura.', NULL, N'cilindro armazenado de forma insegura.', N'manuseio de forma segura', 0, NULL, N'Maior controle das intervenções diárias, aumento da eficiência operacional e melhor priorização das atividades.', '2026-03-30T00:00:00.000', '2026-03-31T12:40:07.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9101, N'92000352', N'92000352', N'Padronização e Centralização da Gestão dos Treinamentos Obrigatórios – PNR‑00006 | DBU Sabolo', NULL, N'Others/Outros', N'Antes da iniciativa, o processo de gestão dos treinamentos obrigatórios apresentava fragilidades críticas:
INSERT INTO #PVC VALUES (9102, N'124132', N'124132', N'New tablet for morning line ups', NULL, N'Refining/Refino', N'Didn''t have tablets for line ups', N'Better communication', N'10255', N'01 - Imagens/01 - Antes/9102.jpeg', N'We did not have tablets to use at our morning line up meetings.', N'01 - Imagens/02 - Depois/9102.jpeg', N'Now we have tablets to add people via teams at our morning line ups. This provides better communication between departments. We have our security department joining us to receive the safety review and the daily safety message.', NULL, N'Safety message being received by other departments.', N'Better communication', 0, NULL, N'Controle das trocas de parafusos', '2026-03-09T00:00:00.000', '2026-03-31T12:58:00.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (9103, N'499302', N'538357', N'Carreagdro de Navios: Luz da Segurança na Manutenção', NULL, N'Others/Outros', N'Observa-se deficiência na iluminação dos trucks do carregador de navios, resultando em baixa luminosidade na área operacional. Essa condição reduz a visibilidade dos componentes e do trajeto, aumentando o risco de falhas operacionais e incidentes de segurança.', N'Reduzir aumentat a luminosidade nos trucks do CN', N'10294', N'01 - Imagens/01 - Antes/9103.jpeg', N'Anteriormente, os trucks do Carregador de Navios (CN) apresentavam uma condição crítica de baixa iluminação. Essa deficiência comprometia a execução das atividades de manutenção e inspeção, além de impactar de forma significativa as operações noturnas durante os dias de embarque. A visibilidade reduzida prejudicava a atuação dos inspetores e aumentava substancialmente o risco de ocorrência de acidentes operacionais.', N'01 - Imagens/02 - Depois/9103.jpeg', N'Após a instalação dos refletores, os riscos associados à baixa ou inexistente iluminação foram eliminados. A melhoria proporcionou maior confiabilidade na execução das atividades de manutenção e inspeção, bem como nas operações realizadas no local durante o período noturno, garantindo melhores condições de visibilidade e segurança operacional.', NULL, N'Realizou-se a instalação de refletores adequados, posicionados estrategicamente para garantir iluminação eficiente nos pontos críticos dos trucks e nas áreas de circulação e inspeção', N'A iluminação adequada é um fator crítico de segurança e confiabilidade operacional. Investimentos relativamente simples em melhorias de infraestrutura, como sistemas de iluminação, têm impacto direto na redução de riscos, na eficiência das atividades operacionais e na integridade dos trabalhadores.', 0, NULL, N'9. Resultados Esperados (Demonstrados)
INSERT INTO #PVC VALUES (9104, N'81050579', N'540124', N'válvula atmosférica  ', NULL, N'Projects/Projetos', N'Antes era necessário uma escada de apoio pra realizar o abastecimento colocando o risco de queda em altura, e demandava tempo para realizar a atividade.', N'segurança ', N'10166', N'01 - Imagens/01 - Antes/9104.jpeg', N'Antes era necessário uma escada de apoio pra realizar o abastecimento colocando o risco de queda em altura, e demandava tempo para realizar a atividade.', N'01 - Imagens/02 - Depois/9104.jpeg', N'Depois foi implementado uma válvula atmosférica para melhor aplicação de abastecimento de óleo eliminando a exposição de tempo em altura   ', NULL, N'sim', N'sentimento de dono ', 0, NULL, N'Aumento das aderência, após inicio da medição', '2026-03-25T00:00:00.000', '2026-03-31T13:37:24.000', N'81050579', NULL, NULL);
INSERT INTO #PVC VALUES (9105, N'81054436', N'81054436', N'Automação do Banco de Dados de Produção via VBA', NULL, N'No Replication/Sem replicação', N'Não havia no processo um banco de dados histórico estruturado que viabilizasse a construção de uma ferramenta de análise, como o Power BI, sem a necessidade de atualizações manuais e diárias.
INSERT INTO #PVC VALUES (9106, N'81050579', N'81013220', N'Chapa para manutenção ', NULL, N'Projects/Projetos', N'Chapa utilizada de apoio as perfuratriz, sem a sua devida pintura padrão  ', N'segurança ', N'10166', N'01 - Imagens/01 - Antes/9106.jpeg', N'Chapa utilizada de apoio as perfuratriz, sem a sua devida pintura padrão poluindo o ambiente de trabalho   ', N'01 - Imagens/02 - Depois/9106.jpeg', N'Após foi realizado a pintura da chapa mantendo o ambiente mais padronizado e limpo  ', NULL, N'Sim', N'5s', 0, NULL, N'Com a implementação do robô auxiliar, todas as etapas que eram manuais e repetitivas — como digitar descrições, códigos, classificações e principalmente datas de planejamento mais de 120 vezes por processo — passaram a ser automatizadas.
INSERT INTO #PVC VALUES (9107, N'81013712', N'200538', N'Asset Protection', NULL, N'Underground/Subterrâneo', N'Pumps for water management on 1250L have historically been placed on the ground which has led to an increase of damage - due to equipment hitting (poor visibility)', N'Reduce the likelihood of causing damage to pump', N'10345', N'01 - Imagens/01 - Antes/9107.jpeg', N'Pumps for water management on 1250L have historically been placed on the ground which has lead to an increase of damage - due to equipment hitting (poor visibility)', N'01 - Imagens/02 - Depois/9107.jpeg', N'Pump was chained and secured to the wall to minimize the chance of damage by inadvertent contact if it was left on the ground. Pump was also marked (painted orange & brow markers) to make it more visible to reduce chances of contact with mobile equipment.', NULL, N'Problem was solved.', N'N/A', 5000, 3, N'MELHOR INSTERFACE COM OS FORNECEDORES.', '2026-03-11T00:00:00.000', '2026-03-31T14:26:36.000', N'81013712', NULL, NULL);
INSERT INTO #PVC VALUES (9108, N'81059721', N'552496', N'SUPORTE PARA MANGUEIRA DO COMPREENSOR DE AR COMPRIMIDO', NULL, N'Others/Outros', N'Antes a mangueira do compressor de ar comprimido, não era organizada de forma padronizada, de fácil acesso a todos, a mesma não possuía sinalização, ficava em cima de palets de forma desordenada.', N'Organização, melhorar acesso e manter padronizado', N'10144', N'01 - Imagens/01 - Antes/9108.jpeg', N'Anteriormente a mangueira do compressor de ar comprimido, não era organizada de forma padronizada, de fácil acesso a todos, a mesma não possuía sinalização, ficava em cima de palets de forma desordenada.', N'01 - Imagens/02 - Depois/9108.jpeg', N'Com a criação do suporte, a mangueira mangueira do compressor de ar comprimido ficou de forma nítida, com sua identificação, facilitando que todos os turnos mantenham organizada e pratica para uso.
INSERT INTO #PVC VALUES (9109, N'200828', N'200828', N'Scaffolding Access ', NULL, N'Projects/Projetos', N'Scaffold erected for construction access and hoarding during the construction of the new spillway contained several different working levels with varying access points. These multiple access points created ambiguity of what areas of scaffolding were functionally complete for scaffolders to continue erection vs. 100% complete for worker access.', N'Optimize scaffold completion identification processes for workers to rapidly and easily identify which scaffolding areas have been verified by multiple levels of supervision to be 100% complete and green tagged for use.', N'10238', N'01 - Imagens/01 - Antes/9109.jpeg', N'Scaffolding was being used by workers to begin construction of the new spillway that was identified to have missing scaffold components, such as holes in scaffold decking, toe boards missing and improper signage. These deficient items were not identified by scaffolding supervision or contractor supervision prior to being used for access. Ongoing modifications to scaffolding rendered green tags obsolete which were not optimally communicated at shift handovers between day shift and afternoon shift. On several occasions, afternoon shift workers only learned that modifications that created hazards had occurred once they accessed the area where these hazards existed and completed their pre-shift inspections. ', N'01 - Imagens/02 - Depois/9109.jpeg', N'Only work areas that have been inspected by the contractor supervisor, scaffold supervisor and Vale Construction Coordinators, and deemed safe to work in will be accessible to workers. Every scaffold deck level must have a status tag at each access point, with all areas that have not been jointly reviewed red tagged and barricaded with do not enter signage. The status of work fronts and individual scaffold areas – broken down by scaffold level, scaffold type and pier ID - will be listed for each individual work area, posted in a visible place in the worker’s trailer, scaffold status/changes to be communicated to all workers daily at shift line-ups, and green tags to be implemented for each scaffold level access. Positive impact is workers can audit and verify access prior to entering the work area and communication to all workers in consistent.', NULL, N'Yes, the problem was eliminated. Have the workers review the documents prior to start of work, removed the confusion and the possibility of workers accidently walking into unsafe conditions. ', N'1. Green tags alone are insufficient on complex, multi-level scaffolding where ongoing modifications occur.  2. Visual management must be granular—scaffold status needs to be identified by individual level and access point, not the structure as a whole.  3. Shift handovers are a critical control point for safety-related changes, especially where physical conditions evolve daily.  4. Workers need the ability to independently verify access status before entering a work area, without relying solely on verbal communication.', 0, NULL, N'Helps operators respond quicker and reduces plant upsets', '2025-12-19T00:00:00.000', '2026-03-31T15:09:58.000', N'200828', NULL, NULL);
INSERT INTO #PVC VALUES (9110, N'81059721', N'552496', N'INSTALAÇÃO DO FAROL ES2301', NULL, N'Projects/Projetos', N'Não havia iluminação para monitorar as pontas das bombas e portas do radiador hidráulico, estão abertas ou não, dificuldade visual para o trabalho noturno na mina.
INSERT INTO #PVC VALUES (9111, N'81016184', N'502207', N'Ferramenta de Criação de Texto para Requisições SPOT', NULL, N'Others/Outros', N'O processo de criação de textos para requisições SPOT era realizado manualmente, exigindo busca individual de informações, como descrição do material, fabricante, aplicação e modelo. Esse método gerava retrabalho, inconsistências e maior tempo no preenchimento, impactando diretamente a agilidade e a qualidade das requisições enviadas ao setor de compras.', N'Otimização de tempo ', N'10008', N'01 - Imagens/01 - Antes/9111.jpeg', N'Criação de textos totalmente manual para cada requisição.
INSERT INTO #PVC VALUES (9112, N'839373', N'839373', N'Visor de nível', NULL, N'No Replication/Sem replicação', N'Dificuldade para visualização do nível de óleo do soprador', N'Facilitar a visualização do nível de óleo do mancal do soprador', N'10362', N'01 - Imagens/01 - Antes/9112.jpeg', N'Não havia visor no mancal do soprador dificultando a visualização do nível de óleo', N'01 - Imagens/02 - Depois/9112.jpeg', N'Foi instalada um dispositivo (mangueira) para visualização do nível de óleo do mancal', NULL, N'Sim, resolvido', N'Identificar a melhor forma de visualizar o nível de óleo dos mancais', 0, NULL, N'MELHORA NO PROCESSO', '2026-03-20T00:00:00.000', '2026-03-31T15:51:57.000', N'839373', NULL, NULL);
INSERT INTO #PVC VALUES (9113, N'81004893', N'81004893', N'Identificação de eventos críticos distintos para intervenção dedicada YEM', NULL, N'Others/Outros', N'Dificuldade em identificar eventos críticos únicos devido à repetição de registros, dificultando a priorização e intervenção YEM', N'Garantir que a telemetria faça identificação de eventos críticos sem repetição, permitindo atuação direcionada e eficiente.', N'10015', N'01 - Imagens/01 - Antes/9113.jpeg', N'Eventos críticos registrados de forma repetitiva, gerando sobreposição de informações e dificultando a análise e tomada de decisão ', N'01 - Imagens/02 - Depois/9113.jpeg', N'Foi elaborado um visual em dashboard dos eventos críticos, onde passaram a ser classificados de forma distinta e padronizada, permitindo uma análise mais clara das causas, melhor rastreabilidade das ocorrências e direcionamento assertivo das ações corretivas e preventivas. Essa abordagem viabiliza a definição de tratativas específicas para cada tipo de evento, reduz reincidências e fortalece a efetividade das intervenções.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/57b68cba-2247-4f57-899a-a8bd95b9b745/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'A meta inicial de identificar eventos críticos sem repetição foi atingida, eliminando registros duplicados e permitindo análise individual. O problema de priorização foi mitigado com maior foco nas ocorrências realmente críticas.', N'A identificação correta de eventos distintos é essencial para foco, assertividade e melhoria contínua.', 0, NULL, N'Houve aumento da conscientização sobre áreas restritas, redução de desvios comportamentais, fortalecimento da cultura de segurança e maior conformidade em inspeções e auditorias.', '2026-03-17T00:00:00.000', '2026-03-31T15:55:11.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (9114, N'81059721', N'547828', N'OTIMIZAÇÃO DO PROCESSO DE DRENAGEM DOS ÓLEOS - PF1202', NULL, N'Others/Outros', N'
INSERT INTO #PVC VALUES (9115, N'839373', N'839373', N'Controle Alongamento parafuso munhão SAG', NULL, N'Concentration/Concentração', N'Não controle dos parafusos alongados e trocados no SAG', N'Controlar as trocas e o alongamento dos parafusos do SAG', N'10362', N'01 - Imagens/01 - Antes/9115.jpeg', N'Não havia controle dos alongamentos e das trocas dos parafusos do munhão do SAG', N'01 - Imagens/02 - Depois/9115.jpeg', N'Elaboração e acompanhamento do alongamento e das trocas dos parafusos dos munhão de alimentação do SAG', NULL, N'Sim, temos controle dos alongamentos e das trocas de parafuso', N'Controle auxilia na tomada decisão', 0, NULL, NULL, '2026-03-12T00:00:00.000', '2026-03-31T16:11:16.000', N'839373', NULL, NULL);
