INSERT INTO #PVC VALUES (9143, N'81056513', N'81047185', N'REPOSICIONAMENTO DE CALHA', NULL, N'Others/Outros', N'Falha no posicionamento da calha de passagem dos cabos eletricos proximo a saida de gases de escape do motor 1', N'EVITAR FALHAS ELETRICAS', N'10324', N'01 - Imagens/01 - Antes/9143.jpeg', N'Falha no posicionamento da calha de passagem dos cabos elétricos próximo a saída de gases de escape do motor 1', N'01 - Imagens/02 - Depois/9143.jpeg', N'Removido calha da posição original e posicionado atras da viga estrutural do teto da casa de maquinas', NULL, N'Sim, eliminado falhas elétricas que eram causadas devido posicionamento das calha', N'Correção de problemas', 0, NULL, N'sim.
INSERT INTO #PVC VALUES (9144, N'81052339', N'81052339', N'ILUMINAÇAO NA AREA DO AM 20', NULL, N'Projects/Projetos', N'ACIDENTES POR FALTA DE VISIBILIDADE 
INSERT INTO #PVC VALUES (9145, N'81034908', N'81034908', N'Portão acesso ao fosso', NULL, N'Projects/Projetos', N'Foi observado que não havia portão para limitação de pessoas ao fosso do salobo 3, e caso ocasionasse um transbordo ou uma drenagem de caixa, não tinha um controle de pessoas no aceso ao fosso, podendo ocasionar projeção de material em pessoas.', N'controle de acesso de pessoas', N'10031', N'01 - Imagens/01 - Antes/9145.jpeg', N'Foi observado que não havia portão para limitação de pessoas ao fosso do salobo 3, e caso ocasionasse um transbordo ou uma drenagem de caixa, não tinha um controle de pessoas no aceso ao fosso, podendo ocasionar projeção de material em pessoas.', N'01 - Imagens/02 - Depois/9145.jpeg', N'Foi realizado a confecção e montagem de um portão, montado um cadeado para controle de acesso ao fosso do salobo 3, com isso a operação terá conhecimento e controle de pessoas que estiverem no fosso.', NULL, N'problema foi resolvido, agora o time da operação terá o controle de acesso de pessoas ao fosso.', N'Todo ativo para ser melhorado', 0, NULL, NULL, '2026-03-25T00:00:00.000', '2026-04-02T01:35:54.000', N'81034908', NULL, NULL);
INSERT INTO #PVC VALUES (9146, N'1014252', N'1014252', N'Rag bin for Co O:A', NULL, N'No Replication/Sem replicação', N'Rags left up on O:A platform', N'keeps area clean and rags contained', N'0', N'01 - Imagens/01 - Antes/9146.jpeg', N'Rags left on pipe', N'01 - Imagens/02 - Depois/9146.jpeg', N'Bin for rags', NULL, N'yes', N'keep area clean', 0, NULL, N'•	Eliminação de vazamentos
INSERT INTO #PVC VALUES (9147, N'81058052', N'81058052', N'PADRONIZAÇÃO ARMAZENAMENTO DE MACACOS HIDRAULICOS', NULL, N'Others/Outros', N'Os macacos hidráulicos estavam sendo armazenados de forma inadequada, dispostos sobre paletes sem padronização, organização ou identificação definida. Essa condição gerava desordem no local, dificultava o acesso aos equipamentos, aumentava o tempo de busca e expunha os macacos a riscos de quedas, danos e contaminação.
INSERT INTO #PVC VALUES (9148, N'81044674', N'81039011', N'Instalação de Válvulas', NULL, N'No Replication/Sem replicação', N'Ocorrência de obstruções na linha e necessidade de trocas frequentes de mangueiras e conexões, impactando a produção.', N'Reduzir obstruções e evitar trocas repentinas de componentes.', N'10031', N'01 - Imagens/01 - Antes/9148.jpeg', N'Sistema dependente de esforço físico e sujeito a obstruções frequentes na linha (Equipamento AM 2057-18).
INSERT INTO #PVC VALUES (9149, N'81044674', N'81010548', N'Proteção do Eixo do Mancal', NULL, N'No Replication/Sem replicação', N'Foi identificado que o equipamento BP-2057-24 encontrava-se sem proteção na parte rotativa do eixo do mancal.
INSERT INTO #PVC VALUES (9150, N'524896', N'81035519', N'Otimização do Acionamento da Escada Principal da PZ43', NULL, N'Others/Outros', N'O acionamento da escada principal da PZ43 era realizado fora da cabine, exigindo que o operador descesse do posto de operação para acioná-la, gerando deslocamento desnecessário e esforço físico adicional. 
