INSERT INTO #PVC VALUES (9152, N'81019009', N'81019009', N'Consulta de peça Cartepillar', NULL, N'No Replication/Sem replicação', N'Não há ferramenta para consultar disponibilidade de peça da Caterpillar', N'Obter disponibilidade das peças Caterpillar', N'10227', N'01 - Imagens/01 - Antes/9152.jpeg', N'Não há ferramenta para consultar disponibilidade das peças na loja inconpay Sotreq disponível no site MOP', N'01 - Imagens/02 - Depois/9152.jpeg', N'Criado BI para consultar disponibilidade das peças Caterpillar disponíveis na loja inconpay Sotreq situada no site MOP', N'https://app.powerbi.com/groups/04bad810-4f67-4567-946d-2cd015bd297a/reports/faeb5722-5248-4b61-8342-f64dd7c50e8b/ReportSection?experience=power-bi', N'Acesso a disponibilidade das peças da loja Incopany da Sotreq em feriados e finais de semana.', N'Consulta a disponibilidade', 0, NULL, N'sim.
