INSERT INTO #PVC VALUES (9479, N'81049566', N'502163', N'Óleo direcionado', NULL, N'Crusher/Britadeira', N'Após partida da usina, identificamos uma projeção de OLEO pela válvula de dreno da linha, onde poderia ter ocasionado um acidente em projetando óleo na sala de lubrificação do SAG,. ', N'Eliminar risco de projeção de Oléo em pessoas.', N'10362', N'01 - Imagens/01 - Antes/9479.jpeg', N'Ausência de Mangueira para direcionar o dreno da linha em caso de sobrecarga no sistema pela valvula de alivio, podendo projetar em pessoas caso estivessem na sala.', N'01 - Imagens/02 - Depois/9479.jpeg', N'Instalado uma Mangueira após a saída da válvula de alivio, direcionando o fluxo de óleo para a canaleta da sala, caso ocorra despressurização do sistema pelo alivio, o óleo não corre o risco de acertar pessoas. ', NULL, N'Eliminado risco de projeção de oleo em pessoas com a instalação de mangueira.', N'area mais segura', 0, NULL, N'Eliminado a condição de cortes caso aja batidas contra placa.', '2026-04-20T00:00:00.000', '2026-04-21T11:23:51.000', N'81049566', NULL, NULL);
