INSERT INTO #PVC VALUES (9759, N'81054205', N'81054205', N'Indicador de processos- Recebimento/Notas fiscais', 1, N'Others/Outros', N'Falta de controle sobre os processos fiscais referente ao recebimento Físico e Fiscal  dos materiais recebidos e aplicados em campo', N'Reduzir quantitativo de  reclamação de atraso de pagamento de nota fiscal de material  por parte do fornecedor', N'10294', N'01 - Imagens/01 - Antes/9759.jpeg', N'Na gerência, inexistia um controle efetivo das notas fiscais de materiais com pendência de recebimento físico e/ou fiscal, bem como dos processos necessários para geração de MIGO e MIRO, essenciais à liberação de pagamento aos fornecedores.
INSERT INTO #PVC VALUES (9760, N'125765', N'125765', N'PADRÃO DE CADASTRO DADOS MESTRES | LOC E EQUIP', 1, N'Others/Outros', N'Antes não tinha um padrão para seguir de cadastro dos dados mestres alinhado aos requisitos de qualidade da base de dados.', N'CRIAR UM PADRÃO DE CADASTRO DADOS MESTRES | LOC E EQUIP', N'10154', N'01 - Imagens/01 - Antes/9760.jpeg', N'Antes não tinha um padrão para seguir de cadastro dos dados mestres alinhado aos requisitos de qualidade da base de dados.', N'01 - Imagens/02 - Depois/9760.jpeg', N'Agora temos um padrão com a sinalização dos campos mínimos para seguir no cadastro dos dados mestres alinhado aos requisitos de qualidade da base de dados. Facilita e direciona o engenheiro no padrão mínimo de campos que devem ser preenchidos no momento de cadastrar um local de instalação.', NULL, N'Antes da implementação do Kaizen, não existia um padrão para cadastro do local de instalação /Equipamento.', N'PADRONIZAÇÃO', 0, NULL, N'Redução de horas de exposição ao risco das atividade de troca de cilindro.', '2026-04-27T00:00:00.000', '2026-04-30T16:00:55.000', N'125765', NULL, NULL);
INSERT INTO #PVC VALUES (9761, N'541142', N'81006685', N'Instalação de calha direcionadora de fluxo ', 1, N'Others/Outros', N'Ausência de ponto de direcionamento do fluxo que  evite refluxo / transbordo da calha de coleta e passagem da alimentação da flotação.', N'Reduzir impactos e perdas no processo produtivo', N'10209', N'01 - Imagens/01 - Antes/9761.jpeg', N'Ausência de ponto de direcionamento do fluxo que  evite refluxo / transbordo da calha de coleta e passagem da alimentação da flotação.', N'01 - Imagens/02 - Depois/9761.jpeg', N'Instalado uma calha de direcionamento do fluxo que  evite refluxo / transbordo da calha de coleta e passagem da alimentação da flotação.', NULL, N'Instalado uma calha de direcionamento do fluxo que  evite refluxo / transbordo da calha de coleta e passagem da alimentação da flotação.', N'Perdas / Impacto produtivo / 5S', 0, NULL, N'-Maior confiabilidade dos dados de estoque e balanço de massa;
INSERT INTO #PVC VALUES (9762, N'81026275', N'81026275', N'221 Online Vibration & Temperature Monitoring', 1, N'Refining/Refino', N'Vibration monitoring was being done manual using a handheld vibration analyzer. This is a time consuming practice, and limited vibration data collection to once per month.', N'To improve asset condition monitoring ', N'10006', N'01 - Imagens/01 - Antes/9762.jpeg', N'Vibration monitoring was being done manual using a handheld vibration analyzer. This is a time consuming practice, and limited vibration data collection to once per month.
INSERT INTO #PVC VALUES (9763, N'81023781', N'81023781', N'5S location for Eluo parts ', NULL, N'Others/Outros', N'we didnt have stock of parts or replacement for the eluo nebulizer cleaner', N'stock', N'0', N'01 - Imagens/01 - Antes/9763.jpeg', N'the lab didn''t have stock of replacements parts for the eluo nebulizer cleaner. ', N'01 - Imagens/02 - Depois/9763.jpeg', N'ordered new eluo cleaners and replacement o-rings. Then created a storage area with inventory cards.', NULL, N'Yes', N'keeping stock of replacement parts', 0, NULL, N'Sim', '2026-03-26T00:00:00.000', '2026-04-30T16:09:20.000', N'81023781', NULL, NULL);
INSERT INTO #PVC VALUES (9764, N'608878', N'608878', N'5160 shop door sill replacement', 1, N'Underground/Subterrâneo', N'Door sill suffered Damage through years of use', N'improve the structure of the door sill', N'10246', N'01 - Imagens/01 - Antes/9764.jpeg', N'Door sill was rotten and Fire door could not be used. ', N'01 - Imagens/02 - Depois/9764.jpeg', N'Replaced door sill and fire door is back in operation ', NULL, N'yes', N'we could save money doing the work in house. ', 1, 3, N'-Maior confiabilidade e abrangência da análise operacional diária;
INSERT INTO #PVC VALUES (9765, N'81032361', N'81055103', N'PROTEÇÃO ANTENA GPS TT''s', 1, N'Projects/Projetos', N'SUPORTE DO TT91 DAS ANTENAS DE GPS QUEBROU DEVIDO EXCESSO DE VIBRAÇÃO E FRAGILIDADE DO PROJETO INICIAL', N'SEGURANÇA', N'10216', N'01 - Imagens/01 - Antes/9765.jpeg', N'SUPORTE COM CHAPAS FINAS E MUITAS AMARRAÇÕES PARA SUSTENTAÇÃO DA BASE DA ANTENA DE GPS, GERANDO PARADAS PARA SOLDA E RETRABALHOS', N'01 - Imagens/02 - Depois/9765.jpeg', N'DESENVOLVIDO SUPORTE ROBUSTO DE FÁCIL FIXAÇÃO E PERMITINDO TROCA RÁPIDA DO MESMO', NULL, N'SIM / REDUÇÃO DE 6H DE TRABALHO PARA REPARO / RESTABELECIMENTO DE MÁQUINA EM CASO DE FALHAS ESTRUTURAIS', N'EQUIPAMENTO COM ESTRUTURA DE FÁCIL TROCA E RÁPIDO REPARO EM CASO DE FALHAS', 0, NULL, N'A implementação da sumarização dos eventos operacionais, com ranking estruturado e disponibilização imediata do extrato consolidado, eliminou a necessidade de análises manuais e consultas dispersas', '2026-04-27T00:00:00.000', '2026-04-30T16:24:03.000', N'81032361', NULL, NULL);
INSERT INTO #PVC VALUES (9766, N'541142', N'81006685', N'Marcador de ponto de baixo giro', 1, N'Others/Outros', N'Ausência de ponto de referencia no ponto de baixo giro na realização de 360 graus no descongelamento da carga em procedimento operacional pré partida .', N'Reduzir impactos e perdas no processo produtivo', N'10209', N'01 - Imagens/01 - Antes/9766.jpeg', N'Ausência de ponto de referencia no ponto de baixo giro na realização de 360 graus no descongelamento da carga em procedimento operacional pré partida .', N'01 - Imagens/02 - Depois/9766.jpeg', N'Confeccionado dispositivo de marcação de para realização do baixo giro dos moinhos de bolas em procedimento operacional.', NULL, N'Confeccionado dispositivo de marcação de para realização do baixo giro dos moinhos de bolas em procedimento operacional.', N'Perdas / Impacto produtivo', 0, NULL, N'resultado alcançado.', '2026-04-29T00:00:00.000', '2026-04-30T16:41:27.000', N'541142', NULL, NULL);
INSERT INTO #PVC VALUES (9767, N'477830', N'81041794', N'Conversion of CX‑154 Single Deck Personal Cage to Material Cage', 1, N'Underground/Subterrâneo', N'Underutilized asset (personal cage sitting idle).
INSERT INTO #PVC VALUES (9768, N'554321', N'554321', N'App para Cadastro de Justificativas de Desvios Econômicos e Financeiros de Projetos', 1, N'Projects/Projetos', N'Atualmente, as justificativas de desvios dos projetos são registradas descentralizadas, sem padronização e com baixa rastreabilidade, o que dificulta o controle e a consolidação das informações', N'Implantar um aplicativo para padronizar e centralizar o cadastro das justificativas de desvios econômicos e financeiros de projetos, garantindo maior transparência, rastreabilidade.', N'10000', N'01 - Imagens/01 - Antes/9768.jpeg', N'As justificativas são elaboradas em diferentes formatos (e-mails, planilhas, etc.), sem um repositório único.
INSERT INTO #PVC VALUES (9769, N'499365', N'499365', N'Gestão Estruturada do AIP com Foco em 90% de Aderência ao Budget Capex 2026', 1, N'Projects/Projetos', N'Necessidade de controle efetivo do AIP para garantir 90% de aderência ao Budget Capex 2026. A falta de monitoramento consolidado reduz transparência, dificulta ação preventiva e compromete previsibilidade e disciplina de capital', N'Controle efetivo do AIP para reforçar disciplina de capital e previsibilidade financeira, assegurando alinhamento à estratégia e aderência mínima de 90% ao Budget Capex 2026 (USD), com monitoramento consolidado por nível gerencial.', N'10367', N'01 - Imagens/01 - Antes/9769.jpeg', N'Ausência de modelo em Power BI para o AIP gerava baixa transparência, atuação reativa e riscos ao Capex. Reportes levavam até 3 dias, comprometendo previsibilidade, disciplina de capital e governança.', N'01 - Imagens/02 - Depois/9769.jpeg', N'Tela de Controle do AIP ampliou visibilidade do CAPEX 2026, permitindo monitoramento contínuo, ação preventiva sobre desvios, fortalecimento da governança e suporte executivo com dados confiáveis em até 30 minutos.', N'https://app.powerbi.com/Redirect?action=OpenReport&appId=5afac2a5-3ab4-4354-8d9c-54738ad74313&reportObjectId=ea8a384c-6483-4b89-bab7-5c2df8f1a26a&ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626', N'Sem controle estruturado do AIP, havia baixa visibilidade e previsibilidade do Capex. A tela consolidada assegura monitoramento contínuo, aderência de 90% ao Budget 2026 e decisões alinhadas à governança', N'A principal lição aprendida foi que a falta de um controle estruturado e sistemático do AIP compromete a transparência, a previsibilidade financeira e a disciplina de capital, enquanto a implementação de uma tela de acompanhamento consolidada permite atuação preventiva sobre desvios, fortalece a responsabilização das lideranças e eleva significativamente a qualidade da tomada de decisão executiva, em linha com as melhores práticas de governança.', 0, NULL, N'eficiência , redução dos risco de acidentes e danos a equipamentos.
INSERT INTO #PVC VALUES (9770, N'81057538', N'81057538', N'ORGANIZAÇÃO E PADRONIZAÇÃO DO DESCARTE DE VIDRARIA', NULL, N'Others/Outros', N'-A lixeira destinada ao descarte de vidraria não possuía identificação clara sobre o limite que deveria ser descartado. ', N' melhorar o nível máximo de descarte de vidrarias e a correta identificação visual da área.', N'10129', N'01 - Imagens/01 - Antes/9770.jpeg', N'tinhamos dificuldades na identificação do nível máximo de descarte não era facilmente perceptível à distância ou durante a rotina operacional.', N'01 - Imagens/02 - Depois/9770.jpeg', N' A sinalização foi implantada, tornando o nível máximo de descarte de vidrarias mais visível e intuitivo, reduzindo dúvidas durante a operação.
INSERT INTO #PVC VALUES (9771, N'989707', N'989707', N'Padronização óleo Hidráulico Frota Perfuratriz Grande Diâmetro e Pequeno Diâmetro', 1, N'Others/Outros', N'Utilização de 2 tipos de óleo hidráulico Hydra XP 32 e óleo Hydra XP 68 nas frotas Perfuração Grande e Pequeno Diâmetro', N'Padronização óleo das frotas Perfuratriz Mina Sossego', N'10081', N'01 - Imagens/01 - Antes/9771.jpeg', N'Utilização dos óleos hidráulicos Hydra XP 32 e Hydra XP 68 nos sistemas hidráulicos das perfuratrizes de grande e pequeno diâmetro. ', N'01 - Imagens/02 - Depois/9771.jpeg', N'Após a padronização inicial, foi identificada melhoria na performance dos equipamentos com a utilização do óleo hidráulico Hydra XP 68. No entanto, ao avançar na análise técnica visando à padronização dos óleos hidráulicos, considerando os parâmetros de viscosidade e temperatura de operação, concluiu-se que o óleo Hydra XP 100 atende integralmente os requisitos operacionais dos equipamentos Sandvik DR416i, Epiroc PV351D e FlexROC D60/D65.', NULL, N'Situação Inicial Utilização de diferentes óleos hidráulicos (Hydra XP 32 e Hydra XP 68) nas perfuratrizes de grande e pequeno diâmetro. Ausência de padronização técnica, gerando: variação de performance operacional; maior exposição a falhas relacionadas à viscosidade e temperatura; aumento da complexidade na manutenção e no controle de estoque. Impacto indireto na confiabilidade dos equipamentos, refletindo em falhas recorrentes e perda de performance.', N'A não padronização de fluidos hidráulicos pode gerar variações operacionais, dificultar o controle de performance e aumentar o risco de falhas relacionadas à viscosidade e temperatura de operação.', 0, NULL, N'Foi evitado quedas e retrabalhos junto ao processo de transporte em empilhadeiras transporte e armazenamento do cilindro de forma ordenada.
INSERT INTO #PVC VALUES (9772, N'81004462', N'81004462', N'Otimização de material de limpeza em Preventivas', 1, N'Others/Outros', N'Custo elevado com material de limpeza dentro dos planos de manutenção, além de desperdício de material, gerando excesso de resíduos no final de cada preventiva da frota de escavação elétrica e hidráulica de grande porte. ', N'Redução de custo', N'10015', N'01 - Imagens/01 - Antes/9772.jpeg', N'Custo elevado de insumos de limpeza nos planos preventivos das frotas de escavação elétrica e hidráulica de grande porte;
INSERT INTO #PVC VALUES (9773, N'81004462', N'81004462', N'Otimização de Estratégia de Troca de Cilindros WE1850-3', 1, N'Others/Outros', N'Identificado elevado custos de planos para troca de cilindros hidráulicos das carregadeiras Komatsu WE1850-3, onde os cilindros hidráulicos possuem estratégia de troca condicional.', N'Redução de custo e risco', N'10015', N'01 - Imagens/01 - Antes/9773.jpeg', N'Custo Projetado e elevado de troca de cilindros hidráulicos para o ano de 2026; Cilindro que são componentes de troca condicional sendo trocado por tempo, não atendendo a estratégia definida; Tempo de elevado de manutenções programadas, impactando na DF anual; Exposição de riscos de atividades de içamento de carga.
INSERT INTO #PVC VALUES (9774, N'517429', N'517429', N'Verificação da densidade aparente real da pilha secundária para melhoria da confiabilidade do cálculo de massa', NULL, N'Others/Outros', N'O cálculo da massa do material estocado na pilha secundária vinha sendo realizado utilizando uma densidade aparente fixa de projeto (2,0 t/m³), sem validação periódica em campo. Essa prática gerava incertezas nos controles de estoque, uma vez que os volumes são obtidos por levantamentos topográficos e podem não refletir a condição real do material.', N'Definição de teste prático e atualizado para determinação da densidade aparente real do material, considerando condições operacionais (granulometria, empilhamento e umidade).', N'10229', N'01 - Imagens/01 - Antes/9774.jpeg', N'O cálculo da massa do material estocado na pilha secundária vinha sendo realizado utilizando uma densidade aparente fixa de projeto (2,0 t/m³), sem validação periódica em campo.', N'01 - Imagens/02 - Depois/9774.jpeg', N'- Determinação de valores reais e atualizados de densidade aparente do material;
INSERT INTO #PVC VALUES (9775, N'517429', N'517429', N'Atualização do Modelo de Turno 3x3 no Sistema GPV', NULL, N'No Replication/Sem replicação', N'O sistema GPV estava configurado com o modelo de turno anterior, sem aderência ao formato 3x3, comprometendo o acompanhamento correto da produção por turno e a padronização dos relatórios de paradas. A permanência das classificações X e Y gerava risco de inconsistência de dados e análises operacionais imprecisas.', N'Garantir que o sistema GPV esteja totalmente aderente ao modelo de turno 3x3, assegurando precisão nas análises operacionais, padronização dos relatórios e confiabilidade das informações de produção e paradas.', N'10229', N'01 - Imagens/01 - Antes/9775.jpeg', N'O sistema GPV estava configurado com o modelo de turno, não aderente ao formato operacional 3x3. Os dados de produção não refletiam corretamente o turno vigente e os relatórios de eventos de paradas utilizavam as classificações X e Y, já obsoletas. Esse cenário gerava risco de inconsistência das informações, dificuldades de análise e possibilidade de decisões operacionais baseadas em dados imprecisos.', N'01 - Imagens/02 - Depois/9775.jpeg', N'Após a atualização estruturante do sistema GPV, o modelo de turno 3x3 passou a ser plenamente contemplado, os usuários podem acompanhar os dados de produção conforme o turno vigente, e os relatórios de eventos de paradas passaram a ser gerados exclusivamente pelas letras A, B, C e D. A mudança garantiu padronização, confiabilidade dos dados e maior precisão nas análises operacionais, reduzindo riscos e retrabalhos.', NULL, N'A meta inicial era adequar o sistema GPV ao modelo de turno 3x3, eliminando inconsistências no acompanhamento da produção por turno e na geração dos relatórios de paradas. Com a atualização implementada, o sistema passou a refletir corretamente o turno vigente e os relatórios foram padronizados para as letras A, B, C e D, resolvendo o problema identificado e reduzindo os riscos operacionais associados a dados imprecisos.A meta inicial era adequar o sistema GPV ao modelo de turno 3x3, eliminando inconsistências no acompanhamento da produção por turno e na geração dos relatórios de paradas. Com a atualização implementada, o sistema passou a refletir corretamente o turno vigente e os relatórios foram padronizados para as letras A, B, C e D, resolvendo o problema identificado e reduzindo os riscos operacionais associados a dados imprecisos.', N'Mudanças no modelo operacional, como a implantação de novos turnos, devem ser acompanhadas por atualizações sistêmicas tempestivas, garantindo alinhamento entre operação e sistemas. A padronização dos turnos e classificações no GPV reduz riscos de inconsistência de dados, elimina retrabalhos analíticos e aumenta a confiabilidade das informações utilizadas na tomada de decisão.', 0, NULL, N'evitar acidentes, quedas e retrabalhos junto ao processo de transporte em empilhadeiras transporte e armazenamento do cilindro.', '2026-04-01T00:00:00.000', '2026-04-30T21:37:50.000', N'517429', NULL, NULL);
INSERT INTO #PVC VALUES (9776, N'81050431', N'81050431', N'Suporte para impressora ', NULL, N'Others/Outros', N'Foi fabricador um suporte para impressora que ficava em cima da mesa', N'Economia ', N'10139', N'01 - Imagens/01 - Antes/9776.jpeg', N'Antes ficava em cima da mesa.', N'01 - Imagens/02 - Depois/9776.jpeg', N'Fabricado suporte e realizado organização ', NULL, N'Sim', N'Melhoria', 0, NULL, N'É UMA MELHORIA SIMPLES, MAIS NO GERAL, GANHO NA PRODUTIVIDADE, REDUÇÃO DE DESLOCAMENTO, MELHORIA NA ORGANIZAÇÃO, E AUMENTO NA SEGURANÇA.', '2026-04-11T00:00:00.000', '2026-04-30T21:49:18.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9777, N'517429', N'517429', N'KAIZEN – Atualização do Painel FMDS Diário – Via Úmida', NULL, N'No Replication/Sem replicação', N'A ausência dos indicadores críticos de desempenho metalúrgico, no painel reduzia a capacidade de monitoramento da performance metalúrgica, gerando risco de análises incompletas, atraso na identificação de desvios de processo e decisões operacionais baseadas em informações parciais.', N'Ampliar a visibilidade dos resultados operacionais e metalúrgicos da Via Úmida, permitindo acompanhamento diário mais completo e assertivo do desempenho do processo.', N'10229', N'01 - Imagens/01 - Antes/9777.jpeg', N'O painel do FMDS diário da Via Úmida não contemplava indicadores críticos de desempenho metalúrgico, como Recuperação Teórica e % de Cu no Concentrado, limitando a visibilidade dos resultados operacionais e dificultando o acompanhamento diário da eficiência do processo.', N'01 - Imagens/02 - Depois/9777.jpeg', N'Realizada a atualização do painel FMDS diário da Via Úmida, com a inclusão dos indicadores de Recuperação Teórica e % de Cu no Concentrado, ampliando o escopo de acompanhamento diário.
INSERT INTO #PVC VALUES (9778, N'81004893', N'81004893', N'Ranking de Eventos Operacionais Infraestrutura ', 1, N'Others/Outros', N'Inexistência de método estruturado para priorização e análise dos eventos operacionais de infraestrutura, dificultando a identificação de recorrências, atuação preventiva e direcionamento de capacitação operacional.', N'Implantar ranking estruturado dos eventos operacionais de infraestrutura para apoiar tomada de decisão, reduzir recorrência de eventos críticos e fortalecer a disciplina operacional.', N'10015', N'01 - Imagens/01 - Antes/9778.jpeg', N'Não havia sumarização da concentração dos eventos operacionais, tampouco acompanhamento da evolução mensal para avaliação de melhoria ou priorização. Também não existia visualização instantânea e consolidada dos resultados extraídos (extrato), dificultando a análise rápida e a tomada de decisão.', N'01 - Imagens/02 - Depois/9778.jpeg', N'Passou a existir a sumarização da concentração dos eventos operacionais, com visão consolidada e acompanhamento da evolução mensal, permitindo avaliar tendência de melhoria e apoiar a priorização das ações. Os resultados do extrato tornaram‑se disponíveis de forma instantânea e estruturada, viabilizando análises rápidas, direcionamento assertivo e tomada de decisão baseada em dados.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/3620e441-bc06-4389-9562-9ac5bb38ee12/75788be65837351da91c?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Maior visibilidade dos eventos operacionais críticos
INSERT INTO #PVC VALUES (9779, N'81022679', N'81022679', N'Kaizen – Melhoria de  Instalação Bucha MP1000', 1, N'Others/Outros', N'Aplicação de Bucha no Excêntrico do Britador MP1000
INSERT INTO #PVC VALUES (9780, N'536994', N'45161', N'INSTALAÇÃO CURVA DE 90° MANGUEIRA - PF1202', 1, N'Others/Outros', N'Devido a curva da mangueira ser muito  acentuada, estava danificado a mangueira todas as vezes na curva. Causas ocorridas pelo impedimento da passagem de fluidos, aumentando a pressão interna.
INSERT INTO #PVC VALUES (9781, N'536994', N'524893', N'MALETA DE COLETA DE FLUÍDOS', 2, N'Others/Outros', N'O acesso para coleta de óleo nos equipamentos era realizado com os frascos e bomba de coletas nas mãos, onde o índice de contaminações era constante, baixa eficiência dos 03 pontos de apoio ao acessar escada, podendo deixar cair, quebrar, perdendo material, além de grandes riscos de queda e acidentes graves com a perda de equilíbrio.
INSERT INTO #PVC VALUES (9782, N'536994', N'524893', N'PINTURA DA ÁREA DE MANUTENÇÃO - ESCAVAÇÃO ', 1, N'Others/Outros', N'A área de manutenção estava sem pintura, apresentava riscos de segurança, tornando o chão escorregadio, se sem sinalização apropriada, tornava o ambiente propicio ao acontecimento de acidentes e danos a equipamentos
INSERT INTO #PVC VALUES (9783, N'536994', N'45161', N'PINTURA DA PLATAFORMA - PERFURAÇÃO ', 1, N'Others/Outros', N'A área de manutenção estava sem pintura, apresentava riscos de segurança, tornando o chão escorregadio, se sem sinalização apropriada, tornava o ambiente propicio ao acontecimento de acidentes e danos a equipamentos
INSERT INTO #PVC VALUES (9784, N'536994', N'515054', N'CRIAÇÃO DE SUPORTE DO CILINDRO - 966', 1, N'Others/Outros', N'Cilindro de aplicação da articulação da 966 veio do fornecedor sem o suporte para transporte, facilitando riscos de acidentes por estarem soltos e serem manuseados em empilhadeiras, tais como: prensamento de mão e dedos no manuseio.
INSERT INTO #PVC VALUES (9785, N'81022558', N'81015148', N'CX-2305SA-01', NULL, N'Others/Outros', N'Linha de água geral da caixa de polpa da moagem sem tag de identificação.', N'Fácil identificação da válvula', N'10229', N'01 - Imagens/01 - Antes/9785.jpeg', N'Linha de válvula geral de água de lavagem da CX-2305SA-01 sem tag de identificação, dificultando sua localização e sua visualização, sendo necessário tempo e movimento para encontrar a mesma.', N'01 - Imagens/02 - Depois/9785.jpeg', N'Foi instalado placa de identificação para facilitar sua localização, evitando desperdício de tempo e movimento para sua visualização.', NULL, N'fácil visualização', N'fácil visualização', 0, NULL, N'preparar ocupantes e sua evacuação imediata, conforme as normas se segurança', '2026-04-30T00:00:00.000', '2026-05-01T00:44:54.000', N'81022558', NULL, NULL);
INSERT INTO #PVC VALUES (9786, N'81022558', N'81029881', N'TR-2313SA-01', NULL, N'Others/Outros', N'sensor de esticamento sem identificação', N'identificação', N'10229', N'01 - Imagens/01 - Antes/9786.jpeg', N'sensor de esticamento da TR-2313SA-01 sem identificação dificultando sua localização, gerando esforço de tempo e movimento.', N'01 - Imagens/02 - Depois/9786.jpeg', N'Foi instalado tag de identificação no local do sensor de correia esticada para facilitar sua visualização evitando esforço desnecessário e movimentos.', NULL, N'fácil visualização', N'fácil visualização', 0, NULL, NULL, '2026-04-19T00:00:00.000', '2026-05-01T00:57:45.000', N'81022558', NULL, NULL);
INSERT INTO #PVC VALUES (9787, N'81022558', N'81061119', N'DETECTOR DE RASGO', NULL, N'Others/Outros', N'local sem identificação', N'identificação', N'10229', N'01 - Imagens/01 - Antes/9787.jpeg', N'sensor de detector de rasgo da TR-2313SA-01 sem identificação dificultando sua localização, gerando esforço de tempo e movimento.', N'01 - Imagens/02 - Depois/9787.jpeg', N'Foi instalado tag de identificação no detector de rasgo da correia para facilitar sua visualização e assim evitar desperdício de tempo e movimento.', NULL, N'facilitado a identificação', N'facil identificação', 0, NULL, N'Após criação de suporte, objeto foi transportado para reforma, garantiu-lhe segurança do componente em transporte e a segurança das pessoas no manuseio de periféricos.
INSERT INTO #PVC VALUES (9788, N'536994', N'515054', N'CRIAÇÃO DE SUPORTE DE CILINDRO SUPORTE – PF1201', 1, N'Others/Outros', N'Cilindro eram mantido expostos e sem suporte adequado, o que dificultava seu transporte e manuseio, podendo facilitar riscos de acidentes por estarem soltos e serem manuseados em empilhadeiras.
INSERT INTO #PVC VALUES (9789, N'81046953', N'537728', N'INTLATAÇÃO DA CAIXA DE ELOS E GRAMPOS', 2, N'Others/Outros', N'NÃO HAVIA UMA PONTO DEFINIDO PARA ARMAZENAMENTO DE PEQUENOS COMPONENTES COMO: ELOS E GRAMPOS, ENTRE OUROS. PRÓXIMO AOS FILTROS. ESSA AUSÉNCIA DE ORGANIZAÇÃO LEVAVA OS DESLOCAMENTOS FRENQUENTES DOS COLABORADORES PARA BUSCAR MATERIAIS, ALÉM DE FAVORECER O ARMAZENAMENTO INADEQUADO EM SUPERFICIE IMPROVIZADAS.', N'DESLOCAMENTOS AS ARÉAS MAIS DISTANTES, AUMENTO DO TEMPO DE EXECUÇÃO DAS ATIVIDADES', N'10362', N'01 - Imagens/01 - Antes/9789.jpeg', N'NÃO HAVIA UM PONTO DEFINIDO PA O ARAMZENAMENTO DE PEQUENOS COMPONENTES COM: ELOS, GRAMPOS ENTRE OUTROS. PRÓXIMOS AOS FILTROS, ESSA AUSÉNCIA DE ORGANIZAÇÃO LEVAVA OS DESLOCAMENTOS FREQUENTES DOS COLABORADORES PARA BUSCAR MATERIAIS, ALÉM DE FAVORECER O ARMAZENAMENTO INADEQUADO EM SUPERFICIE IMPROVIZADOS.', N'01 - Imagens/02 - Depois/9789.jpeg', N'FOI INSTALADO UMA CAIXA / SUPORTE METÁLICO FIXADO NA PAREDE DO PISO INTERMÉDIARIO CRIANDO UM PONTO ESPECIFÍCO E PRÓXIMO AOS FILTROS PARA ACONDICIONAMENTO DESSES COMPONENTES.', NULL, N'SIM, MINIMIZANDO RISCOS DE QUEDA DE MATERIAIS E CONTRIBUINDO PARA UMA AMBIENTE FAVORENCENDO A EXECUÇÃO DAS ATIVIDADES COM MAIOR AGILIDADE E SEGURANÇA.', N'A MELHORIA TROUXE GANHO OPERACIONAAL E DE SEGURANÇA REDUZINDO O DESLOCAMNTO DESNECESSÁRIOS', 0, NULL, N'visibilidade e facilidade a identificação de obstáculos.
INSERT INTO #PVC VALUES (9790, N'1009297', N'1009297', N'Air line extension', 1, N'Others/Outros', N'Currently the air lance cannot reach up to the wharf conveyor level for cleaning purposes. we will extend the air lances foot print so we can clean on the wharf conveyor level', N'Extension of air line', N'0', N'01 - Imagens/01 - Antes/9790.jpeg', N'Currently the air lance cannot reach up to the wharf conveyor level for cleaning purposes. we will extend the air lances foot print so we can clean on the wharf conveyor level', N'01 - Imagens/02 - Depois/9790.jpeg', N'Air line has been run so we can now clean from wharf conveyor level', NULL, N'Problem was solved', N'Ergonomics', 0, NULL, N'Prevent falls when using scaffold ladder.', '2026-04-24T00:00:00.000', '2026-05-01T09:44:35.000', N'1009297', NULL, NULL);
INSERT INTO #PVC VALUES (9791, N'81046953', N'81055527', N'IMPLATAÇÃO DO PORTÃO DE ACESSO RESTRITO PISO INTERMÉDIARIO', 2, N'Others/Outros', N'A ARÉA PERMANECIA ABERTA, PERMINTIDO CIRCULAÇÃO LIVRE DE PESSOAS MESMO DURANTE INTRVENÇÕES. ISSO AUMENTAVA O RISCO DE EXPOSIÇÃO A EQUIPAMENTOS EM OPERAÇÃO, MOVIMENTAÇÃO DE PEÇAS E POSSIVEIS QUEDAS OU INTERFERÊNCIAS NA ATIVIDADE DE MANUTENÇÃO.', N'META MOSTRA A IMPORTÁNCIA DE CONTROLE AO ACESSO NO PISO INTERMÉDIARIO DO SETOR', N'10362', N'01 - Imagens/01 - Antes/9791.jpeg', N'A ARÉA PERMANECIA ABERTA, PERMINTIDO CIRCULAÇÃO LIVRE DE PESSOAS MESMO DURANTE INTERVENÇÕES. ISSO AUMENTAVA O RISCO DE EXPOSIÇÃO A EQUIPEMENTOS EM OPERAÇÃO, MOVIMENTAÇÃO DE PEÇAS E POSSIVEIS QUEDAS OU INTERFÊRENCIAS NA ATIVIDADES DE MANUTENÇÃO.', N'01 - Imagens/02 - Depois/9791.jpeg', N'FOI INSTALADO O PORTÃO COM SINALIZAÇÃO DE "ACESSO RESTRITO", SOMENTE PESSOAS AUTORIZADAS, CRIANDO UMA BARREIRA FÍSICA CLARA. ESSA AÇÃO TRAZ VÁRIOS GANHOS; SEGURANÇA REFORFADA, CONTROLE DE ACESSO, E ORGANIZAÇÃO DA ARÉA.', NULL, N'SIM, É UMA MELHORIA SIMPLES EM RELAÇÃO A CONDIÇÃO INICIAL MAIS GEROU, POREM GEROU IMPACTO POSITIVO NA SEGURANÇA, REDUZIDO RISCO E MELHORANDO CONDIÇÕES DE TRABALHO.', N'CONTRIBUI POR UM AMBIENTE MAIS SEGURO, PARA EXECUÇÃO DAS ATIVIDADES', 0, NULL, N'Segurança das pessoas e veículos ', '2026-03-18T00:00:00.000', '2026-05-01T10:04:19.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (9792, N'81046953', N'537728', N'instalação do armário tipo baia no piso superior do setor Filtragem', 3, N'Others/Outros', N'ANTES DA IMPLATAÇÃO OS MATERIAIS FICAVAM ARAMZENADOS DE FORMA DESORGANIZADA, PODEDO FICAR ESPALHADO OU EMPILHADOS DE MANEIRA INADEQUADA. ISSO DIFICULTAVA A LOCALIZAÇÃO DOS ITENS, AUMENTAVA O TEMPO E A BUSCA E ELEVAVA OS RISCOS DE ACIDENTES, COMO QUEDAS DE MATERIAIS. ALÉM DE COMPROMETER A CONSERVAÇÃO DOS MESMOS.', N'melhorar as condições de organização', N'10362', N'01 - Imagens/01 - Antes/9792.jpeg', N'ANTES DA IMPLATAÇÃO DO ARMÁRIO TIPO BAIA, OS MATERIAIS FIACAVAM ARMAZANADOS DE FORMA DESORGANIZADA, PODEDO FICAR ESPALHADOS OU EMPILHADOS DE MANEIRA INADEQUADA. ISSO DIFICULTAVA A LOCALIZAÇÃO DOS ITENS, AUMENTAVA O TEMPO E A BUSCA E ELEVAVA OS RISCOS DE ACIDENTES, COMO QUEDAS DE MATERIAIS, ALÉM DE COMPROMETER A CONSERVAÇÃO DOS MESMOS.', N'01 - Imagens/02 - Depois/9792.jpeg', N'APÓS A FABRICAÇÃO E INSTALAÇÃO DO ARMÁRIO TIPO BAIA, OS MATERIAIS PASSARAM A SER ORGANIZADOS EM COMPARTIMENTOS INDIVIDUAIS, FACILITANDO A IDENTIFICAÇÃO E O ACESSO. HOUVE MELHORA SIGNIFICATIVA NA ORGANIZAÇÃO DO AMBIENTE, REDUÇÃO DO TEMPO DE PROCURA, MELHOR APROVEITAMNETO DO ESPAÇO E AUMENTO DE SEGURANÇA, EVITANDO QUEDAS E DANOS AOS MATERIAIS. A SOLUÇÃO TAMBÉM CONTRIBUI PARA UM AMBIENTE DE TRABALHO MAIS LIMPO, PADRONIZADO E EFICIENTE.', NULL, N'HOUVE MELHORIA SIGNIFICATIVA NA ORGANIZAÇÃO, AGILIDADE NA LOCALIZAÇÃO DOS ITENS, REDUÇÃO DE ERROS NA UTILIZAÇÃO E AUMENTO DA SEGURANÇA NO AMBIENTE DE TRABALHO.', N'AGILIDADE NA PROCURA DOS INSUMOS, PERCA DE TEMPO', 0, NULL, N'Instalação de aterramento nas estruturas de ferro, na passarela e as chapas de base de serviço, promovendo segurança a todos no local.', '2026-02-12T00:00:00.000', '2026-05-01T10:53:46.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (9793, N'81033358', N'81033358', N'Wash Bay Grating Replacement', 2, N'Underground/Subterrâneo', N'The old wash bay grating in the 3370 wash bay was damaged with sections that bent, creating tripping hazards.', N'Safety Improvement', N'10238', N'01 - Imagens/01 - Antes/9793.jpeg', N'The old wash bay grating in the 3370 wash bay was damaged with sections that bent, creating tripping hazards.', N'01 - Imagens/02 - Depois/9793.jpeg', N'All the removable sections were replaced with new ones. Any tripping hazards were eliminated with the replacement.', NULL, N'The tripping hazards and potentials for sprains and strains due to the uneven walking surface of the old grating has been eliminated.', N'Regular grating inspections should be performed.', 0, NULL, N'Controle de acesso', '2026-04-30T00:00:00.000', '2026-05-01T13:58:43.000', N'81033358', NULL, NULL);
INSERT INTO #PVC VALUES (9794, N'81050579', N'81035749', N'Suporte de abraçadeiras ', 3, N'Others/Outros', N'o material em especifico não tinha local adequado para armazenamento na ferramentaria', N'organização do ambiente ', N'10144', N'01 - Imagens/01 - Antes/9794.jpeg', N'antes não havia um local adequado para armazenar as braçadeiras, assim deixando as mesmas e um local indevido ocasionando desorganização.', N'01 - Imagens/02 - Depois/9794.jpeg', N'após a identificação da desorganização do local, foi feito a padronização do ambiente organizando o material.', NULL, N'sim, foi feita a melhoria da organização', N'a organização e padronização dos materiais', 0, NULL, N' ganho na organização', '2026-04-30T00:00:00.000', '2026-05-01T15:36:16.000', N'81050579', NULL, NULL);
INSERT INTO #PVC VALUES (9795, N'482095', N'482095', N'AUMENTO CAPACIDADE TRANSPORTE RODOVIÁRIO DE COBRE', 1, N'No Replication/Sem replicação', N'SUBUTILIZAÇÃO DE CAPACIDADE DE TOLERÂNCIA LEGAL DAS CARRETAS NO TRASNPORTE DE COBRE. ', N'AUMENTAR EM 5% PESO BRUTO DAS CARRETAS', N'#N/A', N'01 - Imagens/01 - Antes/9795.jpeg', N'Operava com peso bruto das carretas limitado a 58.500kg por não ser contemplado no acordo sindical dos motoristas, subutilizando a capacidade legal da carreta conforme a 
INSERT INTO #PVC VALUES (9796, N'498359', N'478939', N'SUPORTE PARA KIT DE EMERGENCIA', NULL, N'Others/Outros', N'KIT DE EMERGENCIA FICAVA EXPOSTO  NO CHAO, SEM LOCAL ADEQUADO.', N'5S', N'10362', N'01 - Imagens/01 - Antes/9796.jpeg', N'KIT DE EMERGENCIA FICAVA EXPOSTO  NO CHAO, SEM LOCAL ADEQUADO.', N'01 - Imagens/02 - Depois/9796.jpeg', N'FOI FABRICADO E INSTALADO UM SUPORTE PARA O KIT DE EMERGENCIA COM LOCAL ADEQUADO E MELHORAR ORGANIZAÇÃO DO AMBIENTE.', NULL, N'META ATINGIDA', N'MELHORAR AMBIENTE DE TRABALHO', 0, NULL, NULL, '2026-05-01T00:00:00.000', '2026-05-01T17:14:01.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (9797, N'81022150', N'81022150', N'Warehouse - Standardization and Improvement of Peer Training ProgramStandardization and Improvement of Peer Training Program', 1, N'Others/Outros', N'Peer training and onboarding in the warehouse were inconsistent and largely dependent on individual trainers, with no standardized reference or setup process. This resulted in variability in how key processes were taught, longer onboarding times for new employees, and increased risk of missed steps when assigning employees to different areas.', N'To standardize and strengthen the peer training program by providing clear, consistent training materials and onboarding checklists, ensuring all new and transitioning warehouse employees are set up correctly, trained consistently, and able to perform key processes safely and effectively across all areas.', N'10153', N'01 - Imagens/01 - Antes/9797.jpeg', N'Previously, peer training and onboarding were informal and inconsistent across warehouse areas, relying heavily on individual trainers’ experience rather than standardized guidance. There was no centralized reference material, resulting in variation in how key processes were taught and understood, longer learning curves for new and transitioning employees, and an increased risk of missed setup steps such as system access, equipment, safety requirements, and process expectations, making the approach difficult to sustain with turnover or operational changes.', N'01 - Imagens/02 - Depois/9797.jpeg', N'After implementation, peer training and onboarding became standardized and consistent across all warehouse areas through the use of a centralized training binder and area-specific checklists. Trainers and supervisors now follow clear guidelines for key processes, ensuring employees are set up correctly and receive the same foundational training regardless of trainer, shift, or location. This improved onboarding efficiency, reduced missed steps, increased employee confidence, and created a more sustainable training model that supports continuity, turnover, and future growth.', NULL, N'Yes. 
INSERT INTO #PVC VALUES (9798, N'536994', N'524893', N'IMPLANTAÇÃO DE SINALIZAÇÃO -  CONTAINER PATIO MIRANTE', 1, N'Others/Outros', N'Não existia sinalização de rota de fuga, o que em caso emergencial, poderia atrapalhar a evacuação de pessoas até o ponto de encontro, causando riscos a segurança de todos.
INSERT INTO #PVC VALUES (9799, N'1009559', N'1009559', N'Repurposing Heat Treated Pallets', 1, N'Refining/Refino', N'In 2026 EW will be adding thousands of bags of nickel sulphate to the process stream. These have been arriving on brand new, heat treated pallets. While they will not work for packaging finished product nickel, they can be used for the bracing and support when packaging cobalt drums, simultaneously reducing the need to use nickel pallets, while reducing the cost/necessity to dispose of these pallets. ', N'Cost Savings for inputs as well as disposal', N'0', N'01 - Imagens/01 - Antes/9799.jpeg', N'Before the pallets need to be removed and disposed of.', N'01 - Imagens/02 - Depois/9799.jpeg', N'These pallets are sturdy enough to be reused inside of outgoing finished cobalt containers, helping to secure the load, and reducing the amount of nickel pallets used in this process, saving cost.', NULL, N'Yes, the pallets are being re-used instead of disposed of, and reducing future costs.', N'Reduce, re-use, recycle', 10000, 3, NULL, '2026-05-01T00:00:00.000', '2026-05-02T00:57:38.000', N'1009559', NULL, NULL);
INSERT INTO #PVC VALUES (9800, N'536994', N'515054', N'CRIAÇÃO DE SUPORTE FIXADO DO MOTOR 966', 1, N'Others/Outros', N'O motor foi retirado da 966, e não tinha lugar ou suporte apropriado,  estava sobre dormentes, correndo risco de cair e vim danificar os componentes, ou até mesmo causar acidentes e vir a machucar  pessoas.
INSERT INTO #PVC VALUES (9801, N'536994', N'81009606', N'ILUMINAÇÃO DA CABINE - CM4028 PRANCHA E01', NULL, N'Others/Outros', N'Não existia iluminação interna na cabine do operador, impossibilitando a  visibilidade dos botões de acionamento do caminhão, e tropeço dentro da cabine por não visualizar a parte interna.
INSERT INTO #PVC VALUES (9802, N'536994', N'45161', N'INSTALAÇÃO REFLETORES - MANUTENÇÃO PERFURAÇÃO', NULL, N'Others/Outros', N'O lado externo do galpão da área de manutenção  de perfuração não possui iluminação adequada, o que pode ser um ponto positivo para acidentes, além de facilitar que animais peçonhentos se escondam e ataquem pessoas.
INSERT INTO #PVC VALUES (9803, N'1014906', N'1014906', N'Filter Press Deck Scaffold Guarding', 2, N'No Replication/Sem replicação', N'The ladder used to access the scaffold deck between the WLN Filter Press Decks did not have any guarding around it to help prevent you from falling. ', N'Prevent Falls', N'0', N'01 - Imagens/01 - Antes/9803.jpeg', N'No scaffold guarding to prevent falls when accessing the ladder of the scaffold deck on the WLN Filter Press Deck.', N'01 - Imagens/02 - Depois/9803.jpeg', N'Scaffold Guarding installed to prevent falls when accessing the ladder of the scaffold deck on the WLN Filter Press Deck.', NULL, N'Yes', N'Adequate Guarding ', 0, NULL, N'Fornecimento contínuo de ar comprimido seco e livre de umidade.', '2026-05-01T00:00:00.000', '2026-05-02T08:05:19.000', N'1014906', NULL, NULL);
INSERT INTO #PVC VALUES (9804, N'544624', N'544624', N'Estacionamento Padrão', 2, N'No Replication/Sem replicação', N'Estacionamento sem os batentes e calços dos pneus ', N'Garantir a segurança dos veículos e pessoas', N'10054', N'01 - Imagens/01 - Antes/9804.jpeg', N'Estacionamento em frente a baia de resíduos da moagem sem a presença de calços e batentes e sem a demarcação do local seguro para estacionar. ', N'01 - Imagens/02 - Depois/9804.jpeg', N'Realizado a instação dos batentes e calços, permitindo o estacionamento seguro dos veículos. 
INSERT INTO #PVC VALUES (9805, N'536994', N'545523', N'INSTALAÇÃO DE ATERRAMENTO – PASSARELA E AS CHAPAS DE BASE DE SERVIÇO', 1, N'Others/Outros', N'Quando não há aterramento adequado, a eletricidade pode se acumular em superfícies metálicas. Isso aumenta o risco de choques elétricos, que podem causar lesões graves ou até fatais. Dispositivos de proteção como disjuntores podem não funcionar corretamente, comprometendo a segurança da instalação.
INSERT INTO #PVC VALUES (9806, N'544624', N'544624', N'Portão de Acesso', 3, N'No Replication/Sem replicação', N'Acesso à bomba de aspersão sem portão', N'Garantir o controle de acesso à bomba', N'10054', N'01 - Imagens/01 - Antes/9806.jpeg', N'Escada de acesso à bomba de aspersão da pilha sem a presença  de portão para controle de acesso. ', N'01 - Imagens/02 - Depois/9806.jpeg', N'Realizado fabricado portão para controlar o acesso de pessoas de forma inadvertida na área de acionamento da bomba de aspersão da pilha.  ', NULL, N'Meta alcançada. ', N'Priorizar a segurança das pessoas ', 0, NULL, N'Liberação total da rota de fuga;
INSERT INTO #PVC VALUES (9807, N'699785', N'515044', N'SUPORTE PARA CAPACETE DE SEGURANÇA', 3, N'Others/Outros', N'NAO TINHA LOCAL PARA ACOMODAR OS CAPACETES DE SEGURANÇAS ', N'ORGANIZAÇAO', N'10144', N'01 - Imagens/01 - Antes/9807.jpeg', N'NAO TINHA LOCAL PARA ACOMODAR OS CAPACETES DE SEGURANÇAS ', N'01 - Imagens/02 - Depois/9807.jpeg', N'CONFECCIONADO UM SUPORTE PARA CAPACETE DE SEGURANÇA PROXIMO AOS BANHEIROS', NULL, N'SIM! ganho na organização', N'conformidade com 5s', 0, NULL, N'Redução do carreamento de finos para a via;
INSERT INTO #PVC VALUES (9808, N'81056249', N'81056249', N'Evolução do BI de Desvios do CCP para apoio a tomada de decisão', 1, N'Projects/Projetos', N'O BI de desvios do CCP apresentava informações limitadas e baixo nível de detalhamento, restringindo a análise dos atrasos, das causas e dos impactos das paradas. Essa limitação reduzia a efetividade do acompanhamento operacional e o suporte à tomada de decisão da liderança.', N'Ampliar a visibilidade e o detalhamento dos desvios das paradas/ Melhorar a análise, o controle e o suporte à tomada de decisão da liderança ', N'10358', N'01 - Imagens/01 - Antes/9808.jpeg', N'O acompanhamento dos desvios das paradas no CCP era realizado por meio de um BI básico, composto por apenas três dashboards principais: desvios por área, ativos mais impactados e causas de desvios, todos limitados à visualização em horas de atraso.
INSERT INTO #PVC VALUES (9809, N'1014906', N'1014906', N'WLN Filter Feed Pump Seal Water Green Lock ', 1, N'No Replication/Sem replicação', N'The WLN Filter Feed 310-PSE-015 has been upgraded to an Automatic Lubricating Mechanical Seal and no longer requires seal water. Multiple times now during pre-starts the Seal Water Valve VMB 2008 has been opened allowing seal water to go to the floor for extended periods of time. This adds water to the process needlessly via sumps and needs processed back out.', N'Reduce Processing Costs', N'0', N'01 - Imagens/01 - Antes/9809.jpeg', N'Seal water flowing to the floor and thus into the process via sumps. This seal water is no longer required for this pump due to an upgraded automatic lubricating mechanical seal.', N'01 - Imagens/02 - Depois/9809.jpeg', N'Seal Water Valve VMB-2008 green locked closed and tagged. ', NULL, N'Stopped seal water from entering the process needlessly.', N'Make sure the line up makes sense.', 1000, 3, N'Fácil visualização', '2026-05-01T00:00:00.000', '2026-05-02T15:50:47.000', N'1014906', NULL, NULL);
INSERT INTO #PVC VALUES (9810, N'1010008', N'81013122', N'PEN Sample Cabinet Organization', NULL, N'Refining/Refino', N'Old sample bottles are hard for the lab to distinguish between when they are worn.  Fresh bottles with clear labels make samples easier for techs and the lab personnel', N'Clean sample bottles to help Lab', N'0', N'01 - Imagens/01 - Antes/9810.jpeg', N'Worn sample bottles are hard to read and get brittle and break easily. ', N'01 - Imagens/02 - Depois/9810.jpeg', N'Replacing old worn sample bottles with new and labeled bottles make samples easier to distinguish between for lab personell and potentially cut down on resampling.', NULL, N'Problem resolved with new labelled bottles. ', N'routinely change out old bottles when worn out,', 0, NULL, N'facil identificaçao da bacia de contençao de oleo ', '2026-05-01T00:00:00.000', '2026-05-02T16:25:49.000', N'1010008', NULL, NULL);
INSERT INTO #PVC VALUES (9811, N'512018', N'512018', N'Dispositivo para troca de borda de Retro escavadeira', 2, N'Projects/Projetos', N'Atualmente na atividade de troca de borda da retro escavadeira, não há uma ferramenta de apoio para facilitar a tarefa, sendo está feita com o uso de alavancas, gerando desgaste físico, ergonômico e excesso de trabalho.', N'Redução de cenário de risco', N'10015', N'01 - Imagens/01 - Antes/9811.jpeg', N'Atualmente na atividade de troca de borda das retro escavadeiras, não existe uma ferramenta de apoio para facilitar a tarefa, sendo está feita com o uso de alavancas, gerando desgaste físico, ergonômico e excesso de trabalho.', N'01 - Imagens/02 - Depois/9811.jpeg', N'Foi desenvolvido um projeto de um dispositivo que facilita essa atividade, onde a chapa da borda será colocada com o auxílio de uma girafa, deixando-a na inclinação de 23º, esse dispositivo será usando com o auxilio e um carrinho de condução de ferramentas existente na oficina.
INSERT INTO #PVC VALUES (9812, N'81046149', N'81040359', N' Placa identificação.', 1, N'Others/Outros', N'Reservatório de óleo do sistema de lubrificação do britador primário,  sem identificação.
INSERT INTO #PVC VALUES (9813, N'81046149', N'81040359', N'Reservatório sem indentificação', 1, N'Others/Outros', N'Uma placa de identificação de reservatório de nível de óleo é um item essencial para controle operacional, manutenção e segurança de equipamentos industriais. Ela serve para indicar claramente informações importantes sobre o reservatório de óleo (hidráulico, lubrificação', N'Identificação de nível de óleo do reservatório  ', N'10362', N'01 - Imagens/01 - Antes/9813.jpeg', N'Sem indicação de nível mínimo e máximo, o equipamento pode operar:
INSERT INTO #PVC VALUES (9814, N'81046149', N'81046149', N'Grade de piso segura ', 2, N'Others/Outros', N'Foi identificado que a grade de piso apresenta vão aberto, comprometendo a integridade da superfície de circulação na área operacional. Essa condição expõe os colaboradores ao risco de queda, torção ou aprisionamento de membros, podendo resultar em acidentes.', N'Garante segurança de todos, manter ambiente de trabalho mas seguro.', N'10362', N'01 - Imagens/01 - Antes/9814.jpeg', N'Foi identificado que a grade de piso apresenta vão aberto, comprometendo a integridade da superfície de circulação na área operacional. Essa condição expõe os colaboradores ao risco de queda, torção ou aprisionamento de membros, podendo resultar em acidentes.', N'01 - Imagens/02 - Depois/9814.jpeg', N'Foi realizada a montagem/adequação da grade de piso, eliminando condições inseguras existentes no ambiente de trabalho.
INSERT INTO #PVC VALUES (9815, N'502854', N'502854', N'Padronização da area de componentes', 3, N'Others/Outros', N'antes não havia local designado para armazenar os componentes de rodas.', N'Padronizar, identificar ', N'10140', N'01 - Imagens/01 - Antes/9815.jpeg', N'não havia área designada para alocar os componentes de rodas, deixando a área com componentes em vários sem identificação.', N'01 - Imagens/02 - Depois/9815.jpeg', N'colocado componentes em suporte e identificado conforme cada frota, foi demarcado piso adequando na maturidade 3 e facilitando a localização,', NULL, N'sim', N'organização na area', 0, NULL, N'Padronização da forma de estacionamento;
INSERT INTO #PVC VALUES (9816, N'81006946', N'81006946', N'Filtro secador na linha de lubrificação', 1, N'No Replication/Sem replicação', N'alta quantidade de umidade na graxa.', N'zerar umidade', N'10139', N'01 - Imagens/01 - Antes/9816.jpeg', N'Antes, a linha de ar comprimido não possuía um filtro secador, o que permitia a presença de umidade no sistema. Essa umidade era transportada junto com o ar até os pontos de lubrificação e, durante as atividades de manutenção, acabava sendo introduzida nos componentes. Como consequência, havia risco de contaminação do lubrificante, corrosão das peças e redução da eficiência e vida útil dos equipamentos.', N'01 - Imagens/02 - Depois/9816.jpeg', N'Após a instalação do secador na linha de ar comprimido, houve eliminação da umidade do sistema, garantindo ar mais limpo e seco. Com isso, reduziu-se a contaminação nos pontos de lubrificação, diminuindo riscos de corrosão e desgaste prematuro dos componentes. Como resultado, houve aumento da confiabilidade dos equipamentos, melhoria na qualidade das manutenções e maior vida útil dos sistemas.', NULL, N'sim! se seguirmos as orientações corretas de lubrificação, iremos obter ótimos resultados', N'A umidade na linha é uma fonte crítica de contaminação, especialmente em pontos de lubrificação.', 0, NULL, N'Melhoria significativa da visibilidade no acesso;
INSERT INTO #PVC VALUES (9817, N'36805', N'81006515', N'Implemento para Limpeza Completa no Suporte da Lâmina da Motoniveladora', 2, N'Others/Outros', N'Acúmulo recorrente de material no suporte da lâmina das motoniveladores, gerando paradas não programadas, desgaste prematuro, maior esforço operacional e riscos de segurança para equipe de manutenção.', N'Eliminar o acúmulo de material no suporte da lâmina, reduzir intervenções manuais e aumentar a confiabilidade, segurança e disponibilidade do equipamento.', N'10090', N'01 - Imagens/01 - Antes/9817.jpeg', N'Acúmulo constante de material no suporte da lâmina da Motoniveladora; Riscos durante a Intervenção manual dos mecânicos da manutenção, com risco de segurança.', N'01 - Imagens/02 - Depois/9817.jpeg', N' Instalação de implemento para fazer limpeza contínua durante a operação, eliminando a causa do acúmulo de sujidade das lâminas das motoniveladoras de forma manual pelos operadores.', NULL, N'Sim, meta foi atingida, com eliminação da causa do problema, aumento da confiabilidade operacional e sustentação dos ganhos obtidos pelo Kaizen.', N'Soluções simples e preventivas aumentam a confiabilidade, reduzem custos e melhoram a segurança quando aplicadas diretamente na causa do problema.', 0, NULL, N'Melhoria das condições de acesso à fossa séptica;
INSERT INTO #PVC VALUES (9818, N'36805', N'461327', N'Implantação de sistema de drenagem para coleta da água do ar‑condicionado em escavadeira teleoperada', 1, N'Others/Outros', N'A água proveniente dos drenos do ar‑condicionado era descartada diariamente no interior do equipamento, ocasionando desgaste prematuro de componentes, processos de oxidação de peças e risco à confiabilidade operacional da escavadeira teleoperada.', N'Eliminar o descarte inadequado da água do ar‑condicionado no interior do equipamento, prevenindo desgaste e oxidação de componentes e aumentando a confiabilidade operacional.', N'10090', N'01 - Imagens/01 - Antes/9818.jpeg', N'A água condensada era descartada diretamente no interior da escavadeira, sem controle ou direcionamento adequado.', N'01 - Imagens/02 - Depois/9818.jpeg', N'Implantação de sistema de drenagem para direcionamento e coleta da água, evitando contato com componentes e peças do equipamento.', NULL, N'A solução implementada atendeu plenamente à meta proposta, eliminando a causa do desgaste e da oxidação relacionados ao descarte de água do ar‑condicionado, contribuindo diretamente para a confiabilidade e preservação do equipamento.', N'A correta gestão de pequenos pontos de falha pode evitar danos significativos aos equipamentos, aumentar a vida útil dos componentes e reduzir custos de manutenção.', 0, NULL, N'Redução significativa da velocidade dos veículos;
INSERT INTO #PVC VALUES (9819, N'36805', N'501108', N'Instalação de ganchos para armazenamento adequado de bolsas e mochilas no trailer da EC09', 2, N'Others/Outros', N'Falta de local adequado para as mochilas dos colaboradores eram deixadas no piso do trailer da EC09, ocasionando obstrução da rota de fuga, risco de tropeço e queda ao mesmo nível e dificuldades na evacuação em situações de emergência, configurando risco à segurança e desorganização do ambiente.', N'Eliminar a obstrução das rotas de fuga, reduzir riscos de acidentes e melhorar a organização do ambiente do trailler da EC09', N'10090', N'01 - Imagens/01 - Antes/9819.jpeg', N'Bolsas e mochilas apoiadas diretamente no piso do trailer, sem padronização e com risco à segurança.  Situação gerava obstrução de rota de fuga, risco de tropeço, queda de mesmo nível e dificultava a evacuação em emergência.', N'01 - Imagens/02 - Depois/9819.jpeg', N'Instalação de ganchos no interior do trailer, permitindo o armazenamento suspenso e organizado dos pertences dos colaboradores.', NULL, N'A meta foi plenamente alcançada, com a eliminação da obstrução da rota de fuga e dos riscos associados ao armazenamento inadequado, promovendo um ambiente mais seguro, organizado e alinhado às boas práticas de segurança e 5S.', N'Soluções simples e de baixo custo podem reduzir riscos críticos de segurança, melhorar a organização do ambiente e fortalecer a prática do 5S.', 0, NULL, N'Área do sump liberada para operação e drenagem;
INSERT INTO #PVC VALUES (9820, N'36805', N'536238', N'Implantação de Caixa de Contenção de Finos no acesso próximo à Portaria R2', 1, N'Others/Outros', N'No acesso próximo à Portaria R2 havia acúmulo e arraste de finos para a via, especialmente em períodos de chuva, ocasionando condições inseguras de tráfego, aumento de material particulado, necessidade frequente de manutenção corretiva e risco de impactos ambientais.', N'Conter os finos transportados pela água e pelo tráfego de veículos, melhorar as condições de segurança no acesso da Portaria R2 e reduzir a necessidade de intervenções corretivas na via', N'10090', N'01 - Imagens/01 - Antes/9820.jpeg', N'Os finos eram carreados para a via sem qualquer sistema de contenção, gerando acúmulo de material e degradação do acesso.', N'01 - Imagens/02 - Depois/9820.jpeg', N'Implantação de uma caixa de contenção de finos, permitindo a retenção do material sólido e evitando seu arraste para a via de circulação.
INSERT INTO #PVC VALUES (9821, N'544516', N'544516', N'Entrou no túnel, protege o Pulmão!', 2, N'No Replication/Sem replicação', N'Dificuldade de acesso às máscaras de proteção para entrada no túnel da 2202-TC-01 durante a rotina operacional.', N'Proteção contra particulado / saúde e segurança.', N'10054', N'01 - Imagens/01 - Antes/9821.jpeg', N'O acesso ao túnel da 2202 TC 01 ocorre rotineiramente para execução de atividades operacionais e inspeções, em um ambiente com presença significativa de material particulado em suspensão. Apesar da necessidade e obrigatoriedade do uso de máscaras de proteção respiratória, não havia um ponto de disponibilização adequado e de fácil acesso próximo à entrada do túnel.', N'01 - Imagens/02 - Depois/9821.jpeg', N'Foi instalada uma caixa de armazenamento de máscaras de proteção respiratória em local estratégico, na entrada do túnel da 2202 TC 01, garantindo fácil acesso aos colaboradores antes da realização das atividades. A caixa foi desenvolvida com proteção em acrílico, permitindo a visualização do conteúdo e protegendo as máscaras contra contaminação. Além disso, foi aplicada uma identificação visual clara e atrativa, incentivando o uso do EPI de forma imediata e intuitiva.', NULL, N'Inicialmente, foi identificada a dificuldade de acesso às máscaras de proteção respiratória para entrada no túnel da 2202 TC 01 durante a rotina operacional, o que impactava diretamente na adesão ao uso do EPI e aumentava o risco de exposição ao particulado.
INSERT INTO #PVC VALUES (9822, N'699785', N'543200', N'Identificação adequada para o lava olhos', 2, N'Others/Outros', N'sem identificação adequada para acompanhamento de troca de agua do reservatório do lava olhos ', N'facilidade no controle de troca', N'10144', N'01 - Imagens/01 - Antes/9822.jpeg', N'Identificaçao inadequada para o controle de troca de agua do reservatorio', N'01 - Imagens/02 - Depois/9822.jpeg', N'substituido identificação facil visualização e controle de troca de agua do reservatorio do lava olhos', NULL, N'sim!', N'facil visualizaçao', 0, NULL, N'Melhoria da segurança no deslocamento de pessoas e ferramentas;
INSERT INTO #PVC VALUES (9823, N'699785', N'699694', N'Identificação da bacia de contenção de óleos', 3, N'Others/Outros', N'Sem identificação da bacia de contenção de óleos', N'Identificaçao', N'10144', N'01 - Imagens/01 - Antes/9823.jpeg', N'sem identificação da bacia de contenção de óleos', N'01 - Imagens/02 - Depois/9823.jpeg', N'Identificação da bacia de contenção de óleos', NULL, N'sim! bacia de contenção de óleos sem identificaçao ', N'facil visualizaçao', 0, NULL, N'Implantação de caminho seguro no pátio;
INSERT INTO #PVC VALUES (9824, N'81034922', N'81009653', N'Relação de pendencias - Retorno de planta', 1, N'Others/Outros', N'Havia uma dificuldade de consolidação das pendencias de elétrica e instrumentação dos equipamentos para sanar e permitir o retorno da planta nas PGU''s.', N'Consolidar as informações com plano de ação para garantir o retorno da planta.', N'10081', N'01 - Imagens/01 - Antes/9824.jpeg', N'Não havia um controle consolidado das pendencias de elétrica e instrumentação dos equipamentos para sanar e permitir o retorno da planta nas PGU''s.', N'01 - Imagens/02 - Depois/9824.jpeg', N'Foi criado um controle consolidado com responsáveis e prazos que foi levado nas reuniões diárias de acompanhamento, o que trouxe clareza no que estava pendente para o retorno da planta e evitou o acumulo de pendencia e sobrecarga das equipes no retorno da planta pós-PGU.', NULL, N'Foi criado um controle consolidado com responsáveis e prazos que foi levado nas reuniões diárias de acompanhamento, o que trouxe clareza no que estava pendente para o retorno da planta e evitou o acumulo de pendencia e sobrecarga das equipes no retorno da planta pós-PGU.', N'Controle consolidade', 0, NULL, N'Eliminação das quedas da passarela durante o transporte;
INSERT INTO #PVC VALUES (9825, N'81046574', N'81046574', N'GESTÃO DE MATERIAIS CRÍTICOS E ESTRATÉGICOS', 1, N'Others/Outros', N'DURANTE O PRIMEIRO TRIMETRE DE 2026 HOUVE CRISES RELACIONADAS A AUSÊNCIA DE MATERIAIS CRÍTICOS, ESTRATÉGICOS E DE GARANTIA OPERACIONAL NA USINA DO SOSSEGO, A FIM DE CRIAR UM CONTROLE E GERENCIALMENTE DESSE RISCO FOI DESENSOLVIDO UM RELATORIO DE FUP', N'REALIZAR RELATÓRIO GERENCIAL QUE APRESENTE A SAÚDE DO ESTOQUE PARA ATENDIMENTO A USINA DO SOSSEGO', N'10081', N'01 - Imagens/01 - Antes/9825.jpeg', N'Não havia', N'01 - Imagens/02 - Depois/9825.jpeg', N'FOI CRIADO O RELATÓRIO COM ENVIO SEMANAL TRAZENDO A VISÃO DO ESTOQUE DE SOSSEGO E GERANDO MAIOR CONTROLE E GESTÃO DE RISCO', NULL, N'FOI ALCANÇADO O FAROL DE GESTÃO ', N'CONTROLE DE RISCO', 0, NULL, N'Eliminação do acúmulo de água no acesso;
INSERT INTO #PVC VALUES (9826, N'81034922', N'81009653', N'Checklist de Teste e comissionamento de equipamentos', 1, N'Others/Outros', N'No retorno da Usina, pós-parada, havia uma dificuldade de saber o que deveria ser testado e comissionado para garantir uma boa performance no retorno da planta.', N'Criar checklist de itens a serem testados / comissionados para o retorno da usina', N'10081', N'01 - Imagens/01 - Antes/9826.jpeg', N'Não havia um checklist de itens do que deveria ser testado e comissionado para garantir uma boa performance no retorno da planta.', N'01 - Imagens/02 - Depois/9826.jpeg', N'Foi criado um checklist de itens de verificação a serem testados com responsáveis para garantir uma boa performance no retorno da usina. O controle foi compartilhado com o time de operação, que encabeçou sem cumprimento pós PGU de abril.', NULL, N'Conseguimos estruturar de formar simples os itens que devem ser checados no retorno da usina, garantindo a boa performance no retorno da planta.', N'Criação de checklist de itens de verificação.', 0, NULL, N'Organização do estacionamento de veículos leves;
INSERT INTO #PVC VALUES (9827, N'81034922', N'81046574', N'Colunas de variação de horas - Atividades Críticas PGU', 1, N'Others/Outros', N'No acompanhamento das atividades críticas da PGU, havia uma dificuldade de entendimento se diariamente estávamos tendo variações positivas ou negativas de horas no andamento das atividades.', N'Ter informação clara e precisa da variação de horas no andamento das atividades críticas', N'10081', N'01 - Imagens/01 - Antes/9827.jpeg', N'Não havia uma forma de apresentar a informação clara e objetiva, e para tê-la, tinha a necessidade de ir na apresentação do dia anterior e comparar com do dia atual para ter a informação da variação.', N'01 - Imagens/02 - Depois/9827.jpeg', N'Com a criação das colunas de variação, garantimos essa informação no controle de avanço das atividades críticas, mantendo o histórico de variação por dia.', NULL, N'Com a criação das colunas no controle atingimos o objetivo proposto.', N'Criação de colunas de variações, garantindo informação rápida e precisa.', 0, NULL, N'Irrigação regular e eficiente das plantas;
INSERT INTO #PVC VALUES (9828, N'36805', N'81017082', N'Implantação de sinalização para estacionamento em marcha à ré no estacionamento da planta da Geoterra', NULL, N'Others/Outros', N'Foi identificada, no local de estacionamento da planta da Geoterra, a falta de informação sobre estacionamento em marcha à ré, o que pode gerar riscos à segurança durante manobras, dificuldades na saída das vagas e aumento do potencial de incidentes.', N'Orientar corretamente os condutores quanto ao estacionamento em marcha à ré, aumentando a segurança no estacionamento, melhorando a padronização da manobra e reduzindo riscos de incidentes e colisões.', N'10090', N'01 - Imagens/01 - Antes/9828.jpeg', N'Falta de informação orientativa, podendo contribuir para os veículos estacionarem de forma não padronizada, inclusive de frente.', N'01 - Imagens/02 - Depois/9828.jpeg', N'Instalação de placa de sinalização orientando o estacionamento obrigatório em marcha à ré, garantindo padronização e maior segurança na movimentação dos veículos.', NULL, N'A implantação da sinalização atendeu plenamente à meta inicial, eliminando a ausência de orientação aos condutores e contribuindo para um estacionamento mais seguro, organizado e alinhado às boas práticas de segurança.
INSERT INTO #PVC VALUES (9829, N'36805', N'81017082', N'Melhoria da sinalização e iluminação do estacionamento da planta da Geoterra', 2, N'Others/Outros', N'Identificada, no local de estacionamento da planta da Geoterra, baixa visibilidade no acesso, o que aumentava o risco de manobras inseguras, incidentes e dificultava a entrada e saída de veículos, principalmente em períodos de pouca luminosidade.', N'Melhorar a visibilidade do acesso e aumentar a segurança na circulação de veículos no estacionamento da planta.', N'10090', N'01 - Imagens/01 - Antes/9829.jpeg', N'Iluminação insuficiente no acesso, resultando em manobras não padronizadas e risco à segurança no estacionamento da planta de britagem', N'01 - Imagens/02 - Depois/9829.jpeg', N'Redundância da iluminação com instalação de mais uma de torre de iluminação solar, garantindo melhor visibilidade e orientação segura aos condutores.
INSERT INTO #PVC VALUES (9830, N'36805', N'516001', N'Implantação de acesso adequado à fossa séptica no pátio de Drenagem', 2, N'Others/Outros', N'Não havia acesso específico à fossa séptica no pátio de Drenagem, o que dificultava a entrada da equipe e do caminhão responsável pela limpeza, além de expor os colaboradores a riscos de segurança e aumentar o tempo de execução da atividade.
INSERT INTO #PVC VALUES (9831, N'36805', N'516001', N'Implantação de redutores de velocidade na área da rodoviária', 2, N'Others/Outros', N'Foi identificado tráfego de veículos em velocidade incompatível com a área da rodoviária, caracterizada por circulação intensa de pedestres e veículos leves, aumentando o risco de acidentes, atropelamentos e incidentes operacionais.', N'Reduzir a velocidade dos veículos na área da rodoviária, aumentando a segurança de pedestres e condutores e promovendo um ambiente mais controlado e seguro.', N'10090', N'01 - Imagens/01 - Antes/9831.jpeg', N' Ausência de dispositivos físicos de controle de velocidade, resultando em tráfego acima do recomendado para a área.', N'01 - Imagens/02 - Depois/9831.jpeg', N'Implantação de redutores de velocidade, forçando a redução da velocidade dos veículos e padronizando a condução segura no local.', NULL, N'A implantação dos redutores de velocidade atendeu plenamente à meta estabelecida, eliminando o tráfego em velocidade inadequada e tornando a área da rodoviária mais segura e alinhada às boas práticas de segurança viária.', N'Controles físicos de velocidade são medidas eficazes, simples e de alto impacto para prevenção de riscos, especialmente em áreas com grande circulação de pessoas.', 0, NULL, N'Redução das interrupções no processo de corte;
INSERT INTO #PVC VALUES (9832, N'36805', N'516001', N'estacionamento de veículos leves no sump da britagem', 2, N'Others/Outros', N'Foi identificado o estacionamento de veículos leves na área do sump da britagem, local destinado a drenagem e operação, o que gerava risco à segurança, interferência nas atividades operacionais, obstrução de acessos e potencial impacto em situações de emergência.
INSERT INTO #PVC VALUES (9833, N'36805', N'516001', N'Correção de erosão no acesso ao Dique de Finos III', 2, N'Others/Outros', N'Foi identificada a ocorrência de processo erosivo no acesso ao Dique de Finos III, causado principalmente pela ação das chuvas e pelo tráfego de veículos, resultando em perda de material da via, dificuldades de acesso, aumento do risco de acidentes e potencial impacto à segurança operacional e ambiental.
INSERT INTO #PVC VALUES (9834, N'36805', N'536138', N'Implantação de dispositivo antifurto para controle remoto dos caminhões‑pipa', 1, N'Others/Outros', N'Foi identificado o risco de extravio, retirada indevida ou avaria dos controles remotos dos caminhões‑pipa, ocasionando perda de tempo na hora do abastecimento de água ocasionando em interrupções operacionais.', N'Evitar oparadas dos pipas por falta de controles remotos', N'10090', N'01 - Imagens/01 - Antes/9834.jpeg', N'Controles pequenos, sem local fixo ou sistema de retenção, frequentemente extraviados, ocasionando paradas e atrasos operacionais.', N'01 - Imagens/02 - Depois/9834.jpeg', N'Implantação de local fixo padronizado para guarda do controle remoto, fixado com sistema antifurto, impedindo perdas e retiradas involuntárias.', NULL, N'A meta foi plenamente atingida, com a eliminação do extravio dos controles remotos e das paradas associadas, garantindo maior eficiência, continuidade operacional e aderência às boas práticas de gestão.', N'A padronização de itens críticos e a adoção de soluções simples e robustas reduz falhas recorrentes, aumenta a confiabilidade dos processos e evita perdas operacionais significativas.', 0, NULL, N'Redução significativa do risco de acidentes;
INSERT INTO #PVC VALUES (9835, N'36805', N'536138', N'Implantação de passagem segura para acesso ao galpão da oficina centralizada', 2, N'Others/Outros', N'Falta de passagem segura e adequada para pessoas e transporte de ferramentas com acesso direto ao galpão da oficina centralizada. Essa condição dificultava o deslocamento das equipes, aumentava os riscos de segurança e provocava atrasos nas manutenções da frota fora de estrada.', N'Garantir acesso seguro, direto e padronizado ao galpão da oficina centralizada, reduzindo riscos à segurança e otimizando o tempo de execução das manutenções da frota fora de estrada.', N'10090', N'01 - Imagens/01 - Antes/9835.jpeg', N'Ausência de passagem segura, com necessidade de desvios e deslocamentos inadequados, gerando riscos e atrasos nas atividades de manutenção.', N'01 - Imagens/02 - Depois/9835.jpeg', N'Implantação de passagem segura e dedicada para pessoas e ferramentas, garantindo acesso direto ao galpão da oficina e maior fluidez operacional.', NULL, N'A meta foi plenamente alcançada, com a eliminação da restrição de acesso e dos atrasos associados, proporcionando uma operação mais segura, eficiente e alinhada às boas práticas de manutenção e segurança.', N'A infraestrutura adequada e o planejamento do acesso são fundamentais para garantir segurança, eficiência operacional e cumprimento dos prazos de manutenção.', 0, NULL, N'Organização do armazenamento das bobinas;
INSERT INTO #PVC VALUES (9836, N'36805', N'536138', N'Organização da circulação e implantação de caminho seguro no pátio do 320', 2, N'Others/Outros', N'O pátio do 320 apresentava circulação insegura, sem a definição de um caminho seguro para deslocamento, o que aumentava o risco de incidentes e dificultava o trânsito dos colaboradores no local.', N'Organizar a circulação no pátio do 320, implantar caminho seguro e padronizado para os colaboradores e reduzir os riscos de acidentes e incidentes na área.', N'10090', N'01 - Imagens/01 - Antes/9836.jpeg', N'Ausência de rota definida, circulação desordenada e maior exposição a riscos de segurança.', N'01 - Imagens/02 - Depois/9836.jpeg', N'Organização do pátio com definição e implantação de caminho seguro, melhorando o fluxo de pessoas e a segregação das áreas de circulação.', NULL, N'A meta foi plenamente alcançada, com a eliminação da desorganização da circulação e a implantação de um caminho seguro, reduzindo riscos e proporcionando melhores condições de mobilidade e segurança no pátio do 320.', N'A definição clara de rotas e a organização dos espaços são ações simples que reduzem riscos, melhoram a segurança e aumentam a eficiência no deslocamento das pessoas.', 0, NULL, N'Agilidade na abertura dos quadros elétricos;
INSERT INTO #PVC VALUES (9837, N'36805', N'539594', N'Implantação de sistema de fixação para transporte seguro da passarela de cabos elétricos', 2, N'Others/Outros', N'A passarela para cabos elétricos era transportada solta no caminhão, ocasionando quedas frequentes durante a movimentação do veículo, o que gerava risco de danos ao material e possíveis acidentes com pessoas e equipamentos.
INSERT INTO #PVC VALUES (9838, N'36805', N'552462', N'Correção de acesso com implementação de sistema de drenagem por tubulação', 2, N'Others/Outros', N'O acesso apresentava acúmulo de água e lama, devido à ausência de um sistema de drenagem adequado, ocasionando dificuldade de trafegabilidade, risco de danos aos equipamentos e aumento do potencial de incidentes operacionais.
INSERT INTO #PVC VALUES (9839, N'36805', N'532240', N'Estacionamento para veículos leves e caminho seguro no Dique de Finos III', 2, N'Others/Outros', N'No Dique de Finos III, não havia estacionamento definido para veículos leves, tampouco um caminho seguro delimitado para circulação de pessoas, resultando em circulação desorganizada, aumento do risco de incidentes, conflitos entre veículos e pedestres e exposição dos colaboradores a condições inseguras.', N'Organizar o estacionamento de veículos leves e implantar um caminho seguro para pedestres, aumentando a segurança, a organização da área e reduzindo riscos de acidentes e incidentes operacionais.', N'10090', N'01 - Imagens/01 - Antes/9839.jpeg', N'Veículos estacionados de forma irregular e ausência de rota definida para pedestres, gerando circulação desordenada e riscos à segurança.', N'01 - Imagens/02 - Depois/9839.jpeg', N' Implantação de área definida para estacionamento de veículos leves e delimitação de caminho seguro para circulação de pessoas, promovendo segregação adequada e organização do local.', NULL, N'A meta foi plenamente alcançada, com a organização do estacionamento e a implantação do caminho seguro, eliminando a circulação desordenada e promovendo um ambiente mais seguro, organizado e alinhado às boas práticas de segurança.', N'A organização de áreas e a segregação entre veículos e pedestres são medidas simples e eficazes para prevenir riscos, melhorar a segurança e aumentar a disciplina operacional.', 0, NULL, N'Contenção eficiente dos finos gerados após o corte;
INSERT INTO #PVC VALUES (9840, N'36805', N'36805', N'Sistema de irrigação automática no jardim da área de drenagem', 2, N'Others/Outros', N'A irrigação das plantas do jardim da área de drenagem era realizada de forma manual e não padronizada, resultando em consumo irregular de água, maior demanda de tempo operacional, risco de falhas na irrigação e comprometimento da conservação do jardim.', N'Automatizar o processo de irrigação do jardim da drenagem', N'10090', N'01 - Imagens/01 - Antes/9840.jpeg', N'Irrigação manual, dependente de disponibilidade de pessoas e sujeita a falhas ou excesso/falta de água. Provocando cansaço dos empregados durante atividade', N'01 - Imagens/02 - Depois/9840.jpeg', N'Implantação de sistema de irrigação automática, com programação definida, assegurando irrigação regular e padronizada sem intervenção manual constante.', NULL, N'A meta foi plenamente alcançada com a automação da irrigação, eliminando a dependência do processo manual, garantindo melhor conservação do jardim e promovendo eficiência operacional e sustentabilidade, conforme a proposta inicial do Kaizen.', N'A automação de atividades simples aumenta a eficiência operacional, reduz desperdícios e libera mão de obra para tarefas de maior valor agregado, além de contribuir para a sustentabilidade.', 0, NULL, N'Contenção eficiente dos finos no pátio de toras;
INSERT INTO #PVC VALUES (9841, N'36805', N'36805', N'Identificação dos cabos de aspersão fixa no acesso próximo do Britador 3', 1, N'Others/Outros', N'Durante a execução de uma atividade na leira do Britador 3, ocorreu o rompimento do cabo que alimenta o sistema de aspersão fixa em toda a rampa, em função da ausência de placa de identificação do cabo no local, resultando em falha do sistema e impacto operacional.', N'Evitar danos a cabos e sistemas de aspersão fixa dos acessos', N'10090', N'01 - Imagens/01 - Antes/9841.jpeg', N'Cabos de alimentação da aspersão fixa sem identificação visual, sujeitos a danos durante atividades operacionais na leira próximo da leira do britador 3.', N'01 - Imagens/02 - Depois/9841.jpeg', N'Implantação de placas de identificação e sinalização dos cabos de aspersão, orientando as equipes e prevenindo intervenções indevidas.', NULL, N'A meta foi plenamente alcançada com a identificação adequada dos cabos de aspersão, eliminando a causa do rompimento ocorrido e promovendo maior segurança e confiabilidade operacional na área do Britador 3.
INSERT INTO #PVC VALUES (9842, N'1009254', N'1009254', N'Replace Air Release Valve', 2, N'No Replication/Sem replicação', N'Air release valve letting hot water escape.', N'New air release valve fixes issue.', N'10005', N'01 - Imagens/01 - Antes/9842.jpeg', N'Hot water spraying out of the air release valve.', N'01 - Imagens/02 - Depois/9842.jpeg', N'New air release valve working and no loss of hot water.', NULL, N'Problem was solved', N'Replace defective valves', 0, NULL, N'Melhoria das condições dos acessos durante o deslocamento;
INSERT INTO #PVC VALUES (9843, N'36805', N'36805', N'Desobstrução e restabelecimento do caminho seguro de acesso à caldeiraria', 2, N'Others/Outros', N'O caminho seguro de acesso à caldeiraria encontrava‑se obstruído pela mangueira do caminhão pipa que abastece as caixas d''água, comprometendo o deslocamento dos colaboradores, dificultando o transporte de ferramentas e aumentando o risco de incidentes, como tropeços, quedas e atrasos nas atividades operacionais.', N'Restabelecer o caminho seguro para acesso à caldeiraria, garantindo circulação livre', N'10090', N'01 - Imagens/01 - Antes/9843.jpeg', N'Caminho seguro obstruído, circulação restrita e exposição dos colaboradores a riscos de acidentes.', N'01 - Imagens/02 - Depois/9843.jpeg', N'Desobstrução completa do caminho seguro, com remoção e reposição da mangueira, organização do espaço e restabelecimento da rota de circulação.', NULL, N'A meta foi plenamente alcançada, com a eliminação das obstruções e a restauração do caminho seguro, garantindo um ambiente mais organizado, seguro e alinhado às boas práticas de SSMA e 5S.
INSERT INTO #PVC VALUES (9844, N'36805', N'81014703', N'Melhoria para armazenamento na mesa de corte de tubos cortados', 1, N'Others/Outros', N'Durante as atividades de corte na bancada, foi notado a ausência de um sistema adequado para armazenamento dos tubos já cortados exigindo interrupções constantes para retirada e deslocamento do material para outro local. Essa condição gerava perda de tempo, quebra do ritmo operacional, desorganização do ambiente e movimentação desnecessária do colaborador, impactando negativamente a produtividade e a fluidez da atividade.', N'Implantar uma solução de armazenamento adequada na mesa de corte', N'10090', N'01 - Imagens/01 - Antes/9844.jpeg', N'Tubos cortados acumulados sem local definido, exigindo paradas frequêntes e deslocamento manual para armazenagem em outro ponto.', N'01 - Imagens/02 - Depois/9844.jpeg', N'Mesa com trilhos e suporte central permitiu armazenamento automático dos tubos, eliminando paradas, reduzindo tempo, aumentando a produtividade e melhorando organização, fluxo e segurança.', NULL, N'A meta foi alcançada com a eliminação das paradas desnecessárias e da desorganização causada pela falta de armazenamento adequado, resultando em um processo mais fluido, produtivo e organizado, conforme o objetivo proposto no Kaizen.', N'A organização do layout e a disponibilidade de estruturas adequadas no posto de trabalho são fundamentais para manter o fluxo contínuo', 0, NULL, N'Problema resolvido. Com o apoio do suporte, os caminhões foram liberados utilizando o sistema dos autônomos, devidamente acomodado em um ponto específico, o que facilita a manutenção e o monitoramento dos componentes', '2026-04-05T00:00:00.000', '2026-05-03T23:50:55.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9845, N'36805', N'538792', N'Torneira no posto de trabalho para otimização do processo', 3, N'Others/Outros', N'A ausência de uma torneira no posto de trabalho obrigava o colaborador a realizar deslocamentos frequentes para obtenção de água, gerando perda de tempo, esforço físico desnecessário, desorganização do ambiente e impactando negativamente a eficiência do processo.', N'Eliminar deslocamentos desnecessários, reduzir o esforço físico do colaborador e otimizar o tempo de execução da atividade', N'10090', N'01 - Imagens/01 - Antes/9845.jpeg', N'Necessidade de deslocamento para acesso à água, com interrupções frequentes da atividade e menor fluidez do processo.', N'01 - Imagens/02 - Depois/9845.jpeg', N'Instalação de torneira diretamente no posto de trabalho, permitindo acesso imediato à água e execução contínua da atividade.', NULL, N'A meta foi plenamente alcançada, com a eliminação dos deslocamentos e do esforço excessivo, resultando em um processo mais ágil, organizado e produtivo, conforme o objetivo inicial do Kaizen.', N'Pequenas melhorias de infraestrutura no ponto de uso geram ganhos significativos em produtividade, ergonomia e organização do trabalho.', 0, NULL, N'Agora, a base ficará sendo atualizada diariamente por meio da execução do bot. O próximo passo consiste em integrar esse bot ao fluxo de execução criado pelo Marco Antonio, para que seja possível agendar sua execução, e que ele rode juntos com os demais bots do fluxo.', '2026-04-11T00:00:00.000', '2026-05-03T23:59:48.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9846, N'36805', N'81006698', N'Implantação de suporte para vassouras e pá para recolhimento de lixo', 3, N'Others/Outros', N'A ausência de um local adequado e padronizado para armazenamento de vassouras e pá resultava em materiais deixados no piso ou em locais improvidos, causando desorganização do ambiente, dificuldade de acesso aos utensílios e impacto negativo na prática do 5S.', N'Organizar e padronizar o armazenamento das vassouras e da pá', N'10090', N'01 - Imagens/01 - Antes/9846.jpeg', N'Vassouras e pá armazenadas de forma improvisada, sem local definido, contribuindo para desorganização e perda de tempo.', N'01 - Imagens/02 - Depois/9846.jpeg', N'Instalação de suporte específico para vassouras e pá, permitindo armazenamento adequado, visual e de fácil acesso.', NULL, N'A meta foi plenamente alcançada com a organização e padronização do armazenamento dos utensílios de limpeza, eliminando a desordem inicial e promovendo um ambiente mais organizado e alinhado às boas práticas de 5S.', N'A utilização de suportes simples e a padronização dos locais de armazenamento contribuem significativamente para a organização, disciplina e eficiência no ambiente de trabalho.', 0, NULL, N'By having these materials here on hand, we had significantly less downtime on the crane while these repairs were executed. The tank house remained up on power during this 24 hour period.', '2026-04-17T00:00:00.000', '2026-05-04T00:03:59.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9847, N'36805', N'81014703', N'barreira de proteção no policorte de tubos', 2, N'Others/Outros', N'O policorte de tubos operava sem barreira de proteção adequada, expondo os colaboradores a risco de contato com partes móveis, projeção de fagulhas e partículas, além de aumentar o potencial de incidentes durante a execução dos cortes.', N'Aumentar a segurança do processo de corte de tubos, reduzindo a exposição dos colaboradores a riscos e adequando o posto de trabalho às boas práticas de SSMA.', N'10090', N'01 - Imagens/01 - Antes/9847.jpeg', N'Equipamento de corte de pontaletes sem proteção física eficaz, com maior exposição do operador e do entorno ao risco.', N'01 - Imagens/02 - Depois/9847.jpeg', N'Instalação de barreira de proteção fixa no policorte, promovendo segregação segura da área de corte', NULL, N'A meta foi plenamente alcançada com a implantação da barreira de proteção, eliminando a exposição direta aos riscos do policorte e garantindo um processo mais seguro e controlado, conforme o objetivo do Kaizen.', N'A implementação de barreiras físicas é uma medida simples, porém essencial, para reduzir riscos críticos e promover um ambiente de trabalho mais seguro.', 0, NULL, N'Condensers for this eroom have been down for sometime now, last summer this resulted in the autoclave tripping as the eroom and bucket was overheating. ', '2026-04-19T00:00:00.000', '2026-05-04T00:08:29.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9848, N'36805', N'81021594', N'suporte para bobinas de adesivos na sinalização de mina', 3, N'Others/Outros', N'As bobinas de adesivos utilizadas na sinalização de mina não possuíam local adequado e padronizado para armazenamento, ficando dispersas no ambiente. Essa condição gerava desorganização, dificuldade de acesso ao material, risco de danos às bobinas e perda de tempo durante a execução das atividades de sinalização.', N'Organizar e padronizar o armazenamento das bobinas de adesivos, facilitando o acesso ao material', N'10090', N'01 - Imagens/01 - Antes/9848.jpeg', N'Bobinas armazenadas de forma improvisada, sem local definido, dificultando o manuseio e a logística da sinalização.', N'01 - Imagens/02 - Depois/9848.jpeg', N'Implantação de suporte específico para bobinas de adesivos, garantindo armazenamento adequado, visual e de fácil acesso.
INSERT INTO #PVC VALUES (9849, N'36805', N'527377', N'Identificação sequenciada de cadeados e chaves das caixas e quadros elétricos', 1, N'Others/Outros', N'A ausência de identificação nos cadeados das caixas e quadros elétricos dificultava a rápida localização das chaves corretas para abertura dos painéis elétricos, tornando as intervenções mais demoradas, pouco eficientes e suscetíveis a erros.', N'Padronizar e identificar os cadeados dos quadros elétricos', N'10090', N'01 - Imagens/01 - Antes/9849.jpeg', N'Cadeados sem identificação, exigindo tentativas sucessivas com diferentes chaves, gerando perda de tempo e atrasos nas intervenções.
INSERT INTO #PVC VALUES (9850, N'36805', N'81021594', N'Melhoria no processo de instalação de adesivos de grandes dimensões', 1, N'Others/Outros', N'Instalação de adesivos em tamanhos maiores, era necessária a presença de um ou mais colaboradores adicionais para apoio nas plotagens em paredes, salas e ambientes internos e externos. Essa necessidade ocorria principalmente para auxílio na centralização e posicionamento do material, gerando maior consumo de mão de obra, aumento do tempo de execução e dependência operacional.', N'Reduzir a necessidade de apoio adicional na instalação de adesivos, otimizar o tempo de execução', N'10090', N'01 - Imagens/01 - Antes/9850.jpeg', N'Instalação dependente de mais de um colaborador para centralização do adesivo, com maior tempo de execução e interrupções.', N'01 - Imagens/02 - Depois/9850.jpeg', N'Implantação de ímãs para apoio na plotagem permitiu que um colaborador realizasse o envelopamento sozinho, reduzindo mão de obra, garantindo a produção e melhorando centralização e nivelamento do adesivo.', NULL, N'A meta foi alcançada com a redução do apoio adicional necessário, eliminando a dependência de múltiplos colaboradores e tornando o processo de instalação mais eficiente, padronizado e produtivo, conforme o objetivo inicial do Kaizen.', N'A adoção de métodos simples e padronizados pode reduzir a dependência de recursos humanos adicionais, melhorar a ergonomia e aumentar a eficiência das atividades.', 0, NULL, N'Eliminação de paradas para reajuste de antena, fim da necessidade de troca de bases danificadas e melhoria na qualidade da comunicação de dados da frota.', '2026-04-28T00:00:00.000', '2026-05-04T00:23:02.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9851, N'36805', N'533881', N'Adequação da área de manobra do Britador 01 – Lado A para recebimento de caminhões 797F', 2, N'Others/Outros', N'Área de manobra do Britador 01 – Lado A apresentava largura insuficiente, impossibilitando o recebimento de caminhões 797F. Essa condição gerava alto risco de colisões, corte de pneus e exposição dos equipamentos e operadores a situações inseguras durante as manobras.', N'Adequar a área de manobra para permitir a operação segura dos caminhões 797F, reduzindo riscos de colisões, danos aos pneus e aumentando a segurança e fluidez operacional.', N'10090', N'01 - Imagens/01 - Antes/9851.jpeg', N'Área estreita, com manobras críticas, risco elevado de colisão e corte de pneus, impossibilitando operação segura dos caminhões 797F.', N'01 - Imagens/02 - Depois/9851.jpeg', N'Adequação/alargamento da área de manobra, garantindo espaço suficiente para circulação segura dos caminhões, com redução dos riscos operacionais.', NULL, N'A meta foi plenamente atingida com a adequação da área de manobra, eliminando a restrição operacional existente e reduzindo significativamente os riscos de acidentes e danos aos equipamentos, conforme proposto no Kaizen.
INSERT INTO #PVC VALUES (9852, N'36805', N'533881', N'Implantação de caixa de contenção de finos no pátio novo de toras', 1, N'Others/Outros', N'No pátio novo de toras, havia excesso de material fino proveniente das atividades de corte, sem sistema de contenção ou controle ambiental. Essa condição ocasionava arraste de finos, risco de impacto ambiental, desorganização da área e necessidade frequente de intervenções corretivas.', N'Conter os finos gerados no pátio de toras, reduzir o carreamento de material, atender aos controles ambientais e melhorar a organização e a segurança da área.', N'10090', N'01 - Imagens/01 - Antes/9852.jpeg', N'Material fino carreando do pátio novo de toras, sem controle ambiental, com risco de arraste e impacto ambiental.', N'01 - Imagens/02 - Depois/9852.jpeg', N'Implantação de caixa de contenção de finos, permitindo retenção adequada do material e controle do carreamento.', NULL, N'A meta foi plenamente atingida com a implantação da caixa de contenção, eliminando o excesso de finos sem controle ambiental e promovendo uma operação mais organizada, segura e alinhada às boas práticas ambientais.', N'A adoção de soluções simples de engenharia contribui significativamente para o controle ambiental, redução de impactos e melhoria da organização das áreas operacionais.', 0, NULL, N'Aumento da segurança durante as manobras de abastecimento;
INSERT INTO #PVC VALUES (9853, N'36805', N'516001', N'Implantação de cordão rochoso para contenção de finos no novo pátio de toras', 1, N'Others/Outros', N'No novo pátio de toras, foi identificado o carreamento de finos para a vegetação adjacente, decorrente da ausência de uma barreira física de contenção. Essa condição representava risco de impacto ambiental, desorganização da área e não atendimento aos controles ambientais.
INSERT INTO #PVC VALUES (9854, N'36805', N'2149', N'Drenagem Superficial na entrada do pátio de reaproveitamento de madeiras', 1, N'Others/Outros', N'No pátio de reaproveitamento de madeiras, os efluentes fluviais não possuíam direcionamento adequado, ocasionando escoamento desordenado, formação de áreas alagadas, carreamento de material e risco de impacto ambiental, além de dificultar as atividades operacionais no local.', N'Direcionar corretamente os efluentes fluviais, garantir o escoamento controlado da água, reduzir riscos ambientais e melhorar as condições operacionais do pátio.', N'10090', N'01 - Imagens/01 - Antes/9854.jpeg', N'Efluentes escoando de forma desordenada, sem controle ou direcionamento definido, afetando a área operacional e o entorno.', N'01 - Imagens/02 - Depois/9854.jpeg', N'Implantação de sistema de direcionamento e condução dos efluentes, promovendo escoamento adequado e controlado da água.', NULL, N'A meta foi plenamente alcançada, com a correção do direcionamento dos efluentes fluviais, eliminando o escoamento desordenado e promovendo uma operação mais segura, organizada e ambientalmente adequada.
INSERT INTO #PVC VALUES (9855, N'36805', N'2149', N'Implemento no garfo da pá carregadeira para melhoria do acesso em áreas de carregamento de toras', 2, N'Others/Outros', N'Durante o deslocamento da pá carregadeira de garfo nas áreas destinadas ao carregamento de toras, havia dificuldade de acesso e manobra, ocasionando perda de tempo, exposição a riscos operacionais e menor eficiência no posicionamento do equipamento para execução da atividade.', N'Melhorar o acesso e a mobilidade da pá carregadeira de garfo durante o deslocamento nas áreas de carregamento de toras', N'10090', N'01 - Imagens/01 - Antes/9855.jpeg', N' A pá carregadeira apresentava limitações de acesso e manobra, dificultando o deslocamento seguro e o posicionamento adequado para o carregamento das toras.', N'01 - Imagens/02 - Depois/9855.jpeg', N'Implantação de um implemento de madeira (tipo rodo) acoplado ao garfo da pá carregadeira, permitindo que a própria PC realize a limpeza dos acessos durante o deslocamento.', NULL, N'A meta foi plenamente atingida, com a pá carregadeira passando a realizar a limpeza dos acessos de forma autônoma por meio do implemento tipo rodo, eliminando as dificuldades de deslocamento e promovendo uma operação mais segura, ágil e eficiente.', N'Soluções simples e de baixo custo, quando bem aplicadas, podem aumentar significativamente a eficiência operacional e reduzir riscos, utilizando melhor os próprios recursos disponíveis.', 0, NULL, N'It would have taken approximately 5 days of labour for a scaffold build and dismantle.', '2026-04-23T00:00:00.000', '2026-05-04T00:49:06.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9856, N'36805', N'505288', N'Eliminação do risco de colisão na saída da oficina centralizada por meio da segregação de fluxos', 2, N'Others/Outros', N'Na saída da oficina centralizada, havia confluência de fluxos de pessoas, veículos leves e equipamentos, sem segregação adequada, aumentando o risco de colisões, quase‑acidentes e comprometendo a segurança no deslocamento e nas manobras.
INSERT INTO #PVC VALUES (9857, N'81027090', N'81027090', N'Suporte para componentes dos autônomos', NULL, N'Projects/Projetos', N'Nos caminhão komatsu não existia suporte para acomodar os componentes dos autônomos.', N'Produção', N'10015', N'01 - Imagens/01 - Antes/9857.jpeg', N'Nos caminhão komatsu não existia suporte para acomodar os componentes dos autônomos.', N'01 - Imagens/02 - Depois/9857.jpeg', N'Foi desenvolvido um suporte para resolver esse problema, suporte para acomodar o painel dos autônomos.', NULL, N'Problema resolvido. Com o apoio do suporte, os caminhões foram liberados utilizando o sistema dos autônomos, devidamente acomodado em um ponto específico, o que facilita a manutenção e o monitoramento dos componentes', N'Ver e agir', 0, NULL, N'Obter um farol do processo de medição mais ágil, confiável e padronizado, com redução de erros e maior produtividade. Espera-se garantir total rastreabilidade das informações, maior transparência e uma visão integrada para apoio à tomada de decisão, além de fortalecer a governança e permitir a escalabilidade da solução.', '2025-10-08T00:00:00.000', '2026-05-04T08:26:02.000', N'81027090', NULL, NULL);
INSERT INTO #PVC VALUES (9858, N'81063756', N'81063756', N'Bot para atualização automatizada da base de MSC do Stratws', 1, N'Others/Outros', N'A base de dados MSC do Stratws deveria ser atualizada diariamente de forma manual. O que, apesar de ser simples, se torna enfadonho com o passar do tempo.', N'Atualização automatizada da base de MSC do Stratws', N'10015', N'01 - Imagens/01 - Antes/9858.jpeg', N'A atualização da base de dados era completamente manual e realizada diariamente, o que demanda tempo e se torna repetitivo.', N'01 - Imagens/02 - Depois/9858.jpeg', N'O bot permite automatizar boa parte da tarefa. De modo que basta acessar o bot no A360, executá-lo, que todo os passos seguintes são concluídos. Vale ressaltar que, enquanto o bot executa, ele toma o controle da máquina e do cursor do mouse. Portanto, durante a execução, o operador pode usar esse tempo para fazer outras coisas, como verificar a caixa de emails pelo celular, ou se tem mensagem do chef no Whatsapp, por exemplo. ;D', N'https://vale-rpa-dev.my.automationanywhere.digital/#/bots/repository/private/files/task/100002830/edit', N'O trabalho deixou de ser 100% manual, e tem sua maior parte automatizada. O que ajuda a poupar alguns minutos do operador e permite destinar esse tempo para outra atividade enquanto aguarda a execução do bot concluir.', N'Familiaridade com criação de fluxos no A360', 0, NULL, N'Redução de cenário de risco e adequação à NR 12', '2026-05-01T00:00:00.000', '2026-05-04T08:36:07.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (9859, N'81043460', N'81043460', N'Repair of damaged harvesting crane rails', 1, N'Refining/Refino', N'Crane rail was damaged beyond safe and acceptable use.', N'Repair as required', N'0', N'01 - Imagens/01 - Antes/9859.jpeg', N'Crane rail has been damaged. Engineering work has been going on to produce a repair/replacement plan for the existing rails. Rail has ultimately failed and required emergency repair.', N'01 - Imagens/02 - Depois/9859.jpeg', N'Repair components were ordered at the beginning of this year as a backup in case we did have a failure that required attention. Rails, splice plates, hardware as well as a repair plan was put together by the crane team with help from GIP, as well as Gantrex. This plan was executed late last week to repair the damaged area of the rail.', NULL, N'Work was executed seamlessly,', N'Pays to be prepared', 50000, 3, N'Redução dos riscos em situações de emergência, com extintores posicionados próximos às rotas de fuga e de fácil acesso.', '2026-04-30T00:00:00.000', '2026-05-04T10:38:01.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (9860, N'81043460', N'81043460', N'221 Condenser Replacements', 1, N'Others/Outros', N'Condenser was damaged a number of years ago and requires replacement.', N'Replace condenser for 221-E House', N'0', N'01 - Imagens/01 - Antes/9860.jpeg', N'221 Condensers have failed, was found tagged out and in the system since 2020, yet never escalated.', N'01 - Imagens/02 - Depois/9860.jpeg', N'New condenser was ordered last year, and has been installed on the rooftop of the eroom. The design was a little different but with a little planning and a few consumables all three condensers have been installed.', NULL, N'Yes this Eroom should be much more reliable this summer coming.', N'Follow up on previous wo''s', 0, NULL, N'facil identificaçao dos itens ', '2026-05-01T00:00:00.000', '2026-05-04T11:00:49.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (9861, N'81043460', N'81043460', N'Terminal Block Reliablilty', 1, N'Refining/Refino', N'Terminal blocks are corroded and causing intermittent faults and failures.', N'Increase life span, decrease downtime', N'0', N'01 - Imagens/01 - Antes/9861.jpeg', N'Terminal block contacts have been failing causing faults and alarms that are difficult to troubleshoot and pin point. These terminal blocks are 10-12 years old and in a hevaily corrosive environment.', N'01 - Imagens/02 - Depois/9861.jpeg', N'New blocks are being installed and prior to installation they are being coated with an electric lacquer to prevent corrosion internally, as well as dielectric grease to prevent corrosion externally', NULL, N'Yes!', N'internal corrosion is often worse than external', 10000, 3, NULL, '2026-04-28T00:00:00.000', '2026-05-04T11:09:28.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (9862, N'552818', N'506004', N'Proteção Blindada: Implementação de Caixa de Proteção para o Laser do Mastro (PZ37)', 1, N'Others/Outros', N'O sensor laser instalado no mastro da perfuratriz PZ37 está constantemente exposto a impactos de detritos, vibração excessiva e intempéries durante a operação, resultando em quebras frequentes, desalinhamento e paradas não programadas para manutenção.', N'Zerar a quebra do sensor por causas externas e reduzir em 100% o tempo de máquina parada para substituição deste componente específico nos próximos 6 meses.', N'10267', N'01 - Imagens/01 - Antes/9862.jpeg', N'O laser estava exposto diretamente no mastro, sem barreira física contra fragmentos de rocha ou contato acidental durante o manuseio do equipamento, gerando custos elevados com peças de reposição.', N'01 - Imagens/02 - Depois/9862.jpeg', N'Instalação de uma caixa metálica robusta com visor de alta resistência, projetada para proteger o sensor contra impactos sem interferir na precisão do sinal de medição.', NULL, N'A meta de proteção física foi atingida com a instalação da caixa; espera-se que os indicadores de "Quebra de Sensor" cheguem a zero, cumprindo o objetivo de aumentar a disponibilidade da PZ37 conforme planejado.', N'A importância de adaptar componentes eletrônicos sensíveis ao ambiente hostil de campo e como soluções mecânicas simples podem evitar falhas eletrônicas complexas.', 0, NULL, N'the bleed valve enables us to depressurize the line before disconnecting. ', '2026-03-24T00:00:00.000', '2026-05-04T11:27:06.000', N'552818', NULL, NULL);
INSERT INTO #PVC VALUES (9863, N'552818', N'506004', N'Padronização e Estabilidade: Suporte de Fixação Robusta para Antena Shark (PZ37)', 1, N'Others/Outros', N'A antena Shark apresentava instabilidade devido à fixação improvisada ou vulnerável no topo da cabine/mastro. Isso causava perda frequente de sinal por vibração, danos estruturais à base da antena e riscos de queda, prejudicando a precisão do sistema de monitoramento/GPS.', N'Garantir 100% de estabilidade do sinal e eliminar danos físicos à antena através de uma fixação rígida e protegida, reduzindo o índice de manutenção corretiva no sistema de comunicação.', N'10053', N'01 - Imagens/01 - Antes/9863.jpeg', N'A antena era fixada de forma precária (muitas vezes com abraçadeiras ou bases magnéticas insuficientes), ficando suscetível a vibrações severas da perfuração e deslocamentos durante o transporte.', N'01 - Imagens/02 - Depois/9863.jpeg', N'Desenvolvimento e instalação de um suporte metálico customizado, aparafusado em local estratégico, com amortecedores de vibração (coxins) e posicionamento que otimiza a recepção do sinal sem obstruções.', NULL, N'O suporte resolveu a fragilidade da instalação original. A meta de estabilidade foi atingida, garantindo que o sistema de telemetria/GPS opere sem interrupções causadas por falhas mecânicas de fixação.', N'Componentes de precisão exigem suportes projetados para as condições reais de operação; a estabilidade física é a base para a estabilidade do software e dos dados.', 0, NULL, N'QUE A EMPRES COLHA BONS FRUTOS COM A MELHORIA IMPLEMENTADA.', '2026-04-01T00:00:00.000', '2026-05-04T12:09:26.000', N'552818', NULL, NULL);
INSERT INTO #PVC VALUES (9864, N'552818', N'506004', N'Olhar Estratégico: Suporte de Alta Estabilidade e Proteção para Câmera PTZ (PZ37)', 1, N'Others/Outros', N'A câmera PTZ(Pan-Tilt-Zoom), por ser um equipamento móvel e sensível, sofria com vibrações excessivas e falta de um ângulo de visão otimizado. Além disso, a fixação original não oferecia proteção contra impactos laterais ou queda de detritos, resultando em imagens instáveis e danos frequentes aos motores internos da câmera.', N'Aumentar a estabilidade da imagem em 80% e eliminar gastos com a substituição de câmeras danificadas por falta de suporte adequado, garantindo a visibilidade total da operação.', N'10053', N'01 - Imagens/01 - Antes/9864.jpeg', N'A câmera era instalada em suportes genéricos que não absorviam a vibração da perfuração, causando "efeito gelatina" na imagem e desgaste prematuro das engrenagens de rotação (pan/tilt).', N'01 - Imagens/02 - Depois/9864.jpeg', N'Implementação de um suporte reforçado com sistema de amortecimento e braço de extensão calculado para o melhor ângulo de visão (ponto cego zero), incluindo uma aba de proteção superior (proteção contra sol e chuva/detritos).', NULL, N'O suporte atende à necessidade de visão clara e estável. A meta de proteção foi alcançada ao isolar a câmera dos impactos diretos e reduzir o estresse mecânico causado pela vibração constante.', N'A qualidade do monitoramento remoto depende diretamente da rigidez estrutural do suporte; sistemas móveis (PTZ) exigem atenção redobrada à absorção de impacto.', 0, NULL, N'Now any worker in LRT O/F will know were to find a red chain to barricade an area where hazards are present', '2026-04-06T00:00:00.000', '2026-05-04T12:13:43.000', N'552818', NULL, NULL);
INSERT INTO #PVC VALUES (9865, N'525401', N'81053442', N'Melhoria na Sinalização da Bica de Captação de Água', 2, N'Others/Outros', N'Baixa visualização da estrutura, principalmente em condições de baixa luminosidade e durante operações noturnas.', N'Segurança operacional.', N'10063', N'01 - Imagens/01 - Antes/9865.jpeg', N'Antes da implementação da melhoria, não havia sinalização na bica de captação de água, o que dificultava a visualização da estrutura pelos operadores, principalmente durante manobras e em condições de baixa luminosidade.', N'01 - Imagens/02 - Depois/9865.jpeg', N'A imagen evidencia a instalação de faixas refletivas na estrutura, proporcionando maior visibilidade do ponto de captação, principalmente em operações com baixa luminosidade.
INSERT INTO #PVC VALUES (9866, N'81030117', N'81002274', N'SUPORTE PARA MANOBRA DE CABOS', 2, N'Others/Outros', N'A LOCOMOÇÃO DE CABOS ERA FEITA MANUALMENTE, HAVENDO RISCO DE CHOQUE E DANO ERGONOMICO E PERDA MATERIAL.', N'GARANTIR SEGURANÇA NAS ATIVIDADES DE MANUTENÇÃO', N'10324', N'01 - Imagens/01 - Antes/9866.jpeg', N'A LOCOMOÇÃO DE CABOS ERA FEITA MANUALMENTE, HAVENDO RISCO DE CHOQUE E DANO ERGONOMICO E PERDA MATERIAL.', N'01 - Imagens/02 - Depois/9866.jpeg', N'REALIZADO CONFECÇÃO DE SUPORTE DE REPOSICIONAMENTO DOS CABOS, EVITANDO ESFORÇO EXCESSIVO DOS COLABORADORES DURANTEA A MANOBRA DE CABOS.', NULL, N'A LOCOMOÇÃO DE CABOS ERA FEITA MANUALMENTE, HAVENDO RISCO DE CHOQUE E DANO ERGONOMICO E PERDA MATERIAL.', N'GARANTIR SEGURANÇA NAS ATIVIDADES DE MANUTENÇÃO', 0, NULL, N'espera-se que o acesso à parte superior do motor do caminhão seja realizado de forma mais segura, estável e controlada. ', '2026-04-28T00:00:00.000', '2026-05-04T14:07:59.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (9867, N'81046855', N'81046855', N'Moving Inbound Lanes', 1, N'Others/Outros', N'Moved the inbound lane closer to the desks to make the flow better ', N'Easier to Access the material that is getting received ', N'10153', N'01 - Imagens/01 - Antes/9867.jpeg', N'The inbound lanes were small and located at the door, far from the staff responsible for receiving materials. ', N'01 - Imagens/02 - Depois/9867.jpeg', N'The inbound lanes were moved closer to the desks so we can better see the materials and improve the overall flow, creating a clear entry point for incoming items.', NULL, N'Yes', N'Positioning inbound lanes closer to the receiving team improves visibility, efficiency, and workflow. Proper placement of materials reduces delays, minimizes unnecessary movement, and helps create a more organized and effective receiving process.', 0, NULL, N'Improvements within this maintenance departments benefits the overall plant efficiency by supports maintenance repairs and projects more effectively. Morale is also affected positively when ergonomic improvements are made.', '2026-03-20T00:00:00.000', '2026-05-04T14:08:54.000', N'81046855', NULL, NULL);
INSERT INTO #PVC VALUES (9868, N'81032481', N'81051220', N'Replace scaffold build with drone', 1, N'Others/Outros', N'To view an internal tank roof and upper shell courses, a scaffold would have to be built, requiring additional time the tank would be down.', N'To view the internal tank roof and upper shell courses at the same time as inspection without significant downtime of the tank.n', N'10006', N'01 - Imagens/01 - Antes/9868.jpeg', N'During an internal tank inspection of the IR2 Tank #1, there was no access to inspect the internal tank roof, nozzles and upper shell courses. A scaffold build and dismantle would take time and money, with the tank having to be down longer than anticipated. ', N'01 - Imagens/02 - Depois/9868.jpeg', N'Some of our inspectors had drone training a couple of months ago. Therefore, in place of a scaffold build, one of our QA/QC inspectors utilized the drone for a close-up inspection of the top half of the tank at the same time as the internal inspection. This allowed the tank to go back into service with no extra downtime required.', NULL, N'Full internal inspection was completed without delay.', N'Additional training in various inspection techniques can help perform timely inspections', 11800, 3, N'Preventiva realizada de forma segura, menos risco para o colaboradores durante execução da atividade.', '2026-04-23T00:00:00.000', '2026-05-04T14:16:59.000', N'81032481', NULL, NULL);
INSERT INTO #PVC VALUES (9869, N'81046855', N'81046855', N'Adding 3 x lifting Tables to KDC Warehouse ', 2, N'Others/Outros', N'Receiving materials involved a significant amount of bending and lifting.', N'The primary goal of a lift table is to reduce manual bending and lifting by raising materials to an ergonomic working height.', N'10153', N'01 - Imagens/01 - Antes/9869.jpeg', N'There were no lift tables in place, resulting in excessive bending and manual lifting.', N'01 - Imagens/02 - Depois/9869.jpeg', N'Improve worker safety by reducing strain and risk of injury
INSERT INTO #PVC VALUES (9870, N'504475', N'871194', N'AUTOMAÇÃO - FAROL DE MEDIÇÕES', 1, N'Others/Outros', N'O acompanhamento das medições era realizado por meio de um farol de controle via WhatsApp, no qual cada gestor de contrato atualizava manualmente o seu status.
INSERT INTO #PVC VALUES (9871, N'81054419', N'81054419', N'Redução de Cenário de Riscos elétricos na Escavadeira Hidráulica EC32', 1, N'Others/Outros', N'De acordo com a NR 10 e NR 12, é requisito que haja proteção física contra contato acidental em polos de baterias que expostos configuram risco elétrico. Dessa forma, foi identificado através de apreciação de risco da Pilz a oportunidade de adequar e melhorar a proteção elétrica na EC32 atendo aos e aumentando segurança e diminuindo exposição de colaboradores a riscos elétricos.', N'Diminuir cenário de risco e exposição de pessoas à riscos elétricos', N'10015', N'01 - Imagens/01 - Antes/9871.jpeg', N'Não havia proteção contra curto-circuito, choque elétrico, incêndios, danos no componente, corrosão etc em alguns polos', N'01 - Imagens/02 - Depois/9871.jpeg', N'Compartimento de baterias atendendo as especificações técnicas da NR 10 e NR 12, diminuindo a exposição de colaboradores contra riscos elétricos que podem levar à fatalidades.', NULL, N'adequação à NR 12 e NR 10', N'Redução de riscos', 0, NULL, N'Printer used in copper to cut down on time.', '2026-05-03T00:00:00.000', '2026-05-04T15:49:26.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (9872, N'524896', N'533889', N'Padronização de Extintores nas Perfuratrizes', 1, N'Others/Outros', N'Atualmente, os extintores de incêndio da área não apresentam padronização quanto à identificação, posicionamento e sinalização, o que dificulta a rápida visualização e acesso em situações de emergência. Essa condição gera riscos à segurança, falhas na gestão à vista e não conformidade com os princípios de 5S e requisitos de segurança, podendo comprometer a resposta a incidentes.', N'Estabelecer um padrão único para posicionamento, identificação e sinalização dos extintores de incêndio, garantindo rápida identificação, acesso facilitado e conformidade com os requisitos de segurança, promovendo ambientes mais seguros e organizados.', N'0', N'01 - Imagens/01 - Antes/9872.jpeg', N'Antes da implementação do Kaizen, os extintores de incêndio encontravam-se sem padronização quanto ao posicionamento, identificação e sinalização, apresentando variações entre áreas e postos de trabalho. Essa situação impactava negativamente a gestão à vista, aumentava o risco em situações de emergência.', N'01 - Imagens/02 - Depois/9872.jpeg', N'Como solução para o problema identificado, foi realizada a realocação e padronização do posicionamento dos extintores de incêndio na saída da cabine, garantindo que o equipamento fique próximo à rota de fuga, em local visível, desobstruído e de fácil acesso.', NULL, N'sim', N'A padronização do posicionamento dos extintores, especialmente nas saídas e rotas de fuga, facilita a visualização imediata e o acesso rápido em situações de emergência.', 0, NULL, N'Injury risk is reduced.', '2026-04-09T00:00:00.000', '2026-05-04T16:16:16.000', N'524896', NULL, NULL);
INSERT INTO #PVC VALUES (9873, N'699785', N'550523', N'Identificação do kit mitigação ambiental', 1, N'Others/Outros', N'Kit com conteúdo não identificado', N'facilidade na identificaçao', N'10144', N'01 - Imagens/01 - Antes/9873.jpeg', N'Kit com conteúdo interno não identificado', N'01 - Imagens/02 - Depois/9873.jpeg', N'Identificação do kit mitigação ambiental contendo o que possui internamente ', NULL, N'sim', N'facil visualizaçao', 0, NULL, N'Resultado alcançado, retirado todos os riscos, evitando a paralização da produção.', '2026-05-03T00:00:00.000', '2026-05-04T16:33:45.000', N'699785', NULL, NULL);
INSERT INTO #PVC VALUES (9874, N'983254', N'983254', N'Remoção de corpos moedores do MO02', 2, N'Projects/Projetos', N'Necessidade de remoção manual dos corpos moedores do Moinho MO2, em função do equipamento encontrar-se parado com nível elevado de corpos moedores, o que impossibilita o acesso seguro de equipamentos e equipes para execução da troca das placas de revestimento.', N'Redução de senário de risco na remoção dos corpos moedores do MO02', N'10054', N'01 - Imagens/01 - Antes/9874.jpeg', N'A atividade de retirada de 108 toneladas estava inicialmente prevista para execução manual, realizada por 06 colaboradores, com duração estimada de 48 horas. Tal condição acarretaria sobrecarga física, aumentando significativamente os riscos ergonômicos
INSERT INTO #PVC VALUES (9875, N'1008456', N'1010006', N'Install bleed valve', 2, N'Refining/Refino', N'the bypass line on the impurities MMF line did not have a bleed valve on it. ', N'install a bleed valve', N'0', N'01 - Imagens/01 - Antes/9875.jpeg', N'there was no bleed valve on the bypass line so when we had to disconnect the line it had to be done with a defensive break. ', N'01 - Imagens/02 - Depois/9875.jpeg', N'we installed a bleed valve on the line enabling us to bleed off the line before disconnection making it much safer. ', NULL, N'yes, bleed valve allows us to depressurize the line.  ', N'bleeds should be installed on temp lines. ', 0, NULL, N'no longer an unsafe open hole area', '2026-05-02T00:00:00.000', '2026-05-04T22:03:59.000', N'1008456', NULL, NULL);
INSERT INTO #PVC VALUES (9876, N'496298', N'496298', N'DISPOSITIVO TRAVA DE SEGURANÇA', 1, N'Others/Outros', N'AVARIA
INSERT INTO #PVC VALUES (9877, N'81013114', N'81013114', N'LRT O/F red chain', 1, N'Others/Outros', N'There was no dedicated red chain station for LRT O/F', N'Reduce one time use red tape', N'0', N'01 - Imagens/01 - Antes/9877.jpeg', N'There was no dedicated red chain for LRT overflow area', N'01 - Imagens/02 - Depois/9877.jpeg', N'LRT O/F area is an area where alot of line cleaning is done, and often required danger tape due to work happening over head. This provides a quick and reusable method to barricade the area so people can know not to enter when hazards are present', NULL, N'Yes, there is now a dedicated area where there will always be red chain available for use', N'N/A', 0, NULL, N'  O maior resultado e que agora nós da oficina subconjunto temos um local adequado para fazer a carregar  dos carregadores de rádios e chave de impacto e elétrica, ganhamos em padronização e 5s.', '2026-05-04T00:00:00.000', '2026-05-05T00:53:44.000', N'81013114', NULL, NULL);
INSERT INTO #PVC VALUES (9878, N'1007829', N'1007829', N'Wash Cart Lighting', 2, N'Underground/Subterrâneo', N'Area around washcart very dark during bear season ', N'improve visibility during bear season ', N'10311', N'01 - Imagens/01 - Antes/9878.jpeg', N'Very dark with only 2 small wall lights', N'01 - Imagens/02 - Depois/9878.jpeg', N'Added Light plant to brighten up area', NULL, N'Major improvement to help spot bears in the night', N'Very Dark Area', 0, NULL, N'Integração com SAP;
INSERT INTO #PVC VALUES (9879, N'81006946', N'81048624', N'ESCADA DE ACESSO AO MOTOR', 2, N'No Replication/Sem replicação', N'DIFICULDADE AO ACESSAR A PARTE SUPERIOR DO MOTOR E RISCO DE QUEDA DE NIVEL DIFERENTE.', N'ASEGURAR A SEGURANÇA DO COLABORADOR AO ACESSAR A PARTE SUPERIOR DO MOTOR', N'10139', N'01 - Imagens/01 - Antes/9879.jpeg', N'Subir até a parte superior do motor do caminhão utilizando apenas a escada de acesso da cabine apresenta uma dificuldade significativa, principalmente pela ausência de pontos de apoio adequados. Durante essa tarefa, o trabalhador precisa manter o equilíbrio em uma posição elevada, muitas vezes inclinando o corpo para alcançar a área do motor, o que aumenta o risco de instabilidade.', N'01 - Imagens/02 - Depois/9879.jpeg', N'A criação de uma escada de acesso adequada para alcançar a parte superior do motor do caminhão melhora significativamente as condições de segurança e execução da atividade. Diferentemente da situação anterior, essa escada foi projetada considerando a necessidade de manutenção, oferecendo pontos de apoio firmes e bem posicionados para as mãos e os pés.', NULL, N'Neste caso Sim!
INSERT INTO #PVC VALUES (9880, N'81031229', N'81031229', N'Electric Chain Hoist Upgrade', 2, N'Refining/Refino', N'Manual Chain hoists are essential in industry. We use them all the time. In maintenance, this means of lifting makes heavy lifting tasks possible.
INSERT INTO #PVC VALUES (9881, N'81034398', N'81004817', N' Instalação do cabo de dublagem', 1, N'Others/Outros', N'Para carregar as baterias era preciso remover as baterias do equipamento', N'eliminar a remoção das baterias', N'10139', N'01 - Imagens/01 - Antes/9881.jpeg', N'Para realizar o carregamento das baterias com o carregador nos equipamentos durante a manutenção preventiva e r.i, era necessário remover elas do equipamento, o que ocasionava risco ergonômico para os colaboradores, além da demora na execução da atividade ', N'01 - Imagens/02 - Depois/9881.jpeg', N'Foi instalado um cabo de dublagem no carregador de bateria  para realizar o carregamento das baterias dos equipamentos, esse cabo é instalado diretamente no equipamento, assim não é mais necessário a remoção das baterias, o que eliminou o risco ergonômico para os colaboradores, além de eliminar o tempo para remover as baterias.', NULL, N'Sim, com a instalação do cabo não é mais necessário a remoção das baterias', N'Pequenas mudanças tem resultados significativos', 0, NULL, N'✅ Redução de aproximadamente 72 horas e para 30 minutos corridos no tempo total do processo de reclassificação. 
INSERT INTO #PVC VALUES (9882, N'800303', N'800303', N'That Acid Don''t Freeze!', 1, N'Projects/Projetos', N'We are replacing our Sulphuric Acid day tank, with instruction replacement in-kind, with addition of anodic protection.  Original tank was insulated, as initially there was consideration into using 98% H2SO4 for the plant Operation.  As we are using 93% acid which will not freeze, there is no need to insulate the tank.  Technical approval was gained and I instructed the project team to omit insulation from the project.', N'Save money', N'0', N'01 - Imagens/01 - Antes/9882.jpeg', N'Existing Tank insulated.  Tank is slowly corroding and we need to replace tank with a new one with anodic protection to prevent internal corrosion.', N'01 - Imagens/02 - Depois/9882.jpeg', N'Insulation not required and ommited from bidding process. Estimated cost to insulate was ~$100k', NULL, N'Yes - saved ~$100k on job', N'Challenge status quo', 100000, 3, N'Indicador com calculo diferenciado para caso específico ', '2026-05-04T00:00:00.000', '2026-05-05T14:41:17.000', N'800303', NULL, NULL);
INSERT INTO #PVC VALUES (9883, N'81050431', N'81058947', N'Travador de esteira ', 2, N'Others/Outros', N'Durante a trocar da esteira ela ficar escorregando e caindo assim criando risco de acidentes ', N'Segurança ', N'10248', N'01 - Imagens/01 - Antes/9883.jpeg', N'Antes a esteira ficava escorregando ', N'01 - Imagens/02 - Depois/9883.jpeg', N'Agora a esteira fica apoiada agilizando a manutenção ', NULL, N'Sim', N'Segurança ', 0, NULL, N'Maior transparência, alinhamento entre áreas e assertividade na tomada de decisão, com redução de retrabalho na comunicação do projeto.', '2026-04-22T00:00:00.000', '2026-05-05T15:30:27.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9884, N'1008564', N'1009736', N'Place Printer in Copper Building', 1, N'Refining/Refino', N'When the technicians have to print the paperwork for the loading of the trucks they have to come to the 226 Annex to print the paperwork. ', N'Safe time', N'0', N'01 - Imagens/01 - Antes/9884.jpeg', N'There was no printer in the Copper Building', N'01 - Imagens/02 - Depois/9884.jpeg', N'Printer placed in the Copper Building. Also, Safety as the Technician does not have to keep coming back to the 226 Annex in in climate weather. ', NULL, N'Yes. The printer works great. ', N'No waiting for paperwork.', 0, NULL, N'Risks Reduction', '2026-05-04T00:00:00.000', '2026-05-05T17:37:23.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (9885, N'87000312', N'87000343', N'2-6F Drum Drying Area Protective Guards and Signage Installation', 2, N'Refining/Refino', N'The plastic barricades may be deformed or damaged. And also there was injury risk.', N'This prevents burns when drying collected materials in drums.', N'0', N'01 - Imagens/01 - Antes/9885.jpeg', N'We used cones and bars to create a barrier to prevent entry inside when drying intermediate material in the drums, but these could deform or break if they come into contact with the hot air hose because they were made of plastic.', N'01 - Imagens/02 - Depois/9885.jpeg', N'Aluminum chains were installed on the east and west sides of the drum drying area on floors 2-6.
INSERT INTO #PVC VALUES (9886, N'81006735', N'376814', N'SUPORTE PARA FIXAÇÃO DE TOMADAS', 1, N'Others/Outros', N'Estava ocorrendo com frequência a quebra das tomadas em área, causando risco de choque elétrico e paralização das atividades de virola pois ficava sem ligar as maquinas de solda. ', N'EVITAR QUEBRA DE TOMADAS', N'10303', N'01 - Imagens/01 - Antes/9886.jpeg', N'Tomadas danificadas com risco de choque elétrico, sem suporte, com grande facilidade de quebrar, em altura inadequada causando esforço físico e prejudicando na ergonomia dos colaboradores.  ', N'01 - Imagens/02 - Depois/9886.jpeg', N'Suporte montado, gerado gestão de mudança: 6015 sanado o risco de choque pois agora esta bem fixado e não tem mais risco de quebrar, foi fixado em uma altura de 1,40 Metros também sanando o risco de ergonomia.', NULL, N'Sim, conseguimos eliminar todos os riscos iniciais garantindo a saúde de cada colaborador. ', N'Usar as tomadas de maquina de solda de maneira correta.', 0, NULL, N'Espera-se que a solução proporcione maior eficiência e controle dos processos, com informações centralizadas, padronizadas e confiáveis. Como resultado, haverá redução de retrabalho, maior agilidade no atendimento das demandas, melhoria na qualidade das medições e aumento da transparência e rastreabilidade, contribuindo para uma gestão mais assertiva e tomada de decisão mais segura.', '2026-05-05T00:00:00.000', '2026-05-06T08:49:26.000', N'81006735', NULL, NULL);
INSERT INTO #PVC VALUES (9887, N'387677', N'387677', N'new work shop', 3, N'Underground/Subterrâneo', N'area unorganized and not be utilized', N'clean and organize area as another work shop', N'10058', N'01 - Imagens/01 - Antes/9887.jpeg', N'area is organized and not being utilized. ', N'01 - Imagens/02 - Depois/9887.jpeg', N'cleaned up area and can now be used for a work shop', NULL, N'yes, we now have another area to work', N'clean and utilize areas', 0, NULL, N'increase productivity for jobs ', '2026-05-04T00:00:00.000', '2026-05-06T12:02:33.000', N'387677', NULL, NULL);
INSERT INTO #PVC VALUES (9888, N'387677', N'387677', N'install open hole railing', 1, N'Concentration/Concentração', N'sewer sump was classified as an open hole condition and needed railing', N'to secure area', N'10058', N'01 - Imagens/01 - Antes/9888.jpeg', N'sewer sump area was classified as an open hole condition and needed railing.', N'01 - Imagens/02 - Depois/9888.jpeg', N'fabricated and installed new railing to secure area.', NULL, N'yes', N'secure open hole area with railing', 0, NULL, NULL, '2026-04-30T00:00:00.000', '2026-05-06T12:13:14.000', N'387677', NULL, NULL);
INSERT INTO #PVC VALUES (9889, N'81022747', N'389601', N'ENGATE RAPIDO', 1, N'Others/Outros', N'o reservatório de graxa do trator de esteira 5012 era completado através de um pino graxeiro com pistola de lubrificação', N'mais eficiente e com isso á um ganho de produtividade', N'10144', N'01 - Imagens/01 - Antes/9889.jpeg', N'o reservatório de graxa do trator de esteira 5012 era completado através de um pino graxeiro com pistola de lubrificação, dificultando e demorando para realizar o atendimento do mesmo!', N'01 - Imagens/02 - Depois/9889.jpeg', N'Foi adaptado um engate rápido de uma polegada, sendo assim, passou a ser completado através da transferidora aumentando o fluxo de graxa.', NULL, N'Aumentando o fluxo de graxa', N'Melhoria de processo', 0, NULL, N'Helps with the buildings vacuum and made a ventilation place', '2026-05-01T00:00:00.000', '2026-05-06T12:37:03.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (9890, N'81002005', N'81002005', N'Central de carregadores e baterias ', 3, N'Others/Outros', N'  Os carregadores e baterias das chaves de impacto elétrica e pneumática, rádios e ponte rolante ficava espalhados nas bancadas das células da oficinas de subconjunto. ', N'Criar um central para carregar as baterias e carregadores', N'10303', N'01 - Imagens/01 - Antes/9890.jpeg', N'   Bem antes havia um suporte para colocar os carregadores dos rádios e baterias da ponte rolante, e os carregadores das chave de impactos pneumáticas e elétricas ficava carregando encima das bancadas das células de usina e mina da oficina subconjunto.  ', N'01 - Imagens/02 - Depois/9890.jpeg', N'   Bem tivemos a ideia de aproveitar um armário de ferramenta que não estava sendo utilizado, para fazer uma central para carregar as baterias e carregadores dos rádios e chave de impacto pneumática e elétrica assim juntado em só local.', NULL, N'  Não existia um local adequado pra carregar as baterias das chaves de impacto pneumáticas e elétricas da oficina de subconjunto.', N'5s padronização, reutilização e custo zero.', 0, NULL, N'Mitigar risco de acidentes, melhorar desempenho no manuseio dos filtros e diminuir exposição de má posições ergonômicas ', '2026-05-04T00:00:00.000', '2026-05-06T14:15:42.000', N'81002005', NULL, NULL);
INSERT INTO #PVC VALUES (9891, N'81040247', N'81040247', N'Novo Fluxo de Programação de Andaimes', 1, N'Projects/Projetos', N'Programação de andaimes antes registrada via sharepoint levava muito tempo no preenchimento de planilhas, agora a demanda é rastreável via SAP pelo campo revisão.', N'Integração com SAP; Definição de datas e horários para fechamento; Retorno formalizado de atendimento em S+1; Otimização do processo de programação de andaimes.', N'10178', N'01 - Imagens/01 - Antes/9891.jpeg', N'Programação de andaimes antes era feita a solicitação via sharepoint onde não havia um rastreio das demandas via SAP, para a . 
INSERT INTO #PVC VALUES (9892, N'81036658', N'81036658', N'Interactive Stamps', 1, N'No Replication/Sem replicação', N'Often Times Engineers and Designers are using electronic stamps. As an example, for sealing drawings and stamping reviewed stamps.', N'Save Time Stamping Electronic Documents', N'10339', N'01 - Imagens/01 - Antes/9892.jpeg', N'Electronic Stamps required modifications each time used and was time consuming.', N'01 - Imagens/02 - Depois/9892.jpeg', N'Using custom stamps in PDF-XChange, stamps can be created with interactive fields such as the date saving time from customization each time it''s required. A PowerPoint was created to explain the steps to creating interactive stamps to save time.', NULL, N'Stamps can now be placed in a moment and require no modifications.', N'Software can assist in saving time', 0, NULL, N'Less cable damaged over time will save cost (assumed $5k/ year)', '2026-05-05T00:00:00.000', '2026-05-06T15:30:28.000', N'81036658', NULL, NULL);
INSERT INTO #PVC VALUES (9893, N'529422', N'529422', N' PONTO DE ABASTECIMENTO TQ1213-06', 2, N'Others/Outros', N'Operador (a) acessando a base do tanque para realizar abertura do registro, se expondo ao risco de contato com produto químico. e acesso a área restrita', N' Redução do risco de contato com produtos químicos/ Redução do movimento dos operadores (as) até a base do tanque(área restrita). ', N'10171', N'01 - Imagens/01 - Antes/9893.jpeg', N'Ao realizar atividade de abastecimento de do TQ1213-06, os  operadores do caminhão pipa de água potável CT1509 precisavam acessa área restrita   em uma media de 6 vezes por dia  ate válvula que fica localizada no pé do tanque, e próximo do ponto de dosagem de HIPOCLORITO DE SODIO SE EXPONDO AO RISCO DE CONTATO COM PRODUTO QUÍMICO. ', N'01 - Imagens/02 - Depois/9893.jpeg', N' Foi realizada a instalação de um registro distante da base do tanque,  e fora da  área Restrita que possibilitou aos operadores realizarem abertura do registro sem exposição ao risco  de contato com produto químico e evitar acessos constantes área restrita', NULL, N'SIM, OPERADORES NAO TEM MAIS NESCESSIDADE DE  ACESSAR ÁREA RESTRITA E  ELIMIONOU RISCO DE CONTATO COM PRODUTO QUIMICO E REDUZIU DISTANCIA DE MOVIMENTAÇÃO PARA RESLIZAR ATIVIDADE ', N'CUIDADO ATIVO GENUINO, Conhecimento do perigo altera comportamento,  ', 0, NULL, NULL, '2026-05-01T00:00:00.000', '2026-05-06T18:54:23.000', N'529422', NULL, NULL);
INSERT INTO #PVC VALUES (9894, N'81022779', N'81022779', N'IA Para Segurança de Processo', 1, N'Others/Outros', N'Antes da implementação do apoio da Inteligência Artificial, o processo de reclassificação de eventos de Segurança de Processo apresentava diversas limitações operacionais:
INSERT INTO #PVC VALUES (9895, N'81054419', N'81054419', N'Aprimoramento da Acurácia do Risco de Componentes no BI', NULL, N'Others/Outros', N'Foi implementada melhoria no painel de BI de gestão de componentes para identificação dos itens contemplados em projetos de extensão de vida útil. Esses componentes passam a ser devidamente sinalizados e desconsiderados no cálculo de risco de frota, aumentando a confiabilidade das análises e garantindo maior aderência à realidade operacional.', N'Otimizar cálculo de risco de frota para componentes;', N'10015', N'01 - Imagens/01 - Antes/9895.jpeg', N'Componentes em projeto de extensão de vida útil contando no cálculo de risco de frota, levando ao cálculo incorreto do indicador.', N'01 - Imagens/02 - Depois/9895.jpeg', N'Componentes em projeto de extensão de vida útil com outra tratativa dentro do painel de gestão de componentes indicando ao usuário itens estão no projeto e não contando no cálculo de risco de frota.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/5e15fa89-9fd0-4a3c-8f20-853460bc50c0/ReportSectiona81b89b3e6de2037cb81?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi&clientSideAuth=0', N'Antes: risco superestimado por considerar componentes em extensão de vida.
INSERT INTO #PVC VALUES (9896, N'81054419', N'81054419', N'Padronização do Acompanhamento da Evolução do Projeto de Extensão de Vida Útil junto às áreas parceiras', 1, N'Others/Outros', N'Foi estruturado um modelo padrão de relatório para consolidação e comunicação da evolução do projeto entre as áreas envolvidas. A iniciativa permite maior clareza no acompanhamento de resultados, marcos e próximos passos, promovendo alinhamento entre stakeholders e suportando a tomada de decisão.', N'Garantir acompanhamento claro, padronizado e integrado da evolução do projeto entre as áreas.', N'10015', N'01 - Imagens/01 - Antes/9896.jpeg', N'A evolução do projeto não possuía um formato estruturado de relatórios ou acompanhamento, dificultando o alinhamento entre áreas e a visibilidade dos resultados.', N'01 - Imagens/02 - Depois/9896.jpeg', N'Com a estruturação do relatório, houve padronização da comunicação, maior transparência dos resultados e melhor alinhamento para tomada de decisão.', NULL, N'Antes: ausência de padrão na apresentação da evolução do projeto, gerando desalinhamento.
INSERT INTO #PVC VALUES (9897, N'87000324', N'87000320', N' Material Change for Control Valve Components', 1, N'Refining/Refino', N'Deterioration of the control valve body due to corrosion. Fluid leakage caused by a faulty gasket.', N'Stable production of sulfuric acid and reduced risk of sulfuric acid leaks', N'10217', N'01 - Imagens/01 - Antes/9897.jpeg', N'Deterioration of the control valve body due to corrosion. Fluid leakage caused by a faulty gasket.', N'01 - Imagens/02 - Depois/9897.jpeg', N'Ensuring stable production and reducing the risk of leaks resulting from changes in the materials used for valve bodies and gaskets', NULL, N'There was no gap,', N'Optimization', 0, NULL, N'Garantir movimentação segura e 
INSERT INTO #PVC VALUES (9898, N'1008456', N'1010006', N'Installed signage in bin room', 2, N'Refining/Refino', N'there was an incident where a Clean hr employee had water drip on them when entering the bin room. we installed a sign stating contact SX coach before entering the bin room to remove the bins', N'To prevent Clean Hr employees from removing bins wile a press id being dropped. ', N'0', N'01 - Imagens/01 - Antes/9898.jpeg', N'No sign in place to prevent Clean Hr employees from entering the bin room to remove a bin while a Cd press is being dropped. ', N'01 - Imagens/02 - Depois/9898.jpeg', N'Installed a sigh and red chain stating "contact SX coach before removing Bins". this will ensure a conversation is had between the Clean Hr employee and the coach to communicate when bins can safely be removed. ', NULL, N'yes, the sign and red chain ensures no Clean Hr employee enters the bin room without communicating with the shift coach. ', N'Clean Hr employees were at risk when changing out bins. ', 0, NULL, N'Com a implementação do porta baterias padronizado e controle de acesso restrito aos técnicos, foi garantido o armazenamento seguro, organizado e controlado, eliminando riscos de danos, perdas e uso inadequado.', '2026-05-06T00:00:00.000', '2026-05-07T05:58:54.000', N'1008456', NULL, NULL);
INSERT INTO #PVC VALUES (9899, N'504475', N'871194', N'APLICATIVO - SOLICITAÇÃO ALIMENTAÇÃO COMPLEXO SOSSEGO', 1, N'Others/Outros', N'Informações descentralizadas, com recebimento de solicitações por diferentes canais como WhatsApp, contatos telefônicos, e-mail, entre outros, gerando dificuldades na consolidação das medições, comprometendo a confiabilidade e a credibilidade das informações.', N'Centralizar, otimizar e padronizar o processo de alimentação para facilitar a comunicação e garantir um melhor atendimento.', N'10361', N'01 - Imagens/01 - Antes/9899.jpeg', N'Descentralizadas, com recebimento de solicitações por diferentes canais como WhatsApp, contatos telefônicos, e-mail, entre outros, gerando dificuldades na consolidação das medições, comprometendo a confiabilidade e a credibilidade das informações.
INSERT INTO #PVC VALUES (9900, N'387677', N'387677', N'Rebuild kit locker', 3, N'Underground/Subterrâneo', N'parts are unorganized and not together for a rebuild, if needed.', N'to have a place to store rebuild kits', N'10058', N'01 - Imagens/01 - Antes/9900.jpeg', N'no specific area to store rebuild kits all together, to find easily and track inventory. ', N'01 - Imagens/02 - Depois/9900.jpeg', N'created locker with labeling to store rebuild kits.', NULL, N'yes', N'organize parts to make jobs easier', 0, NULL, N'Garantir movimentação segura e 
INSERT INTO #PVC VALUES (9901, N'81049746', N'81049746', N'Regular Review Unnecessary Licenses', 1, N'Projects/Projetos', N'I confirmed with Oracle that by archiving the Voisey’s Bay project (which was not my project, not my responsibility, outside of my scope entirely) which has been completed and not been used since June 30th of 2025, I have saved the company $585,540.00 per year. 
INSERT INTO #PVC VALUES (9902, N'81039893', N'81039893', N'Vent Sock Exit', 1, N'No Replication/Sem replicação', N'2'' x 2'' hole in the wall behind Pug 4 which removes the building vacuum. ', N'Covering a hole in the wall. Helping with building vacuum', N'0', N'01 - Imagens/01 - Antes/9902.jpeg', N'2'' x 2'' hole in the wall behind Pug 4 which removes the building vacuum. ', N'01 - Imagens/02 - Depois/9902.jpeg', N'Covered the hole with a piece of plywood to help with the building vacuum. Added a sign for vent sock placement. ', NULL, N'Yes, the problem was solved', N'Keeping an open mind and eye can help fix an issue', 0, NULL, N'Dificultar o acesso por distração e 
INSERT INTO #PVC VALUES (9903, N'81034629', N'485334', N'Carrinho de descontaminação do sistema hidráulico ', 1, N'Others/Outros', N'Ausência de suporte para transportar filtro frushing na bomba L.C', N'Melhorar Ergonomia ', N'10324', N'01 - Imagens/01 - Antes/9903.jpeg', N'Antes era necessário realizar o deslocamento manual dos filtros', N'01 - Imagens/02 - Depois/9903.jpeg', N'Confeccionado carrinho de descontaminação no sistema hidráulico, permitindo o deslocamento seguro dos filtros.', NULL, N'Sim. 
INSERT INTO #PVC VALUES (9904, N'81009237', N'81025818', N'Voisey''s Bay Underground - Paste fill bulkhead construction', 2, N'Underground/Subterrâneo', N'At the underground paste fill bulkhead in 3740 Stope, the originally prescribed screen spacer does not adequately support the final layer of screen, resulting in insufficient restraint prior to shotcreting. This may compromise shotcrete encapsulation, load transfer, and bulkhead confinement performance. Furthermore, the current configuration creates numerous exposed steel protrusions, posing a ground control and personnel safety risk during underground activities.', N'Improve screen spacer alignment and rigidity', N'10311', N'01 - Imagens/01 - Antes/9904.jpeg', N'Originally installed as designed, the spacer arrangement does not provide sufficient support to the final screen layer in practice, resulting in poor screen restraint and the creation of numerous exposed steel protrusions that pose a safety risk.  ', N'01 - Imagens/02 - Depois/9904.jpeg', N'Revised spacer configuration improves rigidity, ensures full screen support, and eliminates exposed steel protrusions once the final screen layer is installed. This enhancement exceeds current design requirements and demonstrates a proactive commitment to the principle that life matters most and to making it happen safely.', NULL, N'The issue was resolved by implementing a revised, more rigid screen spacer with an integrated low‑profile depth indicator, ensuring full support of the final screen layer, eliminating hazardous protrusions, and improving both ground control safety and installation efficiency.', N'Design intent does not always reflect field performance. Small modifications can deliver major safety gains - Minor changes to construction components—such as spacer selection—can substantially improve both ground control performance and worker safety. Even when installations comply with stamped drawings, actual underground conditions can expose practical shortcomings that affect safety and performance.', 0, NULL, N'Aumento da segurança do operador durante a operação, com eliminação dos riscos de impacto de materiais sobre a cabine.', '2026-05-06T00:00:00.000', '2026-05-07T12:27:54.000', N'81009237', NULL, NULL);
INSERT INTO #PVC VALUES (9905, N'606854', N'200601', N'Improve Locomotive Cable Storage', 3, N'Others/Outros', N'Locomotive cables are improperly stored and can get damaged or contaminated.', N'Improve Housekeeping and reduce waste', N'0', N'01 - Imagens/01 - Antes/9905.jpeg', N'Locomotive Electrical Cables are stored on ground in compressor area. They can become contaminated with oil or damage from improper storage.', N'01 - Imagens/02 - Depois/9905.jpeg', N'Storage hook installed to hang the hoses away from contamination and less likely to become damaged', NULL, N'Yes', N'assess cable damages and address improper storage', 0, NULL, N'Satisfação da equipe e ganhos tangíveis 
INSERT INTO #PVC VALUES (9906, N'1010861', N'1010861', N'POL Line Cleaning Tool. Pressure Washing Adapter ', 1, N'Refining/Refino', N'Maintenance and cleaning crews would have to be called in to clean minor blockages in hoses and hopper box overflow lines. Pressure washer line cleaning tool made to address minor plugging issues.', N'Clean out hoses and spools in house.', N'0', N'01 - Imagens/01 - Antes/9906.jpeg', N'Minor line plugging occurrences in POL would call for clean harbors crews to address issues.  ', N'01 - Imagens/02 - Depois/9906.jpeg', N'Connected clean out pressure washer tip to hose and pressure washer to make a line cleaning tool.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'yes', N'Pressure washing adaptor ', 1000, 3, N'os resultados esperados foram obtidos ', '2026-05-06T00:00:00.000', '2026-05-07T13:24:43.000', N'1010861', NULL, NULL);
INSERT INTO #PVC VALUES (9907, N'81042246', N'81042246', N'PRO Cantado', 2, N'Others/Outros', N'Diante do aumento de relatos e reclamações oriundas da área de expedição, relacionadas a desvios de comportamento e falhas na execução de procedimentos por parte dos motoristas, identificamos a necessidade de fortalecer a comunicação, a padronização e, principalmente, a absorção efetiva dos procedimentos operacionais obrigatórios.', N'Reduzir falhas de processo e mitigar riscos operacionais ', N'10294', N'01 - Imagens/01 - Antes/9907.jpeg', N'Desvios de comportamento e falhas na execução de procedimentos por parte dos motoristas, identificamos a necessidade de fortalecer a comunicação, a padronização e, principalmente, a absorção efetiva dos procedimentos operacionais obrigatórios. Embora os processos estivessem formalmente estabelecidos, observou-se que o modelo tradicional de treinamento e repasse de informações não estava sendo suficiente para garantir o entendimento pleno e a aplicação consistente das diretrizes de segurança e operação no dia a dia.', N'01 - Imagens/02 - Depois/9907.jpeg', N'Foi então desenvolvido o PRO Cantado — uma abordagem lúdica e interativa que transforma os procedimentos operacionais em música, facilitando a assimilação, retenção e aplicação das orientações no campo. O projeto contempla, de forma prática e didática, os principais processos críticos da operação:
INSERT INTO #PVC VALUES (9908, N'496696', N'496696', N'Melhoria no envio do relatório de turno das solicitações de materiais', 1, N'No Replication/Sem replicação', N'Relatório anterior trazia apenas gráficos e totais, sem detalhar pendências, tratativas ou frota, exigindo análise manual da planilha e aumentando tempo de consulta e risco de perda de informação.', N'Resumo operacional por frota para acompanhamento das solicitações de materiais', N'10023', N'01 - Imagens/01 - Antes/9908.jpeg', N'O relatório de turno das solicitações de materiais era enviado com foco em gráficos e totais consolidados. Para identificar pendências, tratativas em andamento e a frota relacionada, as áreas solicitantes precisavam abrir a planilha e fazer análise manual. Isso aumentava o tempo de consulta, dificultava a priorização das demandas e elevava o risco de perda de informação durante o acompanhamento do turno.', N'01 - Imagens/02 - Depois/9908.jpeg', N'Foi criado um resumo operacional automatizado em VBA, enviado no corpo do e-mail, com cards, pendências e tratativas agrupadas por frota. A melhoria padronizou a comunicação do turno, reduziu análise manual da planilha e facilitou o acompanhamento pelas áreas solicitantes.
INSERT INTO #PVC VALUES (9909, N'550466', N'81050896', N'ETIQUETA DE ADVERTÊNCIA PARA LUBRIFICAÇÃO', 2, N'Others/Outros', N'APÓS A LIBERAÇÃO DO COMPONENTE PARA A ÁREA, A INSTALAÇÃO É REALIZADA SEM A LUBRIFICAÇÃO ADEQUADA.
