INSERT INTO #PVC VALUES (9921, N'81018181', N'81018181', N'blindagem para coletor de óleo ', 1, N'Others/Outros', N'Os coletores/recipientes utilizados atualmente não são apropriados para o abastecimento de óleo nos equipamentos, podendo ocasionar contaminação do lubrificante durante o processo de transferência', N'reduzir a contaminação', N'10362', N'01 - Imagens/01 - Antes/9921.jpeg', N'Os coletores/recipientes utilizados atualmente não são apropriados para o abastecimento de óleo nos equipamentos, podendo ocasionar contaminação do lubrificante durante o processo de transferência', N'01 - Imagens/02 - Depois/9921.jpeg', N'Foi realizada a aquisição de coletores blindados para transferência de óleo, garantindo maior controle da contaminação durante o abastecimento dos equipamentos.', NULL, N'Foi realizada a aquisição de coletores blindados para transferência de óleo, garantindo maior controle da contaminação durante o abastecimento dos equipamentos.', N'melhoria continua', 0, NULL, N'.', '2026-05-06T00:00:00.000', '2026-05-07T16:49:04.000', N'81018181', NULL, NULL);
INSERT INTO #PVC VALUES (9922, N'524052', N'524052', N'Atualização de Projeção de Troca de Esteiras - Infra ', 1, N'Others/Outros', N'A projeção de data de troca esteira estava baseada sobre um cálculo da altura da garra da sapata (uma medida virtual).', N'assertividade de troca', N'10154', N'01 - Imagens/01 - Antes/9922.jpeg', N'O mapeamento de projeção data de troca de esteira em tratores estava baseada sobre um cálculo da altura da garra da sapata (uma medida virtual). ', N'01 - Imagens/02 - Depois/9922.jpeg', N'Foi realizada uma alteração no layout e na forma de cálculo da projeção de data. A inspeção fornece a medição real da altura da garra, através de relatório. Essa informação agora é tabela no painel, comparando com o valor virtual. O cálculo de projeção da vida e data de troca leva em consideração, agora, o valor medido pelo inspetor, sendo mais assertivo no resultado.', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/bd95d92b-6044-444d-a456-347b0329edb2/6f40cece6084c3d9e3a7?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'até o momento o modelo mostrou resultados positivos com a prática no campo.', N'sempre podemos ir mais a fundo na solução de um problema', 0, NULL, N'.', '2026-05-06T00:00:00.000', '2026-05-07T16:53:21.000', N'524052', NULL, NULL);
INSERT INTO #PVC VALUES (9923, N'81018181', N'81018181', N'bomba de transferência de graxa', 1, N'Others/Outros', N'Anteriormente, a transferência de graxa era realizada de forma manual, podendo ocasionar contaminação do lubrificante e exposição dos colaboradores a riscos operacionais', N'reduzir contaminação', N'10362', N'01 - Imagens/01 - Antes/9923.jpeg', N'Anteriormente, a transferência de graxa era realizada de forma manual, podendo ocasionar contaminação do lubrificante e exposição dos colaboradores a riscos operacionais', N'01 - Imagens/02 - Depois/9923.jpeg', N'Foi realizada a implantação de bomba de graxa pneumática com prato raspador para transferência de graxa diretamente dos tambores, eliminando riscos de contaminação do lubrificante e a exposição dos colaboradores durante o processo', NULL, N'Foi realizada a implantação de bomba de graxa pneumática com prato raspador para transferência de graxa diretamente dos tambores, eliminando riscos de contaminação do lubrificante e a exposição dos colaboradores durante o processo', N'melhoria continua ', 0, NULL, N'.', '2026-05-06T00:00:00.000', '2026-05-07T16:55:45.000', N'81018181', NULL, NULL);
INSERT INTO #PVC VALUES (9924, N'81050420', N'81032668', N'suporte do controlador da válvula pneumática', 2, N'Others/Outros', N'Foi realizado a fabricação e instalação do suporte do controlador da válvula pneumática de ar de admissão da célula de flotação', N'SEGURANÇA', N'10031', N'01 - Imagens/01 - Antes/9924.jpeg', N'Partes Móveis expostas na                                                                                          CF-2306SA-06, risco de eventos em atividades.', N'01 - Imagens/02 - Depois/9924.jpeg', N'Foi realizado a fabricação e instalação do suporte do controlador da válvula pneumática de ar de admissão da célula de flotação', NULL, N'COM A FABRICAÇÃO DESSE SUPORTE DE PROTEÇÃO EVITAMOS ACIDENTES EM EXPOSIÇAO DE PARTES MÓVEIS EXPOSTAS.', N'segurança preventiva', 0, NULL, N'.', '2026-05-07T00:00:00.000', '2026-05-08T01:45:21.000', N'81050420', NULL, NULL);
INSERT INTO #PVC VALUES (9925, N'81050420', N'81033430', N'PROTEGENDO PARTES ROTATIVAS EXPOSTA DA BP 05', 2, N'Others/Outros', N'PARTES MOVEIS ROTATIVAS EXPOSTAS', N'SEGURANÇA ', N'10031', N'01 - Imagens/01 - Antes/9925.jpeg', N'PARTES MÓVEIS EXPOSTAS NA                                                                                       BP-2307SA-05, RISCO DE EXPOSIÇÃO A EVENTOS EM ÁREA DE TRABALHO.
INSERT INTO #PVC VALUES (9926, N'524302', N'524302', N'Bucha para remover o induzido do motor do britador', 1, N'Crusher/Britadeira', N'Não era possível remover o induzido, pois o dispositivo realizava uma amarração inadequada, com ângulo e risco de queda e consequentemente atida contra o empregado.', N'Criar um dispositivo que fosse possível remover o induzido sem danificar o mesmo.', N'10249', N'01 - Imagens/01 - Antes/9926.jpeg', N'Não era possível remover o induzido devido não haver o dispositivo adequado, conforme é possível ver na imagem o dispositivo cria um angulo, e durante o içamento o mesmo balança para os lados tornando a operação completamente insegura devido os riscos contra a equipe e também os riscos de danificar o estator do motor. ', N'01 - Imagens/02 - Depois/9926.jpeg', N'Já existia o dispositivo para remover eixos de mancal de CF, o que nos fizemos foi adaptar esse dispositivo para que fosse possível também a remoção dos induzidos desse modelo de motor, tornando a ferramenta já existente mais abrangente na sua utilização, agora com a bucha interna aplicada no dispositivo a equipe de manutenção mecânica consegue retirar com segurança, pois o eixo fica fixo na bucha, rapidez e qualidade, pois não há o risco de danificar o estator durante a extração do induzido.', NULL, N'Problema foi resolvido, pois fizemos o teste prático já durante as atividades de manutenção, o dispositivo se provou de extremo valor pois cumpriu a sua finalidade.', N'Foi aprendido que com o desenvolvimento desse dispositivo ganhamos em produtividade, segurança e qualidade em uma só atividade.', 0, NULL, N'O risco de prensamento foi eliminado, e ainda tivemos o ganho na organização das amostras.', '2026-05-08T00:00:00.000', '2026-05-08T04:06:14.000', N'524302', NULL, NULL);
INSERT INTO #PVC VALUES (9927, N'524302', N'524302', N'Taps para o contra eixo.', 3, N'Open Pit/Poço aberto', N'No passado durante o transporte do contra eixo ocorreu vazamento de graxa e contaminou a carroceria do caminhão, foi feito um comunicado via email que não era para envia o componente de modo que houvesse a possibilidade de ocorrer novos vazamentos, alguns estavam tampando o furo do contra eixo com fita, mas a fita pode sair durante o deslocamento. ', N'Objetivo era eliminar a possibilidade de vazamentos do contra eixo.', N'10249', N'01 - Imagens/01 - Antes/9927.jpeg', N'Conforme é possível ver na imagem o furo roscado estava destampado, o componente é liberado para o cliente já cheio de graxa, conforme situação já ocorrida também havia o risco de tornar a ocorrer vazamentos no transporte e gerar impacto ambiental.', N'01 - Imagens/02 - Depois/9927.jpeg', N'Feito um taps roscado para evitar os vazamentos, de forma que veda completamente a carcaça e impedi contaminação na parte interna do contra eixo.', NULL, N'Foi resolvido, pois uma vez roscado o taps e dado um leve aperto com a chave o componente pode ser transportado com segurança e sem risco de derramamento de óleo.', N'Eliminado o risco de novos vazamentos de óleo no contra eixo durante o transporte.', 0, NULL, N'SIM. Conseguimos instalar os suportes, e suspendemos os compressores, e agora podemos realizar a atividade de forma segura e correta.', '2026-05-07T00:00:00.000', '2026-05-08T04:19:01.000', N'524302', NULL, NULL);
INSERT INTO #PVC VALUES (9928, N'81050420', N'81032668', N'SUPORTE PARA MANGUEIRA FLOTAÇÃO ', 2, N'Others/Outros', N'NÃO HÁ LOCAL DE GUARDAR A MANGUEIRA EM AREA, FICANDO NO CHÃO E EXPOSTA, RISCO DE QUEDA DE PESSOAS.', N'SEGURANÇA PREVENTIVA', N'10031', N'01 - Imagens/01 - Antes/9928.jpeg', N'ANTES NÃO HAVIALUGAR DE ARMAZENAMENTO DA MANGUEIRA QUE SE USA PRA EXECUÇÃO DE ATIVIDADES.', N'01 - Imagens/02 - Depois/9928.jpeg', N'APÓS FOI REALIZADO A FABRICAÇÃO DE SUPORTE PARA MANGUEIRA, EVITANDO QUE FIQUE JOGADA AO CHÃO, EVITANDO ATÉ TROPEÇOS.', NULL, N'ANTES NÃO HAVIA LUGAR DE ARMAZENAMENTO DA MANGUEIRA QUE SE USA PRA EXECUÇÃO DE ATIVIDADES, COM O SUPORTE CRIADO A MANGUEIRA JA TEM UM LUGAR PARA ARMAZENAMENTO.', N'SEGURANÇA PREVENTIVA', 0, NULL, N'Alcançou-se uma menos quantidade de etapas para o avanço da Atividade e um ganho em Performance (menos tempo investido).
INSERT INTO #PVC VALUES (9929, N'504475', N'871194', N'AGENDAMENTO - SALA REUNIÃO COMPLEXO SOSSEGO', 1, N'Others/Outros', N'Atualmente, o controle de agendamento de salas no Complexo do Sossego é realizado de forma despadronizada, utilizando múltiplos canais como WhatsApp, e-mail e planilhas em Excel, o que dificulta a centralização e a confiabilidade das informações.
INSERT INTO #PVC VALUES (9930, N'81045885', N'81045885', N'PLANILHA DE PLANEJAMENTO DE VIGAS', 1, N'Others/Outros', N'OS PLANEJADORES PERDEM UMA QUANTIDADE CONSIDERÁVEL DE TEMPO, PLANEJANDO/ORÇANDO  A QUANTIDADE EXATA DE CHAPAS NECESSÁRIAS PARA FABRICAÇÃO DE VIGAS INTERNAMENTE E EXTERNAMENTE.', N'REDUZIR O TEMPO DE CÁLCULO/ORÇAMENTAÇÃO DE VIGAS QUE PRECISAM SER FABRICADAS', N'10081', N'01 - Imagens/01 - Antes/9930.jpeg', N'ANTES OS PLANEJADORES FAZIAM O CÁLCULO MANUALMENTE, ITEM POR ITEM, BASEADO EM UMA TABELA DE AÇOS E CHAPAS QUE O ARMAZÉM DE QUANTIDADE (EM PESO) DO ESTOQUE.
INSERT INTO #PVC VALUES (9931, N'81034629', N'485334', N'Bomba de Sabão Caminhão Pipa', 1, N'Others/Outros', N'Antes não havia uma bomba de sabão para atendimento das máquinas em campo ', N'Diminuir desperdicios e otimizar tempo', N'10266', N'01 - Imagens/01 - Antes/9931.jpeg', N'Ausência de bomba de sabão para projetar o produto nas máquinas durante atendimento, principalmente em campo. ', N'01 - Imagens/02 - Depois/9931.jpeg', N'Confeccionado e instalado bomba com mangueira e tubulação para espalhar sabão na maquina. ', NULL, N'Sim.
INSERT INTO #PVC VALUES (9932, N'81035706', N'81035706', N'Instalação de tomada para teste de esmerilhadeiras.', 1, N'Others/Outros', N'No empréstimo de esmerilhadeiras e outras ferramentas com plugue elétrico, não havia um meio de verificar se o equipamento estava funcionando corretamente. Em alguns casos, apenas na devolução o colaborador informava que a ferramenta apresentava defeito.', N'Instalação de tomada para teste de esmerilhadeiras e ferramentas elétricas antes do empréstimo.', N'10139', N'01 - Imagens/01 - Antes/9932.jpeg', N'No empréstimo de esmerilhadeiras e outras ferramentas com plugue elétrico, não havia um meio de verificar se o equipamento estava funcionando corretamente. Em alguns casos, apenas na devolução o colaborador informava que a ferramenta apresentava defeito.', N'01 - Imagens/02 - Depois/9932.jpeg', N'Foi instalada uma tomada para teste das ferramentas antes do empréstimo. Com isso, a funcionalidade do equipamento é conferida no ato da entrega, garantindo que a ferramenta esteja em condições adequadas de uso.', NULL, N'Instalação de tomada para teste de esmerilhadeiras e ferramentas elétricas antes do empréstimo.
INSERT INTO #PVC VALUES (9933, N'81047115', N'81046944', N'INDENTIFICAÇÃO DE TAMBORES', 1, N'Others/Outros', N'OS TAMBORES FICAVAM POSICIONADO NA BASE SEM A IDENTIFICAVAM ADEQUADA PARA FÁCIL VISUALIZAÇÃO E PARA A REPOSIÇÃO NO LUGAR CORRETO DE CADA UM. ', N'IDENTIFICAR OS TAMBORES DE ÓLEO CONFORME SUA ESPECIFICAÇÃO', N'10362', N'01 - Imagens/01 - Antes/9933.jpeg', N'OS TAMBORES FICAVAM POSICIONADO NA BASE SEM A IDENTIFICAVAM ADEQUADA PARA FÁCIL VISUALIZAÇÃO E PARA A REPOSIÇÃO NO LUGAR CORRETO DE CADA UM. ', N'01 - Imagens/02 - Depois/9933.jpeg', N'FOI REALIZADO A IDENTIFICAÇÃO POR TIPO DE ÓLEO UTILIZADO, CADA ÓLEO NO LUGAR ADEQUADO A ELES. ', NULL, N'Sim, está sendo implantado a melhoria e estamos tendo resultados positivos', N'Melhorar a visualização do tipo de óleo na base para reposição. ', 0, NULL, N'Process problem can be found easily.', '2026-05-04T00:00:00.000', '2026-05-08T12:49:22.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (9934, N'81047115', N'81034532', N'LUBRIFIVADOR AUTOMATICO', 1, N'Others/Outros', N'Evitar o aquecimento do equipamento e substituir a lubrificação e evitar o aquecimento do equipamento e substituir a lubrificação manual', N'Garantir a lubrificação continua, precisa e eficiente.', N'10362', N'01 - Imagens/01 - Antes/9934.jpeg', N'Equipamento sem lubrificador automático onde a lubrificação era feira manual ', N'01 - Imagens/02 - Depois/9934.jpeg', N'Instalação dos lubrificadores automáticos para Evitar o aquecimento do equipamento e substituir  a lubrificação manual.', NULL, N'sim', N'Automatizar o processo de lubrificação automática, dessa forma proporciona melhores resultados para os colaboradores que lubrificam e garante a eficiência de funcionamento do equipamento. ', 0, NULL, N'eliminação de risco', '2026-05-04T00:00:00.000', '2026-05-08T13:04:23.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (9935, N'81047115', N'81040282', N'SUPORTE  FILTRO', 1, N'Others/Outros', N'Havia uma deficiência no filtro na linha de retorno de óleo do 2051 MH 01,  pela pressão de retorno de óleo o filtro se movimentava criando folgas em suas conexões.  ', N'Melhoria no processo ', N'10362', N'01 - Imagens/01 - Antes/9935.jpeg', N'Vazamento de óleo nas conexões do filtro.', N'01 - Imagens/02 - Depois/9935.jpeg', N'Foi realizado a fabricação de um suporte para estabilizar o filtro.', NULL, N'SIM', N'.', 0, NULL, N'organização', '2026-05-04T00:00:00.000', '2026-05-08T13:11:42.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (9936, N'81047115', N'81012438', N'SUPORTE DE FIXAÇÃO', NULL, N'Others/Outros', N'Compressor não tinha suporte de fixação.', N'Facilita a rotina de trabalho ', N'10362', N'01 - Imagens/01 - Antes/9936.jpeg', N'Compressor não tinha suporte de fixação. Foi fabricado um suporte de fixação para os compressores ', N'01 - Imagens/02 - Depois/9936.jpeg', N'Foi fabricado um suporte de fixação para os compressores ', NULL, N'SIM', N'.', 0, NULL, N'Identificação dos acionamentos.', '2026-05-05T00:00:00.000', '2026-05-08T13:20:21.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (9937, N'81047115', N'81013885', N'TUBULAÇÃO DE ALIMENTAÇÃO', 1, N'Others/Outros', N'O compressor não tinha tubulação de alimentação.', N'Facilita rotina de trabalho ', N'10362', N'01 - Imagens/01 - Antes/9937.jpeg', N'Não tinha tubulação de alimentação ', N'01 - Imagens/02 - Depois/9937.jpeg', N' Foi fabricado a tubulação e feita a instalação e realizada pintura.', NULL, N'SIM', N'Padronização no equipamento. ', 0, NULL, N'Mapear e identificar todos os módulos do transportador 2101tc02.', '2026-05-05T00:00:00.000', '2026-05-08T13:28:29.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (9938, N'1014308', N'1014308', N'Lime sample scoop', NULL, N'No Replication/Sem replicação', N'Lime scoop for taking dry feed samples', N'Lime sample scoop', N'10021', N'01 - Imagens/01 - Antes/9938.jpeg', N'N/A', N'01 - Imagens/02 - Depois/9938.jpeg', N'Scoop for taking dry lime sample', NULL, N'N/A', N'N/A', 0, NULL, N'Eliminar o risco de trabalho à quente toda vez que você realizada a retirada e montagem dos olhares Para retirar o piso do fosso.', '2026-04-21T00:00:00.000', '2026-05-08T13:30:18.000', N'1014308', NULL, NULL);
INSERT INTO #PVC VALUES (9939, N'549569', N'549569', N'Arquivamento das amostras de bica de vazamento', 2, N'No Replication/Sem replicação', N'As amostras de bica de vazamento de metal, após serem analisadas, eram arquivadas por um período de 30 dias dentro de gavetas. No entanto, devido ao desgaste dos armários e ao peso das amostras, as gavetas frequentemente se desprendiam ao serem abastecidas com novas amostras. Essa situação gerava risco de prensamento das mãos e dedos dos operadores e dificultava a identificação das amostras, já que, ao caírem, perdiam a sequência organizada.
INSERT INTO #PVC VALUES (9940, N'549569', N'549569', N'Drenagem da agua dos compressores dos Raio-X', 2, N'Others/Outros', N'Devido à posição da válvula de drenagem dos compressores dos equipamentos de Raio X 01 e 02, localizada na parte inferior, era necessário levantar os compressores diariamente para realizar a drenagem da água acumulada. Esse procedimento exigia esforço físico, postura inadequada e gerava desconforto aos operadores, além de expor os mesmos a riscos ergonômicos durante a execução da atividade.
INSERT INTO #PVC VALUES (9941, N'81026411', N'81026411', N'Procedimento para Içamentos na Crista da Barragem do Sossego', 1, N'Others/Outros', N'Para içamentos de carga na crista da Barragem do Sossego, não havia um padrão orientativo para subsidiar a empresa responsável pelo plano de movimentação de cargas suspensas (Plano de Rigging), ocasionando assim um desperdício de tempo na busca desta orientação e perda de performance no avanço desta atividade. Era sempre feita uma análise caso a caso.', N'Padrão técnico orientativo subsidiando a atividade; Validação de atividade crítica pelo corpo técnico responsável; Menos etapas para o avanço da Atividade; Ganho em Performance (menos tempo investido).', N'10363', N'01 - Imagens/01 - Antes/9941.jpeg', N'Para içamentos de carga na crista da Barragem do Sossego, não havia um padrão orientativo para subsidiar a empresa responsável pelo plano de movimentação de cargas suspensas (Plano de Rigging), ocasionando assim um desperdício de tempo na busca desta orientação e perda de performance no avanço desta atividade. Era sempre feita uma análise caso a caso.', N'01 - Imagens/02 - Depois/9941.jpeg', N'As atividades com equipamentos de elevação de cargas são de alto risco, por isso está atrelado a um item essencial, o Plano de Rigging. Buscando subsidiar este Plano, criou-se, então, o Padrão Orientativo (Nota Técnica) simples e direto apresentando, dentre outras orientações, a capacidade de carga da estrutura. Desta forma, todo içamento na crista da Barragem pode seguir este procedimento sem a necessidade de uma análise específica caso a caso.', NULL, N'Sim, obteve-se um Padrão técnico orientativo subsidiando a atividade crítica e uma validação de atividade crítica pelo corpo técnico responsável;
INSERT INTO #PVC VALUES (9942, N'81054419', N'81054419', N'Otimização Relatório De Confiabilidade e Componentes', 1, N'Projects/Projetos', N'A entrega de relatórios de confiabilidade era realizada de forma pouco padronizada e com baixa visibilidade sobre a cobertura analítica dos componentes.
INSERT INTO #PVC VALUES (9943, N'81046953', N'81040412', N'IMPLATAÇÃO DE SUPORTE PARA MANUSEIO DE TORPEDO', 2, N'Others/Outros', N'O TORPEDO ( PEÇA METÁLICA PESADA), ERA MANIPULADO SEM UM APOIO ADEQUAD. ISSO EXIGIA  ESFORÇO FISÍCO MAIOR POSTURA INADEQUADA ( CURVADO OU COM TORÇÃO NO CORPO), E AUMENTAVA O RISCO DE ACIDENTES, COMO; QUEDAS DE PEÇAS, PRESSAMENTO DE MÃOS OU FADIGA EXCESSIVAS.', N'MELHORAR A ERGONOMIA E A SEGURANÇA NO MANUSEIO DO TORPEDO', N'10362', N'01 - Imagens/01 - Antes/9943.jpeg', N'SUPORTE PARA MANUSEIO DE TORPEDO, MOSTRA BEM UMA MELHORIA SIMPLES, MAIS MUITO EFICIENTE NO DIA-A-DIA. (PEÇA METÁLICA PESADA), ERA MANIPULADO SEM UM APOIO ADEQUADO. ISSO EXIGIA ESFORÇO FISÍCO MAIOR, POSTURA INADEQUADA,(CURVADO OU COM TORÇÃO DO CORPO), E AUMENTAVA O RISCO DE ACIDENTES; COMO QUEDAS DE PEÇAS, PRESSAMENTO DE MÃOS OU FADIGA EXCESSIVA.', N'01 - Imagens/02 - Depois/9943.jpeg', N'COM IMPLATAÇÃO DO SUPORTE METÁLICO,(ESTRUTURA AMARELA COM AS ABRAÇADEIRAS DE FIXAÇÃO, O TORPEDO PASSA A FICAR POSICIONADO, ESTÁVEL E SEGURO E SEGURO. AS ABRAÇADEIRAS MANTÉM A PEÇA FIRME, EVITANDO DESLOCAMENTO DURANTE MANUSEIO.
INSERT INTO #PVC VALUES (9944, N'81046953', N'81059661', N'IMPLATAÇÃO DE PORTÃO DE ACESSO DAS VÁLVULAS DE RECALQUE DAS BOMBAS 2551-BP10, E 2551-BP10R', 2, N'Others/Outros', N'O ACESSO À PLATAFORMA DAS VÁLVULAS DE RECALQUE ENCONTRAVA- SE SEM PROTEÇÃO FRONTAL ADEQUADA PERMINTIDO A ENTRADA NÃO AUTORIZADA DE PESSOAS NA ARÉA OPERACIONAL. A CONDIÇÃO APRESENTAVA RISCO DE ACESSO INDEVIDO, POSSIBILIDADE DE ACIDENTES DURANTE CIRCULAÇÃO E EXPOSIÇÃO DE COLABORADORES A UMA ARÉA DE OPERAÇÃO.', N'A MELHORIA TAMBÉM TEM COMO OBJETIVO PROPORCIONAR MAIS CONTROLE DE ACESSO', N'10362', N'01 - Imagens/01 - Antes/9944.jpeg', N'O ACESSO À PLATAFORMA DAS VÁLVULAS DE RECALQUE ENCONTRAVA- SE SEM PROTEÇÃO FRONTAL ADEQUADA PERMINTIDO A ENTRADA NÃO AUTORIZADA DE PESSOAS NA ARÉA OPERACIONAL. A CONDIÇÃO APRESENTAVA RISCO DE ACESSO INDEVIDO, POSSIBILIDADE DE ACIDENTES DURANTE CIRCULAÇÃO E EXPOSIÇÃO DE COLABORADORES A UMA ARÉA DE OPERAÇÃO.', N'01 - Imagens/02 - Depois/9944.jpeg', N'A IMPLATAÇÃO DO PORTÃO ELIMINOU A ARÉA ABERTA NA ENTRADA DA ESCADA, PROPORCIONANDO MAIS PROTEÇÃO AOS COLABORADORES DURANTE AO ACESSO E CIRCULAÇÃO NA PLATAFORMA.UMA CONDIÇÃO DA ARÉA FOI SIGNIFICATIVAMENTE MELHORADA.', NULL, N'COM A IMPLATAÇÃO DO PORTÃO DE SEGURANÇA, A CONDIÇÃO IDENTIFICADA NA DECLARAÇÃO DO PROBLEMA FOI SOLUCIONADA, ATENDENDO À META ESTABELECIDA DE PROPORCIONAR MAIS SEGURANÇA, A MELHORIA É REDUZIR A EXPOSIÇÃO DE RISCO, AUMENTOU A SEGURANÇA OPERACIONAL E ADEQUOU O ACESSO ÀS CONDIÇÕES SEGURAS DE TRABALHO.', N'A SINALIZAÇÃO VIZUAL FACILITA A IDENTIFICAÇÃO DE ARÉAS DE RISCO E REFORÇA A PERCEPÇÃO DE SEGURANÇA', 0, NULL, N'yes', '2026-05-04T00:00:00.000', '2026-05-08T21:53:38.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (9945, N'1008382', N'1008382', N'IR2 Floc Inline mixer addition', 1, N'Refining/Refino', N'Due to the fact that more floc is required in the IR2 circuit than can be supplied by the circuits originally designed floc addition system a second addition point was added to the discharge of the IR1 THK feed pump. Addition floc flow achieved but undiluted flow causing issues with settling and floc to float to top of thickener. ', N'Dilute IR2 additional floc injection', N'0', N'01 - Imagens/01 - Antes/9945.jpeg', N'Flocculant injected directly into pIR2 THK feed pump discharge not dispersing properly and not maximizing potential settling and/or causing settling issues. ', N'01 - Imagens/02 - Depois/9945.jpeg', N'Inline mixer from ETP not being used taken and added to this injection. A line ran from discharge of pH adjust pump discharge and diluting floc. Sample taken from mixer discharge showed good mixing/dilution of floc meaning better mixing and overall less flocculant needed as it will be more effective. ', NULL, N'Better dilution and mixing of floc, less unmixed floc floating to top of THK. Gradually reducing amount of floc used in THK. ', N'When creating addition floc injections, dilution should always be considered. ', 10000, 3, N'Not reprocessing the solution or causing THK to increase in torque ', '2026-04-30T00:00:00.000', '2026-05-09T03:34:13.000', N'1008382', NULL, NULL);
INSERT INTO #PVC VALUES (9946, N'87000312', N'87000393', N'Install digital ammeter of MHA-BE', 1, N'Refining/Refino', N'The control room has an MH-BE ammeter, and if the SV-5 is clogged, the current reading will drop, so it should be possible to determine if it''s clogged. However, the ammeter is analog and the difference in readings is negligible, So it was difficult to judge visually, and a reliable diagnosis could not be made.', N'To recognize matte choking in the piping by electric current of digital ammeter.', N'0', N'01 - Imagens/01 - Antes/9946.jpeg', N'The control room has an MH-BE ammeter, and if the SV-5 is clogged, the current reading will drop, so it should be possible to determine if it''s clogged. However, the ammeter is analog and the difference in readings is negligible, So it was difficult to judge visually, and a reliable diagnosis could not be made.', N'01 - Imagens/02 - Depois/9946.jpeg', N' Adigital ammeter for MH-BE was installed in the contral room.
INSERT INTO #PVC VALUES (9947, N'81050085', N'81050085', N'PISO SEGURO', 2, N'Others/Outros', N'Piso com vão aberto, sem proteção completa, expondo os colaboradores a riscos siguinificativos durante a atividade operacionais. A condição insegura aumentava a possibilidade de queda em nível diferente, devido a ausência de uma proteção segura e sinalização adequada.', N'Eliminar Risco de Queda', N'10065', N'01 - Imagens/01 - Antes/9947.jpeg', N'Piso com vão aberto, sem proteção completa, expondo os colaboradores a riscos siguinificativos durante a atividade operacionais. A condição insegura aumentava a possibilidade de queda em nível diferente, devido a ausência de uma proteção segura e sinalização adequada.', N'01 - Imagens/02 - Depois/9947.jpeg', N'com a implementação da proteção na abertura da grade de piso, foi possível eliminar a exposição dos colaboradores ao risco de queda, melhorar as condições de circulação na  area operacional e aumentar a segurança durante as atividades, promovendo maior confiabilidade operacional e prevenção de acidentes.', NULL, N'sim', N'Eliminamos o risco de queda', 2, 1, N'Além da padronização e automação, houve aumento da produtividade na análise de materiais, maior agilidade no atendimento das demandas, redução de divergências entre áreas e fortalecimento da tomada de decisão baseada em dados, elevando a eficiência e a qualidade do processo como um todo.', '2026-05-09T00:00:00.000', '2026-05-10T04:26:31.000', N'81050085', NULL, NULL);
INSERT INTO #PVC VALUES (9948, N'81050085', N'81050085', N'Zero Tropeço', 1, N'Others/Outros', N'Mangueira ficava no chão, e muita das vezes amarrada pro fios sem sustentação e acabava solta e ficando no chão com risco de tropeço para as pessoas que circulam na área ', N'eliminar risco de tropeço', N'10065', N'01 - Imagens/01 - Antes/9948.jpeg', N'Mangueira ficava no chão, e muita das vezes amarrada pro fios sem sustentação e acabava solta e ficando no chão com risco de tropeço para as pessoas que circulam na área.', N'01 - Imagens/02 - Depois/9948.jpeg', N'Com objetivo de melhorar as condições de segurança e organização da área operacional, foi confeccionado um suporte para armazenamento adequado da mangueira. Além de promover maior segurança aos colaboradores, a adequação contribui para o fortalecimento das práticas de Housekeeping, padronização e conservação dos materiais nas atividades diárias, garantido uma área organizada.', NULL, N'sim!', N'organização, eliminação de risco', 2, 1, N'O resultado esperado com a migração para o Power Apps é a transformação completa do processo de coleta e análise de avaliações. ', '2026-05-09T00:00:00.000', '2026-05-10T04:45:55.000', N'81050085', NULL, NULL);
INSERT INTO #PVC VALUES (9949, N'502163', N'81012442', N'Motores Tageados 2101TC01', 3, N'Crusher/Britadeira', N'Ausencia de Tag padronizado para os acionamentos do TCLD ( 3 motores/redutores), o que gera confusão na hora da manutenção , e ate passível de erros durante manutenção .', N'IDENTIFICAR E PADRONIZAR os acionamentos. ', N'10362', N'01 - Imagens/01 - Antes/9949.jpeg', N'Ausência de TAG, e identificação dos 3 acionamentos da 2101TC01 TCLD. ', N'01 - Imagens/02 - Depois/9949.jpeg', N'Tagueado conforme padrão os 03 acionamentos da correia 2101TC01.  evitando risco de manutenção e intervenção em acionamento incorreto .', NULL, N'Sim, Equipamentos tagueados conforme padrão. ', N'Melhor nivel de 5s ao taguear equipamentos', 0, NULL, N'Reduced spillage', '2026-05-04T00:00:00.000', '2026-05-10T09:25:51.000', N'502163', NULL, NULL);
INSERT INTO #PVC VALUES (9950, N'502163', N'81012442', N'Módulos padronizados', 3, N'Crusher/Britadeira', N'No transportador 2101TC02 temos 48 módulos, muitos deles sem identificação, ou com numeração incorreta e diversas marcações, o que ja gerou erro durante a troca dos rolos, dificuldade do inspetor de mapear, e atraso na equipe de execução devido necessidade de reconfirmarão do inspetor para validar a troca. ', N'Padronizar a identificação de todos os módulos do lado direito e esquerdo da correia, de forma clara.', N'10362', N'01 - Imagens/01 - Antes/9950.jpeg', N'No transportador 2101TC02 temos 48 módulos, muitos deles sem identificação, ou com numeração incorreta e diversas marcações, o que ja gerou erro durante a troca dos rolos, dificuldade do inspetor de mapear, e atraso na equipe de execução .', N'01 - Imagens/02 - Depois/9950.jpeg', N'Mapeado e tagueados todos os 48 módulos , dos lados direito e esquerdo, facilitando a inspeção, e manutenção durante troca dos rolos. ', NULL, N'Padronizado todos os módulos do transportador, facilitando a inspeção e manutenção dos mesmo. ', N'Melhor maturidade 5s, e facilidade de manutenção', 0, NULL, N'- Redução total do número de pessoas em área de lavra expostas à ZAS (Zona de Autossalvamento do PAEBM);
INSERT INTO #PVC VALUES (9951, N'502163', N'81012442', N'Olhal protegido ! ', 2, N'Crusher/Britadeira', N'Durante toda a atividade de remoção do piso ao lado do moinho de bolas era necessário a solda de olhais ,execução de LP e posteriormente a corte dos mesmos olhais gerando risco de tropeço de pessoas.
INSERT INTO #PVC VALUES (9952, N'502163', N'81012442', N'Extintor sem danos. ', NULL, N'Crusher/Britadeira', N'Investidor de incêndio ao lado do moinho SAG não tinha suporte E deixavam mesmo caído no chão O risco de acionamento involuntário ou que se dá ação elevada e danos no mesmo.', N'Fabricar suporte para o extintor. ', N'10362', N'01 - Imagens/01 - Antes/9952.jpeg', N'Extintor de incêndio sem suporte Caído no chão Uma sujeita a oxidação e danos no mesmo.', N'01 - Imagens/02 - Depois/9952.jpeg', N'Aplicado suporte de base para o extintor não ficar em contato com o chão.', NULL, N'Foi fabricado um suporte e o extintor não está mais em contato com o chão e instalado de forma adequada no ponto de Combate a incêndio.', N'Melhorar padrão de 5s no local. ', 0, NULL, N'Com a criação desta placa vazada a chance de colocar o óleo errado e eliminada', '2026-05-02T00:00:00.000', '2026-05-10T10:35:41.000', N'502163', NULL, NULL);
INSERT INTO #PVC VALUES (9953, N'81060882', N'81060882', N'Tag do equipamento', 2, N'Others/Outros', N'Ausência de identificação no equipamento.', N'Facilitar a identificação e melhorar a produtividade.', N'10362', N'01 - Imagens/01 - Antes/9953.jpeg', N'Painel elétrico sem identificação ou sinalização, devido a troca do componente o mesmo não estava identificado com a Tag.', N'01 - Imagens/02 - Depois/9953.jpeg', N'Realizada a identificação do componente para facilitar possíveis manutenção e eliminar erros durante a operação no mesmo.', NULL, N'A identificação do equipamento vai facilitar na visualização e aumentar a segurança durante as operações.', N'Garantir que os equipamentos sejam identificados.', 0, NULL, N'Eliminação de paradas indevidas por falha de subvelocidade. Maior confiabilidade na leitura do sensor. Aumento da disponibilidade do transportador 6013TR03. Redução de intervenções corretivas e retrabalho de manutenção.
