INSERT INTO #PVC VALUES (10079, N'81052333', N'81057202', N'Base com guarda corpo para manutenção no martelo do rompedor', 1, N'Crusher/Britadeira', N'Colaborador exposto à linha de fogo
INSERT INTO #PVC VALUES (10080, N'81052333', N'472940', N'Casinha para guardar máquina de solda na área da atividade', 1, N'Crusher/Britadeira', N'Era necessário transportar constantemente a máquina de solda entre diferentes áreas de trabalho, pois havia risco de extravio quando deixada no local. Movimento desnecessário (transporte) ergonomia.', N'guardar equipamento com segurança do ativo e ergonomia.', N'10362', N'01 - Imagens/01 - Antes/10080.jpeg', N'Era necessário transportar constantemente a máquina de solda entre diferentes áreas, ergonomia, falta de local seguro para armazenamento nas áreas de trabalho. ', N'01 - Imagens/02 - Depois/10080.jpeg', N'implantação de uma “casinha” para armazenar a máquina de solda. Instalação de sistema de fechamento (cadeado) para garantir a segurança, eliminação do transporte desnecessário do equipamento.', NULL, N'Era necessário ficar levando e trazendo a máquina de solda, eliminação do transporte desnecessário do equipamento. Redução do tempo de deslocamento aumento da segurança (eliminação do risco de extravio).', N'Avaliar o cenário para realizar a atividade com segurança eficiência', 5300, 1, N'Change over/ disconnect the hose without shut down', '2026-05-14T00:00:00.000', '2026-05-17T17:19:38.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (10081, N'81020702', N'500808', N'Capa de proteção interna cabine tyre handler', 1, N'Others/Outros', N'Equipamento fora do padrão de conservação da cabine.', N'Instalar capa de proteção interna na cabine das tyre handler minimizando danos no equipamento', N'10140', N'01 - Imagens/01 - Antes/10081.jpeg', N'Antes era não conforme a forma de conservação da cabine, sem proteção interna, deixando exposta a danos.', N'01 - Imagens/02 - Depois/10081.jpeg', N'Foi aplicado uma capa de proteção interna da cabine, assoalho, poltrona e teto, minimizando avarias e exposição a danos gerais no equipamento.', NULL, N'Sim', N'Padronização dos nossos equipamentos de suporte.', 0, NULL, N'Catch basing emptying itself', '2026-05-13T00:00:00.000', '2026-05-17T18:40:54.000', N'81020702', NULL, NULL);
INSERT INTO #PVC VALUES (10082, N'923110', N'923110', N'Identificação Lava Olhos', 2, N'No Replication/Sem replicação', N'Falta de identificação Lavas Olhos. ', N'Objetivo de melhorar a visibilidade, facilitar a localização em situações de emergência e garantir maior conformidade com os padrões de segurança da área.', N'10054', N'01 - Imagens/01 - Antes/10082.jpeg', N'Antes não tínhamos identificação visível/padrão ponto de Lava Olhos, dificultando identificação em uma eventual emergência.', N'01 - Imagens/02 - Depois/10082.jpeg', N'A melhoria contribui para uma identificação mais rápida do equipamento pelos colaboradores, reforçando as condições de segurança e atendimento emergencial no ambiente de trabalho.', NULL, N'Sim. Conseguimos chegar no objetivo esperado com sucesso.', N'Compromisso com Segurança', 0, NULL, N'Catch basing self sustaining', '2026-05-13T00:00:00.000', '2026-05-17T22:38:02.000', N'923110', NULL, NULL);
INSERT INTO #PVC VALUES (10083, N'81052339', N'81052339', N'NOVO COLETOR PARA ELIMINAR RISCO DE CONTAMINAÇÃO', 1, N'Projects/Projetos', N'ANTES , NA HORA DE COLETAR A AMOSTRA , A GENTE TINHA RISCO DE CONTAMINAR . OU CAIA SUJEIRA DE FORA, OU ENCOSTAMOS A BOCA DO SAQUINHO , OU RESPINGAVA DE OUTRO LUGAR . 
INSERT INTO #PVC VALUES (10084, N'87000324', N'87000372', N'Renewal of Inspection Cover of the Flange Section of the roof top of No.3RT furnace for insulation and temperature measurement', 1, N'Refining/Refino', N'No insulation had been installed, resulting in a significant temperature difference compared to the surrounding areas. Furthermore, when measuring the surface temperature in that area, it was necessary to remove and reinstall the insulation each time.', N'Improvements in Insulation and Measurement Efficiency', N'10217', N'01 - Imagens/01 - Antes/10084.jpeg', N'No insulation had been installed, resulting in a significant temperature difference compared to the surrounding areas. Furthermore, when measuring the surface temperature in that area, it was necessary to remove and reinstall the insulation each time.', N'01 - Imagens/02 - Depois/10084.jpeg', N'The temperature distribution has been evened out. It is now easier to remove and reinstall the insulation.', NULL, N'There was no gap,', N'Optimization', 0, NULL, N'Com a nova abordagem, obtivemos os seguintes resultados:
INSERT INTO #PVC VALUES (10085, N'87000312', N'87000318', N'To improve inspection root for No3 CT and No3 WT', 1, N'Refining/Refino', N'when inspecting No.3CT and No.3 WT required the use of a monkey ladder, which was necessary wearing a safety harness. However, it was not only time-consuming but also dangerous,', N'Improve access to the No3 CT and No3 WT', N'0', N'01 - Imagens/01 - Antes/10085.jpeg', N'when inspecting No.3CT and No.3 WT required the use of a monkey ladder, which was necessary wearing a safety harness. However, it was not only time-consuming but also dangerous,', N'01 - Imagens/02 - Depois/10085.jpeg', N'The installation of stairs made it possible to safely inspect the area without safety harnesses, which led to a reduction in inspection time.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Visibility improvements ', '2026-05-17T00:00:00.000', '2026-05-18T06:54:03.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (10086, N'550466', N'472952', N'Saca Polia/Acoplamento', 2, N'Projects/Projetos', N'A remoção de acoplamentos e polias de grande porte é executada com o auxílio de dispositivos desenvolvidos internamente (Kaizens), aliados ao uso de bomba hidráulica e aquecimento controlado dos componentes. Entretanto, esse processo resulta em maior tempo de execução e eleva a exposição dos colaboradores aos riscos inerentes à atividade.
