INSERT INTO #PVC VALUES (10088, N'1008463', N'1008463', N'Reach Extender', 1, N'Refining/Refino', N'When placing a lifting sling on the Cad press plates, technicians had to over reach to try and place the sling through the holes of the plates', N'Easier access to hook up the plates', N'10112', N'01 - Imagens/01 - Antes/10088.jpeg', N'No storage locations for the reachers', N'01 - Imagens/02 - Depois/10088.jpeg', N'Reacher aid and storage area put on press 1', NULL, N'Yes the goal was achieved', N'Better ergonomics', 0, NULL, N'Redução no tempo de análise.', '2026-05-17T00:00:00.000', '2026-05-18T11:46:55.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (10089, N'1008463', N'460565', N'Reach extender press 2', 1, N'Refining/Refino', N'When hooking up plates to change out cloths, technicians had to over reach to hook up the slings', N'Hook up the plates easier', N'10238', N'01 - Imagens/01 - Antes/10089.jpeg', N'Over reaching required to hook up the press plates', N'01 - Imagens/02 - Depois/10089.jpeg', N'Reach extender and storage location put on press 2', NULL, N'Goal was achieved', N'Better ergonomics', 0, NULL, N'Maturidade de 5S.', '2026-05-17T00:00:00.000', '2026-05-18T11:51:44.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (10090, N'1008463', N'1008463', N'Air Hammer storage location', 3, N'Refining/Refino', N'Air hammer used for changing cloths didn''t have a "home" and was often left on the floor', N'Have a storage area when not in use', N'10112', N'01 - Imagens/01 - Antes/10090.jpeg', N'Air hammer and hose often left lying on the floor, with risk of damage', N'01 - Imagens/02 - Depois/10090.jpeg', N'Storage area was made and labelled right at the changing area', NULL, N'Yes the outcome was met', N'Better housekeeping', 0, NULL, N'A implementação dessa solução contribui significativamente para o aumento da segurança na atividade, reduzindo o potencial de impacto direto ao colaborador e fortalecendo as barreiras de controle contra acidentes envolvendo sistemas pressurizados.', '2026-05-17T00:00:00.000', '2026-05-18T11:55:51.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (10091, N'81048240', N'81048240', N'Implantação de Controle de Dispêndio Externo com Visão Analítica e Suporte à Auditoria', NULL, N'Others/Outros', N'Não havia um controle estruturado dos dispêndios externos.', N'Desenvolvimento e implantação de um controle estruturado de dispêndio externo, permitindo:  Consolidação das informações em base única Acompanhamento contínuo dos gastos Padronização dos dados e informações Facilidade de acesso e consulta', N'10367', N'01 - Imagens/01 - Antes/10091.jpeg', N'Não havia um controle estruturado dos dispêndios externos, o que dificultava:
INSERT INTO #PVC VALUES (10092, N'81048517', N'81048517', N'Padronização e Criação de Procedimentos', 1, N'Others/Outros', N'Criar normas internas, com aprovador, historico de versão e cadastrar no sispav', N'Criar normas internas de padronização', N'10052', N'01 - Imagens/01 - Antes/10092.jpeg', N'Sem padrão e sem mapeamento oficial das atividades, feita somente por videos, de forma confusa e de difícil acompanhamento em pontos específicos', N'01 - Imagens/02 - Depois/10092.jpeg', N'Ter um método, claro, detalhado sobre os procedimentos-chave na área, com um criador e um responsável. Analisando a possibiliade de subir material via SISPAV, para controle de versão e se tornar norma de procedimento padrão.', NULL, N'Não havia procedimento padrão para ser seguido, nem cadastro no SISPAV para atividades críticas internas. Gerando riscos no caso de ausência de um analista responsável pela atividade. ', N'Organização, maior eficiência e sustantabilidade nos processos internos', 0, NULL, N'Maior segurança operacional.', '2026-05-15T00:00:00.000', '2026-05-18T11:57:17.000', N'81048517', NULL, NULL);
INSERT INTO #PVC VALUES (10093, N'1008463', N'460565', N'Bypass line valve', NULL, N'Refining/Refino', N'Bypass line that was on the Imp bypass line was hooked up directly. Shut down was needed to switch over hose or disconnect it', N'Install an isolation valve', N'10112', N'01 - Imagens/01 - Antes/10093.jpeg', N'Hose was bolted directly to the spool', N'01 - Imagens/02 - Depois/10093.jpeg', N'Isolation valve was installed on the hose', NULL, N'Goal was met', N'None', 0, NULL, N'A integração deve gerar ganhos diretos em eficiência, confiabilidade, custo e controle, alinhando a operação a um modelo moderno de manutenção preditiva baseada em condição.', '2026-05-17T00:00:00.000', '2026-05-18T12:13:04.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (10094, N'1013610', N'1013610', N'Cell Feed Sample Bucket', NULL, N'Refining/Refino', N'The bucket under the cell feed sample in Cu EW was often full and hard to move without spilling ', N'Self draining catch basin', N'10112', N'01 - Imagens/01 - Antes/10094.jpeg', N'Bucket often full of solution and in a difficult spot to remove and dump', N'01 - Imagens/02 - Depois/10094.jpeg', N'Self draining catch basin was put under the sample point, removing the chance of the bucket getting too full', NULL, N'Outcome was met', N'Self sustaining', 0, NULL, N'•Redução do desgaste desigual dos côncavos
INSERT INTO #PVC VALUES (10095, N'1013610', N'1013610', N'Spent electrolyte catch basin', 1, N'Refining/Refino', N'Sample catch basin often full and hard to dump', N'Self sustaining catch basin', N'10112', N'01 - Imagens/01 - Antes/10095.jpeg', N'Sample bucket often found full', N'01 - Imagens/02 - Depois/10095.jpeg', N'Self sustaining catch basin under the sample point', NULL, N'Yes goal was met', N'None', 0, NULL, N'Maior agilidade na disponibilização das informações;
INSERT INTO #PVC VALUES (10096, N'481899', N'481899', N'BARREIRA DE CONTENÇÃO', 2, N'Others/Outros', N'Quando ocorria vazamento de óleo no eletrodo, o material derramava no piso e retornava para o próprio eletrodo, ocasionando curto-circuito no mesmo, pois a umidade provocava o fechamento do circuito elétrico.', N'Evitar contato do óleo com o eletrodo.', N'10049', N'01 - Imagens/01 - Antes/10096.jpeg', N'Quando ocorria vazamento de óleo no dos hidráulicos, o material derramava no piso e era direcionado para o eletrodo devido não ter barreira, ocasionando curto-circuito no eletrodo, pois a umidade provocava o fechamento do circuito elétrico.', N'01 - Imagens/02 - Depois/10096.jpeg', N'Após a criação de barreiras em volta dos eletrodos, o líquido hidráulico derramado passou a não atingir mais os eletrodos, evitando assim a ocorrência de curto-circuito. Com isso, foram reduzidas as necessidades de manutenção corretiva e as paradas do forno relacionadas a derramamento de óleo hidráulico.
INSERT INTO #PVC VALUES (10097, N'935171', N'935171', N'Movimentação Segura', 2, N'Others/Outros', N'
INSERT INTO #PVC VALUES (10098, N'81042755', N'81024953', N'Lighting Improvement in Midds Thickner area', 1, N'Concentration/Concentração', N'Area along column on bottom floor elevation of Concentrator in area of Midds Thickner is darker then other areas. Want to maintain the lighting in the area to match other areas.', N'Improve visibility in area', N'10071', N'01 - Imagens/01 - Antes/10098.jpeg', N'Area lighting less then other areas along the thickening tanks.', N'01 - Imagens/02 - Depois/10098.jpeg', N'Light fixture mounted in the darker area and power via near by light power circuits.', NULL, N'Area is well lit now. ', N'Lights important to maintain good visibility', 1000, 3, N'Melhorar a Saúde e Higiene ocupacional dos colaboradores.', '2026-04-28T00:00:00.000', '2026-05-18T14:51:00.000', N'81042755', NULL, NULL);
INSERT INTO #PVC VALUES (10099, N'81051666', N'81012634', N'INSPEÇÃO VISUAL DE SINALIZAÇÃO DE EMERGÊNCIA – PAEBM ', 1, N'Others/Outros', N'Antes da implantação do formulário de inspeção, as inspeções das rotas de fuga eram realizadas de forma visual em campo, com os desvios e necessidades de manutenção tratados diretamente entre as equipes operacionais. Entretanto, não havia uma ferramenta padronizada para registro, rastreabilidade e acompanhamento formal das condições identificadas durante as inspeções.
INSERT INTO #PVC VALUES (10100, N'81051666', N'87002013', N'PLANILHA DE CONTROLE PLUVIOMÉTRICO DA MINA DO SOSSEGO  ', 1, N'Others/Outros', N'Antes não existia uma solução unificada de todo o controle pluviométrico da Mina do Sossego, todas as informações eram extraídas diretamente do site Vista Data Vision de forma individual, o que tornava as informações mais complicadas de serem encontradas/entendidas.
INSERT INTO #PVC VALUES (10101, N'501925', N'501925', N'SMART RPM', 1, N'Others/Outros', N'Dificuldade na identificação da RPM de equipamentos acionados por polias e que possuem rpm variável.', N'Facilitar identificação de RPM dos equipamentos acionados por polia e que possuem RPM variável para análise de vibração.', N'10178', N'01 - Imagens/01 - Antes/10101.jpeg', N'Era necessário identificar a RPM do motor e realizar o cálculo manualmente para encontrar a RPM da bomba.', N'01 - Imagens/02 - Depois/10101.jpeg', N'Foram levantados  os dados de dimensionamento das polias das BP''s, além da relação de redução dos redutores e após inserir a RPM de entrada na planilha, é possível obter de saída.', NULL, N'100% dos equipamentos monitorados mapeados.', N'Otimização do tempo na análise de equipamentos de rpm variável.', 0, NULL, N'Garantir a integridade do ativo ', '2026-05-15T00:00:00.000', '2026-05-18T16:31:43.000', N'501925', NULL, NULL);
INSERT INTO #PVC VALUES (10102, N'81007243', N'81003514', N'Suporte para calços de roda', 3, N'Others/Outros', N'Foi identificado que o suporte destinado ao armazenamento dos calços de roda encontra-se desorganizado, sem padronização e com acondicionamento inadequado dos itens.
INSERT INTO #PVC VALUES (10103, N'81007243', N'81003514', N'Proteção para a válvula reguladora - Cilindro de Solda', 2, N'Smelting/Fundição', N'Durante atividade de soldagem na caçamba da PC07, utilizando máquina MIG, o empregado realizou a abertura da válvula de regulagem de pressão do gás e, em seguida, do registro geral do cilindro.
INSERT INTO #PVC VALUES (10104, N'81050299', N'81050299', N'Proteção do Sensor de Pressão da Transmissão', 1, N'Others/Outros', N'Durante as manutenções, a equipe precisava acessar áreas próximas ao sensor de pressão da transmissão. Como o sensor ficava exposto, era comum pisarem no componente. Resultado: fio rompido e sensor danificado. Isso gerava parada não programada do equipamento, custo de peça nova e retrabalho da manutenção.', N'quebras de sensor por pisoteio após instalação/Redução de 100% nas ordens de serviço corretivas para troca do sensor de pressão da transmissão', N'10007', N'01 - Imagens/01 - Antes/10104.jpeg', N'Durante as manutenções, a equipe precisava acessar áreas próximas ao sensor de pressão da transmissão. Como o sensor ficava exposto, era comum pisarem no componente. Resultado: fio rompido e sensor danificado. Isso gerava parada não programada do equipamento, custo de peça nova e retrabalho da manutenção.', N'01 - Imagens/02 - Depois/10104.jpeg', N'Desenvolvemos e instalamos uma proteção metálica fixa sobre o sensor de pressão da transmissão. A proteção blinda o sensor e o chicote elétrico, impedindo contato direto mesmo que alguém pise na região.', NULL, N'O problema era: "pisoteio quebrava o fio e o sensor parava". A causa não era a equipe ser desatenta. A causa era o projeto: sensor crítico instalado em rota de passagem, sem barreira física. Ao instalar a proteção metálica, eliminamos a possibilidade do contato direto. Mesmo que alguém pise ali hoje, a força vai na proteção, não no sensor. Então o risco foi bloqueado na origem. Não dependemos mais de "tomar cuidado" ou "lembrar de não pisar". Engenharia resolveu o que comportamento não conseguia garantir 100%.Conclusão: Problema de quebra por pisoteio foi 100% mitigado. Enquanto a proteção estiver instalada, essa falha específica não volta a acontecer. Quer que eu já calcule o ganho financeiro estimado pra colocar no Kaizen? Só me fala o custo médio de 1 sensor + horas de máquina parada.', N' Mapear pontos de risco na manutenção: Antes de executar qualquer atividade, observar onde a equipe pisa, apoia ferramenta ou se desloca. Componentes expostos nessas rotas viram alvo.', 10, 1, N'definir e melhorar a entrega de gases.', '2026-05-18T00:00:00.000', '2026-05-19T02:44:09.000', N'81050299', NULL, NULL);
INSERT INTO #PVC VALUES (10105, N'540607', N'540607', N'Melhoria da Segurança Operacional por Meio de Sinalização de Máquinas', 2, N'Others/Outros', N'Devido à ocorrência de alguns incidentes envolvendo máquinas de carga, identificou-se a necessidade de melhorar a sinalização desses equipamentos para reduzir riscos durante as operações.  Com obejtivo de aumentar a segurança dos colaboradores, prevenir novos incidentes,alertar sobre movimentações e operação das máquinas.', N'Prevenção/mitigação de riscos ', N'0', N'01 - Imagens/01 - Antes/10105.jpeg', N'Ocorrência de incidentes envolvendo máquinas de carga.
INSERT INTO #PVC VALUES (10106, N'81050872', N'81050872', N'Integração da Lubrificação Remota por condição na plataforma Dynamox', NULL, N'Others/Outros', N'O processo anterior era fragmentado, exigia maior intervenção manual e reduzia a eficiência operacional, devido à utilização de sistemas isolados e sem integração direta.', N'Realizar as lubrificações de um único lugar, contribuindo para otimização do recurso, aumento da produtividade. ', N'10178', N'01 - Imagens/01 - Antes/10106.jpeg', N'Antes da implementação do botão de integração com a plataforma Dynamox, o processo de lubrificação remota por condição era realizado de forma desconectada entre sistemas. As atividades de lubrificação eram executadas diretamente na plataforma da Perma, sem qualquer comunicação ou sincronização automática com a Dynamox. ', N'01 - Imagens/02 - Depois/10106.jpeg', N'Com a implementação do botão de integração, o processo de lubrificação remota por condição passou a ser realizado de forma centralizada e automatizada dentro da plataforma Dynamox, eliminando a necessidade de utilização de sistemas paralelos.', NULL, N'Antes da integração
INSERT INTO #PVC VALUES (10107, N'536228', N'536228', N'Melhoria do processo de basculamento de caminhões para toda as frotas', NULL, N'No Replication/Sem replicação', N'Britador 1 Lado A restrito somente para frota 793 e 830', N'Aumento de Produtividade', N'10122', N'01 - Imagens/01 - Antes/10107.jpeg', N'Ausência de condições operacionais adequadas (raio de manobra insuficiente) para basculamento de caminhões de grande porte (794,930), resultando em:
INSERT INTO #PVC VALUES (10108, N'81024812', N'81024812', N'Otimização da Análise de Ociosidade por meio de Automação em Power BI', 1, N'Open Pit/Poço aberto', N'Antes da implementação do BI, o processo de análise de ociosidade era predominantemente manual, demandando um esforço significativo na coleta, consolidação e tratamento dos dados. 
INSERT INTO #PVC VALUES (10109, N'82826', N'82826', N'Aprimoramento Dimensional da Base de Rolos Guias', 1, N'Others/Outros', N'Durante inspeção realizada no TR-04, foi verificado que os rolos guias apresentavam travamento, em decorrência da limitação de ajuste associada ao diâmetro insuficiente dos furos de fixação. Tal condição impactava diretamente no alinhamento operacional da correia
INSERT INTO #PVC VALUES (10110, N'81063762', N'81063762', N'Criação de Checklist para verificação de Itens Obrigatórios em Controle Inicial', 1, N'Others/Outros', N'Ausência de um padrão estruturado para validação sistêmica dos requisitos mínimos nos controles iniciais de equipamentos e projetos, resultando em inconsistências de informações, falhas na rastreabilidade, riscos operacionais e retrabalho ao longo do ciclo de vida dos ativos.', N'Implementar um checklist padronizado para assegurar a verificação e conformidade dos itens obrigatórios nos controles iniciais de equipamentos e projetos, garantindo qualidade, confiabilidade das informações e aderência aos processos de gestão de ativos.', N'10081', N'01 - Imagens/01 - Antes/10110.jpeg', N'- As verificações eram realizadas de forma não padronizada e dependentes da experiência individual;
INSERT INTO #PVC VALUES (10111, N'471876', N'471876', N'ruido excessivo  em rotor de capela', 2, N'Others/Outros', N'ruido intermitente no ambiente', N'Minimizar ruido', N'10331', N'01 - Imagens/01 - Antes/10111.jpeg', N'Descrição do Item: (Antes)
INSERT INTO #PVC VALUES (10112, N'82826', N'82826', N'Instalação de Cavalete e Rolo de Retorno na Região do Carro Esticador do TR-04', 1, N'Others/Outros', N'Durante inspeção realizada no TR-04, constatou-se que, na região de retorno da correia, próxima ao carro esticador, ocorria contato da correia com a viga durante a operação normal.', N'Garantir o alinhamento adequado da correia na região do carro esticador do TR-04, por meio da instalação de cavalete e rolo de retorno, proporcionando suporte contínuo e redução de desvios operacionais.', N'10294', N'01 - Imagens/01 - Antes/10112.jpeg', N'Durante a operação, verificou-se contato da correia com a estrutura do transportador ( viga), resultando em desvios de alinhamento.', N'01 - Imagens/02 - Depois/10112.jpeg', N'Instalação de um cavalete e rolo de retorno na região do próximo ao carro esticador.', NULL, N'Sim. A ação contribuiu para redução da quantidade de eventos de desalinhamento da correia e desgaste prematuro da correia transportadora.', N'Importância da presença de cavaletes e rolos de retorno:​  A ausência desses componentes compromete o suporte da correia, favorecendo desalinhamentos e interferências com a estrutura.​  ​  Prevenção de desgaste prematuro​  A correção da interferência evita danos tanto à correia quanto à estrutura metálica.', 0, NULL, N'Aumento da produtividade da equipe
INSERT INTO #PVC VALUES (10113, N'81047089', N'200351', N'Top 10 Schedule - Automated Email ', 1, N'Underground/Subterrâneo', N'10-20 minute task being repeated every day (not just one individual as there are multiple mines) being eliminated entirely as the workflow was automated using technology. This also prevents interruptions of the routine being executed during times when the executor is on vacation, could be sick, etc. ', N'Eliminate repetitive task by automating it using technology', N'10238', N'01 - Imagens/01 - Antes/10113.jpeg', N'Previously, user would visit a website, download a PDF of a schedule, generate an email and then send it to a list of users. ', N'01 - Imagens/02 - Depois/10113.jpeg', N'Solution was implemented by leveraging existing technology, specifically power automate. This technology is not new and is used in for other workflows - was expanded to make our team more efficient. ', NULL, N'Yes the problem was solved as the task has been automated. ', N'Need to better inform team members of potential solutions or opportunities to simplify/automate existing workflows. ', 0, NULL, N'Timely calibration of errant pH probes potentially leads to less reagent addition, and/or to better nickel production by maintaining required set-points that have been optimized for the process.', '2026-05-15T00:00:00.000', '2026-05-19T11:37:28.000', N'81047089', NULL, NULL);
INSERT INTO #PVC VALUES (10114, N'550609', N'550609', N'PROTEÇÕES DE RAC 07', 2, N'Others/Outros', N'HAVIRA', N'GARANTIR TOTAL SEGURANÇA AOS COLABORADORES ', N'10199', N'01 - Imagens/01 - Antes/10114.jpeg', N'A proteção existente não estava em conformidade com os requisitos da NR‑12 vigente, representando risco potencial de ocorrência de acidentes.”', N'01 - Imagens/02 - Depois/10114.jpeg', N'Foi instalada uma nova proteção que atende integralmente aos requisitos da NR‑12, garantindo maior segurança na operação do equipamento, além de proporcionar melhor visibilidade e acesso para atividades de inspeção e manutenção', NULL, N'O problema foi resolvido e replicado para toda as bombas no site', N'Aprendemos que quando temos condições melhores a ser implantadas o resultado garante uma maior satisfação ', 0, NULL, N'Being able to get gloves in a easily accessible designated area, helps keep our work areas clean and can save time by not having to go back to the annex to get some if needed.  ', '2026-04-10T00:00:00.000', '2026-05-19T11:42:43.000', N'550609', NULL, NULL);
INSERT INTO #PVC VALUES (10115, N'81006732', N'81006732', N'Implementação de painel LED na Ferramentaria.', 3, N'Others/Outros', N'Era utilizado placas impressas em folhas A4 para repassarmos informações referente ao atendimento, gerando gastos com papel nas impressões, tempo para realizar as trocas das placas e o empregado tinha que vir até o balcão para visualizar.   ', N'Repasse de informações com maior visibilidade.', N'10184', N'01 - Imagens/01 - Antes/10115.jpeg', N'Era utilizado placas impressas em folhas A4 para repassarmos informações referente ao atendimento, gerando gastos com papel nas impressões, tempo para realizar as trocas das placas e o empregado tinha que vir até o balcão para visualizar.   ', N'01 - Imagens/02 - Depois/10115.jpeg', N'Implementamos um painel de LED via Wi-Fi, realizando os comandos via aplicativo que estão instalados nos celulares da equipe de atendimento. Agilizando no repasse de informações durante o atendimento diário, facilitando na visualização dos empregados à distancia. Evitando gastos com impressões,  eliminando a troca de placas e fazendo o uso do aplicativo em qualquer lugar da Ferramentaria.', N'https://globalvale-my.sharepoint.com/:v:/r/personal/gabrielly_da_silva_vale_com/Documents/Microsoft%20Teams%20Chat%20Files/IMG_8033.MOV?csf=1&web=1&e=lNmoy5', N'Sim, com o Painel de LED facilitamos e aprimoramos a comunicação de Ferramentaria com os empregados.', N'O Painel de LED foi bem aceito e elogiado por toda equipe de atendimento, facilitando e aprimorando a comunicação de Ferramentaria com os empregados.', 0, NULL, N'Having earplugs in a designated area close to the reclaim helps ensure all workers are wearing them by having them in easily, and quickly accessible place.  ', '2026-05-15T00:00:00.000', '2026-05-19T12:41:55.000', N'81006732', NULL, NULL);
INSERT INTO #PVC VALUES (10116, N'1008636', N'1008636', N'Dustex Bump Test', 2, N'No Replication/Sem replicação', N'Maintenance took over the task of changing the filters on the Dustex, being unfamiliar with the equipment that activates the Dustex, I created a sheet with clear instructions that''s next to the switch for reference if nobody is in the area to help assist them and to help eliminate the potential for the bump test not being performed.', N'To give workers clear instructions on bump testing equipment ', N'10113', N'01 - Imagens/01 - Antes/10116.jpeg', N'No instructions', N'01 - Imagens/02 - Depois/10116.jpeg', N'Clear instructions next to the switch on how to bump test in case no lab staff are in the area to assist.', NULL, N'Yes', N'When we completed this task, it was routine every 6 weeks, knowing the equipment and procedures.  During this early transitional period, it''s important to remember, for other people new to the task to be aware of the hazards and procedures who isn''t so familiar with the area and equipment.   ', 0, NULL, N'This activity has been reduced 10 minutes a time.', '2026-04-20T00:00:00.000', '2026-05-19T12:49:36.000', N'1008636', NULL, NULL);
INSERT INTO #PVC VALUES (10117, N'506255', N'506255', N'Dificuldade  de recebimento de gases', 1, N'No Replication/Sem replicação', N'Dificuldade em receber gases devido isolamentos da 
INSERT INTO #PVC VALUES (10118, N'548069', N'548069', N'Robô de Autopreenchimento', 1, N'Others/Outros', N'O processo de preenchimento manual dos campos de depósito e data de necessidade no SAP é realizado de forma repetitiva e suscetível a erros, gerando perda de tempo no planejamento, inconsistências nas informações e possíveis impactos na programação de materiais e execução da manutenção.', N'Automatizar o preenchimento dos campos de depósito e data de necessidade no SAP, reduzindo o tempo de processamento e eliminando erros manuais no planejamento de materiais.', N'10230', N'01 - Imagens/01 - Antes/10118.jpeg', N'O preenchimento dos campos de depósito e data de necessidade no SAP era realizado manualmente pelo planejador, exigindo tempo significativo em atividades repetitivas. Esse processo dependia da atenção do usuário, tornando-se suscetível a erros de digitação e inconsistências nos dados, além de causar retrabalhos e possíveis atrasos na programação de materiais e execução das manutenções.', N'01 - Imagens/02 - Depois/10118.jpeg', N'Após a implementação do script (robô), o preenchimento dos campos de depósito e data de necessidade passou a ser realizado automaticamente, eliminando atividades manuais e repetitivas. Com isso, houve redução significativa no tempo de planejamento, aumento da padronização das informações e eliminação de erros de digitação, tornando o processo mais ágil, confiável e eficiente.', NULL, N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (10119, N'548069', N'548069', N'Criação de Biblioteca de Desenhos Técnicos no Microsoft Teams', 3, N'Others/Outros', N'Desenhos técnicos armazenados em locais distintos (pastas locais, e-mails, SharePoint desorganizado)
INSERT INTO #PVC VALUES (10120, N'81054422', N'81048232', N'Dashboard Integrado de Confiabilidade Usina', 1, N'Others/Outros', N'O processo de análise de confiabilidade dos ativos de automação era realizado de forma descentralizada e pouco integrada, apresentando limitações', N'Desenvolver e implantar uma plataforma analítica integrada para suporte à tomada de decisão em engenharia de confiabilidade, consolidando indicadores e análises estatísticas avançadas diretamente no ambiente Power BI.', N'10081', N'01 - Imagens/01 - Antes/10120.jpeg', N'Análises distribuídas em múltiplas ferramentas (Excel, Minitab, relatórios manuais)
INSERT INTO #PVC VALUES (10121, N'1009872', N'1009872', N'Booster Pack & Tire pump storage', 1, N'Others/Outros', N'We have had tire pumps and battery boosters in the past, but they always go missing then aren''t available when we need them.', N'Prevent items from being taken', N'10240', N'01 - Imagens/01 - Antes/10121.jpeg', N'Before the booster pack and pump would be left in the corner of the coach''s office, where they could be taken without anyone knowing.', N'01 - Imagens/02 - Depois/10121.jpeg', N'Mounted a lockable cabinet on the wall in the coach''s office. Also added a sign-in sign-out sheet inside and locked the key inside the Permit office key repository.', NULL, N'N/A', N'N/A', 0, NULL, N'Reduzimos os riscos na atividade, durante a remoção do sensor, que após a melhoria não tem mais a necessidade', '2026-05-18T00:00:00.000', '2026-05-19T15:05:41.000', N'1009872', NULL, NULL);
INSERT INTO #PVC VALUES (10122, N'548069', N'548069', N'Padronização e criação de listas de tarefas no SAP para manutenção', 1, N'Others/Outros', N'Atualmente, as ordens de manutenção no SAP são criadas sem padronização de tarefas, resultando em variação na execução dos serviços, falta de detalhamento técnico, retrabalho no planejamento e dependência do conhecimento individual dos executantes. Essa ausência de listas de tarefas estruturadas impacta diretamente na qualidade das intervenções, na previsibilidade dos recursos e no tempo de execução das atividades.', N'Padronizar as atividades de manutenção através da criação de listas de tarefas no SAP, garantindo qualidade, redução de tempo no planejamento e maior confiabilidade na execução.', N'10230', N'01 - Imagens/01 - Antes/10122.jpeg', N'Atualmente, não há utilização de listas de tarefas padronizadas no SAP para as atividades de manutenção. As ordens são criadas de forma manual e variável, sem um padrão definido, o que gera retrabalho, inconsistência nas informações e dependência da experiência individual dos executantes.', N'01 - Imagens/02 - Depois/10122.jpeg', N'Com a implementação de listas de tarefas padronizadas no SAP, as ordens de manutenção passam a ser criadas com base em um modelo estruturado, contendo operações definidas, tempos, recursos e sequência lógica de execução. Isso elimina variações no planejamento, reduz retrabalho, aumenta a qualidade das intervenções e diminui a dependência do conhecimento individual dos executantes.', NULL, N'SIM
INSERT INTO #PVC VALUES (10123, N'520046', N'520046', N'Sistema de abastecimento de água bruta do lavador', 1, N'Others/Outros', N'O abastecimento de água dependia exclusivamente da caixa de água bruta principal da oficina que só liberava um terço da água para ser utilizado no lavador. gerando demora nos reabastecimento emergencial do lavador quando havia esvaziamentos dos tanques reservas para limpeza, ocasionando parada no lavador ate o nível ser restabelecido.', N'Garantir fornecimento contínuo, seguro e eficiente de água diretamente ao ponto de armazenamento (caixa d’água), reduzindo riscos e perdas no processo.', N'10139', N'01 - Imagens/01 - Antes/10123.jpeg', N'Dependência de uma única fonte com vazão limitada, causando demora no reabastecimento, baixa resposta em emergências e paradas do lavador durante recuperação de nível.', N'01 - Imagens/02 - Depois/10123.jpeg', N'Implantado abastecimento direto no tanque de reuso por caminhão-pipa, eliminando restrições de vazão. Processo padronizado, com mais controle, reduzindo paradas, garantindo maior disponibilidade e menor desperdício.', NULL, N'resolvido problema de dependência do sistema de água bruta da oficina.', N'Maior agilidade no processo de abastecimento', 0, NULL, N'Ganhos significativos na organização, comunicação e controle das atividades.', '2026-05-15T00:00:00.000', '2026-05-19T15:22:02.000', N'520046', NULL, NULL);
INSERT INTO #PVC VALUES (10124, N'81039085', N'81016655', N'PONTO DE COLETA PARA CONTROLE DE DENSIDADE ', 1, N'Others/Outros', N'A coleta de amostra na alimentação dos Filtros Prensa do Salobo I é realizada por turno para controle de densidade. Porém, os pontos de coleta são de difícil acesso, exigindo montagem de andaime.
INSERT INTO #PVC VALUES (10125, N'520046', N'520046', N'Relatório em tempo real de lavagens de equipamentos do lavador', 1, N'Others/Outros', N'Registros de lavagens via grupos de WhatsApp e inconsistentes, gerando retrabalho, falta de controle em tempo real, baixa confiabilidade dos dados e dificuldade na geração de relatórios e rastreabilidade dos equipamentos.', N'Implantar um sistema digital via celular para registro em tempo real das lavagens de equipamentos, com geração automática de relatórios em PDF, visando aumentar o controle operacional, eliminar registros manuais, melhorar a rastreabilidade e proporcionar tomada de decisão baseada em dados.”', N'10139', N'01 - Imagens/01 - Antes/10125.jpeg', N'Registros anteriores de lavagens eram feitas via grupo de WhatsApp sem padrão, causando erros, retrabalho, demora na consolidação, falta de controle em tempo real e baixa confiabilidade das informações.', N'01 - Imagens/02 - Depois/10125.jpeg', N'Implantação de registro digital em tempo real via celular, com dados padronizados e geração automática de PDF, aumentando controle, confiabilidade, produtividade, rastreabilidade e eliminando retrabalho.', NULL, N'O problema foi resolvido com a digitalização do processo, garantindo registros em tempo real, dados padronizados e relatórios automáticos, eliminando erros, retrabalho e melhorando o controle, a confiabilidade e a tomada de decisão.', N'Importância da digitalização para controle em tempo real Padronização melhora qualidade e confiabilidade dos dados Uso do celular aumenta agilidade e adesão da equipe Automação reduz retrabalho e erros manuais Dados em tempo real apoiam decisões mais rápidas Treinamento da equipe é essencial para sucesso da solução', 0, NULL, N'Aumento de confiabilidade de processos e eliminação de retrabalho na atividadade de troca de motores eletricos. ', '2026-05-13T00:00:00.000', '2026-05-19T16:02:16.000', N'520046', NULL, NULL);
INSERT INTO #PVC VALUES (10126, N'1009730', N'1009730', N'IR2 pH Probe Cleaning and Calibrating Station', 1, N'Others/Outros', N'Having all the necessary materials, buffers, cleaning aids and tools to facilitate IR2 pH probe troubleshooting in one designated area where all the pH probes are found saves time, and allows for quicker maintenance on the probes, thereby decreasing losses due to improper pH control of the circuit over a longer period of time.', N'To facilitate timely resolution of IR2 pH probe issues.', N'10223', N'01 - Imagens/01 - Antes/10126.jpeg', N'Prior to establishing a station with all materials required to effect pH probe troubleshooting located in the area where the probes are placed, the required materials would have to be collected from different locations in the plant, particularly any wrenches required.  This could be time consuming and delay the process of troubleshooting and fixing any issues.', N'01 - Imagens/02 - Depois/10126.jpeg', N'Set in place a table with the most required materials required to troubleshoot IR2 pH probes, and to clean and calibrate as required.', NULL, N'Yes as the central location of the required materials eliminates the need to search for these materials when troubleshooting is required.  Replacement of consumables can be done as time allows.', N'Having Materials Central speeds up troubleshooting and potentially minimizes associated losses.', 0, NULL, N'Aumento da produtividade e redução do tempo necessário para apresentação do FMDS', '2026-05-01T00:00:00.000', '2026-05-19T16:32:26.000', N'1009730', NULL, NULL);
INSERT INTO #PVC VALUES (10127, N'81062684', N'81062684', N'Glove Dispenser ', 2, N'Concentration/Concentração', N'Creating a designated decontamination zone to prevent excess dirt from entering 212 production and annex', N'Creating easy access to nitril gloves for cleaning the reclaim', N'0', N'01 - Imagens/01 - Antes/10127.jpeg', N'No easy access to nitril gloves while cleaning roll crusher. Have to go to annex for gloves. ', N'01 - Imagens/02 - Depois/10127.jpeg', N'Gloves have a proper storage area close to the reclaim for easy access.', NULL, N'Does not by itself fix the problem, but does play a part in the process of fixing it. ', N'How to put up a glove dispenser. ', 0, NULL, N'Aumento da confiabilidade operacional dos redutores das CFs
INSERT INTO #PVC VALUES (10128, N'81062684', N'81062684', N'Ear Plug dispenser ', 2, N'Concentration/Concentração', N'Creating a designated decontamination zone for cleaning the reclaim.', N'Having earplugs close to the reclaim for easy access.', N'0', N'01 - Imagens/01 - Antes/10128.jpeg', N'Earplugs were only available inside the annex. If you are in the reclaim and need earplugs you have to go back to the annex.', N'01 - Imagens/02 - Depois/10128.jpeg', N'Ear plugs are now put in a designated changing area outside the reclaim. Easily accessible for workers while cleaning the area. ', NULL, N'Earplug dispenser plays an important role in creating a designated changing area for reclaim cleaning. Being able to access hearing PPE is important for all workers.', N'Importance of hearing protection ', 0, NULL, N'melhora desempenho e mitigar desperdício ', '2026-05-16T00:00:00.000', '2026-05-19T22:47:06.000', N'81062684', NULL, NULL);
INSERT INTO #PVC VALUES (10129, N'87000312', N'87000339', N'Review of Bed ore filling method', 1, N'Refining/Refino', N'The process of filling the hopper with bed ore for the start-up was heavy duty and time-consuming.', N'Review of Bed ore filling method', N'0', N'01 - Imagens/01 - Antes/10129.jpeg', N'The process of filling the hopper with bed ore for the start-up was heavy duty and time-consuming.', N'01 - Imagens/02 - Depois/10129.jpeg', N'Installation of new piping from 2NOS BE, Bed ore is now automatically supplied.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Os resultados financeiros virão futuramente com e quantidade de itens parados no estoque reduzida, e menor quantidade de itens para possíveis baixa compulsória. ', '2026-05-18T00:00:00.000', '2026-05-19T23:27:05.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (10130, N'502383', N'502383', N'PORTINHOLA PARA ACESSO A BOMBA  DO SUMP DA FILTRAGEM', 1, N'Open Pit/Poço aberto', N'DIFICULDADE DE ACESSO A BOMBA DO SUMP PARA DAR MANUTENÇÃO.', N'FACILITAR ACESSO A BOMBA', N'10362', N'01 - Imagens/01 - Antes/10130.jpeg', N'Necessidade de uso do caminhão munck para retirar bomba do poço para dar manutenção simples por conta da proteção de Guarda corpo ser fixa e muito alta.   ', N'01 - Imagens/02 - Depois/10130.jpeg', N'Foi feito uma modificação e montado uma portinhola facilitando o acesso a bomba e em manutenções simples descartando a necessidade de uso de caminhão munck.', NULL, N'Maior agilidade na entrega das manutenções por conta da facilidade de manutenção com uso da portinhola.', N'redução de tempo em manutenções que não precisam mais do uso do caminhão munch, facilidade para acessar a bomba.', 0, NULL, N'Better compressor performance ', '2026-05-19T00:00:00.000', '2026-05-20T01:33:50.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (10131, N'81039895', N'1013316', N'SLN 5S table', 3, N'Refining/Refino', N'table was dirty and not up to our 5S standards', N'To 5S our SLN table', N'0', N'01 - Imagens/01 - Antes/10131.jpeg', N'Table is dirty and in need of a paint job and proper labeling for the tools/materials you need to discard of the bags. ', N'01 - Imagens/02 - Depois/10131.jpeg', N'New coat of paint applied to the table and proper labels were added to show where stuff belongs once you are finished with it or need to be replaced.', NULL, N'Yes, the table is now up to the 5S standard', N'5S', 0, NULL, N'This was especially helpful for training new technicians', '2026-05-19T00:00:00.000', '2026-05-20T10:23:09.000', N'81039895', NULL, NULL);
INSERT INTO #PVC VALUES (10132, N'81000072', N'81000072', N'Tomador de Pressão Bloco de 7 vias ', 1, N'Others/Outros', N'Remoção do sensor para instalar tomada de pressão para aferir pressão do bloco com manômetro', N'Produtividades ', N'10164', N'01 - Imagens/01 - Antes/10132.jpeg', N'Quando havia a necessidade de aferir a pressão do bloco de 7 vias, tinha que remover o sensor, instalar a tomada de pressão para assim aferir com manômetro e conflitar as pressão obtida antes com sensor.
INSERT INTO #PVC VALUES (10133, N'137489', N'137489', N'BI Pagamentos de Energia e Medições Corporativas', 1, N'No Replication/Sem replicação', N'Anteriormente, as informações mensais relacionadas aos pagamentos de energia e medições corporativas não eram disponibilizadas de forma sistematizada, sendo atendidas apenas sob demanda. Esse formato gerava dependência de solicitações pontuais e consumo significativo de horas de trabalho (HH) do colaborador responsável para levantamento, consolidação e envio dos dados.', N'Dar visibilidade aos processos de pagamento', N'10098', N'01 - Imagens/01 - Antes/10133.jpeg', N'A consolidação das informações era manual, em Excel e sob demanda, gerando dependência de atuação individual para compilação dos dados e consumo médio de 36 horas anuais de esforço operacional.
INSERT INTO #PVC VALUES (10134, N'81000072', N'81000072', N'Tomada de pressão do freio no Bloco DR/PR', 2, N'Others/Outros', N'Necessidade de remoção do sensor do freio para instalar tomada de pressão para aferir a pressão do freio com manometro', N'Produtividade e Segurança', N'10324', N'01 - Imagens/01 - Antes/10134.jpeg', N'Quando havia a necessidade de aferição real da pressão do freio, tinha que remover o sensor e instalar a tomada de pressão no bloco.', N'01 - Imagens/02 - Depois/10134.jpeg', N'Foi instalado um niple T com tomada de pressão na linha da pressão de freio, podendo aferir a pressão real pelo manômetro e a pressão demonstrada pelo sensor simultaneamente.', NULL, N'Para aferir a pressão, era necessário remover o sensor, tendo riscos de queimaduras devido ao oléo quente e ferimentos devido a pressões residuais no sistema. 
INSERT INTO #PVC VALUES (10135, N'97477', N'97477', N'Revestimento das moegas 2 e 3 com refis bipartido de HARDOX', 2, N'Crusher/Britadeira', N'
INSERT INTO #PVC VALUES (10136, N'512019', N'512019', N'Quadro Gestão de Manutenção Preventiva Pátio pinheiro.', 1, N'Others/Outros', N'“Antes da criação do quadro de gestão de manutenção, não havia um local definido para disponibilização do Project e de outras informações relevantes relacionadas à parada do equipamento.”', N'Definir Local para disponibilização de informação nas PMs', N'10324', N'01 - Imagens/01 - Antes/10136.jpeg', N'“Antes da criação do quadro de gestão de manutenção, não havia um local definido para disponibilização do Project e de outras informações relevantes relacionadas à parada do equipamento.”', N'01 - Imagens/02 - Depois/10136.jpeg', N'“Com a criação do quadro de gestão de manutenção, houve ganhos significativos na organização, comunicação e controle das atividades. A definição de um local específico para disponibilização do Project e demais informações relevantes da parada do equipamento proporcionou maior transparência no acompanhamento das etapas, facilitou a tomada de decisão e reduziu falhas de comunicação entre as equipes envolvidas. ', NULL, N'Sim, Resolvido.', N'Melhoria Continua', 0, NULL, N'Less slips on ladder', '2026-05-06T00:00:00.000', '2026-05-20T13:42:45.000', N'512019', NULL, NULL);
INSERT INTO #PVC VALUES (10137, N'608878', N'608878', N'entrance to level in the 153 OB', 3, N'Underground/Subterrâneo', N'levels to the 153 were not clearly labeled.  ', N'make it easier to navigate', N'10238', N'01 - Imagens/01 - Antes/10137.jpeg', N'paint was faded and hard for people to identify the levels. ', N'01 - Imagens/02 - Depois/10137.jpeg', N'repainted all the levels entrances to make it easier to navigate in the 153', NULL, N'yes', N'in time paint fades', 1, 3, NULL, '2026-05-19T00:00:00.000', '2026-05-20T13:52:17.000', N'608878', NULL, NULL);
INSERT INTO #PVC VALUES (10138, N'81034791', N'81034791', N'Otimização na Troca de Motores via Padronização com Checklist Técnico', 1, N'Others/Outros', N'A atividade de substituição de motores em campo apresenta falhas recorrentes devido à ausência de um processo padronizado de verificação técnica para seleção do equipamento adequado.', N'Aumento de confiabilidade de processos e eliminação de retrabalho na atividadade de troca de motores eletricos. ', N'10245', N'01 - Imagens/01 - Antes/10138.jpeg', N'A atividade de substituição de motores em campo apresenta falhas recorrentes devido à ausência de um processo padronizado de verificação técnica para seleção do equipamento adequado. Atualmente, a existência de múltiplos motores em estoque com características semelhantes, porém não equivalentes, aliada à falta de critérios estruturados de conferência, resulta na escolha incorreta do motor a ser instalado. Esse cenário ocasiona retrabalho, aumento do tempo de execução da manutenção, elevação do consumo de horas-homem (HH) e perda de produtividade operacional, além de expor a equipe a riscos adicionais decorrentes da repetição de atividades de montagem, desmontagem e içamento de cargas.', N'01 - Imagens/02 - Depois/10138.jpeg', N'Após a implementação de um checklist técnico padronizado para a substituição de motores em campo, o processo passou a contar com uma etapa estruturada de validação prévia, garantindo a compatibilidade entre o motor a ser instalado e as especificações do equipamento original. A aplicação do checklist, contemplando critérios como potência, tensão, corrente, rotação, tipo de carcaça e dimensões do eixo, assegura a conformidade técnica antes da execução, eliminando falhas na seleção. Como resultado, redução de retrabalho, diminuição do tempo de intervenção e do consumo de horas-homem (HH), além de maior confiabilidade do processo e redução da exposição a riscos associados à repetição de tarefas.', NULL, N'sim, foi reduzido exposição a riscos da equipe e retrabalho em atividades. ', N'Padronização de atividades, reduzem exposição a risco fisicos e ergonomicos. ', 0, NULL, N'Technicians will easily be able to know which bottles are full', '2026-05-19T00:00:00.000', '2026-05-20T15:16:55.000', N'81034791', NULL, NULL);
INSERT INTO #PVC VALUES (10139, N'547165', N'547165', N'Painel de consumo específico no FMDS', 1, N'Others/Outros', N'Ausência de um painel/dashboard único com todos os consumos específicos acumulados, sendo necessário abrir todos slides para verificar os status.', N'Agilizar o FMDS acerca dos consumos específicos dos insumos', N'10229', N'01 - Imagens/01 - Antes/10139.jpeg', N'Necessidade de abrir diversas telas para verificar quais insumos que estão acima do orçado', N'01 - Imagens/02 - Depois/10139.jpeg', N'Criação de um dashboard com indicadores visuais de identificação rápida, abrindo somente onde está ocorrendo o problema', NULL, N'Sim.
INSERT INTO #PVC VALUES (10140, N'81046426', N'81046426', N'DISPOSITIVO PARA PROTEÇÃO DOS REDENTORES DOS REDUTORES DAS CFs DE SALOBO III', 1, N'Others/Outros', N'Os retentores do eixo de entrada dos redutores estão apresentando falhas prematuras devido à elevada temperatura e pressão do ar proveniente do processo de flotação. Essa condição permite a passagem de ar para o interior do redutor, ocasionando a expulsão do óleo lubrificante. Como consequência, o equipamento opera sem lubrificação adequada, resultando em danos às engrenagens e rolamentos dos redutores.', N'Implementar solução para lubrificação e proteção dos retentores, evitando ressecamento, desgaste prematuro e falhas de vedação, garantindo a integridade do sistema, impedindo a entrada de ar no redutor e assegurando a lubrificação adequada dos componentes internos.', N'10031', N'01 - Imagens/01 - Antes/10140.jpeg', N'Os retentores do eixo de entrada dos redutores estão apresentando falhas prematuras devido à elevada temperatura e pressão do ar proveniente do processo de flotação. Essa condição permite a passagem de ar para o interior do redutor, ocasionando a expulsão do óleo lubrificante. Como consequência, o equipamento opera sem lubrificação adequada, resultando em danos às engrenagens e rolamentos dos redutores.', N'01 - Imagens/02 - Depois/10140.jpeg', N'Foi desenvolvido e instalado um dispositivo de proteção para os retentores dos redutores, permitindo a lubrificação contínua dos retentores superior e inferior. Essa solução mantém as vedações lubrificadas, reduzindo o ressecamento, o desgaste prematuro e a perda de eficiência de vedação, eliminando assim a  entrada de ar no interior do redutor.
INSERT INTO #PVC VALUES (10141, N'480642', N'480642', N'Rede de ar comprimido ', 1, N'Others/Outros', N'ausência de um ponto fixo de ar comprimido no box ', N'Eliminar deslocamento de pessoas e despedicio de tempo ', N'10324', N'01 - Imagens/01 - Antes/10141.jpeg', N'A mangueira de ar pneumático ficava distante do box. Sempre que necessário utilizar ar comprimido, o colaborador precisava se deslocar até o ponto de ar existente para buscar, conectar e estender mangueira longa até o local de trabalho.', N'01 - Imagens/02 - Depois/10141.jpeg', N'"Com um ponto de ar fixo no box, ganhamos rapidez, organização e segurança. Eliminamos o desperdício de tempo, deixamos a mangueira organizada e tiramos o risco de tropeço da área."', NULL, N'sim.
INSERT INTO #PVC VALUES (10142, N'81040056', N'81040056', N'Cockpit de Gestão de Mudanças de Materiais', 1, N'Projects/Projetos', N'O processo de gestão de mudanças de materiais apresentava baixa visibilidade consolidada e dependência de consolidação manual das informações. As solicitações estavam distribuídas em diferentes fontes, dificultando a identificação rápida do volume total, dos responsáveis pela tratativa, dos gargalos de aprovação e das demandas críticas. Como consequência, a coordenação tinha baixa previsibilidade operacional, dificultando a condução eficiente das reuniões semanais e comprometendo a priorização das atividades.', N'Mapeamento de materiais repotenciados/modificados ', N'10293', N'01 - Imagens/01 - Antes/10142.jpeg', N'A condição anterior do processo de gestão de mudanças de materiais era marcada por um cenário de baixa organização e pouca eficiência operacional. O acompanhamento das solicitações ocorria de forma descentralizada, sem padronização, o que fazia com que as informações ficassem dispersas em diferentes fontes. Essa fragmentação dificultava a consolidação dos dados e comprometia a visibilidade geral do processo.
INSERT INTO #PVC VALUES (10143, N'1015683', N'1015683', N'Coil Cleaner for Port Compressor ', 1, N'Others/Outros', N'The compressor was experiencing cooling issues due to the cooling coil being contaminated with dirt and debris buildup. The coil condition restricted the airflow and heat transfer efficiency, making it difficult to properly cool the compressor. This issue contributed to elevated operating temperatures and reduced system performance.  ', N'To correct the cooling issue with the compressor and to develop better ways to maintain the compressor. ', N'10284', N'01 - Imagens/01 - Antes/10143.jpeg', N'The compressor fan coil was heavily coated with dirt, dust and debris- this contamination was dense enough to restrict airflow through the coil, reducing cooling efficiency and causing the compressor to run at elevated temperatures. ', N'01 - Imagens/02 - Depois/10143.jpeg', N'A coil cleaning solution was implemented: A coil cleaner was ordered and is now part of operator rounds to ensure the coil is routinely inspected and cleaned before excessive buildup can occur. ', NULL, N'Yes, updated routines will not benefit and improve the compressor reliability. ', N'Preventative maintenance is important for all pieces of equipment.  ', 0, NULL, N'reduçao em 50% no tempo de diagnostico de falha ', '2026-05-01T00:00:00.000', '2026-05-20T22:59:08.000', N'1015683', NULL, NULL);
INSERT INTO #PVC VALUES (10144, N'460346', N'81062460', N'Sample Station Creation', 3, N'Refining/Refino', N'Lack of organization with samples', N'Stage an area with sample vials prepared and list of samples', N'0', N'01 - Imagens/01 - Antes/10144.jpeg', N'Just stacks of sample vials', N'01 - Imagens/02 - Depois/10144.jpeg', N'No mistaking samples required and vials are prepared for easy pickup', NULL, N'It''s easier at SOS to grab the vials you need for the samples', N'Being organized is helpful', 0, NULL, N'Saving on cost of sleeve each impeller change out', '2026-05-20T00:00:00.000', '2026-05-21T03:13:08.000', N'460346', NULL, NULL);
INSERT INTO #PVC VALUES (10145, N'400428', N'400428', N'2A water valve', 1, N'Concentration/Concentração', N'Water valve was not labelled ', N'Identify water valve', N'10058', N'01 - Imagens/01 - Antes/10145.jpeg', N'Valve was not labelled. Other valves in area, possibility of opening wrong valve.', N'01 - Imagens/02 - Depois/10145.jpeg', N'Water valve labelled to easily identify', NULL, N'Yes. Will not open the wrong valves.', N'Label', 0, NULL, N'Maior controle operacional do processo', '2026-05-20T00:00:00.000', '2026-05-21T03:15:46.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (10146, N'81007243', N'81013310', N'Prateleira para computador - Oficina', 3, N'Others/Outros', N'Foi disponibilizada uma mesa dentro da oficina para que os líderes utilizassem seus computadores em conjunto com a televisão. No entanto, a mesa permanecia frequentemente desorganizada, com bolsas, ferramentas e peças. Para solucionar essa situação, a mesa foi retirada. Porém, com essa decisão, o líder ficou sem um local adequado para utilizar o computador conectado à televisão, o que dificultou a exposição do cenário de máquinas paradas para a equipe.', N'Local adequado para uso do computador do líder dentro da oficina. ', N'10139', N'01 - Imagens/01 - Antes/10146.jpeg', N'Foi disponibilizada uma mesa dentro da oficina para que os líderes utilizassem seus computadores em conjunto com a televisão. No entanto, a mesa permanecia frequentemente desorganizada, com bolsas, ferramentas e peças. Para solucionar essa situação, a mesa foi retirada. Porém, com essa decisão, o líder ficou sem um local adequado para utilizar o computador conectado à televisão, o que dificultou a exposição do cenário de máquinas paradas para a equipe.', N'01 - Imagens/02 - Depois/10146.jpeg', N'Para sanar esse problema, foi confeccionado um suporte retrátil que comporta apenas o computador. Dessa forma, o recurso necessário para o líder permanece disponível e em funcionamento, além de garantir a manutenção dos padrões de 5S na área.', NULL, N'Para sanar esse problema, foi confeccionado um suporte retrátil que comporta apenas o computador. Dessa forma, o recurso necessário para o líder permanece disponível e em funcionamento, além de garantir a manutenção dos padrões de 5S na área.', N'Organização mantendo o recuso', 0, NULL, N'Realizar as manutenções das válvulas FV25 e FV27 sem parada da usina, com maior segurança, eliminação de riscos ergonômicos e maior agilidade nas intervenções, garantindo continuidade operacional.', '2026-05-16T00:00:00.000', '2026-05-21T04:09:11.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (10147, N'81007243', N'81003514', N'Placas de identificação caldeiraria ', 1, N'Others/Outros', N'Foi identificada a ausência de placas de sinalização indicativas de superfícies quentes em determinados equipamentos da área. Essa condição representa um risco potencial à segurança dos colaboradores, uma vez que não há alerta visual adequado para prevenir o contato acidental com superfícies de alta temperatura.
INSERT INTO #PVC VALUES (10148, N'1014251', N'1010297', N'Reverting Acid Work Instruction Update', 2, N'No Replication/Sem replicação', N'Procedure was not updated to reflect ramp ', N'To update work instruction to reflect improved procedure', N'0', N'01 - Imagens/01 - Antes/10148.jpeg', N'Work instruction reflected old method of running hoses which increased potential for spills', N'01 - Imagens/02 - Depois/10148.jpeg', N'Work instruction reflects new procedure which requires less connection area and lowers risk of hose failing/spillage ', NULL, N'Work instruction is now accurate, does not include old method of hose connections', N'Updating work instructions allows us to keep procedures current', 0, NULL, N'Resumo Geral da Atividade
INSERT INTO #PVC VALUES (10149, N'1014251', N'1014251', N'Grip Tape on Mixing Bowl Ladder', NULL, N'Others/Outros', N'Ladder had no grips, potential for slips', N'To improve grip and worker safety', N'10278', N'01 - Imagens/01 - Antes/10149.jpeg', N'Not much traction, potential for slips when ladder rungs got wet', N'01 - Imagens/02 - Depois/10149.jpeg', N'Added grip tape to rungs, enhance safety by providing friction points.  Minimize slips when rungs get wet, improves grip for boots and gloves.', NULL, N'Decreased risk of slipping from ladders by providing more grip for worker', N'Enhancing safety of ladders by adding grip', 0, NULL, N'Foi otimizado o tempo em 10 min. ', '2026-05-21T00:00:00.000', '2026-05-21T04:50:07.000', N'1014251', NULL, NULL);
INSERT INTO #PVC VALUES (10150, N'81046149', N'81006548', N'Proteção segura das correias', 2, N'Others/Outros', N'As correias da bomba encontravam-se sem proteção adequada, expondo os colaboradores ao risco de contato acidental com partes móveis do equipamento, podendo ocasionar acidentes e comprometendo a segurança operacional.', N'Eliminar o risco de contato com partes móveis, atender aos requisitos de segurança operacional e proporcionar um ambiente de trabalho mais seguro para os colaboradores.', N'10362', N'01 - Imagens/01 - Antes/10150.jpeg', N'As correias da bomba encontravam-se sem proteção adequada, expondo os colaboradores ao risco de contato acidental com partes móveis do equipamento, podendo ocasionar acidentes e comprometendo a segurança operacional.', N'01 - Imagens/02 - Depois/10150.jpeg', N'Realizada a fabricação e instalação da proteção das correias da bomba, garantindo maior segurança aos executantes das atividades e adequação das condições operacionais do equipamento.', NULL, N'[02:46, 21/05/2026] Leivisonlima86: Eliminar o risco de contato com partes móveis, atender aos requisitos de segurança operacional e proporcionar um ambiente de trabalho mais seguro para os colaboradores.
INSERT INTO #PVC VALUES (10151, N'1014251', N'1010297', N'Safety Shower Air Bottle Storage', 1, N'Others/Outros', N'No indication of full vs empty air bottles, potential for wasted time/effort to hook up an empty bottle because of no label', N'To clearly identify empty from full bottles', N'0', N'01 - Imagens/01 - Antes/10151.jpeg', N'No signage on air bottle cage near box culvert shower', N'01 - Imagens/02 - Depois/10151.jpeg', N'Signage to indicate which bottles are full and which are empty', NULL, N'Cage clearly labelled to indicate which bottles are empty and which are full', N'Clearly indications help prevent wasted time', 0, NULL, N'Resultado Esperado
INSERT INTO #PVC VALUES (10152, N'460346', N'1014901', N'Sample Point Glow-up', 2, N'Refining/Refino', N'Ni salts are building and not being cleaned properly by sample points.', N'Keep the area clean', N'10107', N'01 - Imagens/01 - Antes/10152.jpeg', N'Ni solution is being directed towards the drain and salts are building up and people are not cleaning them up because "the hose doesn''t reach up there"', N'01 - Imagens/02 - Depois/10152.jpeg', N'Hose was added to direct the flow of solution directly in the sump and eliminate the need for constant wash-up because there is no Ni being distributed around the floor.', NULL, N'Match', N'Simple solutions are still wins', 0, NULL, N'Garantir que o transporte de resíduos finos (sucata fina) seja realizado de forma segura, eficiente e padronizada, utilizando o carrinho caçamba adequado.
INSERT INTO #PVC VALUES (10153, N'1014251', N'1014251', N'Air Port Ladder Grip Tape', 1, N'Others/Outros', N'Rungs on ladder are slippery when covered with water or slurry, increasing potential for slips', N'To decrease chance of slips or falls', N'0', N'01 - Imagens/01 - Antes/10153.jpeg', N'Minimal grips on ladder rungs  ', N'01 - Imagens/02 - Depois/10153.jpeg', N'Grip tape added to ladder rungs', NULL, N'Added grip tape to ladder rungs.  Enhance safety by providing friction points.  Improves grip for boots and gloves when water or slurry on rungs', N'Providing grip on ladder rungs to prevent slips', 0, NULL, N'ganhos em qualidade ', '2026-05-20T00:00:00.000', '2026-05-21T05:05:56.000', N'1014251', NULL, NULL);
INSERT INTO #PVC VALUES (10154, N'1014251', N'1010297', N'Stretching Room', 1, N'Others/Outros', N'No area to properly stretch', N'Provide an area for stretching to prevent injuries at work', N'0', N'01 - Imagens/01 - Antes/10154.jpeg', N'No space for stretching', N'01 - Imagens/02 - Depois/10154.jpeg', N'Created a stretching room with equipment to improve employee wellness', NULL, N'Boosts employee wellness by reducing musculoskeletal pain, encourages movement in the workplace and helps prevent injuries in the workplace', N'Stretching to prevent injuries ', 0, NULL, N'Com a implantação do Bi, não teremos retrabalho.', '2026-05-20T00:00:00.000', '2026-05-21T05:18:53.000', N'1014251', NULL, NULL);
INSERT INTO #PVC VALUES (10155, N'1014251', N'1014251', N'Grip Tape on Baghouse Ladder', 1, N'Others/Outros', N'Not a lot of grip on ladder rungs, potential for slips, especially when rungs were wet ', N'To improve safety on ladder', N'0', N'01 - Imagens/01 - Antes/10155.jpeg', N'Not a lot of grip on ladder rungs', N'01 - Imagens/02 - Depois/10155.jpeg', N'Added grip tape to improve safety and prevent slips on baghouse ladder', NULL, N'Added grip tape to rungs, enhance safety by providing friction points.  Minimize slips when rungs get wet, improves grip for boots and gloves.', N'Grip tape to enhance safety on ladders', 0, NULL, N'Acompanhamento preventivo da performance operacional, e definição de ações para habilitar os resultados esperados(META).
INSERT INTO #PVC VALUES (10156, N'81015967', N'81015967', N'Monitoramento online das Subestações SLB 3', 1, N'Projects/Projetos', N'A rede Profibus da planta apresenta falhas recorrentes de comunicação, associadas a interferências eletromagnéticas, instalação inadequada e degradação física dos componentes. Cerca de 40% das redes estão em condição “aceitável baixa”, indicando risco de falhas intermitentes e perda de confiabilidade operacional.
INSERT INTO #PVC VALUES (10157, N'81046570', N'81046570', N'Stock code INDIVIDUAL parts of BUFFER TRAIN PUMP Shaft Sleeve kit', 1, N'No Replication/Sem replicação', N'Not all parts of the BUFFER TRAIN PUMP Shaft Sleeve Kit were needed each time impeller was changed (only gaskets and o-rings needed each change out; rarely the sleeve is needed)', N'Stock code the gaskets and o rings of BUFFER TRAIN PUMP Shaft Sleeve Kit', N'10092', N'01 - Imagens/01 - Antes/10157.jpeg', N'BUFFER TRAIN PUMP Shaft Sleeve Kit - there are three parts to this kit (sleeve, gaskets and o ring); only the gaskets and o ring were needed every impeller change out; rarely the sleeve needs changing', N'01 - Imagens/02 - Depois/10157.jpeg', N'I stock coded and requested, the INDIVIDUAL parts of the 3-part kit, so the sleeve did not need to be ordered as well each impeller change out', NULL, N'Yes, individual parts will be stocked and therefore ONLY these parts will be requested out of WHSE instead of the entire kit', N'Look at any parts that come as a ''kit'' and determine if all parts are needed each time', 1500, 3, N'Melhoria no processo de priorização de atividades de manutenção, tendo atividades programadas conforme seu impacto no ativo e no processo', '2026-05-20T00:00:00.000', '2026-05-21T09:03:22.000', N'81046570', NULL, NULL);
INSERT INTO #PVC VALUES (10158, N'81040303', N'81040303', N'Desenvolvimento de Controle de Processos e Performance - Filtragem', 1, N'Others/Outros', N'Inicialmente, o Salobo não havia indicadores de desempenho para a filtragem, o que impedia medir a eficiência das máquinas e comparar a performance entre filtros. Essa lacuna dificultava identificar se os desvios eram operacionais ou limitações dos equipamentos, comprometendo a análise das causas do não atingimento das metas produtivas.', N'Desenvolver Kpi''s de Gestão de Desempenho na Filtragem', N'10293', N'01 - Imagens/01 - Antes/10158.jpeg', N'No Salobo não havia de indicadores de desempenho para a filtragem, o que impedia medir a eficiência das máquinas e comparar a performance entre filtros. ', N'01 - Imagens/02 - Depois/10158.jpeg', N'O time realizou benchmarking com outras plantas da Vale para definição de indicadores. Foram criadas métricas, disponibilizadas em painel de gestão à vista para monitoramento do desempenho.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/4b8b6038-b3f2-4288-ab37-5d5b5ddd514c/638fa5a5dda466791066?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Inicialmente não existia controle operacional e após a implantação temos os controles de produtividade a nível de filtro.', N'Gerenciamento de Rotina', 0, NULL, N'A solução desenvolvida atendeu à meta inicial, promovendo maior controle da capacidade, ganho de eficiência operacional e padronização do processo.', '2026-03-30T00:00:00.000', '2026-05-21T09:50:26.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (10159, N'81061050', N'81014978', N'Válvula de bloqueio FV27/FV25', 2, N'No Replication/Sem replicação', N'Para fazer manutenção na válvula FV27 e FV25 era necessário fazer o bloqueio geral da válvula principal de abastecimento da usina de água de processo, diante disso essa manutenção so era realizada em Pit Stop.', N'Reduzir tempo de manutenção e exposição de pessoas ao risco.', N'10362', N'01 - Imagens/01 - Antes/10159.jpeg', N'Situação Anterior e Problemas Identificados
INSERT INTO #PVC VALUES (10160, N'471876', N'471876', N'ausência de proteção em partes rotativas', 2, N'Others/Outros', N'De fabrica eixo sem proteção.', N'eliminar risco ', N'10331', N'01 - Imagens/01 - Antes/10160.jpeg', N'No piso superior area dos lavadores de gases, veio de fabrica o neutralizador com eixo sem proteção, pensamos em uma saida imediata porém ainda com risco, isso contradiz nossas Rac,s e coloca em risco os Técnicos que ali fazem a dosagem de Hidróxido de sódio.', N'01 - Imagens/02 - Depois/10160.jpeg', N'Foi feito uma melhoria de proteção dentro das Rac,s onde protegeu com gaiola tipo tela, parafusado, assim eliminou o risco, deixando o ambiente seguro.', NULL, N'resolvido', N'que com olhar critico conseguimos proteger as pessoas.', 0, NULL, N'Elaborado um book de códigos de materiais, incluindo códigos de requisição e locais de instalação, visando otimizar o processo de aquisição e aumentar a visibilidade das informações.', '2026-05-21T00:00:00.000', '2026-05-21T11:34:02.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (10161, N'81061050', N'81040435', N'Proteção dos instrumentos 2251BP02.', 1, N'No Replication/Sem replicação', N'Quebra e disponibilidade do equipamento para operação.', N'Eliminar a quebra acidental do equipamento', N'10362', N'01 - Imagens/01 - Antes/10161.jpeg', N'Sistema de Água de Selagem (2251BP02)
INSERT INTO #PVC VALUES (10162, N'81022781', N'81022781', N'Melhoria no processo de reporte dos resultados de Magnésio (Mg)', 1, N'No Replication/Sem replicação', N'O envio dos resultados era realizado de forma manual, onde os dados eram compilados individualmente e enviados via WhatsApp, demandando maior tempo operacional, além de aumentar o risco de falhas de digitação, inconsistências e dificuldade na visualização de tendências dos resultados.', N'Otimizar o tempo de reporte de resultados ', N'10366', N'01 - Imagens/01 - Antes/10162.jpeg', N'O processo de reporte dos resultados de Magnésio (Mg) das usinas SLB 1, 2 e 3 era realizado manualmente. Após as análises laboratoriais, os resultados eram digitados individualmente e enviados via WhatsApp, e via Excel no e-mail para acompanhamento operacional. Esse método demandava maior tempo da equipe, além de apresentar algumas limitações, como:
INSERT INTO #PVC VALUES (10163, N'81061050', N'81027774', N'Proteção da area de bombas de águas de serviço e resfriamento do SAG. ', NULL, N'Others/Outros', N'Problemas Identificados – Segurança e Acesso à Área
INSERT INTO #PVC VALUES (10164, N'81061050', N'81046970', N'Escada de acesso ao Chiller e BA3053B02 e 02R.', 2, N'Others/Outros', N'Declaração do Problema
INSERT INTO #PVC VALUES (10165, N'81061050', N'81014978', N'Carrinho caçamba p/ transporte de resíduos finos ou seja sucata fina', NULL, N'No Replication/Sem replicação', N'Antes da implementação do carrinho tipo caçamba, o transporte de resíduos finos (sucata fina) era realizado de forma manual e improvisada, sem um equipamento adequado para a atividade.
INSERT INTO #PVC VALUES (10166, N'81046197', N'81046197', N'FABRICAÇÃO DE ESTRUTURA UNIDADE HIDRÁULICA ESPESSADOR', 1, N'Projects/Projetos', N'UNIDADE HIDRAULI S E ENCONTRA EM CONDIÇÕES DEGRADANTES DEVIDO ACUMULO DE SUJEIRA (RESÍDUOS) .', N'MELHORAR CONDIÇÃO DE ACESSO', N'10362', N'01 - Imagens/01 - Antes/10166.jpeg', N'Local sem uso , visto oportunidade para implantar melhoria', N'01 - Imagens/02 - Depois/10166.jpeg', N'Inicio de adequação do espaço para receber a unidade hidráulica', NULL, N'repotenciar sistema do espessador', N'Projetos implantados de forma interna', 0, NULL, N'Resultado esperado foi a eliminação de tempo ', '2026-06-30T00:00:00.000', '2026-05-21T14:05:50.000', N'81046197', NULL, NULL);
INSERT INTO #PVC VALUES (10167, N'81035576', N'81035576', N'BI de Gestão de Controle Rc, reserva,  Mob e desmob, MID ', 1, N'No Replication/Sem replicação', N'Não havia centralização adequada das informações relacionadas às requisições de compra, mobilização e desmobilização de equipamentos e MIDs. Os dados ficavam dispersos e sem rastreabilidade, o que dificultava o acompanhamento das atividades já realizadas.', N'Centralizar e estruturar das informações.', N'10337', N'01 - Imagens/01 - Antes/10167.jpeg', N'Não havia centralização adequada das informações relacionadas às requisições de compra, mobilização e desmobilização de equipamentos e MIDs. Os dados ficavam dispersos e sem rastreabilidade, o que dificultava o acompanhamento das atividades já realizadas.', N'01 - Imagens/02 - Depois/10167.jpeg', N'Desenvolvimento de um BI para acompanhamento, centralização e estruturação das informações de requisições de compra, mobilização e desmobilização de equipamentos e MIDs, assegurando maior rastreabilidade, organização e facilidade no monitoramento das atividades.
INSERT INTO #PVC VALUES (10168, N'81042188', N'81042188', N'Estruturação dos bancos de dados e reportes do CCO do Cobre e Carvão', 1, N'Others/Outros', N'O report anterior não fornecia informações estratégicas e projeções necessárias para acompanhar o ritmo das operações e antecipar riscos, comprometendo a eficiência e a previsibilidade dos embarques.
INSERT INTO #PVC VALUES (10169, N'81046197', N'81046197', N'PROTEÇÃO DE EQUIPAMENTOS ROTATIVOS ', 1, N'Others/Outros', N'EQUIPAMENTO SEM PROTEÇÃO', N'SEGURANÇA', N'10362', N'01 - Imagens/01 - Antes/10169.jpeg', N'equipamento com parte rotativa exposta', N'01 - Imagens/02 - Depois/10169.jpeg', N'instalada proteção tornando equipamento em operação mais seguro', NULL, N'segurança', N'ver e agir', 0, NULL, N'A ação implementada resolveu de forma simples e imediata a ausência de um ponto de descarte de pilhas e baterias, por meio do reaproveitamento de material. A solução eliminou custos, reduziu o tempo de resposta e melhorou a organização da área. Além disso, reforçou a efetividade de iniciativas simples na gestão de resíduos, evidenciando que pequenas melhorias podem gerar impactos positivos relevantes.
INSERT INTO #PVC VALUES (10170, N'81024177', N'81024177', N'Processo de Priorização de Backlog', 1, N'Others/Outros', N'Desenvolvido painel de priorização automatizada de BKL, de forma que as atividades já sejam organizadas conforme priorização, observando os critérios definidos pela gestão de ativos e descritos no VBM-PNR-000305 e VBM-PGS-007349.  Anteriormente estes processo era feio de forma manual e subjetiva, necessitando baixar planilhas, criar tabelas e filtros e por fim aplicar priorização manual da atividade. Com essa ferramenta as atividades já são priorizadas alincadas a critérios globais do CMA Vale, homologados e ativos, para atender a necessidade do ativo e dos processos, removendo o subjetivismo da operação.
INSERT INTO #PVC VALUES (10171, N'550519', N'550508', N'Melhoria na planilha de programação', 1, N'No Replication/Sem replicação', N'Havia dificuldade na visualização da capacidade disponível de HH (Homem-Hora) e na distribuição dos turnos, o que resultava em aumento no tempo de planejamento e tomada de decisão.', N'Otimização de tempo', N'10154', N'01 - Imagens/01 - Antes/10171.jpeg', N'Havia dificuldade na visualização da capacidade disponível de HH (Homem-Hora) e na distribuição dos turnos, o que resultava em aumento no tempo de planejamento e tomada de decisão.', N'01 - Imagens/02 - Depois/10171.jpeg', N'A planilha de solicitação de programação foi desenvolvida com o objetivo de otimizar o tempo de planejamento e melhorar a visualização da disponibilidade de HH (Homem-Hora), conforme a capacidade operacional.
INSERT INTO #PVC VALUES (10172, N'81063756', N'81063756', N'Ajustes  no Painel de Indicadores FMDS/RP da Coord Confiabilidade', 1, N'No Replication/Sem replicação', N'A planilha correspondente ao painel de indicadores de performance de frotas usada pela Coord de Confiabilidade estava apresentando divergências comparada ao BI de Performance de Ativos. Além disso, formatação condicional por cores de atingimento de meta não estava funcionando para algumas frotas. Esse problema estava levando os integrantes do time de processo a realizar manualmente a inserção de dados e formatação das células, o que levava a um grande desperdício de tempo toda semana, além de gerar desconfiança nos dados apresentados.', N'Fazer os indicadores de performance das frotas coincidir com os do BI e corrigir a lógica de Formatação Condicional das células da planilha', N'10015', N'01 - Imagens/01 - Antes/10172.jpeg', N'A planilha correspondente ao painel de indicadores de performance de frotas usada pela Coord de Confiabilidade estava apresentando divergências comparada ao BI de Performance de Ativos por não usarem a mesma base de dados. Além disso, formatação condicional por cores de atingimento de meta não estava funcionando para algumas frotas.', N'01 - Imagens/02 - Depois/10172.jpeg', N'Agora a base de dados da planilha é a mesma do BI, fazendo os indicadores convergirem. E a formatação condicional referente ao nível de aderência com as metas está funcionando normalmente para todas as frotas.', N'https://globalvale.sharepoint.com/:x:/s/CoordenaodeEngenhariadeConfiabilidadeSalobo/IQBQTFEMw91ISIqLTinrF3yQAdMqvlNZa88UVEgFhqbz2VU?e=253TjG', N'Os dois problemas principais de divergências de dados e inadequação de fórmula VBA de Macro foram resolvidos.', N'Substituição de base de dados em excel e edição de código VBA em Macro do excel', 0, NULL, N'Melhora de DF', '2026-05-20T00:00:00.000', '2026-05-21T15:06:34.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (10173, N'81018181', N'81018181', N'Book de materiais', 1, N'Others/Outros', N'Anteriormente, não possuíamos uma planilha contendo os materiais e os códigos de requisição organizados por local de instalação dos equipamentos.', N'melhorar a organização', N'10362', N'01 - Imagens/01 - Antes/10173.jpeg', N'Anteriormente, não possuíamos uma planilha contendo os materiais e os códigos de requisição organizados por local de instalação dos equipamentos.', N'01 - Imagens/02 - Depois/10173.jpeg', N'Elaborado um book de códigos de materiais, incluindo códigos de requisição e locais de instalação, visando otimizar o processo de aquisição e aumentar a visibilidade das informações.', NULL, N'META ALCANÇADA', N'MELHORIA', 0, NULL, N'- Redução de exposição de risco ergonómicos; eliminação da exposição ao calor e partes mecânicas: redução do tempo de atuação em entupimentos; menor esforço físico do operador; espaço adequado para movimentação.
INSERT INTO #PVC VALUES (10174, N'81046058', N'546472', N'Suporte de pódio - pedestal para notebook para trabalho em pé', 2, N'Others/Outros', N'Durante a atividade de conferência de materiais nos escaninhos dos equipamentos da Área de Backlog, foi identificada a necessidade de um equipamento auxiliar para apoiar o notebook, de modo a possibilitar a realização da conferência com menor risco ergonômico.', N'Reduzir a risco ergonômico nas atividades de conferencias de materiais.', N'10184', N'01 - Imagens/01 - Antes/10174.jpeg', N'A atividade de conferência foi realizada sob condições que exigiram esforço físico significativo, associado a uma postura inadequada. ', N'01 - Imagens/02 - Depois/10174.jpeg', N'Foi adquirido um dispositivo específico para alocar o notebook, com o objetivo de reduzir os riscos associados ao esforço físico excessivo e à postura inadequada durante a execução das atividades. Essa medida contribui para a melhoria das condições ergonômicas, promovendo maior segurança, conforto e eficiência no ambiente de trabalho.', NULL, N'Sim. O risco ergonômico associado ao processo de conferencia foi reduzido.', N'Essa medida contribuiu para a melhoria das condições ergonômicas, promovendo maior segurança, conforto e eficiência no ambiente de trabalho.', 0, NULL, N'Resultado dentro do esperado . ', '2026-03-02T00:00:00.000', '2026-05-21T15:15:59.000', N'81046058', NULL, NULL);
INSERT INTO #PVC VALUES (10175, N'81041209', N'81041209', N'Cálculo de sobressalentes utilizando confiabilidade', 1, N'Others/Outros', N'A definição de sobressalentes ocorre sem metodologia padronizada, baseada na experiência individual ou uso histórico. Isso gera decisões subjetivas e tendência ao superdimensionamento do estoque, elevando custos e reduzindo eficiência na alocação de recursos e gestão de materiais.', N'Metologia para definição de estoque', N'10293', N'01 - Imagens/01 - Antes/10175.jpeg', N'Redutor do acionamento do moinho Vertimil sem estoque, com um risco de 92% de uma parada no moinho devido essa ausência. Sem metodologia para definição desse equipamentos no estoque.', N'01 - Imagens/02 - Depois/10175.jpeg', N'Definição de um número de estoque para o redutor baseado em metodologia e probabilidade de falha, que pode ser aplicado para outros componentes críticos', NULL, N'O estoque foi definido e ajustado dentro do SAP, a metodologia poderá ser aplicada para outros componentes críticos', N'Utilização de confiabilidade para análise de sobressalentes', 0, NULL, NULL, '2026-04-30T00:00:00.000', '2026-05-21T15:17:59.000', N'81041209', NULL, NULL);
INSERT INTO #PVC VALUES (10176, N'547165', N'547165', N'Cofre Eletrônico Digital', 3, N'Others/Outros', N'Perdas de chaves, atrasos na abertura de salas de reunião e auditório, ausência de controle de acesso, levando ao descontrole de materiais estocados.', N'Controlar e agilizar o processo', N'10229', N'01 - Imagens/01 - Antes/10176.jpeg', N'Não existia controle efetivo das chaves do claviculário, gerando atrasos e perdas significativas tanto em produtividade quanto material.', N'01 - Imagens/02 - Depois/10176.jpeg', N'Foi implementado uma caixinha eletrônica digital para fazer o controle de acesso a chave do claviculário, reduzindo o tempo de espera de atendimento aos funcionários e fornecimento de materiais', NULL, N'Não há mais espera pelas chaves do claviculário. ', N'Redução do desperdício de tempo', 0, NULL, N'O BI está disponível e atualizado para consulta a informações relevantes para a tomada de decisão dos envolvidos,', '2026-05-18T00:00:00.000', '2026-05-21T15:42:02.000', N'547165', NULL, NULL);
INSERT INTO #PVC VALUES (10177, N'81046058', N'81006523', N'Readequação da Área de Preparação semanal S+1', 1, N'Others/Outros', N'Durante o processo de preparação da programação S+1 foi identificado que o espaço físico disponível não estava sendo suficiente para comportar a programação S+1 e a programação S (corrente), pois os materiais que ainda não haviam sido entregues da semana corrente acabavam se misturando com os que estavam sendo preparados para S+1 e dificultava a retirada, principalmente no turno noturno.', N'Expandir o espaço físico da área de alocação dos materiais da programação semanal', N'10184', N'01 - Imagens/01 - Antes/10177.jpeg', N'Espaço insuficiente para comportar a programação S+1 e a programação S (corrente), pois os materiais que ainda não haviam sido entregues da semana corrente acabavam se misturando com os que estavam sendo preparados para S+1 e dificultava a retirada, principalmente no turno noturno.', N'01 - Imagens/02 - Depois/10177.jpeg', N'Foi readequado um espaço físico (maior) para separar os materiais da preparação S (semana corrente) dos da preparação S+1, que permanecem na parte interna.', NULL, N'Para atender ao objetivo de expandir o espaço físico da área de alocação dos materiais da programação semanal, foi implementada a readequação da infraestrutura com a criação de uma estante externa de maior capacidade. Essa estante oferece o dobro de espaço em relação ao ambiente anterior e garante melhor visualização das ordens programadas.', N'Essa reorganização contribuiu para maior eficiência operacional e otimização do fluxo de trabalho.', 0, NULL, N'👉 Principais ganhos:
INSERT INTO #PVC VALUES (10178, N'544564', N'544564', N'Sistematização reserva de salas - Jequitibá', 3, N'Others/Outros', N'Reservas de salas eram realizadas manualmente pelo Outlook e apenas os responsáveis pela agenda “Jequitibá.agendamento.salas” conseguiam visualizar a disponibilidade e efetuar agendamentos. Essa limitação, somada ao alto volume de solicitações, tornava o processo pouco acessível e monótono, gerando desperdícios de “espera”, que variava de 15 a 30min.', N'Padronizar e automatizar o agendamento de salas, garantindo um processo rápido com eliminação de espera e retrabalhos gerados pelo método manual, até Janeiro/2026.', N'10337', N'01 - Imagens/01 - Antes/10178.jpeg', N'As reservas de salas eram realizadas manualmente pelo Outlook e apenas os responsáveis pela agenda “Jequitibá.agendamento.salas” conseguiam visualizar a disponibilidade e efetuar agendamentos. Essa limitação, somada ao alto volume de solicitações, tornava o processo pouco acessível e monótono, gerando desperdícios de “espera”, que variava de 15 a 30min, dependendo do tempo de resposta, tanto do responsável pelo agendamento, quanto pelo solicitante e o “defeito” na gestão de agendamentos, sendo um controle ineficiente, passivo de erros e falhas que resultavam em retrabalhos, gerando insatisfações.
INSERT INTO #PVC VALUES (10179, N'81006571', N'81021112', N'ESCADA AREA DE VIVENCIA', 2, N'Others/Outros', N'Antes quando abriamos o piso proxima a escada na região dos moinhos era preciso dar a volta em toda a usina para acessar a area dos moinhos', N'Reduzir tempos e movimentos de pessoas', N'10362', N'01 - Imagens/01 - Antes/10179.jpeg', N'Antes, quando abríamos os pisos na região das bolas 03, era necessário dar a volta em toda a usina para acessar o piso dos moinhos. Isso gerava desperdício de tempo e aumentava o cansaço da equipe devido ao longo deslocamento até as frentes de serviço. O trajeto extenso também elevava a exposição ao risco e reduzia a produtividade, já que parte do turno era consumida apenas com o deslocamento.', N'01 - Imagens/02 - Depois/10179.jpeg', N'Após a instalação da escada de acesso direto na região das bolas 03, o deslocamento até o piso dos moinhos foi otimizado. Eliminamos a volta completa na usina, reduzindo o tempo de trajeto, o cansaço da equipe e a exposição ao risco. Com isso, ganhamos mais agilidade e aumentamos o tempo disponível para execução das atividades.', NULL, N'Eliminado o tempo de espera', N'Desperdiçar tempo é necessario', 0, NULL, N'AUMENTO DE CONFIABILIDADE DO ATIVO', '2026-05-20T00:00:00.000', '2026-05-21T16:18:24.000', N'81006571', NULL, NULL);
INSERT INTO #PVC VALUES (10180, N'81049970', N'81049970', N'Mesa desaglomeradora', 2, N'Others/Outros', N'Um dos passos do processo de preparação de amostras de frente de lavra era a formação de pilha de amostra sobre uma bancada, foi realizada uma analise ergonômica do trabalho (AET), na qual foi observada a exigência de esforço físico, movimentos repetitivos e posturas incomodas durante longos períodos.', N'Automatização da tarefa de montagem de pilha', N'10082', N'01 - Imagens/01 - Antes/10180.jpeg', N'Um dos processos de análise de Geometal no laboratório físico consiste na formação de uma pilha alongada de 120 cm de extensão. Antes da melhoria, essa atividade era realizada manualmente com uma amostra de aproximadamente 14 kg. Utilizando uma bandeja, o trabalhador distribuía o material sobre a bancada de forma sequencial, movendo-se da esquerda para a direita e retornando da direita para a esquerda até completar toda a extensão necessária.
INSERT INTO #PVC VALUES (10181, N'81006571', N'81012464', N'CALHA SPOUT SAG', 1, N'Others/Outros', N'Antes possuiamos muita projeção de agua no sput, causando oxidação prematura do equipamento ', N'Eliminar vazamentos no SPOUT', N'10362', N'01 - Imagens/01 - Antes/10181.jpeg', N'Antes, havia intensa projeção de água no chute, o que causava oxidação prematura do equipamento e aumentava o risco de colapso estrutural. Essa condição também comprometia a segurança operacional, pois a corrosão acelerada poderia gerar falhas inesperadas e expor a equipe a acidentes graves durante a operação ou manutenção. ', N'01 - Imagens/02 - Depois/10181.jpeg', N'Após a instalação da calha de água, a projeção foi direcionada corretamente, eliminando o contato direto com a estrutura. Com isso, reduzimos a oxidação prematura, eliminamos o risco de colapso estrutural e aumentamos a segurança da equipe durante operação e manutenção.', NULL, N'Era necessario eliminar o vazamento, depois que foi instalado a calha foi eliminado', N'Melhorias são necessarias', 0, NULL, N'REDUÇÃO DE PARADA DO ATIVO', '2026-05-18T00:00:00.000', '2026-05-21T16:42:09.000', N'81006571', NULL, NULL);
INSERT INTO #PVC VALUES (10182, N'121608', N'121608', N'COLETOR DE PILHA E BATERIAS USADAS', 3, N'Others/Outros', N'Na  área não possuía coletor de pilhas, resultando na ausência de um local adequado para o descarte de pilhas e baterias usadas. ', N'Disponibilizar um ponto adequado para descarte de pilhas e baterias na área, de forma rápida, econômica e ambientalmente correta./Eliminar 100% do descarte inadequado de pilhas na área, implantando um coletor funcional com custo zero de aquisição.', N'10079', N'01 - Imagens/01 - Antes/10182.jpeg', N'O recipiente de sabão líquido seria descartado, enquanto a área não possuía coletor de pilhas, resultando na ausência de um local adequado para o descarte de pilhas e baterias usadas. Além disso, a solução convencional implicaria custos com a aquisição de um coletor, bem como tempo de espera para sua disponibilização.
INSERT INTO #PVC VALUES (10183, N'81058081', N'81058081', N'Redução de Riscos Operacionais por Operação Manual nos Britadores Primários', 1, N'Crusher/Britadeira', N'A operação dos britadores primários permitia intervenções manuais em condições críticas, incluindo ajustes sob carga, partidas e comandos fora do envelope seguro definido pela engenharia.  Não existiam barreiras sistêmicas eficazes para impedir comandos inadequados, permitindo que erros operacionais se convertessem diretamente em falhas do equipamento, com impacto potencial em segurança, integridade do ativo e estabilidade operacional.
INSERT INTO #PVC VALUES (10184, N'81004462', N'81004462', N'DIÁLISE REDUTOR DE GIRO PC5500', 1, N'Others/Outros', N'NÍVEIS ELEVADOS DE CONTAMINAÇÃO NO ÓLEO DOS REDUTORES DE GIRO', N'REDUÇÃO DE CONTAMINANTES', N'10015', N'01 - Imagens/01 - Antes/10184.jpeg', N'Redutores de giro com níveis elevados de contaminação no óleo do redutores de giro, gerando desgaste prematuro dos componentes internos equipamento.', N'01 - Imagens/02 - Depois/10184.jpeg', N'Realizado a implementação de do uso de diálise no óleo lubrificante dos redutores de giro, reduzindo os níveis de contaminação do óleo lubrificante do componente, evitando o desgaste prematuro dos componentes internos do equipamento.', NULL, N'O problema foi resolvido com a sistematização da diálise do óleo lubrificante a cada 500h de operação dos componentes.', N'Controle de contaminantes', 0, NULL, NULL, '2026-05-15T00:00:00.000', '2026-05-21T21:07:20.000', N'81004462', NULL, NULL);
INSERT INTO #PVC VALUES (10185, N'81004462', N'81004462', N'OTIMIZAÇÃO DE CICLOS', 1, N'Others/Outros', N'CICLOS DE MANUTENÇÃO COM TEMPO ELEVADO DE PARADA DE EQUIPAMENTO PARA MANUTENÇÃO, IMPACTANDO NA DF DA FROTA.', N'OTIMIZAÇÃO DE TEMPO DE MANUTENÇÃO', N'10015', N'01 - Imagens/01 - Antes/10185.jpeg', N'Tempo elevado na execução dos planos de manutenção, impactando na DF da frota. Além do elevado número de atividades sistemáticas nos planos de manutenção e elevado número de Hh para execução das atividades dos planos de manutenção.
INSERT INTO #PVC VALUES (10186, N'123307', N'81039417', N'Adequação de acesso seguro ao LSH da 2301 TC 02.', 2, N'Projects/Projetos', N'Na 2301 TC 02, quando ocorre atuação de entupimento de chute (LSH) e a correia é paralisada, o operador necessita realizar limpeza na janela de visita do LSH.A janela está localizada abaixo do acoplamento do motor da correia, fazendo com que o operador execute a atividade em posição não ergonômica, além de ficar exposto a:Risco de contato/vazamento de óleo do acoplamento;Exposição à temperatura elevada do motor;Dificuldade de acesso e movimentação durante a limpeza;aumento do risco de acidentes e fadiga operacional', N'Eliminar a condição de risco ergonómico ; Acesso rápido e seguro.', N'10054', N'01 - Imagens/01 - Antes/10186.jpeg', N'Na 2301 TC 02, quando ocorre atuação de entupimento de chute (LSH) e a correia é paralisada, o operador necessita realizar limpeza na janela de visita do LSH. A janela está localizada abaixo do acoplamento do motor da correia, fazendo com que o operador execute a atividade em posição não ergonômica, além de ficar exposto a:Risco de contato/vazamento de óleo do acoplamento;Exposição à temperatura elevada do motor;Dificuldade de acesso e movimentação durante a limpeza;aumento do risco de acidentes e fadiga operacional.', N'01 - Imagens/02 - Depois/10186.jpeg', N'Realizado reposicionamento da janela de visita do LSH da 2301 TC 02 para lado oposto ao acionamento da correia, eliminando exposição do operador ao acoplamento do motor, calor e postura inadequada durante atividades de limpeza e desobstrução do chute.', NULL, N'Sim, - Redução de exposição de risco ergonómicos; eliminação da exposição ao calor e partes mecânicas do acoplamento: redução do tempo de atuação em entupimentos; menor esforço físico do operador; espaço adequado para movimentação.
INSERT INTO #PVC VALUES (10187, N'480453', N'480453', N'Monitoramento eficiente temperaturas ', 1, N'No Replication/Sem replicação', N'Temperaturas do óleo e bucha dos Rebritadores se encontravam em tela secundária. ', N'Acompanhamento ', N'10054', N'01 - Imagens/01 - Antes/10187.jpeg', N'Temperaturas do óleo e bucha dos Rebritadores se encontravam em tela secundária. ', N'01 - Imagens/02 - Depois/10187.jpeg', N'Inserido temperaturas do óleo e bucha e óleo de retorno dos Rebritadores em tela primária do sistema de controle da Rebritagem ', NULL, N'Sim. Resolvido', N'Acompanhamentos. ', 0, NULL, NULL, '2026-05-21T00:00:00.000', '2026-05-22T03:46:58.000', N'480453', NULL, NULL);
INSERT INTO #PVC VALUES (10188, N'81058081', N'81058081', N'Controle de Condições Críticas e Mitigação de Ações Manuais nos Britadores Secundários', 1, N'Crusher/Britadeira', N'Permissão de operação manual em condições críticas, exigindo intervenção do operador fora do envelope ideal, com risco de falhas decorrentes de ações humanas sob pressão operacional.
INSERT INTO #PVC VALUES (10189, N'81063756', N'81063756', N'Melhorias no BI de Célula de Projetos - Salobo', 1, N'No Replication/Sem replicação', N'O BI não estava mais permitindo atualização. E a diferenciação entre projetos com e sem simulação não estava clara.', N'Resolver o impasse na atualização do BI e especificar projetos com e sem simulação', N'10015', N'01 - Imagens/01 - Antes/10189.jpeg', N'O BI não estava mais permitindo atualização, e estava atualizando dias atrás, atualizava com avisos. E a diferenciação entre projetos com e sem simulação não estava clara.', N'01 - Imagens/02 - Depois/10189.jpeg', N'O BI está atualizando por agendamento e sem avisos. E agora há diferenciação clara entre projetos com e sem simulação.', NULL, N'A atualização estava travada em função de valores nulos em coluna chave, o que foi mitigado.
INSERT INTO #PVC VALUES (10190, N'517429', N'517429', N'Automação da classificação de eventos de Equipamento em Stand by no GPV – Filtragem', 1, N'Others/Outros', N'Foi identificado um elevado volume de eventos de paradas de bombas disponíveis na área de Filtragem registrados no GPV. Esses eventos permaneciam abertos no sistema e exigiam atuação manual da sala de controle para classificação do status para Stand by, gerando retrabalho, risco de inconsistências e perda de tempo. 
INSERT INTO #PVC VALUES (10191, N'81047456', N'81047456', N'ABASTECIMENTO DE GRAXA EC-03', 2, N'Others/Outros', N'processo exigia elevado esforço físico dos colaboradores, aumentava o tempo da atividade e expunha a equipe a riscos ergonômicos, além da possibilidade de quedas durante a execução do abastecimento.', N'Segurança e Qualidade para execução do processo', N'10139', N'01 - Imagens/01 - Antes/10191.jpeg', N'O abastecimento de graxa da escavadeira elétrica EC03 era realizado através do puxamento manual da mangueira do comboio até a sala de lubrificação da máquina, utilizando cordas para auxiliar na subida da mangueira até a parte superior do equipamento.', N'01 - Imagens/02 - Depois/10191.jpeg', N'Com a implantação do KAIZEN, foram instalados 2 carretéis fixos na sala de lubrificação da escavadeira elétrica, permitindo que a mangueira permaneça posicionada na parte superior da máquina.
INSERT INTO #PVC VALUES (10192, N'535941', N'535941', N'ROLO PROTETOR', 1, N'Projects/Projetos', N'DURANTE INSPEÇÃO DA TR-2301SA-01, FOI IDENTIFICADO QUE A CORREIA ESTAVA DESALINHADA E ENTRANDO EM CONTATO COM A ESTRUTURA, NO MODOLO 23 LADO ESQUERDO, E COM ISSO TINHAMOS O RISCO DE RASGO DA CORREIA, DEVIDO A PERCA DAS BORDAS LATERAIS, QUE FRAGILIZAVAM O ATIVO.', N'AUMENTAR VIDA ÚTIL DA CORREIA', N'10031', N'01 - Imagens/01 - Antes/10192.jpeg', N'DURANTE INSPEÇÃO DA TR-2301SA-01, FOI IDENTIFICADO QUE A CORREIA ESTAVA DESALINHADA E ENTRANDO EM CONTATO COM A ESTRUTURA, NO MODOLO 23 LADO ESQUERDO, E COM ISSO TINHAMOS O RISCO DE RASGO DA CORREIA, DEVIDO A PERCA DAS BORDAS LATERAIS, QUE FRAGILIZAVAM O ATIVO.', N'01 - Imagens/02 - Depois/10192.jpeg', N'ABERTO NOTA DE MANUTENÇÃO PARA IMPLEMENTAÇÃO DE UM ROLO PROTETOR DE ESTRUTURA, ANTES DO MODULO, PARA QUE O MESMO PODESSE DESLOCAR A CORREIA RETIRANDO-A DO CONTATO COM A ESTRUTURA METÁLICA.  DESSA FORMA ELIMINANDO O RISCO DE RASGO DA CORREIA.', NULL, N'O PROBLEMA FOI SANADO POR COMPLETO.', N'AUMENTO DE CONFIABILIDADE DO ATIVO', 0, NULL, N'Pessoas abrissem e fechasse o portão com as mãos longe da linha de fogo.', '2026-05-04T00:00:00.000', '2026-05-22T14:03:00.000', N'535941', NULL, NULL);
INSERT INTO #PVC VALUES (10193, N'81010025', N'81010025', N'Implantação do Download de dados remoto dos caminhões transporte GP', 2, N'Others/Outros', N'Necessidade de Mão de obra para realizar coleta de dados (Download) dos caminhões grande Porte nas revisões de 250H.', N'Redução de risco e gerar relatórios de tendencia para redução de falhas', N'10081', N'01 - Imagens/01 - Antes/10193.jpeg', N'Realização de coleta de dados (Download) do caminhão GP com necessidade de mecânico ir até o caminhão e acessar sua cabine para baixar dados.', N'01 - Imagens/02 - Depois/10193.jpeg', N'Realização de coleta de dados (Download) de forma remota, SEM necessidade de mecânico ir até o caminhão e acessar sua cabine para baixar dados. Realizado Kaizen no ativo CM 4057', NULL, N'Problema solucionado', N'Sempre existe oportunidades para redução de exposição ao risco', 0, NULL, N'Conseguimos usar uma bateria que já temos dentro do armazém facilitando a requisição', '2026-05-20T00:00:00.000', '2026-05-22T14:15:26.000', N'81010025', NULL, NULL);
INSERT INTO #PVC VALUES (10194, N'81053351', N'535941', N'PROJEÇÃO CORRETA', 1, N'Projects/Projetos', N'FOI IDENTIFICADO DURANTE ROTA DE INSPEÇÃO, QUE A TR-2301SA-01 QUE SEU CHUTE DE DESGARGA, ESTAVA PROJETANDO MATERIAL PELA PARTE SUPERIOR FRONTAL, COM ISSO FOI ACUMULANDO MATERIAL NA DESCARGA NO CHUTE DO EXTRATOR, A PROJEÇÃO IRREGULAR ESTAVA ACONTECENDO, DEVIDO REPOTECIAMENTO DO CONJUNTO DO ACIONAMENTO.', N'AUMENTO DE PRODUTIVIDADE', N'10031', N'01 - Imagens/01 - Antes/10194.jpeg', N'FOI IDENTIFICADO DURANTE ROTA DE INSPEÇÃO, QUE A TR-2301SA-01 QUE SEU CHUTE DE DESGARGA, ESTAVA PROJETANDO MATERIAL PELA PARTE SUPERIOR FRONTAL, COM ISSO FOI ACUMULANDO MATERIAL NA DESCARGA NO CHUTE DO EXTRATOR, A PROJEÇÃO IRREGULAR ESTAVA ACONTECENDO, DEVIDO REPOTECIAMENTO DO CONJUNTO DO ACIONAMENTO.', N'01 - Imagens/02 - Depois/10194.jpeg', N'APÓS A IDENTIFICAÇÃO DO PROBLEMA, FOI REALIZADO A ABERTURA DE NOTA PARA O AUMENTO DA PARTE FRONTAL ENTRE O CHUTE DE DESCARGA DO TRANSPORTADOR E DO CHUTE DE DESCARGA DO EXTRATOR, COM O AUMENTO DA PARTE FRONTAL O MATERIAL NÃO SE PROJETOU PARA FORA DO CHUTE DO TRANSPORTADOR. FOI REALIZADO AUMENTO DE 300MM NA PARTE FRONTAL DO CHUTE.', NULL, N'SIM, SOLUÇÃO EFICAZ', N'REDUÇÃO DE PARADA DO ATIVO', 0, NULL, N'Espera-se aumentar a produtividade no tratamento da carteira de backlog, com maior volume de ordens trabalhadas e priorizadas corretamente dentro de cada faixa de tempo. A melhoria deve proporcionar redução do backlog envelhecido (principalmente >60 dias), melhor equilíbrio da carteira e maior fluidez no processo de programação. Como consequência, espera-se maior controle das atividades, aumento da eficiência operacional e uma gestão mais assertiva e proativa do backlog', '2026-05-05T00:00:00.000', '2026-05-22T14:16:14.000', N'81053351', NULL, NULL);
INSERT INTO #PVC VALUES (10195, N'535941', N'535941', N'DESVIANDO MATERIAL', 1, N'Projects/Projetos', N'DURANTE ROTA DE INSPEÇÃO, FOI IDENTIFICADO NO AL-2301SA-03, QUE O ATIVO PARAVA SEMANALMENTE, DEVIDO VAZAMENTO NAS GUIAS LATERAIS INFERIORES, QUE OCASIONAVA PARADAS CORRETIVAS E PERCA DE PRODUÇÃO.  EM UMA ANALISE MAIS APROFUNDADA FOI IDENTIFICADO, QUE O MATERIAL DE ALIMENTAÇÃO DO ALIMENTADOR TINHA ESCOAMENTO LATERAIS IGUAIS AO CENTRAL, E COM ISSO HAVIA PRENDIMENTO DE MATERIAL NAS GUIAS, QUE OCASIONAVA RASGO NA CORREIA OU VAZAMENTOS LATERAIS. ', N'REDUZIR PARADAS DO AL-2301SA-03', N'10031', N'01 - Imagens/01 - Antes/10195.jpeg', N'DURANTE ROTA DE INSPEÇÃO, FOI IDENTIFICADO NO AL-2301SA-03, QUE O ATIVO PARAVA SEMANALMENTE, DEVIDO VAZAMENTO NAS GUIAS LATERAIS INFERIORES, QUE OCASIONAVA PARADAS CORRETIVAS E PERCA DE PRODUÇÃO.  EM UMA ANALISE MAIS APROFUNDADA FOI IDENTIFICADO, QUE O MATERIAL DE ALIMENTAÇÃO DO ALIMENTADOR TINHA ESCOAMENTO LATERAIS IGUAIS AO CENTRAL, E COM ISSO HAVIA PRENDIMENTO DE MATERIAL NAS GUIAS, QUE OCASIONAVA RASGO NA CORREIA OU VAZAMENTOS LATERAIS. ', N'01 - Imagens/02 - Depois/10195.jpeg', N'APÓS IDENTIFICAÇÃO DO PROBLEMA, FOI REALIZADO A ABERTURA DE NOTA E COLOCADO EM PROGRAMAÇÃO, REALIZADO PROLONGAMENTO DO CHUTE DE ALIMENTAÇÃO NAS SUAS LATERAIS E PARTE TRASEIRA, AUMENTADO SUA SAIDA FRONTAL, FAZENDO COM QUE O MATERIAL SE DESLOCASSE MAIS PELO CENTRO DA CORREIA, DEIXANDO LIVRE AS GUIAS LATERAIS DE MATERIAL. ELIMINANDO ASSIM O RISCO DE RASGO NA CORREIA E VAZAMENTO NAS GUIAS.
INSERT INTO #PVC VALUES (10196, N'81038943', N'81038943', N'Lista de Sobressalentes - Unidade Hidráulica dos Moinhos Verticais', 1, N'Others/Outros', N'Conforme abordado em FMDS, o time de manutenção corretiva questionou a falta de informações e códigos dos componentes da unidade hidráulica dos moinhos verticais, impactando no tempo de intervenção no equipamento até encontrar o código do componente. ', N'Disponibilização de informação em tempo hábil para o time de manutenção ', N'10293', N'01 - Imagens/01 - Antes/10196.jpeg', N'Falta de informações para o time de manutenção corretiva em campo, sendo necessário apoio rotineiro do time de engenharia para providenciar os códigos dos componentes do sistema hidráulico', N'01 - Imagens/02 - Depois/10196.jpeg', N'Elaborado documento “Lista de Sobressalentes” com códigos VALE, part numbers, descrições e quantidades, garantindo ao time de manutenção todas as informações do sistema hidráulico.', NULL, N'Material disponível para manutenção eliminou a necessidade de apoio da engenharia para buscar códigos dos componentes do sistema hidráulico', N'Metodologias ágeis', 0, NULL, N'Sanar as perdas das ampolas e consequentemente garantir maior segurança no sistema anti-incêndio do equipamento.', '2026-05-21T00:00:00.000', '2026-05-22T14:35:53.000', N'81038943', NULL, NULL);
INSERT INTO #PVC VALUES (10197, N'81052333', N'81017007', N'suporte para mesa e prensa ', 2, N'Projects/Projetos', N'A atividade era realizada utilizando cavaletes desmontáveis
INSERT INTO #PVC VALUES (10198, N'81049526', N'81049526', N'Detecção antecipada de falhas em parafusos via Slow Motion', 1, N'Concentration/Concentração', N'A inspeção dos parafusos dos acoplamentos dos transportadores de correia era realizada apenas com o equipamento parado, o que impossibilitava a identificação precoce de afrouxamento ou início de cisalhamento. Como consequência, as falhas eram detectadas tardiamente, aumentando o risco de quebras, paradas não programadas e danos secundários aos equipamentos.', N'Reduzir falhas de acoplamentos por soltura e cisalhamento de parafusos por meio de inspeção preditiva com slow motion.', N'10293', N'01 - Imagens/01 - Antes/10198.jpeg', N'Durante a rotina de inspeção, o inspetor não avaliava a condição de possível soltura ou cisalhamento dos parafusos sob a condição dinâmica do acoplamento em operação. A análise ficava limitada à inspeção visual em equipamentos parados. 
INSERT INTO #PVC VALUES (10199, N'81011300', N'81011300', N'Sistema de Monitoramento de Contratos (SMC)', 1, N'Others/Outros', N'Com a reestruturação da área de Metais Básicos, a gestão matricial de contratos foi desdobrada em três frentes distintas, gerando a necessidade de um sistema capaz de consolidar as informações de contratos de forma integrada. Ao mesmo tempo, esse sistema precisa permitir a personalização por local, atendendo às particularidades de cada operação, além de oferecer flexibilidade por meio de um ambiente no-code, que viabilize adaptações rápidas e autônomas pelas equipes.', N'Desenvolver sistema para consolidar e controlar informações de contratos em Metais Básicos.', N'10098', N'01 - Imagens/01 - Antes/10199.jpeg', N'Havia um único app para BMSA, com funcionalidades hardcoded e sem controle de perfis: todos podiam alterar qualquer cadastro. A carga de contratos era complexa e realizada apenas em casos críticos.', N'01 - Imagens/02 - Depois/10199.jpeg', N'Sistema centralizado implantado, com controle de acesso por perfil e personalização por local em ambiente no-code, tornando a gestão de contratos mais ágil, padronizada e segura.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/74344e31-2ee7-41ef-a290-323fec0ba8d3?hidenavbar=true&amp;tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&amp;sourcetime=1750687665775&amp;source=portal#', N'Ao disponibilizar um sistema capaz de consolidar e controlar informações de contratos de forma integrada,  incorporar controle de acessos, padronização e flexibilidade com personalização no-code, elevando a eficiência e a segurança da gestão resolvemos os principais problemas declarados.', N'A importância de definir perfis de acesso para garantir governança e segurança dos dados, além de evidenciar que soluções low-code aumentam a agilidade e autonomia das áreas. Também ficou claro que a padronização inicial reduz retrabalho na consolidação de dados, enquanto o envolvimento dos usuários desde o início melhora a aderência do sistema. Por fim, observou-se que a flexibilidade deve equilibrar personalização e controle central, e que a automatização de cargas reduz esforço manual e erros operacionais.', 0, NULL, N'Além de segurança alcançada também tivemos melhoria em produção rapidez em diagnóstico da equipe de operação.    ', '2026-03-31T00:00:00.000', '2026-05-22T16:01:32.000', N'81011300', NULL, NULL);
INSERT INTO #PVC VALUES (10200, N'81052333', N'81014733', N'Suporte para Tote Bin', 2, N'Crusher/Britadeira', N'❌Postura inadequada (antes da elevação)
INSERT INTO #PVC VALUES (10201, N'81053351', N'535941', N'ROLO PROTETOR ', 1, N'Projects/Projetos', N'DURANTE INSPEÇÃO, FOI IDENTIFICADO QUE A CORREIA DA TR-2301SA-01 ESTAVA DESALINHADA, DESSA FORMA TENDO CONTATO DIRETO COM A ESTRUTURA, NO MODOLO 23 AO LADO ESQUERDO. NESSA CONDIÇÃO, A CORREIA APRESENTAVA RISCO DE RASGO, POR CONTA DA PERCA DAS BORDAS LATERAIS. ', N'AUMENTAR VIDA UTIL DA CORREIA', N'10031', N'01 - Imagens/01 - Antes/10201.jpeg', N'DURANTE INSPEÇÃO, FOI IDENTIFICADO QUE A CORREIA DA TR-2301SA-01 ESTAVA DESALINHADA, DESSA FORMA TENDO CONTATO DIRETO COM A ESTRUTURA, NO MODOLO 23 AO LADO ESQUERDO. NESSA CONDIÇÃO, A CORREIA APRESENTAVA RISCO DE RASGO, POR CONTA DA PERCA DAS BORDAS LATERAIS. NESSE LOCAL NÃO HAVIA NENHUM COMPONENTE QUE CONTRIBUIA PARA MELHORIA DESSA CONDIÇÃO.', N'01 - Imagens/02 - Depois/10201.jpeg', N'FOI ABERTO UMA NOTA DE MANUTENÇÃO PARA IMPLEMENTAÇÃO DE UM ROLO PROTETOR DE ESTRUTURA, ANTES DO MODULO, PARA QUE O MESMO PODESSE DESLOCAR A CORREIA, RETIRANDO-A DO CONTATO COM A ESTRUTURA METÁLICA. COM A IMPLEMENTAÇÃO DESSE COMPONENTE, FOI POSSÍVEL ELIMINAR ESSA CONDIÇÃO, EVITANDO O RISCO DE RASGO DA CORREIA. ', NULL, N'SIM, O PROBLEMA FOI SANADO POR COMPLETO.', N'AUMENTO DE CONFIABILIDADE DO ATIVO', 0, NULL, N'Used for the rest of the ball mills in the concentrator', '2026-05-05T00:00:00.000', '2026-05-22T16:03:46.000', N'81053351', NULL, NULL);
INSERT INTO #PVC VALUES (10202, N'81061038', N'124132', N'Ontario Operational Excellence dashboard', 1, N'No Replication/Sem replicação', N'It is not easy to find all the links and information related to operation excellence for Ontario Operations. Employees would usually message me to ask for where to find the kaizen app or the templates.', N'Provide a one-page dashboard for all Ontario employees so they can easily find the kaizen app, templates related to Performance and Continuous Improvement and so on.', N'10238', N'01 - Imagens/01 - Antes/10202.jpeg', N'Employees would need to bookmark all the links they need related to operational excellence, e.g., kaizen app, A3 template, and so on. They would usually message me to ask for the information. This wastes time for looking for information and waiting for me to answer them back.', N'01 - Imagens/02 - Depois/10202.jpeg', N'There is now a SharePoint dashboard for everything Ontario operational excellence related. Any Ontario employee can now go to one page to go to VBM CI site, kaizen app, find templates on performance meetings, A3, etc. This page also shows a quick guideline on the types of CI initiatives as well as the Assurance Calendar from CTO Operating Model team.', NULL, N'Yes', N'Utilize technology to optimize the flow of information to employees', 0, NULL, N'Otimizar a realização de abertura e fechamento da válvula e 
INSERT INTO #PVC VALUES (10203, N'81004462', N'81058516', N'OTIMIZAÇÃO DE INSPEÇÃO DE FPS', 1, N'Others/Outros', N'Perda de DF por paradas de manutenção a cada 125h de manutenção para avaliação de FPS.', N'OTIMIZAÇÃO DE PROCESSO', N'10015', N'01 - Imagens/01 - Antes/10203.jpeg', N'Perda de DF por paradas de manutenção a cada 125h de manutenção para avaliação de FPS, gerando uma perda anual de 0,25% de DF.', N'01 - Imagens/02 - Depois/10203.jpeg', N'Após a implantação do sistema de monitoramento de FPS, foi eliminado a necessidade de parada dos equipamentos a cada 125h para inspeção de FPS.', NULL, N'PROBLEMA RESOLVIDO, APÓS A MELHORIA DE PROCESSO, GERANDO GANHOS DE DF E SEGURANÇA', N'OTIMIZAÇÃO DE PROCESSOS', 0, NULL, N'Otimizar a realização de abertura e 
INSERT INTO #PVC VALUES (10204, N'515697', N'485334', N'Saia da Mesa Frontal da Mesa de Perfuração', 1, N'Others/Outros', N'A saia da mesa de perfuração tinha um acionamento com cilindro hidráulico, que vinha a danificar com facilidade devido colisões durante as locomoções nas leiras e devido ao solo irregular.', N'Diminuir número de falhas no sistema ', N'10150', N'01 - Imagens/01 - Antes/10204.jpeg', N'A saia da mesa tinha um acionamento através de dois cilindro hidráulicos que devido as colisões em leras durante a locomoção vinham a empenar e danificar a estrutura e os cilindros, vindo a causar várias falhas no conjunto da mesa. ', N'01 - Imagens/02 - Depois/10204.jpeg', N'Foi removido toda a estrutura de acionamento hidráulico da mesa frontal e instalado a saia diretamente na base, eliminando os cilindros e base onde vinham a empenar e causas falhas repentinas nesse conjunto.
INSERT INTO #PVC VALUES (10205, N'81046954', N'81046954', N'Fechamento Seguro', NULL, N'Concentration/Concentração', N'Ausência um puxador para abrir e fechar o portão da ferramentaria.', N'Instalar um puxador para abrir e fechar o portão', N'10362', N'01 - Imagens/01 - Antes/10205.jpeg', N'Ausência de puxador no portão de grande porte da ferramentaria, expondo as pessoas ao risco de pensamento dos dedos ao fechar  o portão.', N'01 - Imagens/02 - Depois/10205.jpeg', N'Foi instalado um puxador para o portão, como que de forma segura com os dedos longe da linha de fogo para abrir e fechar o portão . ', NULL, N'Foi alcançado a meta, pois agora as pessoas fecham e abrem o portão de forma segura.', N'aréa mais segura.', 0, NULL, N'Otimizar atividades de limpeza industrial e eliminar condições ergonômicas de sobrecarga ao ter que substituir mangueiras . ', '2026-05-21T00:00:00.000', '2026-05-22T17:43:46.000', N'81046954', NULL, NULL);
INSERT INTO #PVC VALUES (10206, N'515697', N'81055398', N'Alteração do Tipo de Bateria ', 1, N'Others/Outros', N'As baterias do equipamento não estão em contrato e não tem em estoque.', N'Reduzir custo com material estocável', N'10150', N'01 - Imagens/01 - Antes/10206.jpeg', N'As baterias do equipamento não estão em contrato e não tem disponibilidade para a aquisição.', N'01 - Imagens/02 - Depois/10206.jpeg', N'Foi instalado baterias CAT já incluído em contrato e estocável dentro  do armazém facilitando a requisição.
INSERT INTO #PVC VALUES (10207, N'510839', N'510839', N'Padronização e Otimização Visual do Painel de Gestão de Backlog (Carga e Perfuração)', 1, N'Others/Outros', N'O painel anterior de controle de backlog apresentava excesso de informações não estruturadas, baixa padronização visual e dificuldade na leitura analítica, impactando diretamente na tomada de decisão e não possuía os indicadores de quantidades de ordens por tempo na carteira.', N'Melhorar a eficiência da gestão do backlog através de: Aumento da clareza e foco nos indicadores críticos', N'10023', N'01 - Imagens/01 - Antes/10207.jpeg', N'O excesso de gráficos e informações simultâneas gerava poluição visual e aumentava o tempo necessário para interpretação, tornando a análise lenta e pouco eficiente. Além disso, não havia padronização visual adequada (cores, layout e estrutura), o que dificultava a identificação rápida de situações de alerta ou criticidade. Também não existia uma visualização clara da quantidade de ordens de manutenção segmentadas por categorias de tempo, comprometendo a análise do envelhecimento do backlog e a priorização das atividades.', N'01 - Imagens/02 - Depois/10207.jpeg', N'Após a melhoria, o painel foi reorganizado com foco em clareza, padronização e tomada de decisão ágil. As informações passaram a ser apresentadas de forma estruturada, com redução da poluição visual e melhor hierarquia dos indicadores. Destaca-se a inclusão de um indicador visual consolidado que apresenta o quantitativo de ordens de manutenção por faixa de tempo (até 30 dias, entre 30 e 60 dias e acima de 60 dias), permitindo rápida identificação do envelhecimento do backlog e das ordens críticas. Com isso, a análise tornou-se mais intuitiva, facilitando a priorização das atividades e aumentando a eficiência na gestão do backlog.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/b4d13340-ce3a-4f7e-93eb-76346dc03217/ReportSectioneebbbf71a6c998490640?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'A melhoria possibilitou maior eficiência no tratamento da carteira de backlog, com aumento da produtividade no direcionamento e programação das ordens de manutenção. A nova visualização permitiu identificar rapidamente as ordens por faixa de tempo, priorizando aquelas com maior criticidade, o que resultou em redução do backlog envelhecido e melhor equilíbrio da carteira.
INSERT INTO #PVC VALUES (10208, N'81040876', N'81048568', N'Melhoria de acesso', 2, N'Others/Outros', N'Havia dificuldade e riscos ergonômicos durante atividades no selador de argamassa PS720_01. Não tinham acessos e durante movimentações de peças para manutenção do equipamento, as mesmos eram lançados por sobre o guarda corpo.', N'Melhorar acesso e eliminar risco ergônomico', N'10170', N'01 - Imagens/01 - Antes/10208.jpeg', N'Havia dificuldade e riscos ergonômicos durante atividades no selador de argamassa PS720_01. Não tinham acessos e durante movimentações de peças para manutenção do equipamento, as mesmos eram lançados por sobre o guarda corpo.', N'01 - Imagens/02 - Depois/10208.jpeg', N'Foi fabricada e instalada portinhola, criando acesso seguro e controlado.', NULL, N'Sim, problema resolvido, risco ergonômico eliminado.', N'Importância da melhoria continua.', 0, NULL, N'Com a implementação do filtro no App de Alertas, espera-se garantir maior visibilidade e controle sobre as ações de lubrificação em contingência, assegurando a identificação e o acompanhamento de 100% dessas atividades.', '2026-05-16T00:00:00.000', '2026-05-22T18:48:21.000', N'81040876', NULL, NULL);
INSERT INTO #PVC VALUES (10209, N'699694', N'81006744', N'SUPORTE PARA AMPOLA DO SISTEMA AFEX', 1, N'Others/Outros', N'Quando o equipamento parava para suas preventivas e eram feitas suas inspeções de entrada; notava-se quase sempre que a fixação padrão da ampola não estava sendo eficaz, pois as com as decorrentes trepidações durante a operação ou locomoção acabava se perdendo, dessa forma, vimos a oportunidade de melhorar a segurança na fixação desse equipamento tão crucial na prevenção de incêndios e tivemos a ideia de confeccionar um suporte que deixasse a ampola totalmente protegida e sustentada e claro com o acesso em caso de necessidade também facilitado.', N'IMPEDIR QUE COM A TREPIDAÇÃO DO EQUIPAMENTO EM LOCOMOÇÃO OU OPERAÇÃO A AMPOLA SEJA PERDIDA , AVARIADA  OU DEFLAGRADA ACIDENTALMENTE', N'10144', N'01 - Imagens/01 - Antes/10209.jpeg', N'COM AS TREPIDAÇÕES SOFRIDAS PELO EQUIPAMENTO DURANTE OPERAÇÃO OU MESMO LOCOMOÇÃO ERA PERDIDA A AMPOLA DO SSITEMA AFEX DE COMBATE À INCENDIOS; DEIXANDO ASSIM O RISCO DE INCENDIO MAIS EVIDENTE, NO CASO DE UMA NECESSIDADE/EMERGENCIA', N'01 - Imagens/02 - Depois/10209.jpeg', N'- ELIMINAÇÃO TOTAL DA PERDA DESSE ITEM TÃO CRUCIAL PARA ELIMINAÇÃO DE INCENDIOS;
INSERT INTO #PVC VALUES (10210, N'524950', N'81058981', N'Bomba BA-2020SA-24 - Aumento de rigidez estrutural', 1, N'Projects/Projetos', N'Constantes quebras da Bomba BA-2020SA-24, tendo como principal modo de falha, vibração estrutural decorrente de grau de liberdade do Skid de fixação da  bomba a base civil.', N'Reduzir vibração, eliminar causa fundamental de falhas', N'10293', N'01 - Imagens/01 - Antes/10210.jpeg', N'Vibração acima do admitido causando danos aos parafusos do sistema de fixação e desgaste prematuro de componentes causando quebras da bomba e interrupção no processo produtivo.', N'01 - Imagens/02 - Depois/10210.jpeg', N'
INSERT INTO #PVC VALUES (10211, N'533479', N'533479', N'Inovação', 1, N'Others/Outros', N'Falha na dosagem automática do floculante.', N'Eficiência e redução de desperdício ', N'10054', N'01 - Imagens/01 - Antes/10211.jpeg', N'Anteriormente, utilizávamos uma planilha física plastificada para conversão para dosagem de floculante. ', N'01 - Imagens/02 - Depois/10211.jpeg', N'Devido ao alto risco de perda ou dano das informações, decidimos instalar a planilha na tela do supervisório, garantindo maior segurança e integridade dos dados.', NULL, N'Anteriormente, utilizávamos uma planilha física plastificada para conversão para dosagem de floculante. ', N'Sempre podemos melhorar', 0, NULL, NULL, '2026-05-20T00:00:00.000', '2026-05-22T21:30:24.000', N'533479', NULL, NULL);
INSERT INTO #PVC VALUES (10212, N'537635', N'537635', N'Melhor acesso e confiança ', 2, N'Projects/Projetos', N'Durante uma inspeção no chute de transferência da 2301-TC-02 foi identificado que a Portiola do chute estava acumulando bastante material, como melhoria de segurança e melhorar na manutenção elétrica mecânica e inspeção do time de operação foi mudado  para o outro lado o sensor e portiola, com a aprovação da engenharia.  ', N'ELIMINAR A CONDIÇÃO INSEGURA', N'10245', N'01 - Imagens/01 - Antes/10212.jpeg', N'2301-TC-02  Parou por LSH entupimento de chute, ao chegamos  no local  foi identificado  o sensor  com bastante  material a maior  dificuldade  era chega  no sensor  devido  a portiola  do chute  ser em um lugar  de difícil  acesso, ela fica  debaixo  do motor  de acionamento.', N'01 - Imagens/02 - Depois/10212.jpeg', N'para  resolver  esse problema e tirar  essa dificuldade  com o acesso resolvemos  mudar  o projeto  com a aprovação  da engenharia e fábrica uma nova  portiola do lado direito  sentido  fluxo , lado oposto  do motor sendo assim  tirando  toda a dificuldade  em inspecionar  e também  realizar  manutenção  no sensor,  realizamos  também  a mudança  dos eletrodutos e cabeamento  de alimentação  do sensor,  foi  finalizado  realizado  testes e conjunto  com o time de operação  e liberado  o equipamento.', NULL, N'Sim, foi resolvido e com esse projeto facilitou bastante nas manutenções e inspeções. ', N'Ver e Agir.', 0, NULL, NULL, '2026-05-22T00:00:00.000', '2026-05-23T01:59:34.000', N'537635', NULL, NULL);
INSERT INTO #PVC VALUES (10213, N'537635', N'537635', N'Melhorando a confiabilidade do processo', 1, N'Others/Outros', N'Durante inspeção no instrumento, foi identificado que a controladora apresentava desregulagens frequentes.', N'Melhorando a condição, e segurança no possesso. ', N'10245', N'01 - Imagens/01 - Antes/10213.jpeg', N' 2251-FIQ-01 – Durante inspeção no instrumento, foi identificado que a controladora apresentava desregulagens frequentes com isso a intensidade de água do Sag estava desregulados.    ', N'01 - Imagens/02 - Depois/10213.jpeg', N'Como melhoria foi instalada uma válvula solenoide temporizadora para controle da densidade da água e ajuste do tempo de atuação, proporcionando maior precisão e estabilidade ao processo.', NULL, N'Sim, Ate o momento esta normalizado a condição do tempo de temporização de agua do SAG.', N'Ver e Agir.', 0, NULL, N'In-house rebuild capability of Area Maintenance Crews', '2026-05-22T00:00:00.000', '2026-05-23T03:20:45.000', N'537635', NULL, NULL);
INSERT INTO #PVC VALUES (10214, N'400428', N'400428', N'Density cup holder', 3, N'Concentration/Concentração', N'Density cups were leaning on ball mill doors', N'To have proper spot and remove potential of falling objects', N'10058', N'01 - Imagens/01 - Antes/10214.jpeg', N'Density cups were leaning on doors. Potential to fall or create another hazard such as tripping', N'01 - Imagens/02 - Depois/10214.jpeg', N'Fabricated brackets to hang density cup up and out of the way but still accessible to where it is needed. ', NULL, N'Yes. Created proper space and removed potential hazards.', N'Housekeeping', 0, NULL, N'Garantir que a operação de conexão do painel do robô seja realizada de forma ergonômica, segura e eficiente, com o painel posicionado em altura adequada.
