INSERT INTO #PVC VALUES (10265, N'81050261', N'81050261', N'CVW 004 Bend Pully no Key Way ', 1, N'Refining/Refino', N'Bend Pully for CVW-004 came from manufacturer with no key way cut ', N'Use in house machining ', N'0', N'01 - Imagens/01 - Antes/10265.jpeg', N'CVW-004 Bend Pully came from manufacturer with no key way cut. Would have to send offsite to get cut by machine shop ', N'01 - Imagens/02 - Depois/10265.jpeg', N'Used on site machine shop to cut key way and completed on same day', NULL, N'Issue was resolved within same day and saved time and money. ', N'Use on site Machine Shop ', 1000, 3, N'Redução do retrabalho na elaboração do CI, com previa análise da documentação através de checklist.', '2026-05-18T00:00:00.000', '2026-05-26T03:01:23.000', N'81050261', NULL, NULL);
INSERT INTO #PVC VALUES (10266, N'607702', N'81031571', N'install cables 3238 op', 2, N'Underground/Subterrâneo', N'adding 30 foot cables would have required the use of the ith requiring a muck pad to be built in front of the mantle of the 3238 op to be able to drill and install the cables . This would create issues around the stability of the drill footing issues for the oprerars ', N'Safely install the required enhanced support ', N'10238', N'01 - Imagens/01 - Antes/10266.jpeg', N'To install the cables would have required a muck pad to be built exposing the ith drill to possible instability  ', N'01 - Imagens/02 - Depois/10266.jpeg', N'By altering the spacing and number of bolts a shorter cable was able to be used which allowed the jumbo to drill the holes . This facilitated the drilling as no prep work was required in the form of a muck pad. This project was completed in one shift safely', NULL, N'yes enhanced support was installed ', N'plans have to be executable ', 0, NULL, N'Maior praticidade no acesso aos documentos e melhor suporte à execução correta das tarefas operacionais', '2026-05-25T00:00:00.000', '2026-05-26T08:37:19.000', N'607702', NULL, NULL);
