INSERT INTO #PVC VALUES (10913, N'541142', N'541142', N'Válvula de limpeza flotação / Banco Rougher', 3, N'Others/Outros', N'Ausência de ponto de água de serviço para realização 
INSERT INTO #PVC VALUES (10914, N'81029859', N'81029404', N'Suporte de calços de roda.', NULL, N'Others/Outros', N'LUGAR ADEQUADO PARA ORGANZAÇÃO DOS CALÇOS DE RODAS.', N'ORGANIZAÇÃO', N'10144', N'01 - Imagens/01 - Antes/10914.jpeg', N'AUSÊNCIA DE UM SISTEMA ADEQUADO DE ORGANIZAÇÃO PARA OS CALÇOS DE RODAS DA OFICINA DE PEQUENO PORTE GERAVA DESPERDICIO DE TEMPO E IMPACTAVA A EFICIÊNCIA DAS MANUTENÇÕES . ', N'01 - Imagens/02 - Depois/10914.jpeg', N'CONFECCIONADO SUPORTE DE CALÇOS PARA PADRONIZAÇÃO E LOCALIZAÇÃO RÁPIDA  NO POSTO  DE TRABALHO.', NULL, N'SIM AGORA O PROCESSO FLUI MELHOR E MAIS RÁPIDO.', N'ORGANIZAÇÃO E GANHO DE TEMPO ', 0, NULL, N'Conseguimos reduzir as dosagens e despedicios, e rapidez na parada e operação do sistema de dosagem de reagente.', '2026-06-26T00:00:00.000', '2026-06-28T17:14:53.000', N'81029859', NULL, NULL);
INSERT INTO #PVC VALUES (10915, N'1008368', N'1008368', N'Replacing Steam Trap', 1, N'No Replication/Sem replicação', N'Steam Trap 0199 is passing low pressure steam which is not making condensate which could be reused in boiler room. steam entering condensate vessel is lost as it escapes to atmosphere through vent on the vessel', N'Replace Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/10915.jpeg', N'Steam Trap 0199 is passing low pressure steam which is not making condensate which could be reused in boiler room. steam entering condensate vessel is lost as it escapes to atmosphere through vent on the vessel', N'01 - Imagens/02 - Depois/10915.jpeg', N'New Trap installed allowing steam to convert to condensate for reuse rather than losing it through the vent stack', NULL, N'Steam trap was installed without involving maintennce ', N'Having operations complete task removes the cost of having maintenance  do it', 3000, 3, N'A revisão permite continuidade da lavra segregada dos autônomos até que a mina consiga converter toda a frota de equipamentos e também garante tempo hábil para realocação de estruturas do pátio 320.', '2026-06-27T00:00:00.000', '2026-06-28T17:31:09.000', N'1008368', NULL, NULL);
INSERT INTO #PVC VALUES (10916, N'1008368', N'1008368', N'Replacing Steam traps', 1, N'No Replication/Sem replicação', N'Waiting for Maintenance to replace steam trap is lost time and lost steam literally up the vent stack. Also the cost of maintenance doing the task can be saved if operations does the task', N'Replace Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/10916.jpeg', N'Steam Trap 0200 is passing high pressure steam which is not making condensate which could be reused in boiler room. Steam entering the condensate vessel is lost as it escapes to atmosphere through vent on vessel.', N'01 - Imagens/02 - Depois/10916.jpeg', N'New Trap installed allowing steam to convert to condensate for reuse rather than losing it through the Vent stack.', NULL, N'Yes, new steam trap installed without involving maintenance', N'HAving operations complete task removes the cost of having maintenance do the task', 3000, 3, NULL, '2026-06-27T00:00:00.000', '2026-06-28T17:48:24.000', N'1008368', NULL, NULL);
INSERT INTO #PVC VALUES (10917, N'400428', N'400428', N'Lunchroom AC exhaust port', 3, N'Concentration/Concentração', N'Using cardboard which was flimsy that wouldn''t allow light in and not exhausting hot air properly', N'Make semi permanent, ttransparent exhaust port for AC', N'10058', N'01 - Imagens/01 - Antes/10917.jpeg', N'Using cardboard which was flimsy that wouldn''t allow light in and not exhausting hot air properly. This would also allow dust into lunchroom', N'01 - Imagens/02 - Depois/10917.jpeg', N'Cut plexiglass and proper port hole for exhaust and sealed. Sunlight can now come in through window and no hot air returning into lunchroom', NULL, N'Had cardboard which was not robust enough and not seal properly. Replaced with plexiglass and sealed properly', N'Make semi permanent plexiglass panel', 0, NULL, N'Maior assertividade para o plano de blend.', '2026-06-27T00:00:00.000', '2026-06-29T01:09:47.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (10918, N'922260', N'922260', N'ILUMINAÇÃO PARA MUFLA', 2, N'Projects/Projetos', N'Na fusão de amostras para análise flúor, devido a lente do capuz ser de cor verde por segurança na proteção da visão, dificulta a retirada de amostras em fusão, causando derramamentos e até esquecimento de cadinhos na mufla por falta de  visão dos mesmos.', N'AUMENTAR VISIBILIDADE NA FUSÃO DE AMOSTRAS', N'10103', N'01 - Imagens/01 - Antes/10918.jpeg', N'Na fusão de amostras para análise flúor, devido a lente do capuz ser de cor verde por segurança na proteção da visão, dificulta a retirada de amostras da mufla  , causando derramamentos e até esquecimento de cadinhos na mufla por falta de  visão dos mesmos.', N'01 - Imagens/02 - Depois/10918.jpeg', N'           Com a instalação de uma lanterna na frente da mufla, iluminando a parte interior da mufla  os cadinhos fundidos ficam visível ao operador da mufla. ', NULL, N'sim', N'um pequeno investimento elimina perdas de amostras.', 0, NULL, N'Rastreabilidade do processo e melhora no gerenciamento.', '2026-06-24T00:00:00.000', '2026-06-29T01:36:33.000', N'922260', NULL, NULL);
INSERT INTO #PVC VALUES (10919, N'400428', N'400428', N'Blocked electrical panel', 3, N'Others/Outros', N'Materials being stored in front electrical panels blocking access', N'To prevent materials being stored blocking access to electrical panel', N'10058', N'01 - Imagens/01 - Antes/10919.jpeg', N'Materials being stored in front of electrical panle blocking access', N'01 - Imagens/02 - Depois/10919.jpeg', N'Removed items and posted signs reminding employees not to store materials in front of electrical panels', NULL, N'Yes. Cleared pathway and posted sign to remind not to store materials blocking access to panel', N'Can be used in many other areas ', 0, NULL, N'Espera-se, com a implementação do Kaizen, eliminar as falhas recorrentes do sistema, elevar a confiabilidade operacional e garantir uma operação contínua, estável e tecnicamente adequada às condições de carga e desgaste do processo.', '2026-06-28T00:00:00.000', '2026-06-29T03:46:43.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (10920, N'81009130', N'81009130', N'Controle de Montagem de Andaime Parada Programada - PGU2026', 1, N'Others/Outros', N'A falta de controle a atualização manual das informações grande parte dos dados depende de preenchimento manual, aumentando o risco de erros, com a planilha não a evidência de avanços e controle das atividades e alerta para providência imediata.', N'Controle de Montagem Visual e detalhada - Avanços ', N'10184', N'01 - Imagens/01 - Antes/10920.jpeg', N'Com a visualização através de planilha a ausência de controle e prazos as informações grande parte inserida manualmente aumentando o risco de erros e a fata de padronização percebeu-se a dificuldade visual para tomar prioridade diante das atividade de PGU 2026.', N'01 - Imagens/02 - Depois/10920.jpeg', N'A implantação do Power Bi para controle de Andaime PGU2026 trouxe mais eficiência, confiabilidade e agilidade na gestão das atividades de montagem e desmontagem, permitindo uma visão integrada das demandas e apoiando as tomadas de decisão. Monitoramento em tempo real dos avanços, controle por área operacional e gerência, acompanhamento das vistas realizadas garantindo mais controle e gestão dos recursos. ', NULL, N'Sim, tivemos grande resultados nos controle e visualização via planejamento.', N'Aprendizado de controle e eficacia nos monitar\mento em área ', 0, NULL, N'Redução significativa do tempo de processamento e consolidação de dados.
INSERT INTO #PVC VALUES (10921, N'81046537', N'81002274', N'Tampão de isolamento hidráulico.', 1, N'Others/Outros', N'Tubo de acesso a bomba auxiliar 01, ao realizar manutenção no tubo, o mesmo fica exposto a contaminação por derramamento de óleo, pois o diâmetro do tubo é grande e não tem vedação padrão resultando em possível contaminação no solo.', N'Evitar contaminação do sistema hidráulico.', N'10324', N'01 - Imagens/01 - Antes/10921.jpeg', N'Ao realizar manutenção no tubo, o mesmo fica exposto a contaminação por derramamento de óleo, pois o diâmetro do tubo é grande e não tem vedação padrão resultando em possível contaminação no solo.', N'01 - Imagens/02 - Depois/10921.jpeg', N'Confeccionado tampa de isolamento do tubo da bomba auxiliar 01, evitando contaminação do sistema hidráulico do solo por derramamento de óleo .', NULL, N'Sim, evitado contaminação do sistema hidráulico e derramamento de óleo no solo.', N'SENTIMENTO DE DONO, DESENVOLVER MELHORIA E PROJETAR EM EQUIPE.', 0, NULL, N' Como solução, foi desenvolvido um formulário digital integrado a uma planilha automatizada, que permitirá a coleta estruturada dos dados diretamente em campo, o resultado esperado é a organização e automação do lançamento de dados', '2026-06-22T00:00:00.000', '2026-06-29T10:16:01.000', N'81046537', NULL, NULL);
INSERT INTO #PVC VALUES (10922, N'92000157', N'92000157', N'Relatório de Performance Pós Preventiva', 1, N'Others/Outros', N'Atualmente, a avaliação das manutenções preventivas é concentrada principalmente na execução da intervenção, sem uma visão estruturada do comportamento do ativo após sua liberação, limitando a capacidade de medir, de forma objetiva, se a preventiva executada foi efetiva para sustentar a performance do equipamento no curto prazo.
INSERT INTO #PVC VALUES (10923, N'81012522', N'81012522', N'Otimização da coleta e comunicação dos dados de horímetro dos equipamentos leves.', NULL, N'Others/Outros', N'Atualmente há dificuldade na comunicação e na coleta dos dados de horímetro dos equipamentos leves. A ausência de um fluxo padronizado para obtenção dessas informações resulta em atrasos na atualização dos controles, impactando o planejamento de manutenção, a programação das atividades e a confiabilidade dos dados operacionais.', N'Reduzir o tempo e aumentar a confiabilidade na obtenção dos dados de horímetro dos equipamentos leves, garantindo informações atualizadas para o planejamento e controle das operações.', N'10119', N'01 - Imagens/01 - Antes/10923.jpeg', N'A coleta das informações de horímetro dos equipamentos leves era realizada de forma manual, por meio de contatos individuais com operadores e responsáveis pelos equipamentos. Esse processo demandava tempo, dificultava a obtenção rápida dos dados e ocasionava atrasos na atualização dos controles e no planejamento das atividades de manutenção.', N'01 - Imagens/02 - Depois/10923.jpeg', N'Foi desenvolvido um formulário eletrônico (Microsoft Forms) acessado por meio de QR Code, contendo o cadastro de todos os equipamentos leves. Os operadores passaram a registrar a leitura dos horímetros diretamente no formulário durante o preenchimento do checklist diário, permitindo a atualização das informações em tempo real, aumentando a confiabilidade dos dados e reduzindo o tempo gasto na coleta e consolidação das informações.
INSERT INTO #PVC VALUES (10924, N'81053475', N'81053475', N'Automação do Planejamento de Capacidade da Manutenção por Meio da Consolidação Inteligente de HH', 1, N'Projects/Projetos', N'O levantamento da demanda de mão de obra para execução dos planos de manutenção preventiva e inspeção era realizado de forma manual, exigindo grande esforço para consolidar informações de listas de tarefas, planos de manutenção e programação anual. O processo demandava elevado tempo de tratamento dos dados e estava sujeito a inconsistências e retrabalho.', N'Desenvolver uma ferramenta automatizada capaz de calcular a necessidade de Horas-Homem (HH) para atividades preventivas e de inspeção, considerando a programação do mapa de 52 semanas, aumentando a produtividade, confiabilidade e agilidade das análises.', N'10015', N'01 - Imagens/01 - Antes/10924.jpeg', N'Extração e consolidação manual das informações.
INSERT INTO #PVC VALUES (10925, N'989707', N'140178', N'FORMULÁRIO DE VERIFICAÇÃO DE TORQUE RODAS EE01', 1, N'Others/Outros', N'Falta de padrão para torque de referência dos parafusos dos cubos das rodas E001 ', N'Padronização Rotina Torque das rodas E001', N'10081', N'01 - Imagens/01 - Antes/10925.jpeg', N'Falha por ruptura dos parafusos de fixação das rodas traseiras do eixo E001 associada à inexistência de procedimento padronizado para aplicação e controle do torque de aperto dos parafusos dos cubos das rodas.', N'01 - Imagens/02 - Depois/10925.jpeg', N'Elaborado e implantado formulário de verificação de torque para os parafusos de fixação dos cubos das rodas, estabelecendo padrão de inspeção, registro e controle dos valores de torque aplicados, garantindo a conformidade da montagem e reduzindo o risco de falhas por afrouxamento ou sobreaperto.', NULL, N'Problema: Ausência de padrão e controle do torque aplicado aos parafusos dos cubos das rodas, resultando em quebras dos parafusos do eixo E001.
INSERT INTO #PVC VALUES (10926, N'81046916', N'81046916', N'Garantia de vedações dos moinhos Polysius', 1, N'Concentration/Concentração', N'Após a aquisição de vedações com a empresa FLS, foi 
INSERT INTO #PVC VALUES (10927, N'538696', N'538696', N'Controle de Bombas automatico', 1, N'Others/Outros', N'Durante as manobras de paradas e operação das bombas de espumante 2 teríamos que ir individualmente em cada bomba para parar ou colocar lá em operação.', N'Automatizar bombas de reagentes', N'10054', N'01 - Imagens/01 - Antes/10927.jpeg', N'Durante as manobras de paradas e operação das bombas de espumante 2 teríamos que ir individualmente em cada bomba para parar ou colocar lá em operação, em alguns momentos devido a alta demanda, deixava uma ou outra bomba em operação e dosando reagente, ocasionando desperdício e complicações no retorno de Usina ocasionando transbordos devido excesso de espumante.', N'01 - Imagens/02 - Depois/10927.jpeg', N'Juntamento com a equipe de automação e técnicos de sala de controle tivemos uma ideia de fazer agrupamento dessas bombas pelo sistema, tendo assim a opção de parar todas as bombas na qual estão selecionadas pelo grupo, reduzindo o desperdício e dosagem excessiva, evitando transbordos ocasionado pela excesso de espuma.', NULL, N'Foi realizado a automatização agrupamento das bombas para trabalhar em conjunto, para evitar dosagens desnecessarias.', N'Trabalhar com equipamentos em modo automatico diminui desperdícios.', 0, NULL, NULL, '2026-06-18T00:00:00.000', '2026-06-29T11:09:39.000', N'538696', NULL, NULL);
INSERT INTO #PVC VALUES (10928, N'980813', N'980813', N'Revisão Design Rampas - Fase 6.2', 1, N'No Replication/Sem replicação', N'Atual design das Rampas da Fase 6.2 não encaixa na atual rampa dos autônomos. Essa condição impactaria a operação segregada para a lavra dessa frota e teria diretamente interferências com estruturas e pátios na PDE. ', N'Melhoria de design e condição operacional', N'10162', N'01 - Imagens/01 - Antes/10928.jpeg', N'Rampas impactando na lavra segregada dos caminhões autônomos e estruturas e pátio na PDE.', N'01 - Imagens/02 - Depois/10928.jpeg', N'Recuo das posições de rampa para garantia operacional de encaixe com a atual rampa de saída da lavra segregada dos caminhões autônomos.', NULL, N'Problema resolvido com a revisão do Design! Planejamento deve alinhar o novo desenho e garantir que seja executado em campo.', N'Necessidade de revisão periódica de design de Fases alinhadas às estratégias de lavra', 0, NULL, N'Redução significativa do tempo de elaboração do S-1, aumento da produtividade, maior confiabilidade das informações e eliminação de etapas manuais.', '2026-06-15T00:00:00.000', '2026-06-29T12:17:36.000', N'980813', NULL, NULL);
INSERT INTO #PVC VALUES (10929, N'486546', N'486546', N'Implementação de Trava na Caixa do Bico de Abastecimento (CA-02)', 2, N'Others/Outros', N'O equipamento CA-02 opera com caixa de armazenamento do bico de abastecimento sem sistema de travamento confiável, utilizando mecanismo frágil, o que resultou no desprendimento do bico e avaria de componente, gerando custo de R$ 12.000,00 e risco de recorrência.', N'Implementar sistema de travamento seguro na caixa do bico de abastecimento do CA-02, eliminando o risco de desprendimento e evitando recorrência de danos, com zero incidentes relacionados.', N'10079', N'01 - Imagens/01 - Antes/10929.jpeg', N'Após a implementação da trava mecânica reforçada com corrente em 11/06, o risco de abertura involuntária foi eliminado, reduzindo a probabilidade de ocorrência do evento de alta para praticamente nula, com consequente eliminação do potencial de dano associado (R$ 12.000,00 por ocorrência).
INSERT INTO #PVC VALUES (10930, N'81029574', N'81029574', N'Amostragem com a utilização da Retroescavadeira', 1, N'Others/Outros', N'Como parte da rotina operacional, é realizada semanalmente a inspeção das pilhas, com amostragem manual para validação de basculamentos com características físicas distintas. Esse acompanhamento é essencial devido à baixa disponibilidade de minério de alto teor, visando reduzir a diluição e aumentar a confiabilidade dos teores. O uso da retroescavadeira torna a amostragem mais representativa, contribuindo para um melhor controle da qualidade do minério destinado à britagem.
INSERT INTO #PVC VALUES (10931, N'81040303', N'81040303', N'Aplicativo de inspeção dos chutes', 1, N'Others/Outros', N'É realizado a inspeção dos chutes de alimentação, porém não havia um formulário padrão nem um local onde essas inspeções fossem registradas. O inspetor ia em campo abria OM para troca dos revestimentos danificados posteriormente.', N'Padronização; Gerenciamento; Rastreabilidade', N'10293', N'01 - Imagens/01 - Antes/10931.jpeg', N'É realizado a inspeção dos chutes de alimentação, porém não havia um formulário padrão nem um local onde essas inspeções fossem registradas. O inspetor ia em campo e fazia suas anotações, e posteriormente quando retornava para a sala abria OM para troca dos revestimentos danificados. As anotações eram individuais de cada inspetor e não eram registradas em nenhum outro lugar.', N'01 - Imagens/02 - Depois/10931.jpeg', N'Desenvolvido aplicativo utilizando Power apps, possibilitando que o inspetor selecione um dos 51 chutes previamente cadastrados e faça o registro de toda a inspeção dos revestimentos, apontando a condição do revestimento separando por lado do chute e área correspondente. Após todos os campos preenchidos o registro é salvo em um banco de dados no Sharepoint list. O app foi desenvolvido para suportar o registro de forma offline em caso de falta de rede.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/09e29265-780a-4dab-a67b-a895a2d30042?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=513c7b19-375a-4912-a2e3-3e1c3d9f50f0&sourcetime=1777551382196&source=portal', N'Agora é possível realizar o acompanhamento de todas as inspeções realizadas, possibilitando um melhor gerenciamento do processo.', N'Padronização; Gerenciamento', 0, NULL, N'5S', '2026-06-01T00:00:00.000', '2026-06-29T13:37:52.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (10932, N'81049526', N'81049526', N'Eliminação de Falhas Recorrentes no Sistema Pinhão-Cremalheira', 1, N'Projects/Projetos', N'O sistema de translação da cabeça móvel do transportador de correia apresenta falhas recorrentes no conjunto pinhão-cremalheira, caracterizadas por desgaste prematuro e intervenções frequentes, resultando em paradas operacionais não planejadas e redução da confiabilidade do equipamento.
INSERT INTO #PVC VALUES (10933, N'81053475', N'81053475', N'Transformação Digital da Estimativa de Horas-Homem por Meio da Integração Automatizada de Dados Corretivos e Condicionais ', 1, N'Others/Outros', N'A obtenção da demanda de Horas-Homem (HH) proveniente das manutenções corretivas e condicionais exigia a consolidação manual de informações de múltiplas bases de dados, tornando o processo demorado, suscetível a erros e com baixa padronização. Essa limitação dificultava a realização de estudos de dimensionamento de equipes e análises de capacidade da manutenção.', N'Automatizar a consolidação dos dados de manutenção corretiva e condicional, oriundos do BI do PCM para disponibilizar estimativas confiáveis de HH e apoiar os estudos de dimensionamento, planejamento e tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/10933.jpeg', N'Coleta e tratamento manual de dados provenientes de diversas fontes.
INSERT INTO #PVC VALUES (10934, N'81061143', N'81061143', N'PratForms', 1, N'No Replication/Sem replicação', N'o principal problema estava relacionado ao fato de que os dados não eram aprovisionados em tempo real, o que causava não só atrasos, mas também desorganização nas informações da planilha. Isso dificultava o controle, a padronização e aumentava o risco de erros.
INSERT INTO #PVC VALUES (10935, N'521673', N'471863', N'Localização das caixas', 1, N'No Replication/Sem replicação', N'Antes não tinha identificação nas prateleiras para encontrar as caixas com mais facilidade e rapidez.', N'Encontrar as caixas com facilidade', N'10366', N'01 - Imagens/01 - Antes/10935.jpeg', N'Antes da melhoria, não existia identificação nas prateleiras, o que tornava mais difícil e demorada a localização das caixas.', N'01 - Imagens/02 - Depois/10935.jpeg', N'Com a implementação de etiquetas padronizadas de identificação, foi possível melhorar significativamente a organização do espaço e reduzir o tempo de busca das caixas.', NULL, N'Sim, antes não existia identificação nas prateleiras, o que tornava mais difícil e demorada a localização das caixas.', N'Organização', 0, NULL, N'Redução dos custos de materiais com maior controle e visibilidade do consumo, priorização dos itens críticos e atuação na causa. Maior eficiência nas decisões e fortalecimento da gestão de fornecedores.', '2026-06-25T00:00:00.000', '2026-06-29T14:55:19.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (10936, N'521673', N'81022694', N'Segurança no chuveiro de emergência', 2, N'No Replication/Sem replicação', N'Antes o chuveiro ficava solto e vindo pra frente quando puxava o triangulo. ', N'Fixar o chuveiro de emergência', N'10366', N'01 - Imagens/01 - Antes/10936.jpeg', N'Antes o chuveiro encontrava-se solto, deslocando-se para frente ao puxar o triângulo, o que comprometia a segurança e a estabilidade durante o uso.', N'01 - Imagens/02 - Depois/10936.jpeg', N'Após a realização do ajuste e fixação adequada do equipamento, foi eliminada a movimentação indevida, garantindo maior segurança, estabilidade e confiabilidade na operação, além de reduzir o risco de falhas e incidentes.', NULL, N'Antes da melhoria, o chuveiro encontrava-se solto, deslocando-se para frente ao puxar o triângulo, o que comprometia a segurança e a estabilidade durante o uso.
INSERT INTO #PVC VALUES (10937, N'92000576', N'92000576', N'Criação de Algoritmo para Detecção Automática de Interfaces de Telemetria Não Conectadas com Geração de Alertas Integrados ao Aplicativo de Intervenções para Atuação Proativa do time da Telemetria', 1, N'Others/Outros', N'Equipamentos de mina podem operar por longos períodos sem transmissão de dados de telemetria devido a falhas de comunicação de interface. Antes da melhoria, não existia um mecanismo automatizado capaz de identificar essa condição em tempo adequado, permitindo que ativos operassem sem geração de informação, comprometendo o monitoramento, a confiabilidade dos dados e a tomada de decisão operacional.', N'Desenvolver e implementar um algoritmo automatizado capaz de identificar equipamentos operando sem envio de dados de telemetria, gerar alertas de forma automática e integrar esses eventos ao fluxo de tratamento do CMA, garantindo atuação proativa e padronizada.', N'10015', N'01 - Imagens/01 - Antes/10937.jpeg', N'Antes da implementação, não havia controle sistematizado para identificar equipamentos operando sem geração de eventos de telemetria. A detecção de falhas de interface ocorria de forma reativa e pontual, dificultando o monitoramento contínuo dos ativos e comprometendo a confiabilidade das informações utilizadas nas análises operacionais.', N'01 - Imagens/02 - Depois/10937.jpeg', N'Foi desenvolvido um algoritmo que realiza a análise contínua dos equipamentos com base nas horas trabalhadas e na ausência de eventos de telemetria. Quando identificado que um equipamento esteve em operação sem gerar eventos no período analisado, o sistema gera automaticamente um evento denominado “Interface Não Conectada”, indicando possível falha de comunicação.
INSERT INTO #PVC VALUES (10938, N'544612', N'544612', N'Suporte para mangotes', 3, N'Others/Outros', N'Atualmente, os mangotes são armazenados de forma inadequada.', N'Desenvolver e implementar um suporte para armazenamento de mangotes.', N'10054', N'01 - Imagens/01 - Antes/10938.jpeg', N'Mangotes armazenados de forma inadequada, permanecendo no chão ou em locais improvisados, o que dificulta sua identificação e acesso, aumenta o risco de danos, contaminação e acidentes, além de gerar perda de tempo nas atividades operacionais. A ausência de um suporte específico compromete a organização e a produtividade do setor.', N'01 - Imagens/02 - Depois/10938.jpeg', N'Foi implantado um suporte específico para armazenamento dos mangotes, garantindo que permaneçam organizados, identificados e acondicionados corretamente. Com isso, houve redução do tempo de busca e manuseio, diminuição do risco de danos, contaminação e acidentes, além de melhoria na organização, segurança e eficiência das operações.', NULL, N'A meta inicial de desenvolver e implantar um suporte adequado para os mangotes foi alcançada. Após a implementação, os mangotes passaram a ser armazenados de forma organizada, segura e de fácil acesso, eliminando o armazenamento no chão e reduzindo riscos de danos e acidentes. A solução proporcionou maior agilidade nas operações, melhor organização do setor e aumento da eficiência, atendendo aos objetivos propostos.', N'A organização adequada dos mangotes melhora significativamente a eficiência das atividades.', 0, NULL, N'Reduced downtime as we need to make process changes to accommodate filter sluicing. Derisks the process having the redundant filter available quicker', '2026-06-26T00:00:00.000', '2026-06-29T16:49:38.000', N'544612', NULL, NULL);
INSERT INTO #PVC VALUES (10939, N'92000576', N'92000576', N'Automatização e Integração do Painel de Controle de Interfaces com Algoritmo de Detecção de Falhas de Comunicação e Atualização Frequente via Power BI', 1, N'Others/Outros', N'O controle das interfaces de telemetria era realizado manualmente por meio de planilhas Excel atualizadas periodicamente pelo time do CMA. Esse processo era limitado, com baixa frequência de atualização (semanal), alta dependência de intervenção humana e sem integração com o fluxo de tratamento dos eventos. Como consequência, havia atraso na visibilidade das falhas de comunicação e dificuldade para acompanhamento da situação real das interfaces dos equipamentos.', N'Automatizar o controle das interfaces de telemetria, integrando o algoritmo de detecção de falhas ao Power BI, disponibilizando indicadores atualizados de forma frequente e permitindo acompanhamento em tempo quase real da situação das interfaces e das tratativas realizadas.', N'10015', N'01 - Imagens/01 - Antes/10939.jpeg', N'Antes da melhoria, o controle das interfaces era feito por meio de planilhas Excel atualizadas manualmente, geralmente uma vez por semana. Esse processo exigia coleta manual de dados e posterior atualização da planilha, o que gerava atraso na disponibilização das informações, baixa frequência de atualização e ausência de integração com os eventos e tratativas realizadas pela telemetria.', N'01 - Imagens/02 - Depois/10939.jpeg', N'Foi realizada a automatização do controle de interfaces com integração do algoritmo de detecção ao Power BI, substituindo o processo manual em Excel. O painel passou a apresentar, de forma consolidada, o status das interfaces, falhas de comunicação e indicadores por frota, com atualização automática cerca de 6 vezes ao dia. Além disso, foi integrado ao Aplicativo de Intervenções, refletindo status, comentários e tratativas em tempo quase real, garantindo maior visibilidade, confiabilidade e suporte à tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/fed38737-81c1-4d94-abce-067650557a61/4446ccdfa95b668c8002?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (10940, N'301042', N'607702', N'Standardize fan for 3800-3804 Ore Pass', 1, N'Underground/Subterrâneo', N'Initial development required a 30HP fan to ventilate the heading as it advanced. Once the development progressed the fan would need to be replaced with a larger fan to supply adequate CFM for the equipment in the area.', N'Ventilate Ore pass long term', N'10014', N'01 - Imagens/01 - Antes/10940.jpeg', N'30HP fan used for the development is not adequate to support the equipment used after the development is complete.', N'01 - Imagens/02 - Depois/10940.jpeg', N'The 75 HP fan installed will now support all equipment CFM requirements for the life of mine.', NULL, N'Installing the larger fan initially saves substantial cost in rework, cable wire costs as the two fans require different sizes of cable to power them, and down time on the main ramp as this is the main haulage ramp and would create conflicts within production.', N'Use a long-range outlook when planning jobs.', 43, 3, N'O Kaizen reduziu o tempo de análise e comunicação dos resultados de potabilidade, substituindo a consulta individual aos laudos laboratoriais por um boletim consolidado e visual. A melhoria permitiu interpretação mais rápida da campanha, identificação imediata de conformidades ou desvios e maior agilidade na comunicação com os clientes internos.', '2026-06-28T00:00:00.000', '2026-06-29T17:21:38.000', N'301042', NULL, NULL);
INSERT INTO #PVC VALUES (10941, N'81004893', N'81004893', N'S-1 Automático ', 1, N'Others/Outros', N'A elaboração do S-1 era realizada manualmente, demandando tempo dos analistas, aumentando o risco de inconsistências nas informações e reduzindo a produtividade do processo.', N'Automatizar a geração do S-1, reduzindo o tempo de elaboração, padronizando os registros e aumentando a eficiência do processo.', N'10015', N'01 - Imagens/01 - Antes/10941.jpeg', N'O S-1 era elaborado manualmente, exigindo preenchimento de diversos campos, consolidação de informações e revisões frequentes.', N'01 - Imagens/02 - Depois/10941.jpeg', N'O S-1 passou a ser gerado automaticamente a partir das informações inseridas no sistema, reduzindo a intervenção manual e garantindo maior padronização.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/8e4c9fa7-20a3-4d13-ad8c-908113eb074f/ReportSection0993b14cc60d2964a2dd?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvida uma funcionalidade para geração automática do S-1, utilizando dados já disponíveis no sistema e preenchendo os campos de forma padronizada.', N'Processos repetitivos possuem grande potencial de automação, permitindo que as equipes direcionem esforços para atividades de maior valor agregado.', 0, NULL, N'Agora os integrantes da célula de projetos não precisam atualizar sua base manualmente e recebem notificação via Teams de que novas notas foram adicionadas na base.', '2026-06-10T00:00:00.000', '2026-06-29T18:24:14.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10942, N'81004893', N'81004893', N'Inserção de Histórico de Tratamento de Eventos de Telemetria no Painel de Eventos', 1, N'Others/Outros', N'O acompanhamento do histórico de tratamento dos eventos de telemetria era realizado de forma descentralizada, dificultando a rastreabilidade das ações executadas, consultas futuras e análises de reincidência.', N'Disponibilizar o histórico completo de tratamento diretamente no painel de eventos, aumentando a visibilidade, rastreabilidade e agilidade na tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/10942.jpeg', N'As informações de tratamento dos eventos estavam dispersas em registros, e-mails ou consultas paralelas, demandando tempo para localização e validação do histórico.', N'01 - Imagens/02 - Depois/10942.jpeg', N'O histórico de tratamento passou a ser exibido diretamente no painel de eventos, permitindo consulta rápida e centralizada das ações realizadas.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/57b68cba-2247-4f57-899a-a8bd95b9b745/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Foi desenvolvida uma funcionalidade no painel de eventos para registrar e exibir automaticamente todo o histórico de tratamento, concentrando as informações em um único ambiente e facilitando o acompanhamento das ações realizadas.', N'A centralização das informações em um único ambiente reduz tempo de análise, melhora a gestão do conhecimento e aumenta a eficiência operacional.', 0, NULL, N'ELIMINAÇÃO DAS FALHAS RECORRENTES NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02.
INSERT INTO #PVC VALUES (10943, N'81004893', N'81004893', N'Nova Estruturação de Saving e Captura de Valor', 1, N'Others/Outros', N'A mensuração dos ganhos provenientes das iniciativas do CMA apresentava oportunidades de melhoria quanto à padronização dos cálculos, filtros de redução de valores e fluxo de validação, dificultando a rastreabilidade e a confiabilidade dos resultados apresentados.', N'Estruturar um processo padronizado de captura de valor, com critérios definidos para cálculo, filtros de categorização dos ganhos e fluxo de aprovação para validação dos savings.', N'10015', N'01 - Imagens/01 - Antes/10943.jpeg', N'Os ganhos eram apurados por custo residual de novo ou de reforma, sem necessidade aprovação para validação. ', N'01 - Imagens/02 - Depois/10943.jpeg', N'Os savings passaram a seguir metodologia padronizada, com aplicação de filtros de classificação, registros estruturados e fluxo de aprovação para validação dos resultados. Custo do Componente × % Vida Remanescente × Fator de Redução, sendo:
INSERT INTO #PVC VALUES (10944, N'538409', N'81035675', N'LOCOMOÇÃO DE FERRAMENTAS', 2, N'Others/Outros', N'ABUSO NA ERGONOMIA DURANTE LOCOMOÇÃO DE FERRAMENTAS', N'ERGONOMIA/5S', N'10138', N'01 - Imagens/01 - Antes/10944.jpeg', N'LOCOMOÇÃO BRAÇAL
INSERT INTO #PVC VALUES (10945, N'763789', N'763789', N'Implantação de sinalização preventiva para controle de acesso à passarela durante embarque de ferro gusa', 2, N'Others/Outros', N'A passarela que liga a base ao píer é amplamente utilizada e acompanha o transportador 8051 TC13. Porém existe um transportador de outra empresa, posicionado acima e durante embarque de ferro gusa, ocasionam queda de material sobre a passarela. Atualmente, o controle é feito apenas com fechamento do portão, sem sinalização visual, gerando risco de acesso indevido e baixa percepção do perigo.', N'Garantir que 100% dos colaboradores sejam alertados sobre o risco antes de acessar a passarela, eliminando acessos indevidos durante operações com ferro gusa.', N'10294', N'01 - Imagens/01 - Antes/10945.jpeg', N'O acesso à passarela era controlado apenas pelo fechamento do portão durante operações com ferro gusa. Não havia sinalização visual no ponto de entrada, o que dificultava a percepção do risco e poderia levar colaboradores a tentarem acessar a área sem conhecimento do perigo existente.', N'01 - Imagens/02 - Depois/10945.jpeg', N'Com a implantação da placa de sinalização no início da passarela, o risco de queda de material passou a ser comunicado de forma clara e imediata. Os colaboradores agora conseguem identificar o perigo antes do acesso, reduzindo tentativas indevidas e reforçando a segurança operacional.', NULL, N'Sim. A implantação da placa atendeu à meta de melhorar a comunicação de risco, garantindo que os colaboradores sejam alertados logo no início da passarela. Isso aumentou significativamente a percepção do perigo e reduziu a possibilidade de acesso indevido.', N'A comunicação visual no ponto de acesso é essencial para prevenir acidentes / Medidas apenas físicas (como portão) não são suficientes sem reforço informativo / A percepção de risco aumenta significativamente com sinalização clara e objetiva / Integração entre operações de diferentes empresas exige reforço na comunicação de segurança.', 0, NULL, N'This will allow for users to locate the files they are searching for in a timelier manner, less digging, less frustration, etc. ', '2026-06-24T00:00:00.000', '2026-06-30T01:24:08.000', N'763789', NULL, NULL);
INSERT INTO #PVC VALUES (10946, N'460522', N'81016737', N'Respirator Cartridges', NULL, N'Others/Outros', N'It was identified that ops areas were stocking 60926 cartridges, while our standard requirement is 60923 cartridges. 
INSERT INTO #PVC VALUES (10947, N'87000312', N'87000345', N'Energy Savings via Inverter Adjustment of No3 RT Industrial Water Pump', 1, N'Refining/Refino', N'When the 90kW compressor (No. 3) shut down, an excessive amount of water was supplied to the 3RT8F unit, resulting in energy loss.', N'Energy Savings', N'0', N'01 - Imagens/01 - Antes/10947.jpeg', N'When the 90kW compressor (No. 3) shut down, an excessive amount of water was supplied to the 3RT8F unit, resulting in energy loss.', N'01 - Imagens/02 - Depois/10947.jpeg', N'Changing the LOW setting of INV reduced energy loss.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Redução de inconsistência em BI amplamente consultado.', '2026-06-18T00:00:00.000', '2026-06-30T06:37:37.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (10948, N'81054419', N'81054419', N'Gestão Inteligente do Consumo de Materiais com Foco em Custos e Performance', 1, N'Underground/Subterrâneo', N'Atualmente não existe acompanhamento do consumo de materiais o que não permite uma visão clara dos itens mais utilizados e daqueles com maior impacto financeiro. Isso dificulta a identificação de desvios, análise de causas e a tomada de decisão para otimização de custos e melhoria de suprimentos.', N'Monitorar quantitativamente os itens consumidos; Identificar materiais de maior custo e relevância;', N'10015', N'01 - Imagens/01 - Antes/10948.jpeg', N'Ausência de visão estruturada do consumo de materiais, dificultando identificar itens críticos por custo e volume. ', N'01 - Imagens/02 - Depois/10948.jpeg', N'Relatório estruturado com análise de consumo por valor e quantidade, priorização e identificação de itens críticos. Suporte à tomada de decisão, redução de custos e desenvolvimento de fornecedores.', NULL, N'A meta de dar visibilidade ao consumo e priorizar itens críticos foi atingida com a criação do relatório. Conseguimos identificar os principais ofensores de custo e direcionar ações, reduzindo decisões reativas e atuando na causa.', N'A gestão eficaz do consumo exige dados estruturados e priorização por impacto financeiro. A análise integrada (custo x volume) direciona ações mais assertivas, fortalece decisões e viabiliza ganhos com fornecedores.', 0, NULL, NULL, '2026-06-29T00:00:00.000', '2026-06-30T08:44:16.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (10949, N'1008800', N'1008800', N'IR1 R1 Reline completed below cost (2026)', 1, N'Projects/Projetos', N'IR1 Reactor #1 had carryover relining and reinstatement required from 2025 into 2026.', N'Complete relining, return tank to service', N'0', N'01 - Imagens/01 - Antes/10949.jpeg', N'IR1 Reactor #1 had outstanding work remaining from 2025 due to delays with a new regulation with SNL that all mobile compressors on site were to be registered.
INSERT INTO #PVC VALUES (10950, N'1008800', N'1008800', N'Install Titanium Agitator IR1 Reactor #1', 1, N'Refining/Refino', N'Existing agitator was deemed no longer suitable for service.', N'Improve equipment reliability', N'#N/A', N'01 - Imagens/01 - Antes/10950.jpeg', N'IR1 Reactor #1 Agitator was originally a carbon steel rubber lined assembly. The tank was upgraded to Carbon Steel FRP Lined in 2022. Rubber is not suitable for this service.
INSERT INTO #PVC VALUES (10951, N'202638', N'202638', N'Repurpose unused equipment', 1, N'Refining/Refino', N'Our Durco filter failed and was in need of repair. Repairs would take an expected 6 months', N'Cost savings', N'0', N'01 - Imagens/01 - Antes/10951.jpeg', N'Feed filter damage was going to need major repairs and the time to repair would be excessive due the work required', N'01 - Imagens/02 - Depois/10951.jpeg', N'Reuse a similar filter that was not in use in another building saving the down time expected to repair. This would allow us to get the filter back into service minimizing downtime and allow for the filter to be repaired ', NULL, N'yes', N'Using availabel redundant equipment to lessen down time', 0, NULL, N'Financeiro (estimado): ~6h/semana economizadas por coordenação × ~20 coordenações Salobo = ~480h/mês de ganho operacional, equivalente a redução de retrabalho e horas improdutivas dos coordenadores.
INSERT INTO #PVC VALUES (10952, N'1008800', N'1008800', N'CCD-1 Feed Tank Inspection and agitator replacement', 1, N'Refining/Refino', N'CCD-1 Feed Tank was suspected to be leaking. The tank was also operating without an agitator since approximately April 2025.', N'Inspect CCD-1 Overflow Tank and return to service', N'0', N'01 - Imagens/01 - Antes/10952.jpeg', N'The upper shaft of the agitator had sheared from the mixer.
INSERT INTO #PVC VALUES (10953, N'81046430', N'81013286', N'Boletim de Potabilidade Semanal da Mina Salobo', NULL, N'Others/Outros', N'Laudos de análises laboratoriais de potabilidade em linguagem técnica, pouco acessível ao público em geral.', N'Melhorar a governança e transparência das informações de qualidade da água potável através de padronização e layout visual claro, objetivo e didático', N'10017', N'01 - Imagens/01 - Antes/10953.jpeg', N'Os resultados das análises de monitoramento da potabilidade eram disponibilizados por meio dos laudos laboratoriais. Embora tecnicamente válidos e rastreáveis, esses documentos possuem linguagem analítica, formato pouco didático e leitura voltada ao público técnico, dificultando a interpretação rápida pelos clientes internos e ocasionando equívocos de interpretação além da geração de dúvidas frequentes.', N'01 - Imagens/02 - Depois/10953.jpeg', N'Com a aplicação do Kaizen, foi desenvolvido um modelo consolidado, visual e gerencial do Boletim Semanal de Potabilidade, permitindo transformar os dados laboratoriais em informação objetiva, acessível e orientada à tomada de decisão. O novo formato apresenta, em uma única interface, a aderência ao padrão de potabilidade, o status por ponto de consumo, os parâmetros monitorados e a performance geral da campanha. A melhoria aumentou a clareza, rastreabilidade e transparência da comunicação dos resultados de potabilidade, permitindo visualizar as informações com grande rapidez se a água está própria para consumo humano, se houve não conformidades e quais pontos foram monitorados, fortalecendo a confiança dos usuários e a governança do processo de saneamento.', NULL, N'O Kaizen atingiu a meta proposta ao melhorar significativamente a governança, transparência, padronização e comunicação dos resultados de potabilidade. O novo boletim reduziu a dependência da leitura individual dos laudos, facilitou a compreensão pelos clientes internos e fortaleceu a gestão visual da qualidade da água potável na Mina Salobo.', N'1. Informação técnica precisa ser traduzida para linguagem gerencial; 2. A consolidação reduz retrabalho e melhora a tomada de decisão;  3. Indicadores visuais aumentam a confiança dos clientes internos;  4. O boletim melhora a rastreabilidade e mantém a robustez técnica; 5. A gestão da potabilidade deve ser proativa, não apenas reativa; 6. Padronização fortalece a governança; 7. O Kaizen reduziu desperdício de inventário de informação.', 0, NULL, N'Organizar os materiais da tancagem de diesel em um local adequado, melhorando o acesso, o controle dos itens e reduzindo desperdícios por meio do reaproveitamento de tambores.', '2026-06-26T00:00:00.000', '2026-06-30T09:26:54.000', N'81046430', NULL, NULL);
INSERT INTO #PVC VALUES (10954, N'81063756', N'81063756', N'Inclusão automática de novas notas na base da célula de projetos', 1, N'Others/Outros', N'Os integrantes da Célula de Projetos precisavam acessar o Dashboard de Notas YE, copiar as novas notas, e colar em sua base de controle. Esse procedimento era completamente manual e exaustivo.', N'Reduzir esforço manual de atualização da base de dados da célula de projetos com inclusão de novas notas', N'10015', N'01 - Imagens/01 - Antes/10954.jpeg', N'Os integrantes da Célula de Projetos precisavam acessar o Dashboard de Notas YE, copiar as novas notas, e colar em sua base de controle. Esse procedimento era completamente manual e exaustivo.
INSERT INTO #PVC VALUES (10955, N'81039680', N'81050084', N'MELHORIA NA FIXAÇÃO DOS TRILHOS DO CABEÇA MÓVEL DA MOAGEM', 1, N'No Replication/Sem replicação', N'PARADAS POR FALHAS NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02 DEVIDO A AVARIAS NOS TRILHOS, CAUSADAS POR FALHAS DE FIXAÇÃO, OCASIONANDO DESNIVELAMENTO DOS TRILHOS.', N'GARANTIR A CONFIABILIDADE DO ATIVO', N'10178', N'01 - Imagens/01 - Antes/10955.jpeg', N'PARADAS POR FALHAS NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02 DEVIDO A AVARIAS NOS TRILHOS, CAUSADAS POR FALHAS DE FIXAÇÃO, OCASIONANDO DESNIVELAMENTO DOS TRILHOS.', N'01 - Imagens/02 - Depois/10955.jpeg', N'APÓS A FIXAÇÃO DOS CHUMBADORES DOS TRILHOS DA TR-2303SA-02, REALIZADA PELA EQUIPE ESPECIALIZADA DA HITA, O EQUIPAMENTO RETORNOU ÀS CONDIÇÕES OPERACIONAIS ADEQUADAS, RESTABELECENDO A CONFIABILIDADE OPERACIONAL DO ATIVO.', NULL, N'APÓS A EXECUÇÃO DOS SERVIÇOS DE FIXAÇÃO DOS CHUMBADORES DOS TRILHOS PELA EQUIPE ESPECIALIZADA DA HITA, O DESVIO FOI ELIMINADO, RESTABELECENDO O ALINHAMENTO E A INTEGRIDADE DOS TRILHOS. COMO RESULTADO, O EQUIPAMENTO RETORNOU ÀS CONDIÇÕES OPERACIONAIS ADEQUADAS, RECUPERANDO SUA CONFIABILIDADE OPERACIONAL E MITIGANDO O RISCO DE NOVAS PARADAS E PERDAS DE PRODUÇÃO ASSOCIADAS À FALHA IDENTIFICADA.', N'MELHORIA CONTÍNUA', 0, NULL, N'reduzir tempo de maquina parada por conta de reparos com pinturas', '2026-05-13T00:00:00.000', '2026-06-30T10:00:54.000', N'81039680', NULL, NULL);
INSERT INTO #PVC VALUES (10956, N'81063756', N'81063756', N'Boletim informativo de alteração em estratégia de manutenção', 1, N'Others/Outros', N'Não existia uma maneira formal de comunicar alterações propostas pela engenharia de estratégia. Gerando reclamações das áreas impactadas pela demora em receber tais atualizações.', N'Manter áreas impactadas atualizadas de alterações em estratégia de manutenção', N'10015', N'01 - Imagens/01 - Antes/10956.jpeg', N'Não existia uma maneira formal de comunicar alterações propostas pela engenharia de estratégia. Gerando reclamações das áreas impactadas pela demora em receber tais atualizações.
INSERT INTO #PVC VALUES (10957, N'369561', N'369561', N'Report KPIs LHS  - Plano A+3', 1, N'No Replication/Sem replicação', N'Dificuldade de obtenção de informações dos KPIs do sequenciamento de Cava e Pilhas para análises e divulgação dos resultados do Plano A+3.', N'Informações de KPIs rápidos e organizados referente ao sequenciamento de Cava e Pilhas para os Planos A+3', N'10162', N'01 - Imagens/01 - Antes/10957.jpeg', N'Para obtenção dos KPIs, era necessário fazer exportação de vários arquivos no Excel com tabelas de resumo para análises e divulgação dos resultados.', N'01 - Imagens/02 - Depois/10957.jpeg', N'Implantação de um template no Deswik.Sched para exportação automática e organizada dos KPIs do plano para o Excel.', NULL, N'SIM', N'Tratativas de dados automaticamente elimina a possibilidade de erros.', 0, NULL, N'alguns itens foram reutilizados de outras áreas, mantendo de forma mais econômica na execução do projeto.', '2026-06-15T00:00:00.000', '2026-06-30T10:13:08.000', N'369561', NULL, NULL);
INSERT INTO #PVC VALUES (10958, N'1010242', N'1010242', N'D2 PID Cleanup', 1, N'No Replication/Sem replicação', N'Since the migration of all previous doc management systems into D2, there has been a significant number of duplicated files.  The most important documents affected are PIDs (there are other types duplicated as well - which I will work on in the future).  These duplicated files could pose a risk to D2 users if they are unfamiliar with the search method or doc management standard.  Choosing the incorrect PID could give them a very inaccurate version and something that does not show field accurate conditions.', N'To provide a single document, eliminating the need and risk to choose between multiple options.', N'10342', N'01 - Imagens/01 - Antes/10958.jpeg', N'There are a significant number of duplicated PID numbers in D2.  Not only are the layering of versions incorrect and duplicated, but there are different variations of the same PID number.  To reduce the risk of using the wrong PID number, we have marked all old versions as Superseded status and just the one correct PID as Effective status. ', N'01 - Imagens/02 - Depois/10958.jpeg', N'After multiple conversations with the D2 Support Team, it was determined that this migration issue was not an error with D2 itself and therefore it was something that I would have to correct manually.  This process involves viewing/downloading each version of the files, deleting the revisions that are duplicated, deleting the variations of the number so that when we run a search we only get one result, and keeping a log of all meta data of the files removed. D2 currently has 749 PIDs, this initiative is a work in progress, but thus far I have gone through 100 PIDs and removed 2574 versions.  Once this entire task is complete, it will remove all risk of opening the incorrect PID and will make searching in D2 smoother.', NULL, N'Once I have managed all 749 PIDs, this problem should no longer exist.', N'Develop a more comprehensive migration plan prior to completing the migration, migrate in small sets of documents', 0, NULL, N'Alinhamento entre as áreas de interesse, que trouxe maior previsibilidade pra todos.', '2026-06-29T00:00:00.000', '2026-06-30T10:25:37.000', N'1010242', NULL, NULL);
INSERT INTO #PVC VALUES (10959, N'538725', N'538725', N'Sistema de aterramento para reabastecimento de comboio', 2, N'Others/Outros', N'Identificado que o conjunto (carretel, cabo e garra de conexão) apresenta condições inadequadas de conservação, com sinais de desgaste, sujeira e possível oxidação.
INSERT INTO #PVC VALUES (10960, N'81063756', N'81063756', N'Atualização da base de Workforce MDM do BI de Notas YE', 1, N'Others/Outros', N'Vários colaboradores da gerência estavam apresentando o status de INATIVO NO SITEMA no campo referente à gerência do Criador da Nota. E foi detectado que a base Workforce MDM estava a mais de 1 ano desatualizada.', N'Atualizar a base de Workforce MDM do BI de Notas YE para eliminar o status INATIVO NO SISTEMA de colaboradores ativos', N'10015', N'01 - Imagens/01 - Antes/10960.jpeg', N'Vários colaboradores da gerência estavam apresentando o status de INATIVO NO SITEMA no campo referente à gerência do Criador da Nota. E foi detectado que a base Workforce MDM estava a mais de 1 ano desatualizada.', N'01 - Imagens/02 - Depois/10960.jpeg', N'Atualização da base de Workforce MDM no SharePoint e no Power BI e a gerência do criador da nota passou a refletir corretamente.', NULL, N'Os colaboradores ativos no sistema tiveram o campo que antes apontava "INATIVO NO SISTEMA" regularizado.', N'Extração de base Workforce MDM atualizada', 0, NULL, N'Compartilhamento contínuo por meio de pílulas de conhecimento rápidas e acessíveis', '2026-06-08T00:00:00.000', '2026-06-30T11:06:12.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (10961, N'81044914', N'81044914', N'Redução de custo com licenças de informática não utilizadas', 1, N'Others/Outros', N'Atualmente, as licenças de informática não são revisadas, ou seja, algum funcinário pode ter alguma licença que não utiliza mais ou que não precisa gerando custos desnecessários à organização', N'Reduzir custos com licenças não utilizadas', N'10222', N'01 - Imagens/01 - Antes/10961.jpeg', N'Geração de custos com licenças sem gestão próxima', N'01 - Imagens/02 - Depois/10961.jpeg', N'Redução de R$ 5.600 anuais em licenças não utilizadas no PCM', NULL, N'Redução  de R$ 5.600 anuais em licenças de informática que não estavam sendo utilizadas e relocação com a relocação, o valor total vai pra R$ 13.400', N'Redução de custos, otimização de custos, sentimento de dono, empoderamento com comprometimento', 5600, 1, N'Workers know how to get to each piece of equipment ', '2026-06-23T00:00:00.000', '2026-06-30T11:12:14.000', N'81044914', NULL, NULL);
INSERT INTO #PVC VALUES (10962, N'81063756', N'81063756', N'Atualização da base de equipamentos da mina SLB no formulário de disparo de gatilho manual de RAF', 1, N'Others/Outros', N'O formulário estava bastante desatualizado, a ponto de que faltavam uma série de equipamentos novos, o que dificultava o time de Confiabilidade a disparar gatilhos manuais de RAF. Além disso, os disparos manuais de Pneus no BI sempre eram disparados para o responsável pelo equipamento, e não pelo responsável de Pneus.', N'Atualizar base de equipamentos da mina SLB no formulário de disparo de gatilho manual de RAF', N'10015', N'01 - Imagens/01 - Antes/10962.jpeg', N'O formulário estava bastante desatualizado, a ponto de que faltavam uma série de equipamentos novos, o que dificultava o time de Confiabilidade a disparar gatilhos manuais de RAF. Além disso, os disparos manuais de Pneus no BI sempre eram disparados para o responsável pelo equipamento, e não pelo responsável de Pneus.', N'01 - Imagens/02 - Depois/10962.jpeg', N'Hoje temos a lista de equipamentos do atualizada no formulário e os gatilhos manuais de RAF de pneus estão sendo devidamente apontados para o responsável por pneus no BI.', NULL, N'Agora a lista de equipamentos do formulário está atualizada e os gatilhos manuais de RAF de pneus redirecionados para o devido responsável.', N'Edição de formulários Vale Forms', 0, NULL, N'Vacuum quality control now has a baseline, and vacuum effectiveness can be validated periodically. ', '2026-06-10T00:00:00.000', '2026-06-30T11:54:32.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (10963, N'81040303', N'81040303', N'SmartRAF — Motor de Maturidade de RAF da Usina Salobo', 1, N'Others/Outros', N'A análise das RAFs (Registro de Análise de Falha) da Usina Salobo era feita 
INSERT INTO #PVC VALUES (10964, N'81040303', N'81040303', N'Boletim Diário VPS por Coordenação — Salobo', 1, N'Others/Outros', N'O acompanhamento das pendências de rotina VPS em Salobo (Diário de Bordo, Ações Stratws+SAP, Treinamentos, Kaizens, IRIS/Proativos de Segurança e YE) era manual, disperso entre múltiplos sistemas e sem ritual padronizado, gerando falta de visibilidade em tempo real, risco de descumprimento de prazos e metas, retrabalho dos coordenadores e perda de aderência aos indicadores estratégicos do FMDS e do Gerenciamento da Rotina.', N'Garantir 100% de visibilidade diária das pendências de rotina por coordenação em Salobo, via notificação automática no Microsoft Teams, elevando a aderência aos indicadores VPS (DB, Ações, Treinamentos, Kaizens, IRIS e YE) em até 90 dias após o go-live (22/06/2026).', N'10293', N'01 - Imagens/01 - Antes/10964.jpeg', N'Antes do Boletim Diário VPS, cada coordenador precisava acessar manualmente Stratws, SAP, SharePoint e Power BI para identificar pendências de DB, ações, treinamentos, kaizens, IRIS e YE. Não havia ritual fixo, canal único nem notificação automática, o que gerava:
INSERT INTO #PVC VALUES (10965, N'1013697', N'1013697', N'Ultrasonic Autolubricators for RB 425L Pump Station', 1, N'Underground/Subterrâneo', N'Manual greasing required on calendar based frequency for main dewatering pumps in Reid Brook mine. Limited condition based monitoring.', N'Improve condition based monitoring and MTBF', N'10311', N'01 - Imagens/01 - Antes/10965.jpeg', N'Grease zerks located on pump and motor require manual greasing, and lack of sensors for condition based monitoring. Manual greasing takes time for technician to visit the area and requires them to work around running equipment.', N'01 - Imagens/02 - Depois/10965.jpeg', N'Ultrasonic sensors and autolubricators installed on the pump and motor. The sensors continuously monitor the equipment and will grease the bearings based on friction readings. This reduces the labour required to manually grease, and provides information on asset health and the ability to predict failures in advance, minimizing unplanned down time.', NULL, N'Yes. Ultrasonic autolubricators are able to grease equipment automatically reducing labour resources, and improving condition based monitoring. Asset health is able to be monitored remotely.', N'Predictive maintenance and resource efficiency', 0, NULL, NULL, '2026-06-01T00:00:00.000', '2026-06-30T13:14:39.000', N'1013697', NULL, NULL);
INSERT INTO #PVC VALUES (10966, N'121608', N'121608', N'Tambor trasformado em armario', 3, N'Others/Outros', N'Os materiais utilizados nas atividades da tancagem de recebimento de diesel não possuíam um local adequado e padronizado para armazenamento, permanecendo dispersos na área operacional. Essa condição dificultava a organização, o acesso e o controle dos itens, aumentando o risco de perdas e danos aos materiais.
INSERT INTO #PVC VALUES (10967, N'81011163', N'81062557', N'Implementação de Manutenção Preditiva com PDMA nos Motores da Correia 2101-TC-02', 1, N'Others/Outros', N'Os motores da correia transportadora 2101-TC-02 são ativos críticos no fluxo da britagem, conforme fluxograma do processo, sendo responsáveis pelo transporte do minério britado até a pilha de 38.000 t. Uma falha corretiva nesses motores resulta na parada total do processo de britagem por aproximadamente 12 horas, impactando diretamente a alimentação da planta. Atualmente, o plano de manutenção desses motores contempla apenas inspeções sensitivas, termografia, análise de vibração, medição de isolação e lubrificação periódica. Não há monitoramento preditivo elétrico capaz de identificar antecipadamente falhas internas como: degradação de isolação entre espiras, barras quebradas de rotor, excentricidade, desequilíbrios de alimentação e contaminação dos enrolamentos. A ausência dessa camada preditiva eleva o risco de falhas inesperadas, cujo impacto financeiro de uma única ocorrência (12h de parada) é de R$ 7.726.184,81 em lucro cessante, considerando taxa da usina de 2.300 t/h, teores de ', N'Reduzir em no mínimo 80% a ocorrência de falhas corretivas nos motores da correia 2101-TC-02, por meio da inclusão da análise preditiva elétrica (PDMA) no plano de manutenção, eliminando paradas não programadas da britagem e evitando perdas de produção superiores a R$ 7,7 milhões por evento.', N'10081', N'01 - Imagens/01 - Antes/10967.jpeg', N'O plano de manutenção atual contempla inspeções sensitivas, termografia, análise de vibração, medição de resistência de isolação e lubrificação periódica, proporcionando monitoramento adequado dos aspectos mecânicos e parte das condições elétricas dos equipamentos.
INSERT INTO #PVC VALUES (10968, N'81006946', N'81006946', N'Gaiola para Armazenar tintas', 3, N'Others/Outros', N'ausência de tinta na área quando necessário por falta de local para armazenar corretamente.', N'otimizar reparos que necessitam de pinturas', N'10139', N'01 - Imagens/01 - Antes/10968.jpeg', N'A área não possuía um local adequado para armazenar tintas utilizadas em pequenos reparos após serviços de solda em equipamentos. Essa condição comprometia a organização, dificultava o controle dos materiais, aumentava o risco de danos às embalagens e poderia ocasionar desperdícios, impactando a eficiência das atividades de manutenção.', N'01 - Imagens/02 - Depois/10968.jpeg', N'Com a confecção da gaiola para armazenamento de tintas, foi possível organizar adequadamente os materiais, facilitar o controle de estoque.', NULL, N'sim! se mantermos a disciplina.', N'a organização e o armazenamento adequados das tintas melhoram a segurança', 0, NULL, N'MELHOR ASPECTO VISUAL.', '2026-06-29T00:00:00.000', '2026-06-30T15:03:23.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (10969, N'81030963', N'81038507', N'PULSO SEGURO – Segurança Inclusiva por Alerta Vibratório', 1, N'Others/Outros', N'A dependência de alertas sonoros limitava a percepção de riscos por pessoas com deficiência auditiva, reduzindo sua autonomia e aumentando o tempo de resposta em situações de emergência.', N'Aumentar percepção de risco do colaborador e dar a ele autonomia ', N'10079', N'01 - Imagens/01 - Antes/10969.jpeg', N'A dependência de alertas sonoros limitava a percepção de riscos por pessoas com deficiência auditiva, reduzindo sua autonomia e aumentando o tempo de resposta em situações de emergência.', N'01 - Imagens/02 - Depois/10969.jpeg', N'Após a implantação do Pulso Seguro, colaboradores com deficiência auditiva passaram a receber alertas imediatos por vibração, ampliando a segurança, autonomia, inclusão e agilidade nas emergências.', NULL, N'Meta: Garantir que 100% dos colaboradores recebam alertas de segurança de forma imediata e acessível', N'QUE PODEMOS USAR TECNOLOGIA COMO ALIADO DA SEGURANÇA ', 0, NULL, N'Promover maior integração entre os colaboradores da Governança de Contratos, aumentar o engajamento da equipe em iniciativas coletivas e criar um ambiente digital colaborativo que facilite o conhecimento das competências, experiências e conquistas dos integrantes da equipe.', '2026-06-19T00:00:00.000', '2026-06-30T15:03:41.000', N'81030963', NULL, NULL);
INSERT INTO #PVC VALUES (10970, N'520942', N'520942', N'Cobertura em parada de onibus', 2, N'No Replication/Sem replicação', N'qualidade e segurança para todos os empregados que fazem uso desse espaço.', N'valorizar pessoas', N'10232', N'01 - Imagens/01 - Antes/10970.jpeg', N'parada de ônibus para revezamento de turno, com exposição de sol e chuva no posto de combustível.', N'01 - Imagens/02 - Depois/10970.jpeg', N'cobertura na parada de ônibus para os empregados realizarem de forma mais segura, pois garante proteção e integridade das pessoas.', NULL, N'problema resolvido e aprovado pelos usuários.', N'Valorizar pessoas', 0, NULL, N'Redução no tempo de criação da estratégia, maior segurança nas ações traçadas.', '2026-06-02T00:00:00.000', '2026-06-30T15:26:15.000', N'520942', NULL, NULL);
INSERT INTO #PVC VALUES (10971, N'525833', N'525833', N'Report Mapa de Componente M+12', 1, N'Others/Outros', N'Falta de controle e reporte das projeções de troca de componentes da frota de escavação gera falha na comunicação entre planejamento, programação e execução, causando ausência de programação por falta de info sobre troca, OM e material.', N'Dar visibilidade as projeções de troca de componente', N'10023', N'01 - Imagens/01 - Antes/10971.jpeg', N'Falta de controle e reporte das projeções de troca de componentes da frota de escavação gera falha na comunicação entre planejamento, programação e execução, causando ausência de programação por falta de info sobre troca, OM e material.', N'01 - Imagens/02 - Depois/10971.jpeg', N'Após implantação, há controle centralizado das projeções, integração entre áreas e visibilidade de prazos, OM e materiais, garantindo programação antecipada e maior eficiência nas trocas.
INSERT INTO #PVC VALUES (10972, N'503120', N'52548', N'Organizador de equipamentos de manejo de fauna ', 3, N'Others/Outros', N'Durante as ações de resgate e manejo de fauna, os equipamentos eram transportados de forma solta na carroceria da caminhonete, permanecendo expostos às intempéries, o que comprometia sua conservação, segurança e eficiência operacional.', N'Melhor condicionamento dos equipamentos, bem como durabilidade.', N'10104', N'01 - Imagens/01 - Antes/10972.jpeg', N'Durante as ações de resgate e manejo de fauna, os equipamentos eram transportados de forma solta na carroceria da caminhonete, permanecendo expostos às intempéries, o que comprometia sua conservação, segurança e eficiência operacional.', N'01 - Imagens/02 - Depois/10972.jpeg', N'Atualmente, os equipamentos de resgate e manejo de fauna são armazenados em um organizador adequado, permitindo fácil acesso pela lateral da caminhonete e garantindo maior agilidade, organização e preservação dos materiais.', NULL, N'Com essa iniciativa, houve ganho significativo no tempo de resposta, na organização das atividades e na adoção de uma postura ergonômica mais adequada pelos empregados.', N'Atividades planejadas e organizadas são mais eficazes.', 0, NULL, N'Diminuição de tempo na execução da atividade.', '2026-06-29T00:00:00.000', '2026-06-30T15:38:37.000', N'503120', NULL, NULL);
INSERT INTO #PVC VALUES (10973, N'81030963', N'81047196', N'P Conhecimento que Protege: Pílulas de Segurança Baseadas nos PROs', 1, N'Others/Outros', N'Os PROs estavam disponíveis, mas o compartilhamento do conhecimento nem sempre alcançava toda a equipe, podendo gerar dúvidas operacionais e interpretações divergentes dos procedimentos.a.', N'Garantir que 100% da equipe tenha acesso rápido e padronizado aos procedimentos operacionais (PROs), fortalecendo o compartilhamento do conhecimento, reduzindo dúvidas operacionais e aumentando a conformidade com os requisitos de segurança.', N'10079', N'01 - Imagens/01 - Antes/10973.jpeg', N'Os PROs estavam disponíveis, mas o compartilhamento do conhecimento nem sempre alcançava toda a equipe, podendo gerar dúvidas operacionais e interpretações divergentes dos procedimentos.', N'01 - Imagens/02 - Depois/10973.jpeg', N'Com a criação das Pílulas de Conhecimento de Segurança, baseadas nos PROs de Armazenagem, Estocagem e Operação do Armazém e CMD, o conhecimento passou a ser compartilhado de forma simples, objetiva e contínua.
INSERT INTO #PVC VALUES (10974, N'81050261', N'81050261', N'Refinery Drawings on Lunch Room Board ', NULL, N'Refining/Refino', N'New team for Refinery had issues with finding certain types of equipment throughout the areas.  ', N'View Drawings before proceeding to equipment ', N'0', N'01 - Imagens/01 - Antes/10974.jpeg', N'No GA''s Drawings for the team to view before heading out into the building ', N'01 - Imagens/02 - Depois/10974.jpeg', N'GA''s and Drawings posted on the Lunch Room Wall ', NULL, N'Yes', N'Give as many documents to personnel as requested ', 0, NULL, N'Consumo de explosivos foi adequado a real necessidade.', '2026-06-28T00:00:00.000', '2026-06-30T16:05:38.000', N'81050261', NULL, NULL);
INSERT INTO #PVC VALUES (10975, N'200768', N'200768', N'Road dust sampling vacuum - using a battery vs generator', 2, N'No Replication/Sem replicação', N'Workers are exposed to hazards when using a generator for road dust sampling. 
INSERT INTO #PVC VALUES (10976, N'81044397', N'81044397', N'    Reaproveitamento de Peças para Confecção de Suporte de Luvas', 3, N'Projects/Projetos', N'As luvas utilizadas pelos colaboradores não possuíam um local adequado para armazenamento, o que dificultava a organização, o acesso rápido ao EPI e contribuía para o desperdício de materiais. Além disso, havia peças sem utilização que poderiam ser reaproveitadas para atender essa necessidade.', N'Promover a organização dos EPIs, reduzir desperdícios e incentivar o reaproveitamento de materiais disponíveis na unidade.', N'10213', N'01 - Imagens/01 - Antes/10976.jpeg', N'As luvas utilizadas pelos colaboradores não possuíam um local adequado para armazenamento, o que dificultava a organização, o acesso rápido ao EPI e contribuía para o desperdício de materiais. Além disso, havia peças sem utilização que poderiam ser reaproveitadas para atender essa necessidade.', N'01 - Imagens/02 - Depois/10976.jpeg', N'Foi confeccionado um suporte para luvas utilizando peças reaproveitadas que estavam sem utilização. A solução permitiu a criação de um local adequado para armazenamento e disponibilização das luvas, facilitando o acesso dos colaboradores, melhorando a organização do ambiente de trabalho e reduzindo o desperdício de materiais. A ação contribuiu para a otimização dos recursos existentes, promovendo sustentabilidade e melhoria contínua no processo.', NULL, N'Sim', N'O reaproveitamento de materiais disponíveis pode gerar soluções simples, eficazes e de baixo custo para as necessidades do dia a dia. Com criatividade e foco na melhoria contínua, é possível otimizar recursos, reduzir desperdícios e melhorar a organização do ambiente de trabalho.', 0, NULL, N'É POSSIVE REALIZAR ATIVIDADES SIMULTANEAS COM MINIMIZAÇÃO DO RISCO DE PROJEÇÃO DE LIMALHAS', '2026-06-28T00:00:00.000', '2026-06-30T16:49:50.000', N'81044397', NULL, NULL);
INSERT INTO #PVC VALUES (10977, N'81047013', N'478939', N'Espaço adequado para conjunto oxicorte', NULL, N'Others/Outros', N'O carrinho de conjunto de oxicorte ficava dentro da caldeiraria muito próximo da bancada de realização das atividades, oferecendo riscos para o time.', N'Retirar o conjunto de oxicorte do raio de atividades na caldeiraria', N'10362', N'01 - Imagens/01 - Antes/10977.jpeg', N'O carrinho de conjunto de oxicorte ficava dentro da caldeiraria muito próximo da bancada de realização das atividades, oferecendo riscos para o time.', N'01 - Imagens/02 - Depois/10977.jpeg', N'Foi fabricado um espaço para disposição do conjunto de oxicorte e do carrinho, com cobertura, suporte adequado, mais de 5 metros de distância do local de atividade, possibilitando atuação mais segura.', NULL, N'Meta totalmente alcançada com a disposição do conjunto de oxicorte em uma distância segura para a realização das atividades.', N'Segurança', 0, NULL, N'Elaborado Book de FDS, disponivel em local de facil acesso e com gestao a vista na entrada da ferramentaria', '2026-06-12T00:00:00.000', '2026-06-30T17:13:57.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (10978, N'81020643', N'81020643', N'Aplicação de adesivos na sinalização de emergência de PAEBM', 1, N'Others/Outros', N'Baixa ou nenhuma visibilidade da sinalização de emergência do PAEBM.', N'Otimizar custo na fabricação e agilizar conformidade operacional da sinalização de emergência do PAEBM', N'10141', N'01 - Imagens/01 - Antes/10978.jpeg', N'Aqui está um exemplo de placa de rota de fuga sentido único
INSERT INTO #PVC VALUES (10979, N'81047013', N'472909', N'Substituição do recalque da 2051BP01R', NULL, N'Others/Outros', N'TUBULAÇÃO DE RECALQUE DA BOMBA DE POÇO DA BRITAGEM MUITO DETERIORADA, IMPACTANDO O PROCESSO POR REPETIDAS FALHAS', N'Trocar tubulação danificada por uma mais resistente', N'10362', N'01 - Imagens/01 - Antes/10979.jpeg', N'TUBULAÇÃO DE RECALQUE DA BOMBA DE POÇO DA BRITAGEM MUITO DETERIORADA, IMPACTANDO O PROCESSO POR REPETIDAS FALHAS', N'01 - Imagens/02 - Depois/10979.jpeg', N'REALIZADA SUBSTITUIÇÃO DA TUBULAÇÃO DE AÇO CARBONO POR UMA DE INOX, MUITO MAIS RESISTENTE, ALÉM DE TER SIDO COLOCADO UM FLANGE PARA FACILITAR A MANUTENÇÃO', NULL, N'Meta alcançada com a troca da tubulação por uma de material mais resistente', N'PRODUTIVIDADE', 0, NULL, N'Redução no tempo dedicado a avaliação dos dados e retorno rápido na aprovação ou rejeição da nova projeção de DF.', '2026-06-24T00:00:00.000', '2026-06-30T17:43:08.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (10980, N'81042217', N'551106', N'Implantação de ponto de ar comprimido dedicado no transportador TC12 para eliminação de deslocamentos e esforço operacional​', 2, N'Others/Outros', N'Segurança operacional · Ar comprimido · Ergonomia · Redução de esforço físico · Kaizen · Eficiência operacional · Melhoria contínua', N'Eliminar a necessidade de utilização do ponto de ar comprimido do TC14 para atendimento ao TC12.​ Reduzir o esforço físico dos colaboradores durante a atividade.​  Aumentar a segurança ao evitar deslocamentos frequentes em escadas e áreas elevadas.​  Tornar a atividade mais ágil e eficiente, garantindo execução no próprio local de trabalho.', N'10294', N'01 - Imagens/01 - Antes/10980.jpeg', N'Com a inexistência de ponto de ar comprimido no TC12 para realizar atividades de limpeza no local havia a necessidade de puxar a mangueira do TC14 até o TC12, dificultando a execução da atividade, sendo necessário um colaborador permanecer no TC14 para ligar/desligar o ar comprimido, com deslocamentos frequentes em escadas para manuseio da mangueira e esforço físico elevado para transporte e posicionamento da mangueira e limitação de alcance para execução de atividades em outros pontos do TC12. Com esse trabalho foi possível se eliminar o principal desperdício que era o de Movimentação desnecessária e espera onde com o ponto', N'01 - Imagens/02 - Depois/10980.jpeg', N'Instalação de ponto de ar comprimido dedicado no TC12, com válvula de fácil acesso, essa melhoria trouxe a eliminação da necessidade de utilizar o ponto do TC14, podendo ser executada atividades simultâneas no 14 e 12, redução significativa do esforço físico e dos deslocamentos entre transportadores, aumento da autonomia do colaborador para execução da atividade com a ampliação do alcance da mangueira para atender outros pontos do próprio transportador garantindo uma limpeza mais eficiente e com menos impacto ao colaborador e ao ativo.​', NULL, N'O problema foi resolvido com a implantação do ponto de ar comprimido no TC12 que eliminou a necessidade de utilização do TC14, reduzindo deslocamentos, esforço físico e dependência de outro colaborador. A atividade passou a ser realizada diretamente no local, com maior segurança, agilidade e eficiência, atendendo aos objetivos propostos e eliminando desperdícios do processo.​', N'A disponibilização de recursos no ponto de uso reduz esforços e aumenta a segurança com pequenas adaptações estruturais pode ser gerados ganhos significativos em produtividade e qualidade operacional. A eliminação do risco de deslocamentos desnecessários melhora a eficiência e reduz cenários de potenciais acidentes. A autonomia operacional é um fator chave para garantir uma produção segura.​', 0, NULL, N'Confeccionado com materiais sobressalentes na area, um suporte para caixa termica, eliminando o contato direto com o solo/chão e minimizando riscos ergonomicos', '2026-05-22T00:00:00.000', '2026-06-30T17:45:53.000', N'81042217', NULL, NULL);
INSERT INTO #PVC VALUES (10981, N'498359', N'81046967', N'5S SALA DE LUBRIFICAÇÃO 2251MO02', 3, N'Others/Outros', N'SALA DE LUBRIFICAÇÃO DO MOINHO DE BOLAS 02 COM EXCESSIVA QUANTIDADE DE ÓLEO DERRAMADO COM RISCO DE QUEDA.', N'SANAR CONDIÇÕES INSEGURAS NA SALA REFERENTES A PISO ESCORREGADIO', N'10362', N'01 - Imagens/01 - Antes/10981.jpeg', N'SALA DE LUBRIFICAÇÃO DO MOINHO DE BOLAS 02 COM EXCESSIVA QUANTIDADE DE ÓLEO DERRAMADO COM RISCO DE QUEDA.', N'01 - Imagens/02 - Depois/10981.jpeg', N'FOI REALIZADA LIMPEZA DO PISO, PAREDE E TETO, TROCADAS AS MANTAS DE CONTENÇÃO, SANADO VAZAMENTO DE ÓLEO, IDENTIFICADO MATERIAIS.', NULL, N'META ALCANÇADA COM A ÁREA LIMPA E INSENTA DE RISCO DE QUEDA DE MESMO NIVEL E NIVEL DIFERENTE', N'SEGURANÇA', 0, NULL, N'Confeccionado com materiais sobressalentes um suporte de calços de rodas de caminhonete, instalado em local de facil acesso, na lateral da carroceria', '2026-06-29T00:00:00.000', '2026-06-30T17:57:57.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (10982, N'533528', N'533528', N'Plataforma Gamificada - Finanças Legends - Copa 2026', 1, N'Others/Outros', N'A equipe de Governança de Contratos possuía poucas iniciativas estruturadas para integração entre os colaboradores, resultando em oportunidades limitadas para conhecer competências, experiências, conquistas pessoais e profissionais dos colegas. Além disso, não existiam mecanismos de gamificação que incentivassem a participação, colaboração e engajamento de forma contínua.', N'Aumentar o engajamento, a interação e o conhecimento entre os integrantes da Governança de Contratos por meio de uma plataforma gamificada de missões, ranking e álbum de figurinhas digitais.', N'10078', N'01 - Imagens/01 - Antes/10982.jpeg', N'A equipe de Governança de Contratos não possuía uma ferramenta estruturada para promover integração, reconhecimento e interação entre os colaboradores. O conhecimento sobre os colegas estava restrito às atividades do dia a dia, dificultando a identificação de competências, experiências e interesses em comum.
INSERT INTO #PVC VALUES (10983, N'81054422', N'81054422', N'Visão de Estratégia de Congelamento de Planos da GP2026', NULL, N'Others/Outros', N'Dificuldade na estruturação do processo de congelamento de planos da GP2026 em virtude da grande quantidade de informações.', N'Permitir uma definição ágil e clara dos congelamentos de planos de manutenção durante a GP2026', N'10081', N'01 - Imagens/01 - Antes/10983.jpeg', N'Sem visão clara da estratégia para congelamento dos planos, sendo necessárias várias manipulações com diversos dados.', N'01 - Imagens/02 - Depois/10983.jpeg', N'Visão clara, montada a partir de código VBA, trazendo todas as informações necessárias de quais planos devem ser congelados e quando.', NULL, N'A meta foi alcançada, pois a ferramenta permite a definição ágil e clara dos congelamentos de planos de manutenção durante a GP2026 através de uma visão simples e cronograma com as datas para execução do congelamento.', N'Aprofundamento na ferramenta VBA.', 0, NULL, NULL, '2026-06-29T00:00:00.000', '2026-06-30T20:21:31.000', N'81054422', NULL, NULL);
INSERT INTO #PVC VALUES (10984, N'187864', N'187864', N'Estabelecimento de Faixas Críticas de Qualidade de Energia para Acionamento de Ações Preventivas', 1, N'Projects/Projetos', N'O sistema MHT realiza o monitoramento da qualidade de energia das escavadeiras elétricas de grande porte por meio da coleta contínua de parâmetros elétricos críticos. Entretanto, a ausência de limites máximos e mínimos tecnicamente definidos para os disparos de alarmes reduz a efetividade do monitoramento, gerando alarmes excessivos ou pouco representativos. Essa condição compromete a confiabilidade das análises, aumenta o tempo de diagnóstico das equipes de manutenção e eleva o risco de falhas em componentes elétricos críticos. O projeto busca estabelecer critérios padronizados de monitoramento e alarmística, aumentando a assertividade das decisões de manutenção e a confiabilidade operacional dos ativos.', N'Definição e aplicação das grandezas elétricas para o monitoramento assertivo, conforme boas práticas de monitoramento preditivo.', N'10015', N'01 - Imagens/01 - Antes/10984.jpeg', N'Não existia alarmes isso provocava, leituras continuas com inúmeros eventos estatísticos, sem uma metodologia padronizada baseada no comportamento histórico dos ativos.
INSERT INTO #PVC VALUES (10985, N'81037114', N'540124', N'Engate rápido para abastecimento ', NULL, N'Projects/Projetos', N'No fluxo anterior, era necessário realizar a desenrosca do niple para viabilizar o abastecimento do equipamento, gerando retrabalho e impactando diretamente no aumento de maquina parada.', N'Redução de tempo ', N'10144', N'01 - Imagens/01 - Antes/10985.jpeg', N'No fluxo anterior, era necessário realizar a desenrosca do niple para viabilizar o abastecimento do equipamento, gerando retrabalho e impactando diretamente no aumento de maquina parada.', N'01 - Imagens/02 - Depois/10985.jpeg', N'Depois foi implementado um engate rápido para abastecer o equipamento diminuindo assim o tempo que era gasto para abastecer. ', NULL, N'Sim', N'Sentimento de dono ', 0, NULL, N'Agilidade na definição do resultado final da análise.', '2026-06-24T00:00:00.000', '2026-06-30T21:43:35.000', N'81037114', NULL, NULL);
INSERT INTO #PVC VALUES (10986, N'81015244', N'81015244', N'OTIMIZAÇÃO DE PREVENTIVA 250h', 1, N'Open Pit/Poço aberto', N'SUBSTITUIÇÃO DE FILTROS DIESEL COM 250h TRABALHADAS SEM A AVALIAÇÃO REAL DO LIMITE DE CONTAMINAÇÃO.', N'REDUZIR TEMPO/CUSTO DE PREVENTIVA DE 250h', N'#N/A', N'01 - Imagens/01 - Antes/10986.jpeg', N'FILTROS DE DIESEL ERAM SUBSTITUÍDOS COM A FREQUÊNCIA DE 250h, MAS SEM A AVALIAÇÃO REAL DO LIMITE DE CONTAMINAÇÃO.', N'01 - Imagens/02 - Depois/10986.jpeg', N'COM A UTILIZAÇÃO DO DIESEL S10 PREMIUM FOI REALIZADO A EXTENSÃO DA VIDA DO FILTRO DE 250h PARA 500h. NÃO HOUVE PARADAS POR BAIXO RENDIMENTO OU EVENTOS DE OBSTRUÇÃO DE FILTRO.', NULL, N'A OTIMIZAÇÃO FOI ALCANÇADA E SERÁ PADRÃO NA FROTA.', N'Otimização de atividades e custos', 3, 1, N'Melhora no controle de amostras não coletadas, auxiliando a enxergar os desafios operacionais da atividade de campo. Banco de dados com mais informação do ocorrido em campo.', '2026-06-30T00:00:00.000', '2026-06-30T22:22:42.000', N'81015244', NULL, NULL);
INSERT INTO #PVC VALUES (10987, N'483318', N'483318', N'Simulador de consumo de explosivo em planilha de excel', 1, N'Others/Outros', N'Não havia medida de atendimento a demanda de massa detonada a partir do consumo necessário de explosivo.', N'Avaliar capacidade de geração de massa desmontada para atender a lavra das escavadeiras da mina do Salobo, dentro do ciclo orçamentario.', N'10323', N'01 - Imagens/01 - Antes/10987.jpeg', N'Não havia formula para calculo da massa desmontada, a partir do consumo necessário de explosivos (fabricação e aplicação).', N'01 - Imagens/02 - Depois/10987.jpeg', N'Criado em excel, o raciocínio logico entre massa desmontada e razão de carga aplicada com base em cada tipo de material especifico a ser desmontado - minério ( alto, médio e baixo teor) e estéril (rocha fresca, saprolítico e semi-intemperizado) e malha de perfuração classificada pelo diâmetro do furo.
INSERT INTO #PVC VALUES (10988, N'81004893', N'81004893', N'Controle de Utilização de Horas Ociosas e Horas Produtivas da Infraestrutura', 1, N'Others/Outros', N'Ausência de um controle estruturado para acompanhamento das horas ociosas e produtivas da equipe de infraestrutura, dificultando a análise da utilização dos recursos e a identificação de oportunidades de melhoria.', N'Implementar um controle de horas que permita monitorar a utilização dos recursos da infraestrutura, reduzindo a ociosidade e aumentando a produtividade das atividades executadas.', N'10015', N'01 - Imagens/01 - Antes/10988.jpeg', N'Não existia uma ferramenta ou processo padronizado para registrar e acompanhar horas ociosas e horas produtivas, limitando a visibilidade da performance da equipe.', N'01 - Imagens/02 - Depois/10988.jpeg', N'Foi implantado um controle estruturado com indicadores de utilização, permitindo monitorar horas produtivas e ociosas, apoiar a tomada de decisão e otimizar perfomance', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/dd8de810-0a6e-41ce-9ea7-74c7aa078d85/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvido um controle consolidado para registro e acompanhamento das horas produtivas e ociosas da infraestrutura, com indicadores e visualização gerencial que permitem monitorar a utilização dos recursos, identificar desvios e direcionar ações de melhoria contínua.', N'A disponibilização de dados confiáveis sobre utilização dos recursos possibilita identificar gargalos, direcionar ações de melhoria e aumentar a eficiência operacional.', 0, NULL, N'Na', '2026-06-19T00:00:00.000', '2026-06-30T23:29:37.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10989, N'478853', N'478853', N'BIOMBO DE SOLDA', 2, N'Others/Outros', N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'MINIMIZAR RISCOS', N'10023', N'01 - Imagens/01 - Antes/10989.jpeg', N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'01 - Imagens/02 - Depois/10989.jpeg', N'FOI CONFECCIONADO UM BIOMBOM COM MATERIAIS DISPONIVEIS NA AREA, SOBRESSALENTES DE OUTRAS ATIVIDADES DE TRABALHO A QUENTE', NULL, N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'MINIMIZAÇAO DE RISCOS', 0, NULL, N'A META FOI ATINGIDA. APÓS A INSTALAÇÃO DO SUPORTE DE ANCORAGEM, O CABO PASSOU A PERMANECER CORRETAMENTE FIXADO, ELIMINANDO O RISCO DE DESPRENDIMENTO OBSERVADO ANTERIORMENTE. A MELHORIA PROPORCIONOU MAIOR SEGURANÇA OPERACIONAL, AUMENTOU A CONFIABILIDADE DO SISTEMA E CONTRIBUIU PARA A REDUÇÃO DE FALHAS E CUSTOS DE MANUTENÇÃO.', '2026-06-10T00:00:00.000', '2026-06-30T23:30:14.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10990, N'478853', N'478853', N'Book FDS', 3, N'Others/Outros', N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'Gestao a vista e 5s', N'10234', N'01 - Imagens/01 - Antes/10990.jpeg', N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'01 - Imagens/02 - Depois/10990.jpeg', N'Elaborado Book de FDS, disponivel em local de facil acesso e com gestao a vista na entrada da ferramentaria', NULL, N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'padronização e 5s', 0, NULL, N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', '2026-06-11T00:00:00.000', '2026-06-30T23:40:41.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10991, N'81004893', N'81004893', N'Painel de Gestão de Intervenções de Telemetria', 1, N'Others/Outros', N'A gestão das intervenções originadas pela telemetria e cma eram tratadas em visões distintas realizada de forma descentralizada, dificultando o acompanhamento dos status, a priorização das ações, a identificação de pendências e a mensuração dos resultados.', N'Centralizar e automatizar a gestão das intervenções de telemetria, proporcionando visibilidade das ações, acompanhamento dos indicadores e maior agilidade na tomada de decisão. cma e telemetria', N'10015', N'01 - Imagens/01 - Antes/10991.jpeg', N'As informações de intervenções estavam distribuídas em diferentes fontes e separada cma x telemetria, com acompanhamento manual e baixa visibilidade dos status, responsáveis e evolução das tratativas.', N'01 - Imagens/02 - Depois/10991.jpeg', N'Implantação de um painel integrado que consolida as intervenções de telemetria e cma, permitindo monitoramento em tempo real por status, técnico, frota, ativo, subconjunto e data de coleta.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/06be9e1f-5fb3-4ac0-992c-634bafd795bc/be76a0215018000c25b7?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvido um painel de gestão de intervenções de telemetria que consolida automaticamente as informações das tratativas e disponibiliza indicadores operacionais em tempo real. A solução permite acompanhar o ciclo completo das intervenções, monitorar a performance do processo e direcionar esforços para as prioridades da operação.', N'A centralização das informações e a gestão visual aumentam a eficiência do acompanhamento operacional, reduzem o tempo gasto com consolidação de dados e apoiam decisões mais assertivas.', 0, NULL, N'over/under solids can impact other areas of the plant ', '2026-06-10T00:00:00.000', '2026-06-30T23:42:37.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10992, N'483318', N'483318', N'Comparativo  de DF entre ciclos Supply Review', 1, N'Others/Outros', N'Havia muita perda de tempo comparando mês a mês a projeção de DF do ciclo anterior com o ciclo atual.', N'Avaliar contribuição de projeções de Disponibilidade fisica dos equipamentos da  mina, nos ciclos de Supply Review', N'10323', N'01 - Imagens/01 - Antes/10992.jpeg', N'Não havia metodologia que comparasse a projeção de DF do ciclo anterior com a nova projeção do ciclo atual. Essa avaliação era feita consumindo muito tempo, devido ser necessário avaliar mês a mês, cada tag de equipamento. ', N'01 - Imagens/02 - Depois/10992.jpeg', N'Criando em excel, comparativo que avalia os dados da nova projeção e compara com os dados do ciclo anterior, gerando saldos e gerando valores em gráficos, separados por tipo de frota.', NULL, N'Problema resolvido.', N'Redução no tempo dedicado a avaliação dos dados', 0, NULL, N'Centralização das informações, maior rastreabilidade, visibilidade em tempo real dos processos', '2026-06-15T00:00:00.000', '2026-06-30T23:46:26.000', N'483318', NULL, NULL);
INSERT INTO #PVC VALUES (10993, N'478853', N'478853', N'Suporte Caixa Termica para Campo', 2, N'Others/Outros', N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'minimizar riscos ergonomicos e de contaminação', N'10234', N'01 - Imagens/01 - Antes/10993.jpeg', N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'01 - Imagens/02 - Depois/10993.jpeg', N'Confeccionado com materiais sobressalentes na area, um suporte para caixa termica, eliminando o contato direto com o solo/chão e minimizando riscos ergonomicos', NULL, N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'Minimização de riscos', 0, NULL, N'Processo digital, integrado, rastreável e monitorado em tempo real, proporcionando mais eficiência, governança e qualidade na gestão das solicitações de estoque.', '2026-06-17T00:00:00.000', '2026-06-30T23:49:18.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10994, N'478853', N'478853', N'Suporte calco rodas caminhonete', 3, N'Others/Outros', N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'5s', N'10234', N'01 - Imagens/01 - Antes/10994.jpeg', N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'01 - Imagens/02 - Depois/10994.jpeg', N'Confeccionado com materiais sobressalentes um suporte de calços de rodas de caminhonete, instalado em local de facil acesso, na lateral da carroceria', NULL, N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'Padronização e 5s', 0, NULL, N'Aumenta a visibilidade gerencial sobre o avanço e a qualidade dos processos;
INSERT INTO #PVC VALUES (10995, N'81053475', N'81053475', N'Implantação de Matriz Estratégica de Priorização para Otimização dos Ciclos de Estudos de RCM em Equipamentos Móveis', 1, N'Others/Outros', N'Ausência de critério estruturado para definir a sequência de elaboração dos estudos de RCM, dificultando o direcionamento dos recursos para os ativos de maior criticidade.', N'Estabelecer uma metodologia objetiva para priorizar as frotas que devem ser submetidas aos estudos de RCM, maximizando o retorno dos esforços de engenharia.', N'10015', N'01 - Imagens/01 - Antes/10995.jpeg', N'A definição dos ciclos de estudos de RCM era realizada com base em avaliações pontuais e subjetivas, sem uma metodologia padronizada que considerasse a relevância estratégica dos ativos.', N'01 - Imagens/02 - Depois/10995.jpeg', N'As frotas passaram a ser classificadas por meio de uma matriz de priorização baseada em critérios ponderados, permitindo decisões mais transparentes, consistentes e alinhadas às necessidades operacionais da mina.', NULL, N'Foi desenvolvida uma matriz de priorização contemplando critérios como modelo do equipamento, quantidade de ativos, vida média, impacto operacional e prioridade para a mina. Cada critério recebeu um peso específico, gerando um índice de criticidade capaz de classificar as frotas e definir uma sequência estruturada para execução dos estudos de RCM.', N'A utilização de critérios quantitativos e estruturados reduz a subjetividade das decisões e aumenta o alinhamento entre estratégia de manutenção e objetivos do negócio.', 0, NULL, N'A avaliação fica mais realista, pois considera não apenas o impacto técnico da falta do item, mas também a dificuldade de reposição.
INSERT INTO #PVC VALUES (10996, N'81035388', N'498389', N'Implantação de placa de identificação no acesso da Área', 1, N'No Replication/Sem replicação', N'O acesso necessita de melhoria na sinalização de parada obrigatória para reforçar a segurança viária de reduzir o risco de incidentes.', N'Identificação, padronização no acesso, facilitando a orientação e localização das áreas.', N'10257', N'01 - Imagens/01 - Antes/10996.jpeg', N'Não possuía placa de identificação. ', N'01 - Imagens/02 - Depois/10996.jpeg', N'Foi instalada uma placa de identificação no acesso, padronizando a sinalização da área.', NULL, N'A meta foi alcançada com implantação da placa de identificação no acesso. ', N'A identificação adequada dos acessos é essencial para garantir a segurança, facilitar a orientação das equipes e melhorar a eficiência operacional.', 7, 1, N'• Melhor monitoramento do processo
INSERT INTO #PVC VALUES (10997, N'81036958', N'81036958', N'JANELA VISITA TR2009-06', 1, N'Others/Outros', N'AUSENCIA DE ACESSO AO INTERIOR DO CHUTE TR2009-05/2009-06 POR OBSTRUÇÃO DE VIGAS DE TRAVAMENTO INSTALADOS PELA EQUIPE ESTRUTURAL', N'CRIAR ACESSO PARA LIMPEZA E MANUTENÇÃO ', N'10031', N'01 - Imagens/01 - Antes/10997.jpeg', N'JANELAS DE VISITA ANTIGAS FORAM DESCONTINUADAS POR SEREM EXTREMAMENTE FRAGEIS E ESTAREM OBSTRUIDAS POR VIGAS INSTALADAS PELA EQUIPE ESTRUTURAL PARA CONTER DESLOCAMENTO DAS CASAS DE TRANSFERENCIA ', N'01 - Imagens/02 - Depois/10997.jpeg', N'AO  ACESSAR JANELA DE VISITA NOVA E PADRONIZADA AO LOCAL, O ACESSO DE PESSOAS FOI RESTAURADO COM MAIOR SEGURANÇA.', NULL, N'SIM ', N'PADRONIZAÇÃO NOS LEVA AO AMBIENTE MAIS SEGURO ', 0, NULL, N'Disponibilizar um local adequado para armazenamento dos documentos, garantindo melhor organização e controle documental, reduzindo a necessidade de reimpressões e promovendo o uso mais eficiente dos recursos da área.', '2026-06-24T00:00:00.000', '2026-07-01T12:48:38.000', N'81036958', NULL, NULL);
INSERT INTO #PVC VALUES (10998, N'73197', N'73197', N'Simplificação no fluxo de análise do Comitê Pela Vida', 3, N'Others/Outros', N'Nas reuniões do Comitê Pela Vida os fluxos das violações eram feitos através de slides do Power Point, alterando cores e criando ou "arrastando" figuras manualmente para seguir um fluxo de análise. Este processo é moroso e improdutivo.', N'Reduzir o tempo de análise e melhorando a visualização  do fluxo definido', N'10337', N'01 - Imagens/01 - Antes/10998.jpeg', N'Nas reuniões do Comitê Pela Vida os fluxos das violações eram feitos através de slides do Power Point, alterando cores e criando ou "arrastando" figuras manualmente para seguir um fluxo de análise. Este processo é moroso e improdutivo.', N'01 - Imagens/02 - Depois/10998.jpeg', N'Fluxo gerado através de planilha automatizada com a sequência definida de acordo com as respostas de cada quadro, destacando as células que seguirão sendo analisadas até o apontamento da conclusão final.', NULL, N'Agilidade na definição do resultado final da análise.', N'Melhoria simples de processo manual', 0, NULL, N'Clarify the traffic plan in the paste plant.  Congested area to begin with.  ', '2026-06-26T00:00:00.000', '2026-07-01T14:40:24.000', N'73197', NULL, NULL);
INSERT INTO #PVC VALUES (10999, N'81054397', N'81022808', N'Controle no cadastramento de furos executados (FE) e amostras controle QAQC.', 1, N'No Replication/Sem replicação', N'Devido à dinâmica operacional, por vezes os furos eram executados sem devida identificação dos motivos de não amostragem, e as amostras de controle eram anotadas na mão. Como consequência, gerava dúvidas de informações, resultando em inconsistências no controle dos dados (furos perfurados Vs. furos amostrados). ', N'Cadastrar a informação diretamente no arquivo da coletora (GPS)', N'10162', N'01 - Imagens/01 - Antes/10999.jpeg', N'Devido à dinâmica operacional, por vezes os furos eram executados sem a devida identificação dos motivos de não amostragem, e as amostras de controle eram anotadas na mão. Como consequência, gerava dúvidas de informações, resultando em inconsistências no controle dos dados (furos perfurados Vs. furos amostrados). ', N'01 - Imagens/02 - Depois/10999.jpeg', N'A informação fica registrada diretamente no banco de dados, podendo ser visualizada no controle via Power BI, também ajuda a justificar a performance da amostragem.
INSERT INTO #PVC VALUES (11000, N'81044914', N'81044914', N'Locação incorreta de container SLB', 1, N'Others/Outros', N'Após o carve out, alguns containers de ssg estavam locados de maneira indevida em SLB', N'Redução do custo de locação em SLB', N'10222', N'01 - Imagens/01 - Antes/11000.jpeg', N'Durante a gestão de custos, foram verificados custos muito altos com containers na área de PCM, após avaliação cuidadosa, foi constatado que haviam locações de SSG em SLB, provavelmente após a separação das operações de negócio', N'01 - Imagens/02 - Depois/11000.jpeg', N'Comunicação com a área e compensação dos valores em outras aquisições da área', NULL, N'Após revisão, os valores foram levantados para a devida locação na operação correta conforme email de alinhamento', N'Controle de custo, verificação rotineira', 68511, 1, N'Thanks to reducing water , we could reduce 173KWH every years.', '2025-11-06T00:00:00.000', '2026-07-01T16:40:00.000', N'81044914', NULL, NULL);
INSERT INTO #PVC VALUES (11001, N'1010861', N'1010861', N'Filter Press Shifter Mod.', 1, N'No Replication/Sem replicação', N'Shifters of 306-FLP-003 were to tight to lock on plate grab bars.', N'Reliability of filter press plate shifter operation.', N'0', N'01 - Imagens/01 - Antes/11001.jpeg', N'Plate shifters for 306-FLP-003 were fabricated by contractor. When fab was complete shifter component fitment was to tight causing plates to be missed and jammed while washing filter press.', N'01 - Imagens/02 - Depois/11001.jpeg', N'Troubleshooting shifter locks to be to tight to lock on to the plate grab bars causing jam up in the wash process. Solution was to remove material from locking tabs on the shifter to open space for grab bars to lock in place. This process saved extended time washing and troubleshooting jamming issues.', N'https://apps.powerapps.com', N'Problem solved for this issue with fitment.', N'Shifters that come in with fitment issues can be made fit correctly.', 1000, 3, N'Thanks to the expansion of the floor area, we were able to reduce the risk of injury.', '2026-06-30T00:00:00.000', '2026-07-01T17:27:19.000', N'1010861', NULL, NULL);
INSERT INTO #PVC VALUES (11002, N'539450', N'539450', N'SUPORTE FIXAÇÃO DO CABO DE ANCORAGEM DA BÁSCULA ', 2, N'Open Pit/Poço aberto', N'Foi identificado que o cabo de ancoragem encontrava-se sem fixação, permanecendo solto nos equipamentos durante a liberação para operação. Observou-se que o equipamento operava nessa condição.', N'GARANTINDO MAIOR SEGURANÇA OPERACIONAL AO EQUIPAMENTO E ÀS PESSOAS. A AÇÃO TAMBÉM CONTRIBUI PARA A REDUÇÃO DE CUSTOS, PREVENINDO FALHAS, DESGASTE PREMATURO E AVARIAS NO CABO.', N'10279', N'01 - Imagens/01 - Antes/11002.jpeg', N'FOI IDENTIFICADO QUE O CABO DE ANCORAGEM ESTAVA SEM FIXAÇÃO, PERMANECENDO SOLTO NOS EQUIPAMENTOS DURANTE A LIBERAÇÃO PARA OPERAÇÃO. VERIFICOU-SE QUE O EQUIPAMENTO OPERAVA NESSAS CONDIÇÕES, RESULTANDO NA DANIFICAÇÃO DO CABO DE ANCORAGEM DA BÁSCULA. ', N'01 - Imagens/02 - Depois/11002.jpeg', N'FOI INSTALADO O SUPORTE DE ANCORAGEM DO CABO DA BÁSCULA, GARANTINDO A CORRETA FIXAÇÃO E O POSICIONAMENTO DO CABO DE AÇO DURANTE A OPERAÇÃO. ANTES DA LIBERAÇÃO DO EQUIPAMENTO, FOI CONFIRMADA A FIXAÇÃO ADEQUADA DO CABO AO SUPORTE, ASSEGURANDO MAIOR SEGURANÇA OPERACIONAL, REDUZINDO O RISCO DE FALHAS E AUMENTANDO A CONFIABILIDADE DO SISTEMA. A MELHORIA TAMBÉM CONTRIBUI PARA A REDUÇÃO DOS CUSTOS DE MANUTENÇÃO, EVITANDO DESGASTES E AVARIAS PREMATURAS NO CABO E EM SEUS COMPONENTES.', NULL, N'GARANTIR 100% DA FIXAÇÃO SEGURA DO CABO DA BÁSCULA POR MEIO DA INSTALAÇÃO DO SUPORTE DE ANCORAGEM, ELIMINANDO O RISCO DE DESPRENDIMENTO E AUMENTANDO A CONFIABILIDADE E A SEGURANÇA OPERACIONAL.', N' A INSTALAÇÃO DO SUPORTE DE ANCORAGEM GARANTE A FIXAÇÃO CORRETA DO CABO DA BÁSCULA, REDUZINDO O RISCO DE DESPRENDIMENTO E FALHAS DURANTE A OPERAÇÃO.  A PADRONIZAÇÃO DO SISTEMA DE ANCORAGEM AUMENTA A SEGURANÇA DOS OPERADORES E A CONFIABILIDADE DO EQUIPAMENTO.  AÇÕES PREVENTIVAS E MELHORIAS SIMPLES CONTRIBUEM PARA A REDUÇÃO DE CUSTOS COM MANUTENÇÃO, EVITANDO DESGASTE PREMATURO E PARADAS NÃO PROGRAMADAS. A VERIFICAÇÃO DA FIXAÇÃO DO CABO DEVE FAZER PARTE DA INSPEÇÃO ANTES DA LIBERAÇÃO DO EQUIPAMENTO PARA OPERAÇÃO.', 0, NULL, N'Thanks to the scaling up of the piping, the time required for liquid replacement was cut in half.', '2026-07-01T00:00:00.000', '2026-07-02T08:03:47.000', N'539450', NULL, NULL);
INSERT INTO #PVC VALUES (11003, N'553135', N'81047177', N'FERRAMENTA DE REMOÇÃO E INSTALAÇÃO - D6', 2, N'Others/Outros', N'ANTES A REMOÇÃO E INSTALAÇÃO DO EIXO DA TRANSMISSÃO DE D6 ERA FEITA DE FORMA MANUAL E ERGONOMICAMENTE ERRADA. USAVA-SE MARRETAS, SOLDA ... DEIXANDO O EMPREGADO NA LINHA DE FOGO, EXPOSTO AO PERIGO. ', N'TORNAR A ATIVIDADE SEGURA ATÉ 30 DE JUNHO', N'10139', N'01 - Imagens/01 - Antes/11003.jpeg', N'ANTES A REMOÇÃO E INSTALAÇÃO DO EIXO DA TRANSMISSÃO DE D6 ERA FEITA DE FORMA MANUAL E ERGONOMICAMENTE ERRADA. USAVA-SE MARRETAS, SOLDA ... DEIXANDO O EMPREGADO NA LINHA DE FOGO, EXPOSTO AO PERIGO. ', N'01 - Imagens/02 - Depois/11003.jpeg', N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', NULL, N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', N'A VIDA SEMPRE EM PRIMEIRO LUGAR ', 0, NULL, N' leading to optimized product quality and overall quality improvement.', '2026-06-25T00:00:00.000', '2026-07-02T09:29:29.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11004, N'1008574', N'1008574', N'improved CCD wash control', 1, N'Refining/Refino', N'when using water to supplement wash soltiuon for the CCD''s the flow meter was very erratic and displaying +/- 20 m3. ', N'reduce variability in set point ', N'0', N'01 - Imagens/01 - Antes/11004.jpeg', N'water flow was very erratic resulting in inaccurate CCD wash setpoint. This can result in over or under washing the CCD solids causing Ni lose or production downtime ', N'01 - Imagens/02 - Depois/11004.jpeg', N'PPTS would control from valve next to flow meter which caused a lot of turbulence. That valve has been green locked open and tagged to notify PPTs to use the valve further downstream  ', NULL, N'yes', N'field walk issues ', 1000, 3, N'Centralização das principais informações da Gerência Geral em um único portal, facilitando o acesso, a comunicação e a integração entre as equipes', '2026-07-01T00:00:00.000', '2026-07-02T09:58:26.000', N'1008574', NULL, NULL);
INSERT INTO #PVC VALUES (11005, N'81014495', N'81014495', N'BI Homologação de Fornecedores (CH_Master)', 1, N'Others/Outros', N'Com a migração do sistema de gerenciamento de materiais do Klassmatt para o CH_Master, o site deixou de contar com uma base única para o acompanhamento dos processos de homologação de materiais. A base anteriormente utilizada estava integrada aos dados do sistema descontinuado, tornando-se indisponível após a transição, o que impactou a rastreabilidade e a gestão centralizada dessas homologações.', N'Criar uma ferramenta única para acompanhamento dos processos de homologação de materiais no site de Sossego', N'10081', N'01 - Imagens/01 - Antes/11005.jpeg', N'A substituição do Klassmatt pelo CH_Master resultou na perda da base única de acompanhamento dos processos de homologação de materiais no site, uma vez que a solução anterior era dependente dos dados do sistema descontinuado. Como consequência, houve uma redução na visibilidade e centralização das informações relacionadas às homologações.', N'01 - Imagens/02 - Depois/11005.jpeg', N'Criei um relatório único em Power BI para acompanhamento dos processos de homologação de materiais do site de Sossego, utilizando os dados do CH_Master como fonte oficial. A solução proporcionará centralização das informações, maior rastreabilidade, visibilidade em tempo real dos processos, redução de controles manuais, melhoria na qualidade dos dados e suporte à tomada de decisão baseada em indicadores confiáveis.', NULL, N'Sim, o problema foi resolvido.', N'Sempre prezar por um sistema de gerenciamento visual e prático que auxilie nas tomadas de decisão', 0, NULL, N'Redução a zero do perigo de escorregões  na rampa através da adequação com material antiderrapante.', '2026-07-01T00:00:00.000', '2026-07-02T10:53:56.000', N'81014495', NULL, NULL);
INSERT INTO #PVC VALUES (11006, N'81030963', N'81044230', N'Gestão e Governança de Solicitações de Estoque', 1, N'Others/Outros', N'Este Kaizen transformou um processo manual, descentralizado e com baixa visibilidade em uma solução digital integrada e governada. Antes, as solicitações de estoque eram controladas por e-mails e planilhas, gerando retrabalho, dificuldades de acompanhamento, duplicidade de demandas e falta de rastreabilidade.', N'Eliminar controles Manuais ', N'10079', N'01 - Imagens/01 - Antes/11006.jpeg', N'o processo de solicitação de materiais de estoque era realizado por meio de e-mails, planilhas e controles individuais. As informações ficavam dispersas em diferentes fontes, dificultando o acompanhamento das demandas e a visualização do status das solicitações.
INSERT INTO #PVC VALUES (11007, N'81014495', N'81014495', N'Ferramenta de Avaliação de Maturidade  de Processos de Homologação Sossego', 1, N'Others/Outros', N'Sem avaliação de maturidade, a operação perde controle sobre a qualidade, rastreabilidade e evolução dos processos técnicos, aumentando o risco de decisões subjetivas, atrasos, falhas de compliance e exposição operacional. ', N'Estabelecer o acompanhamento mensal da maturidade dos processos ativos de desenvolvimento técnico (SAT, PT, IN e Desomologação, em escala de 0 a 100 pontos, com base em seis dimensões críticas.', N'10081', N'01 - Imagens/01 - Antes/11007.jpeg', N'Sem avaliação de maturidade, a operação perde controle sobre a qualidade, rastreabilidade e evolução dos processos técnicos, aumentando o risco de decisões subjetivas, atrasos, falhas de compliance e exposição operacional. O IMD funciona como uma régua objetiva para transformar processos dispersos em uma carteira governada, mensurável e passível de melhoria contínua.', N'01 - Imagens/02 - Depois/11007.jpeg', N'A ferramenta de avaliação de maturidade dos processos (IMD) é um modelo de acompanhamento mensal utilizado para medir o nível de organização, controle e aderência dos processos ativos de desenvolvimento técnico, como SAT, PT, IN e Desomologação. Ela permite avaliar, de forma padronizada e objetiva, a maturidade dos processos técnicos ativos, garantindo maior controle, rastreabilidade e governança. ', NULL, N'A ferramenta IMD atende essa meta ao transformar processos dispersos em uma carteira mensurável, estruturada por dimensões críticas como SSMA/Compliance, Planejamento, Execução, Encerramento, Governança e Formalização. ', N'A principal lição aprendida foi que a maturidade dos processos só pode ser gerenciada quando existe critério padronizado, evidência rastreável e rotina de acompanhamento. A criação do IMD mostrou que uma ferramenta simples, objetiva e integrada ao BI permite reduzir subjetividade, dar visibilidade à liderança, identificar gargalos e transformar avaliações em planos de ação concretos.', 0, NULL, N'Great communication and problem solving by my team  ', '2026-06-29T00:00:00.000', '2026-07-02T11:11:15.000', N'81014495', NULL, NULL);
INSERT INTO #PVC VALUES (11008, N'81014495', N'81014495', N'Ferramenta de avaliação de Criticidade de Sobressalentes MRO Sossego', 1, N'Others/Outros', N'A operação possuía dificuldade em classificar sobressalentes de forma padronizada, principalmente quando a análise considerava apenas o impacto operacional do item no ativo. Isso podia ', N'Criar uma metodologia objetiva para classificar os sobressalentes em GOP, Crítico ou Normal, considerando não apenas a função do item e a criticidade do ativo, mas também fatores de risco de suprimento, como lead time de aquisição e custo do material.', N'10081', N'01 - Imagens/01 - Antes/11008.jpeg', N'A operação possuía dificuldade em classificar sobressalentes de forma padronizada, principalmente quando a análise considerava apenas o impacto operacional do item no ativo. Isso podia gerar classificações subjetivas, excesso ou falta de estoque, baixa rastreabilidade na decisão e risco de tratar itens de alto impacto logístico ou financeiro como materiais comuns.', N'01 - Imagens/02 - Depois/11008.jpeg', N'A ferramenta de avaliação de criticidade de sobressalentes evoluiu a classificação dos materiais ao combinar impacto operacional com risco de suprimento. A inclusão dos fatores lead time e custo tornou a análise mais robusta, permitindo identificar itens que exigem maior proteção de estoque, contratos, homologação ou plano de contingência. ', NULL, N'A ferramenta atende à meta ao estruturar a avaliação em duas etapas: primeiro, identifica a criticidade operacional do sobressalente com base no ativo e na função do item; depois, aplica uma matriz complementar de risco de suprimento, cruzando lead time e custo para validar ou ajustar a classificação final.', N'A criticidade não deve ser avaliada apenas pelo impacto operacional; Custo elevado exige equilíbrio entre segurança de estoque e capital empatado;   Lead time longo aumenta a exposição operacional.', 0, NULL, N'Eliminação do risco de obstrução da linha de alimentação.
INSERT INTO #PVC VALUES (11009, N'503339', N'503339', N'Habilitar animação do Extrator EX-2009-05', 1, N'Others/Outros', N'Indisponibilidade do Extrator de sucatas sobre o Transportador TR-2009-01', N'Inserido na tela principal da Estocagem Secundária um Pop-up que vai abrir o detalhamento do extrator mostrando sua condição', N'10151', N'01 - Imagens/01 - Antes/11009.jpeg', N'Habilitar animação do Extrator EX-2009-05 sobre o transportador TR-2009-01.
INSERT INTO #PVC VALUES (11010, N'81012099', N'473599', N'Implantação de quadro de gestão documental da área', 3, N'Others/Outros', N'Foi identificada dificuldade na localização e controle dos documentos utilizados diariamente nas atividades operacionais, devido à ausência de um sistema visual padronizado para armazenamento e consulta.', N'Disponibilizar os documentos da área de forma organizada, padronizada e de fácil acesso por meio da implantação de um quadro de gestão documental, garantindo maior agilidade nas consultas e apoio às atividades operacionais.', N'10245', N'01 - Imagens/01 - Antes/11010.jpeg', N'A ausência de um local adequado para armazenamento de documentos tem gerado reimpressões recorrentes, resultando em aumento de custos, desperdício de recursos e dificuldades no controle e organização documental da área.', N'01 - Imagens/02 - Depois/11010.jpeg', N'Com a implantação do quadro, houve uma melhoria na organização dos documentos, reduzindo o extravio de papéis e eliminando a necessidade de reimpressões, o que contribuiu para a diminuição do consumo desnecessário de papel.
INSERT INTO #PVC VALUES (11011, N'81032895', N'81032895', N'Traffic Plan Road Sign', 2, N'Open Pit/Poço aberto', N'No road sign letting motorists know that this road is a one way street.  There is a sign on one side of the road letting drivers know but no sign letting drivers know do not enter. ', N'To align more with traffic plan. ', N'10101', N'01 - Imagens/01 - Antes/11011.jpeg', N'No signs letting vehicles know to "DO NOT ENTER". ', N'01 - Imagens/02 - Depois/11011.jpeg', N'DO NOT ENTER sign to align with traffic plan and to let motorist know not to enter. ', NULL, N'Yes, added signs to show the traffic plan from the parking lot. ', N'To align better with traffic plan. ', 0, NULL, N'eliminação do risco de queda de pessoas', '2026-07-01T00:00:00.000', '2026-07-02T14:25:19.000', N'81032895', NULL, NULL);
INSERT INTO #PVC VALUES (11012, N'81043245', N'81043245', N'Padronização da gestão visual com instalação de placas do passo a passo operacional dos Filtros 2551-FL-01 e 2551-FL-02', 1, N'Others/Outros', N'As instruções do passo a passo de operação dos filtros 2551-FL-01 e 2551-FL-02 eram disponibilizadas por meio de folhas impressas e plastificadas, com tamanho reduzido, menor visibilidade e suscetíveis ao desgaste, dificultando a leitura, a limpeza e a consulta durante as atividades operacionais.', N'Maior visibilidade e legibilidade das instruções operacionais', N'10054', N'01 - Imagens/01 - Antes/11012.jpeg', N'As instruções do passo a passo de operação dos filtros 2551-FL-01 e 2551-FL-02 eram disponibilizadas por meio de folhas impressas e plastificadas, com tamanho reduzido, menor visibilidade e suscetíveis ao desgaste, dificultando a leitura, a limpeza e a consulta durante as atividades operacionais.', N'01 - Imagens/02 - Depois/11012.jpeg', N'Foram confeccionadas e instaladas placas de sinalização em tamanho ampliado para os filtros 2551-FL-01 e 2551-FL-02, contendo o passo a passo da operação e a posição das válvulas em cada etapa do processo. A melhoria substituiu as folhas plastificadas por um material mais resistente, padronizado e de melhor visualização.
INSERT INTO #PVC VALUES (11013, N'87000312', N'87000326', N'To reduce washing water for gas sampler of the No2RT', 1, N'Refining/Refino', N' A constant flow of wash water was maintained for the 2RT gas sampler; however, this water would evaporate, be recovered at the AP, and subsequently be routed to the wastewater treatment system.', N'To reduce waste acid from 2AP.', N'0', N'01 - Imagens/01 - Antes/11013.jpeg', N'A constant flow of wash water was maintained for the 2RT gas sampler; however, this water would evaporate, be recovered at the AP, and subsequently be routed to the wastewater treatment system.', N'01 - Imagens/02 - Depois/11013.jpeg', N'Its installation reduced the volume of wastewater requiring treatment, leading to energy and resource savings.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Tracker has improved on accountability, visibility, and follow-through on key initiatives.', '2026-07-01T00:00:00.000', '2026-07-03T07:14:56.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11014, N'87000312', N'87000377', N'Extend intermediate 7th floor of No2RT', 2, N'Refining/Refino', N'The intermediate 7F floor area was cramped, creating a risk of dropping tools or other items while working.', N'To reduce injury risk.', N'0', N'01 - Imagens/01 - Antes/11014.jpeg', N'The intermediate 7F floor area was cramped, creating a risk of dropping tools or other items while working.', N'01 - Imagens/02 - Depois/11014.jpeg', N'The intermediate 7th-floor area was expanded, reducing the risk of falling parts.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', '2026-07-01T00:00:00.000', '2026-07-03T07:23:41.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11015, N'87000312', N'87000319', N'Installation piping for dilution water at the acid leakage pit in Acid shopping area.', 1, N'Refining/Refino', N'The water supply piping for the acid leakage pit was narrow, so replacing the liquid took a long time.', N'To increase water supply at the leak acid pit there. ', N'0', N'01 - Imagens/01 - Antes/11015.jpeg', N'The water supply piping for the acid leakage pit was narrow, so replacing the liquid took a long time.', N'01 - Imagens/02 - Depois/11015.jpeg', N'Increasing the diameter of the water supply piping reduced the time required to replace the liquid in the pit.', NULL, N'Yes, we could achieve the target as we thought.
INSERT INTO #PVC VALUES (11016, N'87000312', N'87000460', N'Movie timer switch for BQ tumbling machine', 1, N'Refining/Refino', N'The switch on the BQ tumbling machine is located immediately next to the timer dial used to set the rotation speed; consequently, there is a risk of accidentally bumping the dial and altering the timer setting when operating the switch, potentially leading to an incorrect powdering rate measurement.', N'Prevention of timer value fluctuations caused by switch movement in the BQ tumbling machine.', N'0', N'01 - Imagens/01 - Antes/11016.jpeg', N'The switch on the BQ tumbling machine is located next to the timer dial; consequently, there is a risk of accidentally bumping the dial and altering the timer setting.', N'01 - Imagens/02 - Depois/11016.jpeg', N'The position of the timer dial was changed. This allowed the rotational speed to be maintained within the appropriate range.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Redução da emissão de particulados e radiação.', '2026-07-02T00:00:00.000', '2026-07-03T07:42:05.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11017, N'81048240', N'81048240', N'Portal Integrado da Gerência Geral de Finanças Empresariais de Salobo', 1, N'Others/Outros', N'As informações da Gerência Geral de Finanças Empresariais encontravam-se dispersas em diferentes sites, e-mails e pastas, dificultando o acesso rápido ao organograma, aos portais das gerências, às informações de VPS e ao conhecimento das equipes. Essa descentralização gerava perda de tempo na busca por informações e menor integração entre as áreas.', N'Promover a gestão visual e a transparência da Gerência Geral de Finanças Empresariais, consolidando informações estratégicas da área em um portal de fácil acesso alinhado aos princípios do VPS', N'10367', N'01 - Imagens/01 - Antes/11017.jpeg', N'As informações da Gerência Geral de Finanças Empresariais estavam distribuídas em diferentes sites, pastas, e-mails e equipes, sem um ponto único de consulta. A localização de informações como organograma, responsáveis, portais das gerências, representantes de VPS e materiais institucionais dependia do conhecimento individual das pessoas ou de consultas frequentes a colegas. Isso gerava maior tempo de busca, dificuldade de integração entre as áreas e menor visibilidade da estrutura organizacional.', N'01 - Imagens/02 - Depois/11017.jpeg', N'Solução Implementada
INSERT INTO #PVC VALUES (11018, N'81012700', N'543301', N'Rampa de saída do refeitório', 2, N'Others/Outros', N'Identificamos risco de acidente de trabalho na saída do refeitório do escritório de campo devido á falta de aderência no piso da rampa. A ausência de sinalização e de material antiderrapante compromete a segurança na circulação dos colaboradores ao sair do restaurante.', N'mitigar 100% a segurança dos colaboradores ao sair do refeitório, eliminar o risco de escorregamento  ou queda, tornando a saída do restaurante mais segura. ', N'10257', N'01 - Imagens/01 - Antes/11018.jpeg', N'Rampa com superfície lisa e sem aderência na saída do refeitório, gerando perigo imediato de quedas e escorregões para os colaboradores durante o fluxo de saída do restaurante.', N'01 - Imagens/02 - Depois/11018.jpeg', N'Instalação de fitas de alta aderência em toda a rampa de saída do refeitório. Garantindo a tração necessária para os colaboradores, eliminando o risco de escorregões e quedas, tornando o fluxo de saída100% seguro.', NULL, N'sim o problema foi totalmente resolvido com a instalação das fitas antiderrapante, garantindo assim atrito e aderência ao piso e eliminando o risco de escorregões na saída do refeitório.', N'Avaliar segurança. Rampas de acessos de colaboradores devem ter revestimento antiderrapante desde o projeto.', 0, NULL, N'Melhoria da gestão visual.
INSERT INTO #PVC VALUES (11019, N'81046430', N'81013286', N'Segurança Hídrica na Britagem Secundária I/II', 2, N'Others/Outros', N'A Britagem Secundária I/II dependia de abastecimento por caminhão-pipa para alimentação do reservatório de água potável, gerando risco de desabastecimento, exposição a cenário RAC-03, maior vulnerabilidade sanitária e custos operacionais com transporte, combustível e manutenção.', N'Eliminar a dependência de abastecimento por caminhão-pipa na Britagem Secundária I/II, garantindo alimentação contínua do reservatório de água potável pela rede mestra, com maior segurança sanitária, redução de riscos operacionais e melhoria da confiabilidade do abastecimento.', N'10017', N'01 - Imagens/01 - Antes/11019.jpeg', N'Antes do Kaizen, a Britagem Secundária I/II apresentava falta de água de forma recorrente, devido à dependência de abastecimento por caminhão-pipa. Essa condição comprometia atividades operacionais, rotinas de higiene, uso de banheiros, copas e processos de limpeza predial.', N'01 - Imagens/02 - Depois/11019.jpeg', N'Após o Kaizen, o reservatório passou a ser abastecido diretamente pela rede mestra de água potável, garantindo maior continuidade operacional, redução do risco de falta de água, eliminação da dependência de caminhão-pipa e melhoria nas condições de higiene, conforto e segurança sanitária.', NULL, N'A meta inicial do Kaizen era eliminar a dependência de abastecimento por caminhão-pipa, garantindo fornecimento contínuo, seguro e confiável de água potável para a Britagem Secundária I/II.
INSERT INTO #PVC VALUES (11020, N'609694', N'609694', N'Pinch point', 2, N'Underground/Subterrâneo', N'When adding self closing gates at 3410 sump 1 - we caused a severe pinch point issue- This was noticed by crew members completing the work', N'Remove pinch point', N'10260', N'01 - Imagens/01 - Antes/11020.jpeg', N'When adding self closing gates to   3410 level sump 1 - we caused a severe pinch point issue.
INSERT INTO #PVC VALUES (11021, N'515962', N'515962', N'Intertravamento entre os moinhos verticais e as bombas da CX 01 Flotação.', 1, N'No Replication/Sem replicação', N'Quando os Moinhos verticais paravam por falha, as bombas da CX 01 (2351-BP-01, 2351-BP-01R e 2351-BP-02) continuavam em operação e mantinham o fluxo de alimentação direcionado ao moinho parado. Esse comportamento gerava risco de obstrução na linha da tubulação e calha.', N'Eliminar condições de obstruções na alimentação dos moinhos.', N'10054', N'01 - Imagens/01 - Antes/11021.jpeg', N'Quando os Moinhos verticais paravam por falha, as bombas da CX 01 (2351-BP-01, 2351-BP-01R e 2351-BP-02) continuavam em operação e mantinham o fluxo de alimentação direcionado ao moinho parado. Esse comportamento gerava risco de obstrução na linha da tubulação e calha.', N'01 - Imagens/02 - Depois/11021.jpeg', N'Foi criado o intertravamento lógico, entre o moinho vertical e as bombas da caixa 01. Quando o moinho parar por falha, após um minuto as bombas que estiverem funcionando irão parar por intertravamento com o moinho que estiver alimentando, assim a 2351-BP-01 irá intertravar com o 2351-MO-01. Há 2351-BP-02 com o 2351-MO-02 e a 2351-BP-01R vai intertravar dependendo da válvula que estiver direcionada para o respectivo moinho selecionado para alimentação. ', NULL, N'Realizado testes e até o momento resultados positivos', N'Realizar melhorias com objetivo de melhorar segurança de pessoas e ativos.', 0, NULL, N'META ATINGIDA ', '2026-07-02T00:00:00.000', '2026-07-03T13:51:45.000', N'515962', NULL, NULL);
INSERT INTO #PVC VALUES (11022, N'510839', N'510839', N'Aprimoramento da Gestão de Vida Útil dos Cabos', 1, N'Others/Outros', N'O controle da vida útil dos cabos da frota 7495 HD/HR utilizava parâmetros limitados para projeção da tonelagem acumulada, reduzindo a assertividade na previsão das datas de troca e dificultando o planejamento antecipado das intervenções de manutenção.', N'Melhorar a precisão da previsão de troca dos cabos, possibilitando planejamento antecipado e maior confiabilidade das ações de manutenção.', N'10234', N'01 - Imagens/01 - Antes/11022.jpeg', N'O dashboard utilizava a movimentação estimada dos últimos 30 dias como principal parâmetro de projeção, reduzindo a precisão das previsões de troca e a previsibilidade do planejamento de manutenção.', N'01 - Imagens/02 - Depois/11022.jpeg', N'O dashboard passou a utilizar média dos últimos 15 dias e projeções de atingimento de 90% e 98% da vida útil, aumentando a precisão das previsões e a assertividade do planejamento de manutenção.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/dc2d6a76-b33a-444d-b65c-f465aceaa07f/ReportSection?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. A atualização do dashboard incorporou novos parâmetros de análise, incluindo média de movimentação dos últimos 15 dias, projeções de atingimento de 90% e 98% da vida útil e estimativas de troca. Com isso, as previsões passaram a refletir melhor a condição operacional dos equipamentos, aumentando a assertividade do planejamento de manutenção e reduzindo a dependência de análises complementares.', N'A utilização de múltiplos parâmetros operacionais torna as projeções de vida útil mais assertivas, aumentando a confiabilidade dos indicadores e a qualidade do planejamento de manutenção.', 0, NULL, N'Segurança', '2026-07-02T00:00:00.000', '2026-07-03T13:52:08.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11023, N'200500', N'608234', N'Filter Plant Concentrate Tank Covers', 2, N'Concentration/Concentração', N'#1 and #2 concentrate tanks at the filter plant were open to the workroom environment.   Splashing and misting would result in slurry drying and causing dusting conditions in the plant.   ', N'To improve the workroom environment by eliminating  the dusty conditions that exist in the plant.', N'10194', N'01 - Imagens/01 - Antes/11023.jpeg', N'The #1 and #2 Concentrate Tanks at the Filter Plant were open to the workroom environment, allowing slurry splashing and misting to escape the tanks during normal operation. As the airborne slurry dried, it generated dust throughout the area, creating housekeeping, exposure, and maintenance challenges. A key constraint was that the tops of the tanks were located below the floor grating, making it difficult to implement a conventional tank cover while still maintaining access and operability.', N'01 - Imagens/02 - Depois/11023.jpeg', N'To address the dust generation and housekeeping issues associated with the #1 and #2 Concentrate Tanks, tank covers were installed to contain slurry misting and splashing within the tanks and prevent material from escaping into the workroom environment. The project successfully enclosed the tanks despite the challenge of the tank openings being located below the floor grating. Following installation, a noticeable improvement in housekeeping and dust control was observed. Qualitative assessments were conducted using dust collection "coupons" placed near the #2 Tank, which showed no measurable dust accumulation when inspected. Then #1 Tank cover was completed, and the results demonstrate that the enclosure effectively mitigated dust releases while improving overall workplace conditions within the Filter Plant.', NULL, N'Removed the accumulation of dust that was previously created at the #1 and #2 concentrate tanks, which was positive for the workroom environment.', N'controlling dust generation at the source is significantly more effective than managing dust after it has entered the work environment', 0, NULL, N'Cabinet was returned to a functional state.', '2026-03-31T00:00:00.000', '2026-07-03T15:44:36.000', N'200500', NULL, NULL);
INSERT INTO #PVC VALUES (11024, N'81006571', N'81040190', N'PISO AO REDOR DA GRUA FIXA DO SAG', 2, N'Others/Outros', N'Antes ao redor da GRUA LE do SAG estava com ao redor dela danificada ', N'ELIMINAR RISCOS DE PESSOAS ', N'10362', N'01 - Imagens/01 - Antes/11024.jpeg', N'Durante as atividades de manutenção (TROCA DE REVESTIMENTO DO SAG), era necessária a montagem de andaime ao redor da grua devido ao espaçamento entre o piso e a base de fixação da mesma. Essa condição gerava risco de queda de pessoas, exposição a altura e demais perigos associados.', N'01 - Imagens/02 - Depois/11024.jpeg', N'Instalação de um piso fixo ao redor da grua, eliminando o vão e proporcionando uma superfície segura e nivelada para a execução das atividades de troca de revestimento
INSERT INTO #PVC VALUES (11025, N'200500', N'200219', N'Acid Plant Safety Shower Water On-Demand', 2, N'Refining/Refino', N'The Acid Plant’s safety shower system struggled to maintain American National Standards Institute (ANSI) compliant water temperature and supply, especially in winter due to cold incoming water, slow tank reheating, and outdated controls, creating risks of inadequate emergency response', N'Provide 45 minutes of continuous 20°C water to emergency showers, supporting multiple showers simultaneously.', N'10194', N'01 - Imagens/01 - Antes/11025.jpeg', N'The temperature of inlet water that would fill the 1000-gallon tank was at approximately 4°C. 
INSERT INTO #PVC VALUES (11026, N'200500', N'200535', N'Action Plan Tracker', 1, N'Others/Outros', N'Operations and Maintenance Superintendents work on projects continually throughout the year;  wanted a method of tracking the good work that is being completed, and being able to check in as a leadership team at the smelter on what projects are being worked on throughout the complex.', N'Monitor, manage, and drive completion of action items, milestones, deliverables, and savings targets through regular follow-up and accountability routines', N'10194', N'01 - Imagens/01 - Antes/11026.jpeg', N'Operations and Maintenance Superintendents work on projects continually throughout the year;  wanted a method of tracking the good work that is being completed, and being able to check in as a leadership team at the smelter on what projects are being worked on throughout the complex.   There was also no method to monitor, manage, and drive completion of action items, milestones, deliverables, and savings targets through regular follow-up and accountability routines.', N'01 - Imagens/02 - Depois/11026.jpeg', N'At the weekly leadership meeting of the smelter complex, the team reviews action items assigned to each superintendent, and a status update is reported on, discussions on whether assistance is required, discussion on whether a pivot is needed from the original action.', NULL, N'The initial goal was to have a sustainable method of accountability and reporting on the work being completed.  The action plan tracker is providing this to the smelter leadership team.', N'Increase execution discipline and sustain improvement efforts by implementing a tracking system of the work that was assigned and being completed.', 0, NULL, N'ausência de um transporte para movimentar as rodas dos caminhões.', '2026-02-05T00:00:00.000', '2026-07-03T16:43:28.000', N'200500', NULL, NULL);
INSERT INTO #PVC VALUES (11027, N'81007243', N'81048616', N'Suporte da transmissão TT-43', 3, N'Others/Outros', N'A transmissão do TT43 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte.', N'Redução de cenário de risco, ', N'10139', N'01 - Imagens/01 - Antes/11027.jpeg', N'A transmissão do TT43 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte."', N'01 - Imagens/02 - Depois/11027.jpeg', N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', NULL, N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', N'Condição de risco eliminada', 0, NULL, N'Ganho de aproximadamente 20 minutos na atividade por não precisar usar os equipamentos para atendimento a RAC01.', '2026-07-02T00:00:00.000', '2026-07-03T20:23:39.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11028, N'81007243', N'81048616', N'Suporte da transmissão MA52', 3, N'Others/Outros', N'A transmissão do MA52 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte', N'Redução de risco', N'10139', N'01 - Imagens/01 - Antes/11028.jpeg', N'A transmissão do MA52 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte', N'01 - Imagens/02 - Depois/11028.jpeg', N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', NULL, N'Sim', N'Acondicionamento adequado ', 0, NULL, N'Reaproveitamento de materiais da caldeiraria que iria para descarte. ', '2026-07-02T00:00:00.000', '2026-07-03T20:28:13.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11029, N'482294', N'483338', N'Tampa da abóboda', 2, N'No Replication/Sem replicação', N'Projeção de particulados e radiação de temperatura nos equipamentos periféricos.', N'Eliminar furos da abóboda desativados', N'10243', N'01 - Imagens/01 - Antes/11029.jpeg', N'Após desativação da lança de emergência de nitrogênio e lança adição de fios, os furos na abóboda do Forno panela para essa atividade ficaram disfuncionais e logo estavam contribuindo para emissão de particulados e radiação de temperatura nos equipamentos periféricos.', N'01 - Imagens/02 - Depois/11029.jpeg', N'Decidimos fabricar duas tampas refratarias. e sanar o problema de projeção de particulados e radiação.', NULL, N'Foi reduzido a emissão de particulados e radiação durante o processo no forno panela.', N'Não ignore pequenos problemas, sempre haja de acordo os valores da Vale.', 0, NULL, N'Melhor condição para instalação da bandeira. Ganho de tempo de aproximadamente 20 minutos para instalação ou remoção. ', '2026-06-28T00:00:00.000', '2026-07-03T22:14:10.000', N'482294', NULL, NULL);
INSERT INTO #PVC VALUES (11030, N'81007243', N'81021635', N'Confecção de mangueiras para drenar oleo do tandem', 3, N'Projects/Projetos', N'O processo de drenagem do óleo SAE 30 nas motoniveladoras modelo 24M apresentava baixa eficiência devido à incompatibilidade entre a capacidade dos carrinhos coletores (70 litros) e o volume total do reservatório (370 litros). Como resultado, a equipe precisava interromper a atividade cerca de cinco vezes para transportar o óleo até a bomba de transferência, realizar o esvaziamento do coletor e retornar ao equipamento. Essas movimentações adicionais aumentavam o tempo de execução da tarefa para aproximadamente 3 horas, impactando diretamente a produtividade, elevando o esforço operacional e ampliando a exposição dos trabalhadores a riscos ergonômicos.', N'Redução do tempo levado na atividade', N'10139', N'01 - Imagens/01 - Antes/11030.jpeg', N'O processo de drenagem do óleo SAE 30 nas motoniveladoras modelo 24M apresentava baixa eficiência devido à incompatibilidade entre a capacidade dos carrinhos coletores (70 litros) e o volume total do reservatório (370 litros). Como resultado, a equipe precisava interromper a atividade cerca de cinco vezes para transportar o óleo até a bomba de transferência, realizar o esvaziamento do coletor e retornar ao equipamento. Essas movimentações adicionais aumentavam o tempo de execução da tarefa para aproximadamente 3 horas, impactando diretamente a produtividade, elevando o esforço operacional e ampliando a exposição dos trabalhadores a riscos ergonômicos.', N'01 - Imagens/02 - Depois/11030.jpeg', N'Para melhorar a eficiência da atividade, foi confeccionada uma mangueira de 20 metros, conectada diretamente ao sistema de drenagem da motoniveladora 24M e à bomba da baia de lubrificação. Com essa solução, o óleo passou a ser drenado diretamente do equipamento para o sistema de armazenamento, eliminando a necessidade de utilizar os carrinhos coletores durante o processo.
INSERT INTO #PVC VALUES (11031, N'81043245', N'81043245', N'Padronização da gestão visual com instalação de placa de identificação das válvulas dos Filtros 2551-FL-01 e 2551-FL-02', 1, N'Others/Outros', N'A identificação das principais válvulas dos filtros dependia do conhecimento dos operadores ou da consulta em documentos, dificultando a localização rápida dos componentes, principalmente durante inspeções e intervenções operacionais.', N'Apoio ao treinamento de novos operadores. Facilidade na identificação e localização das válvulas', N'10054', N'01 - Imagens/01 - Antes/11031.jpeg', N'A identificação das principais válvulas dos filtros dependia do conhecimento dos operadores ou da consulta em documentos, dificultando a localização rápida dos componentes, principalmente durante inspeções e intervenções operacionais.', N'01 - Imagens/02 - Depois/11031.jpeg', N'Foi confeccionada e instalada uma placa de gestão visual contendo a identificação das principais válvulas dos filtros 2551-FL-01 e 2551-FL-02, com ilustração da localização de cada válvula no equipamento, sua nomenclatura, função e correspondência entre os dois filtros.', NULL, N'SIM. A melhoria facilita a identificação dos componentes, agiliza as atividades operacionais', N' identificação rápida e padronizada das válvulas', 0, NULL, N'Maior segurança, preservação do equipamento e redução de riscos.', '2026-07-03T00:00:00.000', '2026-07-04T02:05:14.000', N'81043245', NULL, NULL);
INSERT INTO #PVC VALUES (11032, N'202638', N'202638', N'Reduce vending machines', 3, N'Refining/Refino', N'Vending machines were not fully stocked and were taking up sace', N'cost reduction', N'0', N'01 - Imagens/01 - Antes/11032.jpeg', N'EW had a total of 6 Fastenal vending machines, some were used as asset lockers however none were full', N'01 - Imagens/02 - Depois/11032.jpeg', N'We consolidated all items and were able to reduce our vending machine totals from 6 to 3', NULL, N'Cost reduced as we are not paying for the machines, area freed up', N'5S', 1000, 3, N'Proteger o sensor de nível contra impactos e garantir a continuidade do processo produtivo.', '2026-07-03T00:00:00.000', '2026-07-04T10:07:35.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11033, N'498359', N'81047016', N'DISPOSITIVOP PARA COMPLETAR O OLEO LUBRIFICANTE', 2, N'Others/Outros', N'Dificuldade na execução em  completar de óleo do tanque do sistema de lubrificação do britador primário, ao virar o tambor de óleo não estando na gravidade correta com isso o óleo não chegava ao tanque, e com os riscos de escorregar na escada, tropeçar, esmagamento de membros.', N'REDUZIR RISCOS ERGONOMICOS', N'10362', N'01 - Imagens/01 - Antes/11033.jpeg', N'Dificuldade na execução em  completar de óleo do tanque do sistema de lubrificação do britador primário, ao virar o tambor de óleo não estando na gravidade correta com isso o óleo não chegava ao tanque, e com os riscos de escorregar na escada, tropeçar, esmagamento de membros.', N'01 - Imagens/02 - Depois/11033.jpeg', N'Foi realizada uma melhoria significativa no britador primário, com foco na eliminação de riscos operacionais e aumento da segurança dos trabalhadores. A intervenção contemplou a readequação do sistema, eliminando o risco de queda durante a execução da atividade, bem como o risco de contaminação do óleo, garantindo maior integridade do processo.
INSERT INTO #PVC VALUES (11034, N'498359', N'81047016', N'JANELA DE VISITA', 2, N'Others/Outros', N'DIFICULDADE NA REMOÇÃO DA PROTEÇÃO PARA PODER ACESSAR O SENSOR DE BAIXA VELOCIDADE', N'REDUZIR EXPOSIÇÃO DE ENERGIA ELETRICA', N'10362', N'01 - Imagens/01 - Antes/11034.jpeg', N'DIFICULDADE NA REMOÇÃO DA PROTEÇÃO PARA PODER ACESSAR O SENSOR DE BAIXA VELOCIDADE', N'01 - Imagens/02 - Depois/11034.jpeg', N'FOI FABRICADO UMA JANELA DE VISITA PARA ACESSAR O SENSOR DE BAIXA VELOCIDADE, COM GANHOS EM ERGONOMIA, PRODUTIDADE, TEMPO, FACILIDADE NA HORA DA MANUTENÇÃO DO SENSOR.', NULL, N'META ATINGIDA ', N'MELHORAR O AMBIENTE DE TRABALHO', 0, NULL, N'Garantia da segurança e melhor otimização do tempo para realização da atividade. ', '2026-07-03T00:00:00.000', '2026-07-04T17:09:48.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11035, N'81006689', N'81045062', N'Deposito de água de ar condicionado', 3, N'Others/Outros', N'Deposito de água de ar condicionado sem escape para água, ocasionando vazamento e risco de escorregão.', N'eliminar o derramamento de água na área', N'10233', N'01 - Imagens/01 - Antes/11035.jpeg', N'Deposito de água de ar condicionado sem escape para água, ocasionando vazamento e risco de escorregão.', N'01 - Imagens/02 - Depois/11035.jpeg', N'Foi instalado torneira para vasão de água acumulada.', NULL, N'sim, Foi instalado torneira para vasão de água acumulada.', N'sempre observar área de trabalho.', 0, NULL, N'The ability to internal inspect a tank that otherwise would have not been inspected. Overall reducing the risk to workers in the area', '2026-07-03T00:00:00.000', '2026-07-04T19:15:56.000', N'81006689', NULL, NULL);
INSERT INTO #PVC VALUES (11036, N'609342', N'609342', N'3rd Floor Cabinet Repair', 3, N'Refining/Refino', N'The cabinet on 3rd floor was rusting away, and the doors were becoming non-functional.', N'To repair the functionality of the 3rd floor cabinet ', N'10114', N'01 - Imagens/01 - Antes/11036.jpeg', N'The cabinet/workbench was becoming non-functional due to wear and tear. Doors were rusting out and overall appearance was unsatisfactory. ', N'01 - Imagens/02 - Depois/11036.jpeg', N'Doors were fabricated and replaced by Barry and work was cleaned and 5s was brought back to 5s state.', NULL, N'Yes, the cabinet was repaired in house and functionality was returned.  ', N'To repair something, instead of having to buy new', 1000, 3, N'A iniciativa gerou maior governança sobre a programação de férias, reduziu a dependência de controles manuais, melhorou a visibilidade gerencial e possibilitou a identificação preventiva de conflitos de agenda. O app também automatizou comunicações ao gestor e lembretes de aniversário e tempo de empresa. A solução foi replicada para outras equipes, ampliando o alcance para aproximadamente 210 pessoas.', '2026-07-02T00:00:00.000', '2026-07-04T22:56:11.000', N'609342', NULL, NULL);
INSERT INTO #PVC VALUES (11037, N'550548', N'550548', N'Energia para Testar, Agilidade para Manter', 1, N'No Replication/Sem replicação', N'A falta de alimentação dos sensores indutivos e capacitivos durante a manutenção da aranha impedia a realização de testes funcionais antes da remontagem. Caso fosse identificada uma falha após a instalação, era necessária uma nova retirada da aranha, atividade com duração aproximada de 5 horas, gerando retrabalho, aumento do tempo de manutenção e maior indisponibilidade do britador.', N'Permitir a realização de testes funcionais dos sensores indutivos e capacitivos antes da remontagem da aranha, eliminando a necessidade de retrabalho decorrente da identificação tardia de falhas, reduzindo em até 5 horas o tempo de manutenção por ocorrência e aumentando a confiabilidade e a disponibilidade do britador.', N'10245', N'01 - Imagens/01 - Antes/11037.jpeg', N'Sem alimentação elétrica, os sensores da aranha não podiam ser testados durante a manutenção. Falhas eram identificadas somente após a montagem, exigindo nova retirada da aranha e cerca de 5 horas de retrabalho.', N'01 - Imagens/02 - Depois/11037.jpeg', N'Foi desenvolvido um dispositivo portátil para testar sensores no local da manutenção, permitindo validar seu funcionamento antes da montagem, evitando retrabalho e reduzindo até 5 horas por ocorrência.', NULL, N'A meta foi atingida com o desenvolvimento do dispositivo portátil, permitindo testar os sensores antes da remontagem da aranha, eliminando retrabalhos e reduzindo em até 5 horas o tempo de manutenção por ocorrência.', N'A validação dos sensores antes da remontagem aumenta a confiabilidade da manutenção, evita retrabalhos, reduz o tempo de intervenção e evidencia a importância de desenvolver ferramentas simples para solucionar limitações operacionais.', 0, NULL, N'The elimination of the dribble box removed a repetitive manual handling task.', '2026-07-04T00:00:00.000', '2026-07-05T02:52:24.000', N'550548', NULL, NULL);
INSERT INTO #PVC VALUES (11038, N'81033365', N'81048606', N'Suporte do extintor de icendio', 1, N'Others/Outros', N'ausência de local adequado', N'processo de melhorias', N'10139', N'01 - Imagens/01 - Antes/11038.jpeg', N'O extintor estava guardado incorretamente no chão e exposto ao tempo (sol e chuva), o que pode causar corrosão e falha no funcionamento.', N'01 - Imagens/02 - Depois/11038.jpeg', N'O extintor foi retirado do chão e instalado em um suporte adequado para garantir sua conservação e funcionamento seguro.', NULL, N'AUSENCIA DE SUPORTE E DEPOIS FOI FABRICADO SUPORTE.', N'MELHORIA CONTINUA', 0, NULL, N'Os condutores estão respeitando o distanciamento seguro.', '2026-06-29T00:00:00.000', '2026-07-05T09:31:52.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11039, N'81033365', N'81048572', N'Carrinho de transportar roda', 2, N'Others/Outros', N'Ausência de suporte para transportar roda.', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11039.jpeg', N'Identificado que a Movimentação manual de rodas durante o transporte interno, gerando risco ergonômico e potencial de acidentes por queda de material ou prensagem de membros.', N'01 - Imagens/02 - Depois/11039.jpeg', N'Realizado fabricação e implementação de carrinho ergonômico dedicado para o transporte seguro de rodas, eliminando o manuseio manual e mitigando o risco de acidentes.', NULL, N'ausência de um transporte para movimentar as rodas dos caminhões.', N'melhoria continua', 0, NULL, N'melhorando a ergonomia e aumentando a segurança dos empregados.', '2026-07-04T00:00:00.000', '2026-07-05T10:05:10.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11040, N'983254', N'983254', N'Segurança na dosagem de CAL', 2, N'Others/Outros', N'Empregados para realizar o abastecimento do tanque de cal virgem 2251SL04 com exposto RAC 01.', N'Redução de riscos', N'10054', N'01 - Imagens/01 - Antes/11040.jpeg', N'Empregados para realizar o abastecimento do tanque de cal virgem 2251SL04 ficava exposta aos riscos de RAC 01.', N'01 - Imagens/02 - Depois/11040.jpeg', N'Prolongamento do guarda-corpos da plataforma em 8000 mm eliminado reduzindo o risco de queda do colabora e aplicação da RAC1 para atividade. ', NULL, N'Meta superada com a redução do risco na atividade.', N'Redução de riscos', 0, NULL, N'Eliminação de perdas produtivas associadas à atividade.
INSERT INTO #PVC VALUES (11041, N'983254', N'983254', N'Estacionamento Britagem', 2, N'Others/Outros', N'Risco de incidente com veículos por movimentação involuntária por ausência de trava rodas no local.  ', N'Redução do risco de batida contra de veículo. ', N'10054', N'01 - Imagens/01 - Antes/11041.jpeg', N'Estacionamento da britagem próximo ao CCB sem trava rodas. Risco de incidente com veículos por movimentação involuntária por ausência de trava rodas no local.  ', N'01 - Imagens/02 - Depois/11041.jpeg', N'Fabricação interna de trava, com uso de restos de materiais da caldeiraria da equipe de manutenção da operação de usina.', NULL, N'Riscos, de movimentação involuntária do veículo no estacionamento eliminado. ', N'Redução de riscos e Reaproveitamento de materiais', 0, NULL, N'A melhoria garantiu continuidade operacional na emissão de notificações contratuais, reduziu esforço manual, aumentou a agilidade do processo e fortaleceu a rastreabilidade das comunicações. O documento gerado automaticamente contempla informações essenciais da notificação, como número, data de emissão, prazo de resposta, fornecedor, contrato, assunto, descrição da ocorrência, cláusulas aplicáveis e campo para ciência/assinatura.', '2026-06-16T00:00:00.000', '2026-07-05T19:50:28.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (11042, N'983254', N'983254', N'Bandeira', 1, N'Others/Outros', N'Falta de mastro para instalação de bandeira no período dos jogos da copa.', N'Instalação de mastro para bandeira ', N'10054', N'01 - Imagens/01 - Antes/11042.jpeg', N'Ausência local seguro para instalação de bandeira do Brasil durante os jogos da copa.', N'01 - Imagens/02 - Depois/11042.jpeg', N'Instalação de um mastro no ponta da lança para posicionamento da bandeira durante os jogos da copa.', NULL, N'Meta alcançada. Encontrado local estratégico, com boa visibilidade e acesso seguro. ', N'Engajamento das equipes.', 0, NULL, N'mantendo o equipamento por mais tempo disponívelpara operação', '2026-06-04T00:00:00.000', '2026-07-05T19:59:31.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (11043, N'81047450', N'525730', N'SUPORTE PARA CAPACETE', 2, N'Others/Outros', N'OS CAPACETES NAO TINHA UM LOCAL ADEQUADO PARA ARMAZENAMENTO AO ENTRA NA SALA DE EPIS,ISSO FAZ COM OS COLABORADORES DEIXAVA OS CAPACETES NO CHAO CAUSANDO ARRANHÕES,UMIDADE,COM RESULTADO A VIDA UTIL DO CAPACETE DIMINUI,AUMENTA O CUSTO DE REPOSIÇÃO E O RISCO DE O EPI NÃO OFERECER PROTEÇÃO NECESSÁRIA EM CASO DE ACIDENTE', N'REDUZIR EM 100 % OS CASOS DE CAPACETES PO DANIFICADOS POR ARMAZENAMENTO INADEQUADO .', N'10036', N'01 - Imagens/01 - Antes/11043.jpeg', N'OS CAPACETES NAO TINHA UM LOCAL ADEQUADO PARA ARMAZENAMENTO AO ENTRA NA SALA DE EPIS,ISSO FAZ COM OS COLABORADORES DEIXAVA OS CAPACETES NO CHAO CAUSANDO ARRANHÕES,UMIDADE,COM RESULTADO A VIDA UTIL DO CAPACETE DIMINUI,AUMENTA O CUSTO DE REPOSIÇÃO E O RISCO DE O EPI NÃO OFERECER PROTEÇÃO NECESSÁRIA EM CASO DE ACIDENTE.', N'01 - Imagens/02 - Depois/11043.jpeg', N'APÓS A FABRICAÇÃO DO SUPORTE,O CAPACETE FICAR PROTEGIDO,SEM CONTATO COM O CHÃO /UMIDADE.A VIDA ÚTIL AUMENTA EM ATÉ 40%,COM MENOS REPOSIÇÃO ,O INVESTIMENTO NO SUPORTE SE PAGA COM A DURABILIDADE DO CAPACETE ', NULL, N'SIM', N'SÓ ENTREGAR NÃO RESOLVE,PRECISA INSTALAR E TREINAR ,HÁBITO SE CRIA COM EXEMPLO E FISCALIZAÇÃO', 0, NULL, N'Como resultado, houve aumento da produtividade, redução de erros, aceleração na execução das atividades e fortalecimento da cultura de melhoria contínua por meio da simplificação dos processos digitais.', '2026-07-04T00:00:00.000', '2026-07-05T23:19:42.000', N'81047450', NULL, NULL);
INSERT INTO #PVC VALUES (11044, N'81037838', N'81047011', N'"Instalação de Grade de Proteção na Condensadora - Sala dos Operadores"', 2, N'Others/Outros', N'A condensadora do ar-condicionado encontrava-se exposta, sem proteção, com risco de impactos e danos que poderiam causar a quebra do equipamento, gerando vulnerabilidade a impactos e comprometendo a segurança.', N'Proteger a unidade condensadora do ar-condicionado da sala dos operadores contra impactos e danos, garantindo a segurança, a integridade do equipamento e a continuidade do funcionamento.', N'10054', N'01 - Imagens/01 - Antes/11044.jpeg', N'A condensadora do ar-condicionado encontrava-se exposta, sem proteção, com risco de impactos e danos que poderiam causar a quebra do equipamento, gerando vulnerabilidade a impactos e comprometendo a segurança.', N'01 - Imagens/02 - Depois/11044.jpeg', N'Foi instalada grade de proteção metálica, pintada na cor amarela, ao redor da unidade condensadora. A proteção garante a integridade do equipamento contra impactos, preserva a tubulação e não compromete a ventilação. Equipamento seguro e sinalizado.', NULL, N'SIM. O problema foi resolvido. A unidade condensadora que estava exposta e sem proteção foi isolada com a instalação da grade de proteção metálica. Com isso, eliminamos o risco de impacto e danos ao equipamento, garantindo a segurança e a continuidade do funcionamento do ar-condicionado.', N'A proteção de equipamentos expostos evita custos com manutenção corretiva e aumenta a vida útil do ativo. A sinalização com cor amarela também reforça a segurança.', 0, NULL, N'- Redução do tempo de abastecimento;
INSERT INTO #PVC VALUES (11045, N'81037838', N'81036133', N'Instalação de Caixa Metálica com Tampa Gradeada', 2, N'Others/Outros', N'  O sensor de nível do silo da Rebritagem operava sem proteção física adequada, ficando vulnerável a impactos causados por ferramentas, equipamentos e materiais durante intervenções de manutenção e rotina operacional. Essa condição representava risco de dano ao instrumento, perda de leitura, necessidade de substituições frequentes e possibilidade de interrupção do processo produtivo.', N'Substituir a proteção antiga por uma caixa metálica mais robusta e segura, evitando contato acidental e danos ao vibrador.', N'10054', N'01 - Imagens/01 - Antes/11045.jpeg', N'O sensor de nível do silo da Rebritagem operava sem proteção física adequada, ficando vulnerável a impactos causados por ferramentas, equipamentos e materiais durante intervenções de manutenção e rotina operacional. Essa condição representava risco de dano ao instrumento, perda de leitura, necessidade de substituições frequentes e possibilidade de interrupção do processo produtivo.', N'01 - Imagens/02 - Depois/11045.jpeg', N'   Foi instalada caixa de proteção metálica na cor amarela com tampa em chapa expandida sobre o sensor de nível do silo da Rebritagem. A nova estrutura é mais robusta e fechada, garantindo proteção contra impactos, queda de materiais e ferramentas durante a operação e manutenção. Com isso, foi eliminada a vulnerabilidade do instrumento, assegurando a confiabilidade da leitura de nível e a continuidade do processo produtivo.  ', NULL, N'SIM. O problema foi resolvido. O sensor de nível do silo da Rebritagem que operava sem proteção adequada recebeu uma caixa de proteção metálica com tampa gradeada. A nova estrutura eliminou a vulnerabilidade a impactos, garantindo a integridade do instrumento e a continuidade da leitura de nível.', N'padronização de proteções reduz riscos e retrabalho.', 0, NULL, N'Os equipamentos que saem da Pilha B parem obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4 que tem menos visibilidade devido ponto cego.', '2026-07-05T00:00:00.000', '2026-07-06T03:01:37.000', N'81037838', NULL, NULL);
INSERT INTO #PVC VALUES (11046, N'81046430', N'81013286', N'Plano de Contingência para Abastecimento de Água Potável no Prédio da Moagem SLB I/II', 2, N'Others/Outros', N'Durante as PGUs, o aumento do consumo no Prédio da Moagem SLB I/II reduz a pressão da rede e aumenta o tempo de recarga dos reservatórios do 7º piso, gerando risco de desabastecimento para cerca de 400 pessoas e impacto nas condições de higiene, consumo e continuidade segura das atividades.', N'Garantir a continuidade do abastecimento de água potável no Prédio da Moagem SLB I/II durante períodos de PGU, por meio do aumento da vazão de recarga dos reservatórios', N'10017', N'01 - Imagens/01 - Antes/11046.jpeg', N'Antes do Kaizen, durante as PGUs, o aumento do consumo reduzia a pressão da rede e atrasava a recarga dos reservatórios do 7º piso da Moagem SLB I/II, gerando risco de desabastecimento para cerca de 400 pessoas e impacto nas condições de higiene, consumo e continuidade segura das atividades.', N'01 - Imagens/02 - Depois/11046.jpeg', N'Após o Kaizen, a aquisição do mangote de 100 metros de 1 polegada permitiu reforçar a vazão de recarga dos reservatórios do 7º piso da Moagem SLB I/II durante PGUs, reduzindo o risco de desabastecimento e garantindo maior estabilidade hídrica, segurança sanitária e continuidade das atividades para cerca de 400 pessoas.', NULL, N'A implantação do mangote de 100 metros de 1 polegada possibilitou reforçar a vazão de abastecimento dos reservatórios, melhorando o equilíbrio hídrico do sistema e reduzindo o risco de desabastecimento durante o período crítico.', N'1)A demanda hídrica aumenta significativamente durante PGUs; 2) Pontos elevados são mais vulneráveis ao desabastecimento; 3) Ações simples podem gerar alto impacto operacional; 4) Segurança hídrica impacta diretamente a continuidade das atividades e processos; 5) Padronizar a solução facilita a replicação.', 0, NULL, N'Aumentar a performance e a produtividade da equipe de manutenção, reduzindo o tempo de setup da coleta SOS e assegurando amostras confiáveis para decisões preditivas ágeis e assertivas nas frotas', '2026-06-02T00:00:00.000', '2026-07-06T09:14:27.000', N'81046430', NULL, NULL);
INSERT INTO #PVC VALUES (11047, N'81030314', N'483565', N'REVITALIZADO ABASTECIMENTO DE GRAXA DOS RESERVATORIOS ', 1, N'Others/Outros', N'Durante do abastecimento da máquina o colaborador tinha que subir no equipamento com a mangueira, assim expondo em trabalho em altura. 
INSERT INTO #PVC VALUES (11048, N'1010414', N'1010414', N'Drone Inspection Cobalt Crud Tank', NULL, N'Refining/Refino', N'The 10 year internal inspection interval is past due for the Cobalt Crud Tank (224-334-TNK-012) and is on the list of inspection for the October 2026 PMP.  A YE notification was created to update the PM for internal inspection to call for a drone inspection. Using the drone for this inspection eliminates the need for complex scaffolding or rope access due to tank orientation and geometry', N'Develop a plan for the internal inspection of the Cobalt Crud Tank', N'10006', N'01 - Imagens/01 - Antes/11048.jpeg', N'An Internal inspection has not been performed on this tank due to the limited access inside', N'01 - Imagens/02 - Depois/11048.jpeg', N'The updated Maintenance Plan will call for the inspection to be carried out via drone', NULL, N'The initial goal was met as there is now a plan to use a drone for the internal inspection of the Cobalt Crud Tank', N'N/A', 0, NULL, N'toda a informação agora está centralizada', '2026-07-05T00:00:00.000', '2026-07-06T11:16:29.000', N'1010414', NULL, NULL);
INSERT INTO #PVC VALUES (11049, N'533528', N'533528', N'App Integrado de Gestão de Férias ', 1, N'Others/Outros', N'A gestão de férias era feita em planilha Excel, com baixa visibilidade consolidada e dificuldade para identificar conflitos entre profissionais no mesmo período. Isso aumentava o risco de ausências simultâneas, impacto na produtividade, maior controle manual e dificuldade para visualizar pessoas sem programação, substitutos e concentração por mês.', N'Digitalizar, automatizar e padronizar a gestão de férias das equipes, permitindo o cadastro rápido das programações, atualização visual em Power BI, identificação preventiva de conflitos de agenda e comunicação automática com a liderança. A iniciativa busca aumentar a governança, reduzir riscos de ausência simultânea de profissionais e possibilitar a replicação da solução para outras áreas.', N'10078', N'01 - Imagens/01 - Antes/11049.jpeg', N'A gestão de férias possuía baixa visibilidade consolidada e dependia de acompanhamento manual, dificultando a identificação prévia de conflitos entre pessoas com férias no mesmo período. Isso gerava conflitos indesejados, risco de ausência simultânea de profissionais e impacto potencial na produtividade da área.', N'01 - Imagens/02 - Depois/11049.jpeg', N'Foi desenvolvido um app integrado de gestão de férias utilizando Power Apps, Power BI, Power Query e Power Automate. A solução permite registrar, editar e consultar férias de forma rápida, com atualização do painel gerencial em aproximadamente 3 minutos. O app alerta quando há tentativa de marcação em período já ocupado, reduzindo conflitos e melhorando o planejamento da equipe.
INSERT INTO #PVC VALUES (11050, N'200500', N'607668', N'Installation of Dribble Screw on Furnace M Floor', 2, N'Others/Outros', N'For many years, the M Floor has been designated as a mandatory respirator area due to elevated levels of airborne dust generated from feed and fines carryover at the primary and secondary scrapers located at the head end of the 29 Conveyor (M+1 Floor). The existing design directed these fines into a chute and dribble box below, which required regular manual handling, transportation, and reintroduction into the process. This method created repeated opportunities for dust generation and employee exposure to airborne contaminants, while also increasing housekeeping requirements and maintenance handling activities. The continued presence of dust impacted workplace conditions, necessitated respiratory protection, and presented ongoing challenges in controlling airborne contaminants at the source.', N'Reduce Airborne Contaminants ', N'10194', N'01 - Imagens/01 - Antes/11050.jpeg', N'Prior to the 2026 PMP modification, the head end of the 29 Conveyor generated a significant amount of feed and fines carryover from the primary and secondary scrapers. These fines were discharged into a chute and collected in a dribble box located below on M Floor. As material accumulated, the dribble box required frequent handling, transportation, and dumping back into the process stream. Each step in this process created opportunities for dust generation, resulting in elevated airborne contaminant levels throughout the area. The persistent dust exposure led to M Floor being designated as a mandatory respirator area for many years, while also increasing housekeeping requirements, material handling activities, and employee exposure to airborne particulates. The existing design controlled the material only after it had already escaped the conveyor system, rather than eliminating the contamination source at its origin.', N'01 - Imagens/02 - Depois/11050.jpeg', N'During the 2026 PMP, the existing feed chute was redesigned and a transfer screw was installed to automatically collect and discharge fines directly onto 33 Conveyor. This modification eliminated the need for the dribble box and the associated manual handling, transportation, and dumping of accumulated material. By returning the fines directly to the process stream at the source, the system significantly reduced dust generation and airborne contaminants on M Floor. The improvement created a cleaner and safer work environment, reduced employee exposure to airborne particulates, lowered housekeeping requirements, improved material recovery, and removed a long-standing source of dust that had contributed to the area''s mandatory respirator designation. The new design provides a sustainable engineering control that addresses the root cause of the issue rather than managing the consequences of material spillage after it occurs.', NULL, N'Yes, the problem was solved by rethinking the fines handling process, the team improved safety, reduced manual work, and enhanced operational efficiency through a sustainable, permanent solution.', N'Long-standing workplace hazards can often be eliminated through simple engineering solutions when the focus is placed on addressing the source of the problem rather than managing its symptoms.', 0, NULL, N'Aumento da segurança operacional.
INSERT INTO #PVC VALUES (11051, N'81062708', N'81062708', N'ADESIVO DISTANCIAMENTO SEGURO ', 2, N'Others/Outros', N'Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução.Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. ', N'Promover a conscientização dos condutores sobre a importância de manter uma distância segura entre veículos durante o deslocamento, contribuindo para a prevenção de colisões traseiras e proporcionando maior tempo e espaço para reação diante de situações inesperadas no trânsito.', N'10030', N'01 - Imagens/01 - Antes/11051.jpeg', N'Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução.Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito.', N'01 - Imagens/02 - Depois/11051.jpeg', N'Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução. Promover a conscientização dos condutores sobre a importância de manter uma distância segura entre veículos durante o deslocamento, contribuindo para a prevenção de colisões traseiras e proporcionando maior tempo e espaço para reação diante de situações inesperadas no trânsito.
INSERT INTO #PVC VALUES (11052, N'81058966', N'550686', N'Fabricação e instalação de alçapões no piso superior da remoagem Salobo 2 – BP-2057-32', 1, N'Others/Outros', N'O acesso aos pontos de manutenção era realizado de forma inadequada, exigindo corte com máquinas rotativas durante as intervenções. Isso aumentava o tempo de execução, gerava riscos de acidentes (cortes, projeção de partículas e faíscas), comprometia a ergonomia e elevava os custos de manutenção.', N'Implantar alçapões de acesso para eliminar a necessidade de cortes durante as manutenções, reduzindo o tempo de intervenção, melhorando a ergonomia e aumentando a segurança dos empregados.', N'10031', N'01 - Imagens/01 - Antes/11052.jpeg', N' Antes era necessário realizar cortes com lixadeira  para acessar o equipamento, aumentando o tempo de manutenção e a exposição dos empregados aos riscos de corte e projeção de partículas.', N'01 - Imagens/02 - Depois/11052.jpeg', N'Foram fabricados  alçapões no piso superior da remoagem, permitindo acesso rápido e seguro aos pontos de manutenção, eliminando a necessidade de cortes durante as intervenções.', NULL, N'sim, fabricado alçapões para facilitar na hora da manutenção dos equipamentos.', N'Pequenas melhorias estruturais podem reduzir significativamente os riscos de acidentes, aumentar a produtividade, facilitar futuras manutenções e proporcionar maior segurança e ergonomia para a equipe.', 0, NULL, N'Automatizar a atualização anual do calendário da planilha M+12, eliminando atividades manuais, reduzindo o risco de erros e aumentando a produtividade e confiabilidade das informações utilizadas no planejamento de manutenção.', '2026-07-03T00:00:00.000', '2026-07-06T15:07:31.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11053, N'81058966', N'81038889', N'Eliminação de parada da coluna de flotação para substituição de mangueiras do manifold da CF 2057 22', 1, N'Others/Outros', N'O manifold da coluna possuía mangueiras conectadas diretamente ao sistema, sem válvulas de bloqueio individuais. Quando ocorria desgaste ou vazamento , era necessária a parada total da coluna para realizar sua substituição.
INSERT INTO #PVC VALUES (11054, N'533528', N'533528', N'Emissão Automatizada de Notificações Contratuais', 1, N'Others/Outros', N'O processo de emissão de notificações dependia do SGC, porém a nova versão do sistema não possuía essa funcionalidade disponível. Isso gerava risco de descontinuidade na emissão formal das notificações, maior esforço manual, perda de agilidade e possível impacto na governança contratual e na comunicação com fornecedores.', N'Automatizar a emissão de notificações contratuais por meio do Power Apps, com geração de PDF e envio por e-mail, garantindo continuidade operacional, padronização, agilidade e rastreabilidade no processo de comunicação formal com fornecedores.', N'10078', N'01 - Imagens/01 - Antes/11054.jpeg', N'As solicitações de notificação eram recebidas pela Governança de Contratos e emitidas via SGC. Com a transição do sistema, a nova versão não possuía essa funcionalidade, gerando risco de interrupção do processo, atrasos, controles manuais e perda de padronização na emissão das notificações.', N'01 - Imagens/02 - Depois/11054.jpeg', N'Foi criada no Power Apps uma funcionalidade para emissão automatizada de notificações contratuais, permitindo gerar o documento em PDF diretamente pelo app e encaminhá-lo por e-mail aos responsáveis. A solução garante continuidade operacional durante a transição do SGC, reduz etapas manuais, padroniza a emissão das notificações, melhora a rastreabilidade e aumenta a agilidade da comunicação formal com fornecedores. O PDF gerado mantém estrutura padronizada de notificação, com número, data de emissão, prazo de resposta, fornecedor, contrato, assunto, cláusulas aplicáveis e campo de ciência/assinatura.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/8ac5a1bb-152a-402d-b5e3-3107c1803b31?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&skipAppMetadata=true', N'O problema foi resolvido com a criação de uma funcionalidade no Power Apps para emissão automatizada de notificações contratuais em PDF e envio por e-mail. A solução eliminou a dependência imediata da funcionalidade indisponível no novo SGC, manteve a continuidade do processo, reduziu tratativas manuais e padronizou a comunicação formal com fornecedores.', N'A automação de etapas críticas em processos de governança contratual reduz riscos de descontinuidade, principalmente durante transições sistêmicas. Soluções desenvolvidas com Power Apps e Power Automate podem preservar a padronização, aumentar a rastreabilidade e manter a operação funcionando mesmo quando funcionalidades oficiais ainda não estão disponíveis.', 0, NULL, N'A implantação da proteção semimóvel dos mancais do tambor de retorno da 2301TC03 representa uma importante melhoria de segurança, confiabilidade e manutenibilidade. O Kaizen eliminou exposições a riscos de acidentes, facilitou as atividades de manutenção e inspeção, aumentou a eficiência da coleta de dados do CMA e contribuiu diretamente para a disponibilidade operacional do equipamento, reforçando o compromisso com a segurança das pessoas e a excelência operacional.', '2026-07-03T00:00:00.000', '2026-07-06T15:37:02.000', N'533528', NULL, NULL);
INSERT INTO #PVC VALUES (11055, N'81058966', N'81038801', N'Substituição do sistema de acionamento CF 2057 28', 2, N'Others/Outros', N' Equipamento frequentemente entrava em manutenção, devido queima do motor, quebras de correias e substituição frequente de polias motriz, devido ao desgastes.', N' Eliminar a indisponibilidade do equipamento devido a troca frequentemente de componentes e motor', N'10031', N'01 - Imagens/01 - Antes/11055.jpeg', N'O equipamento utilizava sistema de acionamento V-Drive, que apresentava falhas frequentes, como queima do motor, quebra de correias, desgaste de polias e substituição de mancais.', N'01 - Imagens/02 - Depois/11055.jpeg', N'Foi realizada a substituição do sistema de acionamento V-Drive pelo sistema E-Drive, eliminando os componentes sujeitos a desgaste frequente e proporcionando maior confiabilidade.', NULL, N'redução de paradas para manutenção.', N'A busca por soluções inovadoras e tecnologias mais confiáveis reduz custos de manutenção, aumenta a disponibilidade dos equipamentos e melhora a eficiência operacional.', 0, NULL, N'A implantação da talha na monovia 2051TL01 representa uma melhoria permanente no processo de manutenção do acionamento da TC do SAG, proporcionando um ambiente mais seguro, reduzindo custos operacionais, diminuindo o tempo de intervenção e aumentando a confiabilidade das atividades. O Kaizen reforça a cultura de melhoria contínua, com foco em Segurança em primeiro lugar, eficiência operacional e excelência na manutenção.', '2026-06-15T00:00:00.000', '2026-07-06T15:41:18.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11056, N'92000679', N'92000679', N'Menu Rápido do Usuário', NULL, N'Others/Outros', N'Os usuários precisavam navegar por múltiplas transações SAP, memorizar códigos e acessar diferentes caminhos para executar atividades rotineiras', N'Reduzir interação com o sistema', N'10234', N'01 - Imagens/01 - Antes/11056.jpeg', N'Usuário navegava por diversos menus e precisava memorizar códigos SAP.', N'01 - Imagens/02 - Depois/11056.jpeg', N'Usuário acessa os principais processos em uma única tela, com poucos cliques.', NULL, N'O Menu Rápido SAP transformou um processo baseado na memorização de transações em uma navegação intuitiva e padronizada. A solução eliminou desperdícios de tempo com buscas e acessos repetitivos, concentrando em uma única interface as principais ferramentas utilizadas pela operação.', N'Padronização', 0, NULL, N'page is more intuitive to use ', '2026-07-06T00:00:00.000', '2026-07-07T08:56:19.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (11057, N'81020607', N'723908', N'Melhoria  no abastecimento do compressor da PZ47', 3, N'Others/Outros', N'O tanque de abastecimento do óleo Corena 68 possuía um bujão de fábrica que dificultava sua remoção devido ao elevado torque de aperto.', N'Melhoria continua', N'10139', N'01 - Imagens/01 - Antes/11057.jpeg', N'O tanque de abastecimento do óleo Corena 68 possuía um bujão de fábrica que dificultava sua remoção devido ao elevado torque de aperto. Essa condição aumentava o tempo de abastecimento, exigia maior esforço do colaborador e apresentava risco de danificar o bujão durante a retirada.
INSERT INTO #PVC VALUES (11058, N'475291', N'81035465', N'Adição de placa pare no Acesso da Pilha B com a Sat 4', 2, N'No Replication/Sem replicação', N' Riscos de colisão no acesso devido à falta de sinalização vertical. Os equipamentos vindos da Pilha B não paravam, desrespeitando a preferência dos veículos vindos da Sat 4, que possuem ponto cego crítico na conversão', N'Evitar possíveis colisões entre equipamentos ou veículos ', N'10257', N'01 - Imagens/01 - Antes/11058.jpeg', N' Riscos de colisão no acesso devido à falta de sinalização vertical. Os equipamentos vindos da Pilha B não paravam, desrespeitando a preferência dos veículos vindos da Sat 4, que possuem ponto cego crítico na conversão', N'01 - Imagens/02 - Depois/11058.jpeg', N'Instalação de placa de sinalização "PARE" no acesso que sai da Pilha B. Situação Atual: Fluxo corrigido. Os equipamentos da Pilha B agora param obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4.', NULL, N'Os equipamentos da Pilha B agora param obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4.', N'A instalação de sinalização vertical ("PARE") é indispensável para garantir a preferência correta, eliminar conflitos de tráfego e mitigar riscos de colisão em acessos críticos.', 0, NULL, N' eliminando a necessidade de cortes durante as intervenções, reduzindo o tempo de execução e proporcionando melhores condições ergonômicas e de segurança.', '2026-05-15T00:00:00.000', '2026-07-07T10:14:38.000', N'475291', NULL, NULL);
INSERT INTO #PVC VALUES (11059, N'81046576', N'81020892', N'Maleta Kit de Coleta Padrão - SOS', 3, N'Others/Outros', N'Materiais de coleta SOS armazenados de forma despadronizada em bancadas e caixas de ferramentas, expostos a poeira e umidade, gerando risco de contaminação da amostra e baixa agilidade no processo de coleta.', N'Padronizar o kit de coleta SOS em maleta única, eliminando contaminação dos materiais e reduzindo o tempo de preparação da coleta.', N'10144', N'01 - Imagens/01 - Antes/11059.jpeg', N'Materiais de coleta SOS armazenados de forma despadronizada em bancadas e caixas de ferramentas, expostos a poeira e umidade, gerando risco de contaminação da amostra e perda de tempo no setup da coleta.', N'01 - Imagens/02 - Depois/11059.jpeg', N'Maleta Kit de Coleta Padrão – SOS reúne sonda, bomba de vácuo, mangueiras, tesoura e cortador de filtro em um só local. Elimina contaminação, agiliza o setup e é replicável para as demais frotas.', NULL, N'SIM — problema resolvido. Kit padronizado em maleta única eliminou a exposição dos materiais a poeira e umidade, garantiu a confiabilidade da amostra e reduziu o tempo de preparação da coleta SOS.', N'Padronização simples e de baixo custo, quando aplicada a processos críticos como a coleta SOS, gera ganho direto em confiabilidade, produtividade e qualidade da análise preditiva.', 0, NULL, N'Agilizar pesquisa de documentos de segurança.', '2026-06-30T00:00:00.000', '2026-07-07T12:47:43.000', N'81046576', NULL, NULL);
INSERT INTO #PVC VALUES (11060, N'486474', N'486474', N'SUPORTE REGULAVEL PARA BASE MAGNÉTICA DO SWITCH DE LIMITE DE BÁSCULA ALTA', 1, N'Open Pit/Poço aberto', N'CORRETIVA NO CAMPO 
INSERT INTO #PVC VALUES (11061, N'81030274', N'81030274', N'Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', 1, N'No Replication/Sem replicação', N'não existia Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual', N'Mapear de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual', N'10234', N'01 - Imagens/01 - Antes/11061.jpeg', N'não existia Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', N'01 - Imagens/02 - Depois/11061.jpeg', N'Agora existe Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/8ac993ed-7c4c-4fcc-9cfc-a3c860f8202a?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=610b18fb-40b1-4932-a352-1e8cd9f4ae4a&sourcetime=1783442521551&source=portal', N'agora é possível ter um histórico de todos que fazem requisição emergencial de compras ', N'utilizando bem as ferramentas é possível criar métodos para evitar problemas no peocesso', 0, NULL, N'A melhoria eliminou o risco de acidentes durante a execução da atividade, tornando o processo mais seguro e confiável.
INSERT INTO #PVC VALUES (11062, N'81024446', N'81024446', N'Eliminação de cenário de risco (RAC 01)', 2, N'Others/Outros', N'Para a realização das atividades de inspeção e manutenção da estação de referência de monitoramento da qualidade do ar, era necessário acessar a parte superior da estrutura utilizando cinto de segurança, escada sem corrimão e possuir os treinamentos exigidos para atividades críticas, conforme o RAC 01.', N'Eliminar trabalho em altura durante atividades de inspeção e manutenção da estação de monitoramento da qualidade do ar ', N'10268', N'01 - Imagens/01 - Antes/11062.jpeg', N'Para a realização das atividades de inspeção e manutenção da estação de referência de monitoramento da qualidade do ar, era necessário acessar a parte superior da estrutura utilizando cinto de segurança, escada sem corrimão e possuir os treinamentos exigidos para atividades críticas, conforme o RAC 01. Para realização da atividade ainda era necessária a elaboração de PTS e acompanhamento mais específico. ', N'01 - Imagens/02 - Depois/11062.jpeg', N'Foi construída uma escada de madeira, utilizando material reaproveitado das atividades de supressão vegetal, equipada com corrimão, com o objetivo de eliminar o risco associado ao trabalho em altura. Essa melhoria proporcionou maior segurança e agilidade na execução das atividades de inspeção e manutenção da estação de referência para monitoramento da qualidade do ar', NULL, N'O problema de trabalho em altura foi solucionado com a construção de uma escada fixa de madeira equipada com corrimão, utilizando material reaproveitado das atividades de supressão vegetal. A implementação dessa estrutura eliminou a necessidade de acesso por métodos que exigiam trabalho em altura, reduzindo a exposição dos trabalhadores ao risco de queda e proporcionando maior segurança, praticidade e eficiência nas atividades de inspeção e manutenção da estação de referência para monitoramento da qualidade do ar', N'A substituição de controles administrativos e do uso frequente de sistemas de proteção para trabalho em altura por uma solução de engenharia permanente proporcionou maior segurança, padronização do acesso, redução da exposição ao risco e ganho de eficiência nas atividades de manutenção e inspeção da estação de monitoramento da qualidade do ar', 0, NULL, N'Redução expressiva dos riscos químicos e aumento da segurança operacional.
INSERT INTO #PVC VALUES (11063, N'81017966', N'81017966', N'SINALIZADOR  SEGURANÇA AUDIO/VISUAL TE 2009-07', 2, N'Projects/Projetos', N'A talha elétrica não possuía um sistema de alerta sonoro e visual. Durante a operação, as pessoas ao redor nem sempre percebiam o início dos movimentos ou condições de falha, aumentando o risco de acidentes, colisões e danos ao equipamento.', N'Instalar um sinalizador áudio-visual na talha elétrica para alertar os operadores e pessoas próximas durante os movimentos de elevação e translação, além de indicar situações de sobrecarga e cabo frouxo, aumentando a segurança operacional e reduzindo o risco de acidentes.', N'10124', N'01 - Imagens/01 - Antes/11063.jpeg', N'Ausência de sinalização sonora e visual durante a movimentação da talha.
INSERT INTO #PVC VALUES (11064, N'81017966', N'81017966', N'INSTALAÇÃO SINALIZADOR AUDIO VISUAL TE 2009-09', 2, N'Others/Outros', N'A talha elétrica não possuía um sistema de alerta sonoro e visual. Durante a operação, as pessoas ao redor nem sempre percebiam o início dos movimentos ou condições de falha, aumentando o risco de acidentes, colisões e danos ao equipamento.', N'Instalar um sinalizador áudio-visual na talha elétrica para alertar os operadores e pessoas próximas durante os movimentos de elevação e translação, além de indicar situações de sobrecarga e cabo frouxo, aumentando a segurança operacional e reduzindo o risco de acidentes.', N'10124', N'01 - Imagens/01 - Antes/11064.jpeg', N'Ausência de sinalização sonora e visual durante a movimentação da talha.
INSERT INTO #PVC VALUES (11065, N'510839', N'510839', N'Automatização da Atualização de Calendário na Planilha M+12', 1, N'Others/Outros', N'A atualização anual do calendário utilizado no planejamento M+12 era realizada manualmente, demandando tempo da equipe e aumentando o risco de inconsistências nos dias da semana.', N'Automatizar a atualização do calendário anual da planilha M+12, eliminando ajustes manuais e garantindo maior confiabilidade das informações.', N'10234', N'01 - Imagens/01 - Antes/11065.jpeg', N'A atualização dos dias da semana para novos anos era realizada manualmente na planilha M+12, gerando retrabalho, maior tempo de manutenção e risco de erros no calendário.', N'01 - Imagens/02 - Depois/11065.jpeg', N'Foi criado um calendário dinâmico com fórmulas automáticas, permitindo atualizar todo o ano apenas alterando uma célula de referência, eliminando ajustes manuais.', NULL, N'A meta foi plenamente atingida. O processo de atualização do calendário, anteriormente realizado manualmente e sujeito a erros, foi automatizado por meio de fórmulas dinâmicas. A solução eliminou retrabalho, reduziu o tempo gasto com manutenção da ferramenta e aumentou a confiabilidade dos dados utilizados no planejamento de manutenção.', N'Pequenas automações em ferramentas de planejamento podem gerar ganhos significativos de confiabilidade, produtividade e padronização dos processos.', 0, NULL, N'Monitoramento de variações de temperatura dos pinos da caçamba em tempo real, gerando dados quantitativos para tomadas de decisão para serviços de manutenção no sistema de lubrificação centralizado dos pontos de graxa. ', '2026-07-06T00:00:00.000', '2026-07-07T16:38:18.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11066, N'510839', N'510839', N'Extração Automatizada de Planos de Manutenção da frota de Perfuração', 1, N'Others/Outros', N'A extração de planos de manutenção da frota de perfuração no SAP na transação IP19, exigia preenchimento manual de filtros e critérios de seleção, aumentando o tempo de execução e a possibilidade de erros operacionais.', N'Reduzir o tempo gasto na consulta e extração de planos de manutenção da frota de perfuração, aumentando a padronização, produtividade e confiabilidade do processo.', N'10234', N'01 - Imagens/01 - Antes/11066.jpeg', N'A consulta de planos no SAP IP19 exigia configuração manual através da seleção da variante previamente salva , consumindo tempo e aumentando o risco de inconsistências.', N'01 - Imagens/02 - Depois/11066.jpeg', N'Implementado robô VBA para automatizar consultas e baixas de dados no SAP, aumentando a produtividade e permitindo execução paralela de outras atividades.', NULL, N'Sim, o problema foi resolvido. A implementação do robô VBA eliminou a necessidade de execução manual da consulta e extração dos planos de manutenção na transação IP19. O processo passou a ser realizado automaticamente, reduzindo o tempo operacional, minimizando riscos de erro, garantindo maior padronização das informações e liberando o usuário para atividades de maior valor agregado durante a execução da rotina.', N'A automação de atividades repetitivas através de VBA e SAP Script reduz a dependência da operação manual, aumenta a produtividade da equipe e permite direcionar esforços para análises e atividades de maior valor agregado.', 0, NULL, N'A substituição do equipamento convencional por um modelo elétrico proporciona ganhos expressivos em ergonomia, produtividade e redução de custos. Entre os principais benefícios, destacam-se a redução de aproximadamente 50% no peso do equipamento, a eliminação total do consumo de combustível e da exposição à vibração e ao calor gerados por motores a combustão. Além disso, a menor fadiga dos colaboradores aumenta a agilidade e a produtividade das atividades, reduz pela metade a quantidade de equipamentos necessários (de dois para um), diminui os custos com manutenção e insumos e promove significativa melhoria das condições ergonômicas, com menor sobrecarga física ao longo da jornada de trabalho.', '2026-07-06T00:00:00.000', '2026-07-07T17:29:36.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11067, N'516481', N'516481', N'Proteção Semimóvel dos Mancais do Tambor de Retorno – 2301TC03', NULL, N'Projects/Projetos', N'Antes da implantação da melhoria, os mancais do tambor de retorno possuíam proteção inadequada e pontos de acesso expostos, gerando riscos durante atividades de inspeção e manutenção.', N'Desenvolver e instalar uma proteção semimóvel para os mancais do tambor de retorno da correia transportadora 2301TC03, garantindo maior segurança para as equipes de manutenção, operação e inspeção, além de proporcionar melhor acesso para coleta de dados de monitoramento do equipamento.', N'10362', N'01 - Imagens/01 - Antes/11067.jpeg', N'Antes da implantação da melhoria, os mancais do tambor de retorno possuíam proteção inadequada e pontos de acesso expostos, gerando riscos durante atividades de inspeção e manutenção.
INSERT INTO #PVC VALUES (11068, N'516481', N'516481', N'Instalação da Talha 2051TL01 na Monovia', NULL, N'Projects/Projetos', N'Anteriormente, a substituição do redutor dependia de caminhão munck e de operações de içamento complexas, exigindo maior número de pessoas, isolamento de áreas e condições específicas para execução. Com a instalação da talha na monovia, o equipamento passou a ser movimentado de forma segura, controlada e diretamente no local da manutenção.', N'aumentar a segurança, reduzir o tempo de manutenção e eliminar riscos durante as intervenções no acionamento da Transportadora de Correia (TC) do SAG', N'10362', N'01 - Imagens/01 - Antes/11068.jpeg', N'Anteriormente, a substituição do redutor dependia de caminhão munck e de operações de içamento complexas, exigindo maior número de pessoas, isolamento de áreas e condições específicas para execução. Com a instalação da talha na monovia, o equipamento passou a ser movimentado de forma segura, controlada e diretamente no local da manutenção.
INSERT INTO #PVC VALUES (11069, N'81031131', N'81031131', N'updating Port PI screen', 1, N'Others/Outros', N'port SOS PI was hard to find information on ', N'make Port SOS PI screen easier to use', N'#N/A', N'01 - Imagens/01 - Antes/11069.jpeg', N'previous screen was unorganized and had large icons for less frequently looked at information cluttering the screen while missing some more beneficial information. 
INSERT INTO #PVC VALUES (11070, N'550315', N'550315', N'CLAVICULÁRIO CORRETIVA', 3, N'Others/Outros', N'A falta de um local padronizado para armazenamento das chaves da manutenção corretiva dificultava sua localização e controle, aumentando o risco de extravios e atrasos nas atividades. O problema foi identificado durante a rotina da equipe, devido ao tempo excessivo gasto na busca das chaves e aos impactos na eficiência operacional.', N'Organizar, identificar e controlar as chaves utilizadas nas atividades de manutenção corretiva, garantindo fácil acesso, armazenamento adequado e rastreabilidade, contribuindo para a agilidade no atendimento das ocorrências e para a conservação dos recursos da área.', N'10234', N'01 - Imagens/01 - Antes/11070.jpeg', N'As chaves utilizadas pela equipe de manutenção corretiva não possuem um claviculário específico para armazenamento e controle, permanecendo guardadas em locais diversos e sem identificação padronizada. Essa condição dificulta a localização rápida das chaves, aumenta o risco de extravios e gera perda de tempo durante a execução das atividades de manutenção, impactando a organização e a eficiência da equipe.', N'01 - Imagens/02 - Depois/11070.jpeg', N'Foi implantado um claviculário para a equipe de manutenção corretiva, com posições definidas e identificadas para cada chave. As chaves passaram a ser armazenadas em local específico, de fácil acesso e visualização, garantindo melhor organização, controle e rastreabilidade.', NULL, N'SIM
INSERT INTO #PVC VALUES (11071, N'81058966', N'81046993', N'Fabricação e instalação de alçapões no piso superior da remoagem Salobo 2 – BP-2057-36.', 1, N'Others/Outros', N' O acesso aos pontos de manutenção era realizado de forma inadequada, exigindo corte com máquinas rotativas durante as intervenções. Isso aumentava o tempo de execução, gerava riscos de acidentes (cortes, projeção de partículas e faíscas), comprometia a ergonomia e elevava os custos de manutenção.', N'Implantar alçapões de acesso para eliminar a necessidade de cortes durante as manutenções, reduzindo o tempo de intervenção, melhorando a ergonomia e aumentando a segurança dos empregados.', N'10031', N'01 - Imagens/01 - Antes/11071.jpeg', N' Antes era necessário realizar cortes com lixadeira ou outras máquinas rotativas para acessar o equipamento, aumentando o tempo de manutenção. E riscos ao trabalhador.', N'01 - Imagens/02 - Depois/11071.jpeg', N'Foram fabricados e instalados alçapões no piso superior da remoagem, permitindo acesso rápido e seguro aos pontos de manutenção, eliminando a necessidade de cortes durante as intervenções.', NULL, N'sim, Foram fabricados e instalados alçapões.', N'Pequenas melhorias estruturais podem reduzir significativamente os riscos de acidentes, aumentar a produtividade', 0, NULL, N'depois da janela de visita instalada ficou acessível para limpeza e inspeção  ', '2026-07-02T00:00:00.000', '2026-07-08T11:09:07.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11072, N'501925', N'501925', N'Gestão de análises de Risco', 1, N'Others/Outros', N'Dificuldade na localização de ART''S pela descrição da tarefa.', N'Facilitar busca de documentos no sistema ART.', N'10178', N'01 - Imagens/01 - Antes/11072.jpeg', N'Dificuldade na localização de ART''S pela descrição da tarefa.', N'01 - Imagens/02 - Depois/11072.jpeg', N'Criado controle com todas as análises de risco da coordenação, indicando as RAC''s e PRO''s associados juntamente com os ID''s.', NULL, N'Redução do tempo de busca em 90%', N'Agilizar a pesquisa de documentos', 0, NULL, N'Desenvolvimento de fornecedor local;
INSERT INTO #PVC VALUES (11073, N'81042755', N'81019680', N'Cathodic Protection Thickener Tanks', 1, N'Concentration/Concentração', N'Enable the corrosion protection system, the Cathodic Protection System, for the Concentrator Thickener tanks, specifically the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks.', N'Re-establish Cathodic Protection of Thickener Tanks', N'10047', N'01 - Imagens/01 - Antes/11073.jpeg', N'The Cathodic Protection system on the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks was not powered. There was an issue with the powering equipment and thus it was not powered pending vendor rep. review and troubleshooting of system. ', N'01 - Imagens/02 - Depois/11073.jpeg', N'The Cathodic Protection system on the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks has been re-powered. Issue with the powering equipment solved via replacement of components. ', NULL, N'Yes. Cathodic protection system for thickener tanks re-energized and corrosion protection is re-enabled.', N'Cathotic Protection system, the anodes are consumables.', 10000, 3, N'Increased efficiency', '2026-06-26T00:00:00.000', '2026-07-08T11:29:49.000', N'81042755', NULL, NULL);
INSERT INTO #PVC VALUES (11074, N'81058966', N'81058364', N'Dispositivo para Proteção das Mãos durante o Uso do Punção', NULL, N'Others/Outros', N'Durante a utilização do punção com o auxílio de uma marreta, foi identificado risco de impacto nas mãos e nos dedos do operador. A atividade exigia que os membros superiores permanecessem próximos à área de impacto, aumentando a probabilidade de acidentes e comprometendo a segurança durante a execução do serviço.
INSERT INTO #PVC VALUES (11075, N'81058966', N'81038934', N'Melhoria nas tubulações de recalque e sucção-BQ-2022-188', 1, N'Others/Outros', N'As tubulações de sucção e recalque originais eram confeccionadas em PEAD rígido. Suas curvas e soldas sofriam ressecamento1 progressivo ao longo do tempo, causado pela ação1 do produto químico transportado pelo sistema, o que resultava em vazamentos frequentes.', N'Substituir as tubulações rígidas por modelos flexíveis, com maior resistência ao produto químico transportado, visando elevar a confiabilidade do sistema e eliminar os vazamentos.  ', N'10031', N'01 - Imagens/01 - Antes/11075.jpeg', N'Havia contaminação constante na baia das BQ’s, causada pelo grande volume de vazamentos provenientes das tubulações dos equipamentos.', N'01 - Imagens/02 - Depois/11075.jpeg', N's tubulações rígidas foram totalmente substituídas por modelos flexíveis, desenvolvidos para maior resistência química e durabilidade.', NULL, N'sim,eliminação completa dos vazamentos nas tubulações
INSERT INTO #PVC VALUES (11076, N'81035985', N'81030300', N'Disponibilização de tablet para monitoramento da PC13 na Usina', 2, N'Others/Outros', N'Na operação da Usina, o monitoramento do sistema de acompanhamento de pneus da PC13 em atividades externas era realizado com dificuldade devido à indisponibilidade de acesso móvel ao sistema, o que poderia gerar atrasos na identificação de desvios e impactar a preservação dos ativos.', N'Maior agilidade no monitoramento da PC13 em atividades externas.', N'10162', N'01 - Imagens/01 - Antes/11076.jpeg', N'Não havia acesso móvel ao sistema de monitoramento da PC13 em campo, limitando o acompanhamento em tempo real e tornando o processo mais lento e menos eficiente.', N'01 - Imagens/02 - Depois/11076.jpeg', N'Disponibilização de tablet para acesso ao sistema em campo, permitindo monitoramento em tempo real, maior agilidade operacional e melhor preservação dos ativos.', NULL, N'Antes da implementação, o monitoramento da PC13 em atividades externas era limitado pela falta de acesso móvel ao sistema, dificultando o acompanhamento em tempo real e aumentando o tempo de resposta para identificação de desvios.
INSERT INTO #PVC VALUES (11077, N'81012715', N'81012715', N'Melhoria da Confiabilidade do Monitoramento Preditivo com Sensor Portátil DynaPortable', 1, N'Others/Outros', N'30% dos spots dos equipamentos da Usina permaneciam sem coleta de dados de vibração devido à ausência de sensores fixos', N'Elevar o número de coleta de dados de Spots sem sensor fixo', N'10362', N'01 - Imagens/01 - Antes/11077.jpeg', N'Aproximadamente 30% dos spots dos equipamentos da Usina permaneciam sem coleta de dados de vibração devido à ausência de sensores fixos e à demora na aquisição e reposição desses dispositivos. Essa limitação reduzia a abrangência do monitoramento preditivo, dificultava a identificação precoce de falhas e aumentava o risco de evolução de defeitos em ativos sem acompanhamento contínuo.', N'01 - Imagens/02 - Depois/11077.jpeg', N'Foi adquirido o sensor portátil DynaPortable como solução para monitorar equipamentos sem sensores fixos instalados. O equipamento é leve, compacto, de fácil transporte e fixação magnética, permitindo coletas rápidas com apenas uma mão, inclusive em áreas sem cobertura de rede, armazenando os dados para sincronização posterior via Bluetooth.
INSERT INTO #PVC VALUES (11078, N'81004462', N'81004462', N'Monitoramento pinos da caçamba', 1, N'Others/Outros', N'Falta de visibilidade de Lubrificação deficiente os pinos e buchas da caçamba, ', N'Previsibilidade e monitoramento', N'10015', N'01 - Imagens/01 - Antes/11078.jpeg', N'Desgaste de pinos e buchas da caçamba devido falha de lubrificação, não sendo possível a identificação com antecedência dos problemas de lubrificação devido a eficiência do sistema.', N'01 - Imagens/02 - Depois/11078.jpeg', N'Instalação de sensores de temperatura na extremidade do braço de elevação lado direito e lado esquerdo, com o objetivos de monitorar a ocorrências de variações de temperatura devido falhas de lubrificação em tempo real, gerando parâmetros para atendimento antecipado de possíveis falha e desgaste dos pinos e buchas da caçamba.
INSERT INTO #PVC VALUES (11079, N'544481', N'81047743', N'Adaptação do equipamento atomizador', 1, N'No Replication/Sem replicação', N'O uso de atomizadores costais motorizados no controle de pragas exige elevado esforço físico devido ao peso, vibração, ruído e calor do equipamento. Essas condições aumentam a fadiga, prejudicam a ergonomia, a produtividade e a qualidade das atividades, além de elevar os riscos de falhas operacionais e acidentes, afetando a segurança e a eficiência do processo.', N'Melhoria ergonômica significativa, com redução de sobrecarga física durante a jornada ', N'10017', N'01 - Imagens/01 - Antes/11079.jpeg', N'A utilização de atomizadores costais motorizados nas atividades de controle de pragas exige elevado esforço físico dos colaboradores, devido ao peso do equipamento, vibração, ruído e calor gerados durante a operação. Essa condição intensifica a fadiga ao longo da jornada, impactando negativamente a ergonomia, a produtividade e a qualidade das atividades executadas. Além disso, o desgaste físico aumenta o risco de falhas operacionais e de acidentes, comprometendo a segurança dos colaboradores e a eficiência do processo.
INSERT INTO #PVC VALUES (11080, N'81034443', N'81047331', N'Implementação do Lavador de Peças para Eliminar Contaminação na Limpeza de Componentes.', 3, N'Others/Outros', N'A lavagem de peças era realizada em baldes com acúmulo de óleo e resíduos. Esse método gerava contaminação cruzada entre os componentes, risco de sujeira retornar ao sistema, ambiente de trabalho sujo e inseguro, e descarte inadequado dos resíduos.', N'Padronizar a lavagem de peças utilizando o lavador de peças, garantindo limpeza sem contaminação, aumento da segurança e organização do posto de trabalho.', N'10140', N'01 - Imagens/01 - Antes/11080.jpeg', N'Nas primeiras fotos a lavagem estava sendo feita no balde, com resíduo de óleo preto acumulado no fundo e nas paredes. Isso gera risco de contaminação cruzada, porque a sujeira de uma peça volta pra outra. ', N'01 - Imagens/02 - Depois/11080.jpeg', N'As peças estão na bancada verde do lavador, com contenção. O fluido fica circulando ali e não espalha óleo no chão.
INSERT INTO #PVC VALUES (11081, N'81034443', N'81034443', N' Inventário e Checklist para Ferramentas de Caminhões Fora de Estrada.', 3, N'Others/Outros', N'O armário de ferramentas de apoio aos caminhões fora de estrada não possuía inventário atualizado nem processo padrão de conferência. Isso gerava perda de tempo na busca de ferramentas, ferramentas danificadas ou faltantes não identificadas na troca de turno e risco de atraso na manutenção/liberação dos caminhões por falta de item crítico.', N'Garantir 100% de disponibilidade e rastreabilidade das ferramentas do armário de apoio aos caminhões fora de estrada, através de inventário atualizado e checklist visual na troca de turno, reduzindo perda de tempo na busca de ferramentas e atrasos na manutenção.', N'10140', N'01 - Imagens/01 - Antes/11081.jpeg', N'O armário de ferramentas de apoio aos caminhões fora de estrada não possuía inventário atualizado nem processo padrão de conferência. Isso gerava perda de tempo na busca de ferramentas, ferramentas danificadas ou faltantes não identificadas na troca de turno e risco de atraso na manutenção/liberação dos caminhões por falta de item crítico.', N'01 - Imagens/02 - Depois/11081.jpeg', N'Checklist padrão feito todo início/fim de turno.
INSERT INTO #PVC VALUES (11082, N'516481', N'516481', N'Montagem de Suportes para Linha de Vida na Flexowell 2301TR01', NULL, N'Projects/Projetos', N'ão existia sistema de ancoragem contínuo para trabalho em altura.
INSERT INTO #PVC VALUES (11083, N'81038902', N'81038902', N'dispositivo recuperador de corpos moedores ', 1, N'Others/Outros', N'local -TR-2313SA-01 que e alimentada 
INSERT INTO #PVC VALUES (11084, N'81038902', N'479513', N'janela de inspeção ', 1, N'Others/Outros', N'local- TR-2009-5 chute de descarga chute sem acesso para manutenção  ', N'acessar chute para inspeção  e manutenção interna ', N'10031', N'01 - Imagens/01 - Antes/11084.jpeg', N'LOCAL-SLB-1-2 TR-2009-5 chute de descarga antes esse mesmo chute não tinha como acessar para fazer manutenção deixando o chute se colapsar em desgastes internos  ', N'01 - Imagens/02 - Depois/11084.jpeg', N'LOCAL-SLB-1-2 TR-2009-5 chute de descarga foi fabricado e instalado uma janela de visita na dimensão de 800mmx 800mm assim facilitando o acesso para realizar reparos internamente no chute   ', NULL, N'sim resolvido foi fabricado e instalado uma janela de visita no chute dando condições para acessar e fazer manutenção no mesmo  ', N'sempre criar melhores condições para manutenção ', 0, NULL, N'ELIMINAÇÃO DE RISCOS DE BATIDAS ', '2026-06-29T00:00:00.000', '2026-07-09T00:14:29.000', N'81038902', NULL, NULL);
INSERT INTO #PVC VALUES (11085, N'81011396', N'81011396', N'Desenvolvimento Implemento Garfo para CAT950', 2, N'Projects/Projetos', N'O fornecedor CAT, cotado por suprimentos para fornecimento do implemento Garfo não possuía um implemento nas dimensões necessárias para aplicação na Carregadeira CAT950.  ', N'Especificar Implemento Garfo para implantação na CAT950', N'10015', N'01 - Imagens/01 - Antes/11085.jpeg', N'Ausência de fornecedor que atendesse a especificação para fabricação do Garfo para implementação na Carregadeira CAT950, de acordo com as suas dimensões e requisitos de segurança (mandatório acionamento automático da abertura e fechamento do Garfo), conforme NR-12 Req. Proteção de Máquinas', N'01 - Imagens/02 - Depois/11085.jpeg', N'Desenvolvimento do implemento Garfo, com fornecedor local  de Parauapebas-PA, atendendo aos requisitos de segurança necessários (acionamento hidráulico p/ abertura e fechamento reduzindo assim a exposição ao risco do operador), bem como as dimensões necessárias de operação p/ CAT950 (2440mmx200mmx80mm) com capacidade de carga 18 toneladas', NULL, N'Sim, problema resolvido. Foi desenvolvimento com fornecedor local implemento Garfo, atendendo as especificações técnicas e de segurança', N'Desenvolvimento de novos fornecedores locais', 0, NULL, N'Melhoria da produtividade e do bem-estar da equipe, devido às condições de trabalho mais adequadas.', '2026-07-08T00:00:00.000', '2026-07-09T11:21:21.000', N'81011396', NULL, NULL);
INSERT INTO #PVC VALUES (11086, N'200795', N'301033', N'Garson Rail Slinging Skid', NULL, N'Underground/Subterrâneo', N'Since sections of track rail don''t fit in the Garson cage, we would sling them only 3 at a time.  The method required many supplies including 5 slings, 5 shackles, 2 divider bolts with nuts.  This was time consuming.', N'Increase efficiency and safety', N'10238', N'01 - Imagens/01 - Antes/11086.jpeg', N'Since sections of track rail don''t fit in the Garson cage, we would sling them only 3 at a time.  The method required many supplies including 5 slings, 5 shackles, 2 divider bolts with nuts.  This was time consuming.', N'01 - Imagens/02 - Depois/11086.jpeg', N'Implemented a new rail slinging skid.  It can secure up to 16 sections of track rail.  We can now move almost 6 times the amount in the same time.  All properly designed and engineered for safety.', NULL, N'Problem solved', N'N/A', 0, NULL, N'Redução de custos desnecessários com aquisição de peças e materiais.', '2026-06-30T00:00:00.000', '2026-07-09T12:04:54.000', N'200795', NULL, NULL);
INSERT INTO #PVC VALUES (11087, N'609090', N'609090', N'Air Movers LS1', 3, N'Underground/Subterrâneo', N'The proper amount of CMF required for Load station has always been adequate, the air had a hard time exhausting the area.  High ammonia and high humify would be common during summer months.  Muck Circuit workers felt that something can be done to move the air around and exhaust it faster than its current state', N'Move air and exhaust air faster ', N'10340', N'01 - Imagens/01 - Antes/11087.jpeg', N'The proper amount of CMF required for Load station has always been adequate, but the air had a hard time exhausting the area.  High ammonia and high humify would be common during summer months.  Muck Circuit workers felt that something can be done to move the air around and exhaust it faster than its current state.  ', N'01 - Imagens/02 - Depois/11087.jpeg', N'After discussing the situation with the vent department, it was decided that 3 air movers would be installed with their own stop and start switch in specified locations to move the air around and exhaust quicker from the LS1 platform. Muck Circuit workers are extremely happy with the results especially during the high humidity months. The air movers also help with clearing blast gas when having to blast down hang ups.   ', NULL, N'Yes, the air exhaust faster than before making the environment a lot more comfortable to work.  Having the fans on their own stop and start switch allows the workers to control the flow of air to their liking ', N'Listen to workers that perform the work on a daily basis.  ', 0, NULL, N'Reduced time and effort to clear plugged line from pump', '2026-07-08T00:00:00.000', '2026-07-09T12:52:06.000', N'609090', NULL, NULL);
INSERT INTO #PVC VALUES (11088, N'510839', N'510839', N'Dashboard de Projeção dos Planos de Manutenção da Frota de Carga – Base SAP IP19', 1, N'Others/Outros', N'O processo de análise dos planos da frota de carga era realizado por meio do BI de Projeção de Planos alimentado pelo SAP Hana ou pela extração manual de planilhas Excel do SAP. Além do tempo gasto na obtenção e tratamento das informações, a defasagem da base comprometia a agilidade e a confiabilidade das análises para o planejamento da manutenção.', N'Desenvolver um dashboard simplificado e confiável, utilizando dados extraídos diretamente da transação SAP IP19, reduzindo o tempo de consulta das informações e aumentando a assertividade do planejamento da manutenção da frota de carga.', N'10234', N'01 - Imagens/01 - Antes/11088.jpeg', N'A gestão dos planos da frota de carga era feita por planilhas Excel extraídas do SAP, exigindo análise manual dos dados e aumentando o tempo de consulta e planejamento da manutenção.', N'01 - Imagens/02 - Depois/11088.jpeg', N'Implementado dashboard de projeção dos planos da frota de carga utilizando base SAP IP19, centralizando informações e reduzindo o tempo de análise e planejamento da manutenção.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/26e53ab2-dd5d-4706-ad8d-731dab0da7df/f92168403940559d4135?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim, A melhoria implementada atendeu ao objetivo proposto, substituindo análises manuais realizadas em planilhas extraídas do SAP e complementando as consultas ao BI alimentado pelo SAP Hana. Com a criação do dashboard de Projeção dos Planos da Frota de Carga utilizando dados da transação SAP IP19, houve ganho de produtividade, maior confiabilidade das informações e redução do tempo necessário para análise e tomada de decisão no planejamento da manutenção.', N'utilização de dados extraídos diretamente da transação SAP IP19, associada a dashboards simplificados e direcionados ao usuário, aumenta a confiabilidade das informações e reduz o esforço necessário para análise e planejamento da manutenção.', 0, NULL, N'Bancada móvel com proteção para corte de bloco civil, melhoria na ergonomia do operador e mitigar o risco de projeção ao cortar os blocos.', '2026-07-08T00:00:00.000', '2026-07-09T13:57:07.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11089, N'486474', N'506216', N'ENGATE RAPIDO DE ABASTECIMENTO DE ÓLEO DO MOTOR DIESEL FROTA KOMATSU 830E E 930E', 1, N'Open Pit/Poço aberto', N'​"Identificado vazamento constante de óleo lubrificante no sistema de dreno do motor diesel, causado por desgaste e danos na rosca do bujão/conexão anterior. Esta falha resultava em desperdício contínuo de insumo (óleo motor), riscos de contaminação ambiental e excesso de horas de mão de obra dedicadas a intervenções corretivas e limpeza da área."', N'Substituir a conexão danificada por um sistema de engate rápido para garantir a estanqueidade do cárter, eliminar o desperdício de óleo motor e padronizar o processo de dreno para tornar as revisões futuras mais rápidas e limpas.', N'10140', N'01 - Imagens/01 - Antes/11089.jpeg', N'O dreno do óleo era feito pela remoção manual de um componente com a rosca danificada. O processo gerava gotejamento constante mesmo após o aperto, demandava muito tempo da equipe para conter o óleo e limpar o local, além de trazer o risco de espanar em definitivo a rosca do cárter a cada manutenção.', N'01 - Imagens/02 - Depois/11089.jpeg', N'​Eliminação de Desperdício: Vazamento zero de óleo motor, gerando economia imediata de lubrificante.
INSERT INTO #PVC VALUES (11090, N'55053', N'55053', N'Acompanhamento de carteira', 1, N'Others/Outros', N'Dificuldade na visualização por etapa das ordens da carteira de reforma de componentes.', N'Facilitar visualização de carteira', N'10234', N'01 - Imagens/01 - Antes/11090.jpeg', N'Para visualizar as ordens de reforma por etapa, era necessário criar filtros para visualização exclusiva da etapa.', N'01 - Imagens/02 - Depois/11090.jpeg', N'Foi criado gráfico para acompanhamento das ordens de reforma, por etapa de processo. 
INSERT INTO #PVC VALUES (11091, N'81035985', N'81039320', N'Mesh Monitor', 1, N'Others/Outros', N'Os repetidores de sinal nem sempre mantêm o GPS operacional, dificultando a localização dos equipamentos em campo. Além disso, não há rastreabilidade das movimentações, impossibilitando identificar quem deslocou o repetidor, quando ocorreu a movimentação e para qual área da mina ele foi direcionado, gerando perda de tempo e impacto na eficiência operacional.', N'Precisçao de localização e mapa de calor das minas ', N'10216', N'01 - Imagens/01 - Antes/11091.jpeg', N'A movimentação das repetidoras de sinal ocorria sem controle de localização. Em caso de falha no GPS, as equipes não conseguiam identificar onde o equipamento havia sido posicionado, gerando perda de tempo na localização e impactos na operação.', N'01 - Imagens/02 - Depois/11091.jpeg', N'Foi criado um sistema que registra a última localização da repetidora e a equipe responsável pela movimentação, utilizando o GPS do celular ou tablet para garantir rastreabilidade.', N'https://mesh.revisaai.cloud/pt-BR/map', N'A solução reduziu o tempo de localização das repetidoras durante os desmontes, aumentou a precisão na identificação de áreas sem cobertura e disponibilizou um histórico de movimentações, ampliando o suporte às operações de mina.', N'A rastreabilidade dos ativos não deve depender apenas do GPS embarcado. O registro automatizado da localização e da equipe responsável pela movimentação aumenta a confiabilidade das informações e reduz o tempo gasto na localização das repetidoras.', 0, NULL, N'Facilidade de acesso, organização', '2026-07-08T00:00:00.000', '2026-07-09T15:56:42.000', N'81035985', NULL, NULL);
INSERT INTO #PVC VALUES (11092, N'81054395', N'81054395', N'Desenvolvimento do Fluxograma de Inclusão de Materiais em Estoque', 1, N'Open Pit/Poço aberto', N'A ausência de um fluxograma formal para inclusão de materiais em estoque gerava falta de padronização e retrabalho, sendo identificada durante a análise das solicitações de inclusão.', N'Desenvolver e implementar um fluxograma padronizado para o processo de inclusão de materiais em estoque, definindo critérios, responsabilidades e etapas de aprovação.', N'10015', N'01 - Imagens/01 - Antes/11092.jpeg', N'Antes da melhoria, o processo de inclusão de materiais em estoque não possuía padronização, gerando divergências de avaliação, retrabalho e riscos de inclusões desnecessárias em estoque.', N'01 - Imagens/02 - Depois/11092.jpeg', N'Foi criado um fluxograma padronizado para inclusão de materiais em estoque, definindo responsabilidades e critérios de aprovação. ', NULL, N'Sim. O problema foi mitigado com a criação e implementação do fluxograma, que padronizou o processo, definiu responsabilidades e reduziu dúvidas e retrabalhos nas solicitações de inclusão de materiais em estoque.', N'Padronização do processo e definição clara de responsabilidades. Fluxo formal reduz retrabalho e aumenta a governança. Critérios definidos evitam inclusões desnecessárias em estoque. Alinhamento entre áreas melhora a tomada de decisão.', 0, NULL, N'Melhoria na organização do ambiente, facilitando inspeções e elevando o nível de segurança com baixo custo e alto impacto operacional.', '2026-07-08T00:00:00.000', '2026-07-09T16:46:36.000', N'81054395', NULL, NULL);
INSERT INTO #PVC VALUES (11093, N'81054395', N'81054395', N'Desenvolvimento da Matriz RACI do Processo de Inclusão de Materiais em Estoque', 1, N'Open Pit/Poço aberto', N'A ausência de uma definição formal de responsabilidades gerava dúvidas sobre os papéis das áreas no processo de inclusão de materiais em estoque, impactando o alinhamento e a governança.', N'Definir e formalizar os papéis e responsabilidades das áreas envolvidas no processo de inclusão de materiais em estoque.', N'10015', N'01 - Imagens/01 - Antes/11093.jpeg', N'Antes da melhoria, não havia uma definição clara das responsabilidades das áreas envolvidas, gerando divergências de entendimento e retrabalho.', N'01 - Imagens/02 - Depois/11093.jpeg', N'Foi criada uma matriz RACI para formalizar os responsáveis, aprovadores, consultados e informados em cada etapa do processo.', NULL, N'Sim. A matriz RACI definiu claramente os papéis e responsabilidades, reduzindo dúvidas e aumentando a padronização do processo.', N'Clareza de responsabilidades reduz retrabalho. Papéis bem definidos melhoram o alinhamento entre áreas. Governança depende de atribuições formalizadas.', 0, NULL, N'Adequação de suporte de coletores de resíduos, mantendo organização e limpeza na área.
INSERT INTO #PVC VALUES (11094, N'81004462', N'81004462', N'Escaneamento 3D de caçambas', 1, N'Others/Outros', N'O monitoramento de desgaste das caçambas das escavadeiras e carregadeiras de grande portes eram realizados apenas de modo visual, não existindo a mensuração de desgaste das caçambas.', N'Monitoramento sistemático de desgaste', N'10015', N'01 - Imagens/01 - Antes/11094.jpeg', N'Realizado apenas a inspeção sensitiva a cada 125h para avaliação de desgaste das caçambas e definição de troca, ocorrendo projeções de trocas imprecisas.
INSERT INTO #PVC VALUES (11095, N'92000587', N'81002955', N'ESFRIADOR DE PEÇAS', 1, N'Others/Outros', N'era feito resfriamento jogando água em cima da peça,  risco de queimaduras com o vapor da água quente.', N'  REDUZIR RISCOS ', N'10144', N'01 - Imagens/01 - Antes/11095.jpeg', N'Era feito resfriamento jogando água em cima da peça,  risco de queimaduras com o vapor da água quente.', N'01 - Imagens/02 - Depois/11095.jpeg', N'Foi confeccionado um resfriador de peças, eliminado o risco de queimaduras', NULL, N'SIM, ELIMINAÇÃO DE EXPOSIÇAÕ DO COLABORADOR A QUEIMADURAS.', N'IMPORTANCIA DE IDENTIFICAR RISCOS NAS ATIVIDADES ROTINEIRAS ', 0, NULL, N'Redução de custos com reposição e maior agilidade no processo produtivo, além de promover organização e padronização da área.', '2026-05-22T00:00:00.000', '2026-07-09T22:39:26.000', N'92000587', NULL, NULL);
INSERT INTO #PVC VALUES (11096, N'92000587', N'496890', N'ISTALAÇÃO DE SUPORTE PARA ARMAZENAMENTO DE EXTENÇÕES ELETRICAS ', 1, N'Others/Outros', N'CABOS ESPALHADOS PELO CHÃO, DESORGANIZAÇÃO NAS ATIVIDADES', N' ORGANIZAÇÃO E SEGURANÇA ', N'10144', N'01 - Imagens/01 - Antes/11096.jpeg', N'As extensões elétricas utilizadas na tenda de manutenção da perfuratriz no Pátio de Manutenção Mirante permaneciam acondicionadas diretamente no piso, sem local apropriado para armazenamento. Essa condição ocasionava desorganização da área, dificultava o manuseio dos cabos, aumentava o risco de tropeços e quedas, além de contribuir para o desgaste prematuro das extensões devido ao contato constante com o solo e ao armazenamento inadequado', N'01 - Imagens/02 - Depois/11096.jpeg', N'Foi fabricado e instalado um suporte para acondicionamento das extensões elétricas na tenda de manutenção da perfuratriz do Pátio de Manutenção Mirante. Com a implementação da melhoria, os cabos passaram a permanecer organizados, suspensos e de fácil acesso, promovendo maior segurança operacional, redução do risco de acidentes, preservação dos equipamentos e melhoria das condições de organização e padronização da área conforme os princípios do 5S', NULL, N'SIM, AREA MAIS ORGANIZADA , ELIMINANDO RISCOS DE TROPEÇOS, REDUZINDO DESGASTES DAS EXTENSÕES ', N'5´S NAS ATIVIDADES ', 0, NULL, N'Melhor distribuição de peso
INSERT INTO #PVC VALUES (11097, N'92000587', N'547637', N'ILUMINAÇÃO CABINE DA PF1201', 1, N'Others/Outros', N'FALTA DE ILUMINAÇÃO', N'MELHORAR VISIBILIDADE DO OPERADOR ', N'10144', N'01 - Imagens/01 - Antes/11097.jpeg', N'Não havia no equipamento perfuratriz iluminação na parte superior da cabine para auxiliar no momento de posicionar a lança na horizontal para locomoção muito dificuldade devido a visibilidade no horário de turno noturno', N'01 - Imagens/02 - Depois/11097.jpeg', N'instalado um farol na parte superior da cabine com foco de iluminação para parte traseira do equipamento melhorando a visibilidade no momento de posicionar a lança na horizontal.', NULL, N'SIM. MELHORADO VISIBILIDADE DA OPERAÇÃO', N'MELHORA DA VISIBILIDADE', 0, NULL, N'●	Padronização visual para comunicação com a liderança;
INSERT INTO #PVC VALUES (11098, N'521673', N'33019', N'Climatizado para salão de mina', 2, N'No Replication/Sem replicação', N'O climatizador não funcionava de forma eficiente devido à sua instalação em local inadequado.', N'Reduzir a exposição ao calor', N'10366', N'01 - Imagens/01 - Antes/11098.jpeg', N'Anteriormente, o climatizador não era eficaz devido à sua instalação em local inadequado. Além disso, permanecia desligado com frequência porque o dreno enchia, causando acúmulo de água no chão, o que dificultava as atividades da equipe.', N'01 - Imagens/02 - Depois/11098.jpeg', N'O equipamento passou a proporcionar melhor ventilação e conforto térmico aos empregados mais expostos ao calor durante a execução das atividades, contribuindo para a redução da fadiga, maior bem-estar e melhor desempenho operacional.', NULL, N'Sim, A área agora dispõe de um climatizador instalado em local adequado, proporcionando melhor ventilação aos empregados que estão mais expostos ao calor.', N'Local de trabalho deve ter condições ergonômicas adequadas.', 0, NULL, N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.
INSERT INTO #PVC VALUES (11099, N'550315', N'544865', N'EQUIPAMENTO FULL SERVICE', 1, N'Others/Outros', N'material sendo solicitado para equipamentos de garantia contratualmente ', N'Implementar bloqueio para impedir a abertura de RM (Requisição de Manutenção) corretiva em equipamentos que estejam cobertos por garantia.', N'10234', N'01 - Imagens/01 - Antes/11099.jpeg', N'Identificado solicitação de material para equipamento coberto por garantia.', N'01 - Imagens/02 - Depois/11099.jpeg', N'Implementado o  bloqueio a solicitação de materiais em RMs corretivas para equipamentos cobertos por garantia, garantindo o cumprimento contratual e evitando custos indevidos à empresa.', NULL, N'Problema resolvido com a implementação de bloqueio sistêmico para impedir a abertura de RM corretiva em equipamentos cobertos por garantia, eliminando solicitações indevidas de materiais e assegurando o cumprimento das condições contratuais.', N'Eliminação de solicitações indevidas de materiais para equipamentos em garantia', 0, NULL, N'Em função das notificações lembrarem os responsáveis dos riscos de vencimentos das ações, a expectativa é termos um aumento de aderência.', '2026-07-09T00:00:00.000', '2026-07-10T04:12:26.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11100, N'400428', N'400428', N'6A clean up clean out', 3, N'Concentration/Concentração', N'6A clean up pump plugged regularly and was difficult to tale apart sections to unsand', N'Easier to clean plugged pump', N'10058', N'01 - Imagens/01 - Antes/11100.jpeg', N'Connections were all vitaulic and had no clean out spots making it difficult to clear line.', N'01 - Imagens/02 - Depois/11100.jpeg', N'Installed a clean out valve and a quick connect fitting up the line for ease of clearing line. ', NULL, N'Yes. It will be easier in the future to clear line. Also, if needed it can be disconnected and reconnected without tools', N'Less chance of fatigue or injury struggling to get line back together', 0, NULL, N'Redução de tempo de análise em função de estar publicado e com o número de páginas e visuais suficientes.
INSERT INTO #PVC VALUES (11101, N'81002390', N'81002390', N'Bancada Movel para corte de Bloco ', 1, N'Others/Outros', N'Não havia local especifico para o corte de blocos, a postura da execução da atividade não era ergonómica.
INSERT INTO #PVC VALUES (11102, N'81046355', N'81002390', N'Misturador de Tinta e Massa ', 1, N'Others/Outros', N'Era usado pedaços de cano ou madeira para realizar a mistura da tinta ou massa que seria usada nas atividades.
INSERT INTO #PVC VALUES (11103, N'81002390', N'81002390', N'Sinalização Removível de Solo ', 3, N'Others/Outros', N'Devido a perda de placas ou as mesmas não estar bem fixada sinalizando o local/material.', N'manter o local ou material sinalizado', N'10361', N'01 - Imagens/01 - Antes/11103.jpeg', N'Devido a perda de muitas placas ou as mesmas não estar bem fixada dava a impressão de desordem no local de trabalho ou ausência de sinalização.
INSERT INTO #PVC VALUES (11104, N'81002390', N'81002390', N'Suporte para BOTAS', 3, N'Others/Outros', N' Ausência de local adequado para armazenamento das botas, risco de animais peçonhentos se alojar no EPI.
INSERT INTO #PVC VALUES (11105, N'81002390', N'81002390', N'Suporte para Extensão', 3, N'Others/Outros', N' Ausência de local adequado para armazenamento das extensões, com cabos dispostos no chão, gerando risco de tropeços, desorganização da área e possibilidade de danos aos equipamentos
INSERT INTO #PVC VALUES (11106, N'81002390', N'81002390', N'Suporte para coletores de residuos', 3, N'Others/Outros', N'Coletores acondicionados diretamente no solo.', N'manter 5S', N'10361', N'01 - Imagens/01 - Antes/11106.jpeg', N'Coletores acondicionados diretamente no solo com avarias.', N'01 - Imagens/02 - Depois/11106.jpeg', N'Adequação de suporte de coletores de resíduos, mantendo organização e limpeza na área.
INSERT INTO #PVC VALUES (11107, N'81029879', N'81029879', N'Controle de Caixas Térmicas', 1, N'No Replication/Sem replicação', N' Dificultando na rastreabilidade das caixas térmicas.', N'Objetivo: melhorar o controle e a rastreabilidade das caixas térmicas', N'10178', N'01 - Imagens/01 - Antes/11107.jpeg', N'As caixas térmicas eram disponibilizadas nas áreas conforme a necessidade das equipes. Porém, devido à falta de um controle formal de movimentação, muitas vezes a localização das caixas acabavam sendo informada apenas por mensagens no WhatsApp, dificultando a rastreabilidade e o acompanhamento atualizado de onde cada unidade se encontra.', N'01 - Imagens/02 - Depois/11107.jpeg', N'Para solucionar essa situação e garantir maior controle, foi criado um acompanhamento para identificarmos, de forma rápida e confiável, a localização atual de cada caixa térmica.
INSERT INTO #PVC VALUES (11108, N'81002390', N'81002390', N'Suporte Móvel para Identificação de Materiais', 3, N'Others/Outros', N'Deficiência na identificação de materiais devido à falta de espaço adequado e ausência de suporte para fixação das placas, gerando desorganização, dificuldade na localização dos materiais a ser utilizado ou descartado. Transporte feito de forma segura, distribuindo o peso e mitigando o risco ergonômico.', N'5S, Sinalização', N'10361', N'01 - Imagens/01 - Antes/11108.jpeg', N'Deficiência na identificação de materiais e ausência de suporte para fixação das placas, gerando desorganização, dificuldade na localização dos materiais a ser utilizado ou descartado. ', N'01 - Imagens/02 - Depois/11108.jpeg', N'Com o suporte móvel para placas de identificação, foi possível posicionar a sinalização diretamente junto aos materiais, garantindo melhor visibilidade, preservação das placas, redução de custos com reposição e maior agilidade no processo produtivo, além de promover organização e padronização da área.', NULL, N'Sim, melhor visibilidade, preservação das placas.', N'Preservação das placas, redução de custos com reposição e maior agilidade no processo produtivo', 0, NULL, N'With larger garbage disposal capacity there is less risk of garbage being stored in improper areas', '2026-04-10T00:00:00.000', '2026-07-10T15:22:06.000', N'81002390', NULL, NULL);
INSERT INTO #PVC VALUES (11109, N'81002390', N'81002390', N'FUNIL LANÇADOR DE CONCRETO', 1, N'Others/Outros', N'Era realizado o carregamento manual de concreto em baldes. Porém, devido o peso e o formato do balde dificultava a atividade laboral e ergonômica, também causando desperdício de material.
INSERT INTO #PVC VALUES (11110, N'81054422', N'81048232', N'Painel de Acompanhamento de Projetos de Engenharia via Power BI (Python', 1, N'Others/Outros', N'Falta de padronização e agilidade no monitoramento da carteira de projetos, com risco de atrasos não percebidos a tempo, ausência de visibilidade sobre custo estimado em aberto e sobrecarga de engenheiros não mapeada', N'Desenvolver e implementar um painel automatizado de acompanhamento da carteira de projetos de engenharia, utilizando Power BI integrado a visuais em Python, com o objetivo de consolidar informações de prazo, custo, status e carga de trabalho em uma única plataforma, aumentando a visibilidade da carteira, agilizando a tomada de decisão, reduzindo atividades manuais de reporte e permitindo a identificação proativa de atrasos, reprogramações e riscos associados aos projetos.', N'10081', N'01 - Imagens/01 - Antes/11110.jpeg', N'O acompanhamento da carteira de projetos de engenharia (aceitos, novos, encerrados) era feito de forma dispersa, sem visão consolidada de prazos, custos e carga de trabalho por engenheiro. Não havia identificação automática de projetos atrasados ou reprogramados, dificultando a priorização e a comunicação de status para a área. A geração de relatórios de acompanhamento dependia de montagem manual, consumindo tempo e sujeita a inconsistências.', N'01 - Imagens/02 - Depois/11110.jpeg', N'Desenvolvimento de um conjunto de visuais Python integrados ao Power BI, aplicados diretamente sobre a base de dados de projetos, contemplando:
INSERT INTO #PVC VALUES (11111, N'544481', N'544481', N'SUPORTE DE FERRAMENTAS ', 2, N'Others/Outros', N'As ferramentas ficavam armazenadas de forma desorganizada, sem identificação adequada e sem controle de uso. Havia dificuldade na localização, perda de tempo durante as atividades e risco de extravio ou uso inadequado.', N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.', N'10017', N'01 - Imagens/01 - Antes/11111.jpeg', N'As ferramentas ficavam armazenadas de forma desorganizada, sem identificação adequada e sem controle de uso. Havia dificuldade na localização, perda de tempo durante as atividades e risco de extravio ou uso inadequado.', N'01 - Imagens/02 - Depois/11111.jpeg', N'Ferramentas foram organizadas e padronizadas com identificação visual e controle de uso, reduzindo o tempo de busca e aumentando a conservação, eficiência e segurança das atividades.', NULL, N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.
INSERT INTO #PVC VALUES (11112, N'81063756', N'81063756', N'Abrangência do fluxo de notificação de vencimento de prazos de Ações do Plano Diretor', 1, N'Others/Outros', N'O fluxo de notificação de vencimento de prazos de Ações do Plano Diretor havia sido criado apenas para a gerência de Insp, Confiab e Eng.
INSERT INTO #PVC VALUES (11113, N'81063756', N'81063756', N'Dashboard de Eventos na Mina e Perdas de DF por Paradas de Manutenção', 1, N'No Replication/Sem replicação', N'O time de Confiabilidade de mina utilizava dois Dashboards:
INSERT INTO #PVC VALUES (11114, N'81042217', N'81033125', N'Dispositivo para transporte seguro de amostras de cobre entre a área de coleta e o laboratório', 1, N'Others/Outros', N'As amostras de concentrado de cobre coletadas na área de descarga eram transportadas manualmente até o laboratório para análise de umidade e densidade. Essa condição exigia esforço físico dos colaboradores e aumentava a possibilidade de impactos, movimentação excessiva ou alterações das características da amostra durante o transporte, podendo comprometer a confiabilidade dos resultados analíticos.', N'Reduzir o esforço físico associado ao transporte manual das amostras. Preservar a integridade das amostras durante o deslocamento. Melhorar a confiabilidade dos resultados de umidade e densidade. Aumentar a segurança e ergonomia dos colaboradores. Padronizar o processo de transporte de amostras.', N'10294', N'01 - Imagens/01 - Antes/11114.jpeg', N'Transporte manual das amostras entre o ponto de coleta e o laboratório.
INSERT INTO #PVC VALUES (11115, N'81005555', N'524302', N'Tubo distanciador de ajuste dos mancais ', 1, N'Others/Outros', N'Era necessário ajuda de uma outra pessoa para ajustar os mancais, enquanto um  verificava a medida a ajuda do outro era para segurar a trena e escala.', N'Eliminar a necessidade de duas pessoas para ajustar o distanciamento dos mancais', N'10249', N'01 - Imagens/01 - Antes/11115.jpeg', N'Por diversas vezes era necessário ajuda de outro colega para ajustar os mancais, isso atrasava a atividade dele e acarretava em perca de produtividade para a turma.', N'01 - Imagens/02 - Depois/11115.jpeg', N'Usinado um tubo, que é instalado no furo do graxeiro para serve de guia durante o ajuste, dessa forma não é mais necessário ajuda de outra pessoa para ajustar os mancais, basta rosquear o tubo. ', NULL, N'Foi resolvido e testado na prática, o restante do ajuste foi feito sozinho, somente fazendo uso da ferramenta criada.', N'Fortalecimento do senso de criatividade em prol da melhor distribuição da equipe', 0, NULL, N'para eliminar as possíveis falhas de nível do L/C e da confiabilidade para o equipamento.', '2026-06-17T00:00:00.000', '2026-07-11T02:06:42.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11116, N'81005555', N'524302', N'Ferramenta de instalação do retentor do eixo pinhão do diferencial 854k', 1, N'Others/Outros', N'Falta de meios adequados para instalar o retentor, risco de danificar.', N'Criar um dispositivo capaz de instalar o retentor sem danificar', N'10249', N'01 - Imagens/01 - Antes/11116.jpeg', N'Atividade foi paralisada pois o retentor precisava passar por ajustes e principalmente pois o retentor precisava de uma ferramenta específica que garantisse a sua instalação de forma segura.', N'01 - Imagens/02 - Depois/11116.jpeg', N'A ferramenta foi criada, encaixe feito na base do retentor, material leve e com uma boa resistência, feito instalação do retentor com a ferramenta, testado na prática durante a manutenção desse componente. ', NULL, N'Meta foi atingida e a comprovação veio após o teste prático', N'Senso de engajamneto', 0, NULL, N'Acionamento instantâneo. Ao menor sinal de alerta de temporais, qualquer colaborador abre o aplicativo no celular e, com um toque, acende as luzes vermelhas na área. O tempo de resposta caiu para zero, iniciando o processo de abrigo imediatamente', '2026-06-18T00:00:00.000', '2026-07-11T02:18:13.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11117, N'81005555', N'524302', N'Ferramenta de remoção dos rolamentos do tambor da TCLD', 1, N'Others/Outros', N'Era extremamente difícil remover os rolamentos do tambor da TCLD, pois é um equipamento de grande porte, na maior parte das vezes era necessário cortar os rolamentos. ', N'Realizar a desmontagem sem precisar bater com marretas no rolamento, de uma forma mais rápida e mais eficiente.', N'10249', N'01 - Imagens/01 - Antes/11117.jpeg', N'Era utilizado uma marreta ou slide para bater no rolamento e dessa forma deslocar da bucha e fazê-lo se soltar do eixo, na maioria das vezes era necessário o uso de oxicorte pois o rolamento é de grande porte.  ', N'01 - Imagens/02 - Depois/11117.jpeg', N'Agora é utilizado pressão hidráulica para desmontar, não é necessário uso do oxicorte, apenas pressão hidráulica que é conduzida até os rasgos da bucha e dessa forma obriga o rolamento se deslocar do eixo.', NULL, N'A meta era desmontar o rolamento de uma outra maneira, mais fácil e com mais comodidade para o executante.', N'Fazendo e acontecendo', 0, NULL, N'REDUÇÃO DE TEMPO AO REALIZAR ATIVIDADE', '2026-06-20T00:00:00.000', '2026-07-11T02:34:30.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11118, N'81037761', N'81037761', N'Alarme crítico do Sistema de Despoeiramento Prensagem Salobo IIIParado', 1, N'No Replication/Sem replicação', N'Quando ocorre falha no Sistema de Despoeiramento Prensagem Salobo III não é possível uma identificação rápida do técnico de sala de controle problema devido ausência de alarme crítico.', N'Identificação rápida da falha no Sistema de Despoeiramento da Prensagem Salobo III', N'10025', N'01 - Imagens/01 - Antes/11118.jpeg', N'O Sistema de Despoeiramento da Prensagem foi projetado para operar em modo automático. Contudo, em situações de falha, a Sala de Controle perde a visibilidade operacional do sistema, impossibilitando a identificação imediata de sua condição de operação (em funcionamento ou parado). Além disso, atualmente não existe um alarme crítico que sinalize prontamente essas ocorrências, dificultando o acionamento rápido da cadeia de ajuda para o tratamento da anomalia e o restabelecimento seguro do processo.', N'01 - Imagens/02 - Depois/11118.jpeg', N'Foi implementado um alarme de alerta na tela principal do Sistema Supervisório da Prensagem com o objetivo de notificar imediatamente o técnico de sala sobre eventuais falhas no Sistema de Despoeiramento da Prensagem, possibilitando a rápida avaliação da situação e o acionamento da cadeia de ajuda, quando necessário. Essa iniciativa é fundamental para a mitigação de riscos ambientais e operacionais, prevenindo o acúmulo de poeira em suspensão, que pode comprometer a visibilidade dos operadores em campo e impactar a qualidade do ar respirado, expondo os trabalhadores a condições inseguras.', NULL, N'Alarme implementado e funcional no Sistema Supervisório da Prensagem, com exibição automática na tela principal sempre que ocorrer uma falha no Sistema de Despoeiramento da Prensagem, proporcionando visibilidade imediata da ocorrência e permitindo uma resposta rápida da equipe operacional.', N'Importância do acionamento rápido da cadeia de ajuda reduzem o tempo de resposta, minimizam riscos ambientais e ocupacionais.', 0, NULL, N'Keep on full power', '2026-07-06T00:00:00.000', '2026-07-11T04:42:07.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11119, N'1009261', N'1009261', N'Label for HCL samples', 3, N'Refining/Refino', N'sample bottle full of solution with no label', N'identify samples', N'0', N'01 - Imagens/01 - Antes/11119.jpeg', N'Full samples bottles with no label identifying contents', N'01 - Imagens/02 - Depois/11119.jpeg', N'Label to identify the samples ', NULL, N'yes, problem was solved', N'samples need to be identified', 0, NULL, N'To safely take samples.', '2026-06-30T00:00:00.000', '2026-07-11T09:56:54.000', N'1009261', NULL, NULL);
INSERT INTO #PVC VALUES (11120, N'81055041', N'81055041', N'Padronização e Garantia de Registros de Embarque com Uso de Dispositivo Corporativo Dedicado', 1, N'Others/Outros', N'Durante o processo de embarque, foi identificado que não há garantia nem confiabilidade nos volumes registrados sem a evidência formal entre paradas. Os inspetores, embora presentes integralmente na operação, não conseguem se deslocar para realizar os registros nas balanças, gerando lacunas no processo. Além disso, o uso de dispositivos pessoais compromete a padronização, segurança e continuidade das informações entre turnos.
INSERT INTO #PVC VALUES (11121, N'1015684', N'1015684', N'Larger Domestic Waste Bin at Port', 1, N'Refining/Refino', N'The domestic waste bin at Port was undersized, this would lead to excess garbage being kept inside the building, or general waste being disposed of in the contaminated waste bin, resulting in extra costs of disposal for materials not required to be sent off as contaminated.', N'To have a larger general waste bin similar to the metal and wood bins.', N'0', N'01 - Imagens/01 - Antes/11121.jpeg', N'The domestic waste bin at Port was undersized, this would lead to excess garbage being kept inside the building, or general waste being disposed of in the contaminated waste bin, resulting in extra costs of disposal for materials not required to be sent off as contaminated.', N'01 - Imagens/02 - Depois/11121.jpeg', N'Sourced a larger domestic waste bin for use at Port, this will allow us to segregate and dispose of our waste properly and cut down on the cost of contaminated waste disposal.', NULL, N'We estimate that with the larger general waste bin we will be able to divert 3-5 full bins of contaminated waste a year into the proper domestic waste bin.', N'Adding the larger bin has made garbage disposal and segregation better at Port.', 40000, 3, N'Com a instalação de luminária na tenda de material preventiva, eliminando os riscos de animais peçonhentos devido, tropeços, com a iluminação que estava baixa.
INSERT INTO #PVC VALUES (11122, N'81047013', N'472909', N'Dispositivo para abastecimento de óleo no 2051BR01', NULL, N'Others/Outros', N'-Abastecimento realizado diretamente no reservatório.
INSERT INTO #PVC VALUES (11123, N'498359', N'81047016', N'PROTEÇÃO GUARDA CORPO', 2, N'Others/Outros', N'acesso ao fosso estava danificado e sem partes de guarda - corpo causando risco de queda do mesmo nivel, batida contra e afogamento', N'ELIMINAR RISCOS', N'10362', N'01 - Imagens/01 - Antes/11123.jpeg', N'Acesso ao fosso estava danificado e sem partes de guarda - corpo causando risco de queda do mesmo nível, batida contra e afogamento', N'01 - Imagens/02 - Depois/11123.jpeg', N'Foi realizada uma melhoria com a instalação de um guarda-corpo, visando eliminar a condição de risco e prevenir acidentes, como queda de mesmo nível e afogamento, proporcionando mais segurança às pessoas que circulam pela área.', NULL, N'META ATINGIDA COM SUCESSO', N'melhorar ambiente de trabalho', 0, NULL, N'GARANTIR UMA ÁREA DE IÇAMENTO MAIS SEGURA, COM ACESSO CONTROLADO E DEVIDAMENTE ISOLADO  DURANTE A MOVIMENTAÇÃO DE CARGAS, REDUZINDO O RISCO DE ACIDENTES, PROTEGENDO OS COLABORADORES E PROMOVENDO MAIOR SEGURANÇA E ORGANIZAÇÃO NAS OPERAÇÕES DE RECEBIMENTOS DE MATERIAIS', '2026-07-10T00:00:00.000', '2026-07-11T17:31:39.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11124, N'498359', N'81061120', N'PROTEÇÃO GUARDA-CORPO', 2, N'Others/Outros', N'TUBULAÇÃO PROXIMO DA CELULA RADIOATIVA ESTAV SEM PARTES DO GUARDA CORPO CAUSANDO RISCO DE QUEDA DE MESMO NIVEL.', N'ELIMINAR RISCO ', N'10362', N'01 - Imagens/01 - Antes/11124.jpeg', N'TUBULAÇÃO PROXIMO DA CELULA RADIOATIVA ESTAV SEM PARTES DO GUARDA CORPO CAUSANDO RISCO DE QUEDA DE MESMO NIVEL.', N'01 - Imagens/02 - Depois/11124.jpeg', N'FOI RECUPERADO A PROTEÇÃO GUARDA CORPO DA TUBULAÇÃO DA BOMBA DE POLPA ELIMINANDO RISCO DE QUEDA DE MESMO NIVEL', NULL, N'META ATINGIDA', N'MELHORAR AMBIENTE DE TRABALHO', 0, NULL, N'Melhorar o monitoramento operacional por meio da visualização em tempo real da corrente dos alimentadores, permitindo a identificação rápida de desvios, maior controle do processo e aumento da eficiência operacional.', '2026-07-10T00:00:00.000', '2026-07-11T17:39:36.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11125, N'81047013', N'81056636', N'PORTINHOLA DE PROTEÇÃO - ACESSO AO SENSOR DE VELOCIDADE 2301BR01', NULL, N'Others/Outros', N'Para acessar o sensor de velocidade do rebritador, era necessário tirar bloquear e tirar toda a proteção das correias de acionamento, demandando mais tempo e esforço dos colaboradores.', N'Implementar barreira de proteção entre partes moveis e permitir o acesso rápido ao sensor em caso de parada', N'10362', N'01 - Imagens/01 - Antes/11125.jpeg', N'Para acessar o sensor de velocidade do rebritador, era necessário tirar bloquear e tirar toda a proteção das correias de acionamento, demandando mais tempo e esforço dos colaboradores. ', N'01 - Imagens/02 - Depois/11125.jpeg', N'Fabricada uma portinhola de acesso, mantendo a barreira fisica nas partes moveis mas possibilitando o acesso ao sensor caso necessário', NULL, N'Meta alcançada 100%', N'Facilitar o acesso mantendo a segurança', 0, NULL, N'plate can''t be dropped now', '2026-07-06T00:00:00.000', '2026-07-11T17:49:00.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (11126, N'81052181', N'514016', N'Passaporte de Emergência do Colaborador – Identificação Rápida de Informações Críticas de Saúde', 1, N'Others/Outros', N'Atualmente, os colaboradores possuem apenas o passaporte de treinamentos, não existindo um meio padronizado e de fácil acesso para disponibilizar informações essenciais de saúde em situações de emergência. ', N'Desenvolver e implantar um Passaporte de Emergência do Colaborador, contendo informações críticas de saúde e contato, de forma padronizada, prática e acessível, visando agilizar o atendimento em situações de emergência, apoiar a tomada de decisão das equipes de resgate e contribuir para a segurança e preservação da vida dos colaboradores.', N'10245', N'01 - Imagens/01 - Antes/11126.jpeg', N'Os colaboradores possuíam apenas o passaporte de treinamentos, sem um documento com informações essenciais de saúde para consulta rápida em situações de emergência.', N'01 - Imagens/02 - Depois/11126.jpeg', N'Implantação do Passaporte de Emergência, reunindo informações críticas de saúde e contatos em um único documento, permitindo atendimento mais rápido, seguro e eficiente.', NULL, N'Meta: Disponibilizar um passaporte com informações essenciais de saúde para todos os colaboradores.
INSERT INTO #PVC VALUES (11127, N'81042202', N'81010117', N'Mangueira de ar comprimido', 2, N'Others/Outros', N'
INSERT INTO #PVC VALUES (11128, N'81059721', N'552496', N'ALINHAMENTO DO SENSOR DE NÍVEL DO L/C', NULL, N'Others/Outros', N'O chicote do sensor de nível do L/C estava com várias, e ocasionando ocorrências de baixo nível devido o chicote se rompendo, ocasionando parada do equipamento', N'evitar parada do equipamento, redução de custos e tempo', N'10144', N'01 - Imagens/01 - Antes/11128.jpeg', N'O chicote do sensor de nível do L/C estava com várias, e ocasionando ocorrências de baixo nível devido o chicote se rompendo, ocasionando parada do equipamento.
INSERT INTO #PVC VALUES (11129, N'81059721', N'545523', N'IMPLEMENTAÇÃO DE ALERTA REMOTO PARA DESCARGAS ATMOSFÉRICAS - VIA WI-FI', 2, N'Projects/Projetos', N'a informação dependia do repasse manual. O operador precisava se deslocar até um painel físico para ligar um alarme ou avisar os grupos de boca em boca. Segundos preciosos eram perdidos na comunicação.
INSERT INTO #PVC VALUES (11130, N'81022743', N'81006537', N'PROTEÇÃO PARA PARTE ROTATIVA DA BOMBA DO ACOPLAMENTO', 1, N'Open Pit/Poço aberto', N'EXPOSIÇÃO DE MÃOS E DEDOS A PARTES ROTATIVAS DA BOMBA DO ACOPLAMENTO ', N'EVITAR CONTATO COM PARTES ROTATIVAS DA BOMBA DO ACOPLAMENTO', N'10144', N'01 - Imagens/01 - Antes/11130.jpeg', N'NÃO TINHA PROTEÇÃO NA PARTE ROTATIVA DA BOMDA DO ACOMPLAMENTO, O COLABORADOR ERA EXPOSTO A CORTE, E ESMAGAMENTO  DE MEMBROS. ', N'01 - Imagens/02 - Depois/11130.jpeg', N'CRIAMOS UMA PROTEÇÃO PARA PARTE ROTATIVA DA BOMBA, EVITANDO CONTATO COM OS MEMBROS DOS COLABORADORES, ELIMINANDO O RISCO DE CORTE, E ESMAGAMENTO! PROPORCIONAMENTO REALIZAR ATIVIDADE COM SEGURANÇA E AGILIDADE. ', NULL, N'PROBLEMA ELIMINADO, POIS NÃO TEM MAIS CONATATO COM MEMBROS DOS COLABORADORES.', N'EVITAR CONTATO COM PARTES ROTATIVAS ', 0, NULL, N'Reduzindo o tempo de limpeza;
INSERT INTO #PVC VALUES (11131, N'1008564', N'1009524', N'Avoid high Anolyte Temperature', 1, N'Refining/Refino', N'Powering down from 24000A due to high anolyte temp, ', N'Avoid the anolyte temperatures from exceeding 60 degrees and keeps us at full power', N'0', N'01 - Imagens/01 - Antes/11131.jpeg', N'The Anolyte temperature was exceeding 60 degrees and causing us to reduce power. ', N'01 - Imagens/02 - Depois/11131.jpeg', N'Lowered the Bay Heat Exchangers cooling water setpoints from 52 down to 50.5 degrees', NULL, N'yes', N'Keep temperature down to keep from staying om full power', 0, NULL, N'diminui o tempo de parada do equipamento e aumenta a confiabilidade operacional do sistema de refugo de bolas dos moinhos.', '2026-07-11T00:00:00.000', '2026-07-12T07:48:41.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (11132, N'81062686', N'81062686', N'Sample information and PPE', 2, N'Others/Outros', N'There were no safety information or proper gloves at the sample point.', N'To provide necessary details and PPE to safely take samples.', N'10212', N'01 - Imagens/01 - Antes/11132.jpeg', N'No safety information and no proper gloves. ', N'01 - Imagens/02 - Depois/11132.jpeg', N'Added safety information and proper PPE.', NULL, N'Yes, necessary details and PPE to safely take samples have been added.', N'N/A', 0, NULL, N'CO2 emission could be reduced 126 Kg per year.', '2026-07-11T00:00:00.000', '2026-07-12T08:10:35.000', N'81062686', NULL, NULL);
INSERT INTO #PVC VALUES (11133, N'81056513', N'81047889', N'SUPORTE PROPULSSORAS DE GRAXA', 3, N'Others/Outros', N'Antes as propulssoras de graxa não tinha local adequado ficava num canto no boxe em cima de paletes.', N'Organização e padrão 5s', N'10324', N'01 - Imagens/01 - Antes/11133.jpeg', N'Antes as propulssoras de graxa não tinha local adequado ficava num canto no boxe em cima de paletes.', N'01 - Imagens/02 - Depois/11133.jpeg', N'Com aplicação de suporte agora propulssoras possuem local seguro e adequado para armazenamento', NULL, N'Desorganização e poluição de cenario com propulsorras mal armazenadas', N'5s', 0, NULL, N'Disponibilizar informações gerenciais de forma rápida e confiável, eliminando atividades manuais de consolidação de dados e permitindo o monitoramento contínuo dos principais indicadores de manutenção da frota.', '2026-07-11T00:00:00.000', '2026-07-12T11:50:38.000', N'81056513', NULL, NULL);
INSERT INTO #PVC VALUES (11134, N'81059721', N'552496', N'ILUMINAÇÃO NA TENDA DE MATERIAL - PREVENTIVA', 3, N'Others/Outros', N'O local possuía baixa  iluminação na tenda de material preventiva pátio Mirante, dificultando visibilidade e aumentando o risco de acidentes com risco animais peçonhentos..
INSERT INTO #PVC VALUES (11135, N'81059721', N'552496', N'INSTALAÇÃO DA LUMINÁRIA NA PARTE INTERNA DA CABINE', 1, N'Others/Outros', N'a falta de iluminação na cabine impossibilitando a  visibilidade dos botões de acionamento do caminhão, e tropeço dentro da cabine por não visualizar a parte interna do mesmo.', N'Segurança, melhor visibilidade, ter qualidade principalmente em  turnos noturnos que precisam de visibilidade ', N'10144', N'01 - Imagens/01 - Antes/11135.jpeg', N'Não existia iluminação interna na cabine do operador, impossibilitando a  visibilidade dos botões de acionamento do caminhão, e tropeço dentro da cabine por não visualizar a parte interna do mesmo.
INSERT INTO #PVC VALUES (11136, N'81046953', N'81055527', N'INSTALAÇÃO DE PORTÃO DE SEGURANÇA NA ÁREA DA PONTE PARA RECEBIMENTO E IÇAMENTO DE MATERIAIS', 2, N'Others/Outros', N'A ÉRA DA PONTE DESTINADA AO RECEBIMENTO E IÇAMENTO DE MATERIAIS NÃO POSSUIA PORTÃO DE ISOLAMENTO. ISSO PERMITIA O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS, AUMENTANDO O RISCO DE ACIDENTES, COMO ATIGIMENTO POR CARGAS SUSPENSAS E ACESSO NÃO AUTORIZADO Á ÁREA OPERACIONAL.', N'INSTALAR UM PORTÃO DE SEGURANÇA NA ÁREA DA PONTE PARA CONTROLAR O ACESSO DURANTE O RECEBIMENTO E O IÇAMENTO DE MATERIAIS, ELIMINANDO EXPOSIÇÃO DOS COLABORADORES AOS RISCOS DE CARGAS SUSPENSAS, AUMENTANDO A SEGURANÇA OPERACIONAL GARANTINDO UMA ÁREA DE TRABALHO MAIS ORGANIZADA E SEGURA', N'10362', N'01 - Imagens/01 - Antes/11136.jpeg', N'A ÁREA DA PONTE DESTINADA AO RECEBIMENTO E IÇAMENTO DE MATERIAL NÃO POSSUÍA PORTÃO DE ISOLAMENTO. ISSO PERMITIA O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS, AUMENTANDO O RISCO DE ACIDENTES, COMO ATINGIMENTO POR GARGAS SUSPENSAS E ACESSO NÃO AUTORIZADO Á ÁREA OPERACIONAL.', N'01 - Imagens/02 - Depois/11136.jpeg', N'A INSTALAÇÃO DO PORTÃO ELIMINA UMA CONDIÇÃO INSEGURA AO IMPEDIR O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS SUSPENSAS, REDUZINDO SIGNIFICATIVAMENTE O RISCO DE ACIDENTES. ALÉM DISSO, FORTALECE O CONTROLE DA ÁREA, ATENDENDO ÁS BOAS PRÁTICAS DE SEGURANÇA OPERACIONAL E PRESERVANDO A INTEGRIDADE FÍSICA DOS TRABALHADORES.', NULL, N'A ÁREA DA PONTE NÃO NÃO POSSUÍA PORTÃO DE ISOLAMENTO, PERMITINDO O ACESSO DE PESSOAS DURANTE O RECEBIMENTO DE MATERIAL, COM A INSTALAÇÃO DO PORTÃO, O ACESSO PASSOU A SER CONTROLADO E Á ÁREA FICOU DEVIDAMENTE ISOLADA DURANTE  AS OPERAÇÕES DE IÇAMENTO, A MELHORIA ATENDEU Á META ESTABELECIDA, REDUZIDO A EXPOSIÇÃO AOS RISCOS, AUMENTANDO A SEGURANÇA DOS COLABORADORES E PROPORCIONANDO MAIOR CONTROLE.', N'A IDENTIFICAÇÃO E ELIMINAÇÃO DE CONDIÇÕES INSEGURAS ANTES DA EXECUÇÃO DAS ATIVIDADES REDUZEM SIGNIFICAMENTE OS RISCOS DE ACIDENTES ', 0, NULL, N'Risk of process upset requiring manual intervention and downtime is reduced.', '2026-07-09T00:00:00.000', '2026-07-12T17:56:20.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (11137, N'81037761', N'516643', N'Disponibilização da corrente do alimentadores da Pilha Primária Salobo III na tela do Supervisório', 1, N'No Replication/Sem replicação', N'Atualmente, a tela do supervisório não apresenta a corrente dos alimentadores da Pilha Primária Salobo III, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos técnicos de sala de controle.', N'Visualização rápida da corrente dos alimentadores da Pilha Primária Salobo III', N'10025', N'01 - Imagens/01 - Antes/11137.jpeg', N'A tela do supervisório do Circuito de Britagem Primária Salobo III não apresenta a corrente dos alimentadores, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos operadores.', N'01 - Imagens/02 - Depois/11137.jpeg', N'Foi incluída na tela do supervisório a indicação da corrente dos alimentadores da Pilha Primária Salobo III, proporcionando ao técnico de Sala de Controle maior visibilidade das condições operacionais permitindo uma análise mais rápida e eficiente da operação pelos técnicos.', NULL, N'Com a indicação da corrente dos alimentadores da Pilha Primária Salobo III, o técnico de sala de controle tem maior visibilidade das condições operacionais permitindo uma análise mais rápida e eficiente da operação pelos técnicos.', N'Contribuir para a identificação de oportunidades de melhoria e favorecendo análises mais assertivas e tomadas de decisão mais ágeis.', 0, NULL, N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, proporcionando melhor acompanhamento, integração e comunicação entre os colaboradores. Desta forma, as pessoas conseguem identificar os colaboradores novatos em nossas operações. ', '2026-07-06T00:00:00.000', '2026-07-13T00:36:18.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11138, N'81062454', N'81062454', N'wire for deflector plate', 1, N'Others/Outros', N'deflector plate wasn''t secured so it could fall into the bin i fdropped', N'secure so it can not be dropped', N'10271', N'01 - Imagens/01 - Antes/11138.jpeg', N'plate not secured', N'01 - Imagens/02 - Depois/11138.jpeg', N'used wire to attach plate', NULL, N'wire stops plate from being able to be dropped', N'plate can''t be dropped into bin', 0, NULL, N'Aumento da confiabilidade das informações', '2026-07-12T00:00:00.000', '2026-07-13T02:35:00.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11139, N'1010605', N'1010605', N'Fan for feed bin whipping', 2, N'Others/Outros', N'During the summer months the bin whip location is to warm to be staying up at for long periods of time. The area is 8+ stories up and requires full PPE, so is very warm even during the winter months.', N'Reduce heat exhaustion at bin whip controls', N'10271', N'01 - Imagens/01 - Antes/11139.jpeg', N'Area is very hot, especially during summer. No nearby areas to cool down.', N'01 - Imagens/02 - Depois/11139.jpeg', N'Large fan added to keep heat at bay.', NULL, N'YES, area is much more reasonable to be in for extended periods of time.', N'We need more fans', 0, NULL, NULL, '2026-07-12T00:00:00.000', '2026-07-13T02:35:31.000', N'1010605', NULL, NULL);
INSERT INTO #PVC VALUES (11140, N'81062454', N'81062454', N'mounting hose rack', 1, N'Others/Outros', N'previous mount kept detaching from wall', N'to keep mount from detaching from wall', N'10271', N'01 - Imagens/01 - Antes/11140.jpeg', N'mount was installed with self tapping screws which over time would pull out of wall', N'01 - Imagens/02 - Depois/11140.jpeg', N'mount was secured with bolt and nut', NULL, N'bolt and nut can''t detach from wall', N'bolt works better then screw', 0, NULL, N'Better housekeeping, knowing where items are stored that are currently not in use', '2026-07-12T00:00:00.000', '2026-07-13T02:43:30.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11141, N'81062454', N'81062454', N'marker holder', 1, N'No Replication/Sem replicação', N'nowhere to put markers', N'have markers in good location for use', N'10271', N'01 - Imagens/01 - Antes/11141.jpeg', N'no holder for markers', N'01 - Imagens/02 - Depois/11141.jpeg', N'holder now in spot where they are needed', NULL, N'markers will be where needed', N'markers are easier to find when in holder', 0, NULL, NULL, '2026-07-12T00:00:00.000', '2026-07-13T02:51:14.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11142, N'81037761', N'516643', N'Disponibilização da corrente do alimentadores da Secundária Salobo III na tela do Supervisório', 1, N'No Replication/Sem replicação', N'A tela do supervisório do Circuito de Britagem Secundária Salobo III não apresenta a corrente dos alimentadores da Pilha Secundária, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos operadores.
INSERT INTO #PVC VALUES (11143, N'496936', N'496936', N'Barra distribuidora de ar comprimido ', 2, N'Others/Outros', N'A limpeza de pó na área da Calcinação e Forno Redução é realizada utilizando um equipamento confeccionado em cano de PVC com apenas uma saída de ar comprimido. No entanto ha uma baixa eficiência de limpeza, pois apenas uma saída de ar cobre uma pequena área por vez, ocasionando maior esforço físico e ergonômico do operador, devido à necessidade de movimentar continuamente,', N'Projetar e implementar uma Barra Distribuidora de Ar Comprimido em PVC com saídas de ar estrategicamente distribuídas e duas rodinhas de apoio na barra horizontal, permitindo o deslocamento suave sobre o piso. A barra distribuidora tem como finalidade remover poeira, acúmulo finos de minério e outros resíduos de áreas industriais, reduzindo o tempo de limpeza, o consumo de ar comprimido e a exposição dos colaboradores a riscos ergonômicos e operacionais.', N'10049', N'01 - Imagens/01 - Antes/11143.jpeg', N'Atualmente, a limpeza de pó na área da Calcinação e Forno Redução é realizada utilizando um equipamento confeccionado em cano de PVC com apenas uma saída de ar comprimido. O operador direciona o jato de ar manualmente sobre o piso para remover o material particulado acumulado.
INSERT INTO #PVC VALUES (11144, N'81022574', N'81022574', N'Melhoria na Detecção de Falhas da TR-2305SA-04 através de Alarme na Sala de Controle', 1, N'Others/Outros', N'Anteriormente, quando a TR-2305SA-04 parava, a informação permanecia em uma área da tela da sala de controle com pouca visibilidade, dificultando a percepção imediata do evento pelo técnico. Como resultado, o equipamento frequentemente permanecia parado por períodos prolongados até que a condição fosse identificada e tratada, gerando impactos na operação.', N'Que o Tecnico de sala consiga visualizar de forma rapida a parada da TR-2305SA-04', N'10051', N'01 - Imagens/01 - Antes/11144.jpeg', N'Anteriormente, quando a TR-2305SA-04 parava, a informação permanecia em uma área da tela da sala de controle com pouca visibilidade, dificultando a percepção imediata do evento pelo técnico. Como resultado, o equipamento frequentemente permanecia parado por períodos prolongados até que a condição fosse identificada e tratada, gerando impactos na operação.', N'01 - Imagens/02 - Depois/11144.jpeg', N'Para eliminar essa dificuldade, foi desenvolvida em conjunto com a equipe de Automação uma lógica de alarme que exibe uma falha de forma destacada na tela da sala de controle sempre que a TR-2305SA-04 é interrompida. Com essa melhoria, o técnico passa a ter visibilidade imediata da ocorrência, podendo acionar rapidamente o operador de área e solicitar apoio com maior prontidão. Essa ação reduz significativamente o tempo de resposta, diminui o tempo de parada do equipamento e aumenta a confiabilidade operacional do sistema de refugo de bolas dos moinhos.', NULL, N'Sim, pois conseguimos melhorar a prontidão operacional devido o técnico de sala ter visibilidade rápida da falha quando a TR-2305SA-04 para', N'Melhoria no processo', 0, NULL, N'Atendimento ao requisito do procedimento operacional.
INSERT INTO #PVC VALUES (11145, N'87000312', N'87000312', N'Reducing CO2 emissions through the introduction of EV trucks', 1, N'Others/Outros', N'Using petrol car was exhausting a lot of CO2', N'Reduction of CO2 emissions', N'0', N'01 - Imagens/01 - Antes/11145.jpeg', N'All the company car was petrol car. Using petrol car was exhausting a lot of CO2', N'01 - Imagens/02 - Depois/11145.jpeg', N'One of the company car changed from petrol car to EV car. As a result, CO2 emission could be reduced.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'O resultado alcançado é maior acompanhamento do sistema Dynamox com gestão a vista podemos acompanhar através de gráficos no Bi ', '2026-07-12T00:00:00.000', '2026-07-13T07:24:34.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11146, N'549252', N'549252', N'Dashboard Automatizado para Gestão de Ocorrências de Manutenção da Frota', 1, N'Others/Outros', N'A ausência de uma ferramenta automatizada para análise das ocorrências de manutenção gerava retrabalho na consolidação dos dados, dificultava o monitoramento dos indicadores de desempenho da frota e limitava a rapidez na identificação de desvios e oportunidades de melhoria.', N'Reduzir o esforço manual no tratamento de dados de manutenção, disponibilizando indicadores em tempo real por meio de dashboard automatizado, aumentando a produtividade da equipe e a qualidade das análises operacionais.', N'10171', N'01 - Imagens/01 - Antes/11146.jpeg', N'O controle das ocorrências de manutenção era realizado por meio de uma planilha básica, com baixa padronização e limitada capacidade de análise. A consolidação das informações era realizada manualmente, demandando tempo para atualização dos dados e elaboração de relatórios. A ausência de indicadores automáticos e painéis gerenciais dificultava a identificação rápida dos principais desvios, equipamentos com maior recorrência de falhas e tendências das ocorrências de manutenção, aumentando o esforço operacional e o risco de inconsistências nas análises.', N'01 - Imagens/02 - Depois/11146.jpeg', N'Foi desenvolvida uma nova estrutura de banco de dados padronizada e um dashboard automatizado para monitoramento das ocorrências de manutenção da frota. A solução permite a atualização rápida das informações e a geração automática de indicadores estratégicos, como quantidade de ocorrências, equipamentos com mais paradas, distribuição por tipo de ocorrência, responsáveis e tendências mensais. A melhoria reduziu atividades manuais, aumentou a confiabilidade dos dados, trouxe maior agilidade na geração de relatórios e forneceu suporte mais eficiente para a tomada de decisão da gestão de manutenção.', NULL, N'SIM. O problema foi mitigado por meio da criação de uma nova estrutura de banco de dados e de um dashboard automatizado. A solução eliminou grande parte do trabalho manual de consolidação e análise das informações, proporcionando maior agilidade na geração de relatórios, aumento da confiabilidade dos dados e melhor acompanhamento dos indicadores de manutenção.', N'Automação e padronização de dados aumentam significativamente a confiabilidade das informações, reduzem retrabalhos e permitem maior agilidade na geração de indicadores para tomada de decisão.', 0, NULL, N'aumento da segurança operacional e redução do risco químico,
INSERT INTO #PVC VALUES (11147, N'544481', N'544481', N'PROTETOR DE FOICE ', 2, N'Others/Outros', N'As foices eram transportadas e armazenadas sem proteção na lâmina, ficando expostas. Isso gerava risco elevado de cortes durante o manuseio, transporte e deslocamento da equipe, além de maior desgaste da lâmina por contato com outras superfícies.', N'Aumentar a segurança dos colaboradores durante o transporte e armazenamento da foice, prevenindo acidentes com cortes, além de garantir melhor conservação da lâmina.', N'10017', N'01 - Imagens/01 - Antes/11147.jpeg', N'As foices eram transportadas e armazenadas sem proteção na lâmina, expondo trabalhadores a cortes durante o manuseio e deslocamento, além de acelerar o desgaste do equipamento.', N'01 - Imagens/02 - Depois/11147.jpeg', N'Foi implantado protetor de lâmina para foice, reduzindo riscos de acidentes no transporte e armazenamento, aumentando a segurança dos colaboradores e a vida útil da ferramenta.', NULL, N'SIM, Foi implantado o uso de protetor de lâmina para foice, confeccionado com material resistente e de fácil encaixe. Com isso, a lâmina permanece protegida durante o transporte e armazenamento, reduzindo significativamente o risco de acidentes, melhorando a segurança dos colaboradores e aumentando a vida útil da ferramenta.', N'Segurança', 0, NULL, N'Maior disponibilidade dos canhões de lavagem.
INSERT INTO #PVC VALUES (11148, N'544481', N'544481', N'SUPORTE PARA LAVA OLHOS PORTÁTIL  ', 2, N'Others/Outros', N'O lava-olhos portátil ficava armazenado em locais improvisados ou sem identificação com dificuldade de acesso rápido em situações de emergência. ', N'Garantir 100% de disponibilidade e acesso rápido ao lava-olhos portátil em áreas com risco de contato químico, promovendo organização, padronização e segurança operacional.', N'10017', N'01 - Imagens/01 - Antes/11148.jpeg', N' O lava-olhos portátil ficava armazenado em locais improvisados ou sem identificação com dificuldade de acesso rápido em situações de emergência. ', N'01 - Imagens/02 - Depois/11148.jpeg', N'Foi implantado protetor de lâmina para foice, reduzindo riscos de acidentes no transporte e armazenamento, aumentando a segurança dos colaboradores e a vida útil da ferramenta.', NULL, N'Foi Implantado um  suporte fixo e identificado para armazenamento do lava-olhos portátil, o equipamento fica  posicionado em local estratégico e de fácil acesso.
INSERT INTO #PVC VALUES (11149, N'1010304', N'1010304', N'Change 150-CVF-001 vibrator timing', 1, N'Crusher/Britadeira', N'Vibrator timing sequence was a fixed interval, ~20 minutes between cycles. This led to buildup and potential plugging of the grizzly and belt area. CRT were running vibrators in manual mode for more frequent cycles.', N'Improve circuit performance, reduce plugging', N'0', N'01 - Imagens/01 - Antes/11149.jpeg', N'Vibrator timing sequence was a fixed interval, ~15 minutes between cycles. The timing could mean that, at higher production rates (46tph and higher), there was potential for multiple buckets to be dumped into the grizzly in between vibrator cycles. This led to buildup and potential plugging of the grizzly and belt area. CRT were running vibrators in manual mode for more frequent cycles.', N'01 - Imagens/02 - Depois/11149.jpeg', N'Suggested tying vibrator cycle interval to match bucket timing number that is entered by CRTs.
INSERT INTO #PVC VALUES (11150, N'544481', N'544481', N'ABRAÇADEIRA PADRINHO/AFILHADO ', 1, N'Others/Outros', N'Não havia identificação visual entre padrinhos e afilhados, dificultando o acompanhamento e a integração dos colaboradores nas atividades operacionais. Os colaboradores antigos não identificavam os colaboradores recente na área. A apresentação dos mesmo, eram feitas através de DSS. ', N'Fortalecer a cultura de segurança e a integração entre colaboradores através do programa “Padrinho e Afilhado.', N'10017', N'01 - Imagens/01 - Antes/11150.jpeg', N'Não havia identificação visual entre padrinhos e afilhados, dificultando a integração e o acompanhamento. Colaboradores experientes não identificavam facilmente os recém-chegados à área.', N'01 - Imagens/02 - Depois/11150.jpeg', N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, facilitando a identificação dos novatos e melhorando a integração, comunicação e acompanhamento.', NULL, N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, proporcionando melhor acompanhamento, integração e comunicação entre os colaboradores. Desta forma, as pessoas conseguem identificar os colaboradores novatos em nossas operações. ', N'Acompanhamento -identificação', 0, NULL, N'Maior rastreabilidade do material limonítico segregado.', '2026-06-02T00:00:00.000', '2026-07-13T11:14:27.000', N'544481', NULL, NULL);
INSERT INTO #PVC VALUES (11151, N'81006667', N'81006667', N'Power Bi de Treinamentos', 1, N'Others/Outros', N'Antes tinha um power bi de treinamentos, porém com a mudança de sistema do RH houve uma atualização na base de relatórios tornando o bi que existia ineficaz. ', N'Criar Bi de treinamentos para gerência', N'10054', N'01 - Imagens/01 - Antes/11151.jpeg', N'Existia um painel Power BI para acompanhamento dos treinamentos dos colaboradores. Entretanto, após a mudança do sistema de RH, houve atualização na estrutura e na base de dados dos relatórios, tornando o dashboard existente obsoleto e ineficaz para o monitoramento das informações de treinamento.', N'01 - Imagens/02 - Depois/11151.jpeg', N'Foi criado um novo Power BI integrado à base de dados atual do sistema de RH, permitindo o acompanhamento eficiente dos treinamentos dos colaboradores. A ferramenta trouxe maior confiabilidade das informações, atualização automática dos dados e melhor gestão das capacitações.', NULL, N'A meta foi alcançada com a criação de um novo painel, permitindo novamente o acompanhamento eficiente e atualizado dos treinamentos dos colaboradores.', N'manter os relatórios e dashboards alinhados às mudanças dos sistemas corporativos', 0, NULL, N'Maior segurança para os colaboradores e seus pertences;
INSERT INTO #PVC VALUES (11152, N'81057857', N'81057857', N'Auto Lubber Upgrade, Filter Press 4', 1, N'Refining/Refino', N'issue - grease system was not providing adequate grease to bearings.
INSERT INTO #PVC VALUES (11153, N'1008370', N'1008370', N'Salt bucket storage', 1, N'Others/Outros', N'POL storage room was messy, unorganized and not meeting 5S standards ', N'Organization', N'0', N'01 - Imagens/01 - Antes/11153.jpeg', N'Clutter, items stored overhead, no organization.', N'01 - Imagens/02 - Depois/11153.jpeg', N'All items reorganized and overhead storage removed.
INSERT INTO #PVC VALUES (11154, N'503436', N'503436', N'MONITORAMENTO DE TEMPERATURA DOS ACUMULADORES DE FREIO DE PISTÃO', 1, N'Others/Outros', N'Foi realizada a instalação de sensores de temperatura Dynamox no acumulador de freio do caminhão Komatsu 830E, com o objetivo de monitorar continuamente a condição operacional do componente. Durante o acompanhamento dos dados, foi identificada uma elevação da temperatura no acumulador, condição diretamente relacionada ao aumento da pressão do gás em seu interior. Quando o sensor Dynamox através do gráfico de tendência apresenta dados de criticidade alta podemos identificar na tela do CMA da mina condições anormais nos pistões e evitar falha na direção do equipamento com paradas não planejadas.', N'MONITORAR TEMPERATURAS ELEVADAS DOS ACUMULADORES DE FREIO DE PISTÃO', N'10024', N'01 - Imagens/01 - Antes/11154.jpeg', N'Os acumuladores de freio de pistão do caminhão Komatsu 830 E apresentaram altas temperaturas e paradas não planejadas em corretiva devido ao endurecimento do volante da direção do operador na mina. Condição essa devido a vazamentos dentro do componente e alta temperatura e sem condições de operação em mina para movimentar o equipamento.', N'01 - Imagens/02 - Depois/11154.jpeg', N'Através da instalação dos sensores de temperatura Dynamox TC Ag nos acumuladores de freio de pistão, é possível monitorar continuamente a evolução da temperatura desses componentes. O sistema permite a configuração de parâmetros de alerta e criticidade, gerando alarmes automáticos quando são identificadas elevações anormais de temperatura. Além disso, os dados podem ser visualizados no CMA da mina, possibilitando o acompanhamento da condição do equipamento e a emissão de laudos técnicos que subsidiem a programação de paradas planejadas para inspeção e manutenção, reduzindo o risco de falhas e aumentando a confiabilidade operacional.', NULL, N'Antes da implantação dos sensores Dynamox TC Ag, as falhas nos acumuladores de direção e freio eram identificadas apenas após a manifestação de sintomas, como aumento excessivo da temperatura, enrijecimento da direção e paradas não planejadas. Após a instalação dos sensores, tornou-se possível acompanhar a evolução da temperatura em tempo real por meio dos gráficos de tendência disponíveis no CMA da mina, permitindo a emissão de alertas preventivos e a programação de paradas planejadas para manutenção, mitigando riscos operacionais e aumentando a confiabilidade dos ativos.', N'Monitoramento online', 25300, 1, N'Aumento da segurança para motoristas e pedestres;
INSERT INTO #PVC VALUES (11155, N'544481', N'544481', N'CHECKLIST DE INSPEÇÃO – ROÇO MECANIZADO', 2, N'Others/Outros', N'As atividades de roço mecanizado eram iniciadas sem um padrão definido de inspeção da área e controle de projeção de materiais. Havia risco de lançamento de pedras, galhos e resíduos durante a operação da roçadeira, além da ausência de isolamento adequado e controle de acesso de pessoas e veículos na área operacional.', N'Padronizar a inspeção das atividades de roço mecanizado, garantindo o controle dos riscos relacionados à projeção de materiais, isolamento da área e segurança dos empregados, prevenindo acidentes com pessoas, veículos e equipamentos.', N'10017', N'01 - Imagens/01 - Antes/11155.jpeg', N'As atividades de roço mecanizado eram realizadas sem padrão de inspeção e isolamento da área, aumentando o risco de projeção de materiais e exposição de pessoas e veículos.', N'01 - Imagens/02 - Depois/11155.jpeg', N'Foi implantado checklist visual para roço mecanizado, assegurando inspeção da área, isolamento, uso de EPIs e controle de riscos, aumentando a segurança e prevenindo acidentes. ', NULL, N'Foi implantado um checklist visual de inspeção para as atividades de roço mecanizado, garantindo a verificação do isolamento da área, uso correto de EPIs, inspeção dos equipamentos e controle dos riscos de projeção de materiais. A melhoria proporcionou mais segurança operacional, maior percepção de risco e prevenção de acidentes durante as atividades.', N'Padronização', 0, NULL, NULL, '2026-05-21T00:00:00.000', '2026-07-13T13:12:02.000', N'544481', NULL, NULL);
INSERT INTO #PVC VALUES (11156, N'1008370', N'1008370', N'222 line labelling', 1, N'Others/Outros', N'Upcoming line cleaning for building 222. Pipes in pipe rack not labelled and can be confusing. Maintenance and ops both unfamiliar with overhead lines in pipe rack', N'Visual aid for techs, maintenance and work parties', N'0', N'01 - Imagens/01 - Antes/11156.jpeg', N'Many lines running through 222 pipe rack, none of which are labelled. With upcoming cleaning of many of these lines, it would be a benefit to have them easy to identify by all work parties', N'01 - Imagens/02 - Depois/11156.jpeg', N'Line labelled in area that can clearly be seen. This will help all working parties, Ops, Maintenance and Clean Harbors to be able to identify lines more efficiently.', NULL, N'Yes, line is labelled which will provide a positive impact going forward', N'Labelled lines make overall work easier/more efficient', 0, NULL, N'Proactive identification of potential issues, savings and efficiencies in hosting ecosystem in a consistent and predictable manner ', '2026-07-10T00:00:00.000', '2026-07-13T13:13:38.000', N'1008370', NULL, NULL);
INSERT INTO #PVC VALUES (11157, N'81042078', N'81042078', N'IMPLANTAÇÃO DE DISPOSITIVO NIVELADOR PARA PADRONIZAÇÃO DA ALTURA DAS AMOSTRAS NA DETERMINAÇÃO DE UMIDADE', 1, N'Others/Outros', N'Na etapa de preparação das amostras para determinação de umidade, prevista no PRO-004262, não existia uma ferramenta que garantisse o atendimento ao requisito de altura máxima de 30 mm da camada de material. O nivelamento era realizado visualmente, favorecendo a formação de “camelos” e de camadas irregulares, comprometendo a uniformidade da secagem, aumentando a variabilidade do processo e reduzindo a confiabilidade dos resultados analíticos.
INSERT INTO #PVC VALUES (11158, N'503436', N'503436', N'MONITORAMENTO DE INSTAÇÃO DE GATEWAYS FROTA TRANSPORTE', 1, N'No Replication/Sem replicação', N'O controle de instalação das gateways da frota transporte são monitoradas através de uma planilha de Excel em pastas aleatórias sem visão geral de como está o andamento do comissionamento das gateways com gestão a vista.  ', N'Acompanhar o monitoramento de instalação através de um farol de Bi e no CMA', N'10024', N'01 - Imagens/01 - Antes/11158.jpeg', N' Sobre o comissionamento das gateways Dynamox o controle era realizado através de planilha de Excel e no grupo de WhatsApp sobre o andamento das instalações com pouca visibilidade para as equipes de inspeção de campo e CMA. ', N'01 - Imagens/02 - Depois/11158.jpeg', N'Após a criação do Bi de farol de controle de instalação de sensores Dynamox e gateways nos equipamentos através da alimentação de informações, conseguimos enviar os dados para o CMA e através da tela de gestão a vista podemos acompanhar através de gráficos e condições de alarmes o andamento da instalação das gateways.', NULL, N'Anteriormente não havia condição de acompanharmos o monitoramento desses ativos quanto á instalação somente através de planilhas e no WhatsApp celular, após a criação de um Bi para controle do comissionamento de instalação das gateways, conseguimos acompanhar o comissionamento com dados e eventos nas telas do CMA.', N'Monitoramento com gestão a vista', 0, NULL, N'Redução de pessoas em campo operacional.
INSERT INTO #PVC VALUES (11159, N'81058966', N'81038717', N'BQ-2022-191 – Melhoria nas tubulações de recalque e sucção.', 1, N'Others/Outros', N' As tubulações de sucção e recalque eram feitas em PEAD rígido, e suas curvas e soldas, com o passar do tempo, ressecavam devido à ação do produto químico transportado pelo sistema, ocasionando frequentes vazamentos.', N'ubstituir as tubulações rígidas por tubulações flexíveis e mais resistentes ao produto químico, aumentando a confiabilidade do sistema e reduzindo os vazamentos.', N'10031', N'01 - Imagens/01 - Antes/11159.jpeg', N' Existia muita contaminação na baia devido ao excesso de vazamentos provenientes das tubulações dos equipamentos.', N'01 - Imagens/02 - Depois/11159.jpeg', N'As tubulações foram substituídas por modelos flexíveis, mais resistentes aos produtos químicos e com maior vida útil.', NULL, N'sim, redução dos vazamentos nas tubulações, eliminação da contaminação frequente na baia das BQ’s', N'Melhorias de processo contribuem diretamente para segurança, confiabilidade operacional e aumento da vida útil dos equipamentos.', 0, NULL, N'Monthly carbon output reduced >50% from 2025 in VBM Azure subscriptions from 757kgCO2e to 362kgCO2e', '2026-07-08T00:00:00.000', '2026-07-13T17:07:21.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11160, N'81058966', N'81038855', N'Adequação da tubulação dos canhões de limpeza da baia da CX-2057-06', 1, N'Others/Outros', N'Durante o translado da CX-2057-06, foi identificado um grande acúmulo de material concentrado na baia, com potencial de ser direcionado ao sump. Entretanto, devido às falhas recorrentes na tubulação de alimentação dos canhões de lavagem, o equipamento permanecia indisponível, impossibilitando a limpeza eficiente da baia e a recuperação do material para retorno ao circuito de processo.', N'Aumentar a vida útil da tubulação dos canhões de lavagem. Eliminar vazamentos de água. Garantir a disponibilidade dos canhões de limpeza. Melhorar a organização, limpeza e segurança da área. Reduzir perdas operacionais por acúmulo de material.', N'10031', N'01 - Imagens/01 - Antes/11160.jpeg', N'Durante o translado da CX-2057-06, verificou-se grande acúmulo de material concentrado na baia. Os caminhões de lavagem, responsáveis por  esse material ao sump para retorno ao processo, encontravam-se frequentemente indisponíveis devido a falhas na tubulação de alimentação.', N'01 - Imagens/02 - Depois/11160.jpeg', N'Foi fabricado e instalado um novo trecho de tubulação, substituindo o percurso subterrâneo por uma tubulação externa e de fácil acesso para inspeções e manutenções. ', NULL, N'sim,Aumento da vida útil da tubulação.
INSERT INTO #PVC VALUES (11161, N'81045248', N'1009268', N'Ball Valve for water lance ', 1, N'Concentration/Concentração', N'to clean the Ball Mill Discharge tank it can be full of solids. It can be difficult to get the concentrate to drain out of the tank.
INSERT INTO #PVC VALUES (11162, N'81045248', N'1010297', N'Workbench ', 3, N'Others/Outros', N'Our workbench is made of wood and is falling apart. It is difficult to keep clean', N'create sturdy, clean workbench', N'0', N'01 - Imagens/01 - Antes/11162.jpeg', N'we spray down this area so the wood is getting wet multiple times a shift.
INSERT INTO #PVC VALUES (11163, N'81029574', N'81029574', N'Criação da nomenclatura LR (Limonita Rica) para segregação e controle de estoque de minério', 1, N'Open Pit/Poço aberto', N'Anteriormente, a segregação dos estoques de limonita era realizada apenas com base nas características físicas observadas em campo. Esse método não permitia distinguir de forma clara os materiais com maior teor de níquel na zona limonítica. A ausência de parametrização e de uma nomenclatura padronizada dificultava a rastreabilidade da origem do material, podendo ocasionar a mistura de minérios com diferentes qualidades e comprometendo a confiabilidade do controle de estoque e do direcionamento do material para o processo.
INSERT INTO #PVC VALUES (11164, N'81020607', N'547536', N'Armários com leitor de crachá', 3, N'Others/Outros', N'Os armários disponíveis na área apresentavam condições inadequadas de utilização e não possuíam sistema de segurança para controle de acesso.', N'Melhoria Continua ', N'10139', N'01 - Imagens/01 - Antes/11164.jpeg', N'Os armários disponíveis na área não eram adequados às necessidades operacionais e não possuíam mecanismos de segurança para controle de acesso.', N'01 - Imagens/02 - Depois/11164.jpeg', N'Foi realizada a aquisição e instalação de novos armários com sistema de abertura por leitura de crachá, proporcionando maior segurança no armazenamento de pertences, modernização da área e melhoria das condições de organização e controle de acesso.', NULL, N'Maior segurança para os colaboradores e seus pertences;
INSERT INTO #PVC VALUES (11165, N'201675', N'201675', N'Tech Obsolesence Elimination and Cost Reduction', 1, N'Projects/Projetos', N'Expensive and obsolete technology assets using costly service models ', N'Reduce cost and support risk through replacement of obsolete assets with vale owned equiptment', N'0', N'01 - Imagens/01 - Antes/11165.jpeg', N'-high ongoing cost for obsolete 3rd party owned equipment
INSERT INTO #PVC VALUES (11166, N'81020607', N'547536', N'Instalação de Base Estrutural para Armários', 3, N'Others/Outros', N'Os armários ficavam apoiados diretamente no piso, tornando-os mais suscetíveis ao desgaste prematuro e à deterioração causada pelas condições do ambiente.', N'Melhoria Continua', N'10139', N'01 - Imagens/01 - Antes/11166.jpeg', N'Os armários permaneciam diretamente apoiados no chão, ficando expostos à umidade, sujeira e possíveis impactos, o que poderia acelerar o desgaste da estrutura, comprometer sua conservação e dificultar a limpeza e organização da área.', N'01 - Imagens/02 - Depois/11166.jpeg', N'Foi realizada a confecção e instalação de uma base estrutural para os armários, elevando-os do piso e proporcionando maior proteção, estabilidade e melhor conservação dos equipamentos.', NULL, N'A instalação da base estrutural elevou o padrão de conservação dos armários, reduzindo riscos de deterioração, aumentando sua vida útil e contribuindo para um ambiente mais organizado e seguro.', N'Qualidade e produtividade no processo', 0, NULL, N'Redução de 25% da mão de obra necessária na atividade;
INSERT INTO #PVC VALUES (11167, N'81020607', N'547536', N'Implantação de Sinalização para Entrada e Saída de Veículos', 1, N'Others/Outros', N'A área não possuía um sistema de sinalização para controlar a entrada e saída de veículos, o que dificultava a orientação dos condutores, aumentava o risco de conflitos de tráfego e comprometia as condições de segurança operacional.', N'Melhoria Continua', N'10139', N'01 - Imagens/01 - Antes/11167.jpeg', N'Não havia sinalização para entrada e saída de veículos, dificultando a orientação dos condutores e o controle do fluxo de tráfego na área, aumentando o risco de incidentes e manobras inadequadas.', N'01 - Imagens/02 - Depois/11167.jpeg', N'Foi realizada a aquisição e instalação de um semáforo para controle da entrada e saída de veículos, proporcionando maior visibilidade, organização do fluxo de tráfego e reforço das condições de segurança na área.', NULL, N'A implantação do semáforo trouxe mais segurança e controle para a circulação de veículos, reduzindo riscos operacionais, melhorando a organização do tráfego e proporcionando maior confiabilidade nas movimentações da área.', N'Segurança e qualidade no processo', 0, NULL, N'organização e armazenamento adequado de ferramentas de limpeza, substituindo o acondicionamento desorganizado no canto por um suporte fixo para ferramentas', '2026-07-08T00:00:00.000', '2026-07-14T11:34:36.000', N'81020607', NULL, NULL);
INSERT INTO #PVC VALUES (11168, N'201675', N'201675', N'Exit Markham Datacenter facility ', 1, N'No Replication/Sem replicação', N'Markham datacenter managed facility no longer required and used as originally intended for disaster recovery purposes.  Continued use resulting in unnecessary cost and environment complexity ', N'Eliminate or migrate all hosting equiptment and applications from Markham to eliminate need for datacenter ', N'0', N'01 - Imagens/01 - Antes/11168.jpeg', N'>30 applications/services, ~8 hosting equipment assets in Markham datacenter resulting in >$5K/month in facility costs 
INSERT INTO #PVC VALUES (11169, N'201675', N'81031520', N'On-Premises & Cloud Hosting Observability Excellence', 3, N'Others/Outros', N'-missing proactive routines to regularly check on-premises and cloud services for health, security, and performance issues/risks
INSERT INTO #PVC VALUES (11170, N'201675', N'200363', N'VBM peer review routine for billing cost validation', 1, N'Others/Outros', N'Historical responsibility for dxc billing cost review and approval performed by VSA without due dilligence/peer review by VBM team members.  Difficulty toi ensure accuracey and thoroughness of billing file review due to size and global scope without regional assesstment ', N'Cost control, billing accuracey, waste reduction ', N'0', N'01 - Imagens/01 - Antes/11170.jpeg', N'-Monthly DXC billing file for hosting costs review centralized by VSA team without peer review/feedback from VBM 
INSERT INTO #PVC VALUES (11171, N'81012715', N'81012715', N'Otimização das atividade de campo do CMA.', 1, N'Others/Outros', N'Ausência de um processo padronizado para disponibilização das listas de coleta e instalação, resultando em perda de tempo, retrabalho e baixa produtividade nas atividades de campo.', N'Aumentar a produtividade da equipe por meio de padronização de listas.', N'10362', N'01 - Imagens/01 - Antes/11171.jpeg', N'Antes da implantação do Kaizen, não existia um método padronizado para disponibilizar as listas de coleta e instalação. Cada colaborador gerava suas próprias listas, utilizando procedimentos distintos, o que consumia tempo, gerava retrabalho, dificultava o acompanhamento das pendências e reduzia a produtividade das atividades em campo.', N'01 - Imagens/02 - Depois/11171.jpeg', N'Foram inseridas planilhas padronizadas de coleta e instalação nos três tablets da equipe de CMA, garantindo que todos os colaboradores utilizem a mesma base de informações, sempre atualizada. As listas permitem marcar as atividades concluídas e manter visíveis apenas as pendências, facilitando a execução das tarefas em campo. A melhoria reduziu o tempo de preparação das atividades, eliminou retrabalho, padronizou o processo e aumentou a produtividade, a organização e a eficiência da equipe.', NULL, N'Meta alcançada e retrabalho reduzido. Redução das visitas à campo ao mesmo equipamento e redução de pessoas em área operacional gerando mais segurança.', N'Ferramentas simples, quando bem organizadas, geram banhos significantes de produtividade.', 0, NULL, N'Risco zero de acidentes por partes móveis.', '2026-07-13T00:00:00.000', '2026-07-14T12:53:31.000', N'81012715', NULL, NULL);
INSERT INTO #PVC VALUES (11172, N'201675', N'201675', N'Cloud Carbon Reduction ', 1, N'Projects/Projetos', N'Unnecessary carbon output from overprovisioned or unused cloud assets from applications/services in MS Azure', N'Reduce carbon emissions from Azure services ', N'0', N'01 - Imagens/01 - Antes/11172.jpeg', N'-significant number of workloads in Azure cloud no longer required or are oversized for current usage, resulting in excessive carbon emissions and cost ', N'01 - Imagens/02 - Depois/11172.jpeg', N'Established ongoing cadence to review cloud consumption, implemented budgets and other monitors in Azure to improve visibility and proactive routines to analyze performance and efficiency 
INSERT INTO #PVC VALUES (11173, N'81048127', N'81048127', N'Safety Shower', 1, N'Refining/Refino', N'Safety showers continue leaking after testing', N'Less Mess', N'0', N'01 - Imagens/01 - Antes/11173.jpeg', N'Safety showers leaking after testing.', N'01 - Imagens/02 - Depois/11173.jpeg', N'I found that the handle needed to be tightened so when you push the handle all the way it closes the valve all the way', NULL, N'Yes, water stops when you function the handle all the way closed. Before it was hitting the stop and not fully closing.', N'over time and usage the handles wear', 0, NULL, N'Melhoria na organização e padronização da área de trabalho;
INSERT INTO #PVC VALUES (11174, N'201675', N'201986', N'OT Email Relay Reliability Improvements', 2, N'Others/Outros', N'Unreliable email notification service used in Port Colborne impacting safe operations
INSERT INTO #PVC VALUES (11175, N'553135', N'81019440', N'SUPORTE DO FAROL FRONTAL TT-85', 2, N'Others/Outros', N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'DEIXAR A ATIVIDADE MAIS SEGURA, E DAR DURABILIDADE PARA O FAROL', N'10139', N'01 - Imagens/01 - Antes/11175.jpeg', N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'01 - Imagens/02 - Depois/11175.jpeg', N'FOI CONSTRUIDO UM SUPORTE NA OFICINA COM RECURSOS PROPRIOS, GERANDO FACILIDADE PARA INSTALAÇÃO E DURABILIDADE DO FAROL. TAMBÉM TIVEMOS CUSTO EVITADO JÁ QUE O SUPORTE FOI FABRICADO NA OFICINA. ', NULL, N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'MELHORIAS QUE GERAM MELHORIAS ', 0, NULL, N'Decreased lead time = increased productivity and decreased risk', '2026-07-09T00:00:00.000', '2026-07-14T13:57:02.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11176, N'81031659', N'878868', N'Suporte Martelete ', 3, N'Others/Outros', N'Equipamento armazenado de forma inadequada.
INSERT INTO #PVC VALUES (11177, N'201675', N'201675', N'Cloud Observability Improvements', 1, N'Others/Outros', N'-lack of established budgets in cloud to manage workload costs based on actual expenses 
INSERT INTO #PVC VALUES (11178, N'514353', N'878868', N'Suporte Transporte Mourão', 1, N'Projects/Projetos', N'O transporte manual de mourões exigia grande esforço físico, dificultava o manuseio e aumentava o risco de lesões, quedas e perda de controle da carga.', N'"Reduzir o esforço físico e os riscos no transporte de mourões, promovendo maior segurança, ergonomia e padronização da atividade.', N'10017', N'01 - Imagens/01 - Antes/11178.jpeg', N'O transporte manual de mourões exigia esforço físico elevado, dificultava o manuseio e aumentava o risco de lesões, quedas e perda do controle da carga.', N'01 - Imagens/02 - Depois/11178.jpeg', N'Foi implantada uma tenaz para transporte de mourões, garantindo pega firme, reduzindo o esforço físico, aumentando a segurança e facilitando o manuseio da carga.', NULL, N'A meta foi alcançada. O uso da tenaz reduziu o esforço físico, melhorou o controle da carga e aumentou a segurança e a ergonomia no transporte de mourões.', N'ergonomia, segurança e produtividade', 0, NULL, N'Melhorar o controle e a integridade das caixas de mangueiras por meio da utilização de lacres, facilitando a identificação visual de intervenções, tornando as inspeções mais eficientes e contribuindo para a conservação e a prontidão dos equipamentos de combate a incêndio.', '2026-07-13T00:00:00.000', '2026-07-14T14:40:23.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (11179, N'514353', N'878868', N'ferramenta auxiliar transporte de mourão', 1, N'Others/Outros', N'O transporte manual de materiais era realizado por 4 colaboradores, exigindo maior esforço físico, maior exposição ao risco ergonômico e menor eficiência na execução da atividade.', N'Reduzir o esforço físico e otimizar a quantidade de colaboradores envolvidos no transporte, mantendo a segurança e eficiência da atividade.', N'10017', N'01 - Imagens/01 - Antes/11179.jpeg', N'O transporte manual de materiais era realizado por 4 colaboradores, exigindo maior esforço físico, maior exposição ao risco ergonômico e menor eficiência na execução da atividade.', N'01 - Imagens/02 - Depois/11179.jpeg', N'Com a implantação da ferramenta, houve redução da quantidade de colaboradores necessários para a atividade, passando de 4 para 3 pessoas, mantendo maior segurança e eficiência operacional.', NULL, N'Redução de 25% da mão de obra necessária na atividade;
INSERT INTO #PVC VALUES (11180, N'514353', N'878868', N'suporte para organização de ferramentas de limpeza', 3, N'Others/Outros', N'Ferramentas de limpeza armazenadas de forma inadequada, apoiadas no piso e sem local definido, ocasionando desorganização, risco de queda de materiais, dificuldade de identificação e perda de tempo na busca dos utensílios.', N'5s', N'10017', N'01 - Imagens/01 - Antes/11180.jpeg', N'Ferramentas de limpeza armazenadas sem local definido, ocasionando desorganização, risco de queda de materiais, dificuldade de identificação.', N'01 - Imagens/02 - Depois/11180.jpeg', N'Foi desenvolvido um suporte de cano PVC para acondicionamento das ferramentas, garantindo padronização, organização e melhor aproveitamento do espaço.', NULL, N'organização e armazenamento adequado de ferramentas de limpeza, substituindo o acondicionamento desorganizado no canto por um suporte fixo para ferramentas', N'5s', 0, NULL, N'Technicians can now more quickly identify problem with equipment and resolve more efficiently.', '2026-07-10T00:00:00.000', '2026-07-14T14:53:18.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (11181, N'81060882', N'81060882', N'Monitoramento Preditivo no Rolo Desaguador nº 01', 1, N'Projects/Projetos', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'Realizar o monitoramento da temperatura dos rolamentos do rolo', N'10362', N'01 - Imagens/01 - Antes/11181.jpeg', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'01 - Imagens/02 - Depois/11181.jpeg', N'Monitoramento online e em tempo real, garantindo detecção precoce de anomalias sem necessidade de aproximação humana constante do ativo.', NULL, N'A meta inicial do projeto era garantir a integridade do Rolo Desaguador nº 01 através de uma rotina de inspeção mais assertiva e segura.', N'Aumento da Disponibilidade do Rolo Desaguador 01 via Sensoriamento Online', 0, NULL, N'Aumentar a segurança da atividade de lubrificação, eliminando a exposição a riscos ergonômicos e mecânicos através da instalação de pontos de lubrificação remota, proporcionando uma execução mais segura, confortável e eficiente para os empregados.', '2026-07-13T00:00:00.000', '2026-07-14T15:00:47.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11182, N'81060882', N'81060882', N'Monitoramento Preditivo no Rolo Desaguador nº 02', 1, N'Projects/Projetos', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N' Realizar o monitoramento da temperatura dos rolamentos do rolo desaguador de forma online.', N'10362', N'01 - Imagens/01 - Antes/11182.jpeg', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'01 - Imagens/02 - Depois/11182.jpeg', N'Monitoramento online e em tempo real, garantindo detecção precoce de anomalias sem necessidade de aproximação humana constante do ativo.', NULL, N'A meta inicial do projeto era garantir a integridade do Rolo Desaguador nº 02 através de uma rotina de inspeção mais assertiva e segura.', N'Aumento da disponibilidade do rolo desaguador n°2', 0, NULL, N'More accurate reading was accomplished', '2026-07-13T00:00:00.000', '2026-07-14T15:09:52.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11183, N'514353', N'878868', N'Padronização do Controle Diário de Efetivo', 3, N'Others/Outros', N'Ausência de um controle visual atualizado do efetivo diário, dificultando a identificação dos colaboradores disponíveis, em férias ou ausentes, impactando o planejamento e o dimensionamento das atividades.', N'Implementar uma gestão visual eficiente do efetivo, garantindo atualização diária das informações dos colaboradores, melhorando o planejamento das atividades, o dimensionamento da equipe e a tomada de decisão operacional', N'10017', N'01 - Imagens/01 - Antes/11183.jpeg', N'Implantação de controle diário do efetivo em planilha, permitindo o correto dimensionamento das atividades, com visibilidade dos colaboradores ativos, férias e ausências no site.', N'01 - Imagens/02 - Depois/11183.jpeg', N'Implantado painel visual com ímãs e fotos dos colaboradores, contendo nome e função, permitindo atualização diária do status do efetivo (ativo, férias ou ausente), facilitando o controle e a gestão.', NULL, N'Controle do efetivo realizado apenas em planilhas, sem visualização rápida da disponibilidade dos colaboradores, dificultando o acompanhamento diário.', N'5s', 0, NULL, N'- Zero paradas duplas de caminhões.
INSERT INTO #PVC VALUES (11184, N'81060882', N'81060882', N'proteção física articulada dos mancais do tambor traseiro.', 1, N'Projects/Projetos', N'Proteção física danificada e ineficaz, não atendendo aos requisitos mínimos de segurança para enclausuramento de partes móveis.', N'Reduzir a zero o índice de exposição de colaboradores a partes móveis e pontos de prensamento no ativo.', N'10362', N'01 - Imagens/01 - Antes/11184.jpeg', N'Proteção dos mancais do tambor se encontrava com avarias, devido a abertura realizada para facilitar na lubrificação com o equipamento em funcionamento.', N'01 - Imagens/02 - Depois/11184.jpeg', N'Fabricação e montagem de nova proteção dos mancais (padrão de segurança) tipo portão para facilitar no manuseio e possíveis manutenções.', NULL, N'A meta original era restabelecer a segurança e criar uma rotina confiável para os colaboradores.', N'Proteções articuladas com puxadores reduzem o tempo de intervenção mecânica e reestabelecer a segurança.', 0, NULL, NULL, '2026-07-02T00:00:00.000', '2026-07-14T15:23:45.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11185, N'81006732', N'81006732', N'Uso de Pega Cilindro para transporte de cilindros industriais.', 2, N'Others/Outros', N'Era realizado o transporte de cilindros industriais de forma totalmente manual, com uso de força, pressão, flexão manual, podendo causar quedas dos cilindros e lesões corporais devido posturas inadequadas.', N'Minimizar ou eliminar os riscos nos transporte de cilindros de gases.', N'10184', N'01 - Imagens/01 - Antes/11185.jpeg', N'Era realizado o transporte de cilindros industriais de forma totalmente manual, com uso de força, pressão, flexão manual, podendo causar quedas dos cilindros e lesões corporais devido posturas inadequadas.', N'01 - Imagens/02 - Depois/11185.jpeg', N'Implementamos o uso do "Pega Cilindro" para realizarmos o transporte manual dos cilindros industriais, a ferramenta é ideal pois reduz os esforços físicos dos empregados ao utilizar, minimizando os riscos de acidentes devido os cilindros serem acoplados e ajustados conforme a necessidade e na lateral há alças emborrachadas que facilitam o manuseio, oferecendo conforto e firmeza ao realizar o transporte dos cilindros, eliminando posturas e lesões inadequadas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'Sim, com o uso do pega cilindro conseguimos oferecer conforto e firmeza ao realizar o transporte dos cilindros industriais. ', N'Eliminação de posturas inadequadas, e realizado gestão de mudança na área GM 5625.', 0, NULL, NULL, '2026-07-10T00:00:00.000', '2026-07-14T15:29:16.000', N'81006732', NULL, NULL);
INSERT INTO #PVC VALUES (11186, N'81020607', N'543295', N'Elo para ponto de ancoragem do dispositivo para abrir tambor ', 3, N'Others/Outros', N'O dispositivo utilizado para abertura de tambores não possuía um local definido para armazenamento quando não estava em uso, ficando apoiado em locais inadequados. Essa condição gerava risco de danos ao equipamento, dificuldade de localização e potencial de queda ou tropeço na área de trabalho.', N'Melhoria continua ', N'10139', N'01 - Imagens/01 - Antes/11186.jpeg', N'Dispositivo para abertura de tambores sem ponto ou local específico para armazenamento e fixação.', N'01 - Imagens/02 - Depois/11186.jpeg', N'Foi confeccionado e instalado um elo para ponto de ancoragem, permitindo o armazenamento adequado e a fixação segura do dispositivo de abertura de tambores quando fora de uso.', NULL, N'Maior segurança, organização, conservação do equipamento e facilidade de acesso.', N'Qualidade no processo', 0, NULL, N'O operador acessa o equipamento sem necessidade de translado', '2026-07-09T00:00:00.000', '2026-07-14T16:15:13.000', N'81020607', NULL, NULL);
INSERT INTO #PVC VALUES (11187, N'81054395', N'81054395', N'Implementação de Visão Prospectiva para Otimização de Estoques', 1, N'Open Pit/Poço aberto', N'Não existia uma visão consolidada dos ganhos potenciais da revisão dos níveis de estoque, dificultando a priorização das ações e a demonstração dos benefícios esperados. O problema foi identificado durante as análises de Working Capital, diante da necessidade de quantificar e comunicar o potencial de redução do capital imobilizado.', N'Desenvolver uma visão estratégica do potencial de redução de estoques para apoiar a tomada de decisão e direcionar as ações de otimização do capital imobilizado.', N'10015', N'01 - Imagens/01 - Antes/11187.jpeg', N'Antes da implementação, não havia uma visão clara e consolidada do potencial de redução dos estoques, dificultando a priorização das iniciativas e a demonstração dos ganhos esperados. Essa limitação reduzia a visibilidade das oportunidades de otimização do capital imobilizado e foi identificada durante as análises de Working Capital e revisão dos níveis de estoque.', N'01 - Imagens/02 - Depois/11187.jpeg', N'Foi desenvolvida uma projeção estruturada de redução de estoques, com metodologia padronizada para estimar e comunicar os ganhos potenciais, proporcionando maior visibilidade das oportunidades de otimização, melhor direcionamento das ações e suporte à tomada de decisão para redução do capital imobilizado e melhoria do Working Capital.', NULL, N'Sim. Foi criada uma visão consolidada do potencial de redução dos estoques, permitindo quantificar e comunicar os benefícios esperados de forma estruturada', N'A visibilidade dos ganhos potenciais é fundamental para direcionar prioridades e apoiar a tomada de decisão', 0, NULL, N'Aumentar o controle e a rastreabilidade dos anexos, garantindo a segurança das informações do processo.', '2026-07-02T00:00:00.000', '2026-07-15T09:14:55.000', N'81054395', NULL, NULL);
INSERT INTO #PVC VALUES (11188, N'800303', N'800303', N'We can pump that - Lix-84 IC', 1, N'Refining/Refino', N'Lix-84i, an important reagent required for Copper Solvent Extraction had a very long lead time of 6 months.  When speaking with the vendor I was told the reason for the lead time was that we were the only customers for the 84-i product, so the plant needed to be changed to make a batch for us.  We held an RFA to switch our supply to the IC product - more concentrated version, which we had to first prove with could pump due to the increased viscosity.  We proved we could pump and initiated the change.  Lead times should decrease by ~50%', N'Decrease Lead Time', N'0', N'01 - Imagens/01 - Antes/11188.jpeg', N'Lix-84i, an important reagent required for Copper Solvent Extraction had a very long lead time of 6 months.  When speaking with the vendor I was told the reason for the lead time was that we were the only customers for the 84-i product, so the plant needed to be changed to make a batch for us.  I was then informed of a more readily available product, the 84-IC brand which is the same but with a more concentrated (+33%) more active ingredient.', N'01 - Imagens/02 - Depois/11188.jpeg', N'Decreased lead time and cost savings with vendor managing stock in their WHSE', NULL, N'Yes - lead times decreased.  Vendor is now holding the material in their WHSE and managing the min-max inventory for us as well, which results in cost savings associated with the reduction of use of our off-site WHSE space', N'Challenge Status Quo', 10000, 3, N'A solução implantada eliminou o armazenamento das ferramentas no chão, promoveu organização e padronização conforme o 5S, reduziu riscos ergonômicos e aumentou a segurança e a eficiência operacional.
INSERT INTO #PVC VALUES (11189, N'502705', N'502705', N'Prioridade de Componentes no BI', 1, N'No Replication/Sem replicação', N'No BI de Gestão de Materiais e componentes da coordenação de aprovisionamento, é possível enxergar a visão geral de componentes, saldos, aquisições, reformas e distribuição por áreas, porém não tínhamos a visão de prioridade dos componentes ABC para melhor controle das ações.', N'Auxiliar na análise de prioridade dos componentes ABC para tratativa de cobertura.', N'10222', N'01 - Imagens/01 - Antes/11189.jpeg', N'Visão detalhada dos componentes da Usina, separado por grupos de componente, área de aplicação e possibilidade de filtro dos componentes do singelo. Porém sem visão de prioridade dos componentes (ABC). ', N'01 - Imagens/02 - Depois/11189.jpeg', N'Foi incluído no BI, a separação dos componentes por prioridade ABC, bem como o resumo do STATUS de cobertura destes componentes e destaque dos 10 maiores grupos de componentes.', N'https://app.powerbi.com/groups/42c65efb-0cd7-47f1-bd62-844c73607c87/reports/a7de042a-7a35-443c-af0d-eb7ad583367b/22d0e650a9079da3b98d?experience=power-bi', N'Com a publicação do BI, foi possível identificar de forma clara os componentes prioritários para direcionar as tratativas.', N'As demandas podem ser priorizadas após identificação das prioridades.', 0, NULL, N'Ganhos em segurança e garantia de ambiente seguro para os colaboradores com redução de riscos de queda e tropeço.', '2026-07-13T00:00:00.000', '2026-07-15T09:41:04.000', N'502705', NULL, NULL);
INSERT INTO #PVC VALUES (11190, N'486546', N'535629', N'Melhoria da Organização e Conservação das Propulsoras de Graxa', 3, N'Others/Outros', N'As mangueiras das propulsoras de graxa eram armazenadas de forma inadequada, permanecendo enroladas e apoiadas sobre os cilindros dos equipamentos. Essa condição sujeitava componentes críticos a esforços mecânicos e atrito contínuo, aumentando o desgaste prematuro de hastes, vedações e conexões. Além do risco de vazamentos e falhas operacionais, a prática comprometia a organização da área, dificultava o manuseio seguro dos equipamentos e elevava a necessidade de intervenções de manutenção não programadas.', N'Garantir o acondicionamento seguro e organizado das mangueiras das propulsoras de graxa, reduzindo o desgaste prematuro de hastes, vedações e conexões, minimizando o risco de vazamentos e falhas operacionais, além de proporcionar maior segurança e eficiência no manuseio dos equipamentos', N'10079', N'01 - Imagens/01 - Antes/11190.jpeg', N'As mangueiras das propulsoras de graxa eram armazenadas de forma inadequada, permanecendo enroladas e apoiadas sobre os cilindros dos equipamentos. Essa condição sujeitava componentes críticos a esforços mecânicos e atrito contínuo, aumentando o desgaste prematuro de hastes, vedações e conexões. Além do risco de vazamentos e falhas operacionais, a prática comprometia a organização da área, dificultava o manuseio seguro dos equipamentos e elevava a necessidade de intervenções de manutenção não programadas.
INSERT INTO #PVC VALUES (11191, N'513657', N'52836', N'Padronização do Lacre das Caixas de Mangueiras para Garantia da Prontidão Operacional', 1, N'Others/Outros', N'Padronização do Lacre das Caixas de Mangueiras para Garantia da Prontidão Operacional', N'Implementar a padronização dos lacres em todas as caixas de mangueiras', N'10189', N'01 - Imagens/01 - Antes/11191.jpeg', N'Gerando resposta Copilot said: Antes da implementação do Kaizen, as caixas de mangueiras não possuíam lacres de controle, dificultando a verificação rápida da integridade dos equipamentos e a identificação de acessos não autorizados. Essa condição exigia inspeções mais detalhadas para confirmar a presença e as condições dos componentes internos, aumentando o tempo gasto nas verificações e o risco de não conformidades passarem despercebidas. Além disso, a ausência de um controle visual imediato poderia comprometer a confiabilidade e a prontidão dos equipamentos de combate a incêndio, impactando a resposta adequada em situações de emergência.', N'01 - Imagens/02 - Depois/11191.jpeg', N'Copilot said: Após a implementação do Kaizen, todas as caixas de mangueiras passaram a possuir lacres de controle padronizados, permitindo a identificação visual imediata de qualquer abertura ou intervenção nos equipamentos. Com essa melhoria, as inspeções tornaram-se mais ágeis e eficientes, aumentando a confiabilidade da verificação da integridade dos componentes e reduzindo o risco de não conformidades. A adoção dos lacres proporcionou maior controle sobre os equipamentos de combate a incêndio, contribuindo para a sua conservação, disponibilidade e prontidão operacional em situações de emergência.', NULL, N'A ação implementada tratou diretamente o problema identificado, proporcionando um controle visual mais eficiente da integridade das caixas de mangueiras. Com a utilização dos lacres, tornou-se mais fácil identificar aberturas ou intervenções, tornando as inspeções mais ágeis e confiáveis. A melhoria contribuiu para o fortalecimento do controle dos equipamentos e para o aumento da prontidão operacional do sistema de combate a incêndio.', N'A utilização de lacres nas caixas de mangueiras mostrou que medidas simples e de baixo custo podem aumentar a segurança, facilitar as inspeções e garantir maior controle sobre a integridade dos equipamentos, contribuindo para sua prontidão em situações de emergência.', 0, NULL, N'Maior vida útil do sistema de distribuição de ar;
INSERT INTO #PVC VALUES (11192, N'513657', N'52836', N'Inspeção Inteligente por QR Code', 1, N'Others/Outros', N'Gerando resposta Copilot said: As inspeções manuais frequentemente dependem de formulários em papel e registros dispersos, tornando o processo mais lento, sujeito a erros de preenchimento, perda de informações e retrabalho. Além disso, a falta de rastreabilidade e de acesso aos dados em tempo real dificulta o acompanhamento das condições dos ativos e a tomada de decisões rápidas. A inspeção inteligente por QR Code soluciona esses desafios ao permitir o registro digital instantâneo, garantindo maior agilidade, confiabilidade dos dados e controle das informações.', N'Digitalizar e padronizar o processo de inspeção por meio da utilização de QR Codes, garantindo registros mais rápidos, precisos e rastreáveis, com disponibilidade das informações em tempo real para apoiar a gestão e a tomada de decisões.', N'10189', N'01 - Imagens/01 - Antes/11192.jpeg', N'Atualmente, as inspeções são realizadas de forma manual, utilizando formulários em papel ou planilhas preenchidas pelos inspetores em campo. Após a coleta das informações, os dados precisam ser compilados e lançados em sistemas ou relatórios, gerando retrabalho e aumentando o tempo de processamento. Esse modelo está sujeito a falhas de preenchimento, perda de registros, dificuldades na rastreabilidade das inspeções e atraso na disponibilização das informações para análise. ', N'01 - Imagens/02 - Depois/11192.jpeg', N'Após a implementação da Inspeção Inteligente por QR Code, os inspetores passam a acessar os checklists digitais diretamente pelo celular ou tablet, por meio da leitura do QR Code fixado nos equipamentos, áreas ou estruturas. As informações são registradas em tempo real, com possibilidade de anexar fotos e evidências, eliminando o uso de papel e a necessidade de transcrever dados posteriormente. Os registros ficam automaticamente armazenados em uma base centralizada, garantindo rastreabilidade, maior confiabilidade das informações e acesso imediato aos resultados. Com isso, a identificação de desvios e a tomada de decisões tornam-se mais rápidas e eficazes, aumentando a eficiência operacional, o controle dos ativos e a conformidade dos processos.', NULL, N'A solução de Inspeção Inteligente por QR Code atendeu aos objetivos propostos para resolver os problemas identificados no processo de inspeção manual. Enquanto o cenário inicial era marcado pelo uso de formulários em papel, retrabalho na consolidação de dados, dificuldades de rastreabilidade e atraso na disponibilização das informações, a nova solução permitiu a digitalização completa das inspeções, com registro e consulta dos dados em tempo real. Como resultado, houve redução significativa do tempo gasto nas atividades, eliminação de registros físicos, aumento da confiabilidade das informações e melhoria no acompanhamento das não conformidades. Dessa forma, a implementação demonstrou aderência à meta de tornar o processo mais ágil, eficiente, rastreável e alinhado às necessidades operacionais da organização.', N'A implementação da Inspeção Inteligente por QR Code demonstrou que a digitalização dos processos de inspeção aumenta significativamente a qualidade e a confiabilidade dos dados coletados. A facilidade de acesso aos checklists por dispositivos móveis favoreceu a adesão dos usuários e reduziu erros de preenchimento. Também foi constatado que a rastreabilidade em tempo real agiliza a identificação de desvios e a tomada de decisões. Além disso, o projeto evidenciou a importância do treinamento dos colaboradores, da padronização dos formulários digitais e da conectividade adequada em campo para garantir o sucesso da solução e a sustentabilidade dos resultados alcançados.', 0, NULL, N'No more time wasted during inspection looking for decommissioned equipment.', '2026-07-08T00:00:00.000', '2026-07-15T11:25:38.000', N'513657', NULL, NULL);
INSERT INTO #PVC VALUES (11193, N'81046830', N'1010414', N'Kiln Zone Contactor Faults', 1, N'Others/Outros', N'Kiln is intermittently shutting down with an indication for Zone breaker alarm from DCS panel. This indication refers to local HMI for more information. Locally there is no alarm information to help technicians.', N'Add additional messages to local HMI for technician troubleshooting', N'0', N'01 - Imagens/01 - Antes/11193.jpeg', N'Kiln alarm information from DeltaV. References to check local HMI for more fault information to identify issue. However not all fault information is present on local HMI.', N'01 - Imagens/02 - Depois/11193.jpeg', N'Added additional logic to PLC and new alarm messages to display Zone contactor alarms to assist technicians in field to the problematic device.', NULL, N'Alarm messages now present in HMI to allow field technicians to better identify equipment causing the issue.', N'Issues still exist from commissioning, not all logic fully tested', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11194, N'518048', N'518048', N'Lubrificação da barra do d9t', 2, N'Others/Outros', N'Desgaste das buchas e pinos da barra estabilizadora por falta de lubrificação, devido a falta de espaço para acessar os pontos de lubrificação.', N'Segurança do empregado e durabilidade do componente', N'10188', N'01 - Imagens/01 - Antes/11194.jpeg', N'Durante a execução das atividades de lubrificação, tanto em oficina quanto em campo, foi identificado que a intervenção na barra estabilizadora exigia a adoção de postura ergonomicamente inadequada. Adicionalmente, o empregado permanecia em contato direto com a estrutura do equipamento, aumentando a exposição a riscos ergonômicos e potenciais lesões decorrentes de esforço físico, compressão mecânica e restrição de mobilidade durante a execução da tarefa.', N'01 - Imagens/02 - Depois/11194.jpeg', N'Durante o estudo de melhoria da atividade, verificou-se que o fabricante disponibilizava uma atualização de projeto contemplando pontos de lubrificação remota. A adequação foi implementada com o objetivo de eliminar a exposição dos empregados a condições de risco decorrentes do acesso à barra estabilizadora. A solução proporcionou ganhos significativos em segurança, ergonomia e manutenabilidade, reduzindo a necessidade de posturas forçadas e o contato com a estrutura do equipamento. Adicionalmente, houve melhoria na eficácia da lubrificação, aumento da confiabilidade dos componentes e extensão da vida útil dos elementos lubrificados, contribuindo para a redução de falhas e para o aumento da disponibilidade física do equipamento.', NULL, N'Durante o processo de estudos das falhas estávamos focados apenas na duração dos componentes do equipamento, porém durante as avaliações percebemos que o nosso maior ganho foi com a segurança do funcionário.', N'Durante a analise enteemos que melhorias de engenharia do fabricante podem e devem ser implementadas nos equipamentos.', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11195, N'1008463', N'460565', N'LOT Dip tube support', 1, N'Refining/Refino', N'When dipping the LOT, the dip tube was bending, preventing the PPTs from getting an accurate reading', N'More accurate mesasurment', N'10112', N'01 - Imagens/01 - Antes/11195.jpeg', N'Just an open hole, dip tube was bending when trying to get a mesasurment', N'01 - Imagens/02 - Depois/11195.jpeg', N'Dip tube down comer was installed in the hole to keep the tube straight when inserting it into the LOT', NULL, N'Yes', N'None', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11196, N'475291', N'475291', N'Área para Revezamento de operadores no Posto pesado', 1, N'No Replication/Sem replicação', N'A Ausência de um ponto de apoio estratégico próximo ao posto pesado impede o revezamento operacional (almoço/janta, ginástica laboral e outros.) durante a parada por abastecimento dos caminhões fora de estrada. Isso gera paradas duplas desnecessárias dos equipamentos, resultando em perda de tempo produtivo e redução da eficiência operacional da frota.', N'Facilitar/otimizar os revezamentos da operação', N'0', N'01 - Imagens/01 - Antes/11196.jpeg', N'A Ausência de um ponto de apoio estratégico próximo ao posto pesado impede o revezamento operacional (almoço/janta, ginástica laboral e outros.) durante a parada por abastecimento dos caminhões fora de estrada. Isso gera paradas duplas desnecessárias dos equipamentos, resultando em perda de tempo produtivo e redução da eficiência operacional da frota.', N'01 - Imagens/02 - Depois/11196.jpeg', N'Realizamos a adequação física da área com o alargamento do espaço próximo ao posto de abastecimento, garantindo que o fluxo de veículos leves não fosse interferido. Foi implantado um ponto estratégico exclusivo para revezamento de operadores, dotado de leiras sinalizadas e placas de identificação. Para garantir a integridade física da equipe, criamos um caminho seguro delimitado para o deslocamento dos operadores entre o ônibus e o posto. A área foi testada com sucesso para manobras de ônibus e permite que a rendição da ginástica laboral e refeições ocorra de forma segura e simultânea ao abastecimento do caminhão fora de estrada.', NULL, N'Sim. A meta foi 100% atingida. Com o novo ponto estratégico e o caminho seguro, eliminamos as paradas duplas dos caminhões fora de estrada. Agora, o revezamento para almoço e ginástica laboral ocorre de forma totalmente segura e simultânea ao abastecimento, otimizando o tempo produtivo e garantindo a pontualidade das pausas da equipe.', N'Através de um olhar atento pequenas adequações de infraestrutura podem gerar grandes ganhos de produtividade.', 0, NULL, NULL, '2026-07-01T00:00:00.000', '2026-07-15T15:58:21.000', N'475291', NULL, NULL);
INSERT INTO #PVC VALUES (11197, N'1008463', N'460565', N'Reusing pipe clamp', 1, N'Others/Outros', N'Water leak in Cu SX and no clamps available to stop it', N'Stop water leak', N'10112', N'01 - Imagens/01 - Antes/11197.jpeg', N'Water leak in Cu SX and there were no clamps available', N'01 - Imagens/02 - Depois/11197.jpeg', N'A clamp was found on a spool piece in a dumpster and was repurposed instead of throwing it out.', NULL, N'Goal met', N'Removed clamps before throwing out spools', 600, 3, N'Real-time access to: total NCRs YTD, open count, overdue count, pending approvals, verified closures (MTD), status distribution donut chart, NCR volume by month, most frequent offender by vendor, most common root cause by classification, average remediation cycle time by vendor, and an overdue NCR alert table. No manual report preparation required.', '2026-07-14T00:00:00.000', '2026-07-15T16:28:02.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (11198, N'1008463', N'460565', N'Clamp leak in Cd', 1, N'Others/Outros', N'Process water leak in Cd removal and no clamp to stop it', N'Clamp the leak', N'10112', N'01 - Imagens/01 - Antes/11198.jpeg', N'Process water leak and no clamp to stop it', N'01 - Imagens/02 - Depois/11198.jpeg', N'Repurposed a hose clamp on a spool that was getting thrown out', NULL, N'GOal met', N'Remove clamps before throwing out spools', 600, 3, N'- Monthly report generation time reduced from ~4 hours to under 2 minutes
INSERT INTO #PVC VALUES (11199, N'122911', N'473357', N'Estacionamento da carreta SI 43', 1, N'No Replication/Sem replicação', N'Dificuldade pra inspecionar e fazer a logística do operador até o equipamento.', N'Reduzir o tempo de deslocamento dos operadores até a carreta SI 43, eliminando a necessidade de translado do operador até o equipamento.', N'10257', N'01 - Imagens/01 - Antes/11199.jpeg', N'O estacionamento anterior estava localizado no Depósito Sudoeste Flauta, nível 240, exigindo o deslocamento do operador para a realização das inspeções diárias e para a operação do equipamento sempre que fosse necessário executar atividades de transporte.', N'01 - Imagens/02 - Depois/11199.jpeg', N'Foi confeccionado um novo estacionamento ao lado do Escritório do Misto, possibilitando que o operador realize a inspeção diária e acesse o equipamento de forma rápida e prática sempre que necessário. Essa melhoria eliminou a necessidade de translado até o antigo local de estacionamento, reduzindo o tempo de deslocamento e aumentando a eficiência operacional.', NULL, N'Com a realocação do estacionamento para uma área próxima ao Escritório do Misto, a necessidade de translado dos operadores foi eliminada, reduzindo significativamente o tempo de acesso ao equipamento.
INSERT INTO #PVC VALUES (11200, N'81030465', N'81030465', N'Organizador de anexos ', 1, N'Others/Outros', N'Anteriormente, todos os anexos da sala do flúor, sejam eles concluídos, em andamento ou finalizados, eram armazenados de forma única em uma única prancheta. Essa condição gerava falta de organização, dificuldade para localizar os documentos e um alto risco de perda ou extravio de informações importantes para o controle do processo.', N'Eliminar o risco de perca de anexos da analise de Flúor ', N'10366', N'01 - Imagens/01 - Antes/11200.jpeg', N'Anteriormente, todos os anexos da sala do flúor, sejam eles concluídos, em andamento ou finalizados, eram armazenados de forma única em uma única prancheta. Essa condição gerava falta de organização, dificuldade para localizar os documentos e um alto risco de perda ou extravio de informações importantes para o controle do processo.', N'01 - Imagens/02 - Depois/11200.jpeg', N'Após a melhoria, foi implantado um organizador específico com divisórias para separar os anexos por status: Concluídos, Em Andamento e Finalizados. Com isso, ganhamos mais controle, rastreabilidade e segurança na guarda dos documentos. A ação reduziu significativamente o risco de perda, trouxe agilidade na consulta e contribuiu para um ambiente mais organizado e padronizado.', NULL, N'Meta Inicial: Organizar os anexos da sala do flúor e eliminar o risco de perda devido ao armazenamento único em prancheta.
INSERT INTO #PVC VALUES (11201, N'81042202', N'81017935', N'Suporte para ferramentas  ', 3, N'Others/Outros', N'Durante as atividades de limpeza industrial, as ferramentas não possuíam um local definido para armazenamento, permanecendo expostas diretamente no chão. Essa condição comprometia a organização do ambiente, dificultava o acesso aos materiais, aumentava o tempo de execução das atividades e gerava riscos ergonômicos e de segurança aos colaboradores.
INSERT INTO #PVC VALUES (11202, N'81060535', N'487612', N'Redução do Risco de Acidentes por Meio de Sinalização de Degrau​', 2, N'Others/Outros', N'Durante uma reunião no espaço conexão identificamos 
INSERT INTO #PVC VALUES (11203, N'550315', N'550315', N'SUPORTE PARA CALÇO DE RODAS  CAMINHONETE', 1, N'Others/Outros', N'Caminhonete com calço de rodas transportado na carroceria sem suporte ou dispositivo de fixação, permanecendo solto', N'Projetar um suporte para o calço de rodas da caminhonete', N'10234', N'01 - Imagens/01 - Antes/11203.jpeg', N'Calço de rodas solto na carroceria da caminhonete, sem acondicionamento e sem suporte adequado para fixação.', N'01 - Imagens/02 - Depois/11203.jpeg', N'Caminhonete equipada com suporte para armazenamento de calço de rodas, mantendo devidamente fixado e organizado na carroceria, sem risco de deslocamento durante o transporte.', NULL, N'Anteriormente, o calço encontrava-se solto na carroceria, podendo se deslocar durante a movimentação do veículo, gerando risco de queda, danos ao equipamento e potencial ocorrência de acidentes. Após a adequação, o calço passou a ser armazenado em suporte apropriado e devidamente fixado, eliminando o risco de movimentação indevida e garantindo maior organização, segurança e conformidade com as boas práticas de transporte de materiais.', N'A utilização de suportes dedicados melhora a organização dos equipamentos e reduz o risco de perca', 0, NULL, N'.', '2026-07-15T00:00:00.000', '2026-07-16T06:32:46.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11204, N'81058966', N'81036659', N' Substituição da tubulação de ar da coluna de flotação em aço carbono por tubulação em aço inoxidável.', 1, N'Others/Outros', N'A tubulação de ar da coluna de flotação, fabricada em aço carbono, apresentava elevado desgaste devido à corrosão, ocasionando vazamentos frequentes, necessidade de reparos corretivos, risco de perda de pressão do sistema de ar e redução da confiabilidade operacional. ', N' Substituir a tubulação de aço carbono por tubulação em aço inoxidável, aumentando a vida útil do sistema, eliminando vazamentos por corrosão, reduzindo custos de manutenção corretiva e aumentando a confiabilidade operacional da coluna de flotação.', N'10031', N'01 - Imagens/01 - Antes/11204.jpeg', N'Exposição contínua à umidade e ao ambiente agressivo do processo;
INSERT INTO #PVC VALUES (11205, N'1010227', N'1010227', N'Acid Piping Update', 1, N'Others/Outros', N'Modifications were made in the field but these changes were not reflected in SAP. A recent PM was performed, and it was determined that some piping on this PM was removed from service. The PM was also attached to the equipment number that should have been deactivated. There was also some other equipment in the area that had been removed but was not changed in SAP.', N'Ensure assets in SAP reflect what is in the field for proper history tracking', N'0', N'01 - Imagens/01 - Antes/11205.jpeg', N'An active PM identified two pipelines that no longer exist in the field. The PM was also attached to the inactive pipeline in SAP. A pump and transmitter were also determined to be removed.', N'01 - Imagens/02 - Depois/11205.jpeg', N'The decommissioned equipment was changed to inactive in SAP and the PM was updated to no longer reference the pipelines. The PM was also attached to one of the active pipelines instead.', NULL, N'Yes, the required updates were made in SAP so the removed pipelines will no longer be referenced. The next time the PM is completed there will be no time wasted looking for the pipelines. Equipment records and history are now accurate in SAP.', N'Any changes in the field needs to be updated in existing documents and  data management systems.', 0, NULL, N'Ganhos em segurança e garantia de ambiente seguro para os colaboradores com redução de riscos de prensamento de mãos e dedos.
INSERT INTO #PVC VALUES (11206, N'81007807', N'81007807', N'Lista de tarefa - Falha MR (módulo de falha motor)', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11207, N'81007807', N'81007807', N'Lista de tarefa - Falha sistema ABS', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11208, N'81007807', N'81007807', N'Lista de tarefa - Corrigir falhas elétricas', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11209, N'81042793', N'81042793', N'Digital Transformation of Contract Sourcing Planning — Spreadsheet to Intelligent App', 1, N'Projects/Projetos', N'Contract sourcing planning at VNL was managed through a combination of static Excel spreadsheets, disconnected email chains, and manual calendar tracking. No single system provided visibility into sourcing timelines, SLA burn rates, or phase-level progress. Contracts approaching expiry required manual filtering to be identified, sourcing leads had no standard mechanism to record weekly progress, and management had no real-time view of portfolio risk. The effort required to produce a single status report exceeded several hours of manual consolidation every cycle.', N'1.  Replace spreadsheet-based sourcing tracking with a single, authoritative Power Apps canvas app connected to SharePoint as the system of record for all contractors.   2. Give sourcing coordinators, contract managers, and leadership real-time Gantt visibility of all contract SLA timelines, phase positions, and RAG statuses at any point in time.  3. Automatically calculate and flag contracts approaching SLA thresholds — eliminating manual expiry monitoring and ensuring sourcing is triggered with adequate lead time.  4. Provide a structured mechanism for weekly sourcing progress updates and comments, replacing ad-hoc email updates with a timestamped audit trail per contract', N'10026', N'01 - Imagens/01 - Antes/11209.jpeg', N'Contract expiry dates tracked in a shared Excel workbook with no automated alerts.
INSERT INTO #PVC VALUES (11210, N'81042793', N'81042793', N'Digitalization of Contractor Nonconformance Management Through an Integrated Power Apps Solution', 1, N'Projects/Projetos', N'VNL had no dedicated digital system for recording, tracking, and closing out contractor nonconformances across its operations. NCR documentation was managed through a combination of email chains, shared spreadsheets, and manually drafted Word documents — a fragmented approach that created significant gaps in visibility, accountability, audit readiness, and contractor performance governance. Nonconformances were being raised inconsistently, followed up informally, and in several cases not formally closed out at all, leaving unresolved compliance obligations invisible to management and unenforceable under contract.', N'1. Eliminate manual NCR tracking.  2. Ensure completeness of reporting, using mandatory fields. 3.  Reduce average NCR response time by 20% through automating notifications. 4.  Eliminate missed close-out deadlines. 5. Automated overdue alerts; zero NCRs closed without NC Manager sign-off. 6. Create a defensible, time-stamped audit trail for every NCR.', N'10026', N'01 - Imagens/01 - Antes/11210.jpeg', N'NC events were usually identified and reported verbally or via email. Notification emails to the contractor drafted manually. Follow-up was tracked informally. 
INSERT INTO #PVC VALUES (11211, N'81042793', N'81042793', N'Digital Tracking of Contractor Performance Management', 1, N'Projects/Projetos', N'VNL had no integrated system for monitoring the performance of active contractors. Headcount, safety incidents, quality metrics, and financial spend data were maintained in Excel workbooks and emails, with no single source of truth, no mechanism for correlating contractor performance with vendor evaluations. Monthly reporting to management required significant manual effort with risk of error, inconsistency, and delay.', N'1. Consolidate FTE, Quality, Safety, and Finance contractor data into a single integrated platform. 2. Replace manual reporting with automated, on-demand HTML reports exportable to browser and Excel. 3. Enable trend management through monthly dashboard and per-contractor scorecards. 4. Standardise performance monitoring across all contractors under one framework', N'10026', N'01 - Imagens/01 - Antes/11211.jpeg', N'Contractors tracked in fragmented Excel files and email threads across FTE, Safety, Quality, and Finance. No consolidated view, no trend analysis, no automated reporting. Monthly reporting required manual compilation taking several hours, with inconsistent formats between preparers and no audit trail.', N'01 - Imagens/02 - Depois/11211.jpeg', N'Five live report tabs (FTE, Safety, Quality, Finance, Dashboard), Contractor scorecard, automated HTML report generation, one-click browser launch, and Excel export. Scorecard tab delivers per-contractor YTD performance in seconds.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/0128a908-d0bf-4851-a51b-50939f4908f4?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a52b8fdb-f574-451b-bcde-02edf229c540&sourcetime=1784214249050', N'Problem solved. New tool for vendor assessment and potential ranking.', N'Scorecard composite score and trend data can aid earlier identification of underperforming contractors.', 0, NULL, N'O aplicativo resolveu o problema anterior.', '2026-06-19T00:00:00.000', '2026-07-16T12:30:03.000', N'81042793', NULL, NULL);
INSERT INTO #PVC VALUES (11212, N'763789', N'763789', N'Instalação de Espelho Convexo para Eliminação de Ponto Cego e Aumento da Segurança Viária no Acesso à Via Principal', 2, N'Others/Outros', N'Motoristas de carretas encontravam dificuldade para visualizar veículos na via principal devido à existência de ponto cego no acesso, aumentando o tempo de espera e a exposição ao risco de acidentes durante a realização da manobra.', N'Implantar uma solução permanente para eliminar o ponto cego existente no acesso à via principal, aumentando a segurança viária e estabelecendo um novo padrão operacional para motoristas de veículos leves e pesados.', N'10294', N'01 - Imagens/01 - Antes/11212.jpeg', N'No acesso à via principal, os condutores de veículos pesados encontravam dificuldade para visualizar o tráfego da faixa adjacente devido à existência de um ponto cego. A limitação de visibilidade aumentava o tempo de tomada de decisão e elevava a exposição ao risco durante a entrada na via.
INSERT INTO #PVC VALUES (11213, N'516619', N'512014', N'Melhoria na Analise de xantato', 2, N'No Replication/Sem replicação', N'Na analise atual de Xantato necessita de preparação 
INSERT INTO #PVC VALUES (11214, N'81013885', N'81013885', N'SUPORTE METALICO', 2, N'Refining/Refino', N'A carcaça da bomba era movimentada e apoiada diretamente sobre o piso ou bancada, sem um suporte específico. Essa condição dificultava o manuseio, comprometia a estabilidade da peça e aumentava o risco de tombamento, danos às superfícies de vedação, esforço ergonômico excessivo e acidentes durante o transporte.', N' ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', N'10362', N'01 - Imagens/01 - Antes/11214.jpeg', N'A carcaça da bomba era movimentada e apoiada diretamente sobre o piso ou bancada, sem um suporte específico. Essa condição dificultava o manuseio, comprometia a estabilidade da peça e aumentava o risco de tombamento, danos às superfícies de vedação, esforço ergonômico excessivo e acidentes durante o transporte.', N'01 - Imagens/02 - Depois/11214.jpeg', N'Foi fabricado um suporte metálico dimensionado para acomodar a carcaça da bomba de forma estável e segura. O suporte mantém a peça elevada, facilita o transporte por ponte rolante ou carrinho, melhora a ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', NULL, N'SIM. Facilita o transporte por ponte rolante ou carrinho, melhora a ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', N'melhora a ergonomia durante as atividades', 0, NULL, N'houve uma ganho significativo no tempo estimado para posicionar a avaria. Com isso há um ganho sequencial de tempo, em todos os passos da atividade, melhorando a DF do equipamento.', '2026-07-15T00:00:00.000', '2026-07-16T15:30:19.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11215, N'485273', N'485273', N'Otimização do Fornecimento de Água Potável por meio da Substituição de Galões de 20L por Sistema de Filtragem', 1, N'Others/Outros', N'O fornecimento de água por meio de galões de 20 litros gera custos recorrentes de aquisição e logística, além de exigir movimentação manual para troca dos recipientes, expondo os empregados a riscos ergonômicos. Esse processo também demanda tempo operacional e maior necessidade de armazenamento dos galões.', N'Implementar um sistema de filtragem de água diretamente nos bebedouros, substituindo o uso de galões de 20 litros, com o objetivo de promover maior ergonomia nas atividades dos empregados, eliminando a necessidade de movimentação e troca manual dos recipientes. Além disso, a iniciativa visa reduzir custos operacionais relacionados à aquisição, transporte e armazenamento de galões, bem como aumentar a eficiência no fornecimento de água potável, contribuindo para a sustentabilidade e a melhoria das condições de trabalho.', N'10017', N'01 - Imagens/01 - Antes/11215.jpeg', N'O abastecimento de água potável era realizado por meio de galões de 20 litros, que precisavam ser armazenados, transportados e substituídos manualmente sempre que esvaziavam. A atividade exigia o levantamento e manuseio dos galões pelos empregados, gerando esforço físico e risco ergonômico, além de demandar tempo para reposição e controle do estoque de água.', N'01 - Imagens/02 - Depois/11215.jpeg', N'Com a instalação de filtros nos bebedouros, o fornecimento de água passou a ser realizado diretamente no ponto de consumo, eliminando a necessidade de utilização, armazenamento e troca de galões de 20 litros. A melhoria reduziu o esforço físico dos empregados, eliminando os riscos ergonômicos associados ao manuseio dos galões, além de proporcionar redução de custos operacionais, maior praticidade no abastecimento e melhor eficiência no fornecimento de água potável.', NULL, N'Sim, a melhoria implementada atendeu à meta estabelecida, eliminando a troca manual de galões de 20 litros, reduzindo riscos ergonômicos, diminuindo custos operacionais e aumentando a eficiência no fornecimento de água potável.', N'A substituição dos galões por filtros demonstrou que soluções simples podem gerar ganhos expressivos em ergonomia, redução de custos, eficiência operacional e sustentabilidade, reforçando a importância da melhoria contínua na otimização dos processos.', 2, 1, N'Transformar o controle de refeições em um processo totalmente digital, ágil, confiável e sustentável, proporcionando maior eficiência operacional e melhor gestão dos recursos do refeitório.', '2026-07-15T00:00:00.000', '2026-07-16T15:52:19.000', N'485273', NULL, NULL);
INSERT INTO #PVC VALUES (11216, N'81013885', N'81013885', N'PROTEÇÃO DE BOMBA', 2, N'Others/Outros', N'A proteção do acoplamento possuía pequena área de visualização, dificultando a inspeção do estado do acoplamento. Para verificar visualmente componentes como elemento elástico, alinhamento aparente e condição geral, era necessário bloquear o equipamento e remover a proteção, aumentando o tempo da atividade e a exposição dos mantenedores.', N'. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', N'10362', N'01 - Imagens/01 - Antes/11216.jpeg', N'A proteção do acoplamento possuía pequena área de visualização, dificultando a inspeção do estado do acoplamento. Para verificar visualmente componentes como elemento elástico, alinhamento aparente e condição geral, era necessário bloquear o equipamento e remover a proteção, aumentando o tempo da atividade e a exposição dos mantenedores.', N'01 - Imagens/02 - Depois/11216.jpeg', N'Foi confeccionada e instalada uma nova proteção metálica com ampla área em tela metálica de proteção, permitindo a visualização do acoplamento durante as inspeções de rotina, sem necessidade de remoção da proteção. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', NULL, N'SIM. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', N' A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', 0, NULL, N'Redução do tempo gasto na localização e retirada dos EPIs, proporcionando maior agilidade no atendimento das necessidades dos colaboradores e melhor fluidez nas atividades diárias.', '2026-07-15T00:00:00.000', '2026-07-16T15:52:21.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11217, N'81045425', N'81045425', N'TESTE NOS FREIOS DOS MOTORES', 2, N'Others/Outros', N'SEMPRE QUE ERA NECESSÁRIO TESTAR OS FREIOS INSTALADOS NOS MOTORES ERA PRECISO QUE FOSSE DADO COMANDO NO EQUIPAMENTO PARA QUE CHEGASSE TENSÃO NOS MESMOS', N'MINIMIZAR ESPOSIÇÃO A RISCOS DE CHOQUE ELÉTRICO  DURANTE TESTES NOS FREIOS', N'10294', N'01 - Imagens/01 - Antes/11217.jpeg', N'PARA QUE SE CONSEGUISSE TESTAR OS FREIOS DA TRANSLAÇÃO DO CN ERA NECESSÁRIO QUE FOSSE DADO COMANDO NA TRANSLAÇÃO E AS VERIFICAÇÕES FOSSE FEITAS COM O CN EM MOVIMENTO, AUMENTANDO O RISCO  ELÉTRICO.', N'01 - Imagens/02 - Depois/11217.jpeg', N'APÓS CRIAÇÃO DO DISPOSITIVO PARA TESTE, PODEMOS TESTAR OS FREIOS COM O EQUIPAMENTO PARADO E BLOQEADO. ', NULL, N'ALÉM DE REDUZIR O RISCO DE CHOQUE ELÉTRICO, ELIMINAMOS O RISCO DE ESMAGAMENTO PELO MOVIMENTO DO CN DURANTE OS TESTES NOS FREIOS', N'Às vezes, a verdadeira mudança começa quando criamos nossas próprias inovações, e assim transformamos cenários e promovemos a evolução.', 0, NULL, N'MELHOROU A PRODUTIVIDADE EM TODOS O MOMENTOS COM UMA ILUMINAÇÃO MAIS REFORÇADA. COM CUSTO DE R$149,23 POR CADA UMA LUMINÁRIA FABRICADA NESTE MODELO DE EXTENSÃO.', '2026-07-10T00:00:00.000', '2026-07-16T16:31:57.000', N'81045425', NULL, NULL);
INSERT INTO #PVC VALUES (11218, N'81060535', N'81060535', N'Implementação de Sinalização de Segurança para Uso Seguro do Elevador de Cargas do Laboratório Físico 1.', 2, N'Others/Outros', N'Foi identificada a ausência de sinalização de segurança no elevador de cargas do laboratório Físico 1. A falta de comunicação visual não evidenciava os riscos e perigos da utilização do equipamento, essa condição pode dificultar a percepção do risco pelos usuários, aumentando o potencial de acidentes durante a operação do elevador. O mesmo possui abertura de portas de correr que podem vir a fechar rapidamente prensando dedos e mãos, o que ocasionaria em uma ocorrência operacional.
INSERT INTO #PVC VALUES (11219, N'87000312', N'87000339', N'Energy savings through reduced operating frequency of the No. 2 leak acid pit pump', 1, N'Refining/Refino', N'During 3RT operations, condensate from the No. 3 Final MC continuously overflows from the seal tank into the No. 2 leak acid pit. Since this liquid cannot be discharged directly, it is collected in the No. 2 leak acid pit and periodically pumped to the water treatment process.', N'Reduction of pump operating time and working time', N'0', N'01 - Imagens/01 - Antes/11219.jpeg', N'During 3RT operations, condensate from the No. 3 Final MC continuously overflows from the seal tank into the No. 2 leak acid pit. Since this liquid cannot be discharged directly, it is collected in the No. 2 leak acid pit and periodically pumped to the water treatment process.', N'01 - Imagens/02 - Depois/11219.jpeg', N'Liquid from the No. 3 Final MC spray pump is sent via piping to the 3EAT-PT unit, where it undergoes treatment in the water treatment process. This has resulted in reduced electricity costs associated with pump operation and a reduced man power.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Permitir que qualquer usuário do Painel de Telemetria Unificada compreenda rapidamente não apenas a ocorrência do evento, mas também todo o histórico de ações executadas para sua análise e tratamento.', '2026-07-15T00:00:00.000', '2026-07-17T05:30:32.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11220, N'81046830', N'1010414', N'SEW Drive Replacement Procedure', 1, N'Others/Outros', N'SEW drives are used within our Ionic vendor equipment systems, this is a limited footprint and can be challenging to work with if not prepared.', N'Allow for efficient replacement of failed SEW drive equipment.', N'0', N'01 - Imagens/01 - Antes/11220.jpeg', N'SEW drive failures can become a challenge to replace efficiently due to the small footprint of the equipment on site. However, the equipment is important to keep the CSM and Inking Stations running.', N'01 - Imagens/02 - Depois/11220.jpeg', N'Developed a SEW drive replacement procedure and guide to assist field and control technicians when another failure occurs.', NULL, N'Work instruction developed to assist with a more efficient replacement of SEW drives.', N'Important to develop work instructions for future use', 0, NULL, N'Garantir que os spots permaneçam ativos e transmitindo dados regularmente, assegurando monitoramento contínuo dos ativos e suporte às análises de confiabilidade da Mina de Salobo.', '2026-07-16T00:00:00.000', '2026-07-17T06:50:41.000', N'81046830', NULL, NULL);
INSERT INTO #PVC VALUES (11221, N'81043724', N'81043724', N'TABELA DE TAG ', 3, N'Others/Outros', N'O RESPONSAVEL PELA SALA DE CADASTRO TINHA QUE IR TODOS OS DIAS VERIFICAR AS TAG DOS EQUIPAMENTOS PARA LANCAMENTO. O QUE DEMANDAVA MUITO TEMPO NO PROCESSO EM CASO DE MANUTENCAO ERA PRECISO FAZER ESSA VERIFICACAO NAS SALAS PARA ACIONAMENTO DA EQUIPE .', N'ELIMINAR TEMPO NA PROCURA DAS TAG ', N'10366', N'01 - Imagens/01 - Antes/11221.jpeg', N'NÃO EXISTIA UMA PADRONIZAÇÃO COM TODAS AS TAG DISPONIVEIS, ERA NECESSARIO FICAR INDO ATE OS EQUIPAMENTOS PARA VERIFICACAO DAS MESMAS ', N'01 - Imagens/02 - Depois/11221.jpeg', N'FOI DISPONIBILIZADO UMA TABELA COM TODAS AS TAG EXISTENTE NAS SALA DO LABORATORIO FISICO O QUE ELIMINOU O MOVIMENTO DE ESTA INDO TODO OS DIAS VERIFICAR AS TAG EM CADA EQUIPAMENTOS .GANHAMOS TEMPO E AGILIDADE NO PROCESSO DE LANCAMENTO E NA MANUTENÇÃO ', NULL, N'ANTES TINHAMOS QUE IR OLHAR OS TAG VARIAS VEZES DURANTE O TURNO NO EQUIPAMENTO, AGORA TEMOS DISPONIVEL NA SALA DE CADASTRO COM TODOS OS TAG .', N'COM O SIMPLES FATO DE CRIAR UMA TABELA ELIMANOS VARIOS MOVIMENTOS DURANTE O DIA .', 0, NULL, N'Permitir que todos os eventos de telemetria da Mina de Salobo sejam tratados dentro de uma única plataforma, garantindo padronização, rastreabilidade e acompanhamento contínuo das ocorrências.', '2026-07-11T00:00:00.000', '2026-07-17T10:59:26.000', N'81043724', NULL, NULL);
INSERT INTO #PVC VALUES (11222, N'608046', N'81010661', N'Truck Unloading-Wheel Chocks', NULL, N'Others/Outros', N'Previously utilized wheel chocks were rubber wedges, awkward to handle, bend down to ground level to install and usually were not left in place for ease of reagent unloading, as required.', N'Reagent-Handling-Safety', N'10114', N'01 - Imagens/01 - Antes/11222.jpeg', N'Rubber wheel chock left in unloading areas, didn''t have a storage station, hard to handle and usually not in pairs.', N'01 - Imagens/02 - Depois/11222.jpeg', N'Cl2/H2SO4/NaOH-unloading stations implemented new wheel chock positions at all locations, ergonomic-easy to utilize and install during offloading of reagents.', NULL, N'Yes-reagent handler doesn''t have to leave area to locate wheel chocks-they are in unloading areas in position and readily available. ', N'ergonomically friendly/ease of accessibility', 0, NULL, N'Garantir controle completo sobre as substituições de componentes da frota, permitindo análises históricas, gestão da vida útil e suporte à tomada de decisão baseada em dados.', '2026-07-15T00:00:00.000', '2026-07-17T11:18:52.000', N'608046', NULL, NULL);
INSERT INTO #PVC VALUES (11223, N'200746', N'200746', N'Population of Lot # on Co Certificates of Analysis', NULL, N'Others/Outros', N'Lot number information wasn''t consistently being populated on the cobalt certificates of analysis being auto generated by LIMS', N'Consistent addition of lot information to cobalt certificates of analysis', N'10286', N'01 - Imagens/01 - Antes/11223.jpeg', N'When logging cobalt product in LIMS, the barcode wasn''t consistently being scanned into the ID1 field.  When CoA''s are auto-generated by LIMS, the system pulls the information inputted into the ID1 field to populate the lot number on the certificate.  This information was often missing.  The procedure for logging final product also did not include instructions for scanning the barcode information in LIMS.', N'01 - Imagens/02 - Depois/11223.jpeg', N'A LIMS ticket was entered to make the ID1 field in LIMS mandatory when logging Co product.  This would ensure that the necessary information would be inputted into the system and that it would be available for CoA generation.  The procedure for logging final product was also revised to include instructions pertaining to scanning the product barcode into the ID1 field in LIMS.', NULL, N'Required information is now available in LIMS.  The goal has been achieved.', N'Creating mandatory fields helps serve as a reminder to include necessary important information', 0, NULL, N'Permitir que os eventos provenientes da plataforma My Sandvik sejam acompanhados e tratados dentro do mesmo fluxo operacional das demais fontes de telemetria, garantindo padronização, rastreabilidade e maior eficiência das análises.', '2026-07-16T00:00:00.000', '2026-07-17T11:27:04.000', N'200746', NULL, NULL);
INSERT INTO #PVC VALUES (11224, N'81034239', N'81030330', N'App Gestão Operacional', 1, N'Others/Outros', N'O processo de elaboração do relatório de turno era realizado exclusivamente por meio de mensagens no WhatsApp, o que dificultava a padronização e o controle das informações registradas. As ocorrências, resultados e atividades do turno ficavam dispersos em diferentes mensagens, tornando a consulta ao histórico lenta e pouco eficiente.', N'Melhorar o relatório de turno do laboratório', N'10366', N'01 - Imagens/01 - Antes/11224.jpeg', N'O relatório de turno era realizado exclusivamente por meio de mensagens em grupos de WhatsApp. As informações eram registradas de forma não padronizada e a consulta do histórico geral não era eficiente.', N'01 - Imagens/02 - Depois/11224.jpeg', N'O relatório de turno passou a ser realizado por meio de um aplicativo desenvolvido em Power Apps, proporcionando um processo padronizado, estruturado e centralizado. O app garante rastreabilidade.', NULL, N'O problema foi resolvido.', N'O app melhorou a organização e rastreabilidade dos dados', 0, NULL, N'Produção / Tempo', '2026-07-13T00:00:00.000', '2026-07-17T11:29:36.000', N'81034239', NULL, NULL);
INSERT INTO #PVC VALUES (11225, N'81006571', N'81040190', N'SUPORTE DE IÇAMENTO EIXO MO03', 1, N'Others/Outros', N'Antes era necessário uso de uma chapa lisa para içamento do eixo podendo haver desprendimento durante a elevação do eixo', N'Eliminar improvisos', N'10362', N'01 - Imagens/01 - Antes/11225.jpeg', N'A atividade de elevação do eixo era executada de forma manual e sem a utilização de suporte específico, o que expunha os colaboradores a riscos de prensamento de membros superiores e inferiores, além da exposição direta à linha de fogo. 
INSERT INTO #PVC VALUES (11226, N'516619', N'552800', N'Melhoria da Descarga de Efluentes do Peneirador Suspenso', 2, N'No Replication/Sem replicação', N'O colaborador precisa realizar o descarte da água na pia várias vezes ao dia. Atividade gera desgaste físico.', N'Eliminar o trabalho manual de retirada do balde com efluente de descarte ', N'10366', N'01 - Imagens/01 - Antes/11226.jpeg', N'Durante os testes de granulometria no peneirador suspenso, o colaborador precisava retirar continuamente a água acumulada com um balde e descartá-la na pia diversas vezes ao dia. Essa atividade, apesar de realizada dentro dos limites operacionais estabelecidos, exigia esforço físico repetitivo, aumentando o risco de sobrecarga lombar, além da exposição a riscos ergonômicos, quedas e impactos.', N'01 - Imagens/02 - Depois/11226.jpeg', N'A melhoria implementada consistiu na instalação de tubulações de drenagem para conduzir os efluentes diretamente à canaleta de rejeitos, eliminando a necessidade de coleta e descarte manual da água em baldes. Com essa adequação, foi eliminado o esforço físico associado à atividade, reduzindo significativamente a exposição a riscos ergonômicos, sobrecarga lombar, quedas e impactos, além de proporcionar maior segurança e eficiência operacional.', NULL, N'A solução atingiu integralmente a meta proposta, eliminando o esforço físico associado à atividade.', N'A eliminação de atividades manuais repetitivas contribui significativamente para a redução dos riscos ergonômicos e para a preservação da saúde dos colaboradores.', 0, NULL, N'Agora não há necessidade de realizar conexões elétricas e se expor a riscos de choque em baixa tesão. A atividade ficou mais segura e rápida.', '2026-07-16T00:00:00.000', '2026-07-17T13:38:12.000', N'516619', NULL, NULL);
INSERT INTO #PVC VALUES (11227, N'520770', N'520770', N'FACILIDADE DE POSICIONAR', 1, N'Others/Outros', N'DIFICULDADE PARA INDENTIFICAR PONTO CORRETO NO POSICIONAMENTO DA CORREIA ', N'FACILITAR POSICIONAMENTO', N'10031', N'01 - Imagens/01 - Antes/11227.jpeg', N'por a correia rodar muito rápido, havia dificuldade para identificar o ponto a ser posicionado para reparo em determinado local', N'01 - Imagens/02 - Depois/11227.jpeg', N'Foi comprado spray amarelo para fazer marcação bem visivel para identificação durante a operação da correia.
INSERT INTO #PVC VALUES (11228, N'485273', N'485273', N'Implantação de Catraca Digital para Automação da Contagem de Refeições e Eliminação da Lista de Assinaturas', 1, N'Others/Outros', N'Atualmente, o controle e a contagem de refeições são realizados por meio de listas de assinatura em papel no refeitório. Esse processo é manual, demandando tempo para preenchimento, conferência e consolidação das informações, além de estar sujeito a falhas como assinaturas ilegíveis, esquecimentos, duplicidade de registros e divergências na contabilização das refeições.
INSERT INTO #PVC VALUES (11229, N'482858', N'81013746', N'Organização dos EPI''s nas prateleiras', 3, N'Others/Outros', N'EPIs acomodados nas prateleiras, ocupando espaço e aspecto de desordem', N'Deixar o local organizado, otimizar espaço', N'10257', N'01 - Imagens/01 - Antes/11229.jpeg', N'EPIs acomodados diretamente nas prateleiras, ocupando espaço de forma inadequada e sem um padrão definido de organização. Essa condição gera um aspecto visual de desordem, dificulta a identificação e o acesso rápido aos materiais.', N'01 - Imagens/02 - Depois/11229.jpeg', N'Foram instaladas caixas de acrílico nas prateleiras para armazenar os EPIs de forma organizada, reduzindo a desordem visual, facilitando a identificação dos itens e otimizando o espaço disponível.', NULL, N'Sim. A implementação das caixas de acrílico proporcionou melhor organização dos EPIs, diminuindo o tempo de procura e acesso aos materiais.', N'Soluções simples e de baixo custo, o acesso e a reposição dos itens, ', 0, NULL, N'A MUDANÇA GARANTE MUITO MAIS RESISTÊNCIA, EVITA QUEBRAS E DEIXA O EQUIPAMENTO COM MAIS DURABILIDADE E VIDA ÚTIL.', '2026-03-02T00:00:00.000', '2026-07-17T14:56:05.000', N'482858', NULL, NULL);
INSERT INTO #PVC VALUES (11230, N'522369', N'522369', N'LUMINÁRIA PORTÁTIL REFORÇADA ANTI-IMPACTO COM EXTENSÃO DE CABO 5 M NO PLUG INDUSTRIAL 220V', 2, N'Others/Outros', N'DIFICULDADE DE ILUMINAÇÃO NA FRENTE DE SERVIÇO DURANTE TURNO DIA E NOITE NA MOAGEM/TRANSPORTADORES', N'MELHORAR E PADRONIZAR ILUMINAÇÃO NA FRENTE DE SERVIÇO PARA ELÉTRICA/MECÂNICA/OPERAÇÃO', N'10031', N'01 - Imagens/01 - Antes/11230.jpeg', N'DIFICULDADE DE ILUMINAÇÃO NA FRENTE DE SERVIÇO MECÂNICA/ELÉTRICA/OPERAÇÃO NOS TURNOS DE DIA/NOITE NA MOAGEM/TRANSPORTADORES USINAS I,II,III.', N'01 - Imagens/02 - Depois/11230.jpeg', N'FOI DESENVOLVIDO UMA LUMINÁRIA DE LED REFORÇADA ANTI-IMPACTO COM EXTENSÃO DE 5 METROS COM PLUG INDUSTRIAL 220V. PARA MELHORAR E REFORÇAR ILUMINAÇÃO NAS FRENTES DE SERVIÇO COM BAIXA LUMINOTÉCNICA. COM CUSTO R$149,23 PARA FABRICAR ESTE MODELO DE EXTENSÃO DE CABO COM PLUG 220V.', NULL, N'SIM RESOLVIDO E COM APLICAÇÃO COM 6 LUMINÁRIAS PORTÁTIL FABRICADAS COM REFORÇO ANTI-IMPACTO COM CABO DE EXTENSÃO COM PLUG 220V.', N'MELHORIA CONTÍNUA PARA EXPOR MENOS NOSSOS COLABORADORES AO RISCOS OCUPACIONAIS', 1, 1, N'Facilidade em cruzar o pote correto com a tampa correta imediatamente.
INSERT INTO #PVC VALUES (11231, N'92000576', N'92000576', N'Implantação de Agente de IA para Consulta Inteligente do Histórico de Validações e Notas no Portal CMA Connect', 1, N'Projects/Projetos', N'Durante a validação dos alertas de telemetria no portal CMA Connect, os técnicos precisavam consultar diferentes bases para entender o histórico de tratativas já realizadas para um determinado alerta ou equipamento. Esse processo exigia buscas manuais em validações anteriores e em notas de manutenção, aumentando o tempo de análise e dificultando a identificação rápida das ações já executadas.', N'Disponibilizar de forma automática, durante a validação dos alertas, o histórico das últimas tratativas realizadas, incluindo validações anteriores, comentários técnicos, notas abertas ou encerradas e recomendações de atuação, apoiando a tomada de decisão do usuário.', N'10015', N'01 - Imagens/01 - Antes/11231.jpeg', N'Antes da melhoria, os técnicos realizavam a validação dos alertas utilizando apenas as informações do evento atual. Para consultar o histórico de ocorrências semelhantes era necessário acessar outras bases e procurar manualmente validações anteriores, comentários registrados e notas relacionadas ao equipamento. Esse processo consumia tempo e dificultava a identificação rápida das ações já executadas anteriormente.', N'01 - Imagens/02 - Depois/11231.jpeg', N'Foi desenvolvido um Agente de IA integrado ao portal CMA Connect, disponível na tela de validação de alertas. A solução realiza consultas automáticas na base de validações e na base de notas de manutenção, consolidando informações relevantes sobre tratativas anteriores do mesmo alerta ou equipamento. O recurso apresenta ao usuário o status da última validação, comentários registrados anteriormente, notas identificadas, status da nota, data de encerramento e recomendações para apoio à tomada de decisão. Dessa forma, o técnico consegue visualizar rapidamente o histórico completo da ocorrência sem necessidade de pesquisas manuais em outros sistemas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'✅ SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11232, N'92000576', N'92000576', N'Integração do Histórico de Intervenções do CMA Connect ao Painel de Telemetria Unificada para Rastreabilidade das Tratativas de Eventos', 1, N'Others/Outros', N'O Painel de Telemetria Unificada consolidava eventos de diversas plataformas de telemetria utilizadas na Mina de Salobo, como Vision Link, MineCare, MHT Monitor, My Sandvik. No entanto, apesar de apresentar informações detalhadas dos eventos, o painel não possuía visibilidade sobre as tratativas realizadas após a ocorrência dos alarmes. Dessa forma, os usuários conseguiam identificar os eventos, mas não tinham acesso ao histórico das intervenções executadas pelas equipes', N'Integrar ao Painel de Telemetria Unificada o histórico de intervenções registradas no CMA Connect, permitindo que os usuários visualizem as tratativas realizadas para cada evento e equipamento, promovendo rastreabilidade, padronização e apoio à tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/11232.jpeg', N'Antes da melhoria, o Painel de Telemetria Unificada apresentava informações detalhadas sobre os eventos dos equipamentos, incluindo criticidade, data, horário, frequência e evolução dos alarmes. Entretanto, não existia integração com o histórico de intervenções realizadas pelas equipes de telemetria. Para verificar se um evento já havia sido analisado, tratado ou se possuía nota associada, era necessário consultar outras fontes de informação, dificultando o entendimento completo do histórico do evento.', N'01 - Imagens/02 - Depois/11232.jpeg', N'Foi criada uma nova área no Painel de Telemetria Unificada dedicada ao histórico de intervenções registradas no CMA Connect. A solução integra automaticamente os eventos de telemetria às tratativas executadas pelas equipes do CMA e do CCM, permitindo visualizar informações como comentários técnicos, validações realizadas, abertura de notas, parada de equipamentos, responsáveis pela análise e demais ações registradas durante o tratamento do evento. Com essa integração, os usuários passaram a ter uma visão completa do ciclo do evento, desde sua ocorrência até as ações executadas para sua tratativa.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/57b68cba-2247-4f57-899a-a8bd95b9b745/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'✅ SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11233, N'92000576', N'92000576', N'Criação do Painel de Gestão de Coletas DynaPredict para Monitoramento e Priorização de Spots sem Comunicação', 1, N'Others/Outros', N'Os spots da plataforma DynaPredict são responsáveis pela coleta de dados de vibração dos equipamentos monitorados. Antes da implantação do painel, não existia uma ferramenta centralizada para acompanhar quais spots estavam sem comunicação, há quanto tempo estavam sem enviar dados e quais deveriam ser priorizados para atuação. Essa limitação dificultava a gestão dos ativos monitorados e aumentava o risco de equipamentos permanecerem longos períodos sem monitoramento de condição.', N'Desenvolver um painel de gestão que permita monitorar continuamente os spots sem coleta, identificar atrasos, definir prioridades de atuação e direcionar as ações para os responsáveis de cada frota, garantindo maior disponibilidade do monitoramento de vibração.', N'10015', N'01 - Imagens/01 - Antes/11233.jpeg', N'Antes da implantação do painel, não existia uma visão consolidada dos spots que estavam sem envio de dados de vibração. A identificação dependia de consultas manuais na plataforma DynaPredict, dificultando o acompanhamento dos atrasos e a definição de prioridades. Como resultado, alguns spots permaneciam longos períodos sem comunicação, comprometendo o monitoramento de condição dos equipamentos.', N'01 - Imagens/02 - Depois/11233.jpeg', N'Foi desenvolvido o painel Gestão de Coletas DynaPredict, integrado à plataforma Dynamox, permitindo monitorar todos os spots sem comunicação e classificá-los por faixas de atraso. O painel apresenta a distribuição dos spots por criticidade (até 30 dias, de 30 a 60 dias, de 60 a 90 dias e acima de 90 dias sem coleta), além da quantidade total de spots sem comunicação por frota. A solução permite filtrar informações por frota e identificar rapidamente o responsável pela tratativa, tornando o processo de gestão mais eficiente e direcionado. Dessa forma, a equipe consegue atuar de forma proativa para restabelecer a coleta de dados e garantir a continuidade do monitoramento de vibração dos equipamentos.
INSERT INTO #PVC VALUES (11234, N'92000576', N'92000576', N'Integração dos Eventos de Telemetria do MHT Monitor ao Portal CMA Connect para Centralização e Tratativa de Alertas Operacionais', 1, N'Others/Outros', N'O portal CMA Connect já recebia eventos provenientes de diversas fontes de telemetria utilizadas na Mina de Salobo, permitindo o registro, validação e acompanhamento das tratativas realizadas pelas equipes técnicas. Entretanto, os eventos do sistema MHT Monitor, responsável pelo monitoramento das perfuratrizes elétricas, ainda não estavam integrados ao portal, exigindo consultas e acompanhamentos separados e reduzindo a centralização das informações de telemetria.', N'Integrar os eventos do sistema MHT Monitor ao portal CMA Connect, permitindo que os alertas das perfuratrizes elétricas sejam recebidos, validados, tratados e acompanhados dentro da mesma plataforma já utilizada pelo CMA e pela Telemetria.', N'10015', N'01 - Imagens/01 - Antes/11234.jpeg', N'Antes da melhoria, o portal CMA Connect consolidava eventos provenientes de plataformas como MineCare, VisionLink e outras fontes de telemetria. Entretanto, os eventos gerados pelo MHT Monitor não estavam integrados ao processo de validação do portal. Como consequência, as ocorrências das perfuratrizes elétricas não seguiam o mesmo fluxo padronizado de acompanhamento, reduzindo a visibilidade e a centralização das informações.', N'01 - Imagens/02 - Depois/11234.jpeg', N'Foi realizada a integração dos eventos do sistema MHT Monitor ao portal CMA Connect, permitindo que os alertas gerados pelas perfuratrizes elétricas passem a seguir o mesmo fluxo de validação já utilizado para as demais fontes de telemetria. A partir da integração, os técnicos passaram a registrar comentários, validar eventos, informar tratativas realizadas, associar notas e realizar o acompanhamento completo das ocorrências diretamente no portal. Com isso, o CMA Connect ampliou sua capacidade de consolidação de eventos, tornando-se ainda mais aderente ao conceito de Centro Integrado de Eventos de Telemetria e Manutenção.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11235, N'92000576', N'92000576', N'Criação de Algoritmo para Identificação de Trocas de Componentes e Geração do Histórico Automatizado de Substituições da Frota', 1, N'Others/Outros', N'As informações de substituição de componentes estavam distribuídas em registros operacionais do SAP ECC, sem uma visão consolidada que permitisse identificar automaticamente quando um componente era removido e substituído por outro. Essa limitação dificultava análises de vida útil, aderência aos ciclos de troca, acompanhamento de componentes vencidos e rastreabilidade das substituições realizadas na frota.', N'Desenvolver algoritmos capazes de identificar automaticamente as substituições de componentes e disponibilizar essas informações em um painel dedicado, permitindo rastreabilidade, análise da vida útil dos componentes e acompanhamento da aderência aos planos de manutenção.', N'10015', N'01 - Imagens/01 - Antes/11235.jpeg', N'Antes da melhoria não existia uma visão estruturada do histórico de substituições dos componentes da frota. As informações estavam dispersas em registros operacionais e não havia uma lógica capaz de identificar automaticamente quando um componente era removido e substituído. Isso dificultava análises de confiabilidade, acompanhamento da vida útil dos componentes e avaliação da aderência aos ciclos de manutenção.', N'01 - Imagens/02 - Depois/11235.jpeg', N'Foi desenvolvido um algoritmo baseado em gatilhos dos registros do SAP ECC capaz de identificar automaticamente quando um componente é removido e substituído por outro. A partir dessa lógica foi criado um histórico automatizado de substituições, permitindo rastrear a data da troca, horímetro do componente, percentual de vida consumida, ciclo planejado, status da vida útil e demais informações relevantes. Esses dados passaram a alimentar uma nova página no painel Gestão de Componentes, disponibilizando indicadores por frota, equipamento e componente, além de apoiar análises de confiabilidade, aderência aos ciclos de manutenção e gestão do ciclo de vida dos ativos.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/5e15fa89-9fd0-4a3c-8f20-853460bc50c0/e6efa35044639a37e7e7?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11236, N'92000576', N'92000576', N'Integração dos Eventos de Telemetria do My Sandvik ao Portal CMA Connect para Centralização e Tratativa de Alertas Operacionais', 1, N'Others/Outros', N'O portal CMA Connect já consolidava eventos de telemetria provenientes de diferentes plataformas utilizadas na Mina de Salobo, permitindo o registro, validação e acompanhamento das tratativas realizadas pelas equipes técnicas. Entretanto, os eventos provenientes da plataforma My Sandvik ainda não estavam integrados ao portal, exigindo consultas separadas e dificultando a centralização das informações e das ações executadas pelas equipes de telemetria.', N'Integrar os eventos do My Sandvik ao portal CMA Connect, permitindo que os alertas gerados pelos equipamentos monitorados pela plataforma sejam recebidos, validados, tratados e acompanhados dentro do mesmo fluxo operacional utilizado pelas demais fontes de telemetria.', N'10015', N'01 - Imagens/01 - Antes/11236.jpeg', N'Antes da melhoria, os eventos gerados pela plataforma My Sandvik não faziam parte do fluxo operacional do CMA Connect. Dessa forma, os técnicos precisavam consultar fontes distintas para acompanhar ocorrências, reduzindo a centralização das informações e dificultando a rastreabilidade das análises e tratativas realizadas.', N'01 - Imagens/02 - Depois/11236.jpeg', N'Foi realizada a integração dos eventos da plataforma My Sandvik ao portal CMA Connect, permitindo que os alertas gerados pelos equipamentos monitorados sejam recebidos automaticamente e passem a seguir o mesmo fluxo de validação utilizado pelas demais fontes de telemetria. Após a integração, os técnicos passaram a registrar comentários, validar eventos, associar notas de manutenção, informar tratativas executadas e acompanhar todo o histórico das ocorrências diretamente no portal. Com isso, o CMA Connect ampliou sua cobertura operacional e passou a consolidar mais uma importante fonte de telemetria dentro de um ambiente único de gestão.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11237, N'81042217', N'81018130', N'Implantação de alerta visual e sonoro para prevenção de deslocamento do caminhão-pipa com a tomada de força (PTO) acionada', 2, N'Others/Outros', N'Foram registradas ocorrências recorrentes de quebra da tomada de força (PTO) do caminhão-pipa devido ao deslocamento do veículo com o sistema ainda acionado. A condição era causada principalmente pelo esquecimento do operador em desacionar a PTO antes da movimentação do equipamento, gerando falhas mecânicas, indisponibilidade do veículo e custos de manutenção.
INSERT INTO #PVC VALUES (11238, N'81037761', N'81037761', N'Alarme Crítico Prevenção de Desarme das Bombas por Nível Baixo nas Torres de Resfriamento dos Moinhos Salobo 3', 1, N'No Replication/Sem replicação', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos moinhos do Salobo 3, há oscilação na vazão das bombas. Essa condição pode não ser percebida em tempo hábil pelo técnico da sala de controle para acionar a operação e realizar a verificação em campo, podendo resultar no desarme das bombas e em cortes de alimentação da usina. Ocorre que existe um alerta mas o mesmo não está oferecendo tempo suficiente para evitar os desarmes e cortes de alimentação. ', N'Identificação rápida e proteção para evitar o desarme das bombas das torres de resfriamento dos moinhos, prevenindo interrupções e cortes de alimentação na usina.', N'10025', N'01 - Imagens/01 - Antes/11238.jpeg', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos moinhos do Salobo 3, há oscilações na vazão das bombas. Essa condição nem sempre é identificada em tempo hábil pelo técnico da sala de controle para acionar a equipe de operação e realizar a verificação em campo, podendo evoluir para o desarme das bombas e consequentes cortes de alimentação da usina. Atualmente, existe um alerta configurado para vazão inferior a 270 m³/h; entretanto, esse aviso não proporciona tempo de resposta suficiente para a adoção de ações corretivas, resultando na ocorrência de desarmes e impactos operacionais no processo.', N'01 - Imagens/02 - Depois/11238.jpeg', N'Foi implementado um alerta com acionamento a partir de 390 m³/h de vazão no bombeamento (vazão pela qual as bombas iniciam a cavitação), exibido na tela do supervisório (Água Refrigerada e na tela dos moinhos), para indicar ao técnico da sala de controle uma possível redução do nível das torres de resfriamento dos moinhos. Essa antecipação proporciona tempo hábil para acionar a operação e realizar a verificação em campo, mitigando o risco de desarme das bombas e evitando cortes de alimentação da usina.', NULL, N'Alarme funcional e com visibilidade na tela dos moinhos e na tela de água refrigerada das torres no supervisório da sala de controle toda vez que acontece a redução da vazão do bombeamento das torres dos moinhos.', N'A importância de evitar desarmes das bombas e cortes de alimentação da usina, garantindo maior segurança dos equipamentos, estabilidade operacional e produtividade.', 0, NULL, N'eliminar risco de projeção de corpo moedor.', '2026-07-17T00:00:00.000', '2026-07-18T03:16:52.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11239, N'81060357', N'81060357', N'Conector Seguro e Rápido para testes Elétricos', 1, N'Others/Outros', N'Anteriormente, quando necessário realizar um teste de funcionalidade com algum dispositivo eletrônico, como Gateways ou Elsys era necessário buscar um conector macho e realizar as conexões elétricas, o que tomava muito tempo, pois nem sempre as ferramentas, cabos ou conectores estavam a disposição. Nesses casos, eram utilizadas conexões rudimentares que não são seguras e poderiam ocasionar problemas.', N'Minimizar riscos e agilizar o processo de teste de Gateways e Antenas Elsys', N'10178', N'01 - Imagens/01 - Antes/11239.jpeg', N'Anteriormente, quando necessário realizar um teste de funcionalidade com algum dispositivo eletrônico, como Gateways ou Elsys era necessário buscar um conector macho e realizar as conexões elétricas, o que tomava muito tempo, pois nem sempre as ferramentas, cabos ou conectores estavam a disposição. Nesses casos, eram utilizadas conexões rudimentares que não são seguras e poderiam ocasionar problemas.', N'01 - Imagens/02 - Depois/11239.jpeg', N'Criamos uma pequena extensão que já conta com o conector macho e 2 conectores tipo Wago para facilitar a alimentação dos dispositivos. A atividade que antes levava vários minutos para ser feita corretamente ou era feita de forma rudimentar agora é feita de forma segura em menos de 1 minuto com 2 ''clicks''.', NULL, N'O problema foi resolvido por completo. A simples solução permite uma rápida conexão elétrica sem a necessidade de fazer ligações de tomada ou cabos. Agora a atividade é segura e ágil. ', N'Soluções simples aumentam a segurança e otimizam o tempo', 0, NULL, N'Condição de acesso seguro ao desnível para acesso ao chute.', '2026-07-17T00:00:00.000', '2026-07-18T10:42:05.000', N'81060357', NULL, NULL);
INSERT INTO #PVC VALUES (11240, N'542033', N'999359', N'CONTROLE DOS GUINCHOS AUXILIARES', 2, N'Projects/Projetos', N' O controle de acionamento do guincho auxiliar da máquina elétrica 7495 HD/HR não possuía dispositivo de parada de emergência integrado e apresentava menor resistência às condições operacionais da área.', N' Melhorar as condições de segurança, ergonomia e confiabilidade operacional do sistema de acionamento do guincho auxiliar da máquina 7495 HD/HR, reduzindo a exposição dos colaboradores a riscos, permitindo parada rápida em situações de emergência e aumentando a durabilidade do equipamento.', N'10324', N'01 - Imagens/01 - Antes/11240.jpeg', N' Anteriormente, o guincho auxiliar da máquina elétrica 7495 HD/HR era operado por um controle de acionamento que não possuía botoeira de emergência integrada, o que limitava a capacidade de interrupção imediata da operação em situações de risco.
INSERT INTO #PVC VALUES (11241, N'81009130', N'81009130', N'Dispositivo de Acesso seguro no telhado', 2, N'Projects/Projetos', N'Acesso improvisado ao telhado, sem padronização e sem atendimento ao PRO e risco elevado de escorregamento devido à ausência de uma superficie segura sem aderência.', N'Segura e estabilidade de acesso', N'10056', N'01 - Imagens/01 - Antes/11241.jpeg', N'Acesso improvisado ao telhado, sem padronização e sem atendimento ao PRO 026780de Acesso ao telhado e risco elevado de escorregamento devido à ausência de uma superfície segura sem aderência que garantisse estabilidade no acesso e interdição recorrente e atrasos nas atividades.', N'01 - Imagens/02 - Depois/11241.jpeg', N'Com objetivo de aumentar a segurança, eliminar improvisos e padronizar o acesso aos telhados, foi desenvolvido e implementado um dispositivo de acesso ao telhado, que garante maior estabilidade e segurança para o acesso entrada e saída dos colaboradores agilidade de montagens e fácil instalação.', NULL, N'Sim, maior segurança durante o acesso no telhado. ', N'Avaliação de atividades  prévia', 0, NULL, N'Instalar uma barreira fisica nas canaletas próximo a caldeiraria da moagem , e melhorar condições visuais do local. ', '2026-07-17T00:00:00.000', '2026-07-18T10:59:22.000', N'81009130', NULL, NULL);
INSERT INTO #PVC VALUES (11242, N'81057520', N'81057520', N'SUPORTE PARA BRAÇO MECÂNICO DO PULVERIZADOR', 2, N'Projects/Projetos', N'Antes, contávamos apenas com um pequeno gancho para essa função, que por ser frágil, acabava se danificando e  com isso vindo a quebrar com frequência e gerando manutenções constantes.', N'AJUDAR NA DURABILIDADE DO EQUIPAMENTO', N'10129', N'01 - Imagens/01 - Antes/11242.jpeg', N'Antes, contávamos apenas com um pequeno gancho para essa função, que por ser frágil, acabava se danificando e  com isso vindo a quebrar com frequência  gerando manutenções constantes.', N'01 - Imagens/02 - Depois/11242.jpeg', N'Agora, implementamos uma solução com lona resistente em cima do pulverizador, que garante muito mais resistência, durabilidade evitando arranhões e segurança no suporte do equipamento, evitando quebras inesperadas e otimizando nossa operação.', NULL, N'ANTES USAVAMOS UM GANCHO FRÁGIL PARA O DESCANÇO DO BRAÇO MECÂNICO QUE QUEBRAVA COM FREQUÊNCIA', N'DURABILIDADE DOS EQUIPAMENTOS', 0, NULL, NULL, '2026-07-17T00:00:00.000', '2026-07-18T13:59:23.000', N'81057520', NULL, NULL);
INSERT INTO #PVC VALUES (11243, N'81057520', N'81057520', N'PADRONIZAÇÃO E IDENTIFICAÇÃO DE POTES DE AMOSTRAGEM', 1, N'Others/Outros', N'Situação Inicial (Antes)
INSERT INTO #PVC VALUES (11244, N'1008564', N'1009736', N'Post SDS for HarborLite ', 2, N'Refining/Refino', N'SDS Not Posted', N'Post SDS', N'0', N'01 - Imagens/01 - Antes/11244.jpeg', N'NO SDS Posted', N'01 - Imagens/02 - Depois/11244.jpeg', N'SDS Posted', NULL, N'YES', N'Post for the Safe handling of a product', 0, NULL, NULL, '2026-07-17T00:00:00.000', '2026-07-18T17:09:01.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (11245, N'1008564', N'1009736', N'Post SDS for Barium Hydroxide', 2, N'Refining/Refino', N'SDS Not Posted
INSERT INTO #PVC VALUES (11246, N'1008449', N'1008449', N'Copper secondary separator teflon replacement', 1, N'No Replication/Sem replicação', N'Secondary separators not going down far enough to strip the copper off', N'More effeciant copper stripping', N'0', N'01 - Imagens/01 - Antes/11246.jpeg', N'Copper at times become extremely sticky and hard to strip. Secondary separators are there to help but the Teflon pieces are not lowering enough to take the copper off the bottom', N'01 - Imagens/02 - Depois/11246.jpeg', N'New Teflon pieces made up and installed about 4" longer to be able to reach and strip the copper off', NULL, N'Yes problem solved', N'Troubleshooting with maintenance is key', 0, NULL, N'- Equipe impactada diariamente pela mensagem de segurança;
INSERT INTO #PVC VALUES (11247, N'81028405', N'81028405', N'Dimensionamento do Parque Reserva de PTO da Frota DR416i', 1, N'Others/Outros', N'Não existia um critério técnico definido para o dimensionamento do parque reserva de PTO da frota DR416i. As decisões relacionadas à quantidade de conjuntos reserva eram realizadas sem uma metodologia padronizada, gerando risco de indisponibilidade por falta de material ou investimento excessivo em ativos de baixa utilização.', N'Determinar o parque reserva ideal de PTO para a frota DR416i por meio de metodologia de engenharia e confiabilidade, garantindo o atendimento das demandas de manutenção com o menor risco de indisponibilidade operacional e otimização dos recursos investidos em estoque.', N'10015', N'01 - Imagens/01 - Antes/11247.jpeg', N'A frota DR416i não possuía um estudo técnico para definição do parque reserva de PTO. A quantidade de conjuntos disponíveis era baseada em percepção operacional e experiência prática, sem uma metodologia padronizada para avaliar a necessidade real da frota.
INSERT INTO #PVC VALUES (11248, N'1008360', N'1014251', N'Lime Feluwas Vale Form Update', 3, N'Others/Outros', N'During filling out the vale form the stormwater valve was said to always be connected to #1 but the hose connection often changes ', N'Update form to reflect changes ', N'0', N'01 - Imagens/01 - Antes/11248.jpeg', N'During filling out the vale form the stormwater valve was said to always be connected to #1 but the hose connection often changes from #1 to #2 . (NO BEFORE PIC)', N'01 - Imagens/02 - Depois/11248.jpeg', N'Valeform was updated to show an option for which Lime Feluwa the stormwater hose is connected too ', NULL, N'Yes', N'None', 0, NULL, N'Ability to refill cakewash 4 using flush/sample point', '2026-07-17T00:00:00.000', '2026-07-18T19:57:21.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11249, N'81049566', N'81017006', N'MANGOTE SEGURO', 2, N'Concentration/Concentração', N'Bomba de óleo com Mangote de recalque exposto, em caso de rompimento, risco de projetar em pessoas.', N'eliminar o risco de contato em caso de rompimento ', N'10362', N'01 - Imagens/01 - Antes/11249.jpeg', N'Mangote de Recalque da bomba de óleo Era exposto, com risco de SE em caso de rompimento projete óleo pressurizado em pessoas. ', N'01 - Imagens/02 - Depois/11249.jpeg', N'Fabricado capa de proteção para o corpo do mangote, removível com parafuso , protegendo o mangote de projeção em caso de rompimento, eliminando o risco de dano a pessoas. ', NULL, N'Foi instalado capa de proteção para o mangote, caso haja rompimento do mesmo nao ira atingir pessoas.', N'Segurança no caso de rompimento', 0, NULL, N'Conexões até 10 vezes mais rápidas com mais segurança, organização e ergonomia, o que evita a drenagem forçada de água da mina ficar inoperante  por mau contado das conexões e demoras', '2026-07-13T00:00:00.000', '2026-07-19T10:07:15.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11250, N'81049566', N'81012442', N'Suporte tubulaçao', 1, N'Others/Outros', N'Frequente queda da tubulação de agua dentro do predio da moagem , gerando vazamento de agua nos andares inferiores.', N'eliminar queda da tubulação .', N'10362', N'01 - Imagens/01 - Antes/11250.jpeg', N'Tubulação do esgoto no 4 andar do prédio da moagem sem sustentação , caindo, vazamento agua nos andares inferiores. ', N'01 - Imagens/02 - Depois/11250.jpeg', N'Fabricado e instalado suporte para sustentar tubulação e evitar vazamentos de esgoto no local.', NULL, N'Fixado tubulação de forma permanente, eliminando o risco de soltar. ', N'Suporte fixo. ', 0, NULL, N'Tempo de análise quando requisitados', '2026-07-14T00:00:00.000', '2026-07-19T10:18:27.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11251, N'81049566', N'502163', N'Janela de proteção', NULL, N'Concentration/Concentração', N'Chute de alimentação de bolas do sag, sem proteção na janela de visitar, permitindo a projeção de corpo moedores.', N'eliminar risco de projeção de corpo moedor', N'10362', N'01 - Imagens/01 - Antes/11251.jpeg', N'Alimentador de bolas do SAG sem proteção na janela de visita, projetando corpo moedores para aréa externa ', N'01 - Imagens/02 - Depois/11251.jpeg', N'Fabricado e instalado janela de proteção para o chute dosador de bolas, eliminando risco de projeção de corpo moedor. ', NULL, N'instalado janela de visita no chute dosador, eliminando o risco de projeção de corpo moedor durante operação. ', N'Protegido o risco de projeção ', 0, NULL, N'Agilidade no processo de análise', '2026-07-15T00:00:00.000', '2026-07-19T10:33:23.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11252, N'81049566', N'502163', N'Acesso Seguro TC5', 3, N'Crusher/Britadeira', N'Ausência de Escada para acessar o acionamento da 2301TC05 , desnível de 80cm para descer sem degrau de acesso. ', N'Fabricar escada para acesso seguro', N'10362', N'01 - Imagens/01 - Antes/11252.jpeg', N'Ausência de acesso Seguro para acessar o chute de descarga da correia 2301TC05.', N'01 - Imagens/02 - Depois/11252.jpeg', N'Fabricado escada com dois degraus para acesso ao desnível do chute de acionamento da 2301TC05.', NULL, N'Fabricado escada para acesso seguro ao chute da 2301TC05.', N'Mais seguro acesso local', 0, NULL, N'Garantir maior controle, rastreabilidade e padronização das solicitações de remoção de abelhas, pragas e vetores no Complexo Sossego, assegurando que todas as demandas sejam registradas, acompanhadas e concluídas de forma eficiente. Espera-se aumentar a conformidade com os requisitos de Saúde, Segurança e Meio Ambiente (SSMA), por meio da aprovação obrigatória para atividades críticas, além de melhorar a qualidade dos serviços prestados por meio do monitoramento dos atendimentos e da pesquisa de satisfação dos usuários. Como resultado, busca-se fortalecer a gestão operacional, reduzir falhas de processo e promover a melhoria contínua dos serviços.', '2026-07-09T00:00:00.000', '2026-07-19T11:09:40.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11253, N'81049566', N'502163', N'Linha de Agua ', 1, N'Crusher/Britadeira', N'Ausência de ponto de Agua para lavagem na caldeiraria do revezamento na Usina. ', N'Facilitar a limpeza da caldeiraria e peças', N'10362', N'01 - Imagens/01 - Antes/11253.jpeg', N'Ausência de ponto de agua para limpeza da Caldeiraria, lavar peças e outros no local. ', N'01 - Imagens/02 - Depois/11253.jpeg', N'Instalado tubulação e linha de agua para limpeza da caldeiraria e serviços. ', NULL, N'Instalado ponto fixo de agua na caldeiraria.', N'Maior facilidade para limpeza do local', 0, NULL, N'Maior autonomia dos usuários;
INSERT INTO #PVC VALUES (11254, N'81049566', N'502163', N'Aréa organizada', 3, N'Crusher/Britadeira', N'Ausência de barreira física na área próximo a caldeiraria da moagem . ', N'Instalar Barreira para isolar canaleta', N'10362', N'01 - Imagens/01 - Antes/11254.jpeg', N'Ausência de uma barreira para proteger canaleta, com riscos de quedas ao passar próximo .', N'01 - Imagens/02 - Depois/11254.jpeg', N'Instalado uma barreira próxima a área próximo a aréa da caldeiraria protegendo a canaleta e melhorando visualmente o ambiente.', NULL, N'Instalado barreira fisica próximo as canaletes e melhorado a condição visual da área. ', N'Melhor aspecto visual e seguraça', 0, NULL, N'at minimum we are expecting safety improvement', '2026-07-08T00:00:00.000', '2026-07-19T11:49:47.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11255, N'81004794', N'81004794', N'Waste Transportation Utilization ', 1, N'Others/Outros', N'Waste in production areas becoming expensive to transport in Waste Containers.  As well, waste container availability has been a problem', N'Reduce cost, maximize efficiency', N'0', N'01 - Imagens/01 - Antes/11255.jpeg', N'Process waste had accumulated in the EW area in significant quantities due to a lack of available waste containers. The waste consists of nickel debris packaged in large super sacks. Because this material is relatively lightweight, it does not utilize container capacity efficiently and would require up to six waste containers for this cleanup alone.', N'01 - Imagens/02 - Depois/11255.jpeg', N'We sourced a Semi Dump B-Train tractor trailer through our waste management contractor to support the cleanup. The two waste boxes on the unit can accommodate large volumes of material and hold up to 36 tonnes.
INSERT INTO #PVC VALUES (11256, N'550443', N'550443', N'ZERO DEFEITO', 1, N'Others/Outros', N'O desviador da peneira 01/01R apresentava falhas recorrentes devido à movimentação excessiva do mecanismo, ocasionando quebra do sensor e perda de leitura. Essas ocorrências provocavam paradas frequentes do equipamento, impactando diretamente a disponibilidade operacional e a produtividade da planta. Além disso, a substituição do sensor demandava em algumas atuações mais de três horas de intervenção, expondo a equipe a um ambiente com diversos obstáculos e aumentando os riscos durante a execução da atividade.', N'Evitar paradas desnecessárias', N'10245', N'01 - Imagens/01 - Antes/11256.jpeg', N'O desviador da peneira 01/01R apresentava falhas recorrentes devido à movimentação excessiva do mecanismo, ocasionando quebra do sensor e perda de leitura. Essas ocorrências provocavam paradas frequentes do equipamento, impactando diretamente a disponibilidade operacional e a produtividade da planta. Além disso, a substituição do sensor demandava em algumas atuações mais de três horas de intervenção, expondo a equipe a um ambiente com diversos obstáculos e aumentando os riscos durante a execução da atividade.', N'01 - Imagens/02 - Depois/11256.jpeg', N'Com o objetivo de eliminar essas ocorrências, foi desenvolvida e implantada uma melhoria consistindo na instalação de um guia para limitar a movimentação lateral do desviador, evitando o desalinhamento com consequente perda de leitura do sensor e quebra do sensor. Além disso, foi confeccionado um novo suporte para o acionamento do sensor, proporcionando maior estabilidade e confiabilidade ao equipamento.
INSERT INTO #PVC VALUES (11257, N'484637', N'81058959', N'Eliminação da quebra da placa limitadora (7Y1746) do tensor da esteira.', 1, N'Projects/Projetos', N'Durante a operação do equipamento, a placa limitadora de curso do ajustador do tensor da esteira (P/N 7Y1746) sofreu quebra e/ou deformação, perdendo sua função de limitar o movimento do conjunto. Em consequência, o ajustador do tensor passou a girar livremente em seu próprio eixo, atingindo até 360°, o que impossibilitou o correto posicionamento do ponto de aplicação da propulsora de graxa. Devido à falta de acesso para execução do procedimento de tensionamento da esteira, o sistema de ajuste ficou inoperante, comprometendo a manutenção da tensão adequada da esteira e exigindo a substituição do tensor.', N'Garantir a integridade e o correto funcionamento do sistema de tensionamento da esteira, por meio da substituição da placa limitadora de curso (P/N 7Y1746) e/ou do tensor, restabelecendo o controle angular do ajustador e permitindo o acesso adequado para aplicação de graxa, assegurando a manutenção da tensão correta da esteira e a confiabilidade operacional do equipamento.', N'10139', N'01 - Imagens/01 - Antes/11257.jpeg', N'Durante a operação do equipamento, a placa limitadora de curso (P/N 7Y1746) do ajustador do tensor da esteira apresentava quebra e/ou deformação, permitindo a rotação livre do ajustador em até 360°. Essa condição impossibilitava o acesso da propulsora de graxa para o tensionamento da esteira, comprometendo o funcionamento do sistema de ajuste, a manutenção da tensão adequada e ocasionando a necessidade de substituição do tensor.', N'01 - Imagens/02 - Depois/11257.jpeg', N'Após a implementação da melhoria, o sistema de ajuste do tensor da esteira passou a contar com um limitador de curso íntegro e funcional, impedindo a rotação excessiva do ajustador e mantendo seu correto posicionamento. Com isso, o ponto de aplicação da propulsora de graxa permaneceu acessível, permitindo a realização do tensionamento da esteira de forma segura e eficiente. A melhoria restabeleceu o controle angular do ajustador, eliminou a necessidade de substituições prematuras do tensor associadas à quebra da placa 7Y1746 e aumentou a confiabilidade e disponibilidade operacional do equipamento.', NULL, N'A meta inicial foi eliminar as falhas causadas pela quebra da placa limitadora de curso (7Y1746), garantindo o correto funcionamento do ajustador do tensor da esteira e a execução adequada do tensionamento. Após a implementação da melhoria, o ajustador passou a operar dentro do limite previsto, sem rotação excessiva, mantendo o ponto de aplicação da propulsora de graxa acessível para os ajustes necessários. Com isso, foi eliminada a condição que provocava a indisponibilidade do sistema de tensionamento, reduzindo a necessidade de substituição do tensor e aumentando a confiabilidade e a disponibilidade operacional do equipamento.', N'Inspeções preventivas e melhorias no sistema de travamento da placa limitadora (7Y1746) evitam falhas no tensionamento da esteira, reduzem paradas não programadas e aumentam a confiabilidade do conjunto tensor.', 75902, 1, N'depois da criação do nosso projeto na ultima reunião que teve CSP de 2025, r4eunião que antes demorava 2 dias para reavaliar todos os colaboradores da gerencia foi gasto somente 1 dia. ', '2026-07-18T00:00:00.000', '2026-07-19T17:11:07.000', N'484637', NULL, NULL);
INSERT INTO #PVC VALUES (11258, N'202615', N'202615', N'Alternate water source', 1, N'Refining/Refino', N'Building 211 has had numerous freeze-up issues with the process water entering the washbay  ', N'maintain water flow', N'0', N'01 - Imagens/01 - Antes/11258.jpeg', N'Building 211 has had numerous freeze-up issues with the process water entering the washbay. This delays and prevents regular cleaning maintenance of the mobile equipment, cleanup of the washbay floors and walls and the supply to the boot brush washer which leads to environmental concerns when exiting the building.', N'01 - Imagens/02 - Depois/11258.jpeg', N'An alternate source of potable water was identified on the underground right outside the building that had been connected but never commissioned since it was installed during construction. The curb stop was opened, and a bi-pass line was run to the existing hose reels providing an uninterrupted source should the process fail again.', NULL, N'Yes, the curb stop was opened, and a bi-pass line was run to the existing hose reels providing an uninterrupted source should the process fail again.', N'Interruptions to the water supply here leads to PM''s on mobile equipment not being completed and environmental risks  ', 199, 3, N'Change made to all Gas Sensors on Site.', '2026-07-12T00:00:00.000', '2026-07-19T22:40:37.000', N'202615', NULL, NULL);
INSERT INTO #PVC VALUES (11259, N'123307', N'533479', N'SINALIZAÇÃO SEMÁFORO PELA VIDA', 2, N'Others/Outros', N'A comunicação de segurança não estava visível em pontos estratégicos da usina e mina. Sem placas de alertas nos acessos, áreas operacionais e salas de troca de turno, os colaboradores não tinham um lembrete constante das atitudes seguras sobre segurança.', N'Reforçar a cultura de segurança e aumentar a percepção de risco dos colaborares  através da comunicação visual.', N'10054', N'01 - Imagens/01 - Antes/11259.jpeg', N'A comunicação de segurança não estava visível em pontos estratégicos da usina e mina. Sem placas de alertas nos acessos, áreas operacionais e salas de troca de turno, os colaboradores não tinham um lembrete constante das atitudes seguras sobre segurança.', N'01 - Imagens/02 - Depois/11259.jpeg', N'Foi realizada instalação de placas( 30 placas) com alerta de segurança com o tema: "Semáforo pela Vida"  em pontos de grande circulação da usina e na área de troca de turno dos colaboradores da mina, a ação contemplou portões de acesso, escadas, áreas operacionais e salas CCB.', NULL, N'Sim, o objetivo foi 100% alcançado. As placas foram instaladas em todas as área previstas. Agora o colaborador e impactado pela mensagem" PARE, ATENÇAO e SIGA"', N'Pequenas ações de comunicação visual geram grande impacto para cultura de segurança.', 0, NULL, N'This solution eliminated several hours of welding and reworking exhaust systems to perform diesel particulate testing.', '2026-07-03T00:00:00.000', '2026-07-20T00:01:02.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (11260, N'1009299', N'1009299', N'IR1 Floc Dilution pump labels', 1, N'Others/Outros', N'Pumps were not labeled making it difficult to identify ', N'Easy identification of pumps', N'0', N'01 - Imagens/01 - Antes/11260.jpeg', N'No labels on front of pumps', N'01 - Imagens/02 - Depois/11260.jpeg', N'Added labels to front of pumps for easy identification', NULL, N'Yes, pumps are now labeled', N'Labels are effective for easy identification', 0, NULL, N'Redução no backlog de demandas vencidas', '2026-07-07T00:00:00.000', '2026-07-20T00:50:43.000', N'1009299', NULL, NULL);
INSERT INTO #PVC VALUES (11261, N'1009299', N'1009299', N'Cakewash 4 Flush/Sample point ', 1, N'Others/Outros', N'Cakewash 4 had no flush/sample point', N'Add flush point to refill tank', N'0', N'01 - Imagens/01 - Antes/11261.jpeg', N'No flush/sample point on cakewash 4 ', N'01 - Imagens/02 - Depois/11261.jpeg', N'Added flush/sample point to suction drain for refilling of tank', NULL, N'Yes, flush/sample point was added', N'Added flush/sample point', 0, NULL, N'Having this setup will make it easier to collect floc samples rather than looking for a marker or label maker. it also makes it easier to see what is left in the tray rather than in a box.', '2026-07-08T00:00:00.000', '2026-07-20T00:57:36.000', N'1009299', NULL, NULL);
INSERT INTO #PVC VALUES (11262, N'81055392', N'505896', N'Conecta +', 1, N'Projects/Projetos', N'Atividade de conectar e desconectar os cabos dos instrumentos de medição de temperatura e nível  de agua das bombas que drenam a água  no fundo das cavas (SUMP)  Geralmente são 4 destes equipamentos,  o que seriam 60 conexões  de cabos de 0,5mm² para realizar, o tempo de execução para esta manobra é cerca de 40 minutos para alguém experiente, pois a cada retorno de desmonte, é necessário prensar os terminais tubulares de 0,5mm² para conectar nos 60 bornes, outro problema é o desconforto físico devido a falta da ergonomia durante a execução, ainda causando paradas inesperadas no bombeamento devido a falha nas conexões ', N'Conectar e desconectar cabos de instrumentos com extrema velocidade ', N'10242', N'01 - Imagens/01 - Antes/11262.jpeg', N'Atividade de conectar e desconectar os cabos dos instrumentos de medição de temperatura e nível  de agua das bombas que drenam a água  no fundo das cavas (SUMP) é bastante rotineira, 3 cabos para PT100 e 3 cabos para Nível de 0,5mm², cada bomba possui Três PT100 e Dois de nível, totalizando 15 cabos para conectar, geralmente são 4 destes equipamentos,  o que seriam 60 conexões para realizar, o tempo de execução para esta manobra é cerca de 40 minutos para alguém experiente, pois a cada retorno de desmonte, é necessário prensar os terminais tubulares de 0,5mm² para conectar nos 60 bornes, outro problema é o desconforto físico devido a falta da ergonomia durante a execução  ', N'01 - Imagens/02 - Depois/11262.jpeg', N'A conexão e desconexão dos sensores, não impactam mais no retorno do bombeamento  e também na ergonomia do executante , com a utilização do conector Wago que na sua especificação suporta cabos de 0,4 a 4mm², 32 Amperes e 40KG de tração sem romper. Pois são realizadas sem a necessidade de prensar terminais nos 60 cabos  de 0,5mm²  e com apenas um click mecânico já conecta ou desconecta o cabo, evitando também o desgaste dos bornes ', N'https://www.wago.com/br/conexao/conectores-de-emenda/linha221/221inline', N'Resolvido, tempo de conexão era realizado entre 30 hà 50 minutos, com os conectores in-line isso é realizado entre 3 a 7 minutos ', N'Projetar pensando na manutenção aumenta a segurança, reduz o tempo de parada e melhora a confiabilidade do sistema', 0, NULL, NULL, '2026-06-22T00:00:00.000', '2026-07-20T01:18:50.000', N'81055392', NULL, NULL);
INSERT INTO #PVC VALUES (11263, N'532872', N'532872', N'Dashboard de Cobertura da Programação', 1, N'Others/Outros', N'Inexistência de monitoramento detalhado', N'Realizar monitoramento do % programamdo da capacidade dos centros de trabalho', N'10179', N'01 - Imagens/01 - Antes/11263.jpeg', N'Não existia um dashboard dedicado ao monitoramento da cobertura da capacidade programada, dificultando o acompanhamento e a análise dos resultados.', N'01 - Imagens/02 - Depois/11263.jpeg', N'Foi desenvolvido e disponibilizado um dashboard corporativo de Cobertura da Programação, permitindo o monitoramento contínuo da capacidade planejada de manutenção por meio de indicadores visuais e interativos.
INSERT INTO #PVC VALUES (11264, N'532872', N'532872', N'Dashboard de Trabalho Reativo', NULL, N'Others/Outros', N'Inexistência de Dashboard para monitoramento do indicador', N'Desenvolver dashboard para monitoramento do indicador', N'10081', N'01 - Imagens/01 - Antes/11264.jpeg', N'Não existia um dashboard específico para monitoramento do Percentual de Trabalho Reativo, o que dificultava a visibilidade dos indicadores de manutenção corretiva, a identificação das principais causas dos desvios e o acompanhamento do desempenho por área, gerência e equipe. As análises eram realizadas de forma descentralizada, demandando maior esforço na consolidação das informações e reduzindo a agilidade na tomada de decisão.', N'01 - Imagens/02 - Depois/11264.jpeg', N'Dashboard de Trabalho Reativo implantado para monitorar indicadores de manutenção não planejada, com análises por área, equipe e ativo, Pareto de desvios e apoio à tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/99315b71-44b1-4677-ae95-943eeb1be34c/82bc44eee62a58d704d2?experience=power-bi', N'sim, indicador monitorado e em implementação na rotina.', N'Monitorar para gerenciar', 0, NULL, N'This will be a temporary fix untill the pipe can repaired with proper materials ', '2026-07-17T00:00:00.000', '2026-07-20T09:15:21.000', N'532872', NULL, NULL);
INSERT INTO #PVC VALUES (11265, N'504475', N'871194', N'APLICATIVO - Gestão de Solicitações de Remoção de Abelhas e Controle de Pragas e Vetores com Fluxo de Aprovação SSMA no Complexo Sossego', 1, N'Others/Outros', N'Qual é o problema?
INSERT INTO #PVC VALUES (11266, N'92000100', N'92000100', N'Aplicativo de salas', 1, N'Others/Outros', N'Desperdício de tempo. Trabalho manual repetitivo.', N'Otimizar agendamento de salas', N'10234', N'01 - Imagens/01 - Antes/11266.jpeg', N'Antes, para realizar o agendamento de salas, o solicitante precisava entrar em contato com o administrador responsável para verificar a disponibilidade na agenda do Outlook. Todo o processo de reserva dependia dessa consulta, pois somente o administrador possuía acesso à visualização da disponibilidade das salas. Como consequência, havia impacto na rotina de trabalho, já que o administrador precisava interromper suas atividades frequentemente para atender às solicitações e consultar a agenda antes de efetivar os agendamentos.', N'01 - Imagens/02 - Depois/11266.jpeg', N'Foi replicado o aplicativo de agendamento de salas já utilizado no Prédio Jequitibá, proporcionando mais autonomia e agilidade aos usuários.
INSERT INTO #PVC VALUES (11267, N'81013125', N'81013125', N'Contractor Performance', 1, N'Others/Outros', N'Contractor performance has been an issue in the past in multiple areas of the vendor''s accountability. During contract renewal process, we moved to a performance management system for the service.', N'Increase contractor performance', N'10026', N'01 - Imagens/01 - Antes/11267.jpeg', N'Previously there was not a lot of "teeth" in the contract that allowed Vale to set targets that had commercial impact on the contractor. ', N'01 - Imagens/02 - Depois/11267.jpeg', N'We have written into the scope a sliding scale for performance that will commercially impact the vendor based on underperformance and outperformance', NULL, N'We have currently written performance management into the Scope of Work, final results to be followed up', N'We need to bring back performance management', 0, NULL, N'flash vessel overflow line reinstatement to the original configuration, allows just one Autoclave, as opposed to two, come down for the necessary flash vessel overflow line cleanings when required   ', '2026-07-15T00:00:00.000', '2026-07-20T10:09:08.000', N'81013125', NULL, NULL);
INSERT INTO #PVC VALUES (11268, N'81040247', N'81040247', N'Fluxograma de Exceção – Montagem de Andaimes Provisórios ', 2, N'Others/Outros', N'Anteriormente, não havia um controle efetivo sobre a quantidade de barreiras físicas montadas no site Salobo. Como consequência, recursos de andaime eram frequentemente desviados de sua finalidade original e utilizados como solução provisória, sem tratar a causa raiz dos problemas, o que contribuía para a recorrência das ocorrências.', N'Redução de Custo ', N'10178', N'01 - Imagens/01 - Antes/11268.jpeg', N'Anteriormente, não havia um controle efetivo sobre a quantidade de barreiras físicas montadas no site Salobo. Como consequência, recursos de andaime eram frequentemente desviados de sua finalidade original e utilizados como solução provisória, sem tratar a causa raiz dos problemas, o que contribuía para a recorrência das ocorrências.', N'01 - Imagens/02 - Depois/11268.jpeg', N'Foi implementada uma nova diretriz para o controle de solicitações de barreiras físicas provisórias com andaime. A partir de agora, toda instalação deverá ser previamente aprovada por Gilberto Benigno, mediante envio de solicitação formal contendo justificativa técnica, evidência fotográfica, centro de custo (CC) e prazo para implementação da solução definitiva.
INSERT INTO #PVC VALUES (11269, N'473024', N'473024', N'MACRO INSERIR VPTS, ATR E PRO EM LISTA TAREFA DE PLANOS', 1, N'Others/Outros', N'Foi identificado que os planos de manutenção preventiva da usina estão configurados sem a associação obrigatória dos documentos de suporte (VPTS, ART e PRO). Essa condição resulta em ineficiência operacional e aumento do esforço administrativo das equipes de Planejamento e Programação, devido à necessidade de inclusão manual desses documentos em todos os ciclos de programação das ordens de manutenção, elevando o risco de inconsistências e impactando a produtividade do processo.', N'95% DOS PLANOS DA MOAGEMCOM VPTS, ART E PRO', N'10178', N'01 - Imagens/01 - Antes/11269.jpeg', N'Foi identificado que os planos de manutenção preventiva da usina estão configurados sem a associação obrigatória dos documentos de suporte (VPTS, ART e PRO). Essa condição resulta em ineficiência operacional e aumento do esforço administrativo das equipes de Planejamento e Programação, devido à necessidade de inclusão manual desses documentos em todos os ciclos de programação das ordens de manutenção, elevando o risco de inconsistências e impactando a produtividade do processo.', N'01 - Imagens/02 - Depois/11269.jpeg', N'Foi desenvolvida uma Macro em Excel integrada a um SAP Script para automatizar a inclusão de VPTs, ARTs e PROs nas listas de tarefas dos planos preventivos por meio da transação ZOVOPM051. A solução eliminou atividades repetitivas e aumentou significativamente a produtividade, permitindo a inserção de até 100 VPTs, ARTs e PROs em aproximadamente 6 segundos, após o preenchimento das informações pelo usuário.', NULL, N'O problema identificado no processo foi corrigido com total exatidão por meio da solução desenvolvida, eliminando inconsistências e garantindo a execução confiável das atividades. Os resultados alcançados atenderam integralmente aos objetivos definidos, atingindo 100% da meta estabelecida no projeto inicial e proporcionando maior eficiência operacional, padronização e redução de erros.', N'A automação é uma ferramenta poderosa para aumentar a produtividade, reduzir erros e otimizar processos operacionais.', 0, NULL, N'A implementação da solução resultou em maior controle, padronização e confiabilidade das informações relacionadas ao Head Count de Terceiros do Complexo Sossego. Com a automatização do processo, a centralização do recebimento dos dados, a utilização de formulários padronizados e as validações automáticas realizadas pelo Power BI, foi possível reduzir inconsistências, eliminar retrabalho e aumentar a eficiência operacional.
INSERT INTO #PVC VALUES (11270, N'81034557', N'81034557', N'Score de Operadores ', 1, N'Concentration/Concentração', N'A supervisão operacional possuía informações de desempenho dos operadores dispersas em diversas bases e controles, dificultando:
INSERT INTO #PVC VALUES (11271, N'1008535', N'1008535', N'Cl2 & H2S Gas Sensors Reading Negative Values', 2, N'Underground/Subterrâneo', N'During an OH&S visit is was noted that a Chlorine Gas Detector in EW Bay was reading -.28ppm but DCS was showing 0 PPM.  When detectors drift into  the negative region or an improper zero is performed then the negative reading will not be displayed and  Ops will not be aware of required maintenance and risk of lower then actual gas readings.', N'Read Negative Values  to Warn Operations Maintenance is Required', N'0', N'01 - Imagens/01 - Antes/11271.jpeg', N'DCS reading 0 when Gas Sensor in field drifted to a Negative Value.', N'01 - Imagens/02 - Depois/11271.jpeg', N'DCS now  reads negative values.  Alarm added to notify Control Room Operator when reading goes below -.3ppm.  Maintenance can be advised sooner to perform calibration.  Less Risk of reading lower then actual concentrations of Gas.', NULL, N'Previously Negative Readings would not be seen until regularly scheduled maintenance.  With this change maintenance can be performed sooner when needed and gives visibility to the Control Room Operator.', N'Negative Gas Reading & Alarm is Beneficial to Operations.', 0, NULL, N'Aumento da vida útil do ciclone, redução das perdas de material, menor frequência de intervenções de manutenção, maior disponibilidade do equipamento e melhoria da segurança operacional e da produtividade.', '2026-07-19T00:00:00.000', '2026-07-20T17:01:55.000', N'1008535', NULL, NULL);
INSERT INTO #PVC VALUES (11272, N'607251', N'608824', N'DPM sample probe', 1, N'Underground/Subterrâneo', N'New diesel particulate matter tester probes where too large to fit into the test port on the exhaust system. This would have required a rework of all the exhaust ports on 100 pieces of equipment.', N'Eliminate extra work', N'10066', N'01 - Imagens/01 - Antes/11272.jpeg', N'Test probe supplied with the equipment was not compatible with the port sizes on the exhaust. ', N'01 - Imagens/02 - Depois/11272.jpeg', N'Reached out to the supplier of the equipment to see if any other options were available, the supplier did not offer anything. The mobile team was able to get new probes built by a local business, after the probes were received our onsite welder closed off one end and drilled holes in the pipe to match the original probe. Emails and pictures were sent to the manufacture for approvals.  ', NULL, N'Yes, the Totten mobile team was able to come up with simple and cost-effective solution.', N'Look outside the box for solutions', 0, NULL, N'Redução do tempo gasto na consolidação e análise das informações de materiais.
INSERT INTO #PVC VALUES (11273, N'81046574', N'81046574', N'Estratégia de Paradas Preventivas – GP|26', 1, N'Others/Outros', N'Em virtude da GP26 tornou-se fundamental definir a estratégia de paradas conforme priorização clara e estratégica do Backlog para atuação durante as paradas do caminho singelo e das linhas da usina durante esse períod.', N'Definir estratégia de Paradas de Manutenção durante a P|26', N'10081', N'01 - Imagens/01 - Antes/11273.jpeg', N'Não havia estratégia definida', N'01 - Imagens/02 - Depois/11273.jpeg', N'Durante a GP|26, haverá 110 dias de parada do moinho SAG, com uso de by-pass (980 t/h) para sustentar a produção. Nesse período, parte da planta operará enquanto outra estará disponível para intervenções.
INSERT INTO #PVC VALUES (11274, N'81036746', N'81036746', N'Flocculant sample tube storage', 1, N'No Replication/Sem replicação', N'Falcon tube storage has become unorganized in storage cabinet near the floc skid. Labelling the tubes is inconvenient as pen ink does not show up on the plastic.', N'Better organization and availability of sample tubes in floc area', N'10045', N'01 - Imagens/01 - Antes/11274.jpeg', N'No organized storage in area designated for falcon tubes. If tubes are available, they aren''t pre-labeled. ', N'01 - Imagens/02 - Depois/11274.jpeg', N'Tray labelled and filled with ready to use falcon tubes to use for Neut, ETP and IR2 floc sample taking.', NULL, N'Yes, the problem was solved, falcon tubes are now easily accessible and pre-labelled. ', N'Organization helps make tasks easier and less time consuming.', 0, NULL, N'MELHOROU A PRODUTIVIDADE APÓS A IMPLEMENTAÇÃO DO 5S NO KANBAN ELÉTRICA.', '2026-07-19T00:00:00.000', '2026-07-20T21:47:42.000', N'81036746', NULL, NULL);
INSERT INTO #PVC VALUES (11275, N'1008449', N'1008449', N'East crane Hydraulics YEM', 1, N'Refining/Refino', N'New hydraulic lines put on crane 002 during day shift. Came in on nights and they leaked and two hoses were put on but needed to be swapped as it was causing hooks to open when you would close and close when you would open', N'Ops completed this rather than tying up maintenance resources', N'0', N'01 - Imagens/01 - Antes/11275.jpeg', N'New hydraulic lines put on crane 002 during day shift. Came in on nights and they leaked and two hoses were put on but needed to be swapped as it was causing hooks to open when you would close and close when you would open. To fix we would have to get maintenance, tying up resources when there were other urgent work ongoing at the time', N'01 - Imagens/02 - Depois/11275.jpeg', N'Ops completed this work while being walked through it with maintenance that completed the job on days. We were able to tighten the fittings and switch around a hose to get the crane up and running. Preventing maintenance to have to deal with it while other work needed to be done.', NULL, N'yes, avoided hitting power down triggers and didn''t have to tie up maintenance resources', N'Test equipment when things get changed', 500, 3, N'Melhoria da segurança com o 5s em dias.', '2026-07-19T00:00:00.000', '2026-07-20T23:21:51.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11276, N'1008449', N'1008449', N'4" pipe clamp on hot water line', 2, N'Refining/Refino', N'Utility hot water sprung a leak in the tankhouse', N'Stop water leak', N'0', N'01 - Imagens/01 - Antes/11276.jpeg', N'Hot water line started leaking spraying onto the tankhouse and in the walkway next to system 400', N'01 - Imagens/02 - Depois/11276.jpeg', N'Pipe clamp used to stop the leak and keep hot water on so we can use for harvesting. This prevented us from waiting to cut and weld new pipe', NULL, N'Yes water leak stopped via pipe clamp', N'Caution to carbon steel piping in the tankhouse', 0, NULL, N'Redução de impacto recurso hídrico e estabilidade do processo.', '2026-07-10T00:00:00.000', '2026-07-21T02:46:55.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11277, N'1008390', N'1008390', N'Caustic Leak Funnel Setup ', 2, N'Others/Outros', N'Caustic was leaking out of a pipe outside in the piperack and landing on the pavement ', N'To prevent Caustic from Landing on the ground ', N'0', N'01 - Imagens/01 - Antes/11277.jpeg', N'Caustic was leaking in pipe rack outside and onto to the pavement below into a walkway ', N'01 - Imagens/02 - Depois/11277.jpeg', N'We used a JLG to gain access to leak and attached a funnel with rope to the pipe and ran a hose down into a tote. this will make sure that if there is a leak it will fall into the funnel and end up in the tote and not on the walkway.', NULL, N'Yes it will prevent Caustic from falling into the walkway ', N'Ensure right Material is used when Bonding FRP', 0, NULL, N'GARANTIA OPERACIONAL DO EQUIPAMENTO DANIFICADO SUBSTITUÍDO DENTRO DO PRAZO ANTES QUE VOLTAR A RODAR. ECONOMIZAMOS MILHARES DE REAIS.', '2026-07-19T00:00:00.000', '2026-07-21T02:53:35.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11278, N'1008390', N'1008390', N'Fixing Seal Water Solenoid to Recirc Pump ', 1, N'Refining/Refino', N'Tried to start Recirc pump and it failed on no seal water going to pump ', N'To Repair Seal water  Solenoid to Recirc Pump ', N'0', N'01 - Imagens/01 - Antes/11278.jpeg', N'Tried to start Recirc Pump and it failed on no seal water to pump so could not get pump started ', N'01 - Imagens/02 - Depois/11278.jpeg', N'Locked out seal water and took apart the solenoid and cleaned it up and freed up the parts that were dirty and sticking preventing the solenoid from opening and allowing seal water to flow through ', NULL, N'Yes Problem was solved, seal water was restored to the pump and pump was started ', N'Troubleshooting can come up with a simple solution ', 500, 3, NULL, '2026-07-10T00:00:00.000', '2026-07-21T03:09:43.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11279, N'1008449', N'1008449', N'Shift 1 Cl2 badge storage location', 3, N'Refining/Refino', N'Nowhere to store rental badges for shift 1', N'Create storage location', N'0', N'01 - Imagens/01 - Antes/11279.jpeg', N'Shift 1 EW were given 4 Cl2 gas badges and nowhere to safely store these to prevent mixing them up', N'01 - Imagens/02 - Depois/11279.jpeg', N'4 Badges were labels "shift 1" and storage home created in the coaches locker so they are available each shift', NULL, N'yes. Badges are in the correct location each set and aren''t misplaced', N'Creating a home for tools and devices prevent them from getting lost', 0, NULL, N'Maintaining integrity and Improving Workability', '2026-06-01T00:00:00.000', '2026-07-21T03:29:32.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11280, N'81061897', N'81061897', N'Titanium Blind repurposing ', 1, N'Projects/Projetos', N'Reinstating Flash Vessel overflow lines to original configuration would require (2) 16 inch blinds after spool removal that were high cost and long lead times', N'cost savings ', N'0', N'01 - Imagens/01 - Antes/11280.jpeg', N'Titanium blinds required for reinstatement of the original flash vessel overflow line configuration had a long lead time and high cost', N'01 - Imagens/02 - Depois/11280.jpeg', N'We reused titanium blinds from a separate upgrade project on the line that would have been otherwise obsolete. This allowed us to complete the flash vessel overflow line reinstatement to the original configuration and allow just one Autoclave, as opposed to two, come down for the necessary flash vessel overflow line cleanings when required   ', NULL, N'Yes', N'cost savings', 25000, 3, N'It led to the prevention of electric shock accidents.', '2026-06-01T00:00:00.000', '2026-07-21T08:39:28.000', N'81061897', NULL, NULL);
INSERT INTO #PVC VALUES (11281, N'81013125', N'81009117', N'VB rental tracker', 1, N'Others/Outros', N'a number of years ago Shawn Hunt asked for a list of rental equipment on VB site. With multiple requisitioners, each area was siloed which made it difficult to put a single list together', N'Have one unified list of rental equipment on VB site', N'10026', N'01 - Imagens/01 - Antes/11281.jpeg', N'-Conflicting lists living on individual''s hard drives
INSERT INTO #PVC VALUES (11282, N'504475', N'871194', N'Automação - Head Count Terceiros Complexo Sossego', 1, N'Others/Outros', N'Atualmente, o controle do Head Count de Terceiros do Complexo Sossego é realizado por meio de processos manuais e consolidações em diferentes fontes de dados, demandando elevado esforço operacional e aumentando o risco de inconsistências, retrabalho e atrasos na disponibilização das informações. A falta de automação dificulta o acompanhamento em tempo real da força de trabalho terceirizada, impactando a eficiência da gestão, o monitoramento de contratos e a tomada de decisões estratégicas. Dessa forma, torna-se necessária a implementação de uma solução automatizada que proporcione maior confiabilidade, agilidade e padronização no gerenciamento dessas informações.', N'Automatizar o processo de controle e consolidação do Head Count de Terceiros do Complexo Sossego, garantindo maior agilidade, confiabilidade e rastreabilidade das informações, reduzindo atividades manuais, minimizando erros operacionais e proporcionando uma visão atualizada para apoio à gestão e à tomada de decisão.', N'10361', N'01 - Imagens/01 - Antes/11282.jpeg', N'O processo de controle do Head Count de Terceiros do Complexo Sossego era realizado de forma manual, por meio de planilhas e informações enviadas por diferentes áreas. Essa dinâmica resultava em registros incompletos, dados informados incorretamente, duplicidades e divergências entre as bases de informação. Além disso, a consolidação dos dados demandava grande esforço operacional, elevado tempo de processamento e constantes validações manuais.
INSERT INTO #PVC VALUES (11283, N'1008564', N'1008449', N'Post QR Code for Employee Recognition Form', 1, N'No Replication/Sem replicação', N'There was no form posted in the Technician''s Room to access the QR Code for Employee Recognition Form', N'Employee Recognition Form QR Code would be more accessible to the Technicians', N'0', N'01 - Imagens/01 - Antes/11283.jpeg', N'No QR Code for Employee Recognition Form', N'01 - Imagens/02 - Depois/11283.jpeg', N'QR Code for Employee Recognition Form', NULL, N'yes', N'Locate QR Code ', 0, NULL, N'The extension cords have addressed the tripping hazard in the lunchroom.', '2026-07-20T00:00:00.000', '2026-07-21T12:25:57.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (11284, N'81058966', N'472918', N'Substituição do Ciclone CI-2017-02 por modelo com revestimento cerâmico.', 1, N'Others/Outros', N'Durante uma manutenção foi identificado que o ciclone antigo, com revestimento de borracha, apresentava desgaste excessivo devido à abrasão do material transportado. Esse desgaste ocasionava vazamentos de material, aumentando a necessidade de manutenções corretivas, elevando os custos e expondo os colaboradores a riscos durante as intervenções.', N'Substituir o ciclone por um modelo com revestimento cerâmico, aumentando sua vida útil.', N'10031', N'01 - Imagens/01 - Antes/11284.jpeg', N'O ciclone antigo possuía revestimento de borracha, que sofria desgaste prematuro, causando vazamento de material e frequentes paradas para manutenção.', N'01 - Imagens/02 - Depois/11284.jpeg', N' Foi instalado um novo ciclone CI-2017-02 com revestimento de cerâmica, material com maior resistência à abrasão.', NULL, N'SIM. A substituição do ciclone de borracha por um ciclone com revestimento cerâmico eliminou os vazamentos de material causados pelo desgaste prematuro, aumentou a resistência do equipamento, reduziu a necessidade de manutenções corretivas e proporcionou maior segurança e confiabilidade ao processo.', N' componentes mais resistentes aumenta a confiabilidade do equipamento, reduz custos com manutenção', 0, NULL, NULL, '2026-07-15T00:00:00.000', '2026-07-21T14:15:00.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11285, N'81034734', N'520046', N'Dashboard Integrado de Gestão de Materiais por Criticidade e Data de Necessidade', NULL, N'Others/Outros', N'O controle dos materiais da parada era realizado por meio de planilhas e informações descentralizadas, dificultando a visualização dos riscos relacionados aos prazos de entrega e às datas de necessidade para aplicação. Essa limitação reduzia a capacidade de antecipação das ações de mitigação, aumentando o risco de indisponibilidade de materiais críticos e impactos no cronograma da parada.
INSERT INTO #PVC VALUES (11286, N'522369', N'522369', N'5S KANBAN ELÉTRICA', 3, N'No Replication/Sem replicação', N'FOI CONSTATADO NA ROTINA QUE TEM MUITO ACUMULO DE MATERIAL RECEBIDO DO ARMAZÉM PARA ABASTECIMENTO DO KANBAN ELÉTRICA.', N'MELHORAR PROCESSO DE MATERIAIS ORGANIZADO NA PRATELEIRA QUE FICA DISPONÍVEL CONFORME PADRÃO DE CINCO SENSOS DE 5S', N'10031', N'01 - Imagens/01 - Antes/11286.jpeg', N'DESORGANIZAÇÃO NO KANBAN ELÉTRICA COM RECEBIMENTO DE MATERIAL PARA ABASTECER O LOCAL QUE ESTÁ FORA DO PADRÃO DE 5S.', N'01 - Imagens/02 - Depois/11286.jpeg', N'FOI REALIZADO APLICAÇÃO DE TODOS OS SENSOS DE 5S NO KANBAN ELÉTRICA PARA ARMAZENAR MATERIAIS NA PRATELEIRAS E DESCARTAR CORRETAMENTE O RESÍDUO GERADO NA ATIVIDADE DE PADRONIZAÇÃO.', NULL, N'MELHORAR E PADRONIZAR SEMPRE O ABASTECIMENTO DE MATERIAIS PARA CICLO DE MANUTENÇÃO ELÉTRICA, ONDE TEMOS GANHOS NA PRODUTIVIDADE.', N'FOI FEITO TODOS OS SENSOS DE 5S NA ORGANIZAÇÃO DO KANBAN ELÉTRICA', 0, NULL, N'Redução de tempo nas atividades de abertura das praças de sondagrm', '2026-07-20T00:00:00.000', '2026-07-21T15:04:10.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11287, N'522369', N'522369', N'KANBAN ELÉTRICA 5S', 3, N'No Replication/Sem replicação', N'DIFICULDADE NO PRIMEIRO CICLO DE ABASTECIMENTO DE MATERIAIS RECEBIDO DO ARMAZÉM PARA KANBAN ELÉTRICA, ONDE ACUMULA MUITAS CAIXAS QUEBRANDO O CICLO DE 5S.', N'MELHORAR PROCESSO DE MATERIAIS ORGANIZADO NAS PRATELEIRAS QUE FICA DISPONÍVEL CONFORME PADRÃO DE CINCO SENSOS DE 5S', N'10178', N'01 - Imagens/01 - Antes/11287.jpeg', N'DESORGANIZAÇÃO NO KANBAN ELÉTRICA COM RECEBIMENTO DE MATERIAL PARA ABASTECER O LOCAL QUE ESTÁ FORA DO PADRÃO DE 5S.', N'01 - Imagens/02 - Depois/11287.jpeg', N'FOI REALIZADO APLICAÇÃO DE TODOS OS SENSOS DE 5S NO KANBAN ELÉTRICA PARA ARMAZENAR MATERIAIS NA PRATELEIRAS E DESCARTAR CORRETAMENTE O RESÍDUO GERADO NA ATIVIDADE DE PADRONIZAÇÃO.', NULL, N'MELHORAR E PADRONIZAR SEMPRE O ABASTECIMENTO DE MATERIAIS PARA CICLO DE MANUTENÇÃO ELÉTRICA, ONDE TEMOS GANHOS NA PRODUTIVIDADE.', N'FOI FEITO TODOS OS SENSOS DE 5S NA ORGANIZAÇÃO DO KANBAN ELÉTRICA.', 0, NULL, N'Essa sinalização reforça a segurança operacional, restringe intervenções indevidas, aumenta a percepção de risco e padroniza o procedimento de acesso e intervenção no equipamento.', '2026-07-20T00:00:00.000', '2026-07-21T15:35:43.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11288, N'515962', N'81061537', N'melhoria do amostrador cleaners', 1, N'No Replication/Sem replicação', N'Condições ergonômicas ao coletar a amostra ruim  e condições de 5s anormal.', N'melhorar a condição da amostragem e ergonômia ', N'10054', N'01 - Imagens/01 - Antes/11288.jpeg', N'O ponto de coleta de amostra possuía um registro de PVC para controle de abertura e fechamento. Devido à exposição contínua aos intempéries (radiação solar, chuva e variações de temperatura), o componente apresentava fragilidade mecânica, aumentando o risco de quebra durante a operação. Essa condição gerava insegurança para os operadores, maior necessidade de manutenção e possibilidade de indisponibilidade do ponto de amostragem.', N'01 - Imagens/02 - Depois/11288.jpeg', N'Foi realizada a substituição do registro de PVC por uma válvula de aço, material mais resistente às condições ambientais e aos esforços mecânicos aplicados durante a operação. A nova válvula proporciona maior robustez, confiabilidade e vida útil ao sistema de coleta de amostras. Além disso foi instalado mangueira com descarga para a pia, melhoria da ergonomia e 5s do local. ', NULL, N'Sim!', N'Uma boa ergonomia faz toda a diferença no nosso dia a dia.', 0, NULL, N'o numero de ordens de embarcados vencidos da carteira foi sanado', '2026-07-13T00:00:00.000', '2026-07-21T16:52:05.000', N'515962', NULL, NULL);
INSERT INTO #PVC VALUES (11289, N'488890', N'488890', N'Marca  que vai', 1, N'No Replication/Sem replicação', N'Durante a operação do circuito em BY PASS, com o material sendo desviado para a 2301 TC 08, foi identificado que a lógica de controle do sistema continua considerando que 100% da massa alimentada está sendo direcionada ao moinho SAG para o cálculo do percentual de sólidos.', N'Eliminar falha no cálculo do % sólido alimentação do moinho SAG. ', N'10054', N'01 - Imagens/01 - Antes/11289.jpeg', N'Durante a operação em BY-PASS, com desvio de material para a 2301-TC-08, a lógica de controle continua considerando que 100% da massa alimentada segue para o moinho SAG no cálculo do percentual de sólidos. Como resultado, ocorre superestimação da vazão de água, gerando adição excessiva de água ao moinho e aumentando o risco de instabilidade operacional e elevação do nível de descarga.', N'01 - Imagens/02 - Depois/11289.jpeg', N'Foi implementada uma melhoria na lógica de controle do sistema, permitindo identificar automaticamente quando o circuito está operando em BY PASS para a 2301 TC 08 ou alimentando o moinho SAG. Com essa adequação, o cálculo do percentual de sólidos passou a considerar apenas a massa efetivamente direcionada ao moinho, garantindo maior precisão na adição de água, reduzindo riscos operacionais e aumentando a confiabilidade do processo.', NULL, N'A lógica de controle não diferenciava a condição operacional do circuito, comprometendo o cálculo do percentual de sólidos. A meta foi garantir que o cálculo considerasse apenas a massa alimentada ao moinho SAG, aumentando a precisão e a confiabilidade do processo.', N'Confiabilidade no processo faz a diferencia. ', 0, NULL, N'Identificação, mitigação ou neutralização de perigos. Esses benefícios impactam diretamente a produtividade, a cultura organizacional e os custos', '2026-07-15T00:00:00.000', '2026-07-21T17:08:47.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11290, N'522369', N'522369', N'ENTREGA DELIVERY PGU JULHO 2026 MOAGEM SLB III', 2, N'No Replication/Sem replicação', N'INTERVALOS MUITOS LONGOS NA ESPERA DO CICLO DE SEPARAÇÃO DE MATERIAIS. JUNTO COM A ÁREA DEPEDENTE DO RECURSO PARA LIBERAR O EQUIPAMENTO.', N'AGILIDADE NO PROCESSO DE SEPARAÇÃO DE MATERIAIS NO ARMAZÉM PARA DESTINO FINAL À MANUTENÇÃO ELÉTRICA', N'10178', N'01 - Imagens/01 - Antes/11290.jpeg', N'SEPARAR MATERIAIS SÃO MUITOS BUROCRÁTICOS, NA QUAL PERDEMOS MUITO TEMPO AGUARDANDO O CICLO DE SEPARAÇÃO ONDE PERDEMOS EM PRODUTIVIDADE DO PROCESSO INDUSTRIAL.', N'01 - Imagens/02 - Depois/11290.jpeg', N'FOI FEITO COMUNICAÇÃO QUE O MATERIAL ERA CRÍTICO E REDUZIDO À BUROCRACIA EM 7 MINUTOS DE SEPARAÇÃO PARA ENTREGAR NA ÁREA SLB III / USINA NO CICLO DA PGU JUL / 2026.', NULL, N'MUITA AGILIDADE NO FLUXO DE SEPARAÇÃ DE MATERIAIS PARA ATENDER A URGÊNCIA CRÍTICA DO RECURSO.', N'COMUNICAÇÃO É O MELHOR REMÉDIO PARA INTERVENÇÃO DE URGÊNCIA DO MATERIAL CRÍTICO.', 1, 1, NULL, '2026-07-01T00:00:00.000', '2026-07-21T17:47:43.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11291, N'1008390', N'1008390', N'Handle fell off safety shower ', 2, N'Refining/Refino', N'YEM was put in today about safety shower handle was on the floor so the shower could not be pulled if it needed to be used ', N'To fix safety shower so that it can be  used ', N'0', N'01 - Imagens/01 - Antes/11291.jpeg', N'YEM was put in today for safety shower handle had fallen off, so if the safety shower had to used you would not be able to pull the handle. ', N'01 - Imagens/02 - Depois/11291.jpeg', N'When I inspected the shower as to why the handle fell off, I noticed that the nut that held the handle on was missing. Located another nut and put the handle back on and tightened nut. Shower not works as it shoulda', NULL, N'Yes Problem was solved and safety shower is fixed and can be used ', N'Troubleshooting can lead to an easy solution ', 500, 3, N'A melhoria reduziu o esforço físico, aumentou a segurança e padronizou a operação na CF-2057-01.', '2026-07-21T00:00:00.000', '2026-07-22T01:44:33.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11292, N'87000324', N'87000442', N'Specification Change for Bolts and Nuts Used to Secure the 110 kW RB Unit', 1, N'Refining/Refino', N'We had been securing the main unit with double nuts, but there were concerns that the bolts might loosen.', N'Improvements in Insulation and Measurement Efficiency', N'10217', N'01 - Imagens/01 - Antes/11292.jpeg', N'We had been securing the main unit with double nuts, but there were concerns that the bolts might loosen.', N'01 - Imagens/02 - Depois/11292.jpeg', N'We switched to Hardlock Nuts to address the causes of screw loosening.', NULL, N'There was no gap,', N'Optimization', 0, NULL, N'Muito mais segurança', '2026-06-17T00:00:00.000', '2026-07-22T05:17:56.000', N'87000324', NULL, NULL);
INSERT INTO #PVC VALUES (11293, N'87000324', N'87000320', N'Addition to  Regarding Crane Operations on 　Construction Safety Regulations', 2, N'Refining/Refino', N'Since there are no opportunities to raise awareness about the distance between high-voltage power lines and cranes, it is difficult to recognize the danger.', N'Notice to Employees', N'10217', N'01 - Imagens/01 - Antes/11293.jpeg', N'Since there are no opportunities to raise awareness about the distance between high-voltage power lines and cranes, it is difficult to recognize the danger.', N'01 - Imagens/02 - Depois/11293.jpeg', N'High-voltage power lines have been marked on the factory layout plan, and preparations for the risk assessment are complete.', NULL, N'There was no gap,', N'heads up', 0, NULL, N'Melhorar a segurança e a ergonomia da operação, reduzir o tempo de intervenção, facilitar a abertura e o fechamento da válvula e padronizar o sistema de acionamento da AM-2017-47.', '2026-07-21T00:00:00.000', '2026-07-22T06:00:42.000', N'87000324', NULL, NULL);
INSERT INTO #PVC VALUES (11294, N'81033365', N'81033365', N'Suporte de bateria', 2, N'Others/Outros', N'ausência de um suporte correto', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11294.jpeg', N'O suporte antigo encostava nos polos das baterias, gerando curto-circuito e danos mecânicos nas células.', N'01 - Imagens/02 - Depois/11294.jpeg', N'Um novo suporte sob medida foi fabricado, garantindo a fixação firme e o isolamento seguro dos polos.', NULL, N'Problema: Suporte inadequado encostava nos polos, gerando curto-circuito e danificando as baterias.
INSERT INTO #PVC VALUES (11295, N'81058966', N'81038855', N'Adequação da tubulação dos canhões de limpeza da baia da CX-2057-06', 1, N'Others/Outros', N'Durante o translado da CX-2057-06, foi identificado um grande acúmulo de material concentrado na baia, com potencial de ser direcionado ao sump. Entretanto, devido às constantes falhas na tubulação de alimentação dos canhões de lavagem, não era possível realizar a limpeza de forma eficiente, ocasionando perdas operacionais, acúmulo de material e maior necessidade de intervenções de manutenção.', N'Aumentar a vida útil da tubulação; Garantir a disponibilidade dos canhões de lavagem; Reduzir perdas operacionais; Proporcionar um ambiente mais limpo, seguro e organizado.', N'10031', N'01 - Imagens/01 - Antes/11295.jpeg', N'Durante o translado da CX-2057-06, foi identificado grande acúmulo de material concentrado na baia. A indisponibilidade dos canhões de lavagem impedia a remoção desse material e seu retorno ao circuito de processo.', N'01 - Imagens/02 - Depois/11295.jpeg', N'Foi fabricado e instalado um novo trecho de tubulação, substituindo o percurso subterrâneo por um trajeto externo. ', NULL, N'SIM. O problema foi resolvido com a substituição da tubulação subterrânea por uma tubulação externa, eliminando os vazamentos de água e restabelecendo a disponibilidade dos canhões de lavagem. A solução permitiu a recuperação do material acumulado na baia da CX-2057-06, reduzindo perdas operacionais e proporcionando um ambiente mais limpo, seguro e organizado.', N'Aumento da vida útil da tubulação; Eliminação de vazamentos de água; Maior disponibilidade dos canhões de lavagem;', 0, NULL, N'Redução da escrita manual repetitiva, diminuindo a fadiga das mãos e dos punhos , maior conforto e agilidade na execução da atividade administrativa.', '2026-07-09T00:00:00.000', '2026-07-22T08:53:32.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11296, N'124132', N'124132', N'Tripping hazard', 3, N'Refining/Refino', N'We do not have enough electrical outlets in our lunchroom. There was one area in the lunchroom that an employee was using to charge their cell phone. It was stretched across the table and floor area. ', N'Remove tripping hazard', N'10255', N'01 - Imagens/01 - Antes/11296.jpeg', N'We do not have enough electrical outlets in our lunchroom. There was one area in the lunchroom that an employee was using to charge their cell phone. It was stretched across the table and floor area. ', N'01 - Imagens/02 - Depois/11296.jpeg', N'I purchased some extension cords to be used in the lunchroom removing the tripping hazard.', NULL, N'We had a safety issue that needed to be addressed.', N'The importance of removing the tripping hazard', 0, NULL, NULL, '2026-07-21T00:00:00.000', '2026-07-22T10:36:03.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11297, N'202630', N'202630', N'Rental rate reduction', 2, N'Others/Outros', N'Required an additional 20 Chlorine gas monitors - monthly rate of $4800 received, added to our current contract with new monthly rate of $1302.93', N'To reduce monthly rental rate by adding to contract', N'10026', N'01 - Imagens/01 - Antes/11297.jpeg', N'Required an additional 20 Chlorine gas monitors - monthly rate of $4800 received.', N'01 - Imagens/02 - Depois/11297.jpeg', N'Added to our current contract with new monthly rate of $1302.93', NULL, N'Yes, cost savings of $3497.07 per month, 
INSERT INTO #PVC VALUES (11298, N'553135', N'516988', N'PROTEÇÃO DA HASTE DO CILINDRO - EC-20', 2, N'Others/Outros', N'ANTES A HASTE DO CILINDRO FICAVA EXPOSTA A MATERIAIS ABRASIVOS,  SENDO DANIFICADO COM MUITA FACILIDADE. ISSO GERAVA UMA FREQUENTE NECESSIDADE DE TROCA DO CILINDRO EXPONDO OS EMPREGADOS AO RISCO DE ESMAGAMENTO E PRENSAMENTO. ', N'AUMENTAR A VIDA UTIL ', N'10139', N'01 - Imagens/01 - Antes/11298.jpeg', N'ANTES A HASTE DO CILINDRO FICAVA EXPOSTA A MATERIAIS ABRASIVOS,  SENDO DANIFICADO COM MUITA FACILIDADE. ISSO GERAVA UMA FREQUENTE NECESSIDADE DE TROCA DO CILINDRO EXPONDO OS EMPREGADOS AO RISCO DE ESMAGAMENTO E PRENSAMENTO. ', N'01 - Imagens/02 - Depois/11298.jpeg', N'FOI ADQUIRIDA UMA CAPA PROTETORA PARA A HASTE DO CILINDRO. BENEFICIOS ALCANÇADOS: REDUÇÃO DE TROCA DE CILINDROS, EMPREGADOS MENOS EXPOSTOS A RISCOS REALCIONADOS A MANUTENÇÃO E REDUÇÃO DE CUSTO. ', NULL, N'FOI ADQUIRIDA UMA CAPA PROTETORA PARA A HASTE DO CILINDRO. BENEFICIOS ALCANÇADOS: REDUÇÃO DE TROCA DE CILINDROS, EMPREGADOS MENOS EXPOSTOS A RISCOS REALCIONADOS A MANUTENÇÃO E REDUÇÃO DE CUSTO. ', N'SOLUÇÕES EFICAZES ', 0, NULL, N'A aderência do IMOS Automação foi recuperada por meio da revisão das programações, priorização das atividades críticas, alinhamento com a equipe executante e tratativa das ordens recorrentes, garantindo maior execução das OMs e redução do backlog, essa tratativa semanal teve um resultado positivo na aderência desse indicador.', '2026-07-21T00:00:00.000', '2026-07-22T10:52:59.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11299, N'81029574', N'81029574', N'Programação de Sondagem via GPS de navegação para confecção das praças de sondagem', 1, N'Open Pit/Poço aberto', N'O processo de sondagem dependia da equipe de Topografia para realizar a locação e marcação dos furos em campo antes da confecção das praças de sondagem. Essa dependência gerava atrasos no cronograma, aumento do tempo de espera e redução da produtividade da equipe de sondagem.
INSERT INTO #PVC VALUES (11300, N'81006670', N'81053737', N'Sistema de intertravamento de segurança na porta do gabinete elétrico', 2, N'Others/Outros', N'Durante as atividades de inspeção e manutenção no compressor, a abertura da porta do gabinete elétrico permitia o acesso a componentes energizados, mantendo o circuito de comando disponível.', N'Bloquear acesso a gabinete elétrico do compressor', N'10144', N'01 - Imagens/01 - Antes/11300.jpeg', N'Durante as atividades de inspeção e manutenção no compressor, a abertura da porta do gabinete elétrico permitia o acesso a componentes energizados, mantendo o circuito de comando disponível e expondo os trabalhadores ao risco de choque elétrico e partida inesperada do equipamento. Além disso, qualquer profissional, mesmo não sendo eletricista autorizado, tinha livre acesso ao interior do gabinete, permanecendo exposto aos riscos elétricos e podendo realizar alterações indevidas nos parâmetros do equipamento, sem qualquer sistema de intertravamento ou bloqueio que impedisse esse acesso.', N'01 - Imagens/02 - Depois/11300.jpeg', N'Foi implantado um sistema de intertravamento de segurança na porta do gabinete, utilizando um dispositivo de segurança integrado a um relé de segurança. Com a abertura da porta, o circuito de segurança é interrompido, desenergizando o circuito de comando do compressor e impedindo seu funcionamento. O retorno à operação somente é possível após o fechamento da porta e a realização do reset manual do sistema, garantindo que o equipamento só volte a operar de forma segura.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Como complemento à melhoria, foi instalada uma sinalização visual do tipo giroflex na parte superior do gabinete. Sempre que a porta é aberta, o giroflex é acionado, indicando de forma clara e imediata a condição de porta aberta e perigo, alertando todos os profissionais nas proximidades sobre a condição de risco. ', N'Esse processo transforma o registro de falhas em mudanças concretas em processos, sistemas e comportamentos.', 0, NULL, N'CONFECIONADA E INSTALADA FIXAÇÃO DOS TUBOS, GERANDO AUMENTO DA VIDA UTIL DO COMPONENTE E REDUÇÃO DE CUSTO. ', '2026-07-21T00:00:00.000', '2026-07-22T11:48:32.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (11301, N'545887', N'545887', N'Projeção semanal caminhões de leves ', 1, N'Others/Outros', N'A equipe de Automação enfrentava grandes dificuldades para executar suas atividades, devido à falta de visibilidade das demandas de automação no planejamento e programação das atividades de Leves. Frequentemente, as intervenções eram impactadas porque não havia uma projeção adequada contendo informações essenciais, como a descrição das atividades, a quantidade de horas de máquina necessárias e a respectiva demanda a ser atendida.
INSERT INTO #PVC VALUES (11302, N'81006670', N'81053737', N'Melhoria do Circuito Elétrico da Bancada de Teste para Motores de Partida.', 2, N'Others/Outros', N'O motor de partida, cuja corrente nominal pode atingir aproximadamente 120 A, era acionado diretamente por uma chave Margirius com capacidade nominal de apenas 15 A.', N'Melhoria no circuito elétrico da bancada por meio da separação entre os circuitos de comando e potência.', N'10144', N'01 - Imagens/01 - Antes/11302.jpeg', N'A bancada de teste para motores de partida foi fornecida pelo fabricante com o circuito de acionamento elétrico subdimensionado para a aplicação. O motor de partida, cuja corrente nominal pode atingir aproximadamente 120 A, era acionado diretamente por uma chave Margirius com capacidade nominal de apenas 15 A. Essa condição provocava sobrecarga no dispositivo de manobra, ocasionando centelhamento nos contatos e conexões da chave, aquecimento excessivo e elevado risco de falha elétrica, além de comprometer a segurança operacional e a confiabilidade dos ensaios.', N'01 - Imagens/02 - Depois/11302.jpeg', N'Foi implementada uma melhoria no circuito elétrico da bancada por meio da separação entre os circuitos de comando e potência. O acionamento do motor de partida passou a ser realizado por um contator, responsável pelo seccionamento da alimentação elétrica de potência, enquanto uma chave seletora de duas posições ficou dedicada exclusivamente ao circuito de comando, acionando apenas a bobina do contator. Também foi incorporada proteção por disjuntor no circuito. Com essa modificação, a corrente elevada do motor deixou de circular pela chave seletora, eliminando o centelhamento, aumentando a vida útil dos componentes, proporcionando maior segurança operacional e tornando a bancada mais confiável para a realização dos testes.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Com essa modificação, a corrente elevada do motor deixou de circular pela chave seletora, eliminando o centelhamento, aumentando a vida útil dos componentes, proporcionando maior segurança operacional e tornando a bancada mais confiável para a realização dos testes.', N'Esse processo transforma o registro de falhas em mudanças concretas em processos, sistemas e comportamentos.', 0, NULL, N'Eliminação do riscos de prensamento e esmagamento e melhoria riscos ergonômico', '2026-07-21T00:00:00.000', '2026-07-22T13:22:26.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (11303, N'81058075', N'81058075', N'Uniform Sharing and Control Kaizen', 3, N'Others/Outros', N'Uniforms and coveralls at the Long Harbour site are currently stored across multiple locations, including the stockroom and areas near the washrooms, without a consistent process to manage identification, issuance, condition, laundry dispatch, return, or availability for controlled sharing. As a result, some garments remain unidentified, damaged items may be mixed with usable stock, excess inventory is not fully utilized, and the site has limited visibility into the true need for new purchases. This creates avoidable risk related to waste, unnecessary spend, administrative rework, invoice validation, and missed opportunities to maximize the value of garments already available on site.', N'Establish a simple, traceable, and sustainable process to manage uniforms and coveralls at Long Harbour by prioritizing existing stock before new purchases, reducing laundry process discrepancies, and improving stockroom organization. ', N'0', N'01 - Imagens/01 - Antes/11303.jpeg', N'The current process relies primarily on manual controls, informal knowledge, and visual checks. The stockroom does not yet function as a single, reliable source of information because garments are not consistently classified by size, condition, usage status, or laundry status. There is also no reliable digital record confirming how many garments were sent to the laundry, how many were returned, or whether supplier invoices accurately reflect the volume processed. As a result, new uniforms may be requested even when usable garments are available, and the site cannot clearly quantify current waste levels or potential savings.', N'01 - Imagens/02 - Depois/11303.jpeg', N'The stockroom will be reorganized and standardized using 5S principles, with uniforms and coveralls clearly separated by type, size, condition, and status. Clean and usable garments will be made available through a controlled sharing model, supported by defined issuance and return rules. A digital app or tracking tool will record garments sent to and returned from the laundry, enabling monthly reconciliation against supplier invoices. This future-state process will improve traceability, strengthen operational control, increase utilization of existing inventory, and reduce unnecessary purchases and laundry activity.
INSERT INTO #PVC VALUES (11304, N'81058966', N'81054451', N' Adequação da válvula da tubulação de ar – CF-2057-01', 1, N'Others/Outros', N'Durante uma manutenção na tubulação de ar da CF-2057-01, foi identificado que a válvula existente exigia o uso de chave e elevado esforço físico para sua abertura e fechamento. Essa condição aumentava o risco de lesões ergonômicas, dificultava a execução da atividade e impactava a segurança e a eficiência da manutenção.', N' Melhorar a ergonomia e a segurança da atividade, padronizando o sistema de acionamento da válvula e facilitando sua operação.', N'10031', N'01 - Imagens/01 - Antes/11304.jpeg', N'A válvula antiga necessitava de chave para seu acionamento e exigia grande esforço físico para abrir e fechar', N'01 - Imagens/02 - Depois/11304.jpeg', N'A válvula foi substituída por um modelo com volante, permitindo abertura e fechamento de forma simples, rápida e sem necessidade de ferramentas', NULL, N'sim,permitindo abertura e fechamento de forma simples.', N'Pequenas melhorias podem gerar grandes ganhos em segurança, ergonomia e produtividade.', 0, NULL, N'Identify a practical opportunity to reuse rainwater already available at Long Harbour, supporting sustainability, responsible water use, and potential cost reduction', '2026-07-15T00:00:00.000', '2026-07-22T14:43:39.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11305, N'92000525', N'486875', N'Melhoria dos sensores indutivos do mastro', 2, N'Others/Outros', N' As atividades de inspeção, ajuste, manutenção ou substituição desses sensores exigiam a execução de trabalhos em altura, enquadrados nos requisitos do RAC 01 – Trabalho em Altura, demandando a adoção de controles específicos de segurança, utilização de sistemas de acesso e equipamentos de proteção adequados.', N'Tornar os sensores acessíveis para executar a atividade sem risco', N'10324', N'01 - Imagens/01 - Antes/11305.jpeg', N'Situação Anterior Os dois sensores indutivos responsáveis pelo monitoramento da posição do carrossel de acomodação das hastes de perfuração estavam instalados a aproximadamente 10 metros de altura. Esses sensores desempenham função de segurança e intertravamento dos movimentos da cabeça rotativa, fornecendo ao sistema informações sobre a posição do carrossel, indicando se este se encontra na condição de giro ou recolhimento.', N'01 - Imagens/02 - Depois/11305.jpeg', N'Após a realocação dos dois sensores indutivos para uma posição acessível ao nível da plataforma de trabalho, as atividades de inspeção, instalação, ajuste e manutenção dos sensores e respectivos cabeamentos passaram a ser executadas em condição de acesso seguro, sem necessidade de intervenção em altura. Com essa modificação, foi eliminada a exposição dos empregados aos riscos associados ao trabalho em altura, bem como a necessidade de execução de atividades enquadradas no RAC 01 – Trabalho em Altura, uma vez que os componentes passaram a estar localizados abaixo da altura mínima estabelecida para caracterização dessa atividade nas operações da Vale (1,80 m).', NULL, N'Além do ganho em segurança, a alteração proporcionou maior facilidade de acesso aos componentes, redução da complexidade das intervenções de manutenção e aumento da eficiência operacional, mantendo integralmente a funcionalidade de monitoramento e intertravamento do sistema.  Muito mais segurança ', N'Com essa modificação, foi eliminada a exposição dos empregados aos riscos associados ao trabalho em altura, bem como a necessidade de execução de atividades enquadradas no RAC 01 – Trabalho em Altura, uma vez que os componentes passaram a estar localizados abaixo da altura mínima estabelecida para caracterização dessa atividade nas operações da Vale (1,80 m).', 0, NULL, NULL, '2026-06-28T00:00:00.000', '2026-07-22T14:50:59.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11306, N'81058966', N'81058966', N' Adequação da válvula da linha de ar – AM-2017-47', 1, N'Others/Outros', N'Durante uma manutenção na linha de ar da AM-2017-47, foi identificado que a válvula existente possuía acionamento inadequado, exigindo elevado esforço físico e o uso de ferramenta para sua operação. Essa condição aumentava o risco de lesões ergonômicas e dificultava as atividades de manutenção.', N' Melhorar a ergonomia, a segurança e a padronização da operação, facilitando a abertura e o fechamento da válvula.', N'10031', N'01 - Imagens/01 - Antes/11306.jpeg', N'A válvula antiga possuía sistema de acionamento que exigia grande esforço físico e utilização de ferramenta para abertura e fechamento.', N'01 - Imagens/02 - Depois/11306.jpeg', N'Foi instalada uma válvula com volante manual, permitindo abertura e fechamento de forma rápida, segura e sem necessidade de ferramentas.', NULL, N'SIM. O problema foi resolvido com a substituição da válvula antiga por uma válvula com volante, eliminando a necessidade de esforço excessivo e do uso de ferramentas. A melhoria proporcionou maior segurança, ergonomia e eficiência operacional, atendendo ao objetivo proposto.', N'A substituição de componentes por modelos mais ergonômicos contribui para a segurança dos empregados, reduz o esforço físico durante as intervenções e fortalece a cultura de melhoria contínua.', 0, NULL, N'The proposed cut-off process improves month-end discipline, reduces SAP transactions, minimizes estimate variances, and allows Contracts and Finance to focus on higher-value activities.', '2026-07-16T00:00:00.000', '2026-07-22T14:51:19.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11307, N'545887', N'545887', N'Acompanhamento semanal IMOS', 1, N'Others/Outros', N'O aumento do backlog de Automação  ocorreu devido à recorrência de reprogramações sem execução das OMs, motivadas principalmente pela indisponibilidade do equipamento, falta de energia para intervenção, restrição de efetivo e execução concomitante de outras demandas. Como consequência, ordens permaneceram pendentes por longos períodos, impactando diretamente os indicadores de manutenção."', N'Manter aderinca', N'10234', N'01 - Imagens/01 - Antes/11307.jpeg', N'O aumento do backlog de Automação  ocorreu devido à recorrência de reprogramações sem execução das OMs, motivadas principalmente pela indisponibilidade do equipamento, falta de energia para intervenção, restrição de efetivo e execução concomitante de outras demandas. Como consequência, ordens permaneceram pendentes por longos períodos, impactando diretamente os indicadores de manutenção."', N'01 - Imagens/02 - Depois/11307.jpeg', N'Após a tratativa da carteira de backlog, a frota de Automação apresentou evolução significativa no controle das pendências, com redução das ordens represadas, maior aderência à programação e melhor alinhamento entre PCM e execução. A atuação conjunta permitiu atacar as principais causas dos desvios, aumentando a efetividade das intervenções e contribuindo para a estabilização dos indicadores de manutenção da frota."', NULL, N'SIM', N'A rotina diária faz total diferença no processo ', 0, NULL, N'Com a redução de tempo conseguimos aumentar a produção. Abrindo espaço para outras demandas. ', '2026-07-10T00:00:00.000', '2026-07-22T14:53:09.000', N'545887', NULL, NULL);
INSERT INTO #PVC VALUES (11308, N'81054438', N'81054438', N'Implantação de carimbo padronizado para encerramento de Permissão de trabalho seguro (PTS)', 1, N'Others/Outros', N'O encerramento manual das PTS consome tempo, apresenta baixa padronização e aumenta a ocorrência de erros de preenchimento, ocasionando retrabalho na conferência e no arquivamento dos documentos.', N'Redução do tempo de encerramento das PTS.', N'10229', N'01 - Imagens/01 - Antes/11308.jpeg', N'O processo de encerramento das Permissões de Trabalho Seguro (PTS) era realizado totalmente por preenchimento manual. As informações de encerramento eram escritas à mão, tornando a atividade repetitiva, demorada e suscetível a erros.', N'01 - Imagens/02 - Depois/11308.jpeg', N'A padronização elimina variações no preenchimento manual.
INSERT INTO #PVC VALUES (11309, N'81058075', N'81058075', N'Long Harbour On-Site Laundry for Coverall Cleaning and Control', 1, N'Others/Outros', N'The current coverall cleaning process depends on an external provider, which limits Vale’s direct control over collection, return, garment identification, turnaround time, service responsiveness, and invoice validation. Existing issues include unidentified garments, limited visibility over Vale-owned coveralls, inconsistent communication with the supplier, and reduced ability to confirm whether cleaned and dirty garments are properly separated.', N'By building an on-site laundry facility, Long Harbour will gain stronger uniform control, achieve cost savings, and reduce dependency on external suppliers.', N'0', N'01 - Imagens/01 - Antes/11309.jpeg', N'Coveralls are collected and cleaned off site, creating dependency on supplier pickup, response time, and external handling practices. Vale has limited visibility into the full cleaning cycle and less control over volume, garment condition, ownership, and service performance.', N'01 - Imagens/02 - Depois/11309.jpeg', N'An on-site laundry would allow Vale to manage receiving, washing, drying, sorting, and availability of coveralls directly at Long Harbour. This would improve operational control, response time, traceability, garment separation, and visibility over the actual volume cleaned each month.
INSERT INTO #PVC VALUES (11310, N'550315', N'550315', N'Gestão à Vista de Materiais com Pendências', 3, N'Others/Outros', N'Material armazenado em palete sem etiqueta de identificação, comprometendo sua rastreabilidade
INSERT INTO #PVC VALUES (11311, N'545887', N'545887', N'Acompanhamento dos IMOS Automação ', 1, N'Others/Outros', N' O IMOS estava sendo impactado por ordens antigas e pendentes da Automação, decorrentes de sucessivos replanejamentos, indisponibilidade do equipamento, falta de energia e limitações de efetivo para execução das atividades e ordens esquecidas na carteira onde havia pendencia apenas de tratativa.', N'Aderência do indicador semanal', N'10234', N'01 - Imagens/01 - Antes/11311.jpeg', N' O IMOS estava sendo impactado por ordens antigas e pendentes da Automação, decorrentes de sucessivos replanejamentos, indisponibilidade do equipamento, falta de energia e limitações de efetivo para execução das atividades e ordens esquecidas na carteira onde havia pendencia apenas de tratativa.', N'01 - Imagens/02 - Depois/11311.jpeg', N'A aderência do IMOS Automação foi recuperada por meio da revisão das programações, priorização das atividades críticas, alinhamento com a equipe executante e tratativa das ordens recorrentes, garantindo maior execução das OMs e redução do backlog, essa tratativa semanal teve um resultado positivo na aderência desse indicador.', NULL, N'sim', N'Manter o acompanhamento e a rotina com melhoria se faz acontecer.', 0, NULL, N'segurança', '2026-07-10T00:00:00.000', '2026-07-22T15:42:04.000', N'545887', NULL, NULL);
INSERT INTO #PVC VALUES (11312, N'553135', N'543407', N'DISPOSITIVO DE SEGURANÇA MA-83', 2, N'Others/Outros', N'Análise dos riscos durante a manutenção
INSERT INTO #PVC VALUES (11313, N'553135', N'81047717', N'SUPORTE DE FIXAÇÃO DO TUBO DOS CILINDRO TRATOR DE ESTEIRA D6', 1, N'Others/Outros', N'TUBOS SEM A DEVIDA FIXAÇÃO, DESGATE PREMATURO DOS TUBOS
INSERT INTO #PVC VALUES (11314, N'81045351', N'81045351', N'COMPOSTEIRA ', 2, N'Others/Outros', N'A unidade gera diariamente resíduos orgânicos provenientes do preparo e das sobras de alimentos, que são destinados integralmente ao descarte. Essa prática aumenta o volume de resíduos enviados para destinação final, gera custos operacionais e desperdiça um material que poderia ser reaproveitado de forma sustentável.', N'Reduzir o desperdício de resíduos orgânicos por meio da implantação de uma composteira, transformando resíduos em recurso útil, diminuindo os impactos ambientais, incentivando a gestão sustentável de resíduos e promovendo a conscientização ambiental dos colaboradores.', N'10017', N'01 - Imagens/01 - Antes/11314.jpeg', N'Os resíduos orgânicos eram destinados ao descarte, sem processo de reaproveitamento. Aumento do volume de resíduos encaminhados para destinação final, desperdício de matéria orgânica.', N'01 - Imagens/02 - Depois/11314.jpeg', N'Após a implantação da composteira, os resíduos orgânicos passaram a ser reaproveitados na produção de adubo, reduzindo o descarte e fortalecendo as práticas de sustentabilidade da unidade.', NULL, N'A meta foi atingida com a implantação da composteira, permitindo o reaproveitamento dos resíduos orgânicos que antes eram descartados. A iniciativa reduziu o volume de resíduos destinados à coleta, promoveu a produção de adubo orgânico e fortaleceu as práticas de sustentabilidade na unidade.', N'A segregação correta dos resíduos é essencial para o sucesso da compostagem. O engajamento da equipe, a conscientização ambiental e o acompanhamento do processo garantem melhores resultados e possibilitam replicar a iniciativa em outras unidades.', 0, NULL, N'Melhoria da organização do setor, liberação de área de circulação, armazenamento adequado dos materiais e redução do risco de acidentes.', '2026-07-03T00:00:00.000', '2026-07-22T16:09:35.000', N'81045351', NULL, NULL);
INSERT INTO #PVC VALUES (11315, N'81034916', N'81034916', N'SEGURANÇA NO PROCESSO DE CALANDRAGEM', 2, N'Others/Outros', N'Riscos de prensamento/esmagamento por contato acidental com parte móveis da calandra e exposição ergonômicas. 
INSERT INTO #PVC VALUES (11316, N'81058075', N'81058075', N'Controlled Uniform Purchasing and Employee Distribution Process', 3, N'Others/Outros', N'Employees are requesting new uniforms without a formal procedure or clear approval rules. The laundry service has reported approximately 5 to 15 new uniforms per weekly pickup, creating risk of unnecessary purchases, weak cost control, inconsistent decisions, and limited visibility over the real operational need.', N'Establish a standardized process for new uniform acquisition while promoting awareness and accountability among all stakeholders involved.', N'0', N'01 - Imagens/01 - Antes/11316.jpeg', N'Requests may be submitted based on individual need or urgency, without verification of available new or used stock, documented justification, or standard approval criteria. As a result, Vale has limited ability to confirm whether each new uniform is truly required or whether an available new or used uniform could be issued first.', N'01 - Imagens/02 - Depois/11316.jpeg', N'All requests will follow a standard process requiring verification of available new and used stock, justification, approval before purchase, and registration by employee. This will improve purchasing discipline, strengthen accountability, reduce duplicate or emergency purchases, and provide reliable data for monthly cost and demand monitoring.
INSERT INTO #PVC VALUES (11317, N'81058075', N'81058075', N'Rainwater Collection and Reuse from Long Harbour Office Rooftops', 1, N'Others/Outros', N'Rainwater from Long Harbour office rooftops is not currently captured or reused, even though the site receives approximately 1,350 to 1,390 mm of annual precipitation. This creates an opportunity to use an available natural resource to reduce treated water consumption, support environmental goals, and generate potential long-term savings for approved non-potable applications.', N'Promote responsible use of natural resources, support environmental sustainability, and create potential cost savings by reducing the risk of exceeding monthly or annual water consumption limits.', N'0', N'01 - Imagens/01 - Antes/11317.jpeg', N'Rainwater drains from the office rooftops without being collected, stored, or redirected for controlled use. The site continues to rely on treated water for activities that may not require potable water, such as exterior cleaning, floor washing, irrigation, or future support to an on-site laundry if technically approved.', N'01 - Imagens/02 - Depois/11317.jpeg', N'Rainwater would be collected from selected office rooftops, stored in approved tanks, and reused for non-potable activities such as exterior cleaning, floor washing, irrigation, washrooms and potentially to support a future on-site laundry if technically suitable. Goal: Promote responsible use of natural resources, support environmental sustainability, reduce treated water consumption, and lower the risk of exceeding monthly or annual water usage limits. Savings Potential: Based on estimated precipitation, each 1,000 m² of roof area could provide approximately 1.0 to 1.18 million litres/year of usable rainwater, creating savings by offsetting treated water use. This initiative uses a natural resource already available on site and aligns with long-term cost control, sustainability, and operational resilience goals while Engineering refines the technical feasibility.', NULL, N'The initial goal directly addresses the problem by proposing a practical way to capture and reuse rainwater that is currently being lost. While the problem highlights the missed opportunity and continued reliance on treated water, the goal focuses on converting that unused resource into value through reduced water consumption, environmental benefits, and potential cost saving.', N'Responsible use of natural resources can create both environmental and financial value.', 4, 3, N'Improved access to visitor information during emergency situations, enabling faster and more accurate personnel accountability.', '2026-07-22T00:00:00.000', '2026-07-22T17:59:36.000', N'81058075', NULL, NULL);
INSERT INTO #PVC VALUES (11318, N'541850', N'541850', N'Filtro Torre dos​  Comboios Diesel​', 1, N'Open Pit/Poço aberto', N'Os comboios diesel CA02, CV56 e CV58 utilizavam o filtro torre código Vale 13351854 (PN 400007141), identificado pela gestão como um dos principais ofensores de custo da frota, impactando diretamente o orçamento de manutenção.', N'Redução de custos de manutenção, maior disponibilidade potencial, menor frequência de intervenções, padronização .', N'10081', N'01 - Imagens/01 - Antes/11318.jpeg', N'Os comboios diesel CA02, CV56 e CV58 utilizavam o filtro torre código Vale 13351854 (PN 400007141), identificado pela gestão como um dos principais ofensores de custo da frota, impactando diretamente o orçamento de manutenção. Além disso, o componente permanecia associado a planos preventivos e listas de materiais que necessitavam revisão técnica e atualização, exigindo controle mais rigoroso das aprovações, da estratégia de manutenção e da governança dos materiais aplicados. ', N'01 - Imagens/02 - Depois/11318.jpeg', N'mplementar a substituição do filtro torre código Vale 13351854 (PN 400007141) pelo filtro código Vale 13044565 (PN UE610AP40Z) nos comboios diesel CA02, CV56 e CV58, associada à revisão dos planos SAP PM, atualização das listas de tarefas, regularização contratual via ZCON e implantação de controles de rastreabilidade técnica.                                                                              
INSERT INTO #PVC VALUES (11319, N'81058075', N'81058075', N'Monthly Invoice Cut-Off and Accrual Reduction Process', 1, N'Others/Outros', N'At month-end, missing supplier invoices are currently estimated and entered in SAP as accruals. These estimates may not reflect the final invoice value, especially when supplier projections are exceeded. The process also creates rework for Contracts and Finance through accrual creation, approval, reversal, deleted, and subsequent invoice processing.', N'Eliminate rework and improve process efficiency.', N'0', N'01 - Imagens/01 - Antes/11319.jpeg', N'Invoices not received by the month-end deadline require manual accruals based on estimated values. Contracts create the accrual, Finance approves it, the Contract Manager later reverses it, and Finance or Contracts deletes it before the actual invoice can be entered for payment. This adds non-value-added work, delays invoice processing, and increases exposure to estimate variances.', N'01 - Imagens/02 - Depois/11319.jpeg', N'A monthly invoice cut-off date will be established. Invoices received by the cut-off date will be processed in the current month, while invoices received after the cut-off date will be processed in the following month rather than accrued using uncertain estimates. This approach simplifies the workflow, reduces rework, improves consistency, and supports more disciplined period-end processing.
INSERT INTO #PVC VALUES (11320, N'81020908', N'532815', N'Redução de peneiras em teste de granulometria ', 1, N'Others/Outros', N'Durante os testes de moabilidade, acontece a etapa de peneiramento, onde utilizávamos 7 peneiras para descobri o P80, que significa que 20% do material precisa ficar retido na malha de 212 e 80% passar nas malhas subsequentes, para descobri o tempo de moagem necessário. Demandávamos 20 minutos de peneiramento para cada amostra.  ', N'Reduzir tempo de peneiramento', N'10129', N'01 - Imagens/01 - Antes/11320.jpeg', N'Durante os testes de moabilidade, acontece a etapa de peneiramento, onde utilizávamos 7 peneiras para descobri o P80, que significa 20% do material precisa ficar retido na malha de 212 e 80% passar nas malhas subsequentes, para descobri o tempo de moagem necessário. Demandávamos 20 minutos de peneiramento para cada amostra. Com a necessidade de fazer muitos peneiramentos em um dia, precisávamos reduzir o tempo do processo e termos agilidade nas demais etapas. ', N'01 - Imagens/02 - Depois/11320.jpeg', N' Sabendo a massa inicial de cada amostra foi possível então reduzir o número de peneiras para 4, utilizando as malhas maiores, dessa forma conseguimos identificar quanto de material passou e ficou retido. Com a mitigação das peneiras, reduzimos 10 minutos de peneiramento durante o teste. ', NULL, N'O problema foi resolvido, a meta de redução de tempo foi alcançada sem modificar o resultado.', N'Aprendemos que diminuir os processos sem fugir do padrão reduz tempo e esforço.', 0, NULL, NULL, '2026-07-20T00:00:00.000', '2026-07-23T10:38:03.000', N'81020908', NULL, NULL);
INSERT INTO #PVC VALUES (11321, N'81019448', N'81019448', N'Otimização do Fluxo de Homologação por Meio da Padronização e Governança', 1, N'Projects/Projetos', N'Falta de conhecimento e alinhamento dos requisitantes sobre o processo de desenvolvimento e homologação de materiais e fornecedores, resultando no preenchimento incorreto de documentos,  ocasionando retrabalhos, atrasos, riscos de compliance, inconsistências na aplicação de SAT, PT e RET e subjetividade na avaliação dos resultados dos testes.', N'Reduzir a variabilidade e aumentar a confiabilidade do processo de homologação de materiais por meio da capacitação dos requisitantes quanto às diretrizes, padronização das etapas, definição de responsabilidades, estabelecimento de KPIs quantitativos e reforço dos requisitos de compliance e gestão de riscos.', N'10015', N'01 - Imagens/01 - Antes/11321.jpeg', N'Os requisitantes possuíam níveis distintos de conhecimento sobre o processo, suas responsabilidades e os critérios para utilização das ferramentas SAT, PT e RET. Eram recorrentes solicitações com informações incompletas/incorretas, definição inadequada de KPIs, dúvidas sobre fluxos e papéis entre as áreas, além de desvios relacionados aos requisitos de compliance e gestão de riscos. Esse cenário gerava retrabalhos, devoluções, aumento do lead time das homologações e menor confiabilidade na tomada de decisão.', N'01 - Imagens/02 - Depois/11321.jpeg', N'KPIs quantitativos para avaliação dos testes.
INSERT INTO #PVC VALUES (11322, N'92000525', N'81019022', N'Melhoria do aterramento dos motores partida', 2, N'Others/Outros', N'Ao ter curto circuito com principio de incêndio na Pz 02 com cabo de aterramento do motor de partida fizemos essa melhoria', N'Com essa melhoria temos mais segurança operacional e evitamos possivel  principio de incêndio podendo ter perda material', N'10324', N'01 - Imagens/01 - Antes/11322.jpeg', N'Foi identificada ocorrência de curto-circuito com princípio de incêndio na Pz-02, originado no cabo de aterramento do motor de partida. Como ação corretiva, foi realizada a melhoria no sistema para evitar novas falhas.', N'01 - Imagens/02 - Depois/11322.jpeg', N'Melhoria realizada no aterramento do motor de partida da Pz-02. Aumento da segurança operacional e mitigação do risco de princípio de incêndio e danos materiais.', NULL, N'Sim', N'Pequenas falhas elétricas geram grandes riscos Um cabo de aterramento mal fixado, pode parar a operação e gerar perda material. ', 0, NULL, NULL, '2026-06-06T00:00:00.000', '2026-07-23T11:39:45.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11323, N'525833', N'525833', N'Project de acompanhamento dos Projetos de GP', 1, N'Others/Outros', N'Ausência de acompanhamento dos projetos de responsabilidade do time de grande parada', N'Visibilidade e acompanhamento', N'10023', N'01 - Imagens/01 - Antes/11323.jpeg', N'Não havia acompanhamento estruturado dos projetos da Grande Parada, dificultando o controle de prazos, marcos e a visibilidade das atividades em andamento.', N'01 - Imagens/02 - Depois/11323.jpeg', N'Foi implantado um Project para gestão dos projetos, aumentando a visibilidade, o controle dos prazos e a assertividade no acompanhamento das atividades.', NULL, N'Sim, melhoramos o acompanhamento e demos visibilidade', N'Melhoria no acompanhamento', 0, NULL, N'QUALIDADE, SATISFAÇÃO DA EQUIPE DE EXECUÇÃO, ', '2026-07-13T00:00:00.000', '2026-07-23T11:51:18.000', N'525833', NULL, NULL);
INSERT INTO #PVC VALUES (11324, N'81037003', N'479348', N'SUPORTE PARA TRANSPORTE DOS RADIADORES ', 2, N'Others/Outros', N'TRANSPORTE ERA REALIZADO COM PALETE, HAVIA RISCO DE TOMBAMENTO DA CARGA E QUEBRA DO PALETE ', N'TRANSPORTE SEGUROS ', N'10031', N'01 - Imagens/01 - Antes/11324.jpeg', N'Identificou-se que o transporte de radiadores em paletes apresentava risco de quebra do palete e instabilidade da carga, podendo resultar em tombamentos, acidentes de trabalho e avarias no produto. ', N'01 - Imagens/02 - Depois/11324.jpeg', N'Foi fabricado um suporte específico para o transporte dos radiadores, aumentando a segurança da movimentação e eliminando o risco de tombamento da carga.', NULL, N'A ação eliminou o risco identificado, tornando o transporte dos radiadores mais seguro e estável.', N'Que devemos fazer o transporte de matérias de forma correta ', 0, NULL, N'Centralização das ideias e problemas da área, padronização do fluxo de melhoria contínua, definição clara de responsáveis e prazos, maior rastreabilidade das ações, gestão visual dos cronogramas e fortalecimento da participação da equipe. A solução também criou uma base estruturada para monitorar a aderência aos planos de ação e a evolução das iniciativas.', '2026-07-22T00:00:00.000', '2026-07-23T12:06:21.000', N'81037003', NULL, NULL);
INSERT INTO #PVC VALUES (11325, N'92000525', N'81024026', N'Switch de acionamento do controle Remoto Concluída Produtividade', 2, N'Others/Outros', N'Antes esse Switch era exposto e o operador constantemente desligava involuntariamente com braço esquerdo...causando perda operacional', N'realizada melhoria para proteção/relocação do componente', N'10324', N'01 - Imagens/01 - Antes/11325.jpeg', N'Anteriormente o switch ficava exposto, o que ocasionava desligamentos involuntários pelo operador com o braço esquerdo durante a operação.', N'01 - Imagens/02 - Depois/11325.jpeg', N'COM A PROTEÇÃO DO SWITCH ELIMINAMOS ESSE DESLIGAMENTO INVOLUTARIO E PERDA OPERACIONAL MELHORANDO PRODUTIVIDADE E SEGURANCA NAS ATIVIDADES EVITANDO DESLOCAMENTO DA MANUTENÇÃO PARA REINICIAR EQUIPAMENTO ', NULL, N'Sim', N'Proteção física evita erro humano Componentes críticos como botão de parada/emergência não podem ficar expostos na área de alcance do operador. Proteção simples evita falha por descuido.', 0, NULL, NULL, '2026-06-05T00:00:00.000', '2026-07-23T12:20:36.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11326, N'81037003', N'479348', N'Suporte de transporte de piças do freio ', 1, N'Others/Outros', N'equipamentos eram transportados em paletes', N'transporte com segurança ', N'10031', N'01 - Imagens/01 - Antes/11326.jpeg', N'o transporte das pinças do freio dos moinhos eram realizadas  em paletes, existia o risco de quebra do palete e tombamento da carga, expondo os colaboradores a possíveis acidentes e gerando perdas de material.', N'01 - Imagens/02 - Depois/11326.jpeg', N'Foi fabricado um suporte específico para o transporte das pinças, aumentando a segurança da movimentação e eliminando o risco de tombamento da carga', NULL, N'A meta foi atingida com a implementação do suporte, eliminando o risco de tombamento e aumentando a segurança no transporte.', N'transporte seguro', 0, NULL, N'Increased visibility of Health & Safety communications.
INSERT INTO #PVC VALUES (11327, N'81037003', N'81039148', N'suporte de sustentação de vigas e cantoneiras', 3, N'No Replication/Sem replicação', N'Não tínhamos um local adequado para realizar o armazenamentos de nossos matérias ', N'manter os matérias organizados ', N'10031', N'01 - Imagens/01 - Antes/11327.jpeg', N'Não havia um local adequado para o armazenamento dos materiais, resultando em desorganização da área, dificuldade de acesso aos itens e risco de acidentes durante a movimentação.', N'01 - Imagens/02 - Depois/11327.jpeg', N'Foi fabricado um suporte específico para armazenamento dos materiais, proporcionando melhor organização, aproveitamento do espaço e maior segurança na área de trabalho.', NULL, N'A meta foi atingida com a implantação do suporte, garantindo armazenamento adequado, organização dos materiais e maior segurança operacional.', N'A criação de estruturas adequadas para armazenamento melhora a organização, a segurança e a produtividade da área.', 0, NULL, N'Esse Kaizen ficou muito forte, evidenciando claramente os ganhos de digitalização, gestão visual, produtividade e melhoria do processo de planejamento de manutenção, que são fatores normalmente bem avaliados pela Vale Base Metals. 🚀', '2026-07-14T00:00:00.000', '2026-07-23T12:33:19.000', N'81037003', NULL, NULL);
INSERT INTO #PVC VALUES (11328, N'81026906', N'81026906', N'Revestimento Metálico', 1, N'Others/Outros', N'Grande incidência de desgaste e quebra de tambores de dobra.', N'Troca de todos os tambores de cauda das britagens', N'10178', N'01 - Imagens/01 - Antes/11328.jpeg', N'Durante inspeções operacionais, foi identificada uma elevada incidência de descolamento das placas de revestimento nos tambores de cauda das correias transportadoras. Essa falha tem gerado uma série de consequências operacionais relevantes:
INSERT INTO #PVC VALUES (11329, N'81040303', N'81040303', N'Aplicativo de turno', 1, N'Others/Outros', N'Equipes de manutenção necessitavam de uma aplicação para gerenciamento das atividades ocorridas no turno, com acesso as paradas do sistema GPVm, inclusão de novos registros e abertura de pendências para o turno seguinte.', N'Gerenciamento, otimização', N'10293', N'01 - Imagens/01 - Antes/11329.jpeg', N'Registros enviados via Whatsapp em grupos de equipe.', N'01 - Imagens/02 - Depois/11329.jpeg', N'Desenvolvimento de aplicativo em Power Apps para gestão operacional de ocorrências e pendências do GPVm, permitindo a consulta das paradas registradas no sistema, inclusão de comentários e anexação de evidências diretamente aos apontamentos. A solução possibilita ainda o cadastro de novas ocorrências, abertura e acompanhamento de pendências, proporcionando maior controle, rastreabilidade e gestão das atividades em aberto. Como complemento, o aplicativo oferece a geração automática de relatórios em PDF contendo todas as ocorrências registradas no turno, facilitando o compartilhamento das informações e apoiando a tomada de decisão operacional.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/90d8e0e8-6a87-4225-a4a7-c077ec7c8a12?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=8e2fad7f-8c9f-4e4b-8bb9-7c250544ce54&sourcetime=1784824484635', N'Houve uma melhora significativa no gerenciamento das informações do turno, permitindo um acompanhamento dos acontecimentos e otimização de tempo com geração de relatórios de turno.', N'Trabalho em equipe', 500000, 1, N'don''t have to use batteries any more', '2026-07-01T00:00:00.000', '2026-07-23T13:44:01.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (11330, N'81056094', N'81050495', N'Visitor Management System', 1, N'Others/Outros', N'Created a digital Visitor Sign-In Application to replace a paper-based process. The solution improves efficiency, reduces manual data entry, enhances data accuracy, and provides better tracking and reporting of site visitors.', N'Improve the visitor sign in process at Vale corporate offices', N'10353', N'01 - Imagens/01 - Antes/11330.jpeg', N'Visitor sign-in relied on paper records and manual tracking, resulting in extra administrative effort, inconsistent data, and limited visibility into visitor activity.', N'01 - Imagens/02 - Depois/11330.jpeg', N'Implemented a standardized digital visitor sign-in process that improved efficiency, data accuracy, visitor tracking, and reporting. ', NULL, N'Yes - The solution successfully addressed the identified issues by digitizing and standardizing the visitor sign-in process, improving efficiency, data accuracy, tracking, and reporting.', N'User feedback and process standardization were key to developing an effective solution.', 0, NULL, N'Improved user confidence, reduced troubleshooting effort, and accelerated issue resolution.', '2026-07-17T00:00:00.000', '2026-07-23T13:48:22.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11331, N'92000525', N'81063738', N'Suporte base para o armário de material de combate a incêndio ', 1, N'Others/Outros', N'o armário de material de combate a incêndio, estava com a base diretamente no chão. vindo a danificar muito mais rápido ', N'Preservar a integridade do armário ', N'10324', N'01 - Imagens/01 - Antes/11331.jpeg', N'O armário de material de combate á incêndio ficava no chão, com risco de danificar mais rápido devido ao contato com água durante a limpeza da área. ', N'01 - Imagens/02 - Depois/11331.jpeg', N'Mais durabilidade do armário ', NULL, N'Sim', N'Sentimento de dono', 0, NULL, N'Reduced manual effort, improved inventory accuracy, and simplified ongoing printer administration.', '2026-06-12T00:00:00.000', '2026-07-23T14:20:06.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11332, N'81056094', N'81050495', N'Centralized Imaging Station for Computer Deployments', NULL, N'Others/Outros', N'Technicians spent time waiting for image downloads before preparing and deploying computers.', N'Reduce technician wait time by providing a centralized location for computer images.', N'10353', N'01 - Imagens/01 - Antes/11332.jpeg', N'Images had to be downloaded directly from server as needed, creating delays and reducing technician productivity.', N'01 - Imagens/02 - Depois/11332.jpeg', N'Configured a dedicated tower PC for Techs to remote in and store the images creating a central access point on the computer rather than having to download from the network', NULL, N'The imaging station eliminated unnecessary wait times by providing immediate access to images.', N'Centralized resources reduce wait times and improve technician efficiency.', 0, NULL, N'Easier flow of trucks ', '2026-06-08T00:00:00.000', '2026-07-23T14:38:04.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11333, N'1013432', N'1013432', N'Freight Consolidation', 1, N'No Replication/Sem replicação', N'Multiple inbound requests were being uploaded to the freight optimizer and shipped as individual packages. Shipper was contacted to consolidate all the freight once a week to be shipped as one request to save on freight costs. ', N'Cost Savings', N'0', N'01 - Imagens/01 - Antes/11333.jpeg', N'On average each shipment cost was $339 in 2026', N'01 - Imagens/02 - Depois/11333.jpeg', N'Shipments are consolidated weekly at an average cost of $250 per shipment', NULL, N'Yes', N'Methodology can be used in other scenerios', 2328, 3, N'Keep the drivers safe', '2026-07-22T00:00:00.000', '2026-07-23T15:06:34.000', N'1013432', NULL, NULL);
INSERT INTO #PVC VALUES (11334, N'92000525', N'520914', N'Baixa visibilidade das Roc L8 ao acessar mina Corrigido', 1, N'Others/Outros', N'Ao acessar mina a operação com equipamento Roc L8 ficava exposto devido baixa iluminação do equipamento a noite. causando insegurança para operador', N'Melhorar a visibilidade do operador', N'10324', N'01 - Imagens/01 - Antes/11334.jpeg', N'Durante a operação noturna na mina, o equipamento Roc L8 apresentava baixa iluminação frontal, expondo o operador e causando insegurança durante a locomoção. ', N'01 - Imagens/02 - Depois/11334.jpeg', N'Foi realizado a instalação do psicocoflex frontal, aumentando a visibilidade do equipamento e a segurança do Operador durante a locomoção em áreas de curto deslocamento.', NULL, N'Sim', N'Baixa iluminação no equipamento expõe o operador e aumenta o risco de colisão e atropelamento na mina à noite', 0, NULL, N'Redução no tempo de reforma ', '2026-06-11T00:00:00.000', '2026-07-23T15:06:59.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11335, N'1009931', N'202638', N'CMD Scrap Removal', 1, N'Others/Outros', N'A large amount of scrap metal had been gathering around site and need to be removed', N'Sell Scrap Metal', N'0', N'01 - Imagens/01 - Antes/11335.jpeg', N'400TO of scrap metal had accumulated on site. Our internal scrap contractor was unable to remove this volume of scrap metal, and our negotiated contract price was much lower than market value of $50/TO.', N'01 - Imagens/02 - Depois/11335.jpeg', N'Vale negotiated a new agreement with Newco Metals to support the removal of large scrap volumes and maximize returns through market-value pricing @ $110/TO.', NULL, N'Yes, the new scrap removal and sales process generated approximately 44K in revenue for Vale, representing a 24K increase over the 20K that would have been earned using the previous method.', N'Accumulating scrap reaped a higher rate of return and value for Vale', 24000, 3, N'Será ampliado para os demais transportadores', '2026-07-10T00:00:00.000', '2026-07-23T15:44:23.000', N'1009931', NULL, NULL);
INSERT INTO #PVC VALUES (11336, N'495045', N'495045', N'SUPORTE DE PONTO DE ANCORAGEM PARA CINTO DE SEGURANÇA', 2, N'Crusher/Britadeira', N'Durante a aferição da APF, foi identificada a ausência de ponto de ancoragem para o cinto de segurança. Trata-se de uma atividade crítica, com elevado risco de queda do colaborador para o interior do britador, podendo resultar em acidente grave ou fatal. É necessária a implementação de um sistema de ancoragem adequado antes da execução da tarefa.', N'AUMENTAR E GARANTIR A SEGURANÇA NA AFERIÇÃO DA APF', N'10293', N'01 - Imagens/01 - Antes/11336.jpeg', N'ANTES A ATIVIDADE ERA REALIZADA SEM O CINTO DE SEGURANÇA POR FALTA DE PONTO DE ANCORAGEM TRAZENDO RISCOS ACIDENTES E INCIDENTES.', N'01 - Imagens/02 - Depois/11336.jpeg', N'FOI FABRICADO UM SUPORTE E INSTALADO NA ESTRUTURA PARA SERVIR DE PONTO DE ANCORAGEM ONDE COLOCA-SE O TRAVA QUEDA RETRATIL JUNTAMENTE COM CINTO MITIGANDO TODOS OS RISCOS DE QUEDA.', NULL, N'SIM, POIS COM ESSE DISPOSITIVO ELIMINAMOS O RISCO DE QUEDA DO OPERADOR DENTRO DO BRITADOR DURANTE A AFERIÇÃO DA APF.', N'SOLUÇÕES SIMPLES PARA GARANTIR A SEGURANÇA', 0, NULL, N'Resultados Obtidos
INSERT INTO #PVC VALUES (11337, N'81007925', N'81007925', N'Fábrica de Ideias e Salobo Solutions: Da Ideia à Execução', 1, N'Others/Outros', N'Ideias e problemas eram discutidos de forma descentralizada, sem um fluxo estruturado para registro, priorização e acompanhamento. Isso dificultava a definição de responsáveis e prazos, reduzia a rastreabilidade das ações e aumentava o risco de oportunidades de melhoria não avançarem até a implementação.', N'Estruturar o ciclo de melhoria contínua da área, desde o brainstorming e registro de ideias e problemas até a definição de responsáveis, prazos, ações e resultados, aumentando a participação, a rastreabilidade e a efetividade na implementação das soluções.', N'10078', N'01 - Imagens/01 - Antes/11337.jpeg', N'Ideias e problemas eram discutidos em reuniões e canais distintos, sem um fluxo padronizado para registro, priorização e acompanhamento. Não havia visão consolidada de responsáveis, prazos e andamento das ações, aumentando o risco de oportunidades perderem visibilidade ou não avançarem até a implementação.', N'01 - Imagens/02 - Depois/11337.jpeg', N'Foram implantadas duas soluções complementares: a Fábrica de Ideias, para brainstorming, registro e priorização de oportunidades, e o Salobo Solutions, para definir responsáveis, prazos, planos de ação e status. A gestão visual em Power BI padronizou o fluxo da ideia à solução, ampliando a rastreabilidade, o acompanhamento gerencial e a efetividade das ações.', N'https://padlet.com/CaioFogliarine/fabrica-de-ideias-7vozi24j77i9e3jj /  https://app.powerbi.com/groups/me/apps/fb9add9f-c44e-43e7-bbe7-e0c8e3bd0c6c/reports/350a81d8-2f37-43d5-bf82-121ac2455eb8/79a24566b2a0896eac72?experience=power-bi ', N'Comparação com a meta inicial/declaração de problemas:
INSERT INTO #PVC VALUES (11338, N'81038056', N'81038056', N'Cisco Call Manager Cleanup and License Management Process', 1, N'Others/Outros', N'Call Manager contained inactive and unregistered devices and Numbers, making license and number management difficult and increasing manual effort to identify devices and numbers suitable for removal. we were running out of licenses. Cleanup activities were inconsistent and time-consuming.', N'Reduce wasted licenses and administrative effort by establishing a repeatable cleanup process for inactive devices.', N'10100', N'01 - Imagens/01 - Antes/11338.jpeg', N'Manual device review.
INSERT INTO #PVC VALUES (11339, N'81038056', N'81038056', N'Deployment of Digital Displays to Improve Health & Safety Communications at OOC', 1, N'Others/Outros', N'Health & Safety updates, awareness campaigns, and critical communications relied on traditional communication methods that may not always reach employees at the right time or in the right location. There was an opportunity to improve visibility of important safety information within operational areas.', N'Improve visibility, accessibility, and reach of Health & Safety communications by deploying digital display technology in key operational areas at OOC.', N'10100', N'01 - Imagens/01 - Antes/11339.jpeg', N'Health & Safety information was distributed through existing communication channels.
INSERT INTO #PVC VALUES (11340, N'510839', N'510839', N'Dashboard Projeção de Planos de Manutenção de Automação – Base SAP IP19', 1, N'Others/Outros', N'O acompanhamento dos planos de manutenção da automação era realizado por meio de relatórios AMS M+3 com grande volume de dados e baixa capacidade analítica. A ausência de indicadores visuais e filtros específicos dificultava a identificação rápida dos planos programados, aumentando o tempo de análise e reduzindo a eficiência do planejamento da manutenção.', N'Reduzir o tempo de análise dos planos de manutenção da automação, aumentando a visibilidade das informações, a assertividade do planejamento e a rapidez na tomada de decisão através da digitalização e consolidação dos dados em um dashboard interativo.', N'10234', N'01 - Imagens/01 - Antes/11340.jpeg', N'O acompanhamento dos planos de manutenção da Automação era realizado no AMS M+3, exigindo filtros e consultas manuais, dificultando análises, visualização dos dados e a tomada de decisão.', N'01 - Imagens/02 - Depois/11340.jpeg', N'Desenvolvido dashboard Power BI com filtros dinâmicos, indicadores visuais e cores para AMS dos planos, facilitando análises, priorização das atividades e tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/07e3fe80-a920-4704-84d5-182a48eb6756/f92168403940559d4135?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. Maior visibilidade dos planos programados, padronização das análises, redução do tempo de busca por informações, priorização mais eficiente das atividades e suporte à tomada de decisão da equipe de PCM.', N'A utilização de dashboards interativos com indicadores visuais e segmentação dinâmica aumenta a produtividade das análises, padroniza informações e melhora a tomada de decisão.', 0, NULL, N'Renamed 16,000 PDF files and generated the required spreadsheet within minutes.', '2026-07-22T00:00:00.000', '2026-07-23T19:20:56.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11341, N'81046597', N'81046597', N'Ferramenta de Análise de Testes de Oportunidade', 1, N'Open Pit/Poço aberto', N'Falta de aprofundamento na análise dos desvios sob a ótica da confiabilidade humana, comprometendo a consistência da classificação das infrações.', N'Padronizar a análise e classificação de desvios operacionais', N'10293', N'01 - Imagens/01 - Antes/11341.jpeg', N'Classificação de desvios baseada apenas no procedimento ou no item descumprido, sem aprofundamento das causas do descumprimento.', N'01 - Imagens/02 - Depois/11341.jpeg', N'Classificação estruturada com análise dos fatores de confiabilidade humana, permitindo identificar e tratar as causas dos desvios de forma mais assertiva, com melhor direcionamento dos inspetores de DBU.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/5c4ce671-9ac9-4b16-953f-d1556a080401/c61511ca5aab9b4e5902?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. O problema foi resolvido por meio da implementação de uma ferramenta estruturada para análise dos desvios baseada nos fatores de confiabilidade humana.', N'Análise estruturada reduz a subjetividade das avaliações e permite ações mais eficazes.', 0, NULL, N'100% dos materiais preparados e revisados com antecedência, garantindo apresentações de alta qualidade, comunicação clara e maior confiança nas tomadas de decisão.', '2026-07-22T00:00:00.000', '2026-07-23T23:41:39.000', N'81046597', NULL, NULL);
INSERT INTO #PVC VALUES (11342, N'81036736', N'81036736', N'Head Lamp Charging Station', 1, N'Others/Outros', N'Not being able to find a charger for head lamp having to have head lamp in tech room on desk', N'Always have a charged headlamp', N'0', N'01 - Imagens/01 - Antes/11342.jpeg', N'Before adding in head lamp changing station', N'01 - Imagens/02 - Depois/11342.jpeg', N'Now we can hang up our hard hats and charge our head lamps in the changeroom.', NULL, N'Charging station for head lamp. Don''t have to use batteries. A place to hang up our hard hats to charge our head lamps. so, we don''t have to go looking for the right cords and a place to plug them in.', N'Easy way to do thing', 5000, 3, NULL, '2026-07-03T00:00:00.000', '2026-07-24T00:50:11.000', N'81036736', NULL, NULL);
INSERT INTO #PVC VALUES (11343, N'81056094', N'81049500', N'LTE Surface Testing Environment for Underground Tablets', NULL, N'Others/Outros', N'Tablets were deployed underground without prior LTE testing, resulting in user complaints and troubleshooting delays.', N'Enable testing of LTE tablets on surface before underground deployment to identify issues early and improve reliability.', N'10349', N'01 - Imagens/01 - Antes/11343.jpeg', N'No LTE test environment existed on surface. Issues were discovered only after tablets were deployed underground.', N'01 - Imagens/02 - Depois/11343.jpeg', N'Installed LTE equipment on surface, allowing tablets to be tested and validated before underground deployment.', NULL, N'The LTE test environment enabled pre-deployment validation, addressing the root cause of deployment complaints.', N'Testing equipment in a production-like environment before deployment reduces support issues and user frustration.', 0, NULL, NULL, '2026-06-23T00:00:00.000', '2026-07-24T08:47:58.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11344, N'81056094', N'81049500', N'Network Integration of Xerox Printers in Thompson', NULL, N'Others/Outros', N'Some printers relied on local or USB connections, limiting visibility, management, and automated services.
INSERT INTO #PVC VALUES (11345, N'81009995', N'81009995', N'Truck Scale Access Reading', 1, N'No Replication/Sem replicação', N'Without an access reading, the shipper/receiver does not know if the scale is operating effectively or not.', N'Better access to scale system', N'10255', N'01 - Imagens/01 - Antes/11345.jpeg', N'No information screen to show when scale is not working', N'01 - Imagens/02 - Depois/11345.jpeg', N'Proper reading to show when scale is not operating correctly', NULL, N'Information to allow our shipper/receiver better access to our scale', N'better understanding of our scale operations ', 0, NULL, N'- Improved accessibility for technicians of all heights.
INSERT INTO #PVC VALUES (11346, N'81009995', N'81009995', N'Disposable Pants at Shipping Office', 1, N'Others/Outros', N'Drivers show up with shorts and cannot enter the plant', N'Give drivers disposable pants to enter the plant', N'10255', N'01 - Imagens/01 - Antes/11346.jpeg', N'No disposable pants for drivers', N'01 - Imagens/02 - Depois/11346.jpeg', N'Disposable pants for drivers', NULL, N'Allow drivers to enter the plant ', N'Give drivers the ability to enter the plant', 0, NULL, N'Melhorou na parte da segurança, pois temos um local adequado para armazenar os itens de segurança e na parte de ajustes em campo,pois com as ferramentas no malão, pequenos ajustes podem ser feitos em campo', '2026-07-23T00:00:00.000', '2026-07-24T12:00:40.000', N'81009995', NULL, NULL);
INSERT INTO #PVC VALUES (11347, N'388959', N'388959', N'Kit de revestimento de caçamba WE1850', 1, N'Others/Outros', N'Durante a reforma de caçamba preparar o material de revestimento é elevado, consumindo mão de obra da caldeiraria e impossibilitando outras reformas', N'Criar Kit de revestimento para reforma da caçamba', N'10081', N'01 - Imagens/01 - Antes/11347.jpeg', N'O material era confeccionado na caldeiraria, elevando o tempo total de reforma da caçamba', N'01 - Imagens/02 - Depois/11347.jpeg', N'Desenvolvido um kit de revestimento para reforma da caçamba.', NULL, N'Redução no tempo de reforma ', N'agilidade na reforma de componentes', 0, NULL, N'.', '2026-07-23T00:00:00.000', '2026-07-24T12:50:32.000', N'388959', NULL, NULL);
INSERT INTO #PVC VALUES (11348, N'81026906', N'502547', N'Suporte RAC 07', 1, N'Others/Outros', N'Má fixação das proteções RAC 07', N'Melhor fixação das proteções RAC 07', N'10178', N'01 - Imagens/01 - Antes/11348.jpeg', N'As proteções RAC 07 apresentavam fixação inadequada, ocasionando o desprendimento e a queda das grades durante a operação. Essa condição expunha partes móveis do equipamento, aumentando o risco de contato acidental e comprometendo a segurança operacional.', N'01 - Imagens/02 - Depois/11348.jpeg', N'Após a implantação do suporte de fixação, as grades passaram a apresentar maior estabilidade e segurança, eliminando ocorrências de desprendimento durante a operação. Além disso, a solução proporcionou mais agilidade nas atividades de montagem e desmontagem, reduzindo o tempo de intervenção e aumentando a eficiência operacional.', NULL, N'Meta atingida', N'Substituir as demais fixações de toda britagem', 0, NULL, N'Produtividade.
INSERT INTO #PVC VALUES (11349, N'81029574', N'81035347', N'Controle Automatizado de Manutenção da Perfuratriz', NULL, N'Others/Outros', N'O registro das atividades que envolviam a manutenção eram realizados de forma manual e descentralizada, gerando um retrabalho nas buscas de informações e dificultava a analise das principais falhas do equipamento.', N'Automatização dos apontamentos do equipamento PF 6001', N'10171', N'01 - Imagens/01 - Antes/11349.jpeg', N'O registro das manutenções da perfuratriz era realizado de forma manual e descentralizada, dificultando o acompanhamento preciso do tempo gasto nas intervenções e o histórico das correções executadas. Isso gerava retrabalho na busca de informações e dificultava a análise das principais falhas do equipamento.', N'01 - Imagens/02 - Depois/11349.jpeg', N'Foi desenvolvido uma planilha automatizada para a gestão das manutenções da perfuratriz, possibilitando o registro preciso dos tempos de intervenção e das correções executadas. Essa melhoria aumentou o controle das informações, reduziu erros de apontamento e facilitou a análise de falhas recorrentes. Além disso, contribui para a otimização da disponibilidade do equipamento e para o aumento da precisão de indicadores operacionais, como DF (Disponibilidade Física) e UT (Utilização), proporcionando maior confiabilidade na tomada de decisões e no acompanhamento da performance do equipamento.', NULL, N'Sim. A melhoria aumentou o controle das informações reduziu erros de apontamentos. Facilitando a analises de falhas recorrentes. E contribuiu para a otimização da disponibilidade do equipamento.', N'A necessidade de uma padronização e no apontamento das informações', 0, NULL, NULL, '2026-01-01T00:00:00.000', '2026-07-24T13:51:15.000', N'81029574', NULL, NULL);
INSERT INTO #PVC VALUES (11350, N'81046537', N'81063692', N'Grade de Proteção do Para-brisa (Cabine)', 2, N'Others/Outros', N'Durante a inspeção técnica de rotina na Perfuratriz PZ02, foi identificado um desvio crítico na cabine de operação. A grade de proteção frontal do para-brisa, responsável por proteger o operador e o vidro contra projeção de detritos e impactos, encontrava-se fixada de maneira precária utilizando uma corda (amarração paliativa).
INSERT INTO #PVC VALUES (11351, N'81047819', N'81006709', N'Perfuração sem Colapso ', 2, N'Open Pit/Poço aberto', N'Dificuldades na execução da perfuração de pré-corte e dos furos do plano de produção com perfuratrizes de pequeno diâmetro em áreas com elevada percolação de água. A presença de água e forro ocasionava instabilidade dos furos, perda de eficiência operacional, geração de offsets, material agregado ao talude projetado (aumentando o atividade de saneamento, bem como o risco de projeção de material durante à atividade) e risco de não atendimento aos parâmetros de qualidade e profundidade especificados, impactando o desempenho das atividades de perfuração, desmonte.
INSERT INTO #PVC VALUES (11352, N'81046755', N'483391', N'TRACKUP - APP DOS INDICADORES DA SLA - LOGSUP', 1, N'Others/Outros', N'AUSÊNCIA DO CONTROLE E VISIBILIDADE EM TEMPO REAL SOBRE A EXECUÇÃO DO CRONOGRAMA DE COLETAS DA LOGSUP, dificultando a identificação dos desvios, ACOMPANHAMENTOS DOS INDICADORES DA SLA E PRINCIPALMENTE DA ADERE^NCIA DE COLETAS DO SITE SOSSEGO.', N'REDUÇÃO 100%', N'10079', N'01 - Imagens/01 - Antes/11352.jpeg', N'O PROCESSO ERA REALIZADO CON CONTROLES MANUAIS E INFORMAÇÕES DISPERSAS, SEM ACOMPANHAMENTO EM TEMPO REAL DA EXECUÇÃO DO CRONOGRAMA. A IDENTIFICAÇÃO DOS DESVIOS, PONTOS NÃO REALIZADOS, OCORRIA DE FORMA TARDIA, DIFICULTADO A TOMADA DE DECIÇÃO E ATUAÇÃO IMEDIATA NAS TRATAIVAS.', N'01 - Imagens/02 - Depois/11352.jpeg', N'IMPLANTAÇÃO DO APP TRACKUP PARA ACOMPANHAMENTO EM TEMPO REAL DA EXECUÇÃO DO CRONOGRAMA, MONITORAMENTO DOS DESVIOS E GESTÃO DOS INDICADORES DE ADERÊNCIA E DOS DEMAIS INDICADORES DO SLA.', N'https://trackup.logsupsystem.com.br/login', N'SIM, A IMPLANTAÇÃO DO TRACKUP SOLUIONOU A FALTA DE VISIBILIDADE E CONTROLE, PERMITINDO ACOMPANHAMENTO EM TEMPO REAL DA ADERÊNCIA DE COLETAS', N'O APP realiza acompanhamento em tempo real da aderência de coletas tratando os desvios de forma imediataa', 0, NULL, N'NA', '2026-04-06T00:00:00.000', '2026-07-24T14:36:08.000', N'81046755', NULL, NULL);
INSERT INTO #PVC VALUES (11353, N'81056094', N'201795', N'Automate the renaming of 16,000 PDF files and generate a record of the new file names.', NULL, N'Others/Outros', N'Renaming 16,000 PDF files manually was extremely time-consuming and had already taken weeks of effort.', N'Automate the renaming of 16,000 PDF files and generate a record of the new file names.', N'10100', N'01 - Imagens/01 - Antes/11353.jpeg', N'Files had to be renamed individually, creating a significant workload and risk of human error.', N'01 - Imagens/02 - Depois/11353.jpeg', N'Developed a PowerShell script to automatically rename PDF files and export the updated names to Excel.', NULL, N'Automation replaced weeks of manual effort and completed the task accurately in a fraction of the time.', N'Simple automation can eliminate repetitive tasks and deliver significant time savings.', 0, NULL, N'Instalar um suporte para a mangueira ficar guardado de forma organizada', '2026-07-17T00:00:00.000', '2026-07-24T14:38:30.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11354, N'499365', N'499365', N'Informativo da Programação Semana do Diálogo de Saúde e Segurança.', 2, N'Others/Outros', N'A ausência de preparação adequada dos materiais compromete a qualidade das entregas, a credibilidade das informações e o impacto das apresentações junto ao time de gestão de capital.', N'Promover a conscientização e o engajamento do time de FP&A da Gestão de Capital nas práticas de Saúde e Segurança, fortalecendo a cultura de prevenção, cuidado com as pessoas e operação segura no dia a dia.', N'10367', N'01 - Imagens/01 - Antes/11354.jpeg', N'Não havia um padrão estruturado para a preparação dos materiais, resultando em apresentações com qualidade inconsistente e menor efetividade na comunicação das mensagens-chave.', N'01 - Imagens/02 - Depois/11354.jpeg', N'Implementação de uma rotina estruturada de informativo para preparação e revisão dos materiais, garantindo maior qualidade, consistência das mensagens e apresentações mais assertivas para o time e liderança.', NULL, N'Saímos de um cenário de preparação reativa e qualidade variável para um processo estruturado, garantindo entregas consistentes, profissionais e de alto impacto.', N'A qualidade da entrega é definida antes da apresentação. Preparação antecipada, revisão estruturada e alinhamento das mensagens são fatores essenciais para gerar credibilidade, engajamento e decisões mais assertivas.', 0, NULL, N'Ter um ponto disponível  para atuar com ferramentas pneumaticas e limpeza de peças na caldeiraria.', '2026-07-03T00:00:00.000', '2026-07-24T15:03:54.000', N'499365', NULL, NULL);
INSERT INTO #PVC VALUES (11355, N'81041923', N'81041923', N'Raspador HOSCH', 2, N'Open Pit/Poço aberto', N'O raspador de correia da Martin instalado no transportador (TR-2009-06) apresenta desempenho insatisfatório na remoção do material aderido à correia, permitindo elevado retorno de material . Essa condição resulta em acúmulo de material na estrutura do transportador, aumento da necessidade de limpeza, maior desgaste dos componentes, risco à segurança operacional e aumento dos custos de manutenção. Além disso, a frequência de ajustes e substituições compromete a disponibilidade do equipamento e a eficiência do processo.', N'Eliminar  material fugitivo no retorno da correia', N'10031', N'01 - Imagens/01 - Antes/11355.jpeg', N'O raspador de correia da Martin instalado no transportador (TR-2009-06) apresenta desempenho insatisfatório na remoção do material aderido à correia, permitindo elevado retorno de material . Essa condição resulta em acúmulo de material na estrutura do transportador, aumento da necessidade de limpeza, maior desgaste dos componentes, risco à segurança operacional e aumento dos custos de manutenção. Além disso, a frequência de ajustes e substituições compromete a disponibilidade do equipamento e a eficiência do processo.', N'01 - Imagens/02 - Depois/11355.jpeg', N'Os principais benefícios do raspador Hosch em comparação com raspadores convencionais incluem:
INSERT INTO #PVC VALUES (11356, N'81062073', N'81062073', N'Novas Aplicações de Ensaios VLF, Tangente Delta (Tan δ) e Tensão Aplicada', 1, N'Others/Outros', N'A iniciativa visa aumentar a confiabilidade dos ativos elétricos por meio da adoção de diagnóstico preditivo em cabos de alta tensão. O método atual, baseado apenas em Megger, identifica falhas já avançadas, sem detectar degradação progressiva da isolação. A falha do alimentador AL-01 em 10/11/2025, com 8,73 horas de indisponibilidade e impactos operacionais, evidenciou essa limitação.
INSERT INTO #PVC VALUES (11357, N'81058050', N'81058050', N'Automatização dos Moto Bombas.', 2, N'Others/Outros', N'   Durante a operação dos caminhões-pipa, os operadores precisavam descer da cabine para realizar o acionamento manual da bomba de abastecimento, o que aumentava o tempo da atividade e expunha os empregados a riscos desnecessários. Como a operação ocorre em área próxima à mata, havia exposição a animais peçonhentos, selvagens, insetos, terrenos irregulares, condições climáticas adversas e outros equipamentos em movimento. ', N'Redução de Cenário de Risco.', N'10188', N'01 - Imagens/01 - Antes/11357.jpeg', N'   Durante a operação dos caminhões pipa, os operadores precisavam descer da cabine para realizar o acionamento manual da bomba de abastecimento, o que aumentava o tempo da atividade e expunha os empregados a riscos desnecessários. Como a operação ocorre em área próxima à mata, havia exposição a animais peçonhentos, selvagens, insetos, terrenos irregulares, condições climáticas adversas e outros equipamentos em movimento. ', N'01 - Imagens/02 - Depois/11357.jpeg', N'Para eliminar essa condição, foi implantado um sistema de acionamento da bomba por controle remoto via rádio, permitindo a operação diretamente da cabine. A melhoria reduziu significativamente a exposição aos riscos, aumentou a segurança dos operadores e proporcionou maior agilidade e eficiência no processo de abastecimento. GM6095', NULL, N'Sim , através da implantação do sistema automático de funcionamento dos moto bombas.', N'Redução de cenário de risco.', 0, NULL, N'performance, produtividade, segurança, tempo;
INSERT INTO #PVC VALUES (11358, N'81054319', N'81054319', N'Temporary Step Stool Installation to Improve System 200 HMI Accessibility', 2, N'Others/Outros', N'The HMI screen has a scratched, hazy area in the center where alarm and error messages are displayed. Shorter technicians were unable to clearly read critical piece of information from the angle they are standing from, while taller technicians were not affected. Although a screen replacement has been initiated, it requires procurement and is not an immediate repair since it is categorized as a non-urgent maintenance work.', N'Provide all technicians with equal and safe access to critical HMI information while the damaged HMI screen awaits replacement.', N'10191', N'01 - Imagens/01 - Antes/11358.jpeg', N'Shorter technicians struggled to read alarm and error messages on the damaged HMI screen with hazy patch in the center of the screen, reducing response efficiency and increasing the potential for delayed response.', N'01 - Imagens/02 - Depois/11358.jpeg', N'A step stool enables technicians of different heights to comfortably view the HMI, ensuring critical information can be read clearly until the new screen is installed.
INSERT INTO #PVC VALUES (11359, N'81006946', N'81048624', N'MALÃO DO IMPLEMENTO ', 1, N'No Replication/Sem replicação', N'Dificuldade no armazenamento de material, como calços, cones e ferramentas do uso dos operadores ', N'Criar um malão para armazenar material no equipamento ', N'10139', N'01 - Imagens/01 - Antes/11359.jpeg', N'Não havia um malão grande o suficiente para armazenar os epc ''s,e ferramentas do uso diário dos operadores. ', N'01 - Imagens/02 - Depois/11359.jpeg', N'Com a criação do malão de ferramentas, melhorou muito a condição de transporte dos itens de segurança  e ferramentas,  dando uma melhor condição aos colaboradores. ', NULL, N'Sim!se mantermos a disciplina e organização do malão, será eficaz ', N'Ter um local definido e organizado, traz mais segurança  e agilidade ao seu dia a dia de trabalho ', 0, NULL, N'performance, produtividade, segurança, tempo;
INSERT INTO #PVC VALUES (11360, N'81029931', N'81052327', N'PADRONIZAÇÃO VISUAL PANELA-SACO DE AMOSTRA', 1, N'No Replication/Sem replicação', N'1. Plástico sobre o quarteador  
INSERT INTO #PVC VALUES (11361, N'81057418', N'81057418', N'Identificação de amostras com análises pendentes ', 3, N'Open Pit/Poço aberto', N'As amostras armazenadas na prateleira não possuíam identificação visual indicando análises pendentes. Para verificar o status de cada amostra, era necessário acessar o sistema e realizar consultas individuais', N'Maior agilidade na identificação de amostras pendentes.', N'10129', N'01 - Imagens/01 - Antes/11361.jpeg', N'Necessidade de acessar o sistema para identificar análises pendentes de cada amostra.', N'01 - Imagens/02 - Depois/11361.jpeg', N'Identificação imediata das amostras pendentes por meio da sinalização visual na prateleira, sem necessidade de consulta prévia ao sistema.', NULL, N'Redução do tempo gasto em consultas ao sistema.
INSERT INTO #PVC VALUES (11362, N'81046149', N'81046149', N'Adequação de Guarda-corpo', 2, N'Others/Outros', N'Guarda-corpo danificado e/ou fora do padrão, oferecendo risco de queda e comprometendo a segurança dos colaboradores durante o acesso e a circulação.', N'Eliminar o risco de queda, adequar o guarda-corpo às normas de segurança e garantir um ambiente de trabalho seguro para todos.', N'10362', N'01 - Imagens/01 - Antes/11362.jpeg', N'Guarda-corpo danificado e/ou fora do padrão, oferecendo risco de queda e comprometendo a segurança dos colaboradores durante o acesso e a circulação.', N'01 - Imagens/02 - Depois/11362.jpeg', N'Guarda-corpo substituído ou reparado, atendendo aos requisitos de segurança, proporcionando proteção coletiva e circulação segura.
INSERT INTO #PVC VALUES (11363, N'81038902', N'81038902', N'dispositivo recuperador de corpos moedores', 3, N'Others/Outros', N'local=TR2313SA-01 que e alimentada pelo AL-2313SA-01 nessa transferência sempre acontece sobrecarga no transportador e cai muitos corpos moedores no piso causado um aspecto desorganizado e perigoso podendo causar queda de mesmo nível sem falar do desperdício muita das vezes era descartado os corpos moedores    ', N'mudar aspecto físico da área e reduzir gasto com insumo  ', N'10031', N'01 - Imagens/01 - Antes/11363.jpeg', N'LOCAL=TR-2313SA-01 retorno alimentação da TR nesse ponto do transportado sempre acontece de transborda e cair muitos corpos moedores no piso deixando o local em situação de risco podendo causar queda de mesmo nível, e mostrando um aspecto desorganizado da área sem falar num grande desperdício de insumo dos moinhos     ', N'01 - Imagens/02 - Depois/11363.jpeg', N'LOCAL-TR-2313SA-01foi fabricado e instalado um dispositivo para recuperar os corpos moedores, devolvendo manualmente os corpos moedores  com o transportador em operação  sem correr nenhum risco resultado em um local limpo organizado e seguro livre de acidentes e sem desperdício dos corpos moedores ', NULL, N'sim foi fabricado e instalado um dispositivo para devolver os corpos moedores de imediato com o transportador em operação sem correr risco de acidente  ', N'sempre fazer do nosso local de trabalho um lugar mais seguro ', 0, NULL, N'Eliminar os riscos identificados no mirante, adequar a estrutura conforme os padrões de segurança, melhorar a organização da área e aumentar a segurança e a eficiência operacional.', '2026-07-06T00:00:00.000', '2026-07-26T01:03:49.000', N'81038902', NULL, NULL);
INSERT INTO #PVC VALUES (11364, N'81046149', N'81040359', N'Adequação Barreira física ', 2, N'Others/Outros', N'Barreira física danificada, comprometendo a proteção da área.
INSERT INTO #PVC VALUES (11365, N'1014906', N'1014906', N'WLN R3 Level Indicator Safety Barrier', 2, N'Others/Outros', N'Unable to safely access level indicator on WLN R3 for cleaning. To access properly a step stool is required which brings you  ', N'Allow safe access to WLN R3 level inidcator.', N'0', N'01 - Imagens/01 - Antes/11365.jpeg', N'WLN R3 level indicator requires a step ladder to access it properly. ', N'01 - Imagens/02 - Depois/11365.jpeg', N'Scaffold barrier erected to allow safe access to WLN R3 Level Indicator for cleaning.', NULL, N'Yes, can now safely access WLN R3 Level Indicator.', N'Safe Access', 0, NULL, N'A participação da equipe na identificação dos riscos evidenciou que ações simples e de baixo custo podem gerar grandes ganhos em segurança, confiabilidade e padronização das áreas operacionais.', '2026-07-25T00:00:00.000', '2026-07-26T10:09:05.000', N'1014906', NULL, NULL);
INSERT INTO #PVC VALUES (11366, N'81049566', N'81012442', N'Suporte mangueira ', 3, N'Crusher/Britadeira', N'Ausência de um suporte para a mangueira O que levava a mangueira a ficar caída no chão Com o risco de pessoas tropeçarem.', N'fabricar um suporte para guardar a mangueira de forma org', N'10362', N'01 - Imagens/01 - Antes/11366.jpeg', N'Ausência de um suporte para a mangueira Utilizado na limpeza da caldeiraria do revezamento.', N'01 - Imagens/02 - Depois/11366.jpeg', N'Após a instalação de um novo ponto de água e ar Na oficina da cadeira foi fabricado e instalado um suporte para a mangueira.', NULL, N'Foi fabricado um suporte armazenado da mangueira de forma segura', N'Ambiente mais organizado e seguro', 0, NULL, N'A implantação da iluminação de emergência evidenciou que ações preventivas fortalecem a cultura de segurança, asseguram melhores condições de resposta em emergências e contribuem para a proteção das pessoas e do patrimônio.', '2026-07-25T00:00:00.000', '2026-07-26T10:31:56.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11367, N'81049566', N'81012442', N'Linha de ar comprimido ', 3, N'Crusher/Britadeira', N'Ausência de uma linha de ar comprimido para a utilização de ferramentas e limpeza de equipamentos na caldeiraria dos revezamento.', N'instalar ponto de ar comprimido na caldeiraria', N'10362', N'01 - Imagens/01 - Antes/11367.jpeg', N'Ausência de uma linha de ar comprimido na caldeiraria do revezamento', N'01 - Imagens/02 - Depois/11367.jpeg', N'Instalado linha de ar comprimida Vindo da moagem para alimentar a caldeiraria do revezamento.', NULL, N'Instalado linha de ar comprimido na caldeiraria do revezamento.', N'melhoria no dia a dia ', 0, NULL, N'Padronizar o armazenamento dos utensílios de limpeza por meio da instalação de um suporte específico, eliminando materiais apoiados no piso, aumentando a segurança, preservando a vida útil dos equipamentos, reduzindo o tempo de localização e guarda dos utensílios e fortalecendo a aplicação da metodologia 5S, com potencial de replicação em outras áreas.', '2026-07-25T00:00:00.000', '2026-07-26T10:45:30.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11368, N'1008687', N'1008687', N'GUL Cement Usage', 1, N'Underground/Subterrâneo', N'Remove GUL Cement from inventory', N'Remove all inventory of GUL Cement from site at Minimum Cost ', N'10292', N'01 - Imagens/01 - Antes/11368.jpeg', N'GUL Cement was procured and transported to Voisey’s Bay for use in the Cemented Rock Fill (CRF) process. Following further evaluation, it was determined that CRF would not be adopted as a standard operational practice. As a result, approximately 5,100 bags of GUL Cement remain on site with no identified operational use.
INSERT INTO #PVC VALUES (11369, N'1008687', N'1008687', N'Warehouse Workspace Development ', 3, N'Others/Outros', N'Improve the functionality and ergonomics of the Warehouse Receiving area to enhance safety, efficiency, and workflow', N'Improve Warehouse Receiving ', N'10292', N'01 - Imagens/01 - Antes/11369.jpeg', N'The Warehouse Receiving workstation had become cluttered and was not designed to effectively support the daily receiving process. Materials, paperwork, and equipment were stored in a manner that limited available workspace and created inefficiencies during receiving activities. The layout was not ergonomic, requiring employees to perform unnecessary reaching, bending, and movement to complete routine tasks.
INSERT INTO #PVC VALUES (11370, N'81050572', N'81050572', N'PADRONIZAÇÃO IDENTIFICAÇÃO DAS CÉLULAS BANCO DE BATERIAS', 1, N'Others/Outros', N'Banco de baterias não possuía identificação clara e padronizada das células, dificultando inspeções, medições, registros de manutenção e a localização de falhas.
INSERT INTO #PVC VALUES (11371, N'488890', N'544624', N'Sem condição', 1, N'Projects/Projetos', N'Durante a operação do circuito em BY PASS, com o moinho SAG parado, foi identificado um intertravamento na lógica de controle que bloqueava a partida dos alimentadores 2301 AL 01/02 sempre que o fluxo era direcionado para a 2301 TC 08. ', N'Alcançada', N'10054', N'01 - Imagens/01 - Antes/11371.jpeg', N'Durante a operação do circuito em BY PASS, com o moinho SAG parado, foi identificado um intertravamento na lógica de controle que bloqueava a partida dos alimentadores 2301 AL 01/02 sempre que o fluxo era direcionado para a 2301 TC 08. Como consequência, a operação normal do circuito de rebritagem ficava impossibilitada. Diante desse cenário, foi necessário a revisão da lógica de controle para eliminar a restrição operacional identificada.', N'01 - Imagens/02 - Depois/11371.jpeg', N'Após a implantação da melhoria na lógica de controle, foi eliminada a restrição operacional que impedia a partida dos alimentadores 2301 AL 01/02 durante a operação em BY PASS com o moinho SAG parado. A adequação da lógica restabeleceu a flexibilidade operacional do circuito, aumentou a confiabilidade do processo e eliminou a necessidade de intervenções operacionais.', NULL, N'O resultado obtido atendeu integralmente à meta inicial, eliminando o intertravamento indevido e garantindo a operação do circuito conforme a estratégia definida.', N'Validar a lógica de controle em todos os modos de operação evita restrições operacionais.', 0, NULL, N'Processo mais rápido, padronizado e confiável, com ganho de produtividade na análise das pendências de capitalização', '2026-07-19T00:00:00.000', '2026-07-26T14:05:38.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11372, N'81050572', N'81050572', N'Implementação da Rastreabilidade das Células dos Bancos de Baterias através da Padronização da Identificação', 1, N'Others/Outros', N'Os bancos de baterias das subestações não possuíam um padrão de identificação das células, dificultando a rastreabilidade dos componentes durante inspeções, medições e atividades de manutenção. A ausência de identificação clara aumentava o tempo de localização das células, elevava o risco de erros nos registros e comprometia a confiabilidade das informações utilizadas na tomada de decisão e na gestão dos ativos.', N'Padronizar a identificação de 100% das células dos bancos de baterias por meio de etiquetas e nomenclaturas definidas, garantindo rápida localização durante inspeções, medições e manutenções. A iniciativa visa eliminar erros de identificação, aumentar a confiabilidade dos registros, reduzir o tempo de execução das atividades e fortalecer a segurança operacional e a rastreabilidade dos ativos.', N'10294', N'01 - Imagens/01 - Antes/11372.jpeg', N'Situação Inicial
INSERT INTO #PVC VALUES (11373, N'81030117', N'523439', N'SUPORTE PARA CABOS DO GERADOR', 1, N'Others/Outros', N'Na mesa de Perfuração o alojamento do defletor de pó sem proteção quando o mastro está horizontal, com condição de um acidente com pessoas', N'MITIGAR RISCOS', N'10324', N'01 - Imagens/01 - Antes/11373.jpeg', N'Na mesa de Perfuração o alojamento do defletor de pó sem proteção quando o mastro está horizontal, com condição de um acidente com pessoas', N'01 - Imagens/02 - Depois/11373.jpeg', N'Foi confeccionado uma proteção e eliminando o risco de acidentes', NULL, N'Foi confeccionado uma proteção e eliminando o risco de acidentes.', N'MAIS SEGURANÇA', 0, NULL, N'Reduzir o risco de exposição dos operadores a produtos químicos em caso de rompimento da mangueira de dosagem, evitando respingos durante a operação. Proteger os componentes do sistema contra danos mecânicos, aumentar a segurança operacional, a confiabilidade do processo e reduzir a necessidade de manutenções corretivas.', '2026-07-19T00:00:00.000', '2026-07-26T15:16:29.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11374, N'544624', N'81047035', N'Roda pé seguro', 3, N'No Replication/Sem replicação', N'Material de limpeza caindo diretamente para dentro do galpão de concentrado.', N'Eliminar queda de material', N'10054', N'01 - Imagens/01 - Antes/11374.jpeg', N'Rodapé com fragilidade na contenção de materiais proveniente de limpeza do piso ou manutenção. 
INSERT INTO #PVC VALUES (11375, N'488890', N'488890', N'Se alarmou olhe', 1, N'Projects/Projetos', N'Sempre que as temperaturas do sistema de refrigeração do moinho SAG se elevavam, não havia um alarme no sistema de controle que permitisse antecipar uma possível parada do equipamento por alta temperatura do sistema de refrigeração ou do cicloconversor.', N'Antecipar equipe para verificação da elevação das temperaturas sistema de refrigeração moinho SAG.', N'10054', N'01 - Imagens/01 - Antes/11375.jpeg', N'Antes da implantação da melhoria, não havia um alarme no sistema de controle para alertar antecipadamente a elevação da temperatura do sistema de refrigeração do moinho SAG e do cicloconversor. Como consequência, a operação não dispunha de um aviso prévio para atuar preventivamente, aumentando o risco de paradas não programadas por atuação das proteções de alta temperatura.', N'01 - Imagens/02 - Depois/11375.jpeg', N'Após a implementação da melhoria, foi criado um alarme no sistema de controle para monitorar a elevação da temperatura do sistema de refrigeração do moinho SAG e do cicloconversor. Essa funcionalidade passou a alertar antecipadamente a operação sobre condições anormais de temperatura, permitindo a atuação preventiva antes do acionamento das proteções do equipamento, reduzindo o risco de paradas não programadas e aumentando a confiabilidade operacional do processo.', NULL, N'Ausência de alarme preventivo para alta temperatura do sistema de refrigeração do moinho SAG e do cicloconversor, solucionada com a implementação de alarme no sistema de controle.', N'Alarmes preventivos aumentam a confiabilidade operacional.', 324, 3, N'Mitigação de riscos ergonômicos na operação de aperto e desaperto de parafusos nas operações de instalação e remoção de pneus.', '2026-07-25T00:00:00.000', '2026-07-26T18:05:55.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11376, N'81061781', N'523252', N'Adequação do mirante do pátio mirante', 1, N'Projects/Projetos', N'O mirante do pátio apresentava condições inadequadas de utilização, com necessidade de melhorias na estrutura, organização e sinalização, gerando riscos de acidentes, dificuldade de acesso e comprometendo a segurança operacional.', N'Adequar o mirante do pátio, promovendo maior segurança, organização e padronização do ambiente, eliminando riscos aos colaboradores e melhorando a utilização da área.', N'10144', N'01 - Imagens/01 - Antes/11376.jpeg', N'* Estrutura do mirante sem adequação completa.
INSERT INTO #PVC VALUES (11377, N'81061781', N'523252', N'Adequação de acesso de veiculo a tenda de perfuratriz', 2, N'Projects/Projetos', N'O acesso de veículos à tenda da perfuratriz apresentava condições inadequadas, dificultando a circulação e as manobras, aumentando o risco de incidentes, danos aos equipamentos e atrasos nas atividades operacionais.', N'Adequar o acesso de veículos à tenda da perfuratriz, garantindo segurança na circulação, melhor organização da área e maior eficiência nas operações.', N'10144', N'01 - Imagens/01 - Antes/11377.jpeg', N'* Acesso sem padronização.
INSERT INTO #PVC VALUES (11378, N'81061781', N'81061781', N'Instalação de antiderrapante na escada do mirante para prevenir risco de queda', 2, N'Others/Outros', N'A escada do mirante não possuía superfície antiderrapante, tornando o acesso inseguro, principalmente em condições de chuva ou umidade, aumentando o risco de acidentes.', N'Instalar material antiderrapante na escada do mirante para aumentar a segurança dos colaboradores, reduzindo o risco de escorregões e quedas durante o acesso.', N'10144', N'01 - Imagens/01 - Antes/11378.jpeg', N'* Escada sem revestimento antiderrapante.
INSERT INTO #PVC VALUES (11379, N'81061781', N'81061781', N'Instalação de luz de emergência na sala da Komatsu', 2, N'Projects/Projetos', N'A sala da Komatsu não possuía iluminação de emergência. Em caso de interrupção do fornecimento de energia elétrica, o ambiente ficava totalmente sem iluminação, dificultando a evacuação, aumentando o risco de acidentes e comprometendo a segurança dos colaboradores.', N'Instalar iluminação de emergência na sala da Komatsu para garantir a segurança dos colaboradores durante situações de falta de energia, assegurando uma evacuação segura e o atendimento aos requisitos de segurança.', N'10144', N'01 - Imagens/01 - Antes/11379.jpeg', N'* Ausência de luz de emergência na sala.
INSERT INTO #PVC VALUES (11380, N'479995', N'81034962', N'Implantação de suporte para organização e padronização dos utensílios de limpeza (5S)', 3, N'Others/Outros', N'Os utensílios de limpeza eram armazenados de forma inadequada, apoiados no chão e sem local definido, dificultando a organização, favorecendo danos aos equipamentos, aumentando o tempo de procura e comprometendo a aplicação do programa 5S.
INSERT INTO #PVC VALUES (11381, N'524052', N'524052', N'monitoramento de FPS de motoniveladoras', 1, N'Others/Outros', N'não há uma forma rápida e visual de acompanhar o desgaste de bordas de lâminas das motoniveladoras. Para avaliação de condição ou consumo, depende de relatórios de inspeção.', N'projetar consumo de bordas de acordo com desgaste real', N'10154', N'01 - Imagens/01 - Antes/11381.jpeg', N'A verificação da condição de bordas das lâminas de motoniveladoras dependia de pesquisa em base de dados de paradas ou solicitação de relatório fotográfico do time de inspeção', N'01 - Imagens/02 - Depois/11381.jpeg', N' Gerado um painel dashboard em Power Bi que é alimentado pelo inspetor, dessa forma é possível verificar a condição atual da última inspeção e o histórico de datas passadas', NULL, N'resultado positivo pois com o acompanhamento, pode-se projetar consumo mensal e anual', N'sempre há possibilidade de melhoria', 0, NULL, N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', '2026-07-24T00:00:00.000', '2026-07-27T10:36:40.000', N'524052', NULL, NULL);
INSERT INTO #PVC VALUES (11382, N'200236', N'200236', N'CoPilot Assistance with PI Vision', NULL, N'No Replication/Sem replicação', N'PI Vision has a logic language for use in calculations.  The language syntax is not readily available to users.  A question or submission to PI Team can take a significant time and is often avoided.', N'PI Vision programming', N'10190', N'01 - Imagens/01 - Antes/11382.jpeg', N'PI Vision logic syntax is not readily available to users.  PI Team does not have the resource to provide very quick responses to questions regarding logic syntax. ', N'01 - Imagens/02 - Depois/11382.jpeg', N'CoPilot was tested for knowledge of PI Vision logic syntax.  CoPilot is able to provide logic syntax for various scenarios.  It is able to write logic should you require it.  It will also check your own logic for errors.  It is not perfect and does require some back and forth, however the timing within which questions can be answered with respect to PI Vison logic syntax is a fraction of what it was.', NULL, N'Problem is solved.  Waiting is eliminated.', N'AI is becoming very useful in everyday work', 0, NULL, N'A instalação de um guarda‑corpo traz ganhos claros e relevantes para a operação e para a segurança da equipe. O principal benefício é a redução do risco de quedas, garantindo maior proteção aos trabalhadores durante atividades em altura ou em escadas. Além disso, promove conformidade com normas regulamentadoras de segurança, evitando autuações e fortalecendo a cultura preventiva da empresa. ', '2026-06-01T00:00:00.000', '2026-07-27T10:39:34.000', N'200236', NULL, NULL);
INSERT INTO #PVC VALUES (11383, N'81047036', N'81047036', N'Melhoria do Sistema de Ancoragem para Manutenção em Transportadores', 2, N'Others/Outros', N'Durante as atividades de troca de rolos em transportadores, os trabalhadores encontravam dificuldades para localizar e utilizar pontos adequados para conexão dos talabartes dos cinturões de segurança. A ausência de pontos de ancoragem claramente definidos, acessíveis, identificados e tecnicamente validados dificultava a montagem do sistema de proteção contra quedas, aumentava o tempo de preparação da atividade e poderia favorecer o uso de pontos inadequados ou soluções não padronizadas. Essa condição gerava exposição ao risco de queda e impactava a segurança e a eficiência da manutenção.', N'Eliminar as dificuldades e os riscos associados à ausência ou à inadequação de pontos de ancoragem durante as atividades de troca de rolos em transportadores, por meio da avaliação, validação e emissão de documentação técnica pela Engenharia, permitindo o uso seguro e padronizado de pontos específicos da estrutura para instalação de cintas de ancoragem e conexão dos talabartes dos cinturões de segurança.', N'10145', N'01 - Imagens/01 - Antes/11383.jpeg', N'Durante a troca de rolos em transportadores, a atividade demorava muito tempo para ser iniciada, devido a montagem de andaimes, tubo-vida, e os empregados encontravam dificuldades para localizar pontos adequados para conexão dos talabartes dos cinturões de segurança. A ausência de pontos claramente definidos e tecnicamente validados aumentava o tempo de preparação da atividade e poderia favorecer o uso de locais inadequados ou não padronizados, ampliando a exposição ao risco de queda.', N'01 - Imagens/02 - Depois/11383.jpeg', N'Os empregados deixaram de procurar ou avaliar individualmente possíveis locais para conexão dos talabartes. A atividade passou a contar com pontos conhecidos, acessíveis, identificados e respaldados por documentação técnica, tornando a instalação do sistema de proteção contra quedas (cintas de ancoragem) mais segura, rápida e padronizada. Dessa forma, foram eliminadas as improvisações e montagem de tubo-vidas, o que desprendia muito tempo para realização da atividade.', NULL, N'Sim!
INSERT INTO #PVC VALUES (11384, N'81001594', N'81001594', N'Automação da Geração e Consolidação de Relatórios de Pendências de Capitalização', 1, N'Others/Outros', N'A extração de relatórios de pendências de capitalização era feita individualmente por elemento PEP, resultando em um processo manual, repetitivo e de baixa produtividade.', N'Reduzir o esforço operacional na geração de relatórios de pendências de capitalização por meio da automação da extração e consolidação de múltiplos elementos PEPs.', N'10367', N'01 - Imagens/01 - Antes/11384.jpeg', N'A transação do SAP permite gerar o relatório de pendências de capitalização para apenas um elemento PEP por vez. Dessa forma, a extração de informações de múltiplos PEPs exige várias execuções manuais, aumentando o tempo operacional.', N'01 - Imagens/02 - Depois/11384.jpeg', N'Foi desenvolvida uma ferramenta automatizada que permite a geração de relatórios para múltiplos elementos PEP simultaneamente, realizando também a consolidação das informações em um único relatório por projeto. Com isso, o processo tornou-se mais rápido, padronizado e eficiente.', NULL, N'Automatização da geração e consolidação de relatórios de múltiplos elementos PEP, eliminando atividades manuais e reduzindo o tempo de processamento.', N'Automatizar atividades repetitivas é uma das formas mais eficazes de aumentar a produtividade e reduzir desperdícios no processo.', 0, NULL, N'Increased the availability of heat management products on site. ', '2026-06-30T00:00:00.000', '2026-07-27T12:26:57.000', N'81001594', NULL, NULL);
INSERT INTO #PVC VALUES (11385, N'592501', N'592501', N'Controle Caminhões Rodoviários Implementos SLB', 1, N'Others/Outros', N'Ausência de controle integrado da frota de caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, gerando uma lacuna crítica na gestão de ativos. ', N'Estabelecer controle da frota dos caminhões implementos possibilitando a consolidação de dados para construção do contrato de reforma dos ativos.   ', N'0', N'01 - Imagens/01 - Antes/11385.jpeg', N'Ausência de controle integrado da frota de caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, gerando uma lacuna crítica na gestão de ativos. Tal cenário compromete o planejamento de manutenção, a estratégia de reposição de materiais e a previsibilidade da demanda por recursos, impactando diretamente a confiabilidade dos equipamentos, a disponibilidade operacional e a eficiência dos processos de manutenção.', N'01 - Imagens/02 - Depois/11385.jpeg', N'Controle consolidado e padronizado de todos os caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, contribuindo com o planejamento de manutenção, a estratégia de reposição de materiais e a previsibilidade da demanda por recursos, impactando diretamente a confiabilidade dos equipamentos, sendo um embasador técnico para construção de um contrato de reforma dos ativo junto aos fornecedores locais.', N'https://globalvale.sharepoint.com/:f:/r/sites/GESTAODECOMPONENTES-PLANILHA/Shared%20Documents/General/Controle%20Caminh%C3%B5es%20Implementos%20SLB?csf=1&web=1&e=AhRwas', N'Sim', N'Gestão e controle.', 0, NULL, N'Eliminar o contato direto das mãos com o gelo, garantir a utilização da pazinha para retirada do material e fortalecer a cultura de segurança, reduzindo a exposição a acidentes e desvios comportamentais.', '2026-07-27T00:00:00.000', '2026-07-27T13:40:16.000', N'592501', NULL, NULL);
INSERT INTO #PVC VALUES (11386, N'479995', N'81034962', N'Proteção e padronização das mangueiras de dosagem de produtos químicos da ETEO.', 2, N'Others/Outros', N'As mangueiras de dosagem dos produtos químicos Cal, Polímero e Praestol da ETO permaneciam expostas, sem proteção mecânica e sem padronização, ficando suscetíveis a danos, desgaste prematuro, vazamentos e interferências externas. Essa condição comprometia a organização da área, a segurança operacional e a confiabilidade do sistema de dosagem.', N'Proteger e padronizar a passagem das mangueiras de dosagem de cal, polímero e Praestol da ETO, aumentando a segurança operacional, preservando os equipamentos e melhorando a organização da área.', N'10213', N'01 - Imagens/01 - Antes/11386.jpeg', N'As mangueiras de dosagem dos produtos químicos (cal, polímero e Praestol) da ETEO permaneciam expostas, sem proteção mecânica e sem padronização, ficando suscetíveis a impactos, desgaste prematuro, rompimentos e vazamentos. Essa condição aumentava o risco de respingos de produtos químicos sobre os operadores durante a operação e manutenção, comprometendo a segurança das pessoas, a organização da área e a confiabilidade do sistema de dosagem.', N'01 - Imagens/02 - Depois/11386.jpeg', N'Foi instalada uma tubulação de PVC para proteger e organizar a passagem das mangueiras de dosagem dos produtos químicos (cal, polímero e Praestol) da ETEO. A melhoria eliminou a exposição direta das mangueiras a impactos e desgaste mecânico, reduzindo o risco de rompimentos e de respingos de produtos químicos sobre os operadores. Além disso, padronizou a instalação, facilitou as atividades de inspeção e manutenção, aumentou a segurança operacional e elevou a confiabilidade do sistema de dosagem.
INSERT INTO #PVC VALUES (11387, N'594051', N'594051', N'Otimização da Troca dos Braços dos Limpadores D60/D65', 1, N'Others/Outros', N'Durante a elaboração do orçamento de 2027 da Frota de Perfuração PD, foi identificada uma oportunidade de otimização de custos por meio da revisão da estratégia de manutenção dos braços dos limpadores de para-brisa das perfuratrizes D60/D65.
INSERT INTO #PVC VALUES (11388, N'81048243', N'81048243', N'Melhoria Ergonômica nas Operações de Aperto e Desaperto de Parafusos com Chave de Impacto nas remoções e instalações de pneus em equipamentos GP', 2, N'Projects/Projetos', N'Manejo de chaves de impacto em condições específicas as quais são impactantes na ergonomia haja visto o peso da ferramenta e as posições as quais são demandadas pelo mecânico durante as operações de aperto e desaperto de porcas e parafusos nas rodas de equipamentos fora de estrada.', N'Mitigar situações ergonômicas durante as operações de Remoção e Instalação de Pneus em equipamentos de Grande Porte', N'10144', N'01 - Imagens/01 - Antes/11388.jpeg', N'Remoção de Parafusos e porcas com manuseio operacional da chave de impacto em várias posições do pneu-grande esforço físico para mantenimento constante da operação devido ao peso da ferramenta(16kg).', N'01 - Imagens/02 - Depois/11388.jpeg', N'Aplicação de 01 equipamento de apoio na sustentação (sistema tipo gravidade zero(cap 11 à 18kg)) de forma à reduzir o peso da ferramenta durante as operações de movimentação para aperto/desaperto de parafusos.', NULL, N'Situação resolvida conforme premissas base do conceito inicial (GM 4043)', N'Redução de Movimentos e Manipulação de Cargas com auxílio de dispositivos de gravidade zero', 0, NULL, N'segurança ', '2026-07-24T00:00:00.000', '2026-07-27T15:04:47.000', N'81048243', NULL, NULL);
INSERT INTO #PVC VALUES (11389, N'81058966', N'543216', N' Válvula de segurança.', 1, N'Others/Outros', N'Antes os amostradores eram manutenidos apenas em PGU/Parada de linha, por estarem instalados em pontos específicos como o recalque das bombas, alimentação e rejeito da usina, locais que param somente em PGU.', N'Realizar as manutenções em rotina, sem depender de paradas de linha ou PGU.', N'10031', N'01 - Imagens/01 - Antes/11389.jpeg', N'Impossibilidade de  fazer manutenção no equipamento em rotina.
INSERT INTO #PVC VALUES (11390, N'1009878', N'1009878', N'Scan RLS Pump Casing', NULL, N'Refining/Refino', N'The RLS Pump''s casing in 221 has shown signs of failure.  A new casing is over $500k.  Cost is quite high for ordering a spare part', N'Look into alternative suppliers', N'0', N'01 - Imagens/01 - Antes/11390.jpeg', N'Casing is leaking and a spare casing has a long lead time and is over $500k', N'01 - Imagens/02 - Depois/11390.jpeg', N'A third party vendor was contacted who 3D scanned the old casing during the last outage.  They are offering to fabricate a new casing with a better lead time for 1/3 of the cost if we wish to order.', NULL, N'Yes.  Alternative vendor can supply spare parts.', N'3D Scan', 300000, 3, N'Improved user experience, increased visibility of issues, and strengthened communication between users and IT.', '2026-07-26T00:00:00.000', '2026-07-27T15:24:54.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11391, N'81058966', N'81058570', N'Adequação e Padronização de Válvula na Linha de Ar Comprimido', 2, N'Others/Outros', N'Durante a execução de manutenção corretiva/preventiva na rede de utilidades (ar comprimido), identificou-se um desvio de SSMA. A válvula existente demandava torque excessivo e o uso de ferramenta improvisada (chave) para acionamento. Esta condição gerava risco crítico de acidente ergonômico e perda de produtividade pelo tempo elevado de manobra.', N'Eliminar 100% o risco ergonômico na operação da válvula e padronizar o ativo, garantindo conformidade com os requisitos de segurança e facilidade operacional (Garantia da Rotina).', N'10031', N'01 - Imagens/01 - Antes/11391.jpeg', N'Ativo operando fora do padrão técnico ideal. Válvula com acionamento travado.', N'01 - Imagens/02 - Depois/11391.jpeg', N'Implementação de melhoria de engenharia através da substituição por uma válvula de gaveta/esfera .', NULL, N'sim, substituição por uma válvula de gaveta/esfera . ', N' O olhar atento do operador na identificação de desvios e a aplicação imediata do conceito de Melhoria Contínua (Kaizen) evitam incidentes e consolidam a cultura de Disciplina Operacional do VPS.Data ', 0, NULL, N'O aplicativo teve 386 registros e 83 relatórios exportados em PDF nos primeiros 27 dias de utilização apenas pela gerência de elétrica e instrumentação (média de ~14 registros dia).
INSERT INTO #PVC VALUES (11392, N'81017062', N'81017062', N'Oil sample points for hoist equipment', 1, N'Underground/Subterrâneo', N'Oil samples were inconsistently labelled resulting in poor data quality', N'Improve data quality of oil samples', N'10012', N'01 - Imagens/01 - Antes/11392.jpeg', N'Over 20 assets for 4 sample points resulting in poor data quality', N'01 - Imagens/02 - Depois/11392.jpeg', N'Each sample point is labelled with QR code to prevent mislabeling. Data quality will be improved going forward.', NULL, N'Goal achieved', N'QR codes', 0, NULL, N'A melhoria evidenciou a importância de considerar ergonomia, segurança e facilidade operacional no projeto, mostrando que ajustes simples podem reduzir riscos, otimizar atividades e aumentar a eficiência.)', '2026-07-23T00:00:00.000', '2026-07-27T15:43:52.000', N'81017062', NULL, NULL);
INSERT INTO #PVC VALUES (11393, N'81042683', N'81055953', N'In-House Rebuild of Critical SLN Sump', 1, N'Refining/Refino', N'A critical process sump pump experienced significant deterioration requiring a complete wet-end and barrel rebuild. The system had no installed redundancy, resulting in the continued use of temporary drop-in submersible pumps to maintain operation and mitigate production risk.
INSERT INTO #PVC VALUES (11394, N'553135', N'553135', N'ORGANOGRAMA DINAMICO ', 1, N'Others/Outros', N'O ORGANOGRAMA ERA FEITO DE FORMA IMPRESSA E COLOCADA NO FMDS, TODAS AS VEZES QUE ACONTECIAM ATUALIZAÇÕES PRECISAVAMOS FAZER TODO O PROCESSO NOVAMENTE. GASTANDO PAPEIS, PLASTICOS E FITAS ', N'TORNAR AS ATUALIZAÇÕES FÁCEIS ', N'10139', N'01 - Imagens/01 - Antes/11394.jpeg', N'O ORGANOGRAMA ERA FEITO DE FORMA IMPRESSA E COLOCADA NO FMDS, TODAS AS VEZES QUE ACONTECIAM ATUALIZAÇÕES PRECISAVAMOS FAZER TODO O PROCESSO NOVAMENTE. GASTANDO PAPEIS, PLASTICOS E FITAS ', N'01 - Imagens/02 - Depois/11394.jpeg', N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', NULL, N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', N'MELHORIA CONSTANTE ', 0, NULL, N'Reduced calendar creation time from hours to minutes while improving consistency and accuracy.', '2026-07-24T00:00:00.000', '2026-07-27T16:22:07.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11395, N'81007243', N'81047727', N'Guarda corpo escada', 3, N'Others/Outros', N'A ausência de guarda‑corpo em uma escada do lavador', N'Melhorar segurança nas atividades do lavador', N'10139', N'01 - Imagens/01 - Antes/11395.jpeg', N'A ausência de guarda‑corpo em uma escada ou plataforma representa um risco direto à segurança dos trabalhadores, pois aumenta significativamente a possibilidade de quedas durante a execução das atividades, especialmente em situações de movimentação constante ou transporte de ferramentas. Além disso, gera insegurança operacional, já que a equipe executante trabalha com receio, reduzindo eficiência e foco. Outro problema é a não conformidade com normas regulamentadoras de segurança, como a NR‑18 e NR‑35 no Brasil, o que pode resultar em autuações e penalidades. A falta dessa proteção compromete a confiabilidade das operações, pois qualquer acidente pode causar paralisações inesperadas e custos elevados com manutenção corretiva.', N'01 - Imagens/02 - Depois/11395.jpeg', N'Foi elaborado e instalado um guarda-corpo visando garantir maior proteção durante as atividades executadas pelo time do lavador. A estrutura foi projetada e instalada conforme normas de segurança.', NULL, N'A instalação de um guarda‑corpo traz ganhos claros e relevantes para a operação e para a segurança da equipe. O principal benefício é a redução do risco de quedas, garantindo maior proteção aos trabalhadores durante atividades em altura ou em escadas. Além disso, promove conformidade com normas regulamentadoras de segurança, evitando autuações e fortalecendo a cultura preventiva da empresa. ', N'Segurança', 0, NULL, N'todas as marcas de centrais cobertas.', '2026-07-23T00:00:00.000', '2026-07-27T20:25:21.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11396, N'81007243', N'81047727', N'Suporte para armários ', 3, N'Others/Outros', N'Foi identificado que o armário permanece em contato direto com o canhão que lança água e sabão com frequência, situação que pode comprometer tanto a integridade do ativo quanto a segurança das atividades realizadas no local. O contato constante com água e sabão pode acelerar o desgaste do material do armário.', N'Proteção dos armários ', N'10139', N'01 - Imagens/01 - Antes/11396.jpeg', N'Foi identificado que o armário permanece em contato direto com o canhão que lança água e sabão com frequência, situação que pode comprometer tanto a integridade do ativo quanto a segurança das atividades realizadas no local. O contato constante com água e sabão pode acelerar o desgaste do material do armário.', N'01 - Imagens/02 - Depois/11396.jpeg', N'Foi identificado que o armário permanecia em contato direto com o canhão que lança água e sabão com frequência, situação que comprometia sua conservação e a segurança operacional. Para resolver o problema, a equipe da caldeiraria confeccionou e instalou um suporte adequado, elevando o armário e afastando-o da linha de impacto do jato. Com essa medida, foi possível reduzir significativamente a exposição à umidade e aos produtos químicos, preservar a integridade do armário e dos materiais armazenados, além de garantir melhores condições de organização e segurança na área de trabalho.', NULL, N'Sim, com o suporte o armário deixa de ficar em contato direto com o jato de água e sabão lançado, reduzindo a exposição constante à umidade e aos produtos químicos. Isso traz proteção estrutural.', N'Preservação da vida útil dos ativos ', 0, NULL, N'Retenção eficaz de objetos na base da plataforma devido à instalação do rodapé metálico contínuo.', '2026-07-24T00:00:00.000', '2026-07-27T20:35:15.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11397, N'1008687', N'81046822', N'Material Creation - Electrolyte Freezies', 2, N'Concentration/Concentração', N'In Voisey''s Bay getting cooling aids during hot weather is not always easy, with each area using P Card and Spot PO''s to generate mechanisms to bring Squinchers (Electrolyte Freezies) on site for their crews. This creates access air freight and higher costs. ', N'Ensure all working parties have access to items to help with heat stress and dehydration ', N'10292', N'01 - Imagens/01 - Antes/11397.jpeg', N'Prior to improvements, electrolyte replenishers were frequently procured through spot purchase orders and P-Card transactions due to limited inventory planning and inconsistent product availability. This reactive purchasing approach often resulted in urgent air freight shipments to site to prevent stockouts, significantly increasing transportation costs and overall procurement expenses. In addition, fluctuating supplier availability created challenges in securing product when needed, leading to supply uncertainty, increased administrative effort, and reduced cost efficiency within the replenishment process.', N'01 - Imagens/02 - Depois/11397.jpeg', N'A dedicated material code was established for electrolyte replenishers, enabling improved inventory visibility and management within SAP. Min/max inventory levels were defined based on site consumption requirements, and the product was placed under contract to secure consistent supply and pricing. Inventory is now routinely stocked in the warehouse and available through the normal reservation process, eliminating the need for spot purchases, reducing air freight requirements, lowering overall costs, and improving product availability for end users.', NULL, N'Yes solved by creating new stock code and inventory min / max. ', N'Take the initiative to help improve site for everyone', 10000, 3, N'Aumento da confiabilidade do equipamento, maior durabilidade do componente, redução das paradas para manutenção corretiva, agilidade na substituição das peças e melhoria da segurança operacional.', '2026-07-26T00:00:00.000', '2026-07-27T20:39:46.000', N'1008687', NULL, NULL);
INSERT INTO #PVC VALUES (11398, N'81046234', N'81046234', N' Segurança na Retirada de Gelo', 2, N'Others/Outros', N'Durante a retirada de gelo da máquina, foi observado que os empregados utilizavam as próprias mãos para manusear o gelo, gerando exposição a riscos de lesões por frio, cortes e possíveis contaminações. Além disso, não havia uma orientação visual padronizada reforçando a utilização de ferramenta adequada para essa atividade.', N'Eliminar o contato direto das mãos com o gelo durante a retirada do material da máquina, promovendo um processo mais seguro, higiênico e padronizado, reduzindo a exposição a lesões e fortalecendo a cultura de segurança.', N'10099', N'01 - Imagens/01 - Antes/11398.jpeg', N'Durante a retirada de gelo da máquina, alguns empregados realizavam o manuseio diretamente com as mãos, por não haver um reforço visual adequado sobre a utilização da pazinha disponível. Essa prática expunha os empregados ao risco de lesões por contato com superfícies frias, cortes e contaminação do gelo. Além disso, não existia uma padronização clara do processo, favorecendo desvios comportamentais e condições inseguras durante a atividade.', N'01 - Imagens/02 - Depois/11398.jpeg', N'Foi implantada uma comunicação visual de segurança na máquina de gelo, reforçando a proibição do manuseio do gelo com as mãos e orientando a utilização da pazinha apropriada disponível no equipamento. A ferramenta passou a ser mantida em local de fácil acesso e identificação, padronizando o processo de retirada do gelo. A melhoria eliminou o contato direto das mãos com o gelo, reduziu a exposição a riscos de lesões e contaminação, aumentou a conscientização dos empregados sobre o uso correto de ferramentas e fortaleceu a cultura de segurança da área. A ação também possibilita replicação em outras máquinas de gelo da unidade.', NULL, N'O problema foi resolvido através da implantação da comunicação visual e da padronização da utilização da pazinha para retirada do gelo. A melhoria eliminou o manuseio direto do gelo com as mãos, reduziu a exposição ao risco e reforçou a aplicação do princípio "Suas mãos não são ferramentas", contribuindo para um ambiente de trabalho mais seguro.', N'Pequenas melhorias e reforços visuais podem eliminar comportamentos inseguros e reduzir a exposição aos riscos. A disponibilização de ferramentas adequadas e a conscientização dos empregados contribuem para a execução segura das atividades.', 0, NULL, N'Eliminar o risco de contato com a guilhotina da válvula, aumentar a segurança dos colaboradores, prevenir acidentes e garantir melhores condições de operação e manutenção.', '2026-07-27T00:00:00.000', '2026-07-28T00:52:55.000', N'81046234', NULL, NULL);
INSERT INTO #PVC VALUES (11399, N'517558', N'517558', N'IMPLEMENTACAO DE ALARME SONORO NA CAIXA DE FORÇA DO SISTEMA DE INCENDIO DA USINA III', NULL, N'Others/Outros', N'A CAIXA DE FORÇA DO SISTEMA DE ALARME DE INCENDIO POSSUIA APENAS UMA TRANCA QUE FACILITA ABERTURA DE SUA PORTA. POR TODOS ', N'AUMENTAR A PROTEÇAO NA CAIXA DE FORÇA DE INCENDIO ', N'10011', N'01 - Imagens/01 - Antes/11399.jpeg', N'A CAIXA DE FORÇA DO SISTEMA DE ALARME DE INCENDIO POSSUIA APENAS UMA TRANCA QUE FACILITA ABERTURA DE SUA PORTA. POR TODOS', N'01 - Imagens/02 - Depois/11399.jpeg', N' COM A INSTALACAO DE UM ALARME SONORO LIMITA O ACESSO DE PESSOA NAO AUTORIZADA.', NULL, N'SIM', N'MAIS CONTROLE DE ACESSO DE PESSOAS NAO AUTORIZADAS ', 0, NULL, N'Criação de um método único para a execução da limpeza; redução de variabilidade ;Elaboração e Implantação de Instrução de trabalho etc..', '2026-07-27T00:00:00.000', '2026-07-28T03:50:36.000', N'517558', NULL, NULL);
INSERT INTO #PVC VALUES (11400, N'81041919', N'81041919', N'Padronização da posição construtiva dos motores M1 e M2 TR_2020_03 para eliminação de retrabalho em substituições', 2, N'Others/Outros', N'O motor M1 possuía configuração construtiva B3D, diferente do motor M2, que utiliza configuração B3E. Durante as substituições de motores, os motores sobressalentes disponíveis geralmente chegavam com a caixa de ligação posicionada de forma incompatível com a instalação. Essa condição gerava retrabalho frequente, exigindo a inversão da caixa de ligação na oficina antes da liberação do equipamento ou adaptações provisórias dos cabos elétricos em campo durante emergências. Como consequência, ocorria aumento do escopo das atividades de manutenção, maior tempo de indisponibilidade do equipamento, elevação dos custos de mão de obra e aumento da exposição da equipe aos riscos da intervenção.', N'Padronizar a configuração construtiva dos motores M1 e M2, alterando o motor M1 de B3D para B3E, eliminando a necessidade de adequações em oficina e intervenções provisórias em campo, reduzindo o tempo de substituição, aumentando a segurança e melhorando a disponibilidade operacional do equipamento.', N'10178', N'01 - Imagens/01 - Antes/11400.jpeg', N'Os motores M1 e M2 possuíam configurações construtivas diferentes, resultando em incompatibilidade da posição da caixa de ligação nos motores sobressalentes. Isso exigia inversão da caixa na oficina ou adaptações provisórias dos cabos em campo durante as substituições. Como consequência, ocorria retrabalho, aumento do tempo de manutenção, ampliação do escopo das atividades e maior exposição das equipes aos riscos operacionais, impactando a disponibilidade do equipamento.', N'01 - Imagens/02 - Depois/11400.jpeg', N'Os motores M1 e M2 foram padronizados para a configuração B3E, eliminando incompatibilidades na posição da caixa de ligação. A melhoria eliminou retrabalhos em oficina e campo, reduziu o tempo de manutenção e aumentou a disponibilidade dos equipamentos.', NULL, N'A padronização da configuração construtiva para B3E eliminou uma condição crônica de retrabalho durante as substituições de motores. A necessidade de inverter a caixa de ligação em motores de alta tensão exigia desmontagens e ajustes adicionais, aumentando o tempo de manutenção, a exposição dos trabalhadores aos riscos da atividade e o potencial de falhas decorrentes de intervenções desnecessárias. Com a padronização, os motores sobressalentes tornaram-se totalmente intercambiáveis, reduzindo o tempo de reparo, aumentando a confiabilidade do processo e contribuindo para maior disponibilidade operacional dos equipamentos.', N'A padronização de equipamentos similares reduz retrabalhos, simplifica as atividades de manutenção e aumenta a agilidade nas intervenções corretivas e emergenciais.', 0, NULL, N'proteção coletiva robusta que impede acidentes em altura para os colaboradores em tráfego.', '2026-07-17T00:00:00.000', '2026-07-28T09:44:24.000', N'81041919', NULL, NULL);
INSERT INTO #PVC VALUES (11401, N'140178', N'140178', N'Implantação do Minuto da Orientação para Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i', 2, N'Others/Outros', N'Foi identificada a necessidade de aumentar a conscientização e a aderência dos empregados e contratados aos procedimentos de bloqueio e etiquetagem (LOTO) da Perfuratriz Sandvik DR416i. As informações da matriz de bloqueio encontram-se disponíveis nos documentos técnicos, porém nem sempre são consultadas antes das intervenções, dificultando a rápida identificação das energias envolvidas, pontos críticos de bloqueio e sequência correta das etapas de energia zero. Essa condição pode aumentar a exposição aos riscos operacionais e comprometer a efetividade dos controles de segurança durante atividades de manutenção, inspeção e diagnóstico.', N'Fortalecer a cultura de bloqueio de energias e segurança operacional nas atividades de manutenção e intervenção da Perfuratriz Sandvik DR416i, por meio da implementação de comunicação visual padronizada (Minuto da Orientação), promovendo maior conscientização dos riscos, redução de desvios de bloqueio, aumento da conformidade com a matriz de energias e prevenção de acidentes relacionados às fontes elétrica, hidráulica, térmica, gravitacional e pneumática.', N'#N/A', N'01 - Imagens/01 - Antes/11401.jpeg', N'Não existia material visual padronizado sobre a Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i. As informações estavam disponíveis apenas em documentos técnicos, dificultando a consulta rápida, a identificação das fontes de energia e a orientação das equipes durante atividades de manutenção e inspeção', N'01 - Imagens/02 - Depois/11401.jpeg', N'Foi desenvolvido e implantado o “Minuto da Orientação” da Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i, contendo comunicação visual simplificada, identificação das energias críticas, pontos de bloqueio, etapas para energia zero e principais riscos do equipamento. O material passou a ser utilizado em DDS, orientações de campo e atividades de manutenção, facilitando a consulta rápida, aumentando a conscientização das equipes e reforçando a aplicação dos procedimentos de bloqueio e etiquetagem (LOTO). [Cópia de C...Básicos 2 | Excel]
INSERT INTO #PVC VALUES (11402, N'923201', N'979633', N'Controle de substituição elementos filtrantes da Osmose Reversa', 1, N'Others/Outros', N'A falta de controle visual de troca dos elementos filtrantes, impactando na qualidade da água para análise ', N'Garantir a qualidade da água e controle da troca insumos.', N'10129', N'01 - Imagens/01 - Antes/11402.jpeg', N'Ausência de controle visual e rastreabilidade das substituições dos elementos filtrantes da osmose reversa, resultando em dificuldades no gerenciamento dos insumos, risco de trocas fora da periodicidade estabelecida e impacto potencial na qualidade da água utilizada nas análises laboratoriais.', N'01 - Imagens/02 - Depois/11402.jpeg', N'Foi implementado um controle visual de gestão da manutenção junto ao sistema de osmose reversa para registro e rastreabilidade das substituições dos elementos filtrantes. Adicionalmente, foi padronizado um critério de troca preventiva, no qual a cada cinco substituições do filtro PP05 é realizada a renovação programada dos demais filtros, otimizando a vida útil do sistema de filtração e assegurando o fornecimento contínuo de água com especificação adequada para as análises laboratoriais.', NULL, N'O controle visual implementado permitiu padronizar e rastrear as trocas dos elementos filtrantes, melhorando a gestão dos insumos, assegurando a qualidade da água produzida e atendendo à necessidade identificada no cenário inicial.', N'Controle e rastreabilidade dos processos.', 0, NULL, N'Redução de aproximadamente 276 HH/ano dedicadas à análise e correção de fechamentos de massa.
INSERT INTO #PVC VALUES (11403, N'81056094', N'81039915', N'IT Radio Support Channel on ICE Platform', NULL, N'Others/Outros', N'Users had limited options to quickly report issues and obtain IT support while working remotely.', N'Provide real-time IT support through call and text capabilities on Sonim devices.', N'10100', N'01 - Imagens/01 - Antes/11403.jpeg', N'Reporting IT issues could be delayed, impacting response times and user productivity.', N'01 - Imagens/02 - Depois/11403.jpeg', N'Implemented an IT Radio Support Channel, allowing users to call or text IT directly from Sonim phones. Established a dedicated support channel that improved communication and access to IT assistance.', NULL, N'The new support channel provides direct access to IT, improving responsiveness and issue resolution.', N'Accessible communication channels improve user engagement and speed up issue reporting.', 0, NULL, N'SSMARE
INSERT INTO #PVC VALUES (11404, N'81040303', N'81040303', N'Aplicativo de turno', 1, N'Others/Outros', N'Área necessitava de uma aplicação para centralização de informações, gerenciamento e geração de relatórios das ocorrências do turno. O processo acontecia com Reports via WhatsApp em grupos do turno, gerando dificuldade de acompanhamento e com risco de perda de informações importantes.', N'Gerenciamento; Otimização', N'10293', N'01 - Imagens/01 - Antes/11404.jpeg', N'Processo acontecia via WhatsApp com o envio via grupos, de fotos, relatos e pendências.', N'01 - Imagens/02 - Depois/11404.jpeg', N'Desenvolvimento de aplicativo em Power Apps para gestão operacional de ocorrências e pendências do GPVm, permitindo a consulta das paradas registradas no sistema, inclusão de comentários e anexação de evidências diretamente aos apontamentos. A solução possibilita ainda o cadastro de novas ocorrências, abertura e acompanhamento de pendências, proporcionando maior controle, rastreabilidade e gestão das atividades em aberto. Como complemento, o aplicativo oferece a geração automática de relatórios em PDF contendo todas as ocorrências registradas no turno, facilitando o compartilhamento das informações e apoiando a tomada de decisão operacional. ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/90d8e0e8-6a87-4225-a4a7-c077ec7c8a12?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=8e2fad7f-8c9f-4e4b-8bb9-7c250544ce54&sourcetime=1785247482395&source=portal', N'Com o início de utilização do app, houve uma melhora no gerenciamento das informações do turno, permitindo um acompanhamento dos acontecimentos e otimização de tempo com geração de relatórios de turno.', N'Trabalho em equipe; Centralização de informações; Padronização', 500000, 1, N' A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', '2026-07-01T00:00:00.000', '2026-07-28T12:00:28.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (11405, N'550466', N'544517', N'Rebaixamento estrutural', 2, N'Others/Outros', N'As chaves seccionadoras estavam instaladas em altura muito elevada, dificultando a operação. Essa condição gerava baixa ergonomia, maior esforço físico dos executantes e aumento do risco durante o seccionamento, além de tornar as manobras mais lentas e menos seguras.
INSERT INTO #PVC VALUES (11406, N'81056094', N'81050495', N'Long Harbour IT Workspace Optimization', NULL, N'Others/Outros', N'Limited storage space and workspace layout reduced efficiency and collaboration among technicians.', N'Improve storage capacity and create a more effective workspace for Long Harbour IT technicians.', N'10100', N'01 - Imagens/01 - Antes/11406.jpeg', N'Technicians had limited storage space and were spread apart, making collaboration more difficult.', N'01 - Imagens/02 - Depois/11406.jpeg', N'Created a dedicated IT room with additional storage space and an improved collaborative work area. Established a centralized IT workspace that supports collaboration, organization, and efficiency.', NULL, N'Yes - The new workspace increased storage capacity and created a more collaborative environment for technicians.', N'Well-designed workspaces improve team collaboration, organization, and productivity.', 0, NULL, N'None', '2026-07-01T00:00:00.000', '2026-07-28T12:58:23.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11407, N'81056094', N'81056094', N'Reusable Calendar Generator Script', NULL, N'Others/Outros', N'Creating and formatting calendars manually was time-consuming.', N'Create a reusable tool to generate standardized calendars quickly and consistently on Excel.', N'10100', N'01 - Imagens/01 - Antes/11407.jpeg', N'Calendars were created manually, requiring repetitive effort and increasing the risk of formatting errors.', N'01 - Imagens/02 - Depois/11407.jpeg', N'Developed a reusable Office Script that automatically generates calendars in Excel. This standardized calendar creation and reduced manual effort through a consistent automated process.', NULL, N'The script automated calendar generation, eliminating repetitive manual formatting and setup work.', N'Building configurable tools increases reusability and reduces maintenance effort over time.', 0, NULL, N' A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', '2026-07-27T00:00:00.000', '2026-07-28T13:03:53.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11408, N'471876', N'471876', N'Controle universal para ar condicionado', 1, N'Others/Outros', N'NÃO TEMOS TODOS OS CONTROLES DE AR DO PRÉDIO', N'eliminar ausência de controle', N'10032', N'01 - Imagens/01 - Antes/11408.jpeg', N'No prédio do Laboratório, temos 62 centrais de ar, nem todas temos o controle, isso as vezes atrapalha, devido esta ausência, muitas vezes fica desligado por não ter Controle remoto do equipamento, sala quente, reclamação ambiente inadequado para pessoas e equipamentos sensiveis.', N'01 - Imagens/02 - Depois/11408.jpeg', N'Fizemos uma reflexão do problema e pesquisamos com nossos contratos, adquirimos um controle universal, compatível com 99% das marcas de ar condicionados, melhorando assim o atendimento principalmente para o turno.', NULL, N'alcançado', N'pesquisando a gente consegue resolver.', 0, NULL, N'Definitive information on couplings', '2026-07-24T00:00:00.000', '2026-07-28T13:43:20.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11409, N'81023633', N'507447', N'Adequação de Segurança e Fechamento de Guarda-Corpo', 2, N'Others/Outros', N'O sistema antigo utilizava uma proteção simples de tubos (roll). Apresentava apenas barras horizontais e grandes vãos abertos.Ferramentas podiam cair facilmente pelas aberturas da estrutura. Não existia uma barreira de contenção totalmente segura para os operadores.', N'Mitigar o risco de queda de ferramentas e materiais, Proteger os operadores contra acidentes em vãos abertos.', N'10064', N'01 - Imagens/01 - Antes/11409.jpeg', N'A proteção antiga era feita com um sistema simples de tubos (roll). Esse modelo contava apenas com barras horizontais e deixava grandes vãos abertos na estrutura. Essa falta de fechamento aumentava o risco de acidentes. Ferramentas podiam cair facilmente e os operadores não tinham uma barreira de contenção totalmente segura.
INSERT INTO #PVC VALUES (11410, N'81058966', N'81036062', N'Fabricação de Carretel em Inox para a CF', 1, N'Others/Outros', N'Durante as inspeções em campo foi identificado que os carretéis utilizados apresentavam desgaste e quebras frequentes, dificultando a reposição imediata durante as manutenções. Essa condição aumentava o tempo de intervenção, comprometia a disponibilidade do equipamento e elevava os riscos para a equipe.', N'Reduzir os riscos durante as atividades de manutenção, proporcionando maior agilidade, segurança e confiabilidade no processo de substituição dos componentes.', N'10031', N'01 - Imagens/01 - Antes/11410.jpeg', N'Os carretéis antigos sofriam desgaste e quebra com frequência, dificultando a reposição imediata e ocasionando atrasos nas atividades de manutenção.', N'01 - Imagens/02 - Depois/11410.jpeg', N'Foi fabricado um novo carretel em aço inox, permitindo um reparo mais rápido, prático e eficiente quando necessário. A melhoria aumentou a durabilidade do componente. ', NULL, N'sim.a fabricação do caritel em inox eliminou as quebras recorrentes do componente, facilitou a reposição durante as manutenções, reduziu o tempo de intervenção e aumentou a segurança dos empregados.', N'A busca contínua por melhorias nos equipamentos contribui para aumentar a segurança, reduzir o tempo de manutenção e garantir maior confiabilidade ao processo.', 0, NULL, N'Redução de aproximadamente 69% no tempo de limpeza (de 8h para 2h30), aumento da produtividade, maior disponibilidade do equipamento para manutenção, melhoria da segurança e redução da exposição dos colaboradores aos reagentes e à umidade.', '2026-07-07T00:00:00.000', '2026-07-28T15:17:54.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11411, N'81058966', N'81010570', N'Substituição de Válvula com Proteção – BO-2017-25', 1, N'Others/Outros', N'Durante inspeções na área, foi identificado que a válvula instalada possuía a guilhotina exposta, sem qualquer proteção, oferecendo risco de acidentes com as mãos e dedos dos colaboradores durante a operação e manutenção do equipamento. Essa condição comprometia a segurança da atividade e exigia uma ação corretiva.', N'Eliminar o risco de acidentes por contato com a guilhotina da válvula, aumentando a segurança dos colaboradores e adequando o equipamento às boas práticas de segurança.', N'10031', N'01 - Imagens/01 - Antes/11411.jpeg', N'A válvula existente possuía a guilhotina exposta, sem proteção, representando risco de prensamento e acidentes durante sua operação.', N'01 - Imagens/02 - Depois/11411.jpeg', N'A válvula antiga foi substituída por um modelo com proteção integrada na guilhotina, eliminando o contato direto com as partes móveis e reduzindo significativamente o risco de acidentes.', NULL, N'sim,A meta foi atingida com a substituição da válvula antiga por um modelo com proteção na guilhotina. A melhoria eliminou a exposição às partes móveis, reduzindo significativamente o risco de acidentes com as mãos e os dedos e tornando a operação mais segura.', N'A identificação e eliminação de condições inseguras contribuem para um ambiente de trabalho mais seguro. A melhoria contínua deve fazer parte da rotina, buscando sempre prevenir acidentes antes que ocorram.', 0, NULL, N'e melhoria das condições de segurança e manutenção.', '2026-07-27T00:00:00.000', '2026-07-28T15:28:46.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11412, N'763789', N'763789', N'Implantação do Método Padronizado de Limpeza Setorizada das Sapatas do Armazém de Carvão.', 1, N'Others/Outros', N'A limpeza das sapatas era realizada sem sequência padronizada, gerando deslocamentos desnecessários e dificuldade para identificar o status de cada posição. Em observações de campo, identificou-se ausência de critérios para definição da sequência de limpeza, diferenças na execução entre equipes e falta de um padrão visual para controle da atividade.', N'Implementar um novo método padronizado de limpeza das sapatas, baseado em setorização e gestão visual, visando aumentar a eficiência operacional, melhorar a organização da atividade e eliminar desperdícios durante a execução da limpeza.', N'10294', N'01 - Imagens/01 - Antes/11412.jpeg', N'A limpeza das sapatas era realizada de forma não padronizada, sem definição de sequência entre os pontos. Os empregados deslocavam-se entre diferentes sapatas conforme a necessidade percebida no momento, gerando movimentações desnecessárias, dificuldade de acompanhamento da atividade e variação na forma de execução entre equipes.
INSERT INTO #PVC VALUES (11413, N'81023633', N'81022716', N'Blindagem contra Quedas', 1, N'Others/Outros', N'Utilização inadequada de postes improvisados de sinalização fincados no solo.
INSERT INTO #PVC VALUES (11414, N'81028405', N'81028405', N'Dimensionamento Técnico do Parque Reserva de Componentes e Periféricos das Perfuratrizes 320XPC', 1, N'No Replication/Sem replicação', N'A frota de perfuratrizes 320XPC não possuía um critério técnico padronizado para dimensionamento do parque reserva de componentes e periféricos críticos. A definição dos estoques era baseada principalmente em percepções operacionais e experiências anteriores, gerando risco de indisponibilidade por falta de peças em eventos de falha e, simultaneamente, possibilidade de capital excessivamente imobilizado em materiais de baixa necessidade.
INSERT INTO #PVC VALUES (11415, N'81015967', N'81015967', N'Implantação de Balança Integrada na Britagem Secundária para Redução dos Ajustes de Reconciliação de Massa', 1, N'Others/Outros', N'Desvios  significativos entre as medições entre a balança da TR 2005-03 , medição na pilha e os dados de fechamento produção, exigindo ajustes mensais elevados para fechamento de massa. Em dezembro, a britagem secundária (ALBRITSECSLB1_2) demandou correção de +115.319 t, correspondente a 5,7% da produção do período, indicando baixa confiabilidade na medição do fluxo de minério e dificultando a gestão operacional e o controle de perdas.', N'Reduzir em 90% os desvios de reconciliação de massa da britagem secundária, aumentando a confiabilidade das medições e reduzindo o percentual de ajuste da produção para patamares inferiores a 1%.', N'10293', N'01 - Imagens/01 - Antes/11415.jpeg', N'Existiam desvios significativos entre as medições da britagem secundária, pilhas de minério e fechamento da produção, gerando baixa confiabilidade dos dados e necessidade de elevados ajustes de massa. Em dezembro, o ajuste atingiu 115.319 t (5,7% da produção), impactando a gestão operacional, a tomada de decisão, o planejamento da usina e a confiabilidade dos estoques de minério.
INSERT INTO #PVC VALUES (11416, N'81046597', N'81046597', N'Ferramenta de Análise de Testes de Oportunidade DBU', NULL, N'Open Pit/Poço aberto', N'A análise dos desvios humanos na DBU era limitada ao item do procedimento descumprido, sem identificação estruturada das causas subjacentes. Isso exigia análise manual das observações dos Testes de Oportunidade, tornando o processo de geração de insights demorado, complexo e pouco eficiente para direcionar ações de confiabilidade humana.', N'Reduzir o tempo de obtenção, análise e apresentação de dados relacionados à confiabilidade humana, por meio de uma ferramenta padronizada de classificação de desvios operacionais e gestão visual.', N'10293', N'01 - Imagens/01 - Antes/11416.jpeg', N'A elaboração de um relatório de confiabilidade humana com base nos registros de 2026 demandaria entre 6 e 8 horas, considerando todo o processo de análise.', N'01 - Imagens/02 - Depois/11416.jpeg', N'A classificação e análise dos 29 desvios registrados em 2026 foram realizadas em aproximadamente 30 minutos, enquanto o relatório passou a ser gerado automaticamente. Redução de 91,7% do tempo de elaboração do relatório.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/5c4ce671-9ac9-4b16-953f-d1556a080401/c61511ca5aab9b4e5902?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'•	Embora o tempo de análise individual tenha aumentado devido ao maior nível de detalhamento, a padronização da classificação e a automatização da consolidação dos dados resultaram em uma redução significativa do tempo total de elaboração de relatórios e em uma melhoria da qualidade de análise.', N'Uma análise estruturada reduz a subjetividade na avaliação de fatores de desempenho humano; Dados confiáveis são essenciais para análises eficazes de confiabilidade humana; Ferramentas digitais são fundamentais para o gerenciamento da rotina. ', 0, NULL, N'BI COM A VISÃO DA CATEIRA POR ÁREAS E PROCESSOS, DE ONDE É POSSÍVEL TER UMA VISÃO ATUALIZADA DA CARTEIRA PARA REALIZAR ANÁLISES E TOMADAS DE DECISÃO.', '2026-07-24T00:00:00.000', '2026-07-28T22:10:02.000', N'81046597', NULL, NULL);
INSERT INTO #PVC VALUES (11417, N'81029862', N'81029862', N'Implantação de Cadeira para Melhoria Ergonômica no Posto de Trabalho', 2, N'No Replication/Sem replicação', N'O processo de lançamento dos resultados exigia que o colaborador permanecesse em pé por cerca de 30 á 40 minutos, gerando desconforto ergonômico e fadiga nas pernas e costas durante a execução da atividade.', N'Redução de risco ergonômico durante a atividade lançamentos de resultados', N'10198', N'01 - Imagens/01 - Antes/11417.jpeg', N'O lançamento dos resultados era realizado com o colaborador permanecendo em pé durante todo o processo, com duração média de 30 a 40 minutos. Essa condição gerava desgaste físico e risco ergonômico, ocasionando dores nas pernas e na região lombar, comprometendo o conforto e o bem-estar durante a execução da atividade.', N'01 - Imagens/02 - Depois/11417.jpeg', N'Foi disponibilizada uma cadeira para a realização do lançamento dos resultados, permitindo que o colaborador execute a atividade sentado durante todo o processo. A melhoria proporcionou maior conforto ergonômico, reduzindo a sobrecarga física, a fadiga e o risco de dores nas pernas, além de tornar a atividade mais confortável e segura.', NULL, N'Com a instalação de uma cadeira no posto de trabalho, o colaborador passou a realizar o lançamento dos resultados sentado. A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', N'Pequenas adaptações podem eliminar riscos significativos.', 0, NULL, N'Melhoria no controle de acesso à área operacional', '2026-07-28T00:00:00.000', '2026-07-29T04:05:23.000', N'81029862', NULL, NULL);
INSERT INTO #PVC VALUES (11418, N'1008360', N'81036743', N'Flange Identification  ', 2, N'Others/Outros', N'Flange/Pipe didnt have paint on it often posing a problem to strike up against ', N'Paint the object to make sure its seen ', N'0', N'01 - Imagens/01 - Antes/11418.jpeg', N'Flange not painted before ', N'01 - Imagens/02 - Depois/11418.jpeg', N'Flange now painted making it more visible to avoid any strikes ', NULL, N'Yes', N'More visible is safer', 0, NULL, N'melhoria no armazenamento e manuseio dos materiais', '2026-07-28T00:00:00.000', '2026-07-29T04:13:45.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11419, N'1008360', N'81036743', N'Lime Tank Drain Identification ', 2, N'Others/Outros', N'Drain is full of lime and can easily be walked into ', N'Make the drain on the lime tank more visible ', N'0', N'01 - Imagens/01 - Antes/11419.jpeg', N'Drain full of lime making it now harder to see', N'01 - Imagens/02 - Depois/11419.jpeg', N'Drain now painted a bright orange and is more visible ', NULL, N'Yes', N'brighter is better ', 0, NULL, N'Mais agilidade e rapidez para encontrar as baterias carregadas', '2026-07-28T00:00:00.000', '2026-07-29T04:17:15.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11420, N'81029862', N'81029862', N'Implantação de Cadeira para Melhoria Ergonômica no Posto de Trabalho', 2, N'No Replication/Sem replicação', N'O processo de lançamento dos resultados exigia que o colaborador permanecesse em pé por cerca de 30 minutos, gerando desconforto ergonômico e fadiga nas pernas, costas e região cervical durante a execução da atividade.', N'Redução de risco ergonômico durante a atividade lançamentos de resultados', N'10082', N'01 - Imagens/01 - Antes/11420.jpeg', N'O lançamento dos resultados era realizado com o colaborador permanecendo em pé durante todo o processo, com duração média de 30 a 40 minutos. Essa condição gerava desgaste físico e risco ergonômico, ocasionando dores nas pernas e na região lombar, comprometendo o conforto e o bem-estar durante a execução da atividade.', N'01 - Imagens/02 - Depois/11420.jpeg', N'Foi disponibilizada uma cadeira para a realização do lançamento dos resultados, permitindo que o colaborador execute a atividade sentado durante todo o processo. A melhoria proporcionou maior conforto ergonômico, reduzindo a sobrecarga física, a fadiga e o risco de dores nas pernas, além de tornar a atividade mais confortável e segura.', NULL, N'Com a instalação de uma cadeira no posto de trabalho, o colaborador passou a realizar o lançamento dos resultados sentado. A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', N'Pequenas adaptações podem eliminar riscos significativos.', 0, NULL, N'Permitir ao eletricista sair da zona de risco durante a realização de manobras de fechamento de disjuntores ', '2026-07-28T00:00:00.000', '2026-07-29T05:22:57.000', N'81029862', NULL, NULL);
INSERT INTO #PVC VALUES (11421, N'1009878', N'1009878', N'Lime Vic Fitting Tracker for Pipeline', 1, N'Refining/Refino', N'There are multiple victaulic fittings on the lime pipeline which need to be inspected or replaced.  We do not have any detailed drawings showing where or how many couplings we have', N'Determine Quantity of Vic Fittings and Track Them', N'0', N'01 - Imagens/01 - Antes/11421.jpeg', N'There are no definitive details on where the Victaulic couplings are located and how many we have.', N'01 - Imagens/02 - Depois/11421.jpeg', N'The pipeline was walked and each location was given a number.  A tracker was then developed and the civil drawing was marked up to show the team where the couplings are located.  This also provides a means to determined what was repaired and what is outstanding.', NULL, N'It is now clear how many couplings we have and where they are located', N'More Detail on Couplings', 0, NULL, N'Eliminado atrasos nas atividades do caminho critico com problemas de equipamentos de contingências ', '2026-07-27T00:00:00.000', '2026-07-29T06:46:55.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11422, N'81033365', N'1005614', N'Proteção da bomba do arla', 1, N'Others/Outros', N'ausência de proteção contra acumulo de material', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11422.jpeg', N'O acúmulo de material sobre o sistema de ARLA do caminhão causava a contaminação severa de todos os seus componentes.', N'01 - Imagens/02 - Depois/11422.jpeg', N'Desenvolvimento e instalação de uma carenagem de proteção sob medida para bloquear o contato dos materiais com o sistema.', NULL, N'ausência de uma proteção, e fabricado uma proteção.', N'melhoria continua', 0, NULL, N'This has gone as expected. All parties are happy with this change.', '2026-07-28T00:00:00.000', '2026-07-29T08:32:14.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11423, N'81058966', N'498974', N' Instalação de Válvula de Dreno na Caixa de Flotação CF-2017-07', 1, N'Others/Outros', N' Durante as atividades de manutenção da caixa de flotação CF-2017-07 foi identificada a ausência de uma válvula de dreno na parte inferior do equipamento. Essa condição dificultava a drenagem do material acumulado, fazendo com que a equipe da Sodexo gastasse aproximadamente um turno de 8 horas para realizar a limpeza interna.', N'Implantar uma válvula guilhotina de 4 polegadas para facilitar a drenagem do material acumulado, reduzindo o tempo de limpeza de 8 horas para aproximadamente 2 horas e 30 minutos, aumentando a segurança, a produtividade e a disponibilidade do equipamento.', N'10031', N'01 - Imagens/01 - Antes/11423.jpeg', N' a caixa de flotação não possuía válvula de dreno, dificultando a retirada do material acumulado na parte inferior. A limpeza era realizada manualmente, demandando cerca de 8 horas.', N'01 - Imagens/02 - Depois/11423.jpeg', N'Instalada válvula guilhotina de 4" em um ponto estratégico da caixa de flotação, permitindo a drenagem rápida do material acumulado. O tempo de limpeza foi reduzido para  2 horas e 30 minutos, proporcionando maior agilidade, segurança e eficiência.', NULL, N'Sim, O problema foi resolvido com a instalação da válvula guilhotina de 4". A melhoria permitiu a drenagem eficiente do material acumulado, reduziu significativamente o tempo de limpeza, aumentou a produtividade das equipes de manutenção e eliminou a necessidade de longos períodos de limpeza manual, proporcionando maior segurança durante a execução das atividades.', N'A instalação de dispositivos simples, como uma válvula de dreno, pode gerar ganhos expressivos em segurança, produtividade e redução do tempo de manutenção. A identificação de oportunidades em campo e a atuação preventiva contribuem para a melhoria contínua dos processos.', 0, NULL, N'Diminuição de tempo necessário para coleta e envio de informações, redução de 10 minutos para menos de 1 minuto.
INSERT INTO #PVC VALUES (11424, N'81058966', N'81038896', N'Instalação de Válvula de Dreno CF-2017-06', 1, N'Others/Outros', N'Durante a manutenção da caixa de flotação CF-2017-06 foi identificada a ausência de uma válvula de dreno, dificultando a remoção do material acumulado. A limpeza demandava cerca de 8 horas, causando atrasos, baixa produtividade e exposição dos colaboradores à umidade e aos reagentes.', N'Instalar uma válvula guilhotina de 4" para reduzir o tempo de limpeza de 8 horas para 2h30, aumentando a segurança, a produtividade e a eficiência da manutenção.', N'10031', N'01 - Imagens/01 - Antes/11424.jpeg', N' Sem válvula de dreno, a limpeza da caixa era manual e demorava cerca de 8 horas, gerando atrasos na manutenção e maior exposição dos colaboradores à umidade e reagentes.', N'01 - Imagens/02 - Depois/11424.jpeg', N' Foi instalada uma válvula guilhotina de 4", reduzindo a limpeza para cerca de 2h30, melhorando a drenagem, a produtividade e a segurança das equipes.', NULL, N' Sim. A meta foi atingida com redução do tempo de limpeza.', N'Pequenas melhorias de engenharia podem reduzir o tempo de manutenção, aumentar a segurança e elevar a eficiência operacional.', 0, NULL, N'SSMA
INSERT INTO #PVC VALUES (11425, N'517013', N'517013', N'Automatização do Dimensionamento de Hh Preventivo para Estudos de Mão de Obra', 1, N'Open Pit/Poço aberto', N'O levantamento das horas-homem (Hh) preventivas para estudos de dimensionamento de mão de obra era realizado manualmente no SAP, demandando elevado esforço operacional e alto tempo de processamento.', N'Automatizar a obtenção e consolidação das horas planejadas de manutenção preventiva, reduzindo o esforço manual e aumentando a confiabilidade das informações utilizadas nos estudos de dimensionamento de mão de obra.', N'10015', N'01 - Imagens/01 - Antes/11425.jpeg', N'Para obter o dimensionamento de HH preventivo utilizado nos estudos de mão de obra, era necessário acessar o SAP e consultar individualmente os planos de manutenção, registrando manualmente os valores das listas de tarefas. O processo era totalmente manual, demorado e trabalhoso, exigindo grande movimentação entre telas e registros. Além disso, havia elevado risco de erros de digitação, inconsistências nos resultados e retrabalho para validação das informações.', N'01 - Imagens/02 - Depois/11425.jpeg', N'Foi estruturada uma solução baseada em modelagem de dados no Power Query, onde basta realizar a extração da base do SAP para que todo o tratamento e consolidação dos dados ocorram automaticamente. A solução reúne os tempos planejados de HH dos planos de manutenção em uma única estrutura padronizada e confiável, reduzindo atividades manuais, aumentando a agilidade do processo e garantindo maior qualidade e confiabilidade das informações para os estudos de dimensionamento de mão de obra.', NULL, N'Foi desenvolvida uma modelagem de dados utilizando Power Query no Excel, capaz de tratar automaticamente a base exportada do SAP e consolidar os tempos de HH planejados dos planos de manutenção em uma estrutura única para análise, gasto médio 16 horas reduzido para 1 hora.', N'A utilização de modelagem de dados para automatizar processos de consolidação reduz significativamente o esforço operacional, melhora a qualidade das informações e libera tempo para atividades de maior valor agregado.', 0, NULL, N'Redução estimada de até R$ 7.200,00 por ano com a eliminação de custos de manutenção corretiva dos cantos das paredes. A melhoria foi realizada com o reaproveitamento de correia de tambor de retorno, evitando descarte e garantindo proteção contra impactos. A solução aumentou a durabilidade da estrutura, reduziu retrabalho e contribuiu para ganhos financeiros e ambientais.
INSERT INTO #PVC VALUES (11426, N'517013', N'517013', N'Automatização do Dimensionamento de Hh Corretivo e Condicional para Estudos de Mão de Obra', 1, N'Open Pit/Poço aberto', N'A obtenção das horas-homem (Hh) corretivas e condicionais para estudos de dimensionamento de mão de obra exigia diversas etapas manuais de tratamento e consolidação de dados, tornando o processo demorado e sujeito a erros.', N'Automatizar a consolidação das horas executadas em manutenções corretivas e condicionais, reduzindo o esforço operacional e aumentando a confiabilidade das informações utilizadas nos estudos de dimensionamento de mão de obra.', N'10015', N'01 - Imagens/01 - Antes/11426.jpeg', N'Para obter o dimensionamento de HH corretivo e condicional utilizado nos estudos de mão de obra, era necessário baixar uma base de dados proveniente de um relatório em Power BI do PCM e realizar diversas tratativas manuais, incluindo agregação de valores, classificação de itens e consolidação das informações. O processo era demorado, repetitivo, sujeito a erros operacionais e exigia elevado esforço para garantir a consistência dos dados antes da análise.', N'01 - Imagens/02 - Depois/11426.jpeg', N'Foi estruturada uma solução baseada em modelagem de dados no Power Query, onde basta realizar a extração da base do Power BI para que todo o tratamento, classificação e consolidação das informações ocorram automaticamente. A solução reúne os tempos executados das ordens de manutenção corretiva e condicional em uma estrutura única, padronizada e confiável, proporcionando maior agilidade, redução de atividades manuais (de 8 horas para 30 minutos) e aumento da confiabilidade dos dados utilizados nos estudos de dimensionamento de mão de obra.', NULL, N'Foi desenvolvida uma modelagem de dados utilizando Power Query no Excel para automatizar as etapas de tratamento, classificação, consolidação e cálculo dos tempos executados das ordens corretivas e condicionais a partir da base extraída do Power BI do PCM.', N'A automação através de modelagem de dados reduz significativamente o tempo de preparação das informações, elimina retrabalhos e aumenta a qualidade dos dados utilizados em análises técnicas.', 0, NULL, N'performance, produtividade, segurança, tempo', '2026-07-28T00:00:00.000', '2026-07-29T09:53:12.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (11427, N'517013', N'517013', N'Automatização da Avaliação de Critérios para Cadastro de Local de Instalação de 6º Nível', 1, N'Open Pit/Poço aberto', N'A definição sobre a possibilidade de cadastro de locais de instalação de 6º nível durante a elaboração do documento normativo de dados mestres VBM dependia de análises interpretativas dos critérios estabelecidos, gerando dúvidas e dificuldades para tomada de decisão padronizada.', N'Padronizar e automatizar a avaliação dos critérios para cadastro de locais de instalação de 6º nível, garantindo decisões consistentes e alinhadas ao documento normativo.', N'10015', N'01 - Imagens/01 - Antes/11427.jpeg', N'Durante a elaboração do documento normativo de dados mestres VBM, existiam dúvidas e dificuldades para determinar quando um local de instalação poderia ser cadastrado como 6º nível. A análise dependia da interpretação dos critérios definidos no documento, tornando o processo sujeito a diferentes entendimentos, discussões, retrabalho e falta de padronização na tomada de decisão.', N'01 - Imagens/02 - Depois/11427.jpeg', N'Foi desenvolvida uma planilha inteligente que utiliza perguntas estruturadas com respostas em formato dropdown para avaliar automaticamente os critérios definidos no documento normativo. Com base nas respostas fornecidas, a ferramenta gera uma recomendação objetiva indicando se o cadastro como local de instalação de 6º nível é aplicável ou não, garantindo uma decisão padronizada, rastreável e fundamentada nos critérios e diretrizes estabelecidos. Houve uma redução significativa no processo de 1 hora para 5 minutos.', NULL, N'Foi desenvolvida uma planilha inteligente em Excel com lógica de decisão baseada em perguntas e respostas pré-configuradas, utilizando validação de dados (dropdowns) e fórmulas automatizadas para avaliar os critérios definidos no documento normativo e emitir uma recomendação padronizada.', N'Transformar regras e critérios normativos em ferramentas automatizadas reduz subjetividades, aumenta a padronização e melhora a qualidade das decisões.', 0, NULL, N'Sem impacto financeiro direto. Ganhos relacionados ao aumento do engajamento, da comunicação interna e da participação dos colaboradores nas ações de saúde e qualidade de vida.
INSERT INTO #PVC VALUES (11428, N'81022762', N'81059346', N'Suporte de latas (limpa contato, desingripante)', 1, N'Others/Outros', N'Latas ficavam espalhadas sem um local definido
INSERT INTO #PVC VALUES (11429, N'81034922', N'81027004', N'BI DA CARTEIRA DE ORDENS PGB E PGU', 1, N'Others/Outros', N'HAVIA UMA DEFICIÊNCIA PARA OBTER OS DADOS DA CARTEIRA DE PGB E PGU PARA SE FAZER ANÁLISE, TENDO QUE BAIXAR A BASE MANUALMENTE DO SAP E CRIAR TABELAS DINAMICAS PARA ANALISAR.', N'CONTROLE VISUAL PARA ANÁLISE DA CARTEIRA DE PGB E PGU', N'10081', N'01 - Imagens/01 - Antes/11429.jpeg', N'HAVIA UMA DEFICIÊNCIA PARA OBTER OS DADOS DA CARTEIRA DE PGB E PGU PARA SE FAZER ANÁLISE, TENDO QUE BAIXAR A BASE MANUALMENTE DO SAP E CRIAR TABELAS DINAMICAS PARA ANALISAR.', N'01 - Imagens/02 - Depois/11429.jpeg', N'CRIADO BI COM A VISÃO DA CATEIRA POR ÁREAS E PROCESSOS, DE ONDE É POSSÍVEL TER UMA VISÃO ATUALIZADA DA CARTEIRA PARA REALIZAR ANÁLISES E TOMADAS DE DECISÃO.', NULL, N'SIM, COM O BI TEMOS A INFORMAÇÃO RÁPIDA DE FORMA VISUAL PARA ANÁLISE AGILIZANDO ASSIM AS TOMADAS DE DECISÃO.', N'BI COMO FORMA VISUAL ATUALIZADO AGILIZA A TOMADA DE DECISÃO', 0, NULL, N'Having the ability to formally submit NCRs and work with vendors to identify areas of improvement will in time improve overall vendor performance as well as improve internal performance with VNL.', '2026-07-06T00:00:00.000', '2026-07-29T10:11:10.000', N'81034922', NULL, NULL);
INSERT INTO #PVC VALUES (11430, N'81022762', N'81059346', N'Adequação do isolamento da praça Itaquerão ', 2, N'Others/Outros', N'Isolamento ineficaz, facilidade de acesso por lugar impróprio, não fazer o uso do caminho seguro.
INSERT INTO #PVC VALUES (11431, N'81022762', N'81059346', N'Suporte de manta e lona', 1, N'Others/Outros', N'Dificuldade ao manusear as mantas absorventes e lona de contenção 
INSERT INTO #PVC VALUES (11432, N'81022762', N'81061987', N'Suporte para baterias que já estão carregadas ', 1, N'Others/Outros', N'Desorganização das baterias carregadas entre baterias descarregadas
INSERT INTO #PVC VALUES (11433, N'81046359', N'81046359', N'Fechamento de disjuntor temporizado via relé', 2, N'Others/Outros', N'Qual é o problema?
INSERT INTO #PVC VALUES (11434, N'81009653', N'81027004', N'Estratégia de abastecimento de equipamentos de Paradas  ', 1, N'No Replication/Sem replicação', N'Antes não havia um plano de atendimento de abastecimento dos equipamentos de contingências  das atividades de paradas de usina, os acionamentos era feito todos via rádio e gerava atrasos nos atendimentos e paradas dos equipamentos , com isso gerava atrasos direto com impactos nas atividades do caminho Critico da parada de usina . ', N'Viabilizar Recursos , reduzir atrasos nas atividades de Paradas ', N'10081', N'01 - Imagens/01 - Antes/11434.jpeg', N'Antes não havia um plano de atendimento de abastecimento dos equipamentos de contingências  das atividades de paradas de usina, os acionamentos era feito todos via rádio e gerava atrasos nos atendimentos e paradas dos equipamentos , com isso gerava atrasos direto com impactos nas atividades do caminho Critico da parada de usina . ', N'01 - Imagens/02 - Depois/11434.jpeg', N'Foi elaborado , um plano de abastecimento contemplando todos equipamentos de contingência  das atividades criticas da paradas de usina, com localização dos equipamentos , Rota de abastecimento , Horários de abastecimento , e com Tag de todos os equipamentos mapeados nas atividades validado com de time da equipe de combustível do site , gerando assim melhor atendimento e reduzindo atrasos no atendimento , eliminado paradas das atividades do caminho critico por falta de combustível dos equipamentos ', NULL, N'Problema resolvido com ganhos nas entregas das atividades no tempo programado ', N'Falha no abastecimento de equipamentos ', 0, NULL, N'The floor has been repaired and there are no issues in the shipping area in building 6.', '2026-07-01T00:00:00.000', '2026-07-29T10:32:12.000', N'81009653', NULL, NULL);
INSERT INTO #PVC VALUES (11435, N'81031229', N'81031229', N'Procurement Assistance', 1, N'Others/Outros', N'The process of ordering materials can be challenging when considering every step in the work flow. 
INSERT INTO #PVC VALUES (11436, N'81038914', N'81038914', N'Criação de tela no PIMS para reporte gerencial de informações do comissionamento ATHENA – Britagem 1 e 2', 1, N'Open Pit/Poço aberto', N'Foi identificado uma dificuldade e demora no envio das principais informações de comissionamento e Ramp up do projeto.', N'Maior agilidade no envio de informações.', N'10293', N'01 - Imagens/01 - Antes/11436.jpeg', N'Durante a fase de testes e comissionamento do Projeto ATHENA, havia necessidade frequente de reportar informações operacionais para acompanhamento da performance.
INSERT INTO #PVC VALUES (11437, N'81057254', N'81057254', N'Eliminação de Perdas e Contaminação com Graxa Ensacada (SAP 15317285)', 1, N'Others/Outros', N'Durante o consumo de graxa em tambores, permanecia um resíduo médio de 37 kg por tambor (20,5%), exigindo recuperação manual e transferência para outros recipientes.
INSERT INTO #PVC VALUES (11438, N'81042078', N'81042078', N'Replicação: aumento da vida útil da infraestrutura por proteção de cantos em áreas de circulação- Sala de estufa', 1, N'Others/Outros', N'Durante a movimentação e posicionamento dos carrinhos de amostras nas entradas das salas do laboratório, observou-se o impacto frequente nos cantos das paredes. Essa condição ocasionava desgaste da estrutura, descascamento da pintura e necessidade recorrente de manutenção corretiva. Além disso, o contato direto comprometia o padrão visual do ambiente e gerava retrabalho para a equipe. Esse cenário resultava em aumento de custos operacionais e redução da vida útil da infraestrutura, além de impactar negativamente na organização e nos padrões de 5S do laboratório.
INSERT INTO #PVC VALUES (11439, N'81042078', N'81042216', N'Implantação do Método de Determinação da Densidade Aparente de Carvão por Deslocamento de Água', 1, N'Others/Outros', N'O método anteriormente utilizado para determinação da densidade aparente do carvão exigia atividades em campo, como escavação da pilha, utilização de molde metálico, preenchimento do furo com água para determinação do volume, transporte das amostras ao laboratório, secagem em estufa por aproximadamente oito horas e cálculos posteriores. Essas etapas tornavam o processo lento, operacionalmente complexo, com maior consumo de recursos e maior exposição dos colaboradores aos riscos da atividade.
INSERT INTO #PVC VALUES (11440, N'81042078', N'81042078', N'Informativo Mensal – Turma B Sempre em Foco', 1, N'Others/Outros', N'Observou-se a ausência de um canal de comunicação específico para divulgar informações relacionadas à saúde e qualidade de vida da Turma B. Essa falta de divulgação reduz o acesso dos colaboradores a conteúdos relevantes, campanhas internas e orientações sobre hábitos saudáveis, impactando o engajamento e a participação nas ações promovidas pela empresa.
INSERT INTO #PVC VALUES (11441, N'81052333', N'81047054', N'Suporte para as ponteiras do rompedor ', 1, N'Crusher/Britadeira', N'As ponteiras estavam armazenadas em locais inadequados, diretamente sobre o piso superior do britador, gerando risco de tropeço, dificuldade na organização da área e potencial comprometimento da segurança durante as atividades de manutenção.', N'Auxiliar na substituição dos côncavos, garantindo a execução segura e eficiente da manutenção.', N'10362', N'01 - Imagens/01 - Antes/11441.jpeg', N'As ponteiras estavam armazenadas em local inadequado, diretamente sobre o piso superior do britador, gerando risco de tropeço, dificuldade na organização da área e atividade.', N'01 - Imagens/02 - Depois/11441.jpeg', N'Objetivo do suporte: Realizar a remoção e o acondicionamento adequado das ponteiras durante a troca dos côncavos, promovendo maior organização, segurança e eficiência na execução da manutenção.', NULL, N'sim, o suporte está sendo utilizado na substituição dos côncavos, garantindo a execução segura e eficiente da manutenção. Assegurando a continuidade e a confiabilidade da operação do equipamento.', N'melhorias contínuas nos processos operacionais .', 45000, 1, N'.', '2026-07-20T00:00:00.000', '2026-07-29T13:16:12.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (11442, N'81031846', N'1005740', N'NCR Procedure & NCR Vendor Handbook', 1, N'Others/Outros', N'NCR Power App was developed. Refer to Kaizen # 11210. Procedure was required to explain how to use the App, define expectations, obligations, etc.', N'Develop NCR Procedure to explain how to use the NCR App, define expectations, obligations, etc.', N'10026', N'01 - Imagens/01 - Antes/11442.jpeg', N'NCR Power App was developed. Refer to Kaizen # 11210. Procedure was required to explain how to use the App, define expectations, obligations, etc. ', N'01 - Imagens/02 - Depois/11442.jpeg', N'Developed a detailed NCR Procedure & supplemental Workflow & Approvals Reference doc. Also, created a Vendor NCR Handbook defining vendor obligations which auto-attaches to vendor NCRs. Documents linked in NCR App. ', NULL, N'Yes, problem was resolved and goal achieved. More detailed than initially planned. Addition of vendor NCR handbook was not a part of initial plan but will prove to be a great addition to the process.', N'Need for clarity in expectations, roles & approvals within NCR process. Also, importance of providing clarity to vendors on NCR process. ', 0, NULL, N'chemical is now mixing better in the tank which will draw more copper out of the cobalt solution which in turn will make nicer cobalt rounds', '2026-06-19T00:00:00.000', '2026-07-29T13:39:24.000', N'81031846', NULL, NULL);
INSERT INTO #PVC VALUES (11443, N'81011163', N'81062557', N'Substituição de relés SIMOCODE obsoletos (Pro C) por conjuntos-reservas pré-montados com SIMOCODE Pro V', 1, N'Others/Outros', N'Ocorrência de paradas não programadas devido a falhas nos relés SIMOCODE Pro C obsoletos (base instalada de 281 unidades). Os equipamentos apresentam perda de comunicação com a rede, exigindo intervenção manual para restabelecimento da operação, com tempo médio de recuperação de aproximadamente 3 horas. Além disso, a ausência de unidades sobressalentes prontas para reposição rápida amplia o impacto operacional e o tempo de indisponibilidade dos ativos.', N'Evitar as paradas inoportunas com tempo médio de 3 horas de reconexão, decorrentes de falhas nos relés SIMOCODE obsoletos (Pro C), por meio da disponibilização de conjuntos-reserva pré-montados com SIMOCODE Pro V para substituição rápida — conforme validado no piloto 2251 AL-01 —, mitigando o lucro cessante por evento.', N'10081', N'01 - Imagens/01 - Antes/11443.jpeg', N'A gaveta do alimentador 2251 AL-01 (Alimentador de bolas dos moinhos MO-02 e MO-03, área de Moagem) operava com relé SIMOCODE modelo Pro C, já obsoleto. O dispositivo apresentou falha e deixou de conectar-se à rede, comprometendo o monitoramento e a proteção do motor. Para restabelecer a operação, era necessária intervenção manual (diagnóstico, download/upload do programa e reparametrização de sobrecarga e nó de rede), com tempo médio de 3 horas de parada por evento. Não havia gaveta-reserva pré-montada disponível para substituição rápida, o que prolongava a indisponibilidade e expunha o circuito de Moagem a paradas inoportunas.', N'01 - Imagens/02 - Depois/11443.jpeg', N'A gaveta do alimentador 2251 AL-01 (Alimentador de bolas dos moinhos MO-02 e MO-03, área de Moagem) passou a operar com relé SIMOCODE modelo Pro V, atual e com suporte de fabricante. Como ação imediata, foi realizado o download do programa de uma gaveta disponível e o upload no SIMOCODE do AL-01, com configuração dos parâmetros de sobrecarga e nó de rede, normalizando a conexão de rede do dispositivo. Na sequência, foi disponibilizada uma gaveta-reserva pré-montada com SIMOCODE Pro V, permitindo a substituição rápida (plug-in) em caso de nova falha. Com isso, eliminou-se a necessidade de reconexão manual de 3 horas, reduzindo o tempo de parada (MTTR) e mitigando o lucro cessante de R$ 804.262,35 por evento.', NULL, N'A ação implementada atendeu ao objetivo proposto de mitigar as paradas inoportunas associadas às falhas dos relés SIMOCODE Pro C obsoletos. O alimentador 2251 AL-01 passou a operar com um relé SIMOCODE Pro V, modelo atual e suportado pelo fabricante, eliminando a condição de vulnerabilidade causada pelas recorrentes perdas de comunicação observadas no equipamento anterior.
INSERT INTO #PVC VALUES (11444, N'81026607', N'81026607', N'Adequação da Rotina de Entrega de Materiais', 1, N'No Replication/Sem replicação', N'A entrega de materiais do armazém para a área de preparação apresenta atrasos e falta de padronização no processo, causando indisponibilidade de materiais no momento da preparação dos recursos para manutenção. Essa situação gera retrabalho, aumento de deslocamentos, perda de produtividade e impacto no cumprimento da programação das atividades planejadas.
INSERT INTO #PVC VALUES (11445, N'81031846', N'1014409', N'Reduction in Monthly Subscription', 1, N'Others/Outros', N'Monthly subscription cost for OPAS app was $9,500 which was based on full/larger role out. However, Vale not receiving full benefit because OPAS software is still dependent on the ongoing testing being conducted by Vale to determine which device will be used for U/G communication at Voisey''s Bay.', N'Reduce Monthly Subscription Cost', N'10026', N'01 - Imagens/01 - Antes/11445.jpeg', N'OPAS monthly subscription was $9,500. Vale not receiving full benefit. Software dependent on the ongoing testing being conducted by Vale to determine which device will be used for U/G communication at Voisey''s. ', N'01 - Imagens/02 - Depois/11445.jpeg', N'Vendor agreed to lower monthly fee to $2,850 per month while maintaining current level of service for approximately 12 months or until Vale confirms path forward, whichever comes first.  ', NULL, N'Goal of reducing monthly rate was achieved. Rate reduced by $6,650 per month.', N'Challenge rates when the intended service is not being provided even if it is at no fault of the vendor.', 79800, 3, N'.', '2026-05-01T00:00:00.000', '2026-07-29T14:18:56.000', N'81031846', NULL, NULL);
INSERT INTO #PVC VALUES (11446, N'81046916', N'81046916', N'Garantias de curvas 24 x 45° Raio 5D ', 1, N'Concentration/Concentração', N'Após a aquisição de curvas com a empresa Del Rey Minerals, foi observada que as curvas entregues apresentaram descolamento da estrutura de borracha em relação a sua estrutura metálica. Sendo assim, no decorrer do ano de 2026 foram solicitadas as garantias das duas curvas relacionadas a Linha 4 que alimenta o moinho MO-2014-12.', N'Redução de custo com novas aquisições e aumento da confiabilidade da linha 4', N'10293', N'01 - Imagens/01 - Antes/11446.jpeg', N'Conforme é apresentado na figura, tivemos o rompimento da curva e a paralização da linha 4 de SLB 2 para troca do componente. As avarias esse ano totalizaram 42 horas.
INSERT INTO #PVC VALUES (11447, N'124132', N'124132', N'Shipping floor damaged in multiple areas', 1, N'Refining/Refino', N'The floor in building #6 had some damage that required repairs. Causing issues with our forklifts being bounce around.', N'Repair floor', N'10255', N'01 - Imagens/01 - Antes/11447.jpeg', N'The floor area in shipping building #6 was in need of repairs.', N'01 - Imagens/02 - Depois/11447.jpeg', N'The floor area in building #6 has been repaired.', NULL, N'Forklift hitting these holes in the floor causes issues.', N'Floor needed repairs', 0, NULL, N'.', '2026-07-27T00:00:00.000', '2026-07-29T14:26:38.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11448, N'124132', N'124132', N'2-ton scale requires bracing', 1, N'Refining/Refino', N'We had some load cells on the 2-ton scale damaged.', N'Install bracing on the 2-ton scale to eliminate load cell damage', N'10255', N'01 - Imagens/01 - Antes/11448.jpeg', N'We had some load cells damaged on the 2-ton scale by our forklifts moving the scale.', N'01 - Imagens/02 - Depois/11448.jpeg', N'We installed braces to keep the stand from moving.', NULL, N'Load cells will not get damaged by the forklift moving the stand.', N'New braces will help keep the stand in place', 0, NULL, N'.', '2026-07-28T00:00:00.000', '2026-07-29T14:32:37.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11449, N'81013897', N'81013712', N'Crusher Duct Cleaning', 1, N'Crusher/Britadeira', N'Limited vent flow in crusher dust collector due to build up of dust. Considering replacement of all ducting.', N'Improve vent flow in crusher dust collector venting', N'10345', N'01 - Imagens/01 - Antes/11449.jpeg', N'Vent ducting choked due to accumulation of dust.', N'01 - Imagens/02 - Depois/11449.jpeg', N'Cut holes in ducting to allow vacuuming of the duct rather than pulling it all down and replacing.', NULL, N'Problem solved without need to replace all ducting.', N'Dust was able to be vacuumed out safely without need to replace all ducting', 44000, 3, N'Tempo reduzido e confiabilidade nos resultados.', '2026-07-10T00:00:00.000', '2026-07-29T14:33:25.000', N'81013897', NULL, NULL);
INSERT INTO #PVC VALUES (11450, N'81056094', N'81056094', N'Voisey''s Bay Contractor Onboarding Process Guide', NULL, N'Others/Outros', N'Contractor onboarding information was not documented in a centralized, standardized format.', N'Standardize the contractor onboarding process and improve clarity for all stakeholders.', N'10100', N'01 - Imagens/01 - Antes/11450.jpeg', N'Knowledge was dispersed among team members, creating inconsistency and onboarding delays.', N'01 - Imagens/02 - Depois/11450.jpeg', N'Created a comprehensive onboarding guide outlining roles, steps, requirements, and responsibilities. Standardized onboarding activities and provided a single source of truth for the process.', NULL, N'The guide centralized onboarding information and standardized contractor onboarding activities.', N'Clear documentation reduces confusion, improves consistency, and supports knowledge transfer.', 0, NULL, N'performance, produtividade, saúde e segurança, tempo;
INSERT INTO #PVC VALUES (11451, N'81046654', N'81046654', N'Planilha projeção de custo Carga e Carregamento', 1, N'Others/Outros', N'Ausência de informações completas na planilha de custos comprometia a precisão das previsões de gastos, podendo resultar em desvios orçamentários e na necessidade de recursos adicionais não planejados.', N'Controle de custo das ordens mensal D+30 e D+90', N'10234', N'01 - Imagens/01 - Antes/11451.jpeg', N'Alguns campos da planilha de custos apresentavam informações incompletas, comprometendo a precisão das projeções financeiras. Essa situação poderia resultar em custos não previstos, desvios orçamentários e dificuldades no planejamento adequado das ordens.', N'01 - Imagens/02 - Depois/11451.jpeg', N'Foi desenvolvida uma planilha consolidada contendo todas as informações necessárias para tornar as previsões de custos mais assertivas. Foram centralizados em um único local dados como empenhos, kit delivery, ordens solicitadas de períodos anteriores, ordens canceladas e o planejamento previsto. Essa consolidação proporcionou maior visibilidade dos custos, melhor controle orçamentário e redução do risco de gastos acima do valor orçado', NULL, N'Sim', N'Ganho de Tempo na alimentação da planilha', 0, NULL, N'MOVIMENTAÇÃO MAIS FÁCIL E LEVE E VISUALIZAÇÃO DE LIMITE PARA QUANTIDADE CORRETO DENTRO DOS TAMBORES.', '2026-07-08T00:00:00.000', '2026-07-29T14:51:09.000', N'81046654', NULL, NULL);
INSERT INTO #PVC VALUES (11452, N'81056094', N'81056094', N'SharePoint Site Request Process Guide', NULL, N'Others/Outros', N'Users lacked documented guidance for requesting SharePoint sites and relied on IT for assistance.', N'Provide clear instructions for requesting SharePoint sites and reduce user confusion.', N'10100', N'01 - Imagens/01 - Antes/11452.jpeg', N'No centralized instructions existed, resulting in repeated support requests and delays.', N'01 - Imagens/02 - Depois/11452.jpeg', N'Created a guide outlining the SharePoint site request process, requirements, and key information. Standardized the request process and provided a consistent self-service resource.', NULL, N'The guide centralized request information and reduced dependency on EUC support.', N'Clear documentation reduces support effort and improves the user experience.', 0, NULL, N'Evitou possível vazamento e contaminação do solo e perda de material.', '2026-06-23T00:00:00.000', '2026-07-29T14:59:08.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11453, N'483375', N'483375', N'Aplicativo Busca ART', 2, N'Others/Outros', N'As ART''s ficam disponíveis no BI da Segurança, mas para ter acessar essas informações é necessário ter acesso a rede VALE bem como ao Power Apps, é um processo que pode demorar e não é muito intuitivo, o projeto consolida essa informações em um APP que roda de foram Offline, permitindo que executantes, operadores, planejadores e inspetores tenham acesso fácil e rápido a todas as ART''s disponíveis.', N'Facilitar o acesso as ART''s cadastradas e revisadas', N'10178', N'01 - Imagens/01 - Antes/11453.jpeg', N'O acesso as informações é feita através do BI da Segurança, para tal, é necessário solicitação de acesso a plataforma, ao PoweApps e ter acesso a rede Vale V-DATA. Dificultando o executantes, acessar de forma fácil.
INSERT INTO #PVC VALUES (11454, N'81013885', N'81040973', N'PORTÃO METALICO', 2, N'No Replication/Sem replicação', N'O acesso à plataforma era realizado por uma escada sem sistema de fechamento.', N' reduzindo significativamente o risco de queda e proporcionando maior segurança durante o acesso à plataforma.', N'10362', N'01 - Imagens/01 - Antes/11454.jpeg', N'Durante as atividades de içamento de cargas com guindaste , as áreas de acesso não possuíam isolamento adequado. A restrição de acesso era realizada de forma improvisada, utilizando correntes ou cones de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11454.jpeg', N'Foi projetada, fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'sim.  A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado.', N' proporcionando maior controle de acesso.', 0, NULL, N'Com a aplicação da chave seccionadora 6214410, alcançamos a meta estabelecida de melhoria operacional e redução de custos. A solução proporcionou maior facilidade nas manobras de ligação e desligamento, aumentando a segurança e a agilidade das intervenções.', '2026-07-28T00:00:00.000', '2026-07-29T15:10:12.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11455, N'1008390', N'1008390', N'Agitator in tote for Chemical Trial in cobalt ', 1, N'Others/Outros', N'Tech Services is running a trial for a chemical in cobalt, and the tote was not agitated so chemical was settling in the bottom of the tote and not getting  accurate results', N'agitate tote to stir chemicals that settle out ', N'0', N'01 - Imagens/01 - Antes/11455.jpeg', N'Tech Services is running a trial for a chemical in cobalt, and the tote was not agitated so chemical was settling in the bottom of the tote and not getting  accurate results', N'01 - Imagens/02 - Depois/11455.jpeg', N'solution to this issue was to put a small pneumatic  mixer/agitator in the tote to help mix the chemicals and get accurate results during the trial. in order for the mixer to fit we had to make up a little platform on top of the tote to keep the mixer off the bottom. ', NULL, N'Yes Problem was solved mixer is now in tote and mixing the solution for dosing ', N'proper mixing of certain chemicals is needed during dosing ', 0, NULL, N'Melhoria no tempo de manutenção e na ergonomia durante execução da atividade', '2026-07-28T00:00:00.000', '2026-07-29T15:15:15.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11456, N'81013885', N'81040973', N'PORTÃO DE ACESSO PENEIRA', 2, N'Others/Outros', N'Durante as atividades de içamento de cargas com ponte rolante na área das peneiras não tinha o portão de controle de acesso de pessoas. ', N'portão de controle de acesso de pessoas na área das peneiras.', N'10362', N'01 - Imagens/01 - Antes/11456.jpeg', N'Durante as atividades de içamento de cargas com ponte rolante na área das peneiras não tinha o portão de controle de acesso de pessoas. ', N'01 - Imagens/02 - Depois/11456.jpeg', N'Fabricada e instalada uma cancela metálica de segurança nos pontos de acesso  içamento da ponte rolante. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'SIM.A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado.', N'aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', 0, NULL, N'Resultado esperado alcançado', '2026-07-28T00:00:00.000', '2026-07-29T15:23:55.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11457, N'517429', N'517429', N'Automação da Validação de massas dos Pontos de Controle no GPV', 1, N'No Replication/Sem replicação', N'O processo de validação dos apontamentos de movimentação de massa era realizado manualmente nos pontos de controle do GPV. Esses pontos geram aproximadamente 48.993 movimentos por mês, exigindo um elevado volume de conferências e validações operacionais, aumentava a carga operacional da Sala de Controle e tornava o processo suscetível a atrasos, especialmente durante o fechamento mensal', N'Automatizar o processo de validação dos pontos de controle de movimentação de massa, eliminando atividades manuais de baixo valor agregado, reduzindo o tempo dedicado às validações, minimizar riscos de erros operacionais, aumentar a confiabilidade das informações e contribuir para um fechamento mensal mais ágil e dentro dos prazos estabelecidos.', N'10229', N'01 - Imagens/01 - Antes/11457.jpeg', N'Validação manual de aproximadamente 48.993 registros mensais de movimentação de massa, gerados através do pontos de controle, demandava elevado esforço operacional gerando sobrecarga, risco de atrasos no fechamento mensal e utilização de recursos em atividades repetitivas de baixo valor agregado.
INSERT INTO #PVC VALUES (11458, N'81013885', N'81040973', N'CANCELA DE SEGURANÇA', 2, N'Others/Outros', N'Ao acessar o equipamento 2251 BP 02 não tinha uma cancela de segurança.', N', garantindo a continuidade da proteção coletiva.', N'10362', N'01 - Imagens/01 - Antes/11458.jpeg', N' A restrição de acesso a bomba  era realizada de forma improvisada, utilizando de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11458.jpeg', N' Instalada uma cancela metálica de segurança nos pontos de acesso a bomba. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para acessa a bomba.', NULL, N'SIM. aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para acessa a bomba.', N' A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado', 0, NULL, N'Foi fabricado um suporte para melhorar o processo', '2026-07-27T00:00:00.000', '2026-07-29T15:53:46.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11459, N'517429', N'517429', N'Padronização de Apontamentos GPV– Corte Grosseiro na Ciclonagem', 1, N'No Replication/Sem replicação', N'Os apontamentos de paradas relacionados ao corte grosseiro na ciclonagem vinham sendo registrados de forma não padronizada, utilizando diferentes classificações de falha para uma mesma condição operacional, como Entupimento, Inspeção Operacional, Nível Alto, entre outras.
INSERT INTO #PVC VALUES (11460, N'81013885', N'81016951', N'SUPORTE DE CAIXA', 2, N'Others/Outros', N'AGUA EM LOCAL INADEQUADO .', N'MELHORA A AREA DE TRABALHO .', N'10362', N'01 - Imagens/01 - Antes/11460.jpeg', N'A caixa térmica para armazenamento de água potável permanecia apoiada diretamente sobre o piso, dificultando o acesso dos colaboradores, a higienização do local e a organização do ambiente. As embalagens de água também eram armazenadas no chão, ficando suscetíveis ao contato com umidade, sujeira e impactos, comprometendo as boas práticas de organização e conservação.', N'01 - Imagens/02 - Depois/11460.jpeg', N'Foi fabricado e instalado um suporte metálico para elevação da caixa térmica, proporcionando melhor ergonomia durante a utilização, facilitando a limpeza da área e eliminando o contato direto com o piso. O projeto também contemplou um suporte lateral para armazenamento das embalagens de água, mantendo-as organizadas, protegidas e de fácil acesso, contribuindo para a melhoria das condições de trabalho, organização do ambiente e padronização conforme as práticas de segurança e 5S.', NULL, N'SIM.O projeto também contemplou um suporte lateral para armazenamento das embalagens de água, mantendo-as organizadas, protegidas e de fácil acesso, contribuindo para a melhoria das condições de trabalho.', N'Foi fabricado e instalado um suporte metálico para elevação da caixa térmica, proporcionando melhor ergonomia durante a utilização, facilitando a limpeza da área e eliminando o contato direto com o piso.', 0, NULL, N'Foi colocado suporte', '2026-07-28T00:00:00.000', '2026-07-29T16:17:30.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11461, N'81013885', N'81012464', N'PORTAO DE ACESSO', 2, N'Others/Outros', N'Durante as operações de içamento, os colaboradores permaneciam expostos ao risco de queda, devido à ausência de uma barreira física que garantisse a continuidade da proteção coletiva.', N'fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento.', N'10362', N'01 - Imagens/01 - Antes/11461.jpeg', N'Durante as atividades de içamento de cargas com ponte rolante, as áreas de acesso não possuíam isolamento adequado. A restrição de acesso era realizada de forma improvisada, utilizando correntes ou cones de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11461.jpeg', N'Foi projetada, fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'SIM. proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', N'proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança.', 0, NULL, N'Mas agilidade e mas segurança', '2026-07-28T00:00:00.000', '2026-07-29T16:22:42.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11462, N'540335', N'540335', N'Relatório D-1', 1, N'Others/Outros', N'Relatório D-1 e S-1 não confiável, apresentando divergências de dados em comparação com o SAP.', N'Tornar confiável e ', N'#N/A', N'01 - Imagens/01 - Antes/11462.jpeg', N'Foi criado um relatório de acompanhamento D-1 e S-1, alimentado por dados provenientes do BW. Entretanto, as informações apresentavam baixa confiabilidade, pois a carga de dados não ocorria diariamente, resultando em divergências entre os dados exibidos no relatório e as informações registradas no sistema SAP.', N'01 - Imagens/02 - Depois/11462.jpeg', N'Foi desenvolvido um relatório cujos dados são extraídos diretamente do sistema SAP. As informações são atualizadas diariamente, garantindo maior confiabilidade e evitando inconsistências nos dados e nos resultados apresentados.', NULL, N'O relatório anterior frequentemente apresentava informações desatualizadas devido a falhas no sistema BW, o que demandava tempo para investigação, análise e correção dos problemas. Com a extração dos dados sendo realizada diretamente do sistema SAP, o relatório passou a ter maior confiabilidade, garantindo informações atualizadas e eliminando a necessidade de esforços recorrentes para resolver inconsistências, permitindo maior foco nas atividades de negócio.', N'A melhoria dos processos torna o tempo mais produtivo e proveitoso.', 0, NULL, N'melhora a identificação e o tempo  de produção .', '2026-07-01T00:00:00.000', '2026-07-29T16:22:49.000', N'540335', NULL, NULL);
INSERT INTO #PVC VALUES (11463, N'81042078', N'81023761', N'Implantação de Estacionamento Dedicado na Área do Carvão Mineral para Otimização da Mobilidade e Segurança Operacional', 1, N'Others/Outros', N'Atualmente, os veículos utilizados pelos colaboradores não possuem um local exclusivo para estacionamento na área do Carvão Mineral. Essa condição provoca estacionamento em locais inadequados, aumento da circulação de veículos próximos às operações, conflitos entre equipamentos móveis e veículos leves, dificuldades de acesso e maior exposição dos colaboradores aos riscos operacionais.
INSERT INTO #PVC VALUES (11464, N'81008764', N'81007797', N'PESO ADEQUADO  E ERGONOMIA DA TAREFA', 2, N'Others/Outros', N'TAMBORES ESTAVAM FICANDO COM LIMITE ACIMA DO PERMITIDO E ASSIM FICANDO MUITO PESADO, PARA MANUSEAR, E INVIÁVEL ERGONOMICAMENTE PODENDO CAUSAR LESÕES NO COLABORADOR, NA HORA DA MOVIMENTAÇÃO PARA O DESCARTE.', N'ELIMNINAR O EXCESSO DE PESO', N'10129', N'01 - Imagens/01 - Antes/11464.jpeg', N'Os tambores utilizados para descarte não possuíam identificação visual indicando o limite máximo de preenchimento. Com isso, frequentemente eram acondicionados com volume e peso acima do recomendado, tornando a movimentação difícil, ergonomicamente inadequada e aumentando o risco de lesões aos colaboradores durante o transporte para descarte.', N'01 - Imagens/02 - Depois/11464.jpeg', N'Foi implementada a identificação visual do limite máximo de preenchimento dos tambores, orientando os colaboradores quanto à quantidade adequada de material a ser depositada. A ação permitiu o controle do peso dos recipientes, tornando o manuseio e a movimentação mais seguros e ergonômicos, reduzindo o esforço físico e o risco de lesões ocupacionais.', NULL, N'EXCESSO DE PESO E FALTA DE IDENTIFICAÇÃO DE NÍVEL DENTRO DOS TAMBORES, AGORA COM PLACA VISÍVEL E MELHORIA NA ERGONOMIA E MOVIMENTAÇÃO.', N'RESPEITO AS REGRAS E ORIENTAÇÕES DE SEGURANÇA E TRABALHO', 0, NULL, N'O problema foi resolvido por meio da implantação de suporte para acondicionamento das mangueiras em 100% das propulsoras de graxa. A melhoria reduziu o esforço ergonômico durante o manuseio, melhorou a organização dos equipamentos e contribuiu para a realização das atividades de abastecimento e lubrificação de forma mais segura e eficiente.', '2026-07-28T00:00:00.000', '2026-07-29T17:48:17.000', N'81008764', NULL, NULL);
INSERT INTO #PVC VALUES (11465, N'81046537', N'81046759', N'MONTAGEM DE ESTRUTURA PARA SUSTENTAÇÃO', 1, N'Others/Outros', N'As mangueiras do sistema central de fluxo do mastro estavam sofrendo forte atrito.', N'EVITAR ATRITO ENTRE TUBOS', N'10150', N'01 - Imagens/01 - Antes/11465.jpeg', N'Os tubos do sistema central de fluxo de óleo do mastro estavam tendo um grande atrito entre si, resultando em desgaste, podendo acarretar vazamentos e perda de material. ', N'01 - Imagens/02 - Depois/11465.jpeg', N'Providenciado suporte e abraçadeiras plásticas para montagem de estrutura para sustentação do tubo de alimentação dos motores de rotação do cabeçote rotativo, devido à atrito entre tubos, o que poderia ocasionar danos e posteriormente vazamento hidráulico.', NULL, N'SIM, NÃO HOUVE MAIS ATRITOS. ', N'Observação do maquinário ', 0, NULL, N'Garantimos o nível máximo de funcionalidade do sistema anticolisão CAS na operação dos caminhões fora de estrada CAT.', '2026-07-17T00:00:00.000', '2026-07-29T17:50:21.000', N'81046537', NULL, NULL);
INSERT INTO #PVC VALUES (11466, N'81008764', N'81007797', N'ORGANIZAÇÃO DO ARQUIVO DE AMOSTRAS COMPOSTAS', 3, N'Others/Outros', N'FALTA DE ORGANIZAÇÃO E DIFICULDADE DE ENCONTRAR AS AMOSTRAS COMPOSTAS.', N'MANTER ORGANIZADO O ARQUIVO', N'10129', N'01 - Imagens/01 - Antes/11466.jpeg', N'As amostras de USINA e PFE não possuíam identificação padronizada para armazenamento, ficando distribuídas de forma desorganizada no arquivo. A ausência de placas de identificação e de locais definidos dificultava a localização das amostras, aumentava o tempo de busca e elevava o risco de armazenamento incorreto.', N'01 - Imagens/02 - Depois/11466.jpeg', N'Foram implantadas placas de identificação e definida uma padronização para o armazenamento das amostras em caixas específicas e em locais previamente determinados. Com a melhoria, as amostras passaram a ser acondicionadas de forma organizada, facilitando a localização, o controle e a rastreabilidade, além de otimizar o espaço do arquivo.', NULL, N'SIM, TIVEMOS UMA PADRONIZAÇÃO DE ORGANIZAÇÃO NO ARQUIVO DE AMOSTRAS E FACILIDADE NA HORA DA PROCURA DENTRO DO ARQUIVO.', N'ORGANIZAÇÃO E RASTREABILIDADE', 0, NULL, NULL, '2026-07-24T00:00:00.000', '2026-07-29T18:26:54.000', N'81008764', NULL, NULL);
INSERT INTO #PVC VALUES (11467, N'500473', N'500473', N'chave seccionadora', 2, N'Others/Outros', N'dificuldade de ligar e desligar a chave geral.', N'Facilita o ligação da chave seccionadora geral', N'10034', N'01 - Imagens/01 - Antes/11467.jpeg', N'chave seccionadora geral 7N-0718, o seccionamento da energia é através da chave 8H5306, que liga e desliga a chave de bloqueio. Durante a tentativa de manobra da chave seccionadora geral 7N-0718, foi constatada dificuldade para realização do fechamento (ligação), exigindo esforço acima do normal no mecanismo de acionamento. ', N'01 - Imagens/02 - Depois/11467.jpeg', N'A chave seccionadora 621-4410 apresenta facilidade de manobra, permitindo operações de ligação e desligamento de forma simples, rápida e segura. Seu mecanismo proporciona acionamento suave, reduzindo o esforço do operador e contribuindo para maior eficiência e confiabilidade nas atividades de operação e manutenção.', NULL, N'sim, a chave seccionadora 6214410 possui acionamento leve e de fácil operação, facilitando as manobras de ligar e desligar com segurança e praticidade.', N'identificamos que a adoção de soluções que simplificam a operação e a manutenção contribui diretamente para o alcance das metas, a redução de custos e o aumento da confiabilidade do processo.', 334, 1, N'Trip hazard removed', '2026-07-24T00:00:00.000', '2026-07-29T23:39:43.000', N'500473', NULL, NULL);
INSERT INTO #PVC VALUES (11468, N'81042217', N'81055015', N'Implantação de janela de acesso para manutenção da caixa de ligação do motor da unidade hidráulica', 1, N'Others/Outros', N'A caixa de ligação do motor da unidade hidráulica não possuía acesso direto para inspeções e manutenções. As atividades eram executadas por cima da estrutura, exigindo posições inadequadas de trabalho, maior esforço físico e dificuldade de alcance dos componentes, aumentando o tempo de intervenção e a exposição a riscos ergonômicos.
INSERT INTO #PVC VALUES (11469, N'81010025', N'81010025', N'Relatório automatizado Horímetros x Tag x Modelo x Série', 1, N'Others/Outros', N'Demora para consulta de informações referente a Horímetros, Tag, Modelo e Série dos equipamentos de mina', N'Reduzir tempo de consulta', N'10081', N'01 - Imagens/01 - Antes/11469.jpeg', N'Não havia Dashboard para consulta rápida de horímetros, tag, modelo e série de equipamentos de mina', N'01 - Imagens/02 - Depois/11469.jpeg', N'Elaborado relatório automatizado (Dashboard) no Power Bi como fonte de consulta rápida para horímetro x Tag x Modelo x Série.', NULL, N'Reduzido tempo para pesquisa e consulta. Meta alcançada', N'Inovação', 0, NULL, N'Redução do tempo de limpeza dos tornos, aumento da segurança dos operadores por meio da eliminação do contato direto com a limalha e melhoria da organização e produtividade da área de usinagem.', '2026-07-30T00:00:00.000', '2026-07-30T08:35:22.000', N'81010025', NULL, NULL);
INSERT INTO #PVC VALUES (11470, N'81006946', N'81006946', N'SUPORTE DE CILINDROS', 3, N'Others/Outros', N'Atualmente, a área não dispõe de um suporte adequado para a armazenagem de cilindros. Como consequência, os cilindros permanecem diretamente no chão, sem um padrão definido de organização, dificuldade de identificação, movimentação inadequada e comprometimento da segurança e da organização do ambiente de trabalho.', N'Eliminar o armazenamento de cilindros diretamente no chão.', N'10139', N'01 - Imagens/01 - Antes/11470.jpeg', N'Durante a análise do problema, identificou-se que a ausência de um suporte adequado está relacionada à falta de estrutura específica para armazenamento e à inexistência de um padrão definido para alocação dos cilindros. Também foi observado que a limitação de espaço e a ausência de planejamento da área contribuíram para a situação atual.', N'01 - Imagens/02 - Depois/11470.jpeg', N'Com a implantação do suporte, espera-se obter um ambiente mais seguro e organizado, com todos os cilindros armazenados corretamente, redução dos riscos de acidentes, maior facilidade de acesso e movimentação, melhoria no padrão visual da área e atendimento às práticas e requisitos de segurança.', NULL, N'Sim! se mantermos a organização e o padrão.', N'Com a padronização, a área ficou mais segura.', 0, NULL, NULL, '2026-07-29T00:00:00.000', '2026-07-30T09:40:15.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11471, N'81022747', N'540124', N'suporte e  instalado caixa de aferição', NULL, N'Others/Outros', N'não tinha um suporte para colocar a caixa de distribuição dê aferimento dos olhos.', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11471.jpeg', N'Antes não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'01 - Imagens/02 - Depois/11471.jpeg', N'Foi fabricado um suporte', NULL, N'Não tinha nenhum tipo de segurança', N'SEGURANÇA', 0, NULL, N'Com a instalação da fita de isolamento retrátil e redefinição da área, foi possível ampliar efetivamente o espaço de manobra, proporcionando maior segurança, melhor fluidez operacional e redução das manobras corretivas, atendendo à meta de melhorar a circulação da empilhadeira sem necessidade de investimento em infraestrutura.', '2026-07-29T00:00:00.000', '2026-07-30T10:11:52.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11472, N'1014349', N'1014349', N'Capital Spot POs', 1, N'Others/Outros', N'There is a lack of visibility on the status of Spot POs when requisitions are sent to Wipro because local procurement does not issue spot POs. ', N'Increase visability on status of spot PO creation', N'0', N'01 - Imagens/01 - Antes/11472.jpeg', N'Spot requisitions are entered for Long Harbour Capital Projects and are sent to Wipro, not local procurement, for negotiation and award. There is a lack of visibility on the status and potential issues associated with these Spot orders. ', N'01 - Imagens/02 - Depois/11472.jpeg', N'Weekly touchpoint scheduled with LH Capital Proj Super, LH Procurement Super, Contracts Analyst & Wipro
INSERT INTO #PVC VALUES (11473, N'81022747', N'540124', N'Confeccionado suporte e  instalado caixa de aferição', NULL, N'Others/Outros', N'não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11473.jpeg', N'Antes não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'01 - Imagens/02 - Depois/11473.jpeg', N'Foi fabricado um suporte', NULL, N'Sem suporte para aferir', N'Mas suporte para segurança', 0, NULL, N'AGILIDADE E PRECISÃO COM MENOS ERRO NA BUSCA DE MATERIAIS NO ARMAZÉM PARA CONTROLARMOS O HISTÓRICO DE RETIRADA.', '2026-07-29T00:00:00.000', '2026-07-30T10:19:32.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11474, N'81022747', N'540124', N'engate de melhoria de abastecimento', NULL, N'Others/Outros', N'havia nessa cidade de 2 pessoas para completar o óleo e perdíamos muito tempo', N'Agilidade e segurança', N'10144', N'01 - Imagens/01 - Antes/11474.jpeg', N'Antes havia nessa cidade de 2 pessoas para completar o óleo e perdíamos muito tempo', N'01 - Imagens/02 - Depois/11474.jpeg', N'Foi instalado engate rápido no suporte do óleo do martelo e do óleo do hidráulico necessitamos se agora de uma pessoa. Tendo um ganho de 15 minutos', NULL, N'Antes a atividade tomava um tempo maior e com pouca segurança', N'Agilidade do processo', 0, NULL, N'O processo, que anteriormente exigia a leitura de diversos e-mails para localizar informações específicas, passou a ser realizado em poucos segundos por meio da planilha consolidada. Essa melhoria reduziu significativamente o tempo de consulta, atualização e compartilhamento das informações, proporcionando maior produtividade, organização e confiabilidade dos dados.', '2026-07-29T00:00:00.000', '2026-07-30T10:28:46.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11475, N'81006512', N'128215', N'patio Componentes ', 3, N'No Replication/Sem replicação', N'Na área de subconjunto de preparação de material dos componentes , não tinha identificação e organização por processo de prioridade e serviços ', N'Organização ', N'10081', N'01 - Imagens/01 - Antes/11475.jpeg', N'Dificuldade em identifica material para serviços da semana.
INSERT INTO #PVC VALUES (11476, N'538725', N'538725', N'Abrigo para os extintores de carretilha', 1, N'No Replication/Sem replicação', N'Os extintores de carretilha encontram-se expostos às condições climáticas, como chuva, sol e poeira, ocasionando desgaste prematuro, corrosão e necessidade de manutenções frequentes. A ausência de proteção adequada pode comprometer a conservação e a disponibilidade dos equipamentos em situações de emergência.', N'Melhorar a durabilidade e conservação dos extintores de carretilha, reduzindo a exposição às intempéries e aumentando a vida útil dos equipamentos.', N'10079', N'01 - Imagens/01 - Antes/11476.jpeg', N'O extintor de carretilha encontra-se instalado em área externa, sem proteção adequada contra sol, chuva e poeira. Essa condição tem contribuído para o desgaste prematuro da pintura, componentes e etiquetas de identificação, dificultando a inspeção visual e aumentando a necessidade de manutenção. Além disso, a exposição contínua às intempéries pode comprometer a conservação e a vida útil do equipamento, impactando sua confiabilidade em situações de emergência.', N'01 - Imagens/02 - Depois/11476.jpeg', N'Foi desenvolvido e instalado um abrigo metálico para os extintores de carretilha, garantindo proteção contra chuva, sol e poeira. A melhoria padronizou o acondicionamento dos equipamentos nas áreas externas, proporcionando maior conservação e facilitando as inspeções periódicas.
INSERT INTO #PVC VALUES (11477, N'486546', N'535629', N'Melhoria da Ergonomia e Organização no Processo de Lubrificação dos Comboios', 2, N'Others/Outros', N'A ausência de um sistema adequado de acondicionamento para as mangueiras das propulsoras de graxa gerava dificuldades operacionais, aumento do esforço ergonômico durante o manuseio dos equipamentos, desorganização da área e potencial risco de danos às mangueiras e conexões.
INSERT INTO #PVC VALUES (11478, N'81014137', N'81014137', N'POKA YOKE DOS GIGANTES DA MINERAÇÃO', 2, N'Others/Outros', N'Ausência de confiabilidade no teste de 2ª Etapa no retorno de manutenção no cambio de marchar dos caminhões.(Checklist operacional) ', N'Reporte de Falhas Critica.', N'10245', N'01 - Imagens/01 - Antes/11478.jpeg', N'A Verificação de Status funcional do decodificador de marcha no sistema embarcado anticolisão CAS era feita através de checklist manual pelo operador do equipamento, porém a falta de disciplina ou conhecimento da criticidade desta tarefa não garantia o eficácia desse fluxo, e identificamos vários casos na manutenção preventiva em que o Decodificador de marcha estava desligado do ponto de sensoriamento. 
INSERT INTO #PVC VALUES (11479, N'460522', N'81016737', N'Shutdonw - consumable gas detection supplies', 1, N'Projects/Projetos', N'HSR has an existing inventory of consumable gas detection supplies, including tubing, that remains unused following previous outages. Without a process to identify and utilize these available materials, operating areas may unnecessarily purchase new supplies for planned outages, resulting in avoidable costs, excess inventory, and increased waste', N'Utilization of existing gas detection supplies will reduce unnecessary purchasing, lower inventory carrying costs, minimize waste, and generate measurable cost savings for the September outage.', N'0', N'01 - Imagens/01 - Antes/11479.jpeg', N'HSR has an existing inventory of consumable gas detection supplies, including tubing, that remains unused following previous outages. Without a process to identify and utilize these available materials, operating areas may unnecessarily purchase new supplies for planned outages, resulting in avoidable costs, excess inventory, and increased waste. An opportunity exists to optimize inventory management by using existing stock before procuring new materials, thereby reducing costs and improving resource utilization.', N'01 - Imagens/02 - Depois/11479.jpeg', N'An opportunity exists to optimize inventory management by using existing stock before procuring new materials, thereby reducing costs and improving resource utilization.', N'https://globalvale.sharepoint.com/teams/basemetals', N'Utilization of existing gas detection supplies will reduce unnecessary purchasing, lower inventory carrying costs, minimize waste, and generate measurable cost savings for the September outage.', N'inventory control', 1200, 3, N'Estávamos “reféns” dos fabricantes para compra dos componentes homologados, custo mais alto, logística dupla e tempo de entrega maior.
INSERT INTO #PVC VALUES (11480, N'1010861', N'1010861', N'222 Sump Line Re-routing', 3, N'Others/Outros', N'Sump lined in 222 routed across travel ways causing tripping hazards and damage to chem hoses.', N'Re-route lie to remove from travel routes.', N'0', N'01 - Imagens/01 - Antes/11480.jpeg', N'2" chem hoses ran across building floors to move sump liquids. These lines would get ran over by forklifts as well as cause potential tripping hazards. ', N'01 - Imagens/02 - Depois/11480.jpeg', N'Sump lines were re-routed using existing lines and chem hose to create new flow paths for sump liquids. By doing this the hoses could be removed from main travel areas and rerouted. ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Hoses moved', N'Use of existing piping ', 2000, 3, N'Maior aderência ao planejamento, integração entre áreas operacionais, redução de desvios de execução, melhoria da previsibilidade da produção, governança estruturada do sequenciamento e maior alinhamento entre estratégia e operação.', '2026-07-29T00:00:00.000', '2026-07-30T13:28:35.000', N'1010861', NULL, NULL);
INSERT INTO #PVC VALUES (11481, N'202630', N'202630', N'Fee reduction - buyout of vehicles', 1, N'Others/Outros', N'Over the past 3 years we leased 47 vehicles through Hickman''s. Upon review of the buyout and looking for cost reduction i was about to remove the transfer fee of $50 per vehicle', N'Cost reduction', N'10026', N'01 - Imagens/01 - Antes/11481.jpeg', N'Over the past 3 years we leased 47 vehicles through Hickman''s. Upon review of the upcoming buyout and looking for cost reduction i was about to remove the transfer fee of $50 per vehicle', N'01 - Imagens/02 - Depois/11481.jpeg', N'Hickman''s agreed to waive this fee for each vehicle', NULL, N'Hickman''s agreed to waive this $50 fee for each vehicle resulting in an avoidance of $2,350', N'Look at ways to reduce, not a big savings but every dollar counts', 2350, 3, N'Melhoria na aderência dos planos.', '2026-01-13T00:00:00.000', '2026-07-30T13:49:50.000', N'202630', NULL, NULL);
INSERT INTO #PVC VALUES (11482, N'81029873', N'547581', N'Dispositivo Para limpar limalha nos tornos', 3, N'Others/Outros', N'Ausência de um dispositivo específico para remoção de limalha nos tornos, resultando em baixa eficiência na limpeza e redução da disponibilidade operacional dos equipamentos.', N'Desenvolver e implementar um dispositivo para limpeza de limalha nos tornos, visando aumentar a segurança dos operadores, reduzir o tempo de limpeza e melhorar a organização da área de usinagem.', N'10245', N'01 - Imagens/01 - Antes/11482.jpeg', N'Dificuldade na remoção de cavacos presos entre as arestas e a placa do torno, mesmo com o uso de luvas adequadas, aumentando o risco de cortes e lesões durante a limpeza do equipamento.
INSERT INTO #PVC VALUES (11483, N'81052333', N'81014733', N'Carro suporte para transportar tambor', 1, N'Crusher/Britadeira', N'A movimentação manual de tambores gera riscos de lesões ergonômicas, acidentes com queda de carga e derramamento de produtos, comprometendo a segurança dos colaboradores e a eficiência operacional.', N'Segurança e eficiência operacional ', N'10362', N'01 - Imagens/01 - Antes/11483.jpeg', N'A movimentação manual de tambores gera riscos de lesões ergonômicas, acidentes com queda de carga e impactos na segurança dos trabalhadores.', N'01 - Imagens/02 - Depois/11483.jpeg', N'Com a implantação e utilização de carro porta-tambor, reduz o risco de lesões ergonômicas, e proporciona maior estabilidade, controle operacional e executa o transporte seguro dos tambores sem esforços excessivos.
INSERT INTO #PVC VALUES (11484, N'92000679', N'81005006', N'Kaizen Área Livre, Manobra Segura', 2, N'Others/Outros', N'A área de isolamento dependia das grades de isolamento. O que limitava a área de manobra.', N'Ampliação da Área de Manobra Utilizando Apenas Fita Retrátil', N'10234', N'01 - Imagens/01 - Antes/11484.jpeg', N'A área de manobra era limitada pela quantidade de grades de isolamento disponíveis.', N'01 - Imagens/02 - Depois/11484.jpeg', N'Com a fita retrátil, a área de manobra pode ser ajustada conforme a necessidade.', NULL, N'A área disponível para manobra da empilhadeira era insuficiente, dificultando as operações, aumentando o tempo de movimentação e elevando os riscos de contato com estruturas e materiais.', N'Com uma área de manobra mais adequada, diminuíram-se as manobras corretivas, reduzindo riscos de colisões e aumentando a eficiência operacional.', 0, NULL, N'doors open properly now. proper signage for hazards', '2026-07-29T00:00:00.000', '2026-07-30T14:05:22.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (11485, N'81052333', N'472995', N'Spray Controle de Particulados', 2, N'Crusher/Britadeira', N'A geração excessiva de particulados na área operacional tem causado dispersão de poeira no ambiente, a geração excessiva de particulados na área operacional tem causado dispersão de poeira no ambiente,', N'implantação/otimização do sistema de spray', N'10362', N'01 - Imagens/01 - Antes/11485.jpeg', N'Spray de água que serve para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) estava com formato (I) causando obstrução constante nos bicos e com excesso de bicos montado causando desperdício de água.', N'01 - Imagens/02 - Depois/11485.jpeg', N'Foi Instalado novo Spray de água para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) com novo formato (T) eliminando obstrução dos bicos de saída de água .Foi reduzido quantidade de bicos de 6 p/ 4 pra eliminar desperdício de água.', NULL, N'Spray de água que serve para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) estava com formato (I) causando obstrução constante nos bicos e com excesso de bicos montado, causando desperdício de água, foram reduzidos os bicos de 6 para 4 pra eliminar desperdício de água.', N'Melhorias contínuas nos processos operacionais.', 65000, 1, N'less time to disconnect hoses.', '2026-07-28T00:00:00.000', '2026-07-30T14:12:54.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (11486, N'522369', N'92000204', N'CONTROLE DE RESERVAS / PEDIDO ', 1, N'No Replication/Sem replicação', N'DIFICULDADE DE RASTREIO DE MATERIAIS RETIRADOS DO ARMAZÉM PARA ÁREA ELÉTRICA  E KANBAN ELÉTRICA USINAS', N'GARANTIR CONTROLE E EFICIÊNCIA NA BUSCA DE MATERIAIS DA ELÉTRICA.', N'10197', N'01 - Imagens/01 - Antes/11486.jpeg', N'TEMOS DIFICULDADE DE CONTROLE DE DADOS HISTÓRICO DA RETIRADA DO MATERIAIS DO ARMAZÉM PARA ÁREA GERÊNCIA MANUTENÇÃO ELÉTRICA.', N'01 - Imagens/02 - Depois/11486.jpeg', N'FOI DESENVOLVIDO PELA ENGENHARIA UM FORMS VALE DE CONTROLE DE RESERVA / PEDIDO PARA AGILIZAR LEVANTAMENTOS DE DADOS PARA CONSULTA PARA POSSÍVEL RASTREIO.', NULL, N'GANHOS TANGÍVEIS PARA CONTROLE DE RESERVAS  / PEDIDO ATRAVÉS DO DESENVOLVIMENTO DO FORMS PARA MATERIAIS.', N'ADQUIRIMOS HISTÓRICO DE REGISTROS DE CONTROLE DE RESERVAS / PEDIDOS COM EVIDÊNCIAS', 0, NULL, N'Redução do tempo gasto na investigação dos desvios; Maior disponibilidade de informações para análise; Aumento da produtividade das reuniões de OTIF; Melhoria da qualidade e padronização dos dados utilizados pela equipe.', '2026-07-29T00:00:00.000', '2026-07-30T14:45:33.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11487, N'81032641', N'81032641', N'CONTROLE DE ABSENTEÍSMO', 2, N'Others/Outros', N'As informações eram compartilhadas apenas no corpo dos e-mails, o que dificultava a visualização rápida dos dados, o rastreamento dos motivos das ausências e o acompanhamento do histórico do colaborador. Além disso, o formato descentralizado comprometia a agilidade na tomada de decisão e exigia maior tempo para localizar informações específicas.', N'aprimorar a gestão das ausências de colaboradores e tornar o acompanhamento das informações mais eficiente, foi desenvolvida uma planilha padronizada para o controle de absenteísmo da unidade.', N'10017', N'01 - Imagens/01 - Antes/11487.jpeg', N'As informações eram compartilhadas no corpo dos e-mails, que dificultava a visualização rápida dos dados, o rastreamento dos motivos das ausências e o acompanhamento do histórico do colaborador.', N'01 - Imagens/02 - Depois/11487.jpeg', N'Planilha única e estruturada, reunindo informações relevantes em um único local. Ferramenta contempla dados como quantidade de dias, permitindo uma gestão visual organizada e de fácil atualização.', NULL, N'A implementação da planilha trouxe ganhos significativos para a rotina da unidade, dentre eles:
INSERT INTO #PVC VALUES (11488, N'81040231', N'81040231', N'Special waste re-routing', 1, N'No Replication/Sem replicação', N'Vale was incurring significant disposal and transportation costs by shipping certain waste streams through the Clean Harbors system to Quebec and other off-island facilities, while also experiencing operational constraints due to limited Clean Harbors bin availability. Opportunities exist to divert eligible waste streams to local disposal options such as Robin Hood Bay through Vardy''s, reducing transportation costs, freeing up bin inventory, and improving waste handling efficiency', N'Primary driver was avoiding costly transportation of waste to Quebec via Umiak and reducing reliance on limited Clean Harbors bin inventory', N'0', N'01 - Imagens/01 - Antes/11488.jpeg', N'Long Harbour was experiencing limited availability of Clean Harbors waste bins due to lengthy off-island disposal cycles, resulting in operational risk and high transportation costs.', N'01 - Imagens/02 - Depois/11488.jpeg', N'The team identified an opportunity to evaluate whether eligible waste streams could be diverted to local disposal facilities such as Robin Hood Bay through Vardy''s, reducing costs and improving bin availability. Savings of $137.5/ton on disposal and approximately $8000 per bin in transport costs depending on fsc. Assuming 1 bin per month of special waste annual savings would be about $120,000', NULL, N'Yes - Achieved by challenging the existing disposal process and finding a lower-cost local alternative for eligible waste streams.', N'Classify waste correctly and revisit/challenge classifications', 120000, 3, N'Agilidade ', '2026-01-01T00:00:00.000', '2026-07-30T15:29:31.000', N'81040231', NULL, NULL);
INSERT INTO #PVC VALUES (11489, N'81060533', N'81060533', N'SUPORTE ORGANIZADOR DE MATERIAIS', 3, N'Others/Outros', N'Os materiais permaneciam armazenados de forma inadequada, ocupando espaço, dificultando o acesso pelos colaboradores e comprometendo a organização do ambiente. Além disso, não havia um local padronizado para acondicionamento desses itens, o que gerava desperdícios de tempo durante a rotina e prejudicava a aplicação dos princípios do 5S.', N'fortalecer as práticas de Meio Ambiente e 5S, além de promover maior organização e padronização dos materiais de limpeza, foi desenvolvido um suporte organizador para armazenamento de papel-toalha e Perfex utilizando uma caixa plástica de hortifrúti reaproveitada.', N'10361', N'01 - Imagens/01 - Antes/11489.jpeg', N'Materiais eram armazenados de forma inadequada, ocupando espaço, dificultando o acesso pelos colaboradores e comprometendo a organização do ambiente. ', N'01 - Imagens/02 - Depois/11489.jpeg', N'Reaproveitamento de caixa hortifrúti para suporte organizador, com local adequado, identificado e de fácil acesso para o armazenamento do papel-toalha e Perfex. Reutilização de material que seria descartado, contribuindo para a redução de resíduos.', NULL, N'A implementação do suporte organizador trouxe diversos benefícios para a unidade, entre eles:
INSERT INTO #PVC VALUES (11490, N'81007314', N'81047010', N'Chapa de distanciamento do berço do DHR', 1, N'Others/Outros', N'Paradas em corretivas dos equipamentos da frota por folga na corrente de avanço, quebra de tirantes de tensionamento da corrente e mangueiras sacadas do tambor de mangueiras.
INSERT INTO #PVC VALUES (11491, N'369561', N'369561', N'Mudança de Metodologia do Plano A+3', 1, N'Open Pit/Poço aberto', N'Dificuldade e complexidade de alocação de escavadeiras manualmente nas frentes de lavra para um plano de 3 anos feito mês a mês (36 períodos).', N'Redução de tempo e flexibilidade na geração de cenários no plano de lavra A+3', N'10162', N'01 - Imagens/01 - Antes/11491.jpeg', N'Uso do Leveling para o sequenciamento de lavra. Para a elaboração do sequenciamento de lavra, era necessário fazer a alocação manualmente de todos os equipamentos de carga nos polígonos de lavra para um plano de 3 anos (36 meses). Essa atividade manual dificultava a geração de cenários diante das mudanças constantes de premissas dos equipamentos de cargas. Essa metodologia é ideal para horizontes de lavras operacionais, como planos de lavras semanais e mensais ', N'01 - Imagens/02 - Depois/11491.jpeg', N'Uso do Blend para o sequenciamento de lavra. Para a elaboração do sequenciamento de lavra com o blend, utilizamos as capacidades dos equipamentos de cargas como targets de movimentação por fases de lavra, sem uso manual de alocação de equipamentos. Essa metodologia facilita e flexibiliza a geração de cenários de lavra em tempo hábil para nossas entregas. Essa metodologia é ideal para horizontes de lavras de médio e longo prazo.', NULL, N'SIM. A nova metodologia foi testada e já utilizada nas atividades de rotina.', N'Eliminação de rotinas manuais', 0, NULL, N'Garantir um processo padronizado, rastreável e eficiente para o registro de resto ingestão, assegurando que 100% das informações e evidências fotográficas sejam armazenadas e compartilhadas de forma organizada por meio do Microsoft Forms e envio automático por e-mail.', '2026-05-01T00:00:00.000', '2026-07-30T17:17:10.000', N'369561', NULL, NULL);
INSERT INTO #PVC VALUES (11492, N'81057561', N'81057561', N'Cadastro de Fornecedores Alternativos', 1, N'Open Pit/Poço aberto', N'Antes da homologação, só tínhamos a opção de compra dos componentes com o fabricante do equipamentos, tais como, Sandvik, Komatsu e Epiroc. Elevado custo de compra, importação, logística dupla.
INSERT INTO #PVC VALUES (11493, N'978908', N'978908', N'Fórum de alinhamentos e validações prévias do plano trimestral rolante', 1, N'Others/Outros', N'Baixa integração entre os horizontes de planejamento, impactando diretamente a aderência do plano, a produtividade operacional e a utilização dos ativos.', N'Maior aderência ao planejamento, integração entre áreas operacionais, redução de desvios de execução, melhoria da previsibilidade da produção, governança estruturada do sequenciamento e maior alinhamento entre estratégia e operação.', N'10162', N'01 - Imagens/01 - Antes/11493.jpeg', N'Não aconteciam um fórum de alinhamentos e validações prévios para o plano trimestral rolante.', N'01 - Imagens/02 - Depois/11493.jpeg', N'Implementado fóruns mensais de alinhamentos e validações com as equipes operacionais para diligenciamento das atividades de infra, redes e linhas, perfuração e operação referentes ao plano trimestral rolante.', NULL, N'Sim. Atualmente reunimos mensalmente para alinhamentos das atividades para composição das premissas do plano trimestral rolante.', N'Engajamento das equipes.', 0, NULL, N'Implementar um sistema de acompanhamento visual e padronizado dos indicadores, proporcionando melhor gestão das informações, maior eficiência operacional e suporte às ações de melhoria contínua.', '2026-07-01T00:00:00.000', '2026-07-30T17:30:08.000', N'978908', NULL, NULL);
INSERT INTO #PVC VALUES (11494, N'978908', N'978908', N'Criação do Fluxo do Processo Master Plan D90', 1, N'Open Pit/Poço aberto', N'Falta de um fluxo padronizado para o processo recém criado do Master Plan de Polígonos de Desmonte.', N'Padronização ', N'10162', N'01 - Imagens/01 - Antes/11494.jpeg', N'Não existia um fluxo padrão para o processo recém criado do Master Plan de Polígonos de Desmonte.', N'01 - Imagens/02 - Depois/11494.jpeg', N'Criado e padronizado o fluxo do processo.', NULL, N'Sim', N'Ganho na assertividade / construção do plano trimestral.', 0, NULL, N'Otimização do processo.', '2026-07-27T00:00:00.000', '2026-07-30T17:50:15.000', N'978908', NULL, NULL);
INSERT INTO #PVC VALUES (11495, N'81022747', N'939199', N'ENGATE RAPIDO DE ABASTECIMENTO', NULL, N'Others/Outros', N'Para abastecer as caixas de água do pátio da perfuração era necessário remover a tampa para colocar a mangueira de abastecimento.', N'AGILIDADE', N'10144', N'01 - Imagens/01 - Antes/11495.jpeg', N'Para abastecer as caixas de água do pátio da perfuração era necessário remover a tampa para colocar a mangueira de abastecimento.', N'01 - Imagens/02 - Depois/11495.jpeg', N'foi instalado um engate rápido para facilitar o abastecimento.
INSERT INTO #PVC VALUES (11496, N'92000157', N'92000157', N'Relatório de acompanhamento dos desvios de preparação.', 1, N'Others/Outros', N'O acompanhamento dos desvios de materiais era realizado de forma manual e descentralizada, demandando elevado esforço para consolidação dos dados e dificultando a identificação dos principais ofensores e causas dos desvios.', N'Automatizar a consolidação e análise dos desvios de materiais', N'10269', N'01 - Imagens/01 - Antes/11496.jpeg', N'Dados dispersos em diferentes bases e controles, exigindo consolidação manual e limitando a agilidade das análises.', N'01 - Imagens/02 - Depois/11496.jpeg', N'Informações consolidadas em dashboard Power BI, com acompanhamento dos desvios por diferentes perspectivas e maior rapidez na identificação de oportunidades de atuação.', NULL, N'O relatório consolidou informações anteriormente dispersas, reduzindo o esforço de análise e aumentando a visibilidade dos desvios, atendendo ao objetivo de apoiar uma gestão mais eficiente e orientada por dados.', N'A estruturação e padronização dos dados são fundamentais para reduzir esforço operacional e aumentar a qualidade das análises e decisões.', 0, NULL, N'Este alarme antecipa e proporciona tempo hábil para acionar a operação e realizar a verificação em campo, mitigando o risco de desarme do bombeamento das torres de resfriamento, evitando cortes de alimentação da usina.
INSERT INTO #PVC VALUES (11497, N'81008286', N'81008286', N'New cage for nitrogen storage', 1, N'Others/Outros', N'old cage was rusted and signage was no longer legible', N'replace with new cage', N'0', N'01 - Imagens/01 - Antes/11497.jpeg', N'old cage was rusted, signage wasn''t legible, doors would not open properly.', N'01 - Imagens/02 - Depois/11497.jpeg', N'New cage to replace old one, proper signage installed.', NULL, N'yes.', N'n/a', 0, NULL, N'Melhor acompanhamento das aderências entre planos D90 e D30 para uma tomada de ação preditiva.', '2026-05-11T00:00:00.000', '2026-07-30T21:11:07.000', N'81008286', NULL, NULL);
INSERT INTO #PVC VALUES (11498, N'81008286', N'81008286', N'New valve for pressure bleed off', 2, N'Refining/Refino', N'There was no way to bleed off water pressure to this particular hose.', N'add valve for safe disconnect', N'0', N'01 - Imagens/01 - Antes/11498.jpeg', N'No shut off where hose connects, had to leave water in line when disconnecting the hose further up.', N'01 - Imagens/02 - Depois/11498.jpeg', N'Shut off valve added, allowing to stop flow of water and safely disconnect hose further down the line.', NULL, N'Yes, water can now be shut off and hose disconnected properly.', N'quick fix can save time and risks', 0, NULL, N'An alternative Muck Circuit was developed and validated using the Waste System', '2026-05-19T00:00:00.000', '2026-07-30T21:30:16.000', N'81008286', NULL, NULL);
INSERT INTO #PVC VALUES (11499, N'92000157', N'92000157', N'Reestruturação da base de acompanhamento da OTIF', 1, N'Others/Outros', N'A análise dos desvios identificados na OTIF dependia da consulta manual de informações em diferentes transações do SAP, demandando elevado esforço operacional e limitando a eficiência das investigações. Além disso, a estrutura das planilhas não favoreciam o desenvolvimento de relatórios em power BI para consolidação dos dados.', N'Automatizar a obtenção e consolidação de informações utilizadas na análise dos desvios de materiais, reduzindo o esforço manual e aumentando a disponibilidade de dados para tomada de decisão.', N'10269', N'01 - Imagens/01 - Antes/11499.jpeg', N'As informações utilizadas nas análises, como MRP, máximos, mínimos e características das ordens, precisavam ser consultadas individualmente no SAP, tornando o processo lento e suscetível a falhas.', N'01 - Imagens/02 - Depois/11499.jpeg', N'A planilha de acompanhamento foi reformulada e integrada a bases do SAP BO, permitindo o preenchimento automático de informações relevantes para análise dos desvios, como MRP, parâmetros de máximo e mínimo dos materiais e dados das ordens de manutenção. Com isso, os dados passaram a ser disponibilizados de forma estruturada, padronizada e adequada para análises e consolidação de indicadores.', NULL, N'A solução eliminou grande parte das consultas manuais necessárias para obtenção das informações de análise, disponibilizando os dados de forma consolidada e estruturada, em linha com o objetivo de tornar a avaliação dos desvios mais eficiente e produtiva.', N'A automação e o enriquecimento dos dados na origem reduzem significativamente o esforço analítico e ampliam o potencial de utilização das informações.', 0, NULL, N'mitigar o extravio de grampeadores  por falta de identificação', '2026-07-20T00:00:00.000', '2026-07-30T21:32:15.000', N'92000157', NULL, NULL);
INSERT INTO #PVC VALUES (11500, N'81047804', N'50004', N'Portão da bica de metal ', 2, N'Refining/Refino', N'Não pode fica  aberto risco de queda ', N'segurança ', N'10049', N'01 - Imagens/01 - Antes/11500.jpeg', N'Portão menor fora do padrão ', N'01 - Imagens/02 - Depois/11500.jpeg', N'Feita a melhoria e portão padronizador ', NULL, N'sim', N'Foco em segurança', 0, NULL, N'Aumento da confiabilidade dos dados utilizados nas análises de manutenção e confiabilidade, melhoria da qualidade dos apontamentos de parada, maior padronização dos critérios de classificação e identificação de oportunidades de capacitação das equipes.', '2026-07-25T00:00:00.000', '2026-07-30T21:53:58.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11501, N'81047804', N'487432', N'Portão do forno panela ', 2, N'Refining/Refino', N'Melhora o acesso e liberação do caminho seguro ', N'Melhora acesso ', N'10049', N'01 - Imagens/01 - Antes/11501.jpeg', N'atrapalhando o acesso ao caminho seguro ', N'01 - Imagens/02 - Depois/11501.jpeg', N'Fazer a liberação do caminho para melhora o acesso do caminho seguro', NULL, N'sim', N'Foco em segurança ', 0, NULL, N'Completed critical liner replacement without shutting down ore production.
INSERT INTO #PVC VALUES (11502, N'81047804', N'487432', N'Caixa de epi ', 2, N'Refining/Refino', N'Melhora o acesso aos amostrado e elimina o risco de batida contra ', N'Elimina riscos ', N'10049', N'01 - Imagens/01 - Antes/11502.jpeg', N'Dificildade para tira o amostrado podendo bate a mão contra caixa de epi ', N'01 - Imagens/02 - Depois/11502.jpeg', N'caixa de epi realocada eliminando o risco de batida contra ', NULL, N'Sim ', N'Segurança ', 0, NULL, N'aumento da produtividade e segurança', '2026-07-02T00:00:00.000', '2026-07-30T22:24:51.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11503, N'81047804', N'487432', N'Suporte do aluminizado ', 3, N'Refining/Refino', N'Falta de local adequado para colocação do epi ', N'5S', N'10049', N'01 - Imagens/01 - Antes/11503.jpeg', N'Falta de local adequado perto do local de trabalho para o armazenamento do  epi aluminizado ', N'01 - Imagens/02 - Depois/11503.jpeg', N'Suporte adequado para aluminizado próximo ao local de trabalho ', NULL, N'Sim ', N'5S e organização ', 0, NULL, N'Promoting a proper place to secure materials helps ensure crews are following the proper steps to return items as well ensuring safety by not dropping objects.', '2026-07-02T00:00:00.000', '2026-07-30T23:08:09.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11504, N'81045351', N'81045351', N'Implantação de Formulário Digital para Registro de Evidências e Monitoramento do Resto Ingestão nos Refeitórios', 1, N'Projects/Projetos', N'O acompanhamento do resto ingestão dos refeitórios era realizado por meio de mensagens em grupos de WhatsApp, dificultando a organização das informações, a rastreabilidade dos registros, a consulta ao histórico e a consolidação dos dados. A ausência de um processo padronizado comprometia a gestão das evidências e o monitoramento efetivo dos resultados.', N'Garantir 100% dos registros de resto ingestão com evidências fotográficas e informações padronizadas em plataforma digital, proporcionando rastreabilidade, histórico de dados e melhor acompanhamento dos indicadores dos refeitórios.', N'10017', N'01 - Imagens/01 - Antes/11504.jpeg', N'O registro das informações e evidências fotográficas do resto ingestão era realizado por meio de grupos de WhatsApp. Esse processo dificultava a padronização das informações, a rastreabilidade dos registros e a consulta ao histórico das evidências. Além disso, a busca por dados anteriores era demorada, havia risco de perda de informações em meio às mensagens e a consolidação dos dados para acompanhamento dos refeitórios era realizada de forma manual e pouco eficiente.', N'01 - Imagens/02 - Depois/11504.jpeg', N'Com a implantação do Microsoft Forms, os registros de resto ingestão passaram a ser realizados em um formulário padronizado, permitindo o preenchimento das informações e o envio das evidências fotográficas em um único ambiente. Após o preenchimento, as respostas são encaminhadas automaticamente por e-mail, garantindo que as informações fiquem registradas, organizadas e acessíveis para consulta e acompanhamento.
INSERT INTO #PVC VALUES (11505, N'81047804', N'487338', N'Rolete do escudo  ', 2, N'Refining/Refino', N'Dificuldade da remoção do plugue com o tubo ', N'Melhora a ergonomia ', N'10049', N'01 - Imagens/01 - Antes/11505.jpeg', N'Rolete avariado e travado dificultando a remoção da plugue da panela com a utilização de tubo', N'01 - Imagens/02 - Depois/11505.jpeg', N'Substituição por roletes com rolamentos evitando travamentos ', NULL, N'Sim ', N'Segurança e ergonomia ', 0, NULL, N'Easier and safer to preform isolation.  ', '2026-07-13T00:00:00.000', '2026-07-30T23:42:23.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11506, N'81045351', N'81045351', N'Criação de planilha gerencial com acompanhamento gráfico dos indicadores de Parada de Fila e Corpo Estranho', 1, N'Others/Outros', N'Os registros e acompanhamentos dos indicadores de Parada de Fila e Corpo Estranho eram realizados e armazenados por meio de trocas de e-mails, dificultando a consolidação das informações, a consulta ao histórico e a visualização da evolução dos resultados ao longo dos meses. A ausência de uma ferramenta centralizada gerava maior tempo para análise dos dados e limitava a identificação rápida de tendências e oportunidades de melhoria.', N'Desenvolver uma planilha de controle com atualização mensal e visualização gráfica dos principais indicadores de Parada de Fila e Corpo Estranho, proporcionando maior agilidade na análise dos resultados, acompanhamento da evolução mensal e suporte à tomada de decisão.', N'10017', N'01 - Imagens/01 - Antes/11506.jpeg', N'O acompanhamento dos indicadores de Parada de Fila e Corpo Estranho era realizado por meio de registros enviados e armazenados em e-mails. As informações ficavam descentralizadas, dificultando a consulta ao histórico, a consolidação dos dados e a visualização da evolução dos resultados ao longo dos meses. O processo demandava mais tempo para análise e acompanhamento dos indicadores.', N'01 - Imagens/02 - Depois/11506.jpeg', N'Foi desenvolvida uma planilha gerencial com gráficos de acompanhamento mensal, reunindo em um único local todas as informações dos indicadores de Parada de Fila e Corpo Estranho. A nova ferramenta permite visualizar rapidamente a evolução dos resultados, facilita a consulta ao histórico, agiliza as análises e apoia a tomada de decisão, tornando o monitoramento mais eficiente e padronizado.', NULL, N'A melhoria implementada atendeu integralmente à meta proposta, proporcionando melhor gestão visual dos indicadores, redução do tempo de consulta das informações e maior agilidade na análise dos resultados.', N'A transformação de um processo baseado em trocas de e-mails para uma ferramenta estruturada de controle e acompanhamento permitiu maior visibilidade dos resultados, otimização do tempo de análise e melhoria na gestão dos indicadores de qualidade.', 0, NULL, N'Economia Mensal:  R$ 366.919,08 
INSERT INTO #PVC VALUES (11507, N'521673', N'471863', N'Identificação de inicio da coleta de perolas', 1, N'No Replication/Sem replicação', N'Anteriormente, não existia uma identificação para indicar o início da primeira amostra da leitura.', N'Otimizar o processo', N'10366', N'01 - Imagens/01 - Antes/11507.jpeg', N'Anteriormente, não havia uma identificação que indicasse o início da primeira amostra da leitura, o que levava o técnico a gastar tempo verificando em qual lado deveria iniciar a leitura.', N'01 - Imagens/02 - Depois/11507.jpeg', N'A identificação do início da primeira amostra proporcionou maior segurança na execução da leitura, reduzindo a ocorrência de erros operacionais, especialmente em situações em que a identificação do balão se encontra comprometida ou com falhas.', NULL, N'Sim. A implementação da identificação do início da primeira amostra reduziu o tempo gasto pelos técnicos na localização do ponto inicial da leitura, tornando o processo mais ágil, padronizado e eficiente, além de minimizar possíveis erros de interpretação.', N'Rapidez e qualidade na coleta', 0, NULL, N'Making fueling of equipment safer and easier for all employees', '2026-07-27T00:00:00.000', '2026-07-31T00:47:39.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (11508, N'33019', N'33019', N'Padronização e Modernização da apresentação orçamentaria de 2026 3Y 3Y', 1, N'Others/Outros', N'Excesso de informações visuais.
INSERT INTO #PVC VALUES (11509, N'81037761', N'81037761', N'Alarme Crítico Prevenção de Desarme das Bombas por Nível Baixo nas Torres de Resfriamento dos Prensas.', 1, N'No Replication/Sem replicação', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos prensas do Salobo 3, há uma redução na corrente da bomba. Essa condição pode não ser percebida em tempo hábil pelo técnico da sala de controle para acionar a operação e realizar a verificação em campo, podendo resultar no desarme da bomba e em cortes de alimentação da usina. 
INSERT INTO #PVC VALUES (11510, N'81047331', N'81047331', N'Curvas de Aderência Interplanos', 1, N'Others/Outros', N'Não rastreabilidade da aderência entre o plano D90 e o plano D30. ', N'Maior assertividade no sequenciamento ', N'#N/A', N'01 - Imagens/01 - Antes/11510.jpeg', N'Não havia esses indicadores', N'01 - Imagens/02 - Depois/11510.jpeg', N'Melhoria de visualização e controle da aderência entre planos.', NULL, N'Melhor visualização da aderência entre planos para uma melhor tomada de ação preditiva.', N'Importância da rastreabilidade dos processos', 0, NULL, N'Neon Green lanyard also makes wrenches location easy to spot.', '2026-07-28T00:00:00.000', '2026-07-31T08:57:26.000', N'81047331', NULL, NULL);
INSERT INTO #PVC VALUES (11511, N'477830', N'300740', N'Alternative Muck Circuit', 1, N'Underground/Subterrâneo', N'The current muck circuit relies on the 3800 Coarse Ore Bin (COB), underground Crusher, and Conveyor #2. Any major maintenance or extended repairs on these assets require production interruptions.', N'Develop and validate an alternative ore handling process that allows ore production to continue while the 3800 COB, Crusher, and Conveyor #2 are out of service for planned or unplanned maintenance activities.', N'10288', N'01 - Imagens/01 - Antes/11511.jpeg', N'Ore production relied entirely on the primary muck circuit through the 3800 Coarse Ore Bin (COB), underground Crusher, and Conveyor #2. Any major maintenance or extended repairs on these assets required production interruptions. The mine had no proven alternative route to maintain ore production while these assets were out of service.', N'01 - Imagens/02 - Depois/11511.jpeg', N'An Alternative Muck Circuit was developed and validated using the Waste System to bypass the 3800 COB, Crusher, and Conveyor #2. Ore can now be hoisted through the waste stream and routed to surface for crushing, allowing production to continue during planned or unplanned outages of the primary muck circuit.', NULL, N'The process was successfully risk assessed and demonstrated during a two-day Conveyor #2 belt repair, providing a reliable contingency option and increased flexibility for future maintenance activities.', N'Alternative ore circuit proved', 0, NULL, NULL, '2026-06-03T00:00:00.000', '2026-07-31T08:58:49.000', N'477830', NULL, NULL);
INSERT INTO #PVC VALUES (11512, N'81058052', N'81058052', N'tagueamento de grampeadores', 3, N'Others/Outros', N'grampeadores sem identificação eram extraviados ao serem emprestados para outras áreas 
INSERT INTO #PVC VALUES (11513, N'81059325', N'81059325', N'INDICADOR - QUALIDADE DAS CLASSIFICAÇÕES DE PARADA', 1, N'Others/Outros', N'Não havia um mecanismo para avaliar a assertividade das classificações de paradas registradas no sistema. Essa ausência gerava risco de distorções nas análises de confiabilidade e manutenção, uma vez que classificações inadequadas poderiam impactar a identificação das principais causas de perda dos ativos. Dessa forma, surgiu a necessidade de criar um indicador para medir e acompanhar a qualidade das classificações realizadas.', N'Verificar a aderência entre a classificação registrada para a parada e a intervenção efetivamente executada, garantindo maior confiabilidade das informações utilizadas nas análises de manutenção e confiabilidade.', N'10015', N'01 - Imagens/01 - Antes/11513.jpeg', N'Não havia um mecanismo para avaliar a assertividade das classificações de paradas registradas no sistema. Essa ausência gerava risco de distorções nas análises de confiabilidade e manutenção, uma vez que classificações inadequadas poderiam impactar a identificação das principais causas de perda dos ativos. Dessa forma, surgiu a necessidade de criar um indicador para medir e acompanhar a qualidade das classificações realizadas.', N'01 - Imagens/02 - Depois/11513.jpeg', N'Foi implantado um processo de auditoria das classificações de paradas, com avaliação amostral trimestral dos registros realizados pelas equipes.
INSERT INTO #PVC VALUES (11514, N'477830', N'477830', N'Surface Ore Bin Alternative Routing', 1, N'Underground/Subterrâneo', N'The current ore handling process relies on the Surface Ore Bin to load surface trucks and transport ore to the Ore Tent. Any major maintenance or repair work on the Surface Ore Bin requires shutting down the ore system, resulting in production losses.', N'Replace worn liners in the Surface Ore Bin while maintaining ore production and minimizing the impact on operations.', N'10288', N'01 - Imagens/01 - Antes/11514.jpeg', N'Ore was routed exclusively through the Surface Ore Bin before being loaded into trucks and transported to the Ore Tent. Because no alternate route existed, extended maintenance on the bin would have required shutting down ore handling activities, directly affecting production.', N'01 - Imagens/02 - Depois/11514.jpeg', N'An alternative ore routing process was assessed, reviewed, risk-evaluated, and successfully implemented. During daytime shifts, maintenance crews can work in the ore bin. During night shifts, the tilt chute redirected to the Waste Bin, bypassing the Surface Ore Bin.
INSERT INTO #PVC VALUES (11515, N'81058052', N'81058052', N'etiquetagem de caixas de bloqueio de leves', 3, N'Others/Outros', N'a falta de identificação nas caixas de bloqueio dificultava a liberação dos equipamentos sempre que era necessário fazer o desbloqueio dos equipamentos junto aos operadores. ', N'indentificar as caixas de bloqueio por meio de etiquetas impressas ', N'10346', N'01 - Imagens/01 - Antes/11515.jpeg', N'caixas de bloqueio sem identificação para determinar quais equipamentos estavam bloqueados . ', N'01 - Imagens/02 - Depois/11515.jpeg', N'aplicadas etiquetas para fácil descrição dos equipamentos bloqueados na oficina.', NULL, N'sim ,o problema foi resolvido com a identificação das caixas de bloqueio possibilitando a rastreabilidade das chaves debloqueio dos equipamentos de imediato.', N'pequenas ações garantem o aumento de produtividade ', 0, NULL, N'Eliminar o risco de tropeço, melhorar a ergonomia durante a execução das atividades, proporcionar maior segurança e conforto ao colaborador, facilitar o acesso ao componente e aumentar a eficiência e a padronização dos serviços de manutenção.', '2026-07-06T00:00:00.000', '2026-07-31T09:40:40.000', N'81058052', NULL, NULL);
INSERT INTO #PVC VALUES (11516, N'81055952', N'81055952', N'Banding Station 221 SMA Shop', 3, N'Others/Outros', N'Material to be sent back to warehouse continuously being strapped down by ratchet straps', N'Save on Material', N'0', N'01 - Imagens/01 - Antes/11516.jpeg', N'Material to be sent back to warehouse continuously being strapped down by ratchet straps', N'01 - Imagens/02 - Depois/11516.jpeg', N'Set up proper banding station to secure materials going back to warehouse.', NULL, N'Worked out Great', N'Save on straps', 1000, 3, N'Essa adequação permitiu a operação com segurança do ativo de R$ 250.000,00, recuperando a capacidade produtiva de 360 amostras por dia (10.800/mês).', '2026-07-30T00:00:00.000', '2026-07-31T10:00:37.000', N'81055952', NULL, NULL);
INSERT INTO #PVC VALUES (11517, N'81003675', N'81003675', N'Treinamento pratico inversores.', 2, N'Others/Outros', N'Não tinhamos além do dojo uma forma adequada e segura para que os colaboradores tivessem  acesso aos inversores para um primeiro contato de instalação e parametrização', N'Capacitar colaboradores para implementação básica de conexão e parametrização de inversores de frequência.', N'10038', N'01 - Imagens/01 - Antes/11517.jpeg', N'Somente era possível ministrar treinamento na área do dojo de elétrica pois dependia-se da bancada para simular os exercícios.
INSERT INTO #PVC VALUES (11518, N'1015316', N'1015316', N'Mill extension isolations', 2, N'Concentration/Concentração', N'Isolating interments at the mill extension requires opening the PLC cabinet or pulling wires off the TB to perform a task. This is a bigger risk to the assets and the persons involved. ', N'To make it easier and safer to isolate valves and other instruments at the mill extension', N'10359', N'01 - Imagens/01 - Antes/11518.jpeg', N'We previously had to open the PLC cabinets, which are located in the field, to isolate valves and other instruments.', N'01 - Imagens/02 - Depois/11518.jpeg', N'We installed isolation terminal blocks (shown above the red line), while the wiring below the red line represents the original configuration. These terminal blocks allow instruments to be isolated safely and efficiently without opening the PLC cabinets.
INSERT INTO #PVC VALUES (11519, N'496972', N'496972', N'Mercado interno - Redução nos custos de transporte', 1, N'Others/Outros', N'Altos custos com TRANSPORTE DE FERRO NIQUEL PARA CLIENTES DO MERCADO INTERNO, 
INSERT INTO #PVC VALUES (11520, N'81031571', N'81031571', N'Sure Can Fuel ', 2, N'Underground/Subterrâneo', N'To reduce spillage of fuel and splash back on employees while fueling equipment with fuel can', N'Prevent Fuel spills on Employees', N'0', N'01 - Imagens/01 - Antes/11520.jpeg', N'This style of can causes issues with splash back on employees.', N'01 - Imagens/02 - Depois/11520.jpeg', N'This style of fuel can with a nozzel and valve help prevent splash back and make fueling easier to control.', NULL, N'Initial goal was to make fueling equipment easier and safer for employees and has been a success to using the basic style can', N'New Style can is more efficient and easier to use', 0, NULL, N'Ganho na produtividade da equipe de Automação principalmente, que conseguem se planejar melhor e atender mais de uma demanda.', '2026-07-30T00:00:00.000', '2026-07-31T11:17:37.000', N'81031571', NULL, NULL);
INSERT INTO #PVC VALUES (11521, N'81064844', N'1010414', N'Deisel Fuel Storgae Tank - Inspection Interval Extension', 1, N'Refining/Refino', N'The current inspection interval for the LH Deisel Fuel storage tank (580-TNK-009) was no practical from a scheduling standpoint. It was believed that a detailed risk assessment could all for the inspection interval to be extended. The current inspections interval was 3years for both internal and external inspections', N'Extend Inspection Interval of 580-TNK-009', N'10006', N'01 - Imagens/01 - Antes/11521.jpeg', N'Previous Inspection interval 3 year internal/ External', N'01 - Imagens/02 - Depois/11521.jpeg', N'Updated Inspection Interval is 5 year Ext / 10 Year Int', NULL, N'By reviewing inspection reports and, estimating corrosion rates calculating minimum wall thickness of tank nozzle, it was determined that the internal inspection interval could be extended from 3 years to 10 year.', N'Look for oppertunities to extended intervals when there is low risk', 0, NULL, N'Redução de 100% do risco de cortes nas bordas do suporte de copos, garantindo um ambiente de trabalho mais seguro.', '2026-07-28T00:00:00.000', '2026-07-31T12:11:35.000', N'81064844', NULL, NULL);
INSERT INTO #PVC VALUES (11522, N'81020808', N'81020808', N'Planilha Unificada de Horímetros para Inspeção de Pneus', 1, N'Others/Outros', N'Era necessário acessar o SAP e consultar os equipamentos individualmente para coletar os horímetros. Esse processo demandava elevado tempo de execução, além de aumentar o risco de erros na transcrição das informações.', N'Redução de tempo na coleta de dados e confiabilidade.', N'10023', N'01 - Imagens/01 - Antes/11522.jpeg', N'Antes da implementação da planilha unificada, era necessário acessar o SAP e consultar os equipamentos individualmente para coletar os horímetros. Esse processo demandava elevado tempo de execução, além de aumentar o risco de erros na transcrição das informações.', N'01 - Imagens/02 - Depois/11522.jpeg', N'Foi desenvolvida uma planilha unificada de horímetros para inspeção de pneus, contemplando todas as frotas em operação. A ferramenta está integrada às planilhas de controle atualizadas pelos programadores de manutenção de cada frota, realizando a importação automática dos horímetros dos equipamentos.', NULL, N'Maior eficiência no processo de inspeção, melhoria da qualidade dos dados e aumento da assertividade no planejamento das ações de manutenção relacionadas aos pneus da frota.', N'Com essa automatização, as inspeções de pneus passam a utilizar dados atualizados em tempo real, eliminando lançamentos manuais, reduzindo riscos de erros de digitação e aumentando a confiabilidade das informações utilizadas no monitoramento da vida útil dos pneus.', 0, NULL, N'Garantir monitoramento automático e em tempo real das separações, permitindo identificar desvios rapidamente e aumentar a aderência das OTIFs da Mina e da Usina.', '2026-07-30T00:00:00.000', '2026-07-31T13:25:50.000', N'81020808', NULL, NULL);
INSERT INTO #PVC VALUES (11523, N'81053928', N'81053928', N'Use Of Lanyards', 2, N'Refining/Refino', N'Valve wrench for turning valves just left on ledge of I beam , which could fall and hit someone.', N'stop object from falling ', N'10283', N'01 - Imagens/01 - Antes/11523.jpeg', N'Valve wrench just left on ledge with possibility of falling.', N'01 - Imagens/02 - Depois/11523.jpeg', N'I attached the valve wrench to a fixed position next to the valves with a lanyard . Making it easier to spot and impossible to fall possibly hitting someone.', NULL, N'yes the problem was solved because now by adding a lanyard to the valve wrench should stop it from falling to the ground.', N'Dropped objects', 0, NULL, NULL, '2026-07-30T00:00:00.000', '2026-07-31T14:04:19.000', N'81053928', NULL, NULL);
INSERT INTO #PVC VALUES (11524, N'81050431', N'81058947', N'BANCADA DE CORTE', 3, N'Others/Outros', N'Bancada de corte em alto estado de desgaste.', N'custo evitado', N'10139', N'01 - Imagens/01 - Antes/11524.jpeg', N'Bancada de corte em alto estado de desgaste.', N'01 - Imagens/02 - Depois/11524.jpeg', N'Bancada de corte  foi feito uma  recuperação com revitalização e com material novo.', NULL, N'Bancada de corte  foi feito uma  recuperação com revitalização e com material novo', N'economia', 1, 1, N'GANHOS EXCELENTES PARA ELIMINAR PENDÊNCIAS PELA FALTA DE MATERIAIS NO KANBAN ELÉTRICA.', '2026-07-03T00:00:00.000', '2026-07-31T14:26:38.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (11525, N'141002', N'141002', N'Implantação de Informativo Diário de Estoque de Minério ', 1, N'Others/Outros', N'Falta de uma ferramenta de comunicação diária e padronizada para divulgação dos estoques de minério, impactando a eficiência da gestão operacional, o planejamento das atividades e o acompanhamento dos níveis de estoque.', N'esenvolver e implementar um Informativo Diário de Estoque de Minério, consolidando as principais informações de forma clara, visual e acessível para as equipes operacionais e de gestão.', N'10180', N'01 - Imagens/01 - Antes/11525.jpeg', N'As informações de estoque de minério encontravam-se dispersas em diferentes controles e consultas, dificultando a rápida visualização da situação operacional. A ausência de um informativo padronizado exige análises manuais para obtenção dos dados, aumentando o tempo de tomada de decisão e o risco de divergências nas informações.', N'01 - Imagens/02 - Depois/11525.jpeg', N'Implementação de um informativo diário de estoque de minério, consolidando dados de estoque, movimentações e indicadores operacionais em um único relatório padronizado. A iniciativa visa aumentar a visibilidade das informações, agilizar a tomada de decisão e melhorar a gestão dos estoques, reduzindo o tempo gasto na obtenção e análise dos dados.', NULL, N'A ausência de um informativo diário dificulta o acompanhamento dos níveis de estoque, da ocupação dos pátios e das movimentações realizadas, limitando a velocidade na tomada de decisões operacionais e no planejamento das atividades. Além disso, a falta de gestão visual reduz a percepção antecipada de possíveis desvios, como níveis críticos de estoque ou restrições operacionais, podendo impactar a eficiência da cadeia produtiva.', N'Gestão visual dos indicadores permitindo identificar desvios e riscos com antecedência', 0, NULL, N'O SERVIÇO DE SOLDA LEVA E MEDIA DUAS HORAS, SENDO QUE COM A TRAVA A ATIVIDADE É REALIZADA EM 20 MINUTO', '2026-07-30T00:00:00.000', '2026-07-31T14:30:16.000', N'141002', NULL, NULL);
INSERT INTO #PVC VALUES (11526, N'81043438', N'81037700', N'Modificação do sistema propulsão da bomba', 1, N'Projects/Projetos', N'Foi identificado baixo desempenho da bomba BP_2057_22, ocasionado pela alteração do fator de espuma do produto bombeado, resultando no aumento da recirculação interna da bomba durante o bombeamento para o DI_2057_06.', N'Melhorar o desempenho da bomba de polpa flotação', N'10178', N'01 - Imagens/01 - Antes/11526.jpeg', N'A bomba BP_2057_22, responsável pelo bombeamento de polpa para o DI_2057_06, apresentou redução de desempenho em função da elevação do fator de espuma do produto bombeado. Durante a análise, foi identificada a operação da bomba em uma posição inadequada para as condições de elevado fator de espuma. Adicionalmente, constatou-se a existência de uma redução no recalque da tubulação, bem como incrustações em seu interior, fatores que contribuíram para a restrição do fluxo e para a perda de eficiência do sistema de bombeamento.', N'01 - Imagens/02 - Depois/11526.jpeg', N'Foi realizado um estudo de engenharia pela equipe de Engenharia de Confiabilidade, em conjunto com as equipes de PCM e Execução, no qual foi identificado que, para restabelecer e otimizar o desempenho do sistema de bombeamento, seria necessária a alteração da posição de operação da bomba, a substituição do rotor por um modelo mais adequado às condições operacionais e o redimensionamento da tubulação de recalque, visando reduzir as perdas de carga e aumentar a eficiência do sistema', NULL, N'Sim, foi instalado um novo modelo de rotor mais indicado para fator alto de espuma, foi modificado a posição de operação da bomba e aumentador o diâmetro da tubulação de recalque. ', N'A troca do rotor permitiu a recuperação da eficiência operacional da bomba BP_2057_22, confirmando a relevância do acompanhamento sistemático de desempenho como ferramenta para prevenção de perdas de capacidade e confiabilidade do equipamento.', 0, NULL, N'Controle de sobrecarga e falha instantâneo.', '2026-07-21T00:00:00.000', '2026-07-31T14:32:58.000', N'81043438', NULL, NULL);
INSERT INTO #PVC VALUES (11527, N'486546', N'486546', N'Eliminação de Risco Crítico por Segregação do Tráfego de Pessoas e Combustíveis', 2, N'Others/Outros', N'O embarque e desembarque de colaboradores é realizado em um acesso compartilhado entre ônibus de transporte de pessoas e carretas de diesel, em área com espaço reduzido e sem condições adequadas para manobras seguras. A ocorrência de fluxo simultâneo, especialmente nos horários administrativos, aumenta significativamente o risco de colisões e exige manobras críticas, como marcha à ré em rampa com carretas carregadas, elevando a exposição a riscos operacionais no transporte de pessoas.
INSERT INTO #PVC VALUES (11528, N'81006946', N'81006946', N'TRAVA DO BRAÇO DE DIREÇÃO DO CARRO DE BAIXAR PEITO DE TRATOR', 2, N'Others/Outros', N'BRAÇO DE DIREÇÃO FICAVA NO CHÃO', N'POSICINAR O BRAÇO EM POSIÇÃO DE MELHOR ACESSO', N'10139', N'01 - Imagens/01 - Antes/11528.jpeg', N'Condição identificada: O braço permanecia na altura do solo, criando uma condição insegura por representar risco de tropeço e queda para as pessoas que circulam na área. Além disso, a posição exigia que o colaborador realizasse movimentos de flexão excessiva durante a operação, gerando desconforto ergonômico e aumentando o risco de lesões musculoesqueléticas.', N'01 - Imagens/02 - Depois/11528.jpeg', N'Com a aplicação da trava do braço, o componente passou a permanecer em uma posição elevada e estável, proporcionando melhor acesso para a execução das atividades. A melhoria eliminou o risco de tropeço, reduziu o esforço ergonômico do colaborador e aumentou a segurança durante a realização dos serviços.', NULL, N'SIM! SE MANTERMOS AS ORIENTAÇÕES E PROCEDIMENTOS', N'A identificação e correção de condições inseguras antes da execução das atividades são fundamentais para prevenir acidentes.', 0, NULL, NULL, '2026-07-30T00:00:00.000', '2026-07-31T14:51:34.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11529, N'52548', N'471876', N'Otimização de Ativo Crítico: Redução de Ruído no Exaustor BOR004 e Retorno Operacional', 2, N'Others/Outros', N'A operação do exaustor BOR004 na Sala de Absorção Atômica gerava um ruído contínuo de 79,6 dB(A), tornando o ambiente em uma zona de incerteza técnica perante as diretrizes das normas NR-09, NR-15 e NHO 01. Sob o ponto de vista da saúde ocupacional, esse cenário expunha diretamente a equipe técnica e operacional a patologias, tais como fadiga psíquica, irritabilidade e perda auditiva induzida por ruído. Em decorrência do severo impacto ergonômico e visando resguardar a integridade física dos colaboradores, eles deixavam de utilizar o equipamento. Resultando na ociosidade completa de um ativo crítico de alto valor tecnológico, avaliado em R$ 250.000,00, tornando-se em um custo improdutivo para a empresa. Sob a ótica operacional, a paralisação do maquinário fez a unidade deixar de processar cerca de 360 amostras por dia, o que culminou em um déficit acumulado de 10.800 análises mensais não realizadas.', N'Garantir a Segurança Ocupacional: Eliminar o risco à saúde dos operadores de laboratório, reduzindo a exposição ao ruído contínuo e cumprindo os requisitos normativos de Higiene Ocupacional. Recuperar Capacidade Produtiva.', N'10155', N'01 - Imagens/01 - Antes/11529.jpeg', N'Foi medido com um sonômetro o nível de Ruido 79,6 dB(A) no exaustor BOR004 da Sala de Absorção atômica, caracterizando ruido no nível de incerteza em relação ao Nível de Ação do limite de exposição. ', N'01 - Imagens/02 - Depois/11529.jpeg', N'Após Substituição do exaustor BOR004, o novo nível de ruído medido foi de 65,1 dB(A), constatando redução de 14,5 dB(A), na geração de ruido do equipamento.', NULL, N'Sim, o Kaizen resolveu o problema ao substituir o exaustor BOR004, reduzindo o ruído em 14,5 dB(A) e eliminando os riscos à saúde, e adequando o conforto acústico dos colaboradores. ', N'Impactos de pequenas intervenções, A importância da escuta ativa, e Importância do Monitoramento Preventivo.', 0, NULL, N'melhoria na condição ergonômica e de organização da area', '2026-07-06T00:00:00.000', '2026-07-31T15:05:58.000', N'52548', NULL, NULL);
INSERT INTO #PVC VALUES (11530, N'535031', N'535031', N'Cronograma D90', 1, N'Others/Outros', N'O master plan não tinha um acompanhamento que apontasse as não realização do plano no tempo correto e com avanço planejado, além de não possuir visibilidade das atividades criticas para o bom andamento da mina. ', N'Acompanhar a aderência das atividades programada no D90', N'10161', N'01 - Imagens/01 - Antes/11530.jpeg', N'A inexistência de um controle estruturado das atividades limitava a visibilidade do time sobre a aderência ao plano de 90 dias. Com isso, os replanejamentos mensais ocorriam sem rastreabilidade histórica das atividades reprogramadas e dos desvios acumulados.', N'01 - Imagens/02 - Depois/11530.jpeg', N'Atualmente, é possível mensurar as reprogramações, controlar a aderência entre os planos e acompanhar o histórico das atividades. A implementação do cronograma trouxe uma visão sequenciada das atividades alinhada à lógica operacional das equipes executoras, proporcionando visibilidade por polígono das etapas realizadas e das próximas ações necessárias. Como benefício adicional, o cronograma antecipa a visão do sequenciamento operacional, contribuindo para a otimização do processo de elaboração do plano D30 e para uma tomada de decisão mais assertiva.', N'https://globalvale.sharepoint.com/:f:/s/PlanejamentoSLB-MdioPrazo/IgBE5Uky9RU4SqkDXLUdn80OAQLeIh_Ho6KncOvneUFwWsU?email=c0726735%40vale.com&e=vfO7ts', N'Melhor do que o esperado, trouxe outros resultados positivos. ', N'Implantar um cronograma integrado aumenta a visibilidade e a rastreabilidade das atividades. O controle das reprogramações permite identificar desvios recorrentes e atuar preventivamente. O sequenciamento por polígono melhora a integração entre Infraestrutura, Perfuração e Lavra. A visão antecipada das atividades reduz retrabalhos e aumenta a aderência entre os planos M12, D90 e D30. A gestão baseada em predecessoras proporciona maior previsibilidade e assertividade na tomada de decisão operacional.', 0, NULL, N'Foi confeccionado suporte com material sobressalente e instalado no compressor, de modo a manter a mangueira do mesmo enrolada e armazenada de maneira organizada e segura.', '2026-07-17T00:00:00.000', '2026-07-31T15:12:52.000', N'535031', NULL, NULL);
INSERT INTO #PVC VALUES (11531, N'81030963', N'81047196', N'Lista de Funcionários em situação de Emergência ', 1, N'Others/Outros', N'Foi implantado um sistema de controle de presença para emergências, garantindo identificação rápida das pessoas na área, maior rastreabilidade e mais segurança aos colaboradores.', N'Eliminar risco de pessoas ficarem sem acionamento em caso de Emergência ', N'10079', N'01 - Imagens/01 - Antes/11531.jpeg', N'Não havia um controle eficiente para identificar quem estava na área durante os acionamentos de emergência, gerando uma lacuna no processo de segurança e dificultando a rastreabilidade.', N'01 - Imagens/02 - Depois/11531.jpeg', N'Foi implementado um sistema de controle de presença que possibilita a identificação rápida e precisa das pessoas na área durante emergências, aumentando a rastreabilidade, a agilidade na resposta e a segurança dos colaboradores.', NULL, N'Ausência de um método confiável para controlar a presença de pessoas na área durante emergências.
INSERT INTO #PVC VALUES (11532, N'81030963', N'514428', N'MELHORIA NO PROCESSO DE DESCARTE DE INSERVÍVEIS – MID SAP', 1, N'Others/Outros', N'MID “Outros Inservíveis” sem os campos de responsável, gerência, diretoria e aprovador da área usuária; 
INSERT INTO #PVC VALUES (11533, N'81064091', N'81064091', N'Planejar melhor para Executar melhor', 1, N'Others/Outros', N'Tínhamos uma demanda da Automação, que era saber exatamente em qual horário eles teriam o equipamento liberado (desbloqueado), para executarem as preventivas e corretivas.
INSERT INTO #PVC VALUES (11534, N'81044397', N'81044397', N'Proteção das Bordas Metálicas do Suporte de Copos', 1, N'Others/Outros', N'Foi identificado risco de corte devido às bordas metálicas do suporte de copos, comprometendo a segurança dos colaboradores.', N'Eliminar 100% do risco de cortes nas bordas do suporte de copos com a aplicação de proteção de silicone em todos os suportes.', N'10213', N'01 - Imagens/01 - Antes/11534.jpeg', N'O suporte de copos apresenta bordas metálicas expostas, gerando risco de corte aos colaboradores. Como ação preventiva, foi proposta a instalação de bordas de silicone para eliminar esse risco e melhorar a segurança no local de trabalho.', N'01 - Imagens/02 - Depois/11534.jpeg', N'A melhoria consiste na aplicação de bordas de silicone nas partes metálicas expostas do suporte de copos. Essa solução foi proposta para eliminar o risco de cortes e proporcionar maior segurança durante o uso.', NULL, N'A ação proposta está alinhada à meta inicial de eliminar o risco de cortes.', N'A prevenção é a melhor forma de garantir um ambiente de trabalho seguro.', 0, NULL, N'Foi elaborado e confecionado com material sobressalente um suoporte para acondicionar e armazenar as talhas na vertical, de modo a mantê-las organizadas, livres de enrosco e em condição que não interfere em sua vida útil', '2026-07-29T00:00:00.000', '2026-07-31T15:32:14.000', N'81044397', NULL, NULL);
INSERT INTO #PVC VALUES (11535, N'81030963', N'81055853', N'Robo Otiff - Aderbot', 1, N'Others/Outros', N'O processo de acompanhamento da aderência das separações de materiais era realizado de forma manual, com baixa visibilidade dos resultados e identificação tardia de desvios. As análises demandavam consolidação de dados e atuação reativa, aumentando o risco de retrabalho e impactando o atendimento das OTIFs da Mina e da Usina.', N'Eliminar processo manual e dar celeridade no processo ', N'10079', N'01 - Imagens/01 - Antes/11535.jpeg', N'O controle da aderência das separações era manual, com baixa visibilidade dos resultados, identificação tardia de desvios e maior risco de retrabalho no atendimento das OTIFs.', N'01 - Imagens/02 - Depois/11535.jpeg', N'Com o ADERBOT, o monitoramento tornou-se automático e em tempo real, permitindo identificar desvios rapidamente, agir preventivamente e aumentar a aderência operacional.', NULL, N'Meta:
INSERT INTO #PVC VALUES (11536, N'81050431', N'81058947', N'RECUPERAÇÃO DA TRAVA ', 3, N'Others/Outros', N'TRAVA EM ALTA SITUAÇÃO DE DESGASTE', N'ECONOMIA', N'10139', N'01 - Imagens/01 - Antes/11536.jpeg', N'TRAVA EM ALTA SITUAÇÃO DE DESGASTE, RISCO DE QUEBRA OU ACIDENTE.', N'01 - Imagens/02 - Depois/11536.jpeg', N'RECUPERADO TRAVA PROLONGANDO VIDA ULTIL, EVITANDO CUSTO.', NULL, N'RECUPERADO TRAVA PROLONGANDO VIDA ULTIL, EVITANDO CUSTO.', N'ECONOMIA', 10000, 1, N'Sim. 
INSERT INTO #PVC VALUES (11537, N'522369', N'522369', N'TABELA DE PLANO DE AÇÃO KANBAN ELÉTRICA', 1, N'No Replication/Sem replicação', N'DIFICULDADE DE TER UM CONTROLE DE ROTINA PARA BUSCAR MATERIAIS SEMANALMENTE.', N'MELHORAR PERFORMANCE NA BUSCA DE MATERIAL ATRAVÉS DE UM TABELA SEMANAL.', N'10197', N'01 - Imagens/01 - Antes/11537.jpeg', N'TINHAMOS UMA LISTA DE PENDÊNCIAS SEMANAIS FORA DE CONTROLE NA BUSCA DE MATERIAIS PARA O KANBAN ELÉTRICA.', N'01 - Imagens/02 - Depois/11537.jpeg', N'FOI DESENVOLVIDO UMA TABELA DE PENDÊNCIAS PARA AGILIZAR A ROTINA NA BUSCA DE MATERIAIS DA SEMANAL CORRESPONDENTE.', NULL, N'HOUVE PLANEJAMENTO NA ROTINA DE ABASTECIMENTO NO KANBAN ELÉTRICA.', N'GESTÃO VISUAL DA ROTINAS DE BUSCA DE MATERIAIS SEMANALMENTE.', 0, NULL, N'Ganhos Qualitativos
INSERT INTO #PVC VALUES (11538, N'81050431', N'81058947', N'TRAVA DA BALANÇA', 1, N'Others/Outros', N'ANTES A BALANÇA ERA FIXADA COM SOLDA.', N'SEGURANÇA', N'10139', N'01 - Imagens/01 - Antes/11538.jpeg', N'ANTES A BALANÇA ERA FIXADA POR SOLDA, COM RISCO DE PROJEÇÃO.', N'01 - Imagens/02 - Depois/11538.jpeg', N'FABRICADO UMA TRAVA PARA MELHORA A FIXAÇÃO, ELIMINANDO O RISCO DE PROJEÇÃO.', NULL, N'O SERVIÇO DE SOLDA LEVA E MEDIA DUAS HORAS, SENDO QUE COM A TRAVA A ATIVIDADE É REALIZADA EM 20 MINUTO', N'MELHORIAS ', 0, NULL, N'Redução do tempo de consulta.
INSERT INTO #PVC VALUES (11539, N'81004893', N'81004893', N'Controle de Falhas de Balança e Sobrecarga dos Equipamentos', 1, N'Others/Outros', N'Ocorrência recorrente de falhas no sistema de balança e eventos de sobrecarga nos equipamentos de mina, comprometendo a confiabilidade das informações de carga, aumentando o risco de danos estruturais, reduzindo a vida útil dos componentes e impactando a segurança operacional.', N'aumentando a confiabilidade dos dados operacionais e garantindo aderência aos limites de carga estabelecidos para os equipamentos.', N'#N/A', N'01 - Imagens/01 - Antes/11539.jpeg', N'Falhas recorrentes nos sensores e sistemas de pesagem.
INSERT INTO #PVC VALUES (11540, N'81004893', N'81004893', N'Histórico de Tratamento de Eventos S-1 ', 1, N'Others/Outros', N'Ausência de registro histórico consolidado das tratativas realizadas nos eventos de telemetria S-1, dificultando a rastreabilidade das ações executadas, análise de reincidências e avaliação da efetividade das intervenções.', N'Garantir 100% de rastreabilidade das tratativas dos eventos S-1, disponibilizando histórico padronizado para consulta, acompanhamento e tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/11540.jpeg', N'Condição Antes:
INSERT INTO #PVC VALUES (11541, N'81040303', N'81040303', N'Reestruturação da governança de dados Segurança', 1, N'Others/Outros', N'Anteriormente, os dashboards da área de Segurança eram atualizados a partir de relatórios extraídos manualmente do SAP BW. Diariamente, um analista precisava dedicar aproximadamente 30 minutos para realizar a extração dos dados no período da manhã. Após essa etapa, os arquivos Excel eram atualizados manualmente para que os painéis em Power BI pudessem ser posteriormente atualizados.', N'Disponibilização de +30min diários ( 10h mensais )', N'10293', N'01 - Imagens/01 - Antes/11541.jpeg', N'Os dashboards de Segurança dependiam de extrações manuais diárias do SAP BW, consumindo cerca de 30 minutos por dia para atualização dos dados e dos painéis em Power BI. ', N'01 - Imagens/02 - Depois/11541.jpeg', N'O TechSalobo automatizou a atualização dos dashboards de Segurança, eliminando extrações manuais do SAP BW, reduzindo esforço operacional e aumentando a confiabilidade dos dados.', NULL, N'Disponibilização de +30min diários ( 10h mensais )
INSERT INTO #PVC VALUES (11542, N'478853', N'478853', N'Suporte Calços rodas pesados', 3, N'Others/Outros', N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'Organização e 5s', N'10234', N'01 - Imagens/01 - Antes/11542.jpeg', N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'01 - Imagens/02 - Depois/11542.jpeg', N'Foi confeccionado com materiais sobressalentes um suporte de armazenagem de calços de rodas de equipamentos pesados, com melhoria na condição ergonômica e de organização da area', NULL, N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'Organizaçao', 0, NULL, N'PROPORCIONAR AGILIDADE E QUALIDADE NO TEMPO DE COLETA DE AMOSTRAGEM, GARANTINDO MAIOR EFICIÊNCIA E COMPROMETIMENTO COM O PROCESSO.', '2026-07-07T00:00:00.000', '2026-07-31T19:32:33.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11543, N'478853', N'478853', N'Suporte Mangueira Compressor', 3, N'Others/Outros', N'Ausencia de suporte para organziar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'Organização e 5s', N'10234', N'01 - Imagens/01 - Antes/11543.jpeg', N'Ausencia de suporte para organziar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'01 - Imagens/02 - Depois/11543.jpeg', N'Foi confeccionado suporte com material sobressalente e instalado no compressor, de modo a manter a mangueira do mesmo enrolada e armazenada de maneira organizada e segura.', NULL, N'Ausencia de suporte para organizar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'Organização e 5s', 0, NULL, N'segurança / 5S / Organização do Ambiente', '2026-07-10T00:00:00.000', '2026-07-31T19:40:35.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11544, N'478853', N'478853', N'Central de Montagem de Embarcados', 2, N'Projects/Projetos', N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'Organização, 5s e produtividade', N'10234', N'01 - Imagens/01 - Antes/11544.jpeg', N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'01 - Imagens/02 - Depois/11544.jpeg', N'Foi criado um local adequado para montagem dos sistemas de embarcados, com um ambiente controlado, livre de intempéries, com melhores condições ergonômicas, otimizando as montagem e promovendo maior produtividade para o processo', NULL, N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'Produtividade com ambiente adequado', 0, NULL, N'Safety Compliance. ', '2026-07-02T00:00:00.000', '2026-07-31T19:46:39.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11545, N'478853', N'478853', N'Dispositvo abridor de latas de eletrodos', 2, N'Others/Outros', N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'produtividade', N'10234', N'01 - Imagens/01 - Antes/11545.jpeg', N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'01 - Imagens/02 - Depois/11545.jpeg', N'Desenvolvido e confeccionado um dispositivo utilizado para abertura das latas de eletrodos, com geometria compativel com as latas, de modo a garantir uma rapida abertura das latas de maneira padronizada, sem improvisos', NULL, N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'produtividade', 0, NULL, N'FOI CONFECCIONADO CHAPAS PARA FECHAMENTO DAS ABERTURAS, ASSIM ELIMINANDO O RISCO DE QUEDA.', '2026-07-13T00:00:00.000', '2026-07-31T19:51:26.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11546, N'478853', N'478853', N'Bomba sucção fluidos usados', 2, N'Others/Outros', N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'produtividade e meio ambiente', N'10234', N'01 - Imagens/01 - Antes/11546.jpeg', N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'01 - Imagens/02 - Depois/11546.jpeg', N'Foi dimensionada uma bomba para realizar a sucção das bacias e transbordo diretamente para os recipientes de descarte, eliminando a necessidade de uso da empilhadeira, processos manuais e com funil.', NULL, N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'Produtividade e cuidado com meio ambiente', 0, NULL, NULL, '2026-07-08T00:00:00.000', '2026-07-31T19:58:23.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11547, N'478853', N'478853', N'Suporte talhas manuais', 3, N'Others/Outros', N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'Organização, 5s e conservação da ferramenta', N'10234', N'01 - Imagens/01 - Antes/11547.jpeg', N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'01 - Imagens/02 - Depois/11547.jpeg', N'Foi elaborado e confecionado com material sobressalente um suoporte para acondicionar e armazenar as talhas na vertical, de modo a mantê-las organizadas, livres de enrosco e em condição que não interfere em sua vida útil', NULL, N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'Organização e melhoria da armazenagem', 0, NULL, NULL, '2026-07-02T00:00:00.000', '2026-07-31T20:06:37.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11548, N'478853', N'478853', N'Carrinho transporte cilindro trabalho a quente', 2, N'Others/Outros', N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'Praticidade e produtividade', N'10234', N'01 - Imagens/01 - Antes/11548.jpeg', N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'01 - Imagens/02 - Depois/11548.jpeg', N'Foi realizada a aquisição de carrinhos de transporte de cilindros individuais, de modo a garantir o transporte ate os locais onde a empilhadeira não acessa', NULL, N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'Produtividades e praticidade', 0, NULL, N'Com a implementação das etiquetas padronizada ganhamos clareza e melhor visualizações nas chaves e cadeados.', '2026-07-10T00:00:00.000', '2026-07-31T20:14:13.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11549, N'521817', N'521817', N'RC sem Devoluções: Guia Prático para Elaboração Correta de Requisições de Compra', 1, N'Others/Outros', N'Temos observado um número elevado de RCs devolvidas pelo time de Suprimentos devido a inconsistências no preenchimento das requisições. Identificamos a necessidade de disponibilizar um procedimento passo a passo para criação de RCs, contemplando o correto preenchimento dos campos obrigatórios, a seleção adequada do tipo de requisição e a inclusão de toda a documentação e anexos obrigatórios, a fim de reduzir retrabalhos e agilizar o processo de aprovação.', N'Orientar todos os requisitantes sobre as melhores práticas para elaboração de uma Requisição de Compra (RC), garantindo o correto preenchimento de todos os campos obrigatórios, a seleção adequada do tipo de requisição, a inclusão dos anexos necessários e o fornecimento de informações completas ao comprador, de forma a minimizar devoluções, reduzir retrabalhos e aumentar a eficiência do processo de suprimentos.', N'10234', N'01 - Imagens/01 - Antes/11549.jpeg', N'Temos observado um número elevado de RCs devolvidas pelo time de Suprimentos devido a inconsistências no preenchimento das requisições. Identificamos a necessidade de disponibilizar um procedimento passo a passo para criação de RCs, contemplando o correto preenchimento dos campos obrigatórios, a seleção adequada do tipo de requisição e a inclusão de toda a documentação e anexos obrigatórios, a fim de reduzir retrabalhos e agilizar o processo de aprovação.', N'01 - Imagens/02 - Depois/11549.jpeg', N'Uma RC Spot deve ser elaborada de forma completa e consistente, garantindo o preenchimento de todos os campos obrigatórios, a correta classificação do tipo de requisição, a vinculação de todos os anexos e documentações pertinentes, bem como a inclusão de informações detalhadas no campo de texto descritivo e na nota ao comprador, destacando claramente todas as observações, justificativas e requisitos necessários para o correto processamento da demanda. ', NULL, N'Sim. 
INSERT INTO #PVC VALUES (11550, N'483318', N'483318', N'Desenvolvimento de Planilha Integrada de Indicadores para suporte às Reuniões de Performance da Diretoria de Operação', 1, N'Others/Outros', N'
INSERT INTO #PVC VALUES (11551, N'483318', N'483318', N'Melhoria da Planilha de Equipamentos Autônomos', 1, N'Others/Outros', N'A consulta de informações dos equipamentos autônomos exigia análise individual de TAGs.', N'Implementação de filtros e seleção automática de TAGs na planilha.', N'10323', N'01 - Imagens/01 - Antes/11551.jpeg', N'O ajuste de UF e Prod por tag de cada caminhão autonomo era feito de forma manual, demandando bastante tempo.', N'01 - Imagens/02 - Depois/11551.jpeg', N'Implementação de filtros e seleção automática de TAGs na planilha, lincando os indicadores referente a operação autônoma, apenas fazendo a marcação de um checkbox.', NULL, N'Processo mais intuitivo, com filtros automatizados.', N'Redução de erros de consolidação de metas. Maior velocidade na preparação dos dados.', 0, NULL, N'help with keeping technicians out of harms way and as well assist with ergonomics', '2026-07-01T00:00:00.000', '2026-07-31T21:54:02.000', N'483318', NULL, NULL);
INSERT INTO #PVC VALUES (11552, N'81008286', N'81008286', N'Heating Blanket intructions', 1, N'Refining/Refino', N'programming the temperature on heating blankets was confusing without instructions in field.', N'clarity on how to set up the heating blankets properly', N'0', N'01 - Imagens/01 - Antes/11552.jpeg', N'No instructions in field, blanket temps were often set up wrong or not set at all.', N'01 - Imagens/02 - Depois/11552.jpeg', N'easy to understand instructions added next to heating blankets in field.', NULL, N'Yes. temps have been properly set and should be from here on out.', N'simple easy to understand instructions save time', 0, NULL, N'zero acidentes e vidas mudadas por exposiçao desncessaria', '2026-07-31T00:00:00.000', '2026-08-01T01:59:45.000', N'81008286', NULL, NULL);
INSERT INTO #PVC VALUES (11553, N'92000132', N'81035016', N'JANELA DE VISITA ', 2, N'Others/Outros', N'ANTES NÃO TINHA JANELA PARAFAZER A COLETA DA AMOSTRA ', N'Agilidade e qualidade no tempo de de coleta de amostragem, eficiência e comprometimento com processo.', N'10031', N'01 - Imagens/01 - Antes/11553.jpeg', N'ANTES NÃO TINHA JANELA PARAFAZER A COLETA DA AMOSTRA ', N'01 - Imagens/02 - Depois/11553.jpeg', N'Fabricado janela de visita no ponto de amostragem do 
INSERT INTO #PVC VALUES (11554, N'92000132', N'81016565', N'FABRICAÇÃO JANELA DE VISITA ', 2, N'Others/Outros', N'ANTES NÃO HAVIA JANELA DE VISITA NO PONTO DE AMOSTRAGEM', N'GARANTIR A MELHORIA CONTÍNUA DO PROCESSO, PROPORCIONANDO AGILIDADE E QUALIDADE NO TEMPO DE COLETA DE AMOSTRAGEM, AUMENTANDO A EFICIÊNCIA OPERACIONAL E O COMPROMETIMENTO COM O PROCESSO.', N'10031', N'01 - Imagens/01 - Antes/11554.jpeg', N'ANTES NÃO HAVIA JANELA DE VISITA NO PONTO DE AMOSTRAGEM MO-2014-02', N'01 - Imagens/02 - Depois/11554.jpeg', N'FABRICAÇÃO E INSTALAÇÃO DE JANELA DE VISITA NA DESCARGA DO MOINHO - PONTO POSITIVO DE AMOSTRAGEM.OBJETIVO DA MELHORIA CONTÍNUA:
INSERT INTO #PVC VALUES (11555, N'92000132', N'81035016', N'JANELA DE VISITA MO-2014-01', 2, N'Others/Outros', N'ANTES NÃO HAVIA JANELA DE VISITA NO PONTO DE AMOSTRAGEM', N'GARANTIR A MELHORIA CONTÍNUA DO PROCESSO, PROPORCIONANDO AGILIDADE E QUALIDADE NO TEMPO DE COLETA DE AMOSTRAGEM, AUMENTANDO A EFICIÊNCIA OPERACIONAL E O COMPROMETIMENTO COM O PROCESSO.', N'10031', N'01 - Imagens/01 - Antes/11555.jpeg', N'ANTES NÃO HAVIA JANELA DE VISITA NO PONTO DE AMOSTRAGEM', N'01 - Imagens/02 - Depois/11555.jpeg', N'FABRICAÇÃO E INSTALAÇÃO DE JANELA DE VISITA NA DESCARGA DO MOINHO - PONTO POSITIVO DE AMOSTRAGEM.OBJETIVO DA MELHORIA CONTÍNUA:
INSERT INTO #PVC VALUES (11556, N'547290', N'547290', N'Instalação de suporte para bolsa e capacete na área operacional', 3, N'Others/Outros', N'Os colaboradores não possuem um local adequado e padronizado para acondicionar bolsas e capacetes durante as atividades, fazendo com que os itens sejam deixados em bancadas, mesas ou outros locais inadequados.', N'Eliminar a desorganização ', N'10054', N'01 - Imagens/01 - Antes/11556.jpeg', N'Os colaboradores não possuem um local adequado e padronizado para acondicionar bolsas e capacetes durante as atividades, fazendo com que os itens sejam deixados em bancadas, mesas ou outros locais inadequados.', N'01 - Imagens/02 - Depois/11556.jpeg', N'Fixação de suportes metálicos ou ganchos em local estratégico da área, permitindo que cada colaborador acomode sua bolsa e capacete de forma organizada e segura.', NULL, N'Melhoria da organização e limpeza da área.
INSERT INTO #PVC VALUES (11557, N'1010860', N'1010860', N'Tepid water skid PSV Replacement', 2, N'No Replication/Sem replicação', N'Tepid Water Vessel PSV Was due for recertification', N'Safety Compliance', N'10005', N'01 - Imagens/01 - Antes/11557.jpeg', N'Tepid Water Vessel PSV Was due for recertification. Maintenance did not have resources to complete so operations completed the work.', N'01 - Imagens/02 - Depois/11557.jpeg', N'Equipment was isolated and PSV replaced.', NULL, N'Yes PSV replaced and Equipment back in service', N'Compliance', 0, NULL, N'Não mensurado financeiramente. Benefício relacionado à redução de retrabalho, otimização de mão de obra e aumento da confiabilidade operacional.
INSERT INTO #PVC VALUES (11558, N'81030117', N'553136', N'PROTEÇÃO DE LATERAIS DA PASSARELA PF1601', 1, N'Others/Outros', N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA.', N'ELIMINAR RISCOS DE QUEDA', N'10324', N'01 - Imagens/01 - Antes/11558.jpeg', N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA', N'01 - Imagens/02 - Depois/11558.jpeg', N'FOI CONFECCIONADO CHAPAS PARA FECHAMENTO DAS ABERTURAS, ASSIM ELIMINANDO O RISCO DE QUEDA.', NULL, N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA', N'MAIOR SEGURANÇA NAS ATIVIDADES', 0, NULL, N'It is now more time efficient to log and there is visual reminder of the acceptable range and when to perform the task', '2026-07-25T00:00:00.000', '2026-08-01T17:40:19.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11559, N'81042683', N'81042683', N'Belt Filter 002 Bearing Journal Recovery Through In-House Belzona Repair', 1, N'Refining/Refino', N'A failed bearing journal was identified on Belt Filter 002, resulting in the belt being offline and risk to production continuity. The original replacement component valued at approximately $27,795 CAD, along with expedited freight of approximately $25,500 CAD. In addition to the direct cost, the replacement part carried a delivery delay that would have prolonged equipment downtime.', N'Restore Belt Filter 002 to service while avoiding the cost, lead time, and production impact associated with purchasing and expediting a replacement bearing assembly.', N'0', N'01 - Imagens/01 - Antes/11559.jpeg', N'Belt Filter 002 was offline due to a failed bearing journal.
INSERT INTO #PVC VALUES (11560, N'81042683', N'81042683', N'Development of an In-House Rebuild Program for DE and NDE Air Seals', 1, N'Refining/Refino', N'14 failed DE and NDE air seals were considered beyond repair by the WHSE. Replacement of these seals required the purchase of new units at a significant cost, resulting in high maintenance expenditures and the disposal of otherwise recoverable assets.
INSERT INTO #PVC VALUES (11561, N'486356', N'486356', N'Padronização e identificação visual dos cadeados ', 1, N'Others/Outros', N'Os cadeados de bloqueio não possuíam identificação fixa padrão, sendo identificados por papéis avulsos anotações manuais ou etiquetas improvisadas que se desgastavam facilmente ', N'Melhor identificação e padronização ', N'10209', N'01 - Imagens/01 - Antes/11561.jpeg', N'Os cadeados de bloqueios não possuíam identificação fixa padrão sendo identificados por papéis avulsos e anotações manuais feitas com canetas que se apagavam facilmente.', N'01 - Imagens/02 - Depois/11561.jpeg', N'Com a implementação e padronização de etiquetas adesivas impressas em material de Auta durabilidade é legível ganhamos tempo e rastreabilidade em nossas atividades de bloqueio.', NULL, N'Sim , tínhamos dificuldades em organizar os cadeados que não havia numerações legíveis ', N'Organização e padronização ', 0, NULL, N'Redução significativa do tempo da atividade.', '2026-07-28T00:00:00.000', '2026-08-01T22:48:21.000', N'486356', NULL, NULL);
INSERT INTO #PVC VALUES (11562, N'81023776', N'81023776', N'Slaker draining chute', 1, N'Others/Outros', N'Media in the past was messily drained from slaker resulting in time cleaning up', N'Create less workload', N'0', N'01 - Imagens/01 - Antes/11562.jpeg', N'Media in the past was messily drained from slaker resulting in time cleaning up', N'01 - Imagens/02 - Depois/11562.jpeg', N'Chute was created to funnel slaker media in hopper', NULL, N'Less workload for technicians to clean up', N'Less time wasted cleaning up media', 0, NULL, N'Eliminado derramamento de óleo ao solo e projeção ao colaborador', '2026-04-02T00:00:00.000', '2026-08-02T02:10:49.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11563, N'81023776', N'81023776', N'Magnet chute reject bin', 3, N'Others/Outros', N'Clean packs were utilized to contain magnet reject resulting in cost to continue replacing them', N'Have a bin available to keep reusing', N'0', N'01 - Imagens/01 - Antes/11563.jpeg', N'Clean packs were utilized to contain magnet reject resulting in cost to continue replacing them', N'01 - Imagens/02 - Depois/11563.jpeg', N'Reusable hopper was placed instead of clean packs to have ease of dumping and reuse instead of wasting cost replacing clean packs', NULL, N'Yes', N'Consumable items may have a reusable replacement', 1000, 3, N'Maior controle sobre os principais geradores de paradas, redução da atuação reativa da manutenção, aumento da previsibilidade operacional e sustentação das metas de MTBF por meio da identificação e tratamento antecipado dos modos de falha críticos.', '2026-07-01T00:00:00.000', '2026-08-02T02:17:15.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11564, N'81023776', N'81023776', N'Vice on lime laydown', 1, N'Others/Outros', N'technicians not able to clamp down work pieces ', N'Help technicians hold work pieces when using laydown table', N'0', N'01 - Imagens/01 - Antes/11564.jpeg', N'Technicians did not have an available vice to help with work on the lime laydown table', N'01 - Imagens/02 - Depois/11564.jpeg', N'A new vice was implemented and attached to the lime laydown table to assist technicians with clamping work pieces when needed helping with ergonomics and safety', NULL, N'Yes', N'Safety 1rst ', 0, NULL, N'Disponibilizar uma visão executiva e padronizada da saúde dos ativos, facilitando o entendimento dos riscos por todos os níveis da organização, acelerando o direcionamento das cadeias de ajuda e apoiando decisões mais assertivas sobre manutenção e confiabilidade.', '2026-07-01T00:00:00.000', '2026-08-02T02:22:01.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11565, N'81037517', N'87001735', N'dispositivo travamento da engrenagem do compressor', 1, N'Others/Outros', N'dispositivo  retirada do acomplamento de borracha do compressor (remoçao e instalaçao)', N'zero  acidente ', N'10324', N'01 - Imagens/01 - Antes/11565.jpeg', N'Durante a atividade de desacoplamento e acoplamento da engrenagem do compressor, foi identificada a ausência de um dispositivo de travamento padronizado capaz de impedir movimentos involuntários nos sentidos horário e anti-horário. Como alternativa para execução da tarefa, foram utilizados acessórios e ferramentas não padronizados, aumentando a exposição a desvios operacionais, dificuldades na execução da atividade e riscos de segurança para os envolvidos.', N'01 - Imagens/02 - Depois/11565.jpeg', N'foi feito dispositivo que trava de forma horaria e anti horario de forma segura o movimento da engrenagem evitando esmagamento e cortes dilaceraçoes e outros caidentes correlacionado ao movimento e travamento inadequado da engrenagem', NULL, N'sim, e retirado exposiçao por ferramentas inadequadas', N' necessario desenvolver dispositivo para nao usar recursos inadequados ', 0, NULL, N'Aumentar a visibilidade sobre o consumo de óleo hidráulico da frota, permitindo a identificação precoce de vazamentos, redução das perdas de óleo, diminuição de custos e maior agilidade na tomada de decisão.', '2026-05-20T00:00:00.000', '2026-08-02T03:13:41.000', N'81037517', NULL, NULL);
INSERT INTO #PVC VALUES (11566, N'81037517', N'81056020', N'corrimao de proteçao  para Reduçao de exposiçao a riscos e uso constante de andaime e plataforma no complento de oleo redutor ', 1, N'Projects/Projetos', N'Atualmente, as atividades de coleta e complemento de óleo do redutor de avanço exigem, de forma recorrente, a mobilização de plataforma elevatória e/ou montagem de andaime para acesso aos pontos de intervenção. Essa condição aumenta significativamente o tempo de manutenção devido à necessidade de montagem e desmontagem das estruturas de acesso, além de gerar custos adicionais com alocação de equipamentos. Também expõe os trabalhadores a riscos desnecessários associados ao trabalho em altura e à utilização de equipamentos motorizados para acesso suspenso, impactando a segurança, a produtividade e a disponibilidade do equipamento.', N' reduçao de custo e exposiçao  ', N'10324', N'01 - Imagens/01 - Antes/11566.jpeg', N'antes o colaborador subia e ficava exposto pela movimentação parte superior do equipamento    sem proteção  padrão com 03 pontos de acesso, e ou exposição a equipamentos de acessos ', N'01 - Imagens/02 - Depois/11566.jpeg', N'Foi desenvolvida e instalada uma plataforma fixa com escada e guarda-corpo para acesso seguro aos pontos de inspeção, coleta e reposição de óleo. A implementação dessa melhoria elimina a necessidade frequente de montagem e desmontagem de andaimes e da utilização de plataformas elevatórias, reduzindo custos operacionais e tempo de manutenção. Além disso, proporciona maior segurança aos colaboradores ao reduzir a exposição a riscos associados ao trabalho em altura e ao uso de equipamentos de acesso motorizados, contribuindo para a diminuição do tempo de parada dos ativos e aumento da produtividade das intervenções.', NULL, N'Comparação com a meta inicial / declaração do problema
INSERT INTO #PVC VALUES (11567, N'1008445', N'1008445', N'Cobalt Inventory Memo', 1, N'No Replication/Sem replicação', N'We are currently using NiEW Feed Tank #1 as surge capacity for Co solution. They weren''t a management plan for maintaining levels in the circuit', N'Standardize inventory management amongst all shifts', N'0', N'01 - Imagens/01 - Antes/11567.jpeg', N'We are using the NiEW Feed Tank #1 for Co solution surge. There was no direction on when to feed to the NiEW Feed Tank or when to bring solution back', N'01 - Imagens/02 - Depois/11567.jpeg', N'A tank level management plan memo was developed to standardize when to send to or receive solution from the NiEW Feed Tank', NULL, N'Yes', N'Memo Created', 0, NULL, N'Disponibilização de uma base de HH confiável e criação do primeiro estudo técnico de dimensionamento da equipe de Automação, trazendo maior visibilidade da carga de trabalho e suporte para decisões relacionadas à adequação do quadro de pessoal.', '2026-07-05T00:00:00.000', '2026-08-02T03:58:30.000', N'1008445', NULL, NULL);
INSERT INTO #PVC VALUES (11568, N'609694', N'609694', N'Dust collection box', 3, N'Underground/Subterrâneo', N'We installed an industrial vacuum at 3090. The unit is working really good. Now that we started the process-  we come to realize that when the debris box empties out - lots of dust gets air born  because of the ventilation in the area. we could not have known this until we actually got going with the project ', N'Stop dust from becoming air born', N'10260', N'01 - Imagens/01 - Antes/11568.jpeg', N'when debris box empties out the vent spreads the dust all over ', N'01 - Imagens/02 - Depois/11568.jpeg', N'We build a dust collection box around the bottom of the debris box that will stop vent and allow the dust to go in the hole ', NULL, N'yes ', N'All is possible ', 1, 3, N'Implementar uma priorização estruturada dos estudos de LDA e extensão de vida útil, direcionando os recursos para ativos com maior disponibilidade de dados e potencial de geração de resultados.', '2026-08-01T00:00:00.000', '2026-08-02T12:46:28.000', N'609694', NULL, NULL);
INSERT INTO #PVC VALUES (11569, N'81063699', N'81063699', N'Fixação definitiva do suporte de pincéis e apagador na parede', 3, N'Others/Outros', N'O suporte de pincéis e apagador encontrava-se fixado à parede por meio de fita adesiva/cola. Devido à textura da superfície e ao peso dos materiais armazenados, a fixação perdia aderência frequentemente, ocasionando a queda do suporte, danos ao dispositivo, desorganização da área e necessidade de retrabalho para reinstalação.', N'Eliminar a queda recorrente do suporte de pincéis e apagador através da fixação mecânica na parede, garantindo organização, conservação do material e segurança da área.', N'10346', N'01 - Imagens/01 - Antes/11569.jpeg', N'Suporte fixado com fita adesiva, desprendendo-se e caindo constantemente.', N'01 - Imagens/02 - Depois/11569.jpeg', N'Suporte fixado com parafusos e buchas, permanecendo estável e disponível para uso contínuo.', NULL, N'O problema foi resolvido. O suporte, que anteriormente era fixado por fita adesiva e sofria quedas frequentes devido à perda de aderência, passou a ser fixado por meio de parafusos e buchas. Após a implementação, não foram observadas novas quedas, garantindo maior segurança, organização e eliminando a necessidade de retrabalho com recolagens frequentes.', N'Fixações realizadas apenas com fita adesiva em superfícies texturizadas apresentam baixa confiabilidade. A utilização de fixação mecânica (parafusos e buchas) aumenta a durabilidade, segurança e estabilidade dos dispositivos de organização.', 0, NULL, N'maior segurança no armazenamento de material. ', '2026-08-01T00:00:00.000', '2026-08-02T14:26:19.000', N'81063699', NULL, NULL);
INSERT INTO #PVC VALUES (11570, N'81042078', N'81050572', N'Sistema Inteligente de Análise e Rastreabilidade das Células dos Bancos de Baterias por Meio de Relatório Automatizado', 1, N'Others/Outros', N'A ausência de um sistema de monitoramento e rastreabilidade das células dos bancos de baterias dificultava o controle histórico das medições e a identificação de desvios de tensão, resistência interna e temperatura. Como consequência, havia necessidade de novas inspeções para confirmação dos resultados, aumento do tempo de diagnóstico, retrabalho nas atividades de manutenção e menor assertividade na tomada de decisão para substituição de células, impactando a eficiência e a confiabilidade operacional do processo. 
INSERT INTO #PVC VALUES (11571, N'1010294', N'1010294', N'TSS Oven Temp Signage', 1, N'Refining/Refino', N'Logging of TSS oven temperatures are sometimes missed and finding the location of the file can be difficult.', N'Reminder and direction on when and how to track TSS Oven Temperatures', N'10352', N'01 - Imagens/01 - Antes/11571.jpeg', N'Signage and location of logging file was absent for when to complete TSS oven temperature check.', N'01 - Imagens/02 - Depois/11571.jpeg', N'When and where to log the TSS oven temperatures are now posted directly on the TSS Oven door to easy reference.', NULL, N'Yes, easy to reference and visual reminder.  More efficient use of time', N'Visual Aid to trigger data collection', 0, NULL, N'This will also ensure that our targets will be met and zero harm to employees', '2026-08-01T00:00:00.000', '2026-08-02T17:05:58.000', N'1010294', NULL, NULL);
INSERT INTO #PVC VALUES (11572, N'81045248', N'81052061', N'Wharf Conveyor Curtain size chart ', 1, N'Concentration/Concentração', N'not all curtains on the conveyor belts are the same size. When a curtain needs to be ordered we have to sometimes measure the curtain and order a new one using those measurements. If those measurements are not correct, we could order curtains that are not the right size. They are non refundable or returnable, so this could waste money', N'accurate ordering information ', N'0', N'01 - Imagens/01 - Antes/11572.jpeg', N'curtains can tear or become damaged. They are not all the same size, some need openings for pull cords or outlets, ect.  it can become dirty and the sizing information can be illegible. There have been times when a curtain was ordered and it did not fit. Curtains are not returnable or refundable, this could lead to unnecessary costs incurred. ', N'01 - Imagens/02 - Depois/11572.jpeg', N'Created a spreadsheet indicating correct sizes for each curtain along the conveyor. There''s 172 curtains on the wharf conveyor. This eliminates guessing or incorrect measuring. The ordering information for each curtain along the conveyor and its special specifications are included. ', NULL, N'over the course of a year we could order anywhere from 5-10 curtain replacements if not more. Now, we eliminate potentially ordering incorrect sizes', N'measure once', 5000, 3, N'MELHORIA PRODUTIVIDADE', '2026-08-02T00:00:00.000', '2026-08-03T00:21:01.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (11573, N'81045248', N'81045248', N'handle cover', 2, N'Others/Outros', N'there are a few places where the handles of a blind are sticking out at angles that have the potential to come in contact with your body. Some are at chest level, some at eye level and some at knee or shin level. ', N'protect body from injury ', N'0', N'01 - Imagens/01 - Antes/11573.jpeg', N'sometimes there are handles that stick out that might be in the path that you are walking. This one in particular has been painted orange to raise awareness, but it is not at eye level and often gets missed. Hitting your shin or knee off of this can be really painful and has the potential to injure a person', N'01 - Imagens/02 - Depois/11573.jpeg', N'a foam roller or "Pool noodle" cut down to size and placed over the handle has helped to minimize the impact in the event that someone accidentally bumps into it. ', NULL, N'if you accidentally hit your shin or knee off of this handle, you will not hurt yourself nearly as much as you would if you hit it directly on the metal ', N'spacial awareness ', 0, NULL, NULL, '2026-08-02T00:00:00.000', '2026-08-03T01:06:07.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (11574, N'539631', N'81048571', N'Engate para avanço e retração do cilindro de direção com nitrogênio', 2, N'Open Pit/Poço aberto', N'A instalação do cilindro de direção da frota 797F exige manipulação manual para extensão e retração do cilindro, expondo o colaborador a risco ergonômico e contaminação do componente.', N'Reduzir risco ergonômico e evitar contaminação do componente', N'10140', N'01 - Imagens/01 - Antes/11574.jpeg', N'Anteriormente, o avanço e retração do cilindro eram feitos manualmente, expondo o colaborador a risco ergonômico e o componente a risco de contaminação.', N'01 - Imagens/02 - Depois/11574.jpeg', N'Foi confeccionado um dispositivo para acoplar o reservatório de nitrogênio ao cilindro de direção, realizando o avanço e retração sem risco para o colaborador, e sem risco de contaminação.', NULL, N'O problema foi resolvido, o colaborador não fica mais exposto à risco ergonômico e o componente permanece isolado, entrando em contato apenas com o nitrogênio.', N'Nossas ferramentas do dia a dia podem nos ajudar em outras atividades além das que já utilizamos habitualmente', 0, NULL, N'Redução de tempo na identificação de demandas a tratar.', '2026-08-02T00:00:00.000', '2026-08-03T05:53:24.000', N'539631', NULL, NULL);
INSERT INTO #PVC VALUES (11575, N'539631', N'81048571', N'Mangueira de retorno de óleo para instalação do cilindro de direção.', 1, N'Open Pit/Poço aberto', N'Pela ausência de linha de drenagem, durante a extensão ou retração do cilindro pode ocorrer derramamento de óleo.', N'Evitar derramamento de óleo, direcionando corretamente para o coletor de óleo', N'10140', N'01 - Imagens/01 - Antes/11575.jpeg', N'Ao realizar extensão ou retração do cilindro havia derramamento de óleo e projeção', N'01 - Imagens/02 - Depois/11575.jpeg', N'Após confecção da melhoria, foi eliminado o derramamento de óleo e projeção ao colaborador. Além disso, foi reduzido o tempo gasto com limpeza do óleo derramado.', NULL, N'Problema foi sanado, eliminado derramamento de óleo e projeção.', N'Todo processo pode ser melhorado', 0, NULL, N'Reuse of approximately 420 tonnes (200 m³) of suitable excavated material between projects, eliminating unnecessary disposal and reducing material procurement, transportation costs, and landfill utilization.', '2026-08-02T00:00:00.000', '2026-08-03T06:08:06.000', N'539631', NULL, NULL);
INSERT INTO #PVC VALUES (11576, N'81059325', N'81047211', N'Gestão Semanal do Perfil de Perdas para Atingimento do MTBF - Escavação e Carregamento', 1, N'Others/Outros', N'O acompanhamento da confiabilidade das frotas era realizado principalmente por meio do MTBF, indicador que demonstra os resultados após a ocorrência das falhas. A ausência de uma ferramenta de monitoramento dos principais sistemas geradores de paradas dificultava a identificação antecipada de desvios e a priorização de ações de manutenção.
INSERT INTO #PVC VALUES (11577, N'81059325', N'81047211', N'Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento', 1, N'Others/Outros', N'O CMA realizava o monitoramento preditivo dos ativos, porém as informações estavam distribuídas em diferentes laudos e relatórios. A ausência de um painel gerencial consolidado dificultava a visualização da condição da frota, a comunicação dos riscos, o alinhamento das ações e a tomada de decisão nas reuniões S-1 e M-1.', N'Desenvolver e implantar um Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento, consolidando em uma única visão executiva as informações dos métodos preditivos, de forma simples e intuitiva, permitindo que todos os níveis hierárquicos identifiquem rapidamente a condição dos ativos, direcionem as cadeias de ajuda necessárias e apoiem a tomada de decisão nas reuniões S-1 e M-1.', N'10015', N'01 - Imagens/01 - Antes/11577.jpeg', N'O monitoramento dos ativos era realizado pelo Centro de Monitoramento de Ativos (CMA) por meio dos métodos preditivos disponíveis. Entretanto, não existia um painel gerencial consolidado para apresentação nas reuniões semanais (S-1) e mensais (M-1), permitindo visualizar de forma rápida a condição geral das frotas. As informações encontravam-se dispersas em diferentes laudos e relatórios técnicos, dificultando a comunicação dos riscos, o alinhamento entre as equipes e a tomada de decisão gerencial.', N'01 - Imagens/02 - Depois/11577.jpeg', N'Foi desenvolvido um Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento, consolidando em uma única visão os resultados de análise de óleo, vibração, termografia, ultrassom e telemetria. O painel passou a ser utilizado nas reuniões S-1 e M-1, permitindo identificar rapidamente os ativos classificados como Normal, Monitorar ou Crítico, facilitando a comunicação dos riscos, a priorização das ações e a tomada de decisão em todos os níveis da organização.', NULL, N'Sim. O objetivo foi atingido com a implantação de um painel gerencial consolidado para acompanhamento dos resultados preditivos. A ferramenta passou a fornecer uma visão clara e intuitiva da condição das frotas, permitindo que qualquer nível hierárquico compreenda rapidamente os principais riscos e as ações necessárias para mitigá-los, tornando as reuniões S-1 e M-1 mais objetivas e assertivas.', N'A consolidação de informações técnicas em uma ferramenta visual e padronizada facilita a comunicação entre os diferentes níveis da organização, melhora o alinhamento das ações e torna a tomada de decisão mais ágil e eficiente.', 0, NULL, N'Diminuição de paradas corretivas', '2026-07-31T00:00:00.000', '2026-08-03T09:10:27.000', N'81059325', NULL, NULL);
INSERT INTO #PVC VALUES (11578, N'81059325', N'81047211', N'Painel de Monitoramento do Consumo de Óleo Hidráulico das Escavadeiras PC5500-6D', 1, N'Others/Outros', N'Não existia uma ferramenta gerencial para acompanhamento sistemático do consumo de óleo hidráulico das escavadeiras durante as reuniões S-1 e M-1. A ausência de visibilidade consolidada dificultava a identificação precoce de desvios, atrasando o tratamento de vazamentos e aumentando o risco de elevação dos custos com reposição de óleo.', N'Desenvolver e implantar um painel de monitoramento do consumo de óleo hidráulico das escavadeiras PC5500-6D para acompanhamento nas reuniões S-1 e M-1, possibilitando a identificação precoce de desvios de consumo, direcionamento das ações corretivas e mitigação de vazamentos que possam gerar impactos operacionais e financeiros.', N'10015', N'01 - Imagens/01 - Antes/11578.jpeg', N'O acompanhamento do consumo de óleo hidráulico era realizado de forma pontual, sem uma visão consolidada das tendências de consumo por equipamento. Isso dificultava a identificação antecipada de desvios e o direcionamento das ações para eliminação de vazamentos.', N'01 - Imagens/02 - Depois/11578.jpeg', N'Foi desenvolvido um painel gerencial para acompanhamento semanal e mensal do consumo de óleo hidráulico das escavadeiras PC5500-6D. A ferramenta permite identificar rapidamente equipamentos com consumo acima do esperado, investigar as causas dos desvios, definir ações de mitigação e monitorar a evolução dos resultados durante as reuniões S-1 e M-1.', NULL, N'Sim. O painel foi implantado e incorporado às rotinas das reuniões S-1 e M-1, proporcionando visibilidade consolidada do consumo de óleo hidráulico da frota, identificação antecipada de desvios e suporte à tomada de decisão para mitigação de vazamentos e redução de perdas.', N'O monitoramento contínuo de indicadores de consumo permite identificar desvios antes que se tornem eventos de grande impacto, direcionando ações mais rápidas e reduzindo custos associados a vazamentos e perdas de fluido hidráulico.', 0, NULL, N'People are self-aware and drinking more water.', '2026-07-31T00:00:00.000', '2026-08-03T09:23:06.000', N'81059325', NULL, NULL);
INSERT INTO #PVC VALUES (11579, N'81050579', N'517587', N'Alarme de Locomoção ', 2, N'Projects/Projetos', N'Anteriormente, o alarme de locomoção estava instalado no cavalete do mastro do equipamento, o que dificultava a execução da manutenção. Para a substituição do componente, era necessária a utilização de Plataforma Elevatória.', N'eliminar risco de queda de altura, facilita na manutenção', N'10144', N'01 - Imagens/01 - Antes/11579.jpeg', N'Anteriormente, o alarme de locomoção estava instalado no cavalete do mastro do equipamento, o que dificultava a execução da manutenção. Para a substituição do componente, era necessária a utilização de Plataforma Elevatória.', N'01 - Imagens/02 - Depois/11579.jpeg', N'Efetivou-se a mudança de posicionamento do componente. A nova localização proporciona maior ergonomia e acessibilidade para as atividades de manutenção, dispensando o uso de Plataforma Elevatória e eliminando a exposição ao risco de queda em altura.', NULL, N'Sim', N'Sentimento de Dono ', 0, NULL, N'mais autonomia aos autorizados.', '2026-07-29T00:00:00.000', '2026-08-03T12:53:15.000', N'81050579', NULL, NULL);
INSERT INTO #PVC VALUES (11580, N'81053475', N'81053475', N'Saneamento de Dados e Quantificação da Demanda de Headcount da Equipe de Automação', 1, N'Others/Outros', N'A equipe de Automação não possuía uma base de HH confiável e estruturada, dificultando a quantificação da demanda de trabalho e a definição da necessidade adequada de mão de obra para as atividades de execução e inspeção.', N'Sanear e padronizar a base de HH da equipe de Automação, desenvolvendo um estudo estruturado para quantificar a demanda de HC necessária para execução e inspeção, aumentando a assertividade no planejamento de recursos.', N'10015', N'01 - Imagens/01 - Antes/11580.jpeg', N'A base de HH apresentava inconsistências e não existia um estudo estruturado que permitisse avaliar tecnicamente a demanda de mão de obra necessária para atender as atividades de execução e inspeção da equipe.', N'01 - Imagens/02 - Depois/11580.jpeg', N'Base de HH saneada e padronizada, com informações confiáveis para análise. Desenvolvimento do primeiro estudo estruturado de dimensionamento da equipe de Automação, permitindo quantificar a demanda necessária de HC para execução e inspeção.', NULL, N'Foi realizado o saneamento da base de HH, eliminando inconsistências e padronizando as informações registradas. Com os dados tratados, foi desenvolvido o primeiro estudo estruturado de dimensionamento da equipe de Automação, contemplando as atividades de execução e inspeção e permitindo quantificar tecnicamente a necessidade de HC para atendimento das demandas operacionais.', N'A qualidade dos dados é um fator crítico para o sucesso dos estudos de dimensionamento. O saneamento prévio das informações e a validação das premissas aumentam significativamente a confiabilidade dos resultados.', 0, NULL, N'Aumentar a segurança na movimentação de tambores, padronizar o processo de transporte, melhorar as condições ergonômicas da atividade e elevar a eficiência das intervenções de manutenção.', '2026-07-08T00:00:00.000', '2026-08-03T14:54:31.000', N'81053475', NULL, NULL);
INSERT INTO #PVC VALUES (11581, N'81054419', N'81054419', N'Estruturação da Priorização dos Estudos de LDA e Extensão de Vida Útil com Base em Similaridade de Ativos e Disponibilidade de Dados', 1, N'Underground/Subterrâneo', N'A carteira de ativos demandando estudos de LDA e avaliações de extensão de vida útil apresentava elevado volume e recursos limitados para execução. Além disso, não existia um critério padronizado para priorização, resultando em dificuldades na definição dos ativos com maior potencial de obtenção de resultados no curto prazo.', N'Classificar 100% dos ativos candidatos a estudos de LDA e extensão de vida útil em níveis de prioridade, permitindo a elaboração de um roadmap estruturado para execução dos estudos e otimização da utilização dos recursos de engenharia.', N'10015', N'01 - Imagens/01 - Antes/11581.jpeg', N'Estudos de LDA e extensão de vida útil eram priorizados sem critério padronizado, dificultando o direcionamento dos recursos de engenharia.', N'01 - Imagens/02 - Depois/11581.jpeg', N'Ativos classificados por similaridade e disponibilidade de dados, permitindo priorização estruturada, roadmap definido e foco nos estudos de maior potencial de resultado.', NULL, N'A ausência de critérios de priorização foi eliminada por meio da classificação dos ativos conforme similaridade e disponibilidade de dados. Com isso, foi possível estruturar um roadmap de execução, aumentar a assertividade na seleção dos estudos e otimizar a aplicação dos recursos de engenharia.', N'Ativos classificados por similaridade e disponibilidade de dados, permitindo priorização estruturada, roadmap definido e foco nos estudos de maior potencial de resultado.', 0, NULL, N'Helps to keep vehicles clean', '2026-07-31T00:00:00.000', '2026-08-03T15:16:37.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (11582, N'81020787', N'81020787', N'Porta paletes', 2, N'Others/Outros', N'Porta paletes sem nivelamento e falta de travas de segurança.', N'Melhorar a segurança do CTM', N'10234', N'01 - Imagens/01 - Antes/11582.jpeg', N'Porta paletes desnivelado, com falta de batente e travas de segurança.', N'01 - Imagens/02 - Depois/11582.jpeg', N'Novo porta palete com todas as travas de segurança.', NULL, N'Sim, maior segurança no armazenamento de material. ', N'Segurança', 0, NULL, N'Segurança: Eliminar o risco de vazamento de combustível e incêndio devido a quebra de filtros por impacto.
INSERT INTO #PVC VALUES (11583, N'81020787', N'81020787', N'Isolamento de segurança', 2, N'Others/Outros', N'área estava sem opção de isolamento no local de operação de equipamento. ', N'Mitigar a trânsito de pessoas na área de operação.', N'10234', N'01 - Imagens/01 - Antes/11583.jpeg', N'Sem dispositivo de isolamento.', N'01 - Imagens/02 - Depois/11583.jpeg', N'Com dispositivo para isolar a área de operação.', NULL, N'Com esse dispositivo instalado, temos como isolar e mitigar o trânsito de pessoas durante a operação.', N'Segurança', 0, NULL, N'Safer CSE', '2026-07-31T00:00:00.000', '2026-08-03T16:34:13.000', N'81020787', NULL, NULL);
INSERT INTO #PVC VALUES (11584, N'400428', N'400428', N'Unsafe Condition reporting', 2, N'Underground/Subterrâneo', N'Completed unsafe condition cards were being misplaced and not entered, reducing our actual target numbers', N'To have a centralized spot to place completed unsafe condition cards', N'10058', N'01 - Imagens/01 - Antes/11584.jpeg', N'No standard spot for employees to place completed unsafe condition cards, thereby increasing the chances of misplacing and not entering them.', N'01 - Imagens/02 - Depois/11584.jpeg', N'Creating a standard spot for completed cards and informing employees ', NULL, N'Yes. Problem was solved and awareness of potential hazards will make it to employees ', N'Will reduce misplaced cards and potential of employees not hearing of hazards', 0, NULL, N'Reduzir o tempo de exportação dos PDFs e padronizar a formatação dos arquivos enviados à turma de manutenção, acabando com a instabilidade e o risco de omissão de dados.', '2026-08-02T00:00:00.000', '2026-08-04T00:03:33.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (11585, N'81024026', N'81024026', N'Proteção para swith de  acionamento controle remoto', 2, N'Projects/Projetos', N'TODA VEZ OPERADOR DESLIGAVA COM O BRAÇO ACIDENTALMENTE  SISTEMA  DE CONTROLE REMOTO CAUSANDO FALHA NO EQUIPAMENTO', N'Evitar que braço do operador acione acidentalmente o swith', N'10137', N'01 - Imagens/01 - Antes/11585.jpeg', N'ANTERIORMENTE NÃO TINHA A PROTEÇÃO E CONSTEMENTE ERAMOS ACIONADOS PARA VERIFICAR FALHA NO EQUIPAMENTO E MAQUINA ENTRANDO NO CODIGO', N'01 - Imagens/02 - Depois/11585.jpeg', N'COM A PROTEÇÃO MELHORAMOS A SEGURANÇA OPERACIONAL E A PRODUTIVIDADE EVITANDO EQUIPAMENTO ENTRAR NO CODIGO', NULL, N'MELHOROU A EFICIENCIA DO EQUIPAMENTO', N'MELHORA DA SEGURANÇA OPERACIONAL', 2, 1, N'Redução do tempo de limpeza e manutenção, maior agilidade na drenagem da caixa, menor esforço da equipe e aumento da disponibilidade do equipamento.', '2026-08-03T00:00:00.000', '2026-08-04T00:10:07.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11586, N'1014096', N'1014096', N'Aging Kit Storage Clean Up', 1, N'Others/Outros', N'Items are removed from warehouse inventory and placed into Kits for work order execution. A large backlog of items had accumulated from as far back as 2020.', N'Reduce the number of unclaimed equipment sitting in kit storage.', N'10210', N'01 - Imagens/01 - Antes/11586.jpeg', N'Approximately $5.7M dollars worth of equipment was sitting in kit storage from aging WOs (2024 & older) and was not readily available for use.', N'01 - Imagens/02 - Depois/11586.jpeg', N'Low value work was stood down and tied up material was returned to inventory or sent for value recovery. This meant high value work could be executed, and the components were put to productive use.', NULL, N'74% of the value of items from 2024 and older were cleaned up and the remaining items have plans to get them cleaned up. A solid plan exists to do the same for items from 2025.', N'Not every good idea is high enough value to pursue.', 5000000, 3, N'Com a implantação das placas de identificação dos Pousos 1 e 2, foi possível transformar um conhecimento informal em um padrão visual acessível a todos, aumentando a organização da área, a eficiência operacional e a confiabilidade do processo de gestão das tampas dos vagões de cobre.', '2026-08-03T00:00:00.000', '2026-08-04T08:10:29.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11587, N'92000100', N'92000100', N'Acompanhamento empenho YEM', 1, N'Others/Outros', N'Já existia controle dos empenhos por tipo de ordem e ano, porém não havia um painel específico para gestão das ordens YEM, que não devem permanecer empenhadas por longos períodos. Sem essa visão detalhada, os responsáveis priorizavam a tratativa dos empenhos por ano, reduzindo o foco no acompanhamento e na regularização das ordens YEM.', N'Melhorar visibilidade das ordens empenhadas em YEM', N'10234', N'01 - Imagens/01 - Antes/11587.jpeg', N'Ausência de painel específico e detalhado para a gestão das ordens YEM, que, por sua natureza, não devem permanecer empenhadas por longos períodos, por se tratarem de ordens de atendimento a corretiva emergencial. Dessa forma, a ausência dessa visão dedicada dificultava a identificação e o tratamento dessas ordens.', N'01 - Imagens/02 - Depois/11587.jpeg', N'A criação do painel detalhado das ordens YEM empenhadas permitiu identificar gaps na tratativa, além de evidenciar os valores por frota e responsável. Essa visibilidade possibilitou direcionar as ações de forma mais assertiva, focando nos responsáveis e nas ordens que demandam maior atenção e prioridade.', NULL, N'Com a criação desse painel, foi possível ver progresso na tratativa e consequentemente redução no valor empenhado.', N'A criação do painel evidenciou que uma visão específica para ordens YEM é essencial para identificar gaps, direcionar responsabilidades, priorizar ações e reduzir o tempo de permanência dos empenhos, tornando a gestão mais eficiente e assertiva.', 0, NULL, N'RESTABELECIMENTO DO ACESSO SEGURO AO INTERIOR DO CHUTE PARA LIMPEZA E MANUTENÇÕES ', '2026-07-30T00:00:00.000', '2026-08-04T10:49:11.000', N'92000100', NULL, NULL);
INSERT INTO #PVC VALUES (11588, N'607274', N'607274', N'Diverting Excavated Material from Landfill Through Beneficial Reuse', 1, N'Projects/Projetos', N'Approximately 420 tonnes (200 m³) of clean excavated roadbed material from the Creighton Dam & Ditch project was planned for disposal at the CTA Landfill, while the nearby Meatbird Recreation Area Rehabilitation project required imported backfill. This resulted in unnecessary material procurement, transportation costs and landfill utilization. The opportunity was identified through project team and contractor coordination during construction execution planning.', N'Reuse / less material to landfill', N'10225', N'01 - Imagens/01 - Antes/11588.jpeg', N'Prior to implementation of the Kaizen, approximately 420 tonnes (200 m³) of clean excavated roadbed material from the Creighton Dam & Ditch project was designated for transport and disposal at the CTA Landfill. At the same time, the nearby Meatbird Recreation Area Rehabilitation project was scheduled to purchase and import granular backfill material for pump station foundation construction. This approach resulted in avoidable transportation, disposal, and material procurement costs, increased landfill utilization, and additional construction activities. The opportunity to utilize the excavated material at the Meatbird project had not yet been identified.', N'01 - Imagens/02 - Depois/11588.jpeg', N'Although the material consists of clean Granular A and Granular B aggregates, it is not suitable for reuse within the Creighton Dam & Ditch project because excavation activities have blended the material layers, preventing compliance with project-specific material requirements. By redirecting suitable excavated material from the Creighton Dam & Ditch project to the nearby Meatbird Recreation Area Rehabilitation project, transportation and material procurement costs were reduced while minimizing landfill utilization and supporting more efficient project execution.', NULL, N'Yes. The identified inefficiency was eliminated by reusing suitable excavated material between the two projects, reducing disposal, transportation, and material procurement requirements while achieving cost and sustainability benefits', N'Early identification of material-sharing opportunities between projects can eliminate unnecessary disposal, procurement, and transportation costs while maximizing the value of existing resources.', 0, NULL, N'A solução demonstra ganhos relevantes em segurança operacional, ergonomia, produtividade, mobilidade operacional e custo-benefício, reduzindo significativamente a necessidade de estruturas auxiliares convencionais, como andaimes e linhas de vida fixas. Destaca-se ainda a rapidez de mobilização, facilidade de aplicação em diferentes terrenos e ambientes, aderência às normas NR10, NR12 e NR35, além da redução da exposição dos executantes a riscos operacionais.', '2026-07-15T00:00:00.000', '2026-08-04T10:56:21.000', N'607274', NULL, NULL);
INSERT INTO #PVC VALUES (11589, N'81050243', N'81050243', N'PZ35 - Implementação de bomba d''água de 4 pistões', 1, N'Others/Outros', N'A bomba d’água descontinuada apresentava recorrentes entradas de ar no sistema devido a falhas de lubrificação nos copos dosadores dos eixos dos pistões de bombeamento de água. Além disso, sua vida útil era inferior a 3.000 horas de operação, comprometendo a confiabilidade e a disponibilidade do equipamento.', N'Ganhos na UF,DF e confiabilidade do ativo ', N'0', N'01 - Imagens/01 - Antes/11589.jpeg', N'A bomba d’água descontinuada apresentava recorrentes entradas de ar no sistema devido a falhas de lubrificação nos copos dosadores dos eixos dos pistões de bombeamento de água. Além disso, sua vida útil era inferior a 3.000 horas de operação, comprometendo a confiabilidade e a disponibilidade do equipamento.', N'01 - Imagens/02 - Depois/11589.jpeg', N'A bomba instalada possui função semelhante à bomba CAT Pumps, porém o modelo Bean destaca-se pela elevada confiabilidade operacional. Seu projeto incorpora reservatório interno de óleo lubrificante e camisas dos cilindros em cerâmica polida, proporcionando maior resistência ao desgaste e redução do atrito entre os componentes móveis. A carcaça robusta contribui para a estabilidade do conjunto, enquanto a configuração de quatro cilindros promove maior uniformidade no bombeamento, reduzindo pulsações e vibrações. Adicionalmente, a montagem vertical assegura a lubrificação contínua das partes móveis, resultando em maior vida útil, podendo alcançar até 6.000 horas de operação, além de aumentar a disponibilidade e a confiabilidade do equipamento.
INSERT INTO #PVC VALUES (11590, N'81057561', N'81057561', N'Interflon Líquido Contra Particulados', 1, N'Open Pit/Poço aberto', N'O radiador não possui nenhum sistema de proteção ao acumulo de particulados, este quando acumula por sua vez impede a troca de calor de forma eficiente, sendo assim o equipamento alarma alta temperatura do compressor e precisa parar para manutenção corretiva, sendo este um modo de falhas recorrente que afeta o MTBF.
INSERT INTO #PVC VALUES (11591, N'81033186', N'81033186', N'Personal Hydration Levels', 2, N'Others/Outros', N'As the months get warmer it is important that personnel remain hydrated and know when they should drink more water.  ', N'To inform personnel on proper hydration during the summer months.', N'10352', N'01 - Imagens/01 - Antes/11591.jpeg', N'There was no visual aid to remind personnel to stay hydrated in the laboratory and how they should be checking if they had been drinking enough water.', N'01 - Imagens/02 - Depois/11591.jpeg', N'There are now visual aids from the internet placed in all bathroom stalls and urinals in the Lab. Personnel can now self-evaluate hydration level based on urine color. ', NULL, N'Yes, people are now able to self-evaluate if they are properly hydrated.', N'Proper Hydration during summer months.', 0, NULL, N'Controle de acesso passou a ser realizado pelo operador diretamente envolvido na operação do galpão.
INSERT INTO #PVC VALUES (11592, N'520942', N'520942', N'Portão de Acesso autorizados', 2, N'Others/Outros', N'Acesso principal do posto com uso de corrente e cadeado e varias copias de chaves.', N'Acessar entrada de forma eletrônica', N'10077', N'01 - Imagens/01 - Antes/11592.jpeg', N'Antes; o acesso era controlado por cadeado e cada empregado possuía uma cópia, e a cada seis meses era feito a troca do cadeado e a copia de todos, um total por ano de 80 copias só para o portão.', N'01 - Imagens/02 - Depois/11592.jpeg', N'Depois; instalado uma fechadura eletrônica e projetado uma proteção de chapa de ferro para proteger contra chuva e sol. com essa nova aquisição vai diminuir compra de cadeados e cópias de chaves e risco de prensamento de dedos, mais eficaz e seguro.', NULL, N'menos custo e mais beneficio.', N'mais autonomia e eficiência', 0, NULL, N'TEMPO DE ATUAÇÃO NA MÁQUINA REDUZIDO E MELHORAR A ERGONOMIA DO LOCAL.', '2026-07-31T00:00:00.000', '2026-08-04T15:26:55.000', N'520942', NULL, NULL);
INSERT INTO #PVC VALUES (11593, N'478572', N'478572', N'Desenvolvimento de carro para transporte seguro de tambores de correias transportadoras', 1, N'Others/Outros', N'Durante a substituição de tambores de correias transportadoras, a movimentação e o transporte eram realizados sem um dispositivo dedicado, aumentando os riscos operacionais, dificultando o posicionamento seguro do componente e reduzindo a padronização e a eficiência das atividades de manutenção.', N'Reduzir a exposição dos empregados aos riscos de movimentação de cargas pesadas durante as atividades de substituição de tambores de correias transportadoras.', N'10294', N'01 - Imagens/01 - Antes/11593.jpeg', N'Antes, os tambores eram movimentados e armazenados sem dispositivo específico, dificultando o transporte, o posicionamento seguro e a padronização das atividades de manutenção.', N'01 - Imagens/02 - Depois/11593.jpeg', N'Implementado carro de transporte específico para tambores, garantindo movimentação padronizada, maior segurança, melhor ergonomia e maior eficiência operacional.', NULL, N'SIM. O problema foi resolvido com a implantação de um carro dedicado para transporte de tambores. A solução padronizou a atividade, proporcionou maior estabilidade durante a movimentação e reduziu a exposição a riscos operacionais.', N'Dispositivos simples e dedicados podem eliminar riscos operacionais, padronizar atividades e aumentar a eficiência das intervenções de manutenção.', 0, NULL, N'busca contínua pela segurança operacional e eficiência no campo nos levou a desenvolver uma solução definitiva para os procedimentos de manutenção hidráulica e mecânica em nossas perfuratrizes', '2026-07-31T00:00:00.000', '2026-08-04T15:34:02.000', N'478572', NULL, NULL);
INSERT INTO #PVC VALUES (11594, N'1014308', N'1014308', N'Vehicle Wash cabinet', NULL, N'Others/Outros', N'Supplies for cleaning port vehicles', N'Save time cleaning vehicles', N'10002', N'01 - Imagens/01 - Antes/11594.jpeg', N'Hard finding everything to clean vehicles and everything was in the open', N'01 - Imagens/02 - Depois/11594.jpeg', N'Have everything that is needed to clean vehicles. ', NULL, N'Yes', N'N/A', 0, NULL, N'Padronizar o procedimento e garante conformidade com as normas de segurança para trabalhos com ar comprimido.
INSERT INTO #PVC VALUES (11595, N'81050299', N'81050299', N'BASE DOS FILTRO DE COMBUSTIVEL', 1, N'Others/Outros', N'Os filtros de combustível e sensores do equipamento 797F estão expostos na lateral do motor.
INSERT INTO #PVC VALUES (11596, N'1009878', N'1009878', N'Drone Inspection for Overhead Debris', 2, N'Concentration/Concentração', N'Work had been ongoing in Mobile Hopper #1 and it was believed that the hopper was fully clean.  Over a weekend when personnel where off shift debris fell that had not been observed.  This caused scaffold damage and fell down through the hopper to the ground below.', N'Find a better way to verify cleaning', N'0', N'01 - Imagens/01 - Antes/11596.jpeg', N'While many hours where spent on the hopper cleaning extensively; debris was tucked away that could not be seen and fell to the ground below.  All CSE work was shutdown until a path forward could be determined.  The hopper needed to be inspected thoroughly and in a safe manner not placing people in harms way.', N'01 - Imagens/02 - Depois/11596.jpeg', N'After discussions in meetings it was determined the best path forward would be to use the site drone to inspect the hopper without the requirement for CSE.  Once areas of concern were identified rope access could then be contacted to remove the debris by entering the area from above so that they could safely remove the concentrate.', NULL, N'Yes.  A means to better means to inspect the hopper in a safe manner.', N'Drone Inspection for Future Hopper Inspections', 0, NULL, N'alternative grinder options to reduce the risk', '2026-08-04T00:00:00.000', '2026-08-05T06:52:48.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11597, N'478572', N'478572', N'Automação na geração de PDFs da Programação Semanal de Manutenção', 1, N'Others/Outros', N'A geração dos PDFs da programação semanal era totalmente manual. O programador precisava ir aba por aba, ajustar a área de impressão e exportar os arquivos. Esse processo consumia em média 10 minutos, podendo chegar a 30 minutos devido a travamentos do Excel e da nuvem. Além do tempo excessivo, o método gerava inconsistências visuais e risco de esquecer de gerar o PDF de alguma especialidade', N'Reduzir o tempo de geração dos PDFs de compartilhamento da programação semanal de ~10 minutos (podendo chegar a 30 min em caso de travamentos) para menos de 30 segundos, padronizando a formatação e eliminando o risco de erro humano na hora de exportar as abas.', N'10294', N'01 - Imagens/01 - Antes/11597.jpeg', N'A geração manual de PDFs aba por aba consumia de 10 a 30 minutos por travamentos do sistema. O método gerava arquivos desformatados e risco de omissão de alguma especialidade.', N'01 - Imagens/02 - Depois/11597.jpeg', N'Automação via botão de 1 clique gera e padroniza todos os PDFs em 25s. Reduziu o tempo de 10-30 minutos, eliminou travamentos do sistema e acabou com o risco de omissão de alguma aba.', NULL, N'A meta era reduzir o tempo e acabar com os travamentos. O resultado superou a expectativa: passamos de um processo manual de 10 a 30 minutos (sujeito a falhas) para uma rotina automatizada de 25 segundos, 100% confiável e padronizada.', N'Pequenas automações no Excel eliminam grandes desperdícios de tempo. A padronização de processos manuais via macro não apenas ganha tempo, mas reduz erros humanos e o estresse de lidar com travamentos do sistema, libertando a equipe para focar no planejamento.', 0, NULL, N'Eliminar o trabalho em altura durante o abastecimento de água e diesel dos MMU''s, reduzindo o risco de Alto para Eliminado e aumentando a segurança operacional.', '2026-08-04T00:00:00.000', '2026-08-05T10:06:19.000', N'478572', NULL, NULL);
INSERT INTO #PVC VALUES (11598, N'81058966', N'81058364', N'Confecção e Instalação de Canhão de Água para Limpeza da Baia CX-2057-05/06', 1, N'Others/Outros', N'Durante as atividades de limpeza da baia CX-2057-05/06, foi identificado que o processo era realizado com baixo alcance do jato de água, exigindo maior esforço manual, mais tempo de execução e dificultando a limpeza de áreas de difícil acesso, impactando a produtividade e a segurança operacional.', N'Confeccionar e instalar um canhão de água para aumentar o alcance do jato, reduzir o tempo de limpeza, diminuir o consumo de água e melhorar a segurança e eficiência da operação.', N'10031', N'01 - Imagens/01 - Antes/11598.jpeg', N': Antes da melhoria, a limpeza era realizada com equipamento de baixo alcance, exigindo reposicionamento constante, maior esforço manual e mais tempo para conclusão da atividade.', N'01 - Imagens/02 - Depois/11598.jpeg', N'Foi montado e instalado um canhão de água utilizando tubulação, curva de 90°, válvula de bloqueio e bico de descarga, proporcionando maior alcance do jato, facilidade de operação e maior eficiência na limpeza.', NULL, N'A meta foi alcançada. Com a instalação da válvula de dreno, o tempo de limpeza foi reduzido de aproximadamente 8 horas para cerca de 2,5 horas, facilitando a drenagem do material acumulado, reduzindo o esforço operacional e aumentando a eficiência da manutenção.', N'Soluções simples e de baixo custo podem gerar ganhos significativos em segurança, produtividade e padronização das atividades, reduzindo esforço operacional e melhorando a eficiência do processo.', 0, NULL, N'Disponibilizar a visualização em tempo real das imagens do Vision Rock para os técnicos da sala de controle, aumentando a confiabilidade do monitoramento da granulometria, agilizando a identificação de desvios e proporcionando maior assertividade na tomada de decisão operacional.', '2025-07-31T00:00:00.000', '2026-08-05T10:26:00.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11599, N'81042207', N'81054975', N'Implementação de Gestão Visual para Identificação dos Pousos de Tampas de Vagões de Cobre', 1, N'Others/Outros', N'Durante inspeção realizada no galpão de descarga de vagões de cobre, foi identificado que os locais destinados ao repouso de tampas de vagões, conhecidos informalmente como Pouso 1 e Pouso 2, não possuíam qualquer tipo de identificação visual. Essa condição fazia com que somente os colaboradores habituados ao processo soubessem diferenciar os locais, gerando dependência de conhecimento tácito, dificuldades para novos operadores e possibilidade de erros na segregação e utilização das tampas durante as atividades de manutenção e substituição.
INSERT INTO #PVC VALUES (11600, N'81036958', N'81036958', N'JANELA VISITA TR2009-05', 1, N'Projects/Projetos', N'JANELAS DE VISITA ANTIGAS FORAM BLOQUEADAS POR VIGAS ESTRUTURAIS FAZENDO COM QUE AS MESMAS FICASSEM INACESSIVEIS , OUTRO PONTO A SER LEVADO EM CONSIDERAÇÃO É QUE AS JANELAS ANTIGAS ESTAVAM DETERIORADAS MECANICAMENTE', N'INSTALAR JANELAS PADRONIZADAS', N'10031', N'01 - Imagens/01 - Antes/11600.jpeg', N'JANELAS ANTIGAS OBSTRUIDAS POR VIGAS ESTRUTURAIS INSTALADAS PELA EQUIPE DE PROJETOS, JANELAS COM ALTO NIVEL DE DETERIORAÇÃO E INACESSIVEIS PARA LIMPEZA DE ROTINA E MANUTENÇÃO DO ATIVO DURANTE PARADAS DE MANUTENÇÃO ', N'01 - Imagens/02 - Depois/11600.jpeg', N'INSTALAÇÃO DE JANELA PADRONIZADA COM ACESSO LIMITADO POR GRADE QUE AUXILIA NA INSPEÇÃO DO CHUTE E RASPADOR PRIMARIO. JANELA ACESSIVEL DE FORMA ERGONOMICA SEGURA PARA LIMPEZA E MANUTENÇAO DURANTE PARADAS SEM EXPOR EXECUTANTES A RISCOS ERGONOMICOS OU FISICOS COMO CORTES POR CONTATO COM CHAPARIA DO CHUTE. ', NULL, N'O ACESSO AO INTERIOR DO CHUTE FOI RESTABELECIDO DE FORMA SEGURA TANTO PARA AS EQUIPES DE LIMPEZA QUANTO PARA AS MANUTENÇÕES DO EQUIPAMENTO. ', N'PADRONIZAÇÃO TRANSFORMA O AMBIENTE DE TRABALHO MAIS SEGURO ', 0, NULL, N'Results as planned. All stakeholders are able to utilize these prints.', '2026-06-24T00:00:00.000', '2026-08-05T11:34:41.000', N'81036958', NULL, NULL);
INSERT INTO #PVC VALUES (11601, N'81057561', N'81057561', N'Linha de Vida Móvel', 1, N'Open Pit/Poço aberto', N'Para determinados trabalhos em altura existe a necessidade de montagem de andaimes para ancoragem, o que leva muito tempo dependendo da demanda e da altura que necessitamos que seja montado o andaime no equipamento.
INSERT INTO #PVC VALUES (11602, N'81062687', N'81062687', N'RLS Basket Strainer Gasket Storage', 3, N'Others/Outros', N'Most gaskets are stored on the opposite corner of the plant. Having the basket strainer gaskets stored in the immediate vicinity of the RLS pumps allows for faster access and saves time not having to go look for the right size.', N'To provide quick and easy access to gaskets at point of work.', N'0', N'01 - Imagens/01 - Antes/11602.jpeg', N'Basket strainer gaskets, if on hand, could be found in the POL Laydown on the south side of the building. The RLS area is toward the Northeast corner of the building. ', N'01 - Imagens/02 - Depois/11602.jpeg', N'Now there is a designated storage area for basket strainer gaskets in the immediate vicinity of the RLS area, eliminating the need to traverse the building to look for them. Included in this 5S improvement are the stock code for re-ordering and minimum/maximum quantities to ensure that they are always available.', NULL, N'Gaskets are now stored on the wall in the area where they are used, with stock code and min/max quantities posted to ensure they are re-ordered and readily available.', N'5S improvement like having parts stored in their areas of use can improve efficiency by saving time not having to travel very far or search for what is needed.', 0, NULL, N'1 bearing costs ~$40,000 after installation.
INSERT INTO #PVC VALUES (11603, N'81057561', N'81057561', N'Mangueiras CAT', 3, N'Open Pit/Poço aberto', N'Baixa confiabilidade das mangueiras ALFAGOMMA, alto número de paradas para substituir mangueiras.', N'Aumentar a confiabilidade operacional dos equipamentos, trazendo mangueiras mais robustas e de melhor qualidade para serem utilizadas na frota, buscando uma diminuição no número de paradas corretivas, com isso aumento do MTBF.', N'10015', N'01 - Imagens/01 - Antes/11603.jpeg', N'Para manutenções corretivas utilizamos mangueiras ALFAGOMMA, a incidência de problemas com montagem de mangueiras, qualidade da mangueira propriamente dita, estava refletindo em muitas paradas corretivas por conta de vazamento hidráulico, onde a solução é quase sempre a troca da mangueira, impacto no MTBF e MTTR.', N'01 - Imagens/02 - Depois/11603.jpeg', N'Com a aquisição de material, temos a disponibilidade de utilizar a fábrica interna da Sotreq no site de Salobo para confecção de mangueiras a serem utilizadas na frota de perfuração.
INSERT INTO #PVC VALUES (11604, N'81042207', N'495412', N'Controle Seguro de Acesso ao Galpão de Descarga de Cobre', 1, N'Others/Outros', N'O processo de descarga de vagões de cobre dentro do galpão envolve a operação simultânea da ponte rolante (para destampar vagões) e da escavadeira hidráulica (para retirar o material e alimentar o sistema).​
INSERT INTO #PVC VALUES (11605, N'544566', N'544566', N'RELOCAÇÃO BOTOEIRA SELETORA UNIDADE HIDRÁULICA BR-2104SA-01', 1, N'Crusher/Britadeira', N'DEVIDO A INSTALAÇÃO DA BOTOEIRA SELETORA DO BRITADOR BR-2104SA-01 SER EM LOCAL DE DIFICIL ACESSO E ESCONDIDA HOUVE UMA PARADA DO BRITADOR POR CERCA DE 3 HORAS DEVIDO A MESMA ESTAR COM SUA SELEÇÃO EM CAMPO PARA MANUAL . AS EQUIPES DE MECÂNICA , OPERAÇÃO E ELÉTRICA TIVERAM EXTREMA DIFICULDADE EM ENCONTRAR O SISPOSITVO. ', N'ELIMINAR FALHAS DE ACIONAMENTO DA BOTOEIRA SELETORA', N'0', N'01 - Imagens/01 - Antes/11605.jpeg', N'BOTOEIRA DE SELEÇÃO MANUAL E AUTOMÁTICO DA UNIDADE DE LUBRIFICAÇÃO DO BRITADOR BR-2104SA-01 FICAVA EM LOCAL DE DÍFICIL ACESSO , LEVANDO SITUAÇÕES EXTREMAS EM SUA MANUTENÇÃO . ', N'01 - Imagens/02 - Depois/11605.jpeg', N'SELETORA FOI RELOCADA PARA A FORA DA UNIDADE HIDRÁULICA , GERANDO MELHORES CONDIÇÕES DE SEGURANÇA E MANUTENÇÃO . FEITO IDENTIFICAÇÃO DA SELETORA EM CAMPO PARA FACILITAR NA OPERAÇÃO .', NULL, N'HOJE DEVIDO A RELOCAÇÃO DO DISPOSITIVO ESTAMOS COM MAIS PRATICIDADE NA MANUTENÇÃO E IDENTIFICAÇÃO .', N'COMPONENTES PRECISAM ESTAR EM LOCAL MAIS ADEQUADO PARA MANUTENÇÃO.', 0, NULL, NULL, '2026-08-04T00:00:00.000', '2026-08-05T15:42:43.000', N'544566', NULL, NULL);
INSERT INTO #PVC VALUES (11606, N'81059721', N'545523', N'CRIAÇÃO DE DISPOSITIVO DE TRAVA DE HASTES PARA PERFURATRIZES', 2, N'No Replication/Sem replicação', N'O procedimento tradicional de retenção de hastes nas perfuratrizes dependia de cordas, cintas e tubos improvisados. Essa prática trazia alta instabilidade e expunha a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos. Além da insegurança, demandava muito tempo para amarrações e ajustes, tornando a rotina lenta e ineficiente.', N'Evitar instabilidade e a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos.', N'10144', N'01 - Imagens/01 - Antes/11606.jpeg', N'O procedimento tradicional de retenção de hastes nas perfuratrizes dependia de cordas, cintas e tubos improvisados. Essa prática trazia alta instabilidade e expunha a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos. Além da insegurança, demandava muito tempo para amarrações e ajustes, tornando a rotina lenta e ineficiente.
INSERT INTO #PVC VALUES (11607, N'81059721', N'365593', N'INSTALAÇÃO DE REGISTRO DA EXTREMIDADE DA MANGUEIRA DO COMPRESSOR DE AR', 2, N'No Replication/Sem replicação', N'Mangueira do compressor de ar sem registro na extremidade, ocorrendo acionamentos involuntários quando usando em equipamento como bombas e ferramentas pneumáticas.', N'Elimina o efeito chicote e vazamentos durante a troca de ferramentas', N'10144', N'01 - Imagens/01 - Antes/11607.jpeg', N'A mangueira do compressor de ar não possuía registro na extremidade. Ocorrendo acionamentos involuntários, quando utilizado o equipamento, causando disparos acidentais ao operar bombas e ferramentas pneumáticas.
INSERT INTO #PVC VALUES (11608, N'189456', N'189456', N'Melhoria de informação no relatório despacho info resumo mina', 1, N'Open Pit/Poço aberto', N'Falta de uma visão unificada da frota, dificultando a identificação ágil dos caminhões disponíveis e daqueles em manutenção em um único relatório.', N'Informação rápida em um único relatório', N'0', N'01 - Imagens/01 - Antes/11608.jpeg', N'A ausência de um relatório único e consolidado para acompanhamento dos caminhões disponíveis e em manutenção dificulta a obtenção de informações rápidas e confiáveis sobre a situação da frota. Como consequência, as equipes precisam consultar diferentes fontes de dados, aumentando o tempo de análise e o risco de informações divergentes.', N'01 - Imagens/02 - Depois/11608.jpeg', N'A consolidação das informações de caminhões disponíveis e em manutenção em um único relatório proporciona maior agilidade e eficiência na gestão da frota. Com uma visão centralizada, as equipes conseguem identificar rapidamente a situação operacional de cada frota, reduzindo o tempo gasto na busca de informações em diferentes fontes garantindo assim maior eficiência operacional, melhor utilização dos ativos e mais velocidade na tomada de decisão, contribuindo para o alcance das metas de produção e disponibilidade da frota.', N'http://172.19.144.219/ReportServer/Pages/ReportViewer.aspx?/Planejamento/Relat%c3%b3rios+operacionais/Informativo+Resumo+Mina&rs:Command=Render', N'Ausência de meta anterior.', N'agilidade e eficiência na gestão da frota', 0, NULL, N'Todo material enviado via expresso deve possuir controle de rastreamento e registro de cada etapa da entrega.', '2026-08-05T00:00:00.000', '2026-08-06T11:09:20.000', N'189456', NULL, NULL);
INSERT INTO #PVC VALUES (11609, N'200795', N'607697', N'Alternate Grinder with Improved Safety Switch Configuration', 2, N'Underground/Subterrâneo', N'Worker was injured June 23, 2026 when they reached into their tool bag and a cordless grinder inadvertently started resulting in laceration to left index finger.', N'Source alternate grinders with other safety switch configurations', N'10202', N'01 - Imagens/01 - Antes/11609.jpeg', N'While reaching into the tool bag to grab a hammer, a worker accidentally triggered a battery-operated grinder. The safety switch moves in the same direction as the paddle. The grinder cut through the glove on the workers other hand requiring stitches
INSERT INTO #PVC VALUES (11610, N'81051447', N'81051447', N'Eliminação do Trabalho em Altura no Abastecimento de Água e Diesel dos MMU''s por Meio da Adequação do Sistema de Abastecimento', 2, N'Others/Outros', N'O processo de abastecimento de água e diesel dos MMU''s exigia que o operador realizasse acesso em altura para conectar e operar os pontos de abastecimento localizados na parte superior do equipamento. Essa condição expunha os trabalhadores ao risco de queda de altura, classificado como risco alto na matriz de riscos, além da exposição ao contato com diesel durante a operação. Apesar da existência de controles administrativos e requisitos de trabalho em altura, a atividade mantinha potencial para ocorrência de acidentes graves. Diante desse cenário, foi identificada a necessidade de uma solução de engenharia que eliminasse a exposição ao risco na fonte.', N'Eliminar a necessidade de acesso em altura durante as atividades de abastecimento de água e diesel dos MMU''s, reduzindo a exposição dos trabalhadores ao risco de queda de nível diferente e ao contato com diesel, elevando a segurança operacional e promovendo melhoria sustentável no processo.', N'10253', N'01 - Imagens/01 - Antes/11610.jpeg', N'-Necessidade de acesso à parte superior do MMU para abastecimento de água e diesel.
INSERT INTO #PVC VALUES (11611, N'488890', N'488890', N'Toque e veja.', 1, N'Projects/Projetos', N'Para o monitoramento da granulometria do minério transportado pelas correias 2051 TC 01, que alimenta a pilha pulmão, e 2301 TC 05, o sistema Vision Rock disponibilizava apenas os dados granulométricos. Embora o equipamento também possua recurso de visualização por imagem, essa funcionalidade não estava disponível para acompanhamento em tempo real pelos técnicos da sala de controle, limitando a análise operacional e a tomada de decisão.', N'Visualizar o material do Vision Rock da 2051 TC 01 e 2301 TC 05 em tempo real.', N'10054', N'01 - Imagens/01 - Antes/11611.jpeg', N'O sistema Vision Rock, responsável pelo monitoramento da granulometria do minério nas correias 2051 TC 01 (alimentação da pilha pulmão) e 2301 TC 05, disponibilizava apenas os dados granulométricos para a sala de controle. Apesar de o equipamento possuir recurso de visualização por imagem, essa funcionalidade não era acessível aos técnicos de operação, restringindo a validação visual das informações, reduzindo a confiabilidade das análises operacionais e dificultando a tomada de decisão em tempo real.', N'01 - Imagens/02 - Depois/11611.jpeg', N'Foi disponibilizada a visualização das imagens do sistema Vision Rock para os técnicos da sala de controle, permitindo o acompanhamento em tempo real da granulometria do minério nas correias 2051 TC 01 e 2301 TC 05. Com essa implementação, passou a ser possível validar visualmente as informações fornecidas pelo sistema, proporcionando maior confiabilidade no monitoramento do processo, maior agilidade na identificação de desvios granulométricos e melhor suporte à tomada de decisão operacional.', NULL, N'Antes da melhoria, os técnicos da sala de controle tinham acesso apenas aos dados granulométricos do Vision Rock, sem a visualização das imagens. Após a implantação, as imagens passaram a ser disponibilizadas em tempo real, aumentando a confiabilidade do monitoramento e proporcionando maior assertividade na tomada de decisão operacional.', N'O aproveitamento de recursos existentes aumentou a confiabilidade operacional e a agilidade na tomada de decisão.', 0, NULL, N'The objective was achieved by creating a clear and accessible tracking system that provides visibility of all active safety notices and associated timelines. The process reduces the risk of using outdated information and improves overall communication and compliance.', '2026-08-03T00:00:00.000', '2026-08-06T12:27:25.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11612, N'81041701', N'81041701', N'Ferramenta de Gestão do Processo de Manutenção do Sistema Remoto', 1, N'Others/Outros', N'Demandas do time de monitoramento com dificuldade de gerir, devido as ordens sistemáticas, necessidades do sistema e solicitações do processo de preditiva. 
INSERT INTO #PVC VALUES (11613, N'1010585', N'300563', N'Ventilation Prints', 1, N'Underground/Subterrâneo', N'Ventilation requirements were being communicated through comments on a mid-range block plan. While these comments identified high-level requirements, they lacked the detailed information to support planning and implementation.', N'Develop detailed ventilation prints that clearly define all ventilation requirements, installation details, and supporting information required for successful execution.', N'10357', N'01 - Imagens/01 - Antes/11613.jpeg', N'Ventilation requirements were provided as notes and comments on block plans by the Ventilation Specialist. ', N'01 - Imagens/02 - Depois/11613.jpeg', N'Detailed ventilation prints are issued, including ducting layouts, accessories, fan specification and installation requirements providing a complete plan for execution.', NULL, N'The issue has been successfully resolved, as Operations now receives a complete understanding of requirements before installation begins. All stakeholders have greater visibility into project needs, including planners who can accurately design drift dimensions and other critical elements. This improved level of detail enhances communication, alignment, and decision-making across the entire process, resulting in more effective planning and execution.', N'Detailed Prints', 0, NULL, N'Padronização das análises dos históricos de falhas.', '2026-08-04T00:00:00.000', '2026-08-06T12:45:49.000', N'1010585', NULL, NULL);
INSERT INTO #PVC VALUES (11614, N'81041701', N'81041701', N'Ampliação da faixa de frequência monitorada nas células de flotação.', NULL, N'Crusher/Britadeira', N'O monitoramento de telemetria é essencial para acompanhar continuamente as variações do equipamento. Porém para as CFs da usina III que são redutores robustos e os sensores são colados longes do rolamento, além da rotação ser baixa no eixo de saída (88 RPM), precisávamos de uma coleta de vibração com maior sensibilidade. 
INSERT INTO #PVC VALUES (11615, N'81040957', N'81040957', N'Ultrasonic Greasing of Generator Bearings', 1, N'Smelting/Fundição', N'After a premature fixed bearing failure, greasing practices were focused on to prevent future bearing failures. The frequency of bearing greasing was to be determined, as well as methodology/equipment required to ensure optimal quantity of grease is injected into the bearings each time. ', N'Ensure accurate greasing frequency and quantity of generator bearings.', N'10111', N'01 - Imagens/01 - Antes/11615.jpeg', N'Greasing PM''s were set to bi-weekly, with inadequate quantity of grease injected into the bearings, contributing to premature failures. No equipment installed to monitor bearing conditions or assist with greasing. 
INSERT INTO #PVC VALUES (11616, N'81013114', N'81013114', N'Increase Hi SP', 1, N'Others/Outros', N'A sump LI was cycling, causing alarm to ring in sometimes 50-60 times a day.', N'To decrease DCS alarms', N'0', N'01 - Imagens/01 - Antes/11616.jpeg', N'A LI on a sump in our building was cycling, causing a Hi sump level alarm to ring in on DCS.', N'01 - Imagens/02 - Depois/11616.jpeg', N'A request was made to DCS support to increase the Hi setpoint alarm on the sump, causing the alarm to not ring in on DCS as frequently. But the sump still kicking in and pumping the solution', NULL, N'Yes so far the problem has been solved, the sump is doing its job while not having the alarm ring  in on DCS panel', N'An easy solution to get of unnessesary alarms', 0, NULL, N'A implementação da melhoria eliminou aproximadamente 2.350 tratativas manuais por mês relacionadas a horímetros repetidos, reduzindo cerca de 26,5 horas mensais de atividades operacionais e evitando mais de 1.500 interrupções no processamento. Com isso, o robô passou a executar o processo de forma contínua e confiável, alcançando 100% de sucesso no tratamento dessas ocorrências e aumentando a eficiência da automação.', '2026-08-05T00:00:00.000', '2026-08-06T14:14:30.000', N'81013114', NULL, NULL);
INSERT INTO #PVC VALUES (11617, N'202638', N'202638', N'Shipping cost savings', 1, N'Refining/Refino', N'Shipping copper cathodes to have copper removed had a quoted price of $1700 per load', N'Cost savings', N'0', N'01 - Imagens/01 - Antes/11617.jpeg', N'Shipping cost per load regardless of weight was $1700 per load quoted for contractor', N'01 - Imagens/02 - Depois/11617.jpeg', N'Sent out for quote and through Vale shipping portal we were able to get a quote for $950 per load. 8 loads total for a savings of $6000', NULL, N'yes, savings realized', N'Get quotes for all requests to find the cheapest price', 6000, 3, N'AHORA HÁ UMA MELHOR OTIMIZAÇÃO DO TEMPO DA EQUIPE.', '2026-08-05T00:00:00.000', '2026-08-06T15:02:21.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11618, N'202638', N'1008697', N'Reduce WLN loading', NULL, N'Refining/Refino', N'Excess water being sent to WLN', N'Reduce water load to WLN', N'0', N'01 - Imagens/01 - Antes/11618.jpeg', N'The nickel dip tanks are always overflowing to prevent quality issues', N'01 - Imagens/02 - Depois/11618.jpeg', N'Water consumption was evaluated and reduced by.5m3 for a total of 24m3 per day (.5m3 per dip tank, two dip tanks) ', NULL, N'Yes reduced water sent to spillage', N'always look for waste and ways to reduce', 10000, 3, N'Se realiza trabajo de manera más rapida y con menos errores humanos.', '2026-08-05T00:00:00.000', '2026-08-06T15:13:43.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11619, N'81011654', N'81011654', N'PADRONIZAÇÃO E OTIMIZAÇÃO DAS LISTAS DE TAREFAS SAP COM USO DO MICROSOFT COPILOT', 1, N'Others/Outros', N'ATUALMENTE AS LISTAS DE TAREFA APRESENTAM FALTA DE PADRONIZAÇÃO NA ESTRUTURA, CONTEÚDO E NÍVEL DE DETALHAMENTO, GERANDO DIVERGÊNCIAS NO PLANEJAMENTO E NA EXECUÇÃO DAS ATIVIDADES. ESSA VARIAÇÃO RESULTA EM RETRABALHOS, MAIOR TEMPO DE PREPARAÇÃO DAS ORDENS, DIFICULDADES NA ESTIMATIVA DE RECURSOS E REDUÇÃO DA EFICIÊNCIA DO PROCESSO DE MANUTENÇÃO. A AUSÊNCIA DE UM PADRÃO TÉCNICO TAMBÉM IMPACTA A QUALIDADE DOS REGISTROS E A REPLICABILIDADE DAS MELHORES PRÁTICAS.', N'PADRONIZAR E OTIMIZAR AS LISTAS DE TAREFA DE MANUTENÇÃO, GARANTINDO MAIOR QUALIDADE NO PLANEJAMENTO, REDUÇÃO DE RETRABALHOS, PADRONIZAÇÃO DAS ORDENS SAP, MELHORIA DA PRODUTIVIDADE E AUMENTO DA CONFIABILIDADE DAS INFORMAÇÕES UTILIZADAS PELAS EQUIPES DE EXECUÇÃO.', N'10279', N'01 - Imagens/01 - Antes/11619.jpeg', N'As listas de tarefas SAP possuíam informações repetidas, excesso de texto e falta de padronização, dificultando o planejamento das atividades de manutenção. Além disso, havia baixa aderência aos requisitos definidos no PRO-046572 Diretriz de Segurança Para Planejar Ordem de Manutenção - Sossego, resultando em maior tempo para elaboração das tarefas, variações na qualidade das informações cadastradas e risco de interpretações divergentes durante a execução das atividades.', N'01 - Imagens/02 - Depois/11619.jpeg', N'As listas de tarefas SAP foram revisadas, simplificadas e padronizadas em conformidade com o PRO-046572 Diretriz de Segurança Para Planejar Ordem de Manutenção - Sossego, eliminando redundâncias e incorporando os requisitos mínimos de SSMA. Também foram criadas chaves modelo para cada etapa da manutenção, garantindo uma estrutura padronizada para elaboração das atividades. Adicionalmente, foi desenvolvido um prompt padronizado no Microsoft Copilot para geração automática das descrições de Ordens SAP.
INSERT INTO #PVC VALUES (11620, N'81034352', N'81055552', N'Implementação de preenchimento automático no cadastro de pesagens', 1, N'Others/Outros', N'O sistema não permitia pesquisar os registros digitando o nome. Para localizar informações como empresa, material e outros campos, era necessário percorrer manualmente a barra de rolagem até encontrar a opção desejada. Esse processo aumentava o tempo de cadastro das pesagens, tornava a operação menos ágil e favorecia a seleção incorreta de itens. ', N'Reduzir tempo de cadastro das pesagens, eliminando o atraso procurando material por meio do preenchimento automático dos campos. ', N'10233', N'01 - Imagens/01 - Antes/11620.jpeg', N'Sistema não permitia pesquisar os registros digitando o nome. Para localizar informações como empresa, material e outros campos, era necessário percorrer manualmente a barra de rolagem até encontrar a opção desejada. Esse processo aumentava o tempo de cadastro das pesagens, tornava a operação menos ágil e favorecia a seleção incorreta de itens. ', N'01 - Imagens/02 - Depois/11620.jpeg', N'Com a implementação da pesquisa por digitação, basta inserir as primeiras letras para que o sistema localize e complete automaticamente o registro, reduzindo o tempo de busca e aumentando a eficiência operacional.', NULL, N'A melhoria atendeu ao objetivo proposto, eliminando a necessidade de percorrer a barra de rolagem para localizar informações. O preenchimento por pesquisa tornou o cadastro mais rápido, eficiente e com menor risco de erros na seleção dos dados.', N'Melhorias no sistema podem gerar grande impacto significativo na rotina.', 0, NULL, N'Se espera incentivar a los trabajadores a realizar actividad fisica en proyecto', '2026-08-03T00:00:00.000', '2026-08-06T17:54:16.000', N'81034352', NULL, NULL);
INSERT INTO #PVC VALUES (11621, N'550315', N'550315', N'CADERNO DE ENTREGA:  EXPRESSO PERFURAÇÂO', 1, N'Others/Outros', N'Durante a execução das atividades do projeto Expresso Perfuração, foi identificada a falta de materiais enviados via transporte expresso', N'Este caderno tem como finalidade formalizar a entrega dos serviços executados no projeto Expresso Perfuração', N'10234', N'01 - Imagens/01 - Antes/11621.jpeg', N'Não existe um Caderno de Entrega do Expresso Perfuração formalizado e consolidado contendo todas as informações, evidências, registros técnicos, documentos de inspeção, testes realizados e aprovações necessárias para a entrega oficial do projeto.', N'01 - Imagens/02 - Depois/11621.jpeg', N'Foi identificado atraso e interrupções nas atividades de perfuração devido a falhas operacionais nos equipamentos e condições adversas encontradas em campo, comprometendo a execução conforme o planejamento inicial.', NULL, N'A ocorrência evidenciou a necessidade de aprimorar os controles logísticos e a rastreabilidade dos materiais enviados via expresso', N'Fortalecer a rastreabilidade dos materiais  Todo material enviado via expresso deve possuir controle de rastreamento e registro de cada etapa da entrega.', 0, NULL, N'Proteger a los trabajadores de las ráfagas de viento que se pueden presentar en la región en estas fechas.', '2026-08-06T00:00:00.000', '2026-08-07T04:16:07.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11622, N'92000587', N'81002955', N'RECUPERAÇÃO E ADEUQAÇÃO DAS BASES DE FIXAÇÃO ', 1, N'Others/Outros', N'APRESENTAVA DEFORMÇÕES, DESGASTE E FUROS DE FIXAÇÃO DANIFICADOS, NECESSITANTODA RECUPERAÇÃO PARA RESTABELECER SUAS CONDIÇÕES ADEQUADAS DE UTILIZAÇÃO ', N'RESTABELECER AS CONDIÇÕES ADEQUADAS DE USO E AFIXAÇÃO DO CONJUNTO ', N'10144', N'01 - Imagens/01 - Antes/11622.jpeg', N'Componente apresentava deformações, desgaste e danos nos pontos de fixação, incluindo furos comprometidos, necessitando de recuperação para garantir as condições adequadas de utilização.', N'01 - Imagens/02 - Depois/11622.jpeg', N'Foi realizada a recuperação dos componentes, contemplando o desempeno das peças, substituição da base do deslizante, recuperação de alguns furos, execução de novos furos nas bases de fixação no truque e aplicação de nova pintura.', NULL, N'Sim. O conjunto foi recuperado, com correção das deformações, recuperação e execução dos furos de fixação, substituição da base do deslizante e nova pintura, restabelecendo suas condições adequadas de utilização.', N'A identificação precoce de desgastes e danos permite uma recuperação preventiva e evita o agravamento dos problemas.', 0, NULL, N'Melhoria da produtividade e desempenho operacional através da disponibilização de um suporte adequado para o Tote Bin de sabão.', '2026-08-06T00:00:00.000', '2026-08-07T05:15:53.000', N'92000587', NULL, NULL);
INSERT INTO #PVC VALUES (11623, N'974865', N'81002390', N'Base de Apoio para Martelete Elétrico', 3, N'Others/Outros', N'Não havia local especifico para guardar as ferramentas elétricas as mesma eram acondicionadas no chão.
INSERT INTO #PVC VALUES (11624, N'1010585', N'300608', N'Safety Notice Tracking Sheet', NULL, N'Others/Outros', N'Improve visibility and management of active safety notices to ensure all team members are aware of current notices, upcoming action dates and expiration timelines.', N'To improve visibility and management of safety notices', N'10357', N'01 - Imagens/01 - Antes/11624.jpeg', N'Safety notices were tracked through the safety notice site and email notifications to the individual who originally created the notice. As staff changed roles or new employees joined the team, they weren''t apprised of the expiry as they weren''t on the email list. This created lack of visibility regarding safety notices that are active, upcoming expiry dates and we don''t want this overlooked during the planning and design stage.', N'01 - Imagens/02 - Depois/11624.jpeg', N'A centralized safety notice tracking sheet was developed and is maintained by the Divisional supervisor. The tracking sheet provides visibility of all the active safety notices and their associated timelines. Team members can now proactively monitor upcoming expiry dates, understand ownership and required actions, and ensure current safety notices are considered during planning activities. The process reduces the risk of using outdated information and improves overall communication and compliance.', NULL, N'Yes, the implementation of the safety notice tracking sheet successfully addressed the visibility gap. The team now has a single source of truth for the active safety notices, making it easy to identify current notices, track expiration dates, and take timely action. This has improved awareness and accountability, and confidence that layout plans are being developed using current and valid safety notices.', N'Visibility Gap Solved', 0, NULL, N'5S (Senso de Organização e Identificação)
INSERT INTO #PVC VALUES (11625, N'471876', N'471876', N'RUIDO EXCESSIVO NA SALA DE ABOSRÇÃO ATÔMICA', 1, N'Others/Outros', N'Rotor da sala de absorção com ruido excessivo.', N'Reduzir ruido ', N'10032', N'01 - Imagens/01 - Antes/11625.jpeg', N'Tivemos um ocorrido, onde um dos exaustores da sala de absorção atômica ficou com ruido excessivo ficando impraticável trabalhar naquela condição 79,6 decibéis, com isso, ficou parado um equipamento de 38.000 reais, que consegue produzir em condições normais , 1 amostra a cada 3 minutos, colocando em 24 horas e contemplando os horários de parada do Técnico, faria, 410 amostras, ou seja, deixamos de fazer, 87.320 amostras em 6 meses.', N'01 - Imagens/02 - Depois/11625.jpeg', N'Pesquisamos no mercado, colocamos um Exaustor mais silencioso e com a mesma performance do projeto original, solucionado e reestabelecida a analise, com o Técnico trabalhando conforme rege a Higiene ocupacional, 65,1 Decibéis.', NULL, N'resolvido', N'que com a pesquisa e recomendações conseguimos', 0, NULL, N'ESPERA-SE MANTER O CARREGADOR DE BATERIAS, EM LOCAL FIXO, IDENTIFICADO E ORGANIZADO.', '2026-08-03T00:00:00.000', '2026-08-07T11:16:39.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11626, N'487516', N'487516', N'Controle de notas YE', 1, N'Others/Outros', N'Inexistência de relatório padrão que permita busca rápida das falhas ocorridas por componente, relacionando ao histórico de reformas anteriores e ordens de correção.', N'Criação de controle que permita a busca rápida das falhas ocorrida com os componentes, histórico da reforma e nota da tratativa.', N'10008', N'01 - Imagens/01 - Antes/11626.jpeg', N'Inexistência de controle de notas YE para as falhas. Necessidade de busca no SAP conforme necessidade das informações.', N'01 - Imagens/02 - Depois/11626.jpeg', N'Controle de notas YE relacionadas a falhas de componentes que permitam a criação de relatórios de busca por código Vale, número do equipamento, frota, fornecedor, garantia etc.', NULL, N'Sim.
INSERT INTO #PVC VALUES (11627, N'516619', N'516619', N'Adequação da Altura do Peneirador ', 1, N'No Replication/Sem replicação', N' Equipamento apresenta instabilidade operacional e altura inadequada em relação ao piso, dificultando o acesso seguro para operação,', N'Melhorar estabilidade estrutural, alinhamento adequado e elevação compatível com as necessidades operacionais e Ergonômicas', N'10032', N'01 - Imagens/01 - Antes/11627.jpeg', N'Antes da adequação, o peneirador suspenso apresentava instabilidade operacional e altura inadequada em relação ao piso, dificultando o acesso seguro para operação, limpeza e manutenção. A ausência de pés de apoio comprometia a ergonomia dos trabalhadores, exigindo posturas inadequadas, maior esforço físico e aumentando os riscos de desconforto muscular e acidentes durante as atividades.', N'01 - Imagens/02 - Depois/11627.jpeg', N'Após a instalação dos pés de sustentação, o equipamento passou a apresentar melhor estabilidade estrutural, alinhamento adequado e elevação compatível com as necessidades operacionais. A adequação ergonômica proporcionou melhores condições de trabalho, favorecendo postura mais correta dos operadores, redução do esforço físico, maior segurança durante o uso e facilidade no acesso para inspeção e higienização. Além disso, a melhoria contribui para maior eficiência operacional e conformidade com princípios ergonômicos e de segurança no ambiente de trabalho.', NULL, N'Sim, com a instalação dos pés de sustentação corrigiu as deficiências identificadas no equipamento, proporcionando maior estabilidade estrutural, alinhamento adequado e altura compatível com a operação.', N'Pequenas adequações estruturais podem proporcionar grandes benefícios em ergonomia, segurança e desempenho operacional.', 0, NULL, NULL, '2026-08-06T00:00:00.000', '2026-08-07T13:15:58.000', N'516619', NULL, NULL);
INSERT INTO #PVC VALUES (11628, N'487516', N'487516', N'Formulário padrão tratamento notas YE', 1, N'Others/Outros', N'Abertura e tratamento de notas YE de análise de falha sem um padrão definido.', N'Criar um formulário padrão para levantamento de informações para tratamento de falhas.', N'10008', N'01 - Imagens/01 - Antes/11628.jpeg', N'A inexistência de um padrão formal para análise de falhas gerava deficiências significativas no processo investigativo, comprometendo a qualidade e a confiabilidade dos resultados. Sem uma metodologia padronizada, as informações coletadas tendem a variar de acordo com o analista responsável, podendo resultar em registros incompletos sobre o equipamento, condições operacionais, histórico de manutenção e evidências da falha. Essa falta de uniformidade dificultava a comparação entre ocorrências semelhantes, reduzindo a rastreabilidade das informações e aumenta o risco de conclusões baseadas em dados insuficientes.', N'01 - Imagens/02 - Depois/11628.jpeg', N'A análise de falhas é um processo sistemático que tem como objetivo identificar a causa raiz de uma ocorrência, utilizando informações do equipamento, histórico de manutenção e condições operacionais. Inicialmente são levantados dados como conjunto, equipamento, fornecedor, máquina de aplicação, horímetro e descrição do ocorrido, além dos efeitos observados durante a falha. Essas informações permitem caracterizar o evento e estabelecer a base para a investigação técnica.
INSERT INTO #PVC VALUES (11629, N'510839', N'510839', N'Robô IK11: Eliminação da Intervenção Manual em Horímetros Repetidos', 1, N'Others/Outros', N'Após a implantação do robô de lançamento de horímetros na transação IK11 do SAP, foi identificado um desvio operacional quando o sistema encontrava leituras iguais às registradas anteriormente, situação comum em equipamentos parados. Nesses casos, o SAP retornava a mensagem "A posição do contador é a mesma do documento anterior", impedindo a continuidade automática do processo e exigindo intervenção manual para tratamento da ocorrência. Essa condição comprometia a automação completa da atividade e gerava retrabalho para os usuários.', N'Aprimorar o robô de lançamento de horímetros para tratar automaticamente ocorrências de horímetros repetidos', N'10234', N'01 - Imagens/01 - Antes/11629.jpeg', N'Quando o robô identificava uma leitura de horímetro com o mesmo valor do último registro existente no SAP — situação comum em equipamentos parados — o sistema emitia a mensagem "A posição do contador é a mesma do documento anterior" e interrompia o processamento automático.
INSERT INTO #PVC VALUES (11630, N'81063720', N'81063720', N'GESTÃO DE ANÁLISES', 1, N'Open Pit/Poço aberto', N'NÃO HÁ UMA GESTÃO DE ANÁLISE DE OMS, O QUE PODE ACABAR ACARRETANDO EM CONFUSÃO DURANTE AS ANÁLISES PODENDO ANÁLISAR A MESMA OM DUAS VEZES.', N'OTIMIZAÇÃO DE TEMPO', N'10024', N'01 - Imagens/01 - Antes/11630.jpeg', N'UMA PLANILHA DE OMS É GERADA POR SEMANA PELO PROGRAMADOR PARA A EQUIPE DE PREDITIVA REALIZAR, PORÉM NÃO HÁ UMA GESTÃO DE DE OMS TRATADAS, ONDE OS TÉCNICOS PODEM SE CONFUNDIR E ACABAR ANALISANDO A MESMA OM.', N'01 - Imagens/02 - Depois/11630.jpeg', N'A SOLUÇÃO PARA SANAR O PROBLEMA FOI ADICIONAR UMA COLUNA PARA CADA TÉCNICO SINALIZAR QUE A OM JÁ FOI TRATADA POR ELE, ASSIM OTIMIZANDO O TEMPO DE TRABALHO E EVITANDO O RETRABALHO DA EQUIPE.', NULL, N'SIM! HOJE A PLANILHA É COMPARTILHADA COM OS MEMBROS DA EQUIPE ONDE TODOS FICAM CIENTES DAS OMS QUE JÁ FORAM TRATADAS, ASSIM OTIMIZANDO O TEMPO DE TRABALHO.', N'TER GESTÃO DAS OM É IMPORTANTE', 0, NULL, NULL, '2026-08-06T00:00:00.000', '2026-08-07T16:43:45.000', N'81063720', NULL, NULL);
INSERT INTO #PVC VALUES (11631, N'87000071', N'87000089', N'Digitalización de toma de información geologica ', 1, N'Projects/Projetos', N'Se realiza la toma de datos geológicos de las muestras de sondaje en formularios de papel que posteriormente se pasan a una planilla digital, haciendo doble trabajo por parte de los asistentes ', N'Reducir el tiempo de trabajo en toma de datos geologicos ', N'#N/A', N'01 - Imagens/01 - Antes/11631.jpeg', N'Antes el proceso de almacenamiento de datos geológicos de las muestras era poco eficiente, propenso a errores humanos y lento, donde se generaban planillas en papel para luego ser digitalizadas. ', N'01 - Imagens/02 - Depois/11631.jpeg', N'Se genera aplicación digital para trabajar en tablets, donde los datos son almacenados solo una vez y pueden ser consultados en tiempo real, se evita duplicar trabajo y se ahorra tiempo. 
INSERT INTO #PVC VALUES (11632, N'87000071', N'87000088', N'Síntesis y orden de cambio de turno de asistentes ', 1, N'Projects/Projetos', N'Se realizan informes de cambios de turnos muy extensos y sin lineamientos. ', N'Orden y eficiencia en cambios de turnos', N'#N/A', N'01 - Imagens/01 - Antes/11632.jpeg', N'Informe de cambio de turno de los supervisores detallado, día a día, lo que genera un exceso de información y donde se pierden las cosas de importancia. ', N'01 - Imagens/02 - Depois/11632.jpeg', N'Nueva planilla donde se sintetiza lo más relevante de los trabajos, sobre esta misma se basa la comunicación durante el cambio de turno y almacenamiento de la información en Teams.', NULL, N'Si, se logra estandarizar el uso de un solo formato para el cambio de turno donde será más fácil acceder a la información y se reportarán los hechos relevantes del turno.', N'Estandarización de reportes', 0, NULL, NULL, '2026-07-21T00:00:00.000', '2026-08-07T18:36:36.000', N'87000071', NULL, NULL);
INSERT INTO #PVC VALUES (11633, N'87000071', N'87000089', N'Iniciativas deportivas', 2, N'Projects/Projetos', N'Se identifica que no existen iniciativas para realizar actividad fisica en proyecto después del horario laboral. ', N'Promover actividad fisica en proyecto', N'#N/A', N'01 - Imagens/01 - Antes/11633.jpeg', N'No se cuenta con equipamiento deportivos ni se organizan instancias deportivas que motive a salir del sedentarismo y mejorar la salud fisica de los trabajadores.', N'01 - Imagens/02 - Depois/11633.jpeg', N'Se gestiona la compra de elementos deportivos simples para realizar ejercicios posterior al horario laboral y se organiza un pequeño torneo de Ping-Pong, ya que se cuenta con mesa, pelotas y paletas. ', NULL, N'Si, los trabajadores muestran entusiasmo por la compra de los elementos para realizar ejercicio y el campeonato de ping pong que  fomenta la competencia sana, el vínculo y confianza entre trabajadores 
INSERT INTO #PVC VALUES (11634, N'87000071', N'87000089', N'Mejora en muestrera Proyecto Bloque El Loa', 1, N'Projects/Projetos', N'Solo se tiene malla protectora del sol pero se identifica vientos recurrentes en la zona', N'Protección del viento', N'#N/A', N'01 - Imagens/01 - Antes/11634.jpeg', N'Se tiene la muestrera tapada con malla en el techo para protección de la radiación UV, pero se identifica que la región presenta ráfagas de viento considerables en estas fechas. ', N'01 - Imagens/02 - Depois/11634.jpeg', N'Se habilitó una malla que protege del viento y especialmente de las partículas en suspensión, que generan incomodidad, irritación ocular, entre otras. ', NULL, N'Se confeccionó la muestrera, sin tomar en cuenta la posible condición de viento de la región. Ahora el personal se resguarda correctamente y puede desarrollar su trabajo con normalidad y seguros', N'Evaluar climatológicamente las áreas de trabajo ', 0, NULL, N'A better understanding of our targets by the business ', '2026-07-01T00:00:00.000', '2026-08-08T12:14:56.000', N'87000071', NULL, NULL);
INSERT INTO #PVC VALUES (11635, N'81035621', N'81035621', N'CAVALETE PARA TOTE BIN DE SABÃO', 3, N'Others/Outros', N'Atualmente o Tote Bin de sabão é utilizado sem um suporte adequado, dificultando o acesso ao ponto de drenagem e às operações de manuseio.', N'Desenvolver e instalar um cavalete para suporte do Tote Bin de sabão, garantindo maior estabilidade, ergonomia e segurança durante o manuseio, abastecimento e utilização do produto.', N'10324', N'01 - Imagens/01 - Antes/11635.jpeg', N'Atualmente o Tote Bin de sabão é utilizado sem um suporte adequado, dificultando o acesso ao ponto de drenagem e às operações de manuseio.', N'01 - Imagens/02 - Depois/11635.jpeg', N'Foi confeccionado e instalado um cavalete metálico para suporte do Tote Bin de sabão, elevando o recipiente a uma altura adequada para operação e drenagem do produto.', NULL, N'SIM, o problema foi resolvido. A instalação do cavalete proporcionou apoio adequado ao Tote Bin de sabão, eliminando a condição insegura identificada anteriormente.', N'Soluções simples e de baixo custo podem gerar ganhos significativos em segurança, ergonomia e organização.', 0, NULL, N'Otimização de HH estimada em 4h/mês.', '2026-08-01T00:00:00.000', '2026-08-09T04:40:50.000', N'81035621', NULL, NULL);
INSERT INTO #PVC VALUES (11636, N'81035621', N'81046347', N'SUPORTE PARA ENROLAR CABOS', 3, N'Others/Outros', N'Atualmente os cabos são armazenados diretamente no piso, ficando expostos a danos mecânicos, sujeira e emaranhamento.', N'Desenvolver e instalar um suporte para armazenamento e enrolamento de cabos, garantindo melhor organização da área, conservação dos cabos e eliminação de riscos de tropeços e quedas.', N'10324', N'01 - Imagens/01 - Antes/11636.jpeg', N'Os cabos eram armazenados diretamente sobre o piso, ficando desorganizados e sujeitos a emaranhamento, desgaste prematuro e contaminação por sujeira.', N'01 - Imagens/02 - Depois/11636.jpeg', N'Foi desenvolvido e instalado um suporte para enrolamento e armazenamento de cabos.', NULL, N'A instalação do suporte permitiu o armazenamento adequado dos cabos, eliminando a necessidade de mantê-los no piso. A melhoria proporcionou mais segurança, organização e praticidade no manuseio, atendendo aos objetivos estabelecidos pelo projeto.', N'A organização adequada de materiais e ferramentas contribui diretamente para a segurança, produtividade e conservação dos equipamentos.', 0, NULL, N'Using locally sourced seals, saved money on the initial replacement cost as well as money associated with replacing failed electrical components and ultimately the reliability of the crane and its downtime due to related failures.', '2026-08-02T00:00:00.000', '2026-08-09T04:51:15.000', N'81035621', NULL, NULL);
INSERT INTO #PVC VALUES (11637, N'81042207', N'81054975', N'Garantir a identificação clara e padronizada dos locais de repouso das tampas de vagões  (Pouso 1 e Pouso 2), eliminando ambiguidades e facilitando a gestão operacional da área  de descarga de vagões de cobre.', 3, N'Others/Outros', N'Durante inspeção realizada no galpão de descarga de vagões 
INSERT INTO #PVC VALUES (11638, N'81006946', N'81006946', N'SUPORTE DE CARREGADOR DE BATERIAS', 3, N'Others/Outros', N'NÃO TINHAMOS UM LOCAL ADEQUADO PARA POR O CARREGADOR DE BATERIAS', N'CRIAR UM LOCAL FIXO PARA O CARREGADOR', N'10346', N'01 - Imagens/01 - Antes/11638.jpeg', N'A ausência de um local fixo e definido para armazenar o carregador de baterias, lixadeiras e furadeira gera desorganização no ambiente de trabalho, dificultando a localização e o acesso aos equipamentos e ferramentas. Essa condição também pode aumentar o risco de extravios', N'01 - Imagens/02 - Depois/11638.jpeg', N'Foi desenvolvido e instalado um suporte específico para o carregador de baterias, estabelecendo um local fixo, identificado e organizado para sua armazenagem.', NULL, N'SIM! SE MANTERMOS O LOCAL ORGANIZADO', N'A PADRONIZAÇÃO E O MELHOR CAMINHO PARA UM LOCAL DE TRABOLHO SEGURO E ORGANIZADO', 0, NULL, N'Cost avoided would be associated with replacing the camera and components as they are currently no longer working and would need to be replaced on each crane if operations wanted to start using this system again. As well the potential for dropped objects has now been removed.', '2026-08-08T00:00:00.000', '2026-08-09T20:45:06.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11639, N'81024026', N'81024026', N'confecção degrau de segurança Pz 14', NULL, N'Projects/Projetos', N'Em alguns poligonos com patolamento equipamento o acesso equipamento fica arriscado podendo causar incidente', N'Melhor segurança ao subir equipamento', N'10137', N'01 - Imagens/01 - Antes/11639.jpeg', N'fizemos a melhoria na escada de acesso para adcionar mais um degrau', N'01 - Imagens/02 - Depois/11639.jpeg', N'Depois da melhoria tivemos melhor acesso ao equipamento tendo mais segurança nas atividades', NULL, N'com a resolução do problema melhoramos a atividade da operação e manutenção tendo mais segurança no acesso', N'segurança nas atividades', 0, NULL, N'This change resulted in an instant relief of these common and nuisance alarms that would knock the crane down for various lengths of time. Depending on where the crane was located, a ladder, AWP or scaffold would sometimes be required for a simple alignement repair.', '2026-08-04T00:00:00.000', '2026-08-09T22:45:18.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11640, N'81024026', N'81024026', N'Reforma de cerquites', NULL, N'Projects/Projetos', N'estavamos com muitos cerquites danificados gerando custo e desgaste', N'melhorar custo e sgurança', N'10137', N'01 - Imagens/01 - Antes/11640.jpeg', N'Muitos cerquites danificados causando excesso sucata e custo excessivo', N'01 - Imagens/02 - Depois/11640.jpeg', N'Cerquites recuperados melhorando ambiente de trabalho e redução de custo', NULL, N'Com esse reparo conseguimos reduzi despesa e melhorar eficiencia', N'podemos melhorar e evoluir diminuindo custo', 4, 1, N'Padronização de registro de dados e centralização do histórico para rastreabilidade.', '2026-08-02T00:00:00.000', '2026-08-09T22:55:35.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11641, N'81024026', N'81024026', N'Confeccionado suporte para extintor de incendio oxicorte', NULL, N'Projects/Projetos', N'Foi verificado que oxicorte não tinha extintor de incendio', N'Dar mais segurança atividade com oxicorte', N'10137', N'01 - Imagens/01 - Antes/11641.jpeg', N'Foi verificado que carinho oxicorte não tinha extintor incendio', N'01 - Imagens/02 - Depois/11641.jpeg', N'foi feito suporte para extintor e providenciado extintor trazendo mais segurança as atividades', NULL, N'Foi verificado que o carinho de oxicorte tem como ser mais seguros', N'temos ter sempre visão de segurança', 0, NULL, N'Sistema de lubrificação com graxa limpa, para que não haja nenhuma impureza que possa danificar componentes do equipamento.', '2026-08-03T00:00:00.000', '2026-08-09T23:13:24.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11642, N'1014096', N'1014096', N'Failed SX Flow Meter', 1, N'No Replication/Sem replicação', N'Process upsets increased HCL concentration in IMP SX. This was causing premature failure of 326-FIT-21242.', N'Prevent premature flow meter failure', N'10006', N'01 - Imagens/01 - Antes/11642.jpeg', N'HCL upsets were destroying the graphite gasket inside the flow meter. 2 failures in short succession occurred. Once the gasket failed, the process fluid destroyed the flow meter.', N'01 - Imagens/02 - Depois/11642.jpeg', N'Worked with vendor to find a much more suitable gasket for the regular service and for upsets. Updated the material master list and procured replacements.', NULL, N'YES - More compatible flow meter + gasket was installed.', N'Material Compatibility for SX Imp upsets.', 0, NULL, N'Ganhos Obtidos:
INSERT INTO #PVC VALUES (11643, N'1014096', N'1014096', N'Failed Acid Wash Pump', 1, N'No Replication/Sem replicação', N'Acid wash pump and motor 226-352-PNE-001 were upgraded under a previous MOC and it''s BOM wasn''t updated. Pump failed and maintenance had no spare parts.', N'Ensure Proper Sparing for Acid Wash Pump', N'10006', N'01 - Imagens/01 - Antes/11643.jpeg', N'Unable to locate spare pump after MOC completed (docs & SAP not updated), maintenance was about to order a new pump and motor.', N'01 - Imagens/02 - Depois/11643.jpeg', N'Found the MOC, located the correct pump information, found a surplus pump in inventory. Avoided purchase new $24k pump. Repair was planned, no wait for parts, no downtime.', NULL, N'BOM was updated to account for the MOC, existing surplus spare was utilized, no incremental cost to the business and no downtime.', N'Check inventory before buying new!', 24000, 3, N'Que o equipamento diminua os alarmes de falha por pressão do sistema/tanque hidráulico.', '2026-06-30T00:00:00.000', '2026-08-10T07:21:15.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11644, N'1014096', N'1014096', N'Repurposing Forgotten Lights', NULL, N'No Replication/Sem replicação', N'While cleaning up warehouse inventory, 3 Milwaukee work lights from 2014 were found. Unopened, unused and forgotten about. Find a use for them.', N'Find use for brand new, unused, forgotten about lights ', N'10006', N'01 - Imagens/01 - Antes/11644.jpeg', N'While cleaning up warehouse inventory, 3 Milwaukee work lights from 2014 were found. Unopened, unused and forgotten about. Find a use for them.', N'01 - Imagens/02 - Depois/11644.jpeg', N'Tristan H needed new lights for his maintenance team. Lights were re-purposed, taken and used. Avoided the need to purchase a set of new lights and avoided sending these lights for CMD.', NULL, N'Were able to utilize the lights rather than sending them to CMD. Avoided buying new lights. Used what was already on hand.', N'While cleaning up forgotten messes, you can find something valuable.', 1000, 3, N'Melhorou a segurança pois agora a empilhadeira tem o seu  próprio lugar para encaixar e executar a atividade de locomoção do gerador. ', '2026-06-17T00:00:00.000', '2026-08-10T07:35:48.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11645, N'1014096', N'1014096', N'Spare Gearbox Fitup Concerns', NULL, N'No Replication/Sem replicação', N'Spare gearbox for agitator 346-AGP-050 looked different from the existing in the field. The stoked couplings were also incorrect for the agitator.', N'Spare gearbox looked different from existing, could it be used?', N'10006', N'01 - Imagens/01 - Antes/11645.jpeg', N'Job stopped, mismatch between new and existing gearbox and spare couplings wrong.', N'01 - Imagens/02 - Depois/11645.jpeg', N'Clarified the spare was correct and design upgrade removed adaptor plate. Correct couplings sourced. BOM updated. Work rescheduled.', NULL, N'Avoided tossing out the spare gearbox and purchasing a new. Only had to purchase cheap new couplings (500$). Couplings updated on the BOM.', N'Parts that look slightly different can still be equivalent.', 10000, 3, N'alcançado com a eliminação do risco.', '2026-08-05T00:00:00.000', '2026-08-10T07:54:23.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11646, N'81043246', N'81046443', N'Controle de Rádios Operacionais', 1, N'No Replication/Sem replicação', N'O controle de rádios era realizado de forma inadequada, gerando dificuldades na gestão dos equipamentos, falta de informações sobre sua disponibilidade e falhas na comunicação entre as equipes. Como consequência, ocorriam atrasos nas atividades operacionais e impactos na produtividade.', N'Realizar o controle de rádios em campo ', N'10054', N'01 - Imagens/01 - Antes/11646.jpeg', N'O controle de rádios era realizado sem padronização, dificultando a gestão e a localização dos equipamentos. A falta de acompanhamento das entregas e devoluções favorecia o desvio de rádios, gerava falhas na comunicação entre as equipes e resultava em atrasos nas atividades operacionais, impactando diretamente a produtividade e a eficiência da operação.', N'01 - Imagens/02 - Depois/11646.jpeg', N'Com a implantação de um controle padronizado dos rádios, passou a ser possível acompanhar a disponibilidade dos equipamentos em tempo real, garantindo maior rastreabilidade e organização. Como resultado, houve redução das falhas de comunicação, mais agilidade na execução das atividades e aumento da eficiência operacional.', NULL, N'A meta foi alcançada com a implementação de um controle eficiente dos rádios, proporcionando maior rastreabilidade, redução de desvios, melhor comunicação entre as equipes e diminuição dos atrasos operacionais, aumentando a produtividade e a eficiência da operação.', N'A implementação do controle de rádios demonstrou a importância de manter um processo padronizado para a gestão dos equipamentos de comunicação.', 0, NULL, N'Este Kaizen tem como objetivo melhorar o processo de abastecimento do líquido de arrefecimento (ELC) da ilha de lubrificação, garantindo a integridade do fluido e eliminando riscos de contaminação durante a operação.hidráulicas.', '2026-08-03T00:00:00.000', '2026-08-10T10:21:30.000', N'81043246', NULL, NULL);
INSERT INTO #PVC VALUES (11647, N'1008789', N'1008789', N'Stock Availability Targets ', 1, N'Others/Outros', N'There was no visible targets on the Power BI page for Stock Availability, therefor there was no indicator of "what good looks like"', N'Visual display for availability targets ', N'0', N'01 - Imagens/01 - Antes/11647.jpeg', N'There was no visible targets on the Power BI page for Stock Availability, therefor there was no indicator of "what good looks like"', N'01 - Imagens/02 - Depois/11647.jpeg', N'Visual indicator added so everyone can be aware of what the targets are and if we are meeting them. ', NULL, N'Yes, a visual indicator added so everyone can be aware of what the targets are and if we are meeting them. ', N'Repeatable ', 0, NULL, N'Sem risco de queda', '2026-08-09T00:00:00.000', '2026-08-10T11:21:23.000', N'1008789', NULL, NULL);
INSERT INTO #PVC VALUES (11648, N'81063756', N'396366', N'Automatização da atualização do BI de RAF e Ações Stratws', 1, N'Others/Outros', N'O BI precisava ser diariamente atualizado manualmente consumindo cerca de 4h/mês de HH para essa tarefa.', N'Eliminar o processo manual de atualização diária do BI de RAF e Ações Stratws', N'10015', N'01 - Imagens/01 - Antes/11648.jpeg', N'Para a atualização diária da base de dados do BI de Controle de RAF e Ações Stratws, os dados de RAF, MCS e Ações do Stratws precisavam ser manualmente baixados do sistema DIARIAMENTE, gerando arquivos Excel que precisam ser carregados também em pastas do SharePoint.
INSERT INTO #PVC VALUES (11649, N'81043460', N'81043460', N'Harvesting Crane Enclosures', 1, N'Refining/Refino', N'Harvesting crane panel door seals have failed letting contaminants enter the panels causing extensive corrosion issues and premature failure of electrical components.', N'Seal the panels for better air quality, less corrosion', N'0', N'01 - Imagens/01 - Antes/11649.jpeg', N'Door seals on 16 harvesting crane panels have failed. Bought previously from Kuenz directly, and where quite costly with a long lead time, leading to additional corrosion and more electrical components to prematurely fail.', N'01 - Imagens/02 - Depois/11649.jpeg', N'Sourced replacements locally at a fraction of the cost and picked them up and installed within 24 hours. Saving time, money and component failures.', NULL, N'Yes', N'Source materials locally', 5000, 3, N'Engates protegidos contra sujeira e contaminação.
INSERT INTO #PVC VALUES (11650, N'81063756', N'81063756', N'Disparo de emails com relatório D-1 das frotas da mina Salobo', 1, N'Others/Outros', N'As informações encontravam-se em diferentes dashboards, tornando o processo de análise mais lento.', N'Consolidar em um relatório D-1 dados de performance, manutenção e gatilhos de RAF e MCS para promover uma análise mais rápida e centralizada dos responsáveis', N'10015', N'01 - Imagens/01 - Antes/11650.jpeg', N'A visão D-1 geralmente é realizada de forma dinâmica no BI de Performance de Frotas alternando entre as frotas e datas; e paralelizando com o BI de RAF e MCS para gerenciamento dos gatilhos.', N'01 - Imagens/02 - Depois/11650.jpeg', N'Este relatório já consolida em um único documento PDF o cenário D-1 e acumulado mensal dos indicadores de performance das frotas, gatilhos de RAF e MCS e Resumo de Paradas de Manutenção.', NULL, N'Hoje o time de engenharia de confiabilidade recebe diariamente um PDF consolidando dados de performance, paradas de manutenção e gatilhos de RAF e MCS em visão D-1 e acumulado mensal.', N'Criação de fluxo integrado com Power BI para disparo de e-mail com corpo escrito em HTML e CSS.', 0, NULL, NULL, '2026-07-31T00:00:00.000', '2026-08-10T12:54:06.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (11651, N'81043460', N'81043460', N'Remove Thermal Camera Components (RTMS)', 2, N'Refining/Refino', N'RTMS components are no longer required on the harvesting cranes, There are PMS to replace components we will no longer need to replace, as well the camera and associated parts pose a safety risk as a potential dropped object.', N'Remove RTMS components', N'0', N'01 - Imagens/01 - Antes/11651.jpeg', N'RTMS components are no longer required by the operations team and both mechanical and electrical components need to be removed from the bridge. ', N'01 - Imagens/02 - Depois/11651.jpeg', N'All components removed, no more risk of potential dropped objects!', NULL, N'yes', N'Easier solutions, sometime more economical and safe.', 20000, 3, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-04T00:00:00.000', '2026-08-10T13:49:54.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (11652, N'81043460', N'81043460', N'Increase Reflector Pad Size', 1, N'Refining/Refino', N'Harvesting crane rails, banging, knocking and misalignment issues cause the lasers to come off their reflective pad faulting out the cranes. Depending on the cranes location this could result in 20 min to +6 hours downtime and production loss.', N'Increase reliabaility of crane, reduce downtime for nuissance issues.', N'0', N'01 - Imagens/01 - Antes/11652.jpeg', N'Surface area of reflective pad and reflector isn''t suitable anymore for cranes operation and causes alarms and faults while harvesting in bay 3 and bay 4.', N'01 - Imagens/02 - Depois/11652.jpeg', N'Increase reflector pad by 2X to compensate for the crane rail issues further down the tank house. This has eliminated the nuisance faults, alarm and downtime associated with Crane 3 lasers.', NULL, N'Yes', N'A simple fix is sufficient enough for us to minimize downtime, all completed with materials on hand.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVÁVEIS.', '2026-08-10T00:00:00.000', '2026-08-10T13:59:45.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (11653, N'81063756', N'81063756', N'Formulário para cadastro de ganhos efetivos com alteração em estratégia de manutenção', 1, N'No Replication/Sem replicação', N'Ausência de repositório centralizado de dados referentes à ganhos reais com alterações em estratégias de manutenção, dificultando o registro e rastreabilidade dos ganhos obtidos.', N'Padronizar registro e centralizar histórico em BI dos ganhos efetivos obtidos com alteração em estratégia de manutenção', N'10015', N'01 - Imagens/01 - Antes/11653.jpeg', N'Ausência de repositório centralizado de dados referentes à ganhos reais com alterações em estratégias de manutenção, dificultando o registro e rastreabilidade dos ganhos obtidos.', N'01 - Imagens/02 - Depois/11653.jpeg', N'O cadastramento foi padronizado com a criação do formulário em MS Forms que grava as respostas e evidência anexada em lista do SharePoint.
INSERT INTO #PVC VALUES (11654, N'81057561', N'81057561', N'Filtro de Linha de Graxa', 1, N'Open Pit/Poço aberto', N'Komatsu alegou que havia contaminantes na graxa do equipamento, em virtude da falta de proteção para o abastecimento por parte da lubrificação, sendo assim colocamos um filtro na linha para proteção no abastecimento.', N'Realizar uma melhoria com a instalação de um filtro na linha de abastecimento de graxa.', N'10015', N'01 - Imagens/01 - Antes/11654.jpeg', N'Havia um filtro padrão na linha de abastecimento, mas muito ineficiente, o que fez com que fosse permitido a entrada de impurezas durante o abastecimento da graxa, contaminando o sistema.', N'01 - Imagens/02 - Depois/11654.jpeg', N'Foi instalado um filtro mais robusto, como iniciativa de melhoria, para resguardar melhor o sistema de lubrificação quanto a contaminantes oriundos do ato do abastecimento de graxa.', NULL, N'SIM, agora com a melhoria há um filtro mais robusto, era solução que era ação do plano diretor, onde precisamos buscar uma solução eficaz.', N'Importância da boa lubrificação.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-09T00:00:00.000', '2026-08-10T14:34:18.000', N'81057561', NULL, NULL);
INSERT INTO #PVC VALUES (11655, N'492669', N'492669', N'CONTROLE ENVIO DE CILINDROS, AMPOLAS E TANQUE PARA RECARGA', 1, N'Others/Outros', N'Inexistência de base contendo todas as solicitações para emissão NF .', N'BASE DE CONTROLE CONSOLIDADA', N'10234', N'01 - Imagens/01 - Antes/11655.jpeg', N'Não existia uma base de controle consolidada para o envio de cilindros, ampolas e tanques para recarga. As solicitações eram realizadas por meio da emissão de Nota Fiscal e as informações ficavam disponíveis apenas no SAP, dificultando consultas futuras e rastreabilidade. Para localizar uma NF específica era necessário realizar pesquisas por diferentes critérios no sistema, consumindo em média 30 minutos por consulta. Além disso, não era possível obter rapidamente informações gerenciais, como quantidade de envios realizados no mês, responsáveis pelas solicitações, aprovações e ativos atendidos.', N'01 - Imagens/02 - Depois/11655.jpeg', N'Foi criada uma base única para controle das solicitações de saída de tanques, cilindros e ampolas para recarga, consolidando informações como Nota Fiscal, Ordem de Manutenção, ativo atendido, data da emissão, aprovadores e fornecedor responsável. Com a centralização dos dados, o tempo de localização de uma NF foi reduzido de aproximadamente 30 minutos para 5 minutos, representando uma redução de 83% no tempo gasto para consulta das informações. A solução também possibilitou maior rastreabilidade, padronização dos registros e geração rápida de informações gerenciais sobre o processo.', NULL, N'Tivemos muitos ganhos com o processo, o principal foi a centralização das demandas com todas as solicitações em banco de dados.', N'Agilidade nas informações', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-03T00:00:00.000', '2026-08-10T14:36:13.000', N'492669', NULL, NULL);
INSERT INTO #PVC VALUES (11656, N'81057561', N'81057561', N'Melhoria Regulador de Pressão Tanque Hidráulico', 1, N'Open Pit/Poço aberto', N'Havia uma repetição de falhas, onde era decorrente de alarmes de pressão do tanque hidráulico do equipamento, gerando impacto no MTBF principalmente.', N'Melhorar a regulagem de pressão  das linhas de alimentação do sistema  hidráulico', N'10015', N'01 - Imagens/01 - Antes/11656.jpeg', N'O regulador de pressão padrão apresentada alarmes, onde deveria haver falha de pressão no sistema hidráulico, porém, onde quando o equipamento parava não era identificada falha, entendemos então que o regulador não era confiavel.', N'01 - Imagens/02 - Depois/11656.jpeg', N'Foi instalado um modelo novo de regulador de pressão no equipamento, para melhorar a confiabilidade do sistema hidráulico como um todo.', NULL, N'SIM, agora com este modelo entendemos que o MTBF não será mais impactado pelo modo de falhas.', N'Importância de monitoramento da condição do equipamento.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVÁVEIS.', '2026-08-09T00:00:00.000', '2026-08-10T15:09:37.000', N'81057561', NULL, NULL);
INSERT INTO #PVC VALUES (11657, N'92000525', N'485334', N'Suporte do gerador a Diesel', NULL, N'Others/Outros', N'Anteriormente o gerador era apoiado diretamente sobre o palete de madeira. Quando não havia palete, o equipamento era apoiado no chão, o que causava amassamento da base e danos estruturais.', N'Suporte para fazer o içamento com empilhadeira', N'10324', N'01 - Imagens/01 - Antes/11657.jpeg', N'O gerador era movimentado sobre palete, que frequentemente amassava ou quebrava pelo excesso de peso. Sem palete, o equipamento era arrastado direto no chão, sem apoio, causando dano estrutural e dificuldade na locomoção.', N'01 - Imagens/02 - Depois/11657.jpeg', N'Foi fabricado um suporte para o gerador. Agora é possível movimentá-lo com a empilhadeira de forma segura, eliminando o risco de dano e agilidade durante a movimentação.', NULL, N'Sim, pois agora temos local adequado para fazer o içamento que não vai gerar danos ao equipamento e será feito de forma segura.', N'Otimização e risco e melhoria no processo', 0, NULL, N'Melhorar a visibilidade das informações críticas do processo, eliminando alarmes obsoletos e reduzindo a poluição visual no supervisório, para proporcionar monitoramento mais eficiente e maior agilidade na tomada de decisão operacional.', '2026-08-07T00:00:00.000', '2026-08-10T15:18:02.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11658, N'471876', N'471876', N'DRENO DE LIMPEZA', 1, N'Others/Outros', N'Na sala Open space não havia dreno para agua de limpeza', N'ELIMINAR RISCO ', N'10032', N'01 - Imagens/01 - Antes/11658.jpeg', N'Na sala Open space, não havia dreno para limpeza, então a agua era jogada pela porta de emergência(ponto de atenção) com a nova reforma, a fiação elétrica em calhas passa abaixo do piso da porta de emergência, vindo a cair agua na fiação, além de abrir toda hora de limpeza a porta, nisso o risco de ficar escorregadio devido o sabão.', N'01 - Imagens/02 - Depois/11658.jpeg', N'Foi feito um dreno na sala, onde a agua de limpeza segue outro caminho, assim evitando esse trajeto com esses dois riscos, com também facilitou para nossos colaboradores da limpeza .', NULL, N'risco eliminado', N'que observando a gente resolve situações', 0, NULL, N'.', '2026-08-06T00:00:00.000', '2026-08-10T15:28:19.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11659, N'81056513', N'552777', N'Melhoria no Sistema de Abastecimento do Líquido de Arrefecimento da Ilha de Lubrificação', 1, N'Others/Outros', N'Antes da implementação da melhoria, o abastecimento era realizado por apenas uma bomba pneumática da Graco, utilizada tanto para o líquido de arrefecimento (ELC) quanto para os óleos GEAR 150 e GEAR 220.
INSERT INTO #PVC VALUES (11660, N'81022747', N'81006480', N'SUPORTE  DO LAVA OLHOS', 3, N'Others/Outros', N'Antes não havia um suporte de apoio', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11660.jpeg', N'Não havia nenhum suporte de sustentação como base de apoio', N'01 - Imagens/02 - Depois/11660.jpeg', N'Foi confeccionado um suporte para melhor sustentação do material', NULL, N'Melhorando a segurança de quem vai ultilizar.', N'Organização', 0, NULL, N'ELIMINAÇÃO DO RISCO', '2026-08-09T00:00:00.000', '2026-08-10T17:03:55.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11661, N'81020607', N'723908', N' MELHORIA NO SISTEMA DE TRANSFERÊNCIA DE ÓLEO HIDRÁULICO', 1, N'Others/Outros', N'O processo de transferência dos óleos era mais demorado e exigia maior esforço operacional, aumentando o tempo gasto para realizar o abastecimento.', N'Melhoria continua', N'10139', N'01 - Imagens/01 - Antes/11661.jpeg', N'As bombas utilizadas para transferência dos óleos hidráulicos não possuíam a conexão adequada para facilitar a transferência dos óleos dos tambores para os Totibins.
INSERT INTO #PVC VALUES (11662, N'81020607', N'81016957', N'Implantação de tampas protetoras e identificação dos engates rápidos de abastecimento de graxa.', 1, N'Others/Outros', N'Os engates rápidos estavam expostos à poeira, la ma e outros contaminantes.
INSERT INTO #PVC VALUES (11663, N'503436', N'503436', N'MONITORAMENTO DO MUNHÃO DO CILINDRO DE DIREÇÃO', 1, N'Others/Outros', N'Os munhões dos caminhões fora-de-estrada CAT 797F referente ponto de articulação e suporte entre o cilindro de elevação que funciona como um eixo de articulação para os cilindros. No entanto Durante inspeções preditivas e preventivas, é comum encontrar: Falha de lubrificação, Aumento de temperatura por atrito.', N'ACOMPANHAR  POSSIVEIS DESGASTES ANTECIPADOS ', N'10024', N'01 - Imagens/01 - Antes/11663.jpeg', N'Ao longo do ciclo operacional do equipamento, a deficiência na lubrificação do munhão, associada à baixa frequência de inspeções sensitivas e preventivas, pode acelerar o processo de degradação do componente. Como consequência, é comum identificar condições como:
INSERT INTO #PVC VALUES (11664, N'81034776', N'81034776', N'Identificação Motores uh SLB III', 1, N'Others/Outros', N'Falta de identificação adequada podendo gerar lentidão para resolução de falhas.', N'Tornar atuação mas rápida e segura', N'10290', N'01 - Imagens/01 - Antes/11664.jpeg', N'Falta de identificação adequada no MO-2305SA-01-ST001-M1 podendo gerar lentidão para resolução de falhas.', N'01 - Imagens/02 - Depois/11664.jpeg', N'Com melhoria realizada no MO-2305SA-01-ST001-M1 passamos a ter uma condição de trabalho mas adequada, tornando as atuações mas rápidas e seguras, criando um ambiente mas confortável para a execução de atividades.', NULL, N'SIM. Com melhoria realizada no MO-2305SA-01-ST001-M1 passamos a ter uma condição de trabalho mas adequada, tornando as atuações mas rápidas e seguras, criando um ambiente mas confortável para a execução de atividades.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ UMA GRANDE DIFERENÇA NA SEGURANÇA E PRODUTIVIDADE.', 0, NULL, NULL, '2026-08-10T00:00:00.000', '2026-08-11T04:03:34.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (11665, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES UH SLB III.', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10290', N'01 - Imagens/01 - Antes/11665.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST001-M2 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/11665.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM. COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'cleaning / inspection not forgotten ', '2026-08-10T00:00:00.000', '2026-08-11T04:30:37.000', N'81034776', NULL, NULL);
