INSERT INTO #PVC VALUES (11667, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES UH SLB III.', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10290', N'01 - Imagens/01 - Antes/11667.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST001-M6 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/11667.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M6 PASSAMOS ATER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM. COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M6 PASSAMOS ATER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, NULL, '2026-08-10T00:00:00.000', '2026-08-11T04:52:19.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (11668, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES UH SLB III.', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10290', N'01 - Imagens/01 - Antes/11668.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST001-M7 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/11668.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M7 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM. COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M7 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'IMPLEMENTAR A GERAÇÃO PADRONIZADA DE CHECK LISTS SAP A PARTIR DE LAUDOS TÉCNICOS UTILIZANDO COPILOT, REDUZINDO O TEMPO DE PLANEJAMENTO, ELIMINANDO VARIAÇÕES DE INTERPRETAÇÃO, MELHORANDO A QUALIDADE DAS LISTAS DE TAREFAS E AUMENTANDO A RASTREABILIDADE DAS ATIVIDADES EXECUTADAS EM CAMPO.', '2026-08-10T00:00:00.000', '2026-08-11T05:01:18.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (11669, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES SLB III.', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10290', N'01 - Imagens/01 - Antes/11669.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST001-M8 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/11669.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M8 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM. COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M8 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'ELIMINAR O RISCO DE TOMBAMENTO DA PRATELEIRA E DE QUEDA DE MATERIAIS POR MEIO DA IMPLEMENTAÇÃO DE REFORÇO ESTRUTURAL, GARANTINDO MAIOR ESTABILIDADE DA ESTRUTURA, SEGURANÇA DAS PESSOAS, INTEGRIDADE DOS MATERIAIS ARMAZENADOS E CONFORMIDADE COM AS BOAS PRÁTICAS DE ARMAZENAMENTO.', '2026-08-10T00:00:00.000', '2026-08-11T05:08:44.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (11670, N'997932', N'538696', N'IN-PIT A VISTA', 1, N'Others/Outros', N'Se dar sempre que precisamos visualizar as bombas do IN-IPIT , pôs para isso precisamos abrir outras duas telas, o que dificulta visualizar e ou reconhecer possíveis falhas.', N'Otimizar a visibilidade em tempo real da vazão e condição das bombas do IN-PIT.', N'10054', N'01 - Imagens/01 - Antes/11670.jpeg', N'Havia condições de alarme referentes às bombas da balsa, equipamentos que já não existiam mais em campo, gerando poluição visual na tela de supervisão com informações irrelevantes. Ao mesmo tempo, informações críticas das bombas do IN-PIT, de extrema importância para a operação do processo, permaneciam ocultas em uma tela específica, dificultando a rápida identificação e atuação operacional. ', N'01 - Imagens/02 - Depois/11670.jpeg', N'Após a implementação das melhorias na tela do supervisório de Espessamento e Bombas, foram removidos alarmes e informações referentes a equipamentos desativados, eliminando a poluição visual. As informações críticas das bombas do IN-PIT passaram a ser exibidas de forma mais acessível e destacada, proporcionando maior agilidade na identificação de anomalias e suporte à tomada de decisão operacional.', NULL, N'A melhoria implementada atingiu a meta proposta ao eliminar alarmes de equipamentos desativados, reduzir a poluição visual no supervisório e destacar as informações críticas das bombas do IN-PIT, proporcionando maior eficiência no monitoramento e maior rapidez na tomada de decisão operacional.', N'Priorizar informações críticas e remover alarmes obsoletos melhora a eficiência operacional.', 0, NULL, N'Este Kaizen transformou um processo que dependia de análises detalhadas em uma gestão visual simples e padronizada. A utilização das cores verde, azul e amarelo permite identificar instantaneamente o nível de conclusão de cada OM, aumentando a eficiência operacional, reduzindo perdas de tempo e fortalecendo o controle e a confiabilidade do processo de manutenção.', '2026-08-10T00:00:00.000', '2026-08-11T09:27:16.000', N'997932', NULL, NULL);
INSERT INTO #PVC VALUES (11671, N'81013885', N'81046945', N' PORTÃO DE SEGURANÇA DA 2251 BP 03', 2, N'Others/Outros', N'
INSERT INTO #PVC VALUES (11672, N'81023799', N'81031088', N'Mine to Mill Stockpile Spreadsheet ', 1, N'Underground/Subterrâneo', N'Previously, the mine and mill plan have been established using one document. The new document is designed to separate the two plans and allow for stockpile considerations to better optimize both plans. ', N'Process Improvement ', N'10311', N'01 - Imagens/01 - Antes/11672.jpeg', N'The previous spreadsheet did not distinguish between the mine plan and the mill plan. ', N'01 - Imagens/02 - Depois/11672.jpeg', N'The new spreadsheet will include a Stockpile tab which can utilized by the mill to plan blending and throughput. This will allow greater flexibility for both mining and milling plans. ', NULL, N'Yes, the new spreadsheet provides greater planning flexibility. ', N'Efficiency Improvement', 0, NULL, NULL, '2026-08-10T00:00:00.000', '2026-08-11T15:59:41.000', N'81023799', NULL, NULL);
INSERT INTO #PVC VALUES (11673, N'81046197', N'81046197', N'CALIBRAGEM SEGURA', 2, N'Others/Outros', N'A execução da atividade de aferição de pressão e calibração de acumuladores em unidades hidráulicas expunha os colaboradores a condições inseguras de trabalho, devido à falta de acesso ergonômico e seguro aos pontos de intervenção do equipamento.', N'SEGURANÇA', N'10362', N'01 - Imagens/01 - Antes/11673.jpeg', N' A execução da atividade de aferição de pressão e calibração de acumuladores em unidades hidráulicas expunha os colaboradores a condições inseguras de trabalho, devido à falta de acesso ergonômico e seguro aos pontos de intervenção ou documentação de projetos de engenharia:
INSERT INTO #PVC VALUES (11674, N'81046197', N'81046197', N'ELIMINAÇÃO DE RISCO DE MANUSEIO ', 2, N'Projects/Projetos', N'O problema atual se resume em uma operação semanal de coleta e descarte de óleo e graxa residuais dos moinhos de bolas que expõe os trabalhadores a sérios riscos devido às péssimas condições ergonômicas e ambientais. Tudo começa no corredor de coleta, um espaço extremamente estreito e confinado por paredes de concreto e estruturas metálicas que impede o uso de maquinários logísticos comuns, como empilhadeiras ou paleteiras. Por causa dessa restrição de espaço, os operadores são obrigados a realizar manobras humanas complexas e um esforço físico excessivo para movimentar manualmente os tambores metálicos pesados desde a base de recebimento. Para agravar a movimentação dessa carga, o piso de concreto de todo o trajeto encontra-se severamente contaminado por óleo e umidade, tornando-se altamente escorregadio e gerando um risco iminente de quedas de mesmo nível que podem resultar em fraturas ou lesões graves.
INSERT INTO #PVC VALUES (11675, N'81013885', N'81013885', N' Portão de segurança de acesso a 2251 BP 04', 2, N'Others/Outros', N'A área de acesso às bombas não possuía portão de segurança, deixando o acesso ao local aberto e expondo os colaboradores ao risco de queda no fosso durante a execução de atividades de inspeção e manutenção.', N' Aumentando a segurança', N'10362', N'01 - Imagens/01 - Antes/11675.jpeg', N'ANTES
INSERT INTO #PVC VALUES (11676, N'81046570', N'81046570', N'Separate a kit into individual parts', 1, N'Others/Outros', N'Sleeve kit for tailings buffer pumps, consisted of three parts: gasket, O rings and sleeve. Often times the o-rings were the only part needed ($3 part). The sleeve is $1400. So, we could JUST order the O rings, I separated the three parts, stock coded them and got the stocked in inventory. This way we can just order the O ring and not the sleeve, saving money in the end. ', N'To save money', N'10092', N'01 - Imagens/01 - Antes/11676.jpeg', N'Sleeve kit for tailings buffer pumps, consisted of three parts: gasket, O rings and sleeve. Often times the o-rings were the only part needed ($3 part). The sleeve is $1400. So, we could JUST order the O rings, I separated the three parts, stock coded them and got the stocked in inventory. This way we can just order the O ring and not the sleeve, saving money in the end. ', N'01 - Imagens/02 - Depois/11676.jpeg', N'Now we can order the parts individually and NOT have to order the entire kit. Procurement will not have to order as many sleeves, also, resulting in savings for them as well.', NULL, N'Yes, the problem was solved', N'If you can separate a kit (a group of parts) into individual parts, when not all the parts are needed, look at the possibility. Saving money for the mill and the warehouse.', 1400, 3, N'Fortalecimento da conscientização e do comprometimento da equipe com os requisitos de segurança.
INSERT INTO #PVC VALUES (11677, N'1009878', N'1010346', N'Victaulic Groover - Hand Tool', NULL, N'Refining/Refino', N'Concerns have been raised about some pipe locations on the pipeline.  If a repair is urgently required, it may be difficult to prepare the pipe with new victaulic grooves as it is insulated and would require a crane for removal of the pipe to send it to the shop for grooving.', N'Perform repair in place', N'0', N'01 - Imagens/01 - Antes/11677.jpeg', N'Piping is concerning in some areas, and repairs may be required during victaulic coupling replacement.  It would be difficult to remove existing piping and send to the shop for grooving.', N'01 - Imagens/02 - Depois/11677.jpeg', N'A victualic hand groover has been ordered.  With this unit on hand, we will be able to prepare piping in place for repair purposes.', NULL, N'Yes.  Repairs can be completed in a much more cost effective manner.', N'Portable Hand Tool', 5000, 3, N'Formalização dos pontos abordados durante a rodada de mina, através do mapa.', '2026-08-11T00:00:00.000', '2026-08-12T06:21:44.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11678, N'81036747', N'81036747', N'222 Board', 1, N'Others/Outros', N'No routines posted in 222', N'make routine clear', N'0', N'01 - Imagens/01 - Antes/11678.jpeg', N'Board in 222 sat lab had good information but was missing the routines. ', N'01 - Imagens/02 - Depois/11678.jpeg', N'If you couldnt remember what was written on the whitebaord in the 221 tech office from start of shift it is now in a chart in the 222 sat lab. ', NULL, N'yes', N'make expectations clear and easy to follow', 0, NULL, N'Maior controle de custos, permitindo identificar os gastos associados aos andaimes fixos e direcionar ações para otimização de recursos.', '2026-08-11T00:00:00.000', '2026-08-12T06:59:17.000', N'81036747', NULL, NULL);
INSERT INTO #PVC VALUES (11679, N'81036747', N'81036747', N'222 Step Stool ', 2, N'Refining/Refino', N'Cabinets/boards in 222 are high and not user friendly for smaller technicians', N'Create a safe way to reach items in sat lab', N'0', N'01 - Imagens/01 - Antes/11679.jpeg', N'Items in the 222 Sat Lab are stored in cabinets that are very tall. There are individuals (myself included) that cannot reach the top shelf safely. With the addition of the tool cabinet the grabber tool is not safe to pick up drills.', N'01 - Imagens/02 - Depois/11679.jpeg', N'A small step stool was ordered for the Sat Lab. This ensures that technicians are not straining to reach, climbing on counters or dropping items from above their heads. ', NULL, N'yes. Step was ordered, labelled, and storage area created. ', N'order items that make the work place safe for all ', 0, NULL, N'Promover manobras mais seguras durante o transporte e posicionamento de radares e placas fotovoltaicas, reduzindo o risco de colisões, atropelamentos e danos aos equipamentos.
INSERT INTO #PVC VALUES (11680, N'81031846', N'1005740', N'Standardized Travel Eligibility Document', 1, N'Others/Outros', N'Lack of standardized travel criteria across all VNL contracts sometimes results in excessive billing hours for travel and related travel expenses.', N'Elimiinate commercial ambiguity by establishing a standardized framework governing travel eligibility, travel time compensation and expense reimbursement.', N'10026', N'01 - Imagens/01 - Antes/11680.jpeg', N'Lack of standardized travel criteria across all VNL contracts sometimes results in excessive billing hours for travel and related travel expenses.', N'01 - Imagens/02 - Depois/11680.jpeg', N'Developed a detailed travel document for VNL that establishes a standardized framework governing travel eligibility, travel time compensation, & expense reimbursement for all Contractor Personnel.', NULL, N'A detailed travel document was created and will now eliminate commercial ambiguity and provide a standardized framework for travel across VNL contracts which will reduce invoice disputes, etc. NOTE: Estimated $100k annually for Expected Outcome. I am unsure how to calculate a true value.', N'Importance of eliminating commercial ambiguity and standardization across VNL.', 100000, 3, N'Disponibilizar uma ferramenta que permita identificar rapidamente viagens com divergências entre origem e subárea, reduzindo o tempo de análise, eliminando retrabalho e aumentando a confiabilidade das informações registradas no OP PRO.', '2026-08-11T00:00:00.000', '2026-08-12T08:26:23.000', N'81031846', NULL, NULL);
INSERT INTO #PVC VALUES (11681, N'81011654', N'81011654', N'LISTA DE TAREFAS: GERAÇÃO DE CHECK LISTS SAP  LAUDOS TÉCNICOS COM COPILOT', 1, N'Others/Outros', N'A ELABORAÇÃO MANUAL DE LISTAS DE TAREFAS SAP A PARTIR DE LAUDOS TÉCNICOS DEMANDA TEMPO E ESTÁ SUJEITA A DIFERENTES INTERPRETAÇÕES, IMPACTANDO A PADRONIZAÇÃO E A QUALIDADE DAS INSTRUÇÕES DE MANUTENÇÃO.', N'PADRONIZAR E AGILIZAR A GERAÇÃO DE CHECK LISTS SAP A PARTIR DE LAUDOS TÉCNICOS, REDUZINDO O TEMPO DE PLANEJAMENTO E MELHORANDO A QUALIDADE DAS LISTAS DE TAREFAS.', N'10279', N'01 - Imagens/01 - Antes/11681.jpeg', N'A ELABORAÇÃO DE LISTAS DE TAREFAS SAP A PARTIR DE LAUDOS TÉCNICOS ERA REALIZADA MANUALMENTE, EXIGINDO ANÁLISE INDIVIDUAL DE CADA DOCUMENTO. O PROCESSO DEMANDAVA TEMPO E ESTAVA SUJEITO A DIFERENTES INTERPRETAÇÕES, GERANDO VARIAÇÃO NA QUALIDADE E PADRONIZAÇÃO DAS INSTRUÇÕES DE MANUTENÇÃO.', N'01 - Imagens/02 - Depois/11681.jpeg', N'FOI DESENVOLVIDO UM PROMPT NO COPILOT PARA CONVERTER LAUDOS TÉCNICOS EM LISTAS DE TAREFAS (CHECK LISTS) SAP PADRONIZADAS. A SOLUÇÃO REDUZIU O TEMPO DE PLANEJAMENTO, MELHOROU A QUALIDADE DAS INSTRUÇÕES, FACILITOU O REGISTRO DAS ATIVIDADES PELA EXECUÇÃO E AUMENTOU A RASTREABILIDADE E A PADRONIZAÇÃO DOS SERVIÇOS', NULL, N'O PROBLEMA FOI RESOLVIDO COM A IMPLEMENTAÇÃO DE UM PROMPT NO COPILOT CAPAZ DE CONVERTER LAUDOS TÉCNICOS EM CHECK LISTS SAP PADRONIZADOS. A SOLUÇÃO REDUZIU O TEMPO DE ANÁLISE E ELABORAÇÃO DAS LISTAS DE TAREFAS, AUMENTOU A PADRONIZAÇÃO DAS INSTRUÇÕES E FACILITOU O REGISTRO DAS ATIVIDADES PELA EQUIPE DE EXECUÇÃO.', N'LIÇÕES APRENDIDAS  A PADRONIZAÇÃO ASSOCIADA AO COPILOT REDUZ O TEMPO DE PLANEJAMENTO, MELHORA A QUALIDADE DAS LISTAS DE TAREFAS E AUMENTA A RASTREABILIDADE DAS ATIVIDADES.', 0, NULL, N'Redução do risco de quedas na Escada 02 do Lavador, aumento da segurança dos usuários, adequação aos padrões de segurança da área, melhoria das condições de acesso e eliminação da condição insegura identificada.', '2026-08-10T00:00:00.000', '2026-08-12T09:07:04.000', N'81011654', NULL, NULL);
INSERT INTO #PVC VALUES (11682, N'81011654', N'81011654', N'REFORÇO ESTRUTURAL DE PRATELEIRA PARA AUMENTO DA SEGURANÇA OPERACIONAL', 3, N'Others/Outros', N'DURANTE INSPEÇÃO REALIZADA NA FÁBRICA DE MANGUEIRA, FOI IDENTIFICADO QUE UMA PRATELEIRA APRESENTAVA EXCESSO DE MATERIAIS ARMAZENADOS E FIXAÇÃO INADEQUADA, COMPROMETENDO SUA ESTABILIDADE E SEGURANÇA. ESSA CONDIÇÃO GERAVA POTENCIAL DE TOMBAMENTO DA ESTRUTURA E QUEDA DE MATERIAIS, EXPONDO PESSOAS E EQUIPAMENTOS A RISCOS DE ACIDENTES E DANOS MATERIAIS.', N'ELIMINAR O RISCO DE TOMBAMENTO DA PRATELEIRA E DE QUEDA DE MATERIAIS, GARANTINDO CONDIÇÕES SEGURAS DE ARMAZENAMENTO, PRESERVAÇÃO DOS RECURSOS MATERIAIS E MAIOR SEGURANÇA PARA AS PESSOAS QUE CIRCULAM NA ÁREA.', N'10279', N'01 - Imagens/01 - Antes/11682.jpeg', N'A PRATELEIRA APRESENTAVA EXCESSO DE MATERIAIS ARMAZENADOS E FIXAÇÃO INADEQUADA, COMPROMETENDO A ESTABILIDADE DA ESTRUTURA. ESSA CONDIÇÃO GERAVA RISCO DE TOMBAMENTO E QUEDA DE MATERIAIS, COM POTENCIAL DE CAUSAR ACIDENTES, DANOS AO PATRIMÔNIO E IMPACTOS À SEGURANÇA DAS PESSOAS QUE TRANSITAM PELA ÁREA.', N'01 - Imagens/02 - Depois/11682.jpeg', N'REALIZADO O REFORÇO E A FIXAÇÃO DA PRATELEIRA POR MEIO DA INSTALAÇÃO E SOLDAGEM DE CANTONEIRAS ESTRUTURAIS, ALÉM DA REORGANIZAÇÃO DOS MATERIAIS ARMAZENADOS. A MELHORIA ELIMINOU O RISCO DE TOMBAMENTO E QUEDA DE MATERIAIS, PROPORCIONANDO MAIOR SEGURANÇA, ESTABILIDADE DA ESTRUTURA E MELHOR ORGANIZAÇÃO DO AMBIENTE DE TRABALHO.', NULL, N'SIM. O PROBLEMA FOI RESOLVIDO. A INSTALAÇÃO DA CANTONEIRA DE REFORÇO PROPORCIONOU O TRAVAMENTO ESTRUTURAL DA PRATELEIRA, ELIMINANDO A CONDIÇÃO DE INSTABILIDADE IDENTIFICADA. COM A MELHORIA IMPLEMENTADA, O RISCO DE TOMBAMENTO E QUEDA DE MATERIAIS FOI ELIMINADO, ATENDENDO INTEGRALMENTE AO OBJETIVO PROPOSTO E ELEVANDO O NÍVEL DE SEGURANÇA DA ÁREA.', N'A IDENTIFICAÇÃO PROATIVA DE CONDIÇÕES INSEGURAS E A IMPLEMENTAÇÃO DE SOLUÇÕES SIMPLES E DE BAIXO CUSTO PODEM ELIMINAR RISCOS OPERACIONAIS, AUMENTANDO A SEGURANÇA E A CONFIABILIDADE DAS ESTRUTURAS DE ARMAZENAMENTO', 0, NULL, NULL, '2026-08-05T00:00:00.000', '2026-08-12T10:12:00.000', N'81011654', NULL, NULL);
INSERT INTO #PVC VALUES (11683, N'81063720', N'81063720', N'Padronização Visual de Status das Ordens de Manutenção (OM)', 1, N'Open Pit/Poço aberto', N'Antes da implementação deste Kaizen, não existia um padrão visual para identificar o estágio real das Ordens de Manutenção (OMs). Todas as OMs apresentavam informações semelhantes no sistema, exigindo análises individuais para entender se a atividade havia sido apenas executada, apropriada, se possuía evidências anexadas ou se já estava encerrada.', N'Otimização de tempo!', N'10024', N'01 - Imagens/01 - Antes/11683.jpeg', N'Antes da implementação deste Kaizen, não existia um padrão visual para identificar o estágio real das Ordens de Manutenção (OMs). Todas as OMs apresentavam informações semelhantes no sistema, exigindo análises individuais para entender se a atividade havia sido apenas executada, apropriada, se possuía evidências anexadas ou se já estava encerrada.
INSERT INTO #PVC VALUES (11684, N'81052333', N'516481', N'JANELA DE ACESSO AO SENSOR DO CHUTE E PLATAFORMA', 1, N'Crusher/Britadeira', N'anteriormente não havia acesso adequado para manutenção do sensor, necessitava de montagem de andaime para ter acesso. Necessitava de andaime e escada para realizar a manutenção, colocando os colaboradores a linha de fogo, e aumento de custo na utilização de andaimes.', N'Ter acesso para manutenção adequada do sensor do chute', N'10362', N'01 - Imagens/01 - Antes/11684.jpeg', N'não possuía acesso adequado para execução das atividades de manutenção do sensor.er necessária a montagem de andaime e a utilização de escada, aumentando significativamente o tempo de execução da tarefa, e exposição dos colaboradores aos riscos .', N'01 - Imagens/02 - Depois/11684.jpeg', N'Foi confeccionada uma janela de acesso com plataforma fixa, proporcionando acesso seguro e permanente ao sensor para realização de inspeções, manutenções preventivas e corretivas.', NULL, N'sim,
INSERT INTO #PVC VALUES (11685, N'81027232', N'81027232', N'Melhoria no acesso a ombreira direita Barragem do IGB', 2, N'Others/Outros', N'O acesso à ombreira direita da Barragem do IGB apresentava situação de risco de queda em mesmo nível e em nível diferente, uma vez que, para acessar a ombreira, era necessário transitar sobre blocos soltos de rocha, o que comprometia a segurança dos deslocamentos e aumentava a probabilidade de acidentes.', N'Segurança dos colaboradores', N'10141', N'01 - Imagens/01 - Antes/11685.jpeg', N'O acesso à ombreira direita da Barragem do IGB apresentava situação de risco de queda em mesmo nível e em nível diferente, uma vez que, para acessar a ombreira, era necessário transitar sobre blocos soltos de rocha, o que comprometia a segurança dos deslocamentos e aumentava a probabilidade de acidentes.', N'01 - Imagens/02 - Depois/11685.jpeg', N'
INSERT INTO #PVC VALUES (11686, N'200746', N'81023781', N'Addition of PT test', 1, N'Others/Outros', N'The lab had no established or documented means to demonstrate competency in performing environmental analyses using ICP‑OES technology.', N'Be able to demonstrate competency in using ICP-OES technology to analyze environmental samples', N'#N/A', N'01 - Imagens/01 - Antes/11686.jpeg', N'The laboratory performs daily environmental analyses using ICP‑OES and maintains routine quality control measures to ensure the accuracy of data released to customers. However, the quality assurance program lacks a formal mechanism for demonstrating competency with this technology through participation in third‑party proficiency testing.  ', N'01 - Imagens/02 - Depois/11686.jpeg', N'The laboratory strengthened its quality assurance program by adding a metals‑in‑solution proficiency test to its existing PT schedule, providing third‑party confirmation of competency in ICP‑OES analysis.', NULL, N'The lab will be able to demonstrate competency in the next round of PT testing in Oct, 2026.', N'Continually evaluate the efficiency of the lab''s quality program', 0, NULL, N'Proporcionar maior controle e conscientização quanto ao acesso à área do equipamento.', '2026-08-11T00:00:00.000', '2026-08-12T12:14:13.000', N'200746', NULL, NULL);
INSERT INTO #PVC VALUES (11687, N'521657', N'521657', N'Sinalização de recuo de blocos.', 1, N'Others/Outros', N'Existia uma placa sinalizando a área de recuo de blocos. Entretanto, quando os tratores de pneus eram acionados via rádio para realizar a limpeza de blocos, os operadores não conseguiam identificar qual recuo específico necessitava do atendimento.', N'Sinalizar de forma orientativa.', N'10141', N'01 - Imagens/01 - Antes/11687.jpeg', N'Existia uma placa sinalizando a área de recuo de blocos. Entretanto, quando os tratores de pneus eram acionados via rádio para realizar a limpeza de blocos, os operadores não conseguiam identificar qual recuo específico necessitava do atendimento. Como a mina possui diversos recuos, os equipamentos acabavam circulando pela área em busca do local correto, gerando perda de tempo e reduzindo a eficiência da atividade.', N'01 - Imagens/02 - Depois/11687.jpeg', N'Realizada a adequação das placas de sinalização dos recuos de blocos, com identificação por letras. Com essa melhoria, os operadores dos tratores conseguem identificar corretamente o local solicitado via rádio, reduzindo o tempo de atendimento e deslocamentos desnecessários na mina.', NULL, N'Foi superada a meta inicial.', N'Um detalhe na especificação de uma placa podem agilizar e viabilizar a atuação do equipamento.', 0, NULL, N'maior confiabilidade operacional, melhor visibilidade para os colaboradores e aumento da segurança durante a execução das atividades, contribuindo para uma operação mais segura e eficiente.', '2026-08-03T00:00:00.000', '2026-08-12T13:02:25.000', N'521657', NULL, NULL);
INSERT INTO #PVC VALUES (11688, N'935171', N'527712', N'Relatório de peritagem avançado  ', 1, N'Others/Outros', N'O modelo de relatório de peritagem apresentava informações incompletas e exigia um elevado tempo de preenchimento. Além disso, era necessário anexar manualmente toda a documentação no SAP, tornando o processo mais lento, aumentando o esforço operacional e reduzindo a produtividade da equipe.', N'Reduzir o tempo de elaboração e emissão dos relatórios de peritagem em pelo menos 30%', N'10230', N'01 - Imagens/01 - Antes/11688.jpeg', N'O modelo de relatório de peritagem apresentava informações incompletas e exigia um elevado tempo de preenchimento. Além disso, era necessário anexar manualmente toda a documentação no SAP, tornando o processo mais lento, aumentando o esforço operacional e reduzindo a produtividade da equipe.', N'01 - Imagens/02 - Depois/11688.jpeg', N'Relatório de peritagem unificado com lista de peças e registro fotográfico, incluindo listas suspensas padronizadas. Resultado: mais agilidade, padronização, confiabilidade e menos erros', NULL, N'O problema identificado era o tempo excessivo na elaboração dos relatórios de peritagem, devido às informações dispersas, preenchimento manual e anexação de documentos. Com a implementação do novo modelo, que unifica a lista de peças recomendadas e o relatório fotográfico em um único documento, além do uso de listas suspensas padronizadas, a meta de simplificar e padronizar o processo foi alcançada, proporcionando mais agilidade, confiabilidade e redução de erros.', N'A padronização dos formulários reduz o tempo de preenchimento e minimiza erros de registro.', 0, NULL, N'aumento da segurança operacional e redução do risco químico, maior durabilidade e vida útil das tubulações.', '2026-08-11T00:00:00.000', '2026-08-12T13:37:13.000', N'935171', NULL, NULL);
INSERT INTO #PVC VALUES (11689, N'521657', N'549070', N'Análise de estabilidade das praças de radares.', 1, N'Others/Outros', N'A área para instalação de radares era realizada apenas avaliação visual.', N'Garantir a instalação de radares em área segura.', N'10141', N'01 - Imagens/01 - Antes/11689.jpeg', N'A inspeção das praças para instalação dos radares era realizada de forma visual.', N'01 - Imagens/02 - Depois/11689.jpeg', N'A adoção da análise prévia de estabilidade geotécnica proporciona maior segurança e confiabilidade na execução das atividades assegurando que as áreas de instalação sejam avaliadas antecipadamente quanto aos riscos de instabilidade das bermas, deslizamentos ou outras condições que possam comprometer a integridade das pessoas, equipamento e operações. 
INSERT INTO #PVC VALUES (11690, N'521657', N'521657', N'Mapa com pontos da rodada de mina', 1, N'Others/Outros', N'Existia a rodada de mina, contudo não era formalizado os pontos de passagem.', N'Evidenciar pontuações geotécnicas ao longo da rodada de mina. ', N'10141', N'01 - Imagens/01 - Antes/11690.jpeg', N'Não existia formalização dos pontos discutido durante a rodada de mina. ', N'01 - Imagens/02 - Depois/11690.jpeg', N'Elaborado linhas no mapa, com pontos de interesse Geotécnico discutidos ao longo da rodada de mina.', NULL, N'Meta alcançada.', N'Utilizando software da Deswik, é possível desenhar linhas com pontos abordados em áreas de interesse Geotécnico.', 0, NULL, N'Reduzir vazamento nas conexões e prolongar a vida útil do engate sustentando a tubulação', '2026-08-03T00:00:00.000', '2026-08-12T14:31:04.000', N'521657', NULL, NULL);
INSERT INTO #PVC VALUES (11691, N'81040247', N'81040247', N'BI de Relatório de andaimes fixos ', 1, N'Projects/Projetos', N'Situação Anterior: Não existia um controle estruturado dos andaimes fixos montados no Complexo Salobo, dificultando a visibilidade dos custos associados e o acompanhamento da utilização desses ativos.', N'Redução de Custo', N'10178', N'01 - Imagens/01 - Antes/11691.jpeg', N'Situação Anterior: Não existia um controle estruturado dos andaimes fixos montados no Complexo Salobo, dificultando a visibilidade dos custos associados e o acompanhamento da utilização desses ativos.', N'01 - Imagens/02 - Depois/11691.jpeg', N'Maior controle e transparência dos custos relacionados aos andaimes fixos, melhoria na gestão dos recursos, suporte à tomada de decisão e aumento da eficiência no acompanhamento das estruturas montadas em campo.', N'https://app.powerbi.com/groups/169ed629-1a2b-46f5-b181-746dfa4a3f95/reports/74975a87-2837-4f41-afc5-008ab320bf3b/5df4b3bd9235650052b5?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'O problema foi resolvido e dará margem para acompanhar o custo dia a dia dos andaimes fixos para reduzir o valor agregado', N'Desperdício de material em campo gerando custo financeiro para companhia ', 500000, 1, N'agora com a padronização não será necessário tanto esforço físico.', '2026-08-01T00:00:00.000', '2026-08-12T14:47:33.000', N'81040247', NULL, NULL);
INSERT INTO #PVC VALUES (11692, N'521657', N'521657', N'Pílula do conhecimento', NULL, N'Others/Outros', N'Não existia a pílula do conhecimento, como informativo do uso obrigatório de câmera de ré nas atividade de mobilizações dos radares. ', N'Além de comunicar, imprimir a pílula para colar no veículo.', N'10141', N'01 - Imagens/01 - Antes/11692.jpeg', N'Não existia informativo para colocar no veículo. ', N'01 - Imagens/02 - Depois/11692.jpeg', N'Elaborado Card, para colar na parte interna das camionetes fortalecendo a informação da obrigatoriedade do uso de câmera de ré, durante as atividade de mobilizações de radares e placas fotovoltaicas. ', NULL, N'Meta alcançada. ', N'A importância de reiterar a informação.', 0, NULL, N'Manutenção dos amostradores realizada em rota de rotina, com bloqueio individual, maior segurança e agilidade, mantendo a continuidade operacional da linha e reduzindo a dependência de paradas programadas.', '2026-08-11T00:00:00.000', '2026-08-12T15:01:11.000', N'521657', NULL, NULL);
INSERT INTO #PVC VALUES (11693, N'549252', N'81013267', N'Melhoria na Correção de Viagens', 1, N'Others/Outros', N'Atualmente, a identificação de viagens com inconsistências entre origem e subárea é realizada por meio das telas de carregamento e basculamento do OP PRO. Nessas consultas são exibidas simultaneamente viagens corretas e incorretas, dificultando a localização rápida das divergências e aumentando o tempo necessário para análise e correção dos registros.
INSERT INTO #PVC VALUES (11694, N'520046', N'520046', N'Corrimão de proteção contra queda na escada 02 do lavador', 1, N'Others/Outros', N'Problema: Ausência de corrimão adequado na Escada 02 do Lavador, gerando risco de queda.
INSERT INTO #PVC VALUES (11695, N'81062073', N'81062073', N'Monitoramento Online de Descargas Parciais Cabos Isolados 12/20 kV', 1, N'Others/Outros', N'Não havia aplicação de monitoramento online de descargas parciais nos cabos isolados 12/20 kV, o que dificultava a identificação precoce de degradações no sistema de isolamento. A ausência dessa tecnologia aumentava o risco de falhas não planejadas, indisponibilidade dos ativos, perdas de produção e intervenções corretivas emergenciais. A necessidade foi identificada durante as atividades de monitoramento e confiabilidade dos ativos elétricos, evidenciando oportunidade de melhorar a capacidade de diagnóstico e atuação preventiva.', N'Implementar o monitoramento online de descargas parciais em cabos 12/20 kV para identificar falhas potenciais de forma antecipada, reduzir riscos de interrupções não planejadas e aumentar a confiabilidade e disponibilidade dos ativos elétricos.', N'10293', N'01 - Imagens/01 - Antes/11695.jpeg', N'Antes da implementação da solução, não havia aplicação de monitoramento online de descargas parciais nos cabos isolados 12/20 kV. A avaliação da condição dos circuitos dependia de inspeções pontuais e da ocorrência de sintomas mais evidentes de degradação, reduzindo a capacidade de identificar falhas potenciais de forma antecipada.
INSERT INTO #PVC VALUES (11696, N'81030465', N'81030465', N'Suporte para pistola ', 1, N'Others/Outros', N'Antes a pistola de ar comprimido era apoiada de forma inadequada na estrutura da máquina, sem local definido para guarda.
INSERT INTO #PVC VALUES (11697, N'81006706', N'81002603', N'Melhoria na esteira do Carro Panela linha 02', 1, N'No Replication/Sem replicação', N'Equipamento estava travando com frequência devido   a esteira estar desalinhada fazendo com que a mesma saia do trilho ocasionando tombamento na estrutura. ', N'Garantir que a esteira translade sempre alinhada ', N'10280', N'01 - Imagens/01 - Antes/11697.jpeg', N'Equipamento estava travando com frequência devido   a esteira estar desalinhada fazendo com que a mesma saia do trilho ocasionando tombamento na estrutura. Sendo necessário a parada do equipamento para retornar a esteira para o trilho e assim liberar o equipamento para operação.', N'01 - Imagens/02 - Depois/11697.jpeg', N'Instalado rolos guias auto alinhantes na extensão do trilho , garantindo o alinhamento da esteira , reduzindo a parada do equipamento  para retornar a esteira para o trilho e assim liberar o equipamento para operação.', NULL, N'Sim . Houve redução da parada do equipamento', N'Garantir o funcionamento do equipamento', 0, NULL, N'Mitigação de danos prematuros aos tecidos e às placas.', '2026-02-15T00:00:00.000', '2026-08-12T17:50:26.000', N'81006706', NULL, NULL);
INSERT INTO #PVC VALUES (11698, N'81043245', N'81043245', N'identificação (TAG) das chaves de emergência dos filtros', 1, N'Others/Outros', N'Anteriormente, algumas chaves não possuíam identificação e outras apresentavam tags desgastadas, dificultando sua visualização.', N'Facilitar a identificação e localização das chaves de emergência.', N'10054', N'01 - Imagens/01 - Antes/11698.jpeg', N'Anteriormente, algumas chaves não possuíam identificação e outras apresentavam TAGS desgastadas, dificultando sua visualização.', N'01 - Imagens/02 - Depois/11698.jpeg', N'Foram instaladas novas tags em tamanho ampliado, proporcionando maior destaque e facilitando a localização rápida das chaves de emergência durante as atividades operacionais e em situações de necessidade.', NULL, N'SIM! Fortalecer a identificação das chaves de emergência dos filtros 2551-FL-01 e 2551-FL-02.', N'Agilidade no processo e mais segurança na hora da identificação da chave de emergência correta', 0, NULL, N'fabricar suporte para enrolar de forma rápida e organizada a mangueira.', '2026-08-12T00:00:00.000', '2026-08-13T03:02:19.000', N'81043245', NULL, NULL);
INSERT INTO #PVC VALUES (11699, N'81043245', N'81043245', N'Identificação e restrição de acesso ao filtro 1', 1, N'Others/Outros', N'Os portões de acesso ao filtro não possuíam identificação quanto à restrição de acesso à área.', N'Reforçar a comunicação de segurança, evitar acessos não autorizados.', N'10054', N'01 - Imagens/01 - Antes/11699.jpeg', N'Os portões de acesso ao filtro não possuíam identificação quanto à restrição de acesso à área.', N'01 - Imagens/02 - Depois/11699.jpeg', N'Confeccionadas e instaladas placas de sinalização nos acessos, contendo orientação sobre acesso restrito e necessidade de autorização do operador responsável.', NULL, N'SIM! Orientando os colegas dos riscos ao  acessar a parte interna do equipamento sem autorização. ', N'conscientização quanto ao acesso no equipamento.', 0, NULL, N'Instalar uma Baia para segregação dos resíduos contaminados da equipe de revezamento Para posterior descarte do CMD.', '2026-08-12T00:00:00.000', '2026-08-13T03:21:22.000', N'81043245', NULL, NULL);
INSERT INTO #PVC VALUES (11700, N'550443', N'550443', N'BYPASS EFICIÊNTE', 2, N'Others/Outros', N'A área da dosagem de bolas e da alimentação do bypass apresentava deficiência de iluminação devido a um curto-circuito nos cabos elétrico.', N'ILUMINAÇÃO SEGURA', N'10245', N'01 - Imagens/01 - Antes/11700.jpeg', N'A área da dosagem de bolas e da alimentação do bypass apresentava deficiência de iluminação devido a um curto-circuito nos cabos elétrico.', N'01 - Imagens/02 - Depois/11700.jpeg', N'Foi realizado o lançamento de um novo cabo elétrico e a readequação da alimentação dos refletores da área de dosagem de bolas. Além disso, foram instalados quatro novos refletores para melhorar a iluminação da região da moega e área de circulação da pá carregadeira do circuito de bypass.
INSERT INTO #PVC VALUES (11701, N'81058966', N'81038717', N' BQ-2022-209 – Melhoria nas tubulações de recalque e sucção.', 1, N'Others/Outros', N'As tubulações de sucção e recalque eram feitas em PEAD rígido, e suas curvas e soldas, com o passar do tempo, ressecavam devido à ação do produto químico transportado pelo sistema, ocasionando frequentes vazamentos.
INSERT INTO #PVC VALUES (11702, N'81049566', N'81017006', N'Engate rapido ', 1, N'Refining/Refino', N'Mangote da linha do PSI conectado com diversas abraçadeiras.
INSERT INTO #PVC VALUES (11703, N'81049566', N'81012442', N'Suporte tubulação', 1, N'Smelting/Fundição', N'Ausência de suporte e sustentação para os mangotes do PSI no que forçavam as conexões e recorrente gerava vazamentos.', N'Fazer o suporte para sustentar os mangotes', N'10362', N'01 - Imagens/01 - Antes/11703.jpeg', N'Agência de suporte para os magotes do PSI que recorrente gerava Vazamentos ou dano nas conexões.', N'01 - Imagens/02 - Depois/11703.jpeg', N'fabricado e instalar o suporte para sustentação da tubulação e dos mangotes do PSI mantendo maior estabilidade nas conexões.', NULL, N'Foi fabricado um suporte instalado dando maior sustentação às conexões e reduzindo exposição a quebra o vazamento.', N'Redução de vazamentos e dano as conexões', 0, NULL, N'Aumento da agilidade na execução das atividades por meio da visualização facilitada dos dados e resultados.', '2026-08-04T00:00:00.000', '2026-08-13T09:46:46.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11704, N'81058966', N'81054451', N'Adequação de válvula.CF-2017-28', NULL, N'Others/Outros', N'Durante uma manutenção na tubulação de ar notamos uma válvula que dependia de esforço físico e chave para abrir. CF-2017-28', N'Manter nossa área de trabalho padronizada.', N'10031', N'01 - Imagens/01 - Antes/11704.jpeg', N'A válvula antiga dependia de esforço físico e chave para abrir.
INSERT INTO #PVC VALUES (11705, N'81058966', N'81058570', N'Implementação de Válvula de Bloqueio Dedicada para Manutenção Ágil em Amostradores de Processo.AM-2017-49', 1, N'Others/Outros', N'A linha de tubulação não possuía um dispositivo de isolamento individual para o sistema de amostragem.
INSERT INTO #PVC VALUES (11706, N'81049566', N'81017006', N'Drenagem do PSI', 1, N'Crusher/Britadeira', N'Ausência de ponto para desobstrução e drenagem na linha do PSI onde era necessário remover as mangueiras de mangotes Toda vez que ocorria obstrução da linha.', N'Vai ficar no ponto para drenagem dos mangotes', N'10362', N'01 - Imagens/01 - Antes/11706.jpeg', N'Ausência de ponto de drenagem na linha do PSI.', N'01 - Imagens/02 - Depois/11706.jpeg', N'Instalado ponto para injeção de água e desobstrução ou drenagem da linha do PSI Não sendo mais necessária a remoção de mangotes.', NULL, N'Foi possível realizar a desobstrução dos magotes sem a necessidade de manobra operacional apenas injetando água', N'Eliminando a necessidade de DESACOPLAR os magotes para subbstruir a linha', 0, NULL, N'✅Disponibilização de informação sobre Homologações de Salobo descentralizada de pessoas e sem a necessidade do perfil de homologação da plataforma CH-Master;
INSERT INTO #PVC VALUES (11707, N'81013223', N'81054396', N'Controle e Planejamento de Atividades de Infraestrutura.', 1, N'No Replication/Sem replicação', N'A gestão das atividades de infraestrutura era realizada de forma descentralizada, com informações distribuídas em diferentes controles e registros, dificultando a visualização consolidada das demandas, o acompanhamento dos prazos e a priorização das atividades. Essa situação gerava riscos de falhas na comunicação entre as equipes, retrabalho, conflitos de programação, atrasos na execução dos serviços e baixa confiabilidade das informações para a tomada de decisão.
INSERT INTO #PVC VALUES (11708, N'81049566', N'81017006', N'Alçapão limpeza esgoto ', 1, N'Others/Outros', N'Ausência de acesso para desobstrução Da linha de esgoto das salas da moagem.', N'Instalar um acesso A área de obstrução e retirada da caixa de esgoto.', N'10362', N'01 - Imagens/01 - Antes/11708.jpeg', N'Caixa de esgoto ficava abaixo do piso chapeado, para acesso a caixa era necessário corte de chapas metálicas expondo pessoas ao risco de trabalho a quente.', N'01 - Imagens/02 - Depois/11708.jpeg', N'Fabricado abertura na chapa metálica, como janela de visita para acesso a caixa de esgoto , eliminando a necessidade de corte e solda toda via que era necessário desobstrução do esgoto. ', NULL, N'Fala foi instalado uma janela de visita Na chapa de acesso à caixa de esgoto Agora é permitido o acesso sem a necessidade de trabalho à quente eliminando o risco de exposição de pessoas.', N'eliminar risco de trabalho a quente', 0, NULL, N'Melhoria na gestão da cobertura de brigadistas locais, com maior agilidade na identificação dos profissionais por área e ponto de emergência, facilitando o acompanhamento da prontidão para atendimento às emergências.', '2026-08-05T00:00:00.000', '2026-08-13T10:55:48.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11709, N'81049566', N'81012442', N'Suporte para Lixeira na area', 1, N'Concentration/Concentração', N'Ausência de lixeiras e suporte para próximo a área de abastecimento do pipa , estava acumulando lixeiras ', N'padronizar descarte de resíduos ', N'10362', N'01 - Imagens/01 - Antes/11709.jpeg', N'Ausência de lixeiras e suporte no local, colaboradores estavam descartando lixo no chão. ', N'01 - Imagens/02 - Depois/11709.jpeg', N'Fabricado suporte para instalação de lixeiras padronizadas na aréa em conjunto com a Giltrans.', NULL, N'Instalado suporte para três lixeiras, e realizar a segregação dos resíduos no local. ', N'Padronizado suporte para instalação de lixeiras', 0, NULL, N'Conseguimos tira as pessoas da linha de fogo e exposição ao risco e aumentamos a detecção de falha.', '2026-08-07T00:00:00.000', '2026-08-13T11:06:11.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11710, N'81045862', N'81045862', N'Melhoria na lavagem dos tecidos dos filtros prensa', 1, N'Others/Outros', N'Lavagem inadequada dos tecidos/placas por baixa pressão.', N'Evitar danos nos tecidos e placas por baixa pressão de lavagem', N'10081', N'01 - Imagens/01 - Antes/11710.jpeg', N'O monitoramento da pressão de lavagem dos filtros prensa era realizado exclusivamente por meio de instrumentação local (manômetro), demandando inspeção e leitura direta pelo operador de campo. Em determinadas situações, falhas nesse acompanhamento operacional resultavam na execução inadequada do ciclo de lavagem dos tecidos filtrantes, comprometendo sua limpeza e desempenho. Como consequência, observava-se o desgaste prematuro dos tecidos e danos às placas filtrantes, reduzindo sua vida útil e aumentando a necessidade de intervenções de manutenção.', N'01 - Imagens/02 - Depois/11710.jpeg', N'Com a implantação do novo transmissor de pressão, as condições de despressurização excessiva da água de lavagem passarão a ser monitoradas continuamente. Em caso de pressão abaixo do limite operacional estabelecido, será gerado um alarme na sala de controle, disponibilizando a informação em tempo real para a sala de controle. A partir desse alerta, o operador da sala poderá acionar prontamente a equipe de campo para realizar os ajustes necessários no sistema, garantindo a correta pressão de lavagem dos filtros prensa. Essa melhoria reduz significativamente o risco de lavagem inadequada dos tecidos filtrantes, mitigando danos prematuros aos tecidos e às placas filtrantes, além de contribuir para o aumento da confiabilidade operacional do processo/operação.', NULL, N'Sim', N'NA', 0, NULL, N'We achieved improved personnel monitoring and accountability within the designated area.', '2026-08-05T00:00:00.000', '2026-08-13T11:25:06.000', N'81045862', NULL, NULL);
INSERT INTO #PVC VALUES (11711, N'81049566', N'81017006', N'Enrolador de mangueira', NULL, N'Others/Outros', N'Suporte para enrolar mangueira de forma manual .', N'melhorar organização da mangueira da caldeiraria', N'10362', N'01 - Imagens/01 - Antes/11711.jpeg', N'Suporte de enrolar mangueira de forma manual.', N'01 - Imagens/02 - Depois/11711.jpeg', N'Fabricado enrolador de mangueira de forma segura e eficaz.', NULL, N'fabricado suporte para mangueira de forma enrola rapido.', N'area mais organizada', 0, NULL, N'Redução de tempo e maior confiabilidade no levantamento do indicador de DF das gateways.', '2026-08-04T00:00:00.000', '2026-08-13T11:30:07.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11712, N'81049566', N'81017006', N'Baia de resíduos ', 1, N'Crusher/Britadeira', N'ausência de uma baixa para a segregação dos resíduos químicos e perigosos na caldeiraria do revezamento.', N'fabricar baia para segregar residuos', N'10362', N'01 - Imagens/01 - Antes/11712.jpeg', N'A ausência de uma Baia para a segregação descarte de resíduos contaminados na caldeiraria do revezamento Os resíduos eram condicionados de forma irregular gerando acúmulo no local.', N'01 - Imagens/02 - Depois/11712.jpeg', N'Fabricado instalado uma Baia para condicionamento de 2 tambores para descarte e segregação de resíduos contaminados no local mantendo os resíduos seguros protegidos em uma área específica para o descarte.', NULL, N'Foi fabricada instalado uma baia para acondicionamento de 2 tambores Para descarte dos resíduos contaminados segregando dos demais.', N'Resíduos perigosos separados', 0, NULL, N'A automação reduziu o tempo de execução de 8 para 3 minutos e a quantidade de interações manuais de 8 para 2 cliques por execução, representando ganhos de 62,5% no tempo e 75% nos cliques necessários para a atividade. Considerando três execuções semanais, a melhoria proporciona uma economia de aproximadamente 65 minutos e 78 cliques por mês, além de reduzir a exposição a erros operacionais, aumentar a padronização e garantir maior confiabilidade na obtenção dos dados da carteira de planos.', '2026-08-05T00:00:00.000', '2026-08-13T12:00:27.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11713, N'81039677', N'81039677', N'Isolamento de Voz no Microsoft Teams', 1, N'Others/Outros', N'Durante reuniões em salas com várias pessoas, era comum ocorrer interferência no áudio devido a conversas paralelas e ruídos próximos ao microfone, dificultando a comunicação entre os participantes.
INSERT INTO #PVC VALUES (11714, N'81049566', N'81017006', N'Ajuste de embreagem Bolas', 2, N'Crusher/Britadeira', N'Válvula para ajuste de embreagem de pressão da embreagem do moinho de bolas  Fica localizado Em uma posição Ergonomicamente desfavorável E durante toda a partida do moinho é necessário a calibração dessa embreagem Colocando a pessoa em péssimas Condições ergonômicas .', N'Deixar a válvula em uma condição ergonômica favorável para o ajuste', N'10362', N'01 - Imagens/01 - Antes/11714.jpeg', N'Durante o ajuste da embreagem o colaborador permanecia alguns minutos agachado Para ajustar embreagem.', N'01 - Imagens/02 - Depois/11714.jpeg', N'Realizado adequação e reposicionamento da válvula de ajuste da embreagem onde permite o colaborador realizar o ajuste Em pé em uma condição ergonômica favorável.', NULL, N'Fui substituído a posicionamento da válvula de ajuste onde agora permite a regulagem da embreagem em pé com uma boa condição ergonômica reduzindo a exposição de pessoas durante o momento de regulagem.', N'melhor condição ergonomica ', 0, NULL, N'Mitigação de risco e colisão entre equipamento liberação de acesso bloqueado e melhoria na cultura de segurança e 5s dos operadores no pátio.', '2026-08-06T00:00:00.000', '2026-08-13T13:08:42.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11715, N'81049566', N'81017006', N'Proteção tubulação dreno', 2, N'Others/Outros', N'No piso no moinho de bolas 2 Tem um tubo  de 6'''' para dreno de água do piso Onde havia risco de torção de pés devido à ausência de uma tampa.', N'Fabricar uma tampa para eliminar o risco de torção ', N'10362', N'01 - Imagens/01 - Antes/11715.jpeg', N'tubulação de dreno do piso da moagem Com risco de torção de pés devido à ausência de tampa.', N'01 - Imagens/02 - Depois/11715.jpeg', N'Obrigado tampa para proteção da tubulação eliminando o risco de torção.', NULL, N'Foi realizado uma tampa eliminando o risco de torção dos pés.', N'População com tampa protegida.', 0, NULL, N'Desenvolvimento de Pessoas:
INSERT INTO #PVC VALUES (11716, N'81027232', N'81027232', N'Planilha de acompanhamento dos instrumentos manuais', 3, N'Others/Outros', N'A ausência de ferramentas visuais para monitoramento dos dados dificulta o acompanhamento dos indicadores. Apesar de os dados estarem registrados no sistema Geotec, não há gráficos ou dashboards que possibilitem visualizar sua evolução, identificar desvios e apoiar a tomada de decisão.', N'Acompanhar evolução dos instrumentos ', N'10141', N'01 - Imagens/01 - Antes/11716.jpeg', N'O sistema não mostra o gráfico com a evolução dos dados.', N'01 - Imagens/02 - Depois/11716.jpeg', N'Foi criada uma planilha individual para cada instrumento, permitindo acompanhar a evolução dos dados ao longo do tempo e identificar se os valores atingiram ou não os níveis de alerta estabelecidos.', NULL, N'Sim. A planilha possibilita uma visualização gráfica dos dados, permitindo acompanhar a evolução dos instrumentos com mais agilidade e identificar rapidamente quando algum deles atinge níveis de alerta.', N'A planilha possibilita uma visualização gráfica dos dados, permitindo acompanhar a evolução dos instrumentos com mais agilidade e identificar rapidamente quando algum deles atinge níveis de alerta.', 99, 1, N'Disponibilizar monitoramento contínuo e remoto das escavadeiras 7495, eliminando a necessidade de coleta manual de dados, aumentando a confiabilidade das informações de condição dos ativos e possibilitando a identificação antecipada de falhas em componentes críticos.', '2026-08-03T00:00:00.000', '2026-08-13T13:52:07.000', N'81027232', NULL, NULL);
INSERT INTO #PVC VALUES (11717, N'514353', N'878868', N'Melhoria na Organização do Malão da Frente de Serviço', 3, N'Others/Outros', N'O malão utilizado pela frente de serviço apresentava condições inadequadas de organização, com ferramentas', N'Melhoria da organização e do 5S', N'10017', N'01 - Imagens/01 - Antes/11717.jpeg', N'O malão apresentava ferramentas, materiais e EPIs desorganizados e sem segregação, dificultando a localização dos itens e comprometendo a organização e as condições de armazenamento.', N'01 - Imagens/02 - Depois/11717.jpeg', N'Foi confeccionado um novo malão metálico com prateleiras internas, permitindo melhor organização e segregação dos materiais, aproveitamento do espaço e facilidade de acesso aos itens.', NULL, N'A meta de melhorar a organização e o armazenamento dos materiais foi atingida, com a substituição do malão antigo por uma estrutura metálica com prateleiras, proporcionando melhor segregação, acesso e aproveitamento do espaço.', N'A organização adequada dos materiais contribui para a segurança, conservação dos itens e agilidade na execução das atividades. Soluções simples podem melhorar significativamente o ambiente de trabalho e o 5S.', 0, NULL, N'Conseguimos tira as pessoas da linha de 
INSERT INTO #PVC VALUES (11718, N'514353', N'878868', N'Abridor Manual para Garrafão de Água', 1, N'Others/Outros', N'Utilização de faca para abertura de garrafões de água de 20 litros, expondo os colaboradores ao risco de cortes e lesões durante a atividade.', N'Dispositivo Seguro para Abertura de Garrafão', N'10017', N'01 - Imagens/01 - Antes/11718.jpeg', N'Os colaboradores utilizavam faca para abrir garrafões de água de 20 litros, expondo as mãos ao risco de corte e lesões durante a realização da atividade.', N'01 - Imagens/02 - Depois/11718.jpeg', N'Foi confeccionado um abridor manual para os garrafões de 20 litros, eliminando o uso de faca e proporcionando maior segurança, praticidade e facilidade na abertura.', NULL, N'A meta de eliminar o uso de faca na abertura dos garrafões foi atingida com a implantação do abridor manual, reduzindo a exposição dos colaboradores ao risco de corte.', N'Melhoria na Abertura de Garrafões de Água', 0, NULL, N'Difficult to determine an exact cost savings but this will save a lot of time for the planners and schedulers since they no longer have to try to align the two PMs or determine extra shut down windows.', '2026-08-12T00:00:00.000', '2026-08-13T14:18:09.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (11719, N'81059323', N'81059323', N'Power BI de dados de registros de inconformidade de materiais e serviços e processos de homologação (SAT e PT) ', 1, N'Others/Outros', N'Inexistência de base com consolidação de dados de tratativa de inconformidades;
INSERT INTO #PVC VALUES (11720, N'81057902', N'81057902', N'PLC audit/clean up', 3, N'Refining/Refino', N'PLC cabinet in product packaging in rough condition ', N'repair and clean product packaging PLC cab', N'0', N'01 - Imagens/01 - Antes/11720.jpeg', N'PLC cabinet in rough condition requiring a cleaning and repair ', N'01 - Imagens/02 - Depois/11720.jpeg', N'cleaned up PLC and reinstalled panduit covers ', NULL, N'problem resolved by cleaning and repair ', N'plc Audit needed ', 0, NULL, N'local organizado.', '2026-08-12T00:00:00.000', '2026-08-13T15:12:22.000', N'81057902', NULL, NULL);
INSERT INTO #PVC VALUES (11721, N'81047161', N'81047161', N'Mapa Pontos de Emergência com Brigadistas Locais', 2, N'Others/Outros', N'Dificuldade em filtrar, acompanhar o processo de perto referente aos pontos de Emergência, os brigadistas locais conforme IT 08, classificação das áreas, cobertura por capacidade de brigadistas locais conforme especificação do CBMPA.', N'Otimizar o Processo', N'10130', N'01 - Imagens/01 - Antes/11721.jpeg', N'O acompanhamento dos brigadistas locais, pontos de emergência e capacidade de cobertura das áreas era realizado por meio de planilhas, exigindo consultas e filtros manuais para identificar os brigadistas vinculados a cada área e verificar a cobertura necessária conforme os requisitos aplicáveis. Esse processo dificultava a visualização integrada das informações, a atualização dos dados e a tomada de decisão de forma ágil.', N'01 - Imagens/02 - Depois/11721.jpeg', N'Foi desenvolvido um mapa digital dos brigadistas locais, permitindo a visualização e filtragem das informações por área, ponto de emergência e capacidade de cobertura. A solução possibilita consulta rápida e integrada dos dados, facilitando o números dos brigadistas atuais vencidos e a vencer, acompanhamento da cobertura por números de brigadistas existentes conforme CBMPA.', NULL, N'O problema foi solucionado com a implantação do mapa digital dos brigadistas, permitindo visualizar, filtrar e acompanhar os brigadistas por área e ponto de emergência, facilitando a gestão da cobertura e da prontidão para atendimento às emergências.', N'A centralização das informações em um mapa digital facilita a visualização, filtragem e acompanhamento da distribuição dos brigadistas, permitindo identificar de forma mais rápida a cobertura das áreas e apoiar a tomada de decisão em situações de emergência.', 0, NULL, N'organização ', '2026-08-10T00:00:00.000', '2026-08-13T15:42:17.000', N'81047161', NULL, NULL);
INSERT INTO #PVC VALUES (11722, N'524616', N'524616', N'Monitoramento de vibração no PTO PZ02 online.', 2, N'Others/Outros', N'Evitar que pessoas sejam expostas ao risco na realização das coletas de vibração fisicamente no componente.', N'Retira as pessoas da exposição do risco ao realizar  atividade.', N'10024', N'01 - Imagens/01 - Antes/11722.jpeg', N'Coleta de vibração realizada de forma manual utilizando sensor portátil diretamente nos pontos de medição do componente. O técnico precisava acessar fisicamente o equipamento em operação, posicionar o sensor em cada ponto de coleta e aguardar a aquisição dos dados individualmente. O processo demandava exposição em área operacional, maior tempo de inspeção e deslocamento entre os pontos monitorados', N'01 - Imagens/02 - Depois/11722.jpeg', N'Foi implantado o monitoramento online por sensores fixos, permitindo o acompanhamento contínuo dos componentes em tempo real, reduzindo a necessidade de coleta manual em campo e aumentando a agilidade na tomada de ação diante de anomalias', NULL, N'Sim, conseguimos tira as pessoas da linha de fogo e exposição ao risco e aumentamos a detecção de falha.', N'Através do monitoramento online conseguimos aumentar a detecção de falha no início dela e eliminamos a exposição de pessoas em campo.', 0, NULL, N'Meta atingida: foi disponibilizado um sistema adequado de emergência para descontaminação dos olhos e do corpo, reduzindo o tempo de resposta e mitigando os riscos em eventuais ocorrências de contaminação.', '2026-08-12T00:00:00.000', '2026-08-13T16:03:17.000', N'524616', NULL, NULL);
INSERT INTO #PVC VALUES (11723, N'81048174', N'81048174', N'Key Card Access Control ', 2, N'Others/Outros', N'Mitigate the risk of uncredentialed or untracked personnel entering classified areas through controlled access and comprehensive entry logging.', N'Improve access management to designated areas by enabling controlled entry and enhanced visibility of personnel within monitored locations.', N'0', N'01 - Imagens/01 - Antes/11723.jpeg', N'Previously entry into the restricted and classified area was done through signage directing you to calling the control room to announce your entry and have the control room operator manually write the entry into there log book. ', N'01 - Imagens/02 - Depois/11723.jpeg', N'Following the installation, card readers were installed at designated entry and exit points. The system scans and verifies an individual''s credentials before granting access and unlocking the door. Once access is granted, the system automatically records entry and exit times, provides real-time visibility of current occupants within the area, and displays the name, photograph, and relevant details of each person upon entry.', NULL, N'The implementation of access control enhances the efficiency, accuracy, and accountability of entry into controlled areas.', N'Implementing advanced access-control technology reinforces our commitment to safety, improves situational awareness and emergency response capabilities, and may ultimately reduce risk and save lives. ', 0, NULL, N'Financeiro: Redução de custos com substituição e reparos de mangueiras, evitando desgastes e danos causados pelo acondicionamento inadequado.
INSERT INTO #PVC VALUES (11724, N'501925', N'501925', N'PADRONIZAÇÃO PARA INDICADOR DF GATEWAYS', 1, N'Others/Outros', N'Não havia padrão na nomenclatura das gateways, dificultando identificar quais equipamentos eram responsáveis pela cobertura dos ativos do singelo e a extratificação para levantadmento do indicador de disponibilidade física.', N'AGILIZAR IDENTIFICAÇÃO DE GATEWAYS NO SISTEMA', N'10178', N'01 - Imagens/01 - Antes/11724.jpeg', N'Não havia padrão na nomenclatura das gateways no sistema dynapredict.', N'01 - Imagens/02 - Depois/11724.jpeg', N'Criado um padrão para nomenclatura de gateways, facilitando a identificação das gateways por área  usina/britagem e circuito singelo. O objetivo é realizar o levantamento do indicador de disponibilidade física de forma rápida e confiável.', NULL, N'Sim. Agora é possível identificar de forma rápida as gateways por fase.', N'melhoria no mapeamento de gateways', 0, NULL, N'Eliminação total do retrabalho com remarcação topográfica na praça e garantia da continuidade da operação.', '2026-08-12T00:00:00.000', '2026-08-13T17:15:57.000', N'501925', NULL, NULL);
INSERT INTO #PVC VALUES (11725, N'510839', N'510839', N'Automatização do Download da Carteira de Planos da Frota de Carga na IP19', 1, N'Others/Outros', N'O processo de extração da carteira de planos da frota de carga na transação IP19 do SAP era realizado manualmente pelos planejadores, exigindo acesso à transação, seleção da variante adequada, execução do relatório e exportação dos dados para Excel. A atividade consumia tempo operacional, dependia de ações repetitivas do usuário e estava sujeita a erros de execução, reduzindo a produtividade e a padronização do processo.', N'Automatizar integralmente o processo de download da carteira de planos da frota de carga na transação IP19 do SAP, eliminando atividades manuais repetitivas, reduzindo o tempo de execução e padronizando a obtenção dos dados para análise e gestão da manutenção.', N'10234', N'01 - Imagens/01 - Antes/11725.jpeg', N'A extração da carteira de planos da frota de carga na transação IP19 era realizada manualmente no SAP, exigindo acesso à transação, seleção da variante, execução do relatório e exportação dos dados para Excel. A atividade consumia aproximadamente 8 minutos e 8 cliques por execução, além de estar sujeita a erros de parametrização, seleção incorreta de variantes e inconsistências operacionais.', N'01 - Imagens/02 - Depois/11725.jpeg', N'Foi desenvolvido um robô em VBA integrado ao SAP GUI Scripting para automatizar a extração da carteira de planos da frota de carga. A solução passou a executar automaticamente a navegação, seleção da variante, processamento do relatório e exportação dos dados para Excel, reduzindo o esforço operacional para aproximadamente 3 minutos e 2 cliques por execução, com maior padronização e confiabilidade do processo. Além da redução de 62,5% no tempo de execução, a automação eliminou 75% das interações manuais, aumentando a padronização do processo e reduzindo significativamente o risco de erros operacionais.', NULL, N'SIM. O problema foi solucionado. Foi desenvolvido e implantado um robô para automatizar o download da carteira de planos da frota de carga na transação IP19 do SAP. A solução passou a executar automaticamente as etapas de acesso à transação, seleção da variante, processamento do relatório e exportação dos dados para Excel, eliminando a execução manual da atividade, reduzindo o tempo operacional e aumentando a padronização e confiabilidade do processo.', N'A automação de rotinas repetitivas utilizando SAP GUI Scripting e VBA possibilita maior produtividade, padronização dos processos e redução de atividades operacionais sem valor agregado, permitindo que o planejador concentre esforços em análises e tomadas de decisão.', 0, NULL, N'Redução de senário de risco', '2026-08-13T00:00:00.000', '2026-08-14T09:41:21.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11726, N'81012700', N'537005', N'Local adequado para estacionar', 2, N'Others/Outros', N'Ausência de um local adequado e sinalizado para estacionar o trator de esteira da pilha pulmão, dificultando e causando perda de tempo  operacional no inicio e no fim de turno para posicionar o equipamento e em caso de manutenção operacional. ', N'Adequar e sinalizar um local exclusivo para estacionar trator de esteira da pilha pulmão', N'10257', N'01 - Imagens/01 - Antes/11726.jpeg', N'Atualmente, o trator de esteira que opera na pilha pulmão não possui um local fixo, plano e sinalizado para estacionar. Isso faz com que o equipamento seja deixado em pontos improvisados gerando desorganização na área, há perda de tempo operacional dos operadores para localizar e posicionar a maquina no inicio e no final de turno ( troca de turno), além de dificultar o acesso seguro da equipe de manutenção quando necessário.', N'01 - Imagens/02 - Depois/11726.jpeg', N'Foi realizado a adequação, nivelamento e sinalização de uma área exclusiva para o estacionamento do trator de esteira próximo a pilha pulmão. criou-se um padrão visual claro para a vaga do equipamento, eliminando tempo de busca e manobras desnecessária na troca de turno. Garantindo acesso segura para os operadores e manutenção.', NULL, N'sim o problema foi totalmente resolvido com a criação e sinalização da vaga exclusiva para o trator de esteira na pilha pulmão, eliminou-se tempo perdido com manobras e busca do equipamento na troca de turno, e para acesso a equipe de manutenção quando necessário.', N'padronização e a demarcação visual de áreas operacionais. ', 0, NULL, N'Eliminar a exposição dos operadores às partes móveis dos tornos na região do eixo da árvore traseira.', '2026-08-08T00:00:00.000', '2026-08-14T09:48:17.000', N'81012700', NULL, NULL);
INSERT INTO #PVC VALUES (11727, N'81012700', N'486535', N'Padronização e sinalicao do estacionamento da escavadeira', 2, N'Open Pit/Poço aberto', N'Ausência de vaga exclusivo, delimitada e sinalizada para o estacionamento da escavadeira hidráulica no pátio mirante, gerando risco de colisões, obstrução de acesso e manobras insegura na troca de operador/turno.
INSERT INTO #PVC VALUES (11728, N'547627', N'552245', N'Adequação da Altura do Guarda-Corpo da frota 785, para Eliminação do Risco de Queda em Altura', 2, N'Others/Outros', N'Risco de queda em altura da plataforma superior dos caminhões 785', N'Eliminação do risco de queda em altura dos caminhões 785', N'10315', N'01 - Imagens/01 - Antes/11728.jpeg', N'Durante inspeção de área, foi identificado que o guarda-corpo existente possuía altura insuficiente para garantir a proteção adequada dos colaboradores contra quedas em altura. Essa condição gerava exposição ao risco de acidente, especialmente durante atividades de manutenção, inspeção e operação realizadas próximas à borda da estrutura.
INSERT INTO #PVC VALUES (11729, N'81042856', N'81042856', N'EC03 - Instalação da gateway Dynamox em escavadeiras eletricas 7495', 1, N'Others/Outros', N'Atualmente, a coleta dos dados dos sensores Dynamox instalados nas escavadeiras elétricas 7495 depende da proximidade de dispositivos móveis ou de atividades manuais em campo, resultando em atrasos na obtenção das informações, perda de dados históricos e menor agilidade na identificação de anomalias. A ausência de transmissão automática limita o potencial da manutenção preditiva e aumenta o risco de falhas não detectadas em tempo hábil.', N'Implementar gateways Dynamox nas escavadeiras 7495 para viabilizar a coleta automática e contínua dos dados de vibração dos sensores, aumentando a confiabilidade do monitoramento preditivo, reduzindo a necessidade de coleta manual e possibilitando a identificação antecipada de falhas nos componentes críticos.', N'10015', N'01 - Imagens/01 - Antes/11729.jpeg', N'As escavadeiras elétricas 7495 possuíam sensores Dynamox instalados para monitoramento de condição, porém a coleta dos dados era realizada de forma manual, exigindo deslocamento da equipe até o equipamento para sincronização via dispositivo móvel. Essa condição ocasionava atrasos na obtenção das informações, possibilidade de perda de dados, baixa frequência de análise e maior exposição dos empregados em atividades de campo. Além disso, a indisponibilidade de dados em tempo real dificultava a identificação precoce de falhas em componentes críticos, reduzindo a efetividade da manutenção preditiva e aumentando os riscos de intervenções corretivas não planejadas.', N'01 - Imagens/02 - Depois/11729.jpeg', N'Foi realizada a instalação e configuração dos gateways Dynamox nas escavadeiras elétricas 7495, permitindo a transmissão automática dos dados coletados pelos sensores de monitoramento de condição para a plataforma online. Com a solução implementada, as informações passaram a ser disponibilizadas de forma contínua e remota, eliminando a necessidade de deslocamentos frequentes para sincronização manual dos dispositivos.
INSERT INTO #PVC VALUES (11730, N'524616', N'524616', N'Monitoramento online do sistema hidráulico da pz02.  ', 2, N'Others/Outros', N'Evitar que pessoas sejam expostas ao risco na 
INSERT INTO #PVC VALUES (11731, N'1010227', N'1010227', N'#3 & #4 SW Heat Recovery Exchangers PM Revision', 1, N'No Replication/Sem replicação', N'There were two separate maintenance plans on these heat exchangers, one for the internal inspection (completed every 2 years) and one for the instrument calibrations/function tests (completed every 3 years). This caused scheduling issues and problems with conducting the work due to shut down requirements. The two PMs were being completed independent of each other.', N'Optimize maintenance work for easier scheduling/planning and equipment availability.', N'0', N'01 - Imagens/01 - Antes/11731.jpeg', N'Two separate maintenance plans for the same system on different time intervals, heat exchanger internal inspection (2Y) and instrument calibration/function tests (3Y).', N'01 - Imagens/02 - Depois/11731.jpeg', N'Combined all maintenance work for the system into one PM. When these are due both work orders will be generated at the same time, ensuring the system is down for all work.', NULL, N'This restructuring of the PMs allows the instrumentation team to conduct their checks while the system is down for the internal heat exchanger inspection. This ensures that the checks will actually get completed, won''t get missed, and there is no extra downtime required to complete the PM outside of scheduled shut down work.', N'Ensure all scheduled PM work is properly developed, documented, and optimized.', 0, NULL, N'COM ISSO GARANTINDO QUALIDADE E EFICIÊNCIA NO ABASTECIMENTO.', '2026-08-04T00:00:00.000', '2026-08-14T14:56:10.000', N'1010227', NULL, NULL);
INSERT INTO #PVC VALUES (11732, N'524616', N'524616', N'Monitoramento online do compressor( sistema de ar) da pz02', 2, N'Others/Outros', N'Mitigar a exposição de pessoas a riscos operacionais durante a atividade de coleta de dados de vibração realizada fisicamente nos componentes.
INSERT INTO #PVC VALUES (11733, N'81013620', N'523252', N'ampliação de tomadas 440 e 220.', 3, N'Others/Outros', N'cabos de extensão energizada passando pelo acesso do pátio.', N'evitar cabos de extensão, passando pelo meio do acesso.', N'10144', N'01 - Imagens/01 - Antes/11733.jpeg', N'extensão com alimentação 440v passando pelo meio do pátio, podendo causar risco de tropeço ou choque elétrico.', N'01 - Imagens/02 - Depois/11733.jpeg', N'instalado duas tomadas 440v e 220v para evitar a passagem de extensão pelo meio do pátio de manutenção. ', NULL, N'sim', N'um local organizado gera menos acidente.', 0, NULL, N'- Fixação Mecânica: A limit switch foi fixada à estrutura metálica mediante parafusos e porcas de travamento, impedindo o afrouxamento por vibração e garantindo estabilidade ao longo do tempo.
INSERT INTO #PVC VALUES (11734, N'81013620', N'515044', N'suporte para enrolar mangueira de ar', 3, N'Others/Outros', N'Mangueira de ar comprimido ficava jogada no chão, ficando de forma que poderia causa risco de tropeço e queda de mesmo nível.', N'organização da área', N'10144', N'01 - Imagens/01 - Antes/11734.jpeg', N'mangueira de ar comprimido jogada pelo chão de forma desorganizada, podendo ocasionar tropeço e queda de mesmo nível. ', N'01 - Imagens/02 - Depois/11734.jpeg', N'Fabricado um suporte para enrolar a mangueira de ar comprimido, ficando de forma organizada e sem riscos de tropeço e queda de mesmo nível.', NULL, N'sim, local limpo e organizado.', N'um ambiente organizado gera menos acidente.', 0, NULL, N'Reduced breakdown time is more plant availability for production.', '2026-08-13T00:00:00.000', '2026-08-14T15:53:18.000', N'81013620', NULL, NULL);
INSERT INTO #PVC VALUES (11735, N'550523', N'523252', N'IMPLANTAÇÃO SISTEMA CHUVEIRO E LAVA OLHOS', 2, N'Others/Outros', N'Antes da implantação da melhoria, a área do lavador não dispunha de chuveiro de emergência e lava-olhos apropriados para atendimento imediato em uma eventual ocorrência de contaminação. Essa condição poderia aumentar o tempo de resposta para a descontaminação do colaborador, elevando o risco de agravamento da exposição e de possíveis consequências à sua integridade física.', N'Disponibilizar recursos adequados para atendimento imediato em casos de contato acidental com produtos químicos ou agentes contaminantes durante as atividades no lavador, por meio da implantação de chuveiro de emergência e lava-olhos, visando reduzir o tempo de resposta, minimizar a exposição e mitigar possíveis consequências à integridade física dos colaboradores.', N'10144', N'01 - Imagens/01 - Antes/11735.jpeg', N'Anteriormente, a área do lavador contava apenas com um lava-olhos simples, destinado ao atendimento de ocorrências envolvendo exclusivamente a região dos olhos. Não havia um sistema de emergência adequado para a descontaminação de outras partes do corpo, como chuveiro de emergência.
INSERT INTO #PVC VALUES (11736, N'550523', N'515044', N'Instalação de Suporte para Mangueira do Sistema de Ar', 3, N'Others/Outros', N'A mangueira do sistema de ar permanecia sem um suporte adequado para acondicionamento, podendo ficar solta e exposta, gerando riscos de danos, interferências na operação e desorganização da área.', N'Garantir o acondicionamento adequado da mangueira do sistema de ar, evitando que fique solta ou exposta, proporcionando maior organização, segurança e conservação do equipamento durante a operação.', N'10144', N'01 - Imagens/01 - Antes/11736.jpeg', N'A mangueira do sistema de ar permanecia sem local adequado para acondicionamento, ficando solta e sujeita a danos e interferências durante a operação.', N'01 - Imagens/02 - Depois/11736.jpeg', N'Foi implantado um suporte específico para acondicionamento da mangueira, mantendo-a organizada, protegida e posicionada de forma segura durante a operação.', NULL, N'Meta atingida: a implantação do suporte permitiu o acondicionamento adequado da mangueira, proporcionando maior organização, conservação e segurança durante a operação.', N'A melhoria reforçou a importância de manter mangueiras e acessórios devidamente acondicionados, contribuindo para a organização, conservação dos componentes e redução de riscos durante a operação.', 0, NULL, N'Disponibilizar monitoramento contínuo e remoto das escavadeiras 7495, eliminando a necessidade de coleta manual de dados, aumentando a confiabilidade das informações de condição dos ativos e possibilitando a identificação antecipada de falhas em componentes críticos.', '2026-08-12T00:00:00.000', '2026-08-14T16:36:04.000', N'550523', NULL, NULL);
INSERT INTO #PVC VALUES (11737, N'81012700', N'81026684', N'Poka-yoke na proteção das demarcação topografia', NULL, N'Open Pit/Poço aberto', N'Vulnerabilidade das demarcações dos furos da topografia na praça das perfuração devido as á dispersão de cavacos e poeira gerados pelos furos das perfuratrizes em atividade. O acumulo desse material cobre as marcações, resultando no risco de perda visual do ponto marcado pelo operador e em retrabalho de remarcação.', N'Grantir 100% de proteção e visibilidade das demarcações topografica contra o acumulo de particulados e poeira gerados pela perfuração.', N'10257', N'01 - Imagens/01 - Antes/11737.jpeg', N'Durante a perfuração, os cavacos e o pó de rocha gerados em atividade cobrem as demarcações e os guias da linha do pré-corte, com isso ocasiona a perda de visibilidade dos ponto demarcados causando desperdício de tempo operacional e necessidade de retrabalho com a remarcação dos furos.', N'01 - Imagens/02 - Depois/11737.jpeg', N'Foi desenvolvido e implementado um dispositivo cônico ("chapéu") portátil com alça e faixas refletivas, ele é colocado sobre as demarcações da topografia durante a operação, impedindo totalmente o soterramento por cavacos e poeira dos furos, garantindo alta visibilidade dos pontos marcado.
INSERT INTO #PVC VALUES (11738, N'983254', N'983254', N'Iluminação de Caminho seguro', 2, N'Others/Outros', N'Ricos de queda de nível diferente e mesmo nível, ataque de animais peçonhentos, batida contra.  ', N'Iluminação do caminho seguro ', N'10054', N'01 - Imagens/01 - Antes/11738.jpeg', N'Ausência de iluminação no caminho seguro entre o CCB da filtragem e transferência TC01/TC02 e subestação. ', N'01 - Imagens/02 - Depois/11738.jpeg', N'Instalação de iluminação no caminho seguro entre o CCB da filtragem e transferência TC01/TC02 e subestação. ', NULL, N'Meta alcançada, iluminação eficiente dando visibilidade do percurso ao usuário.', N'Segurança noturna', 0, NULL, N'Redução da probabilidade de equívocos com relação as TAG''s dos equipamentos.', '2026-08-13T00:00:00.000', '2026-08-14T21:32:27.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (11739, N'81063774', N'81049689', N'PROTEÇÃO DO EIXO DA ARVORE DO TORNO 02.', 2, N'Others/Outros', N'Os tornos da oficina de usinagem encontram-se sem proteção no eixo da árvore traseira, caracterizando uma condição insegura e aumentando a exposição dos operadores a riscos de aprisionamento e acidentes.', N'SEGURANÇA', N'10230', N'01 - Imagens/01 - Antes/11739.jpeg', N'Os tornos da oficina de usinagem encontram-se sem proteção no eixo da árvore traseira, caracterizando uma condição insegura e aumentando a exposição dos operadores a riscos de aprisionamento e acidentes.', N'01 - Imagens/02 - Depois/11739.jpeg', N'Realizada fabricação e  adequação dos tornos da usinagem com a instalação de proteção no eixo da árvore traseira, garantindo maior segurança operacional e conformidade com os requisitos de segurança.', NULL, N'Foi realizada a instalação das proteções nos equipamentos, eliminando a condição insegura identificada e reduzindo significativamente o risco de acidentes relacionados ao contato com partes móveis.', N'percepção de risco no ambiente de trabalho, ', 0, NULL, N'Redução da probabilidade de equívocos com relação as TAG''s dos equipamentos.', '2026-08-11T00:00:00.000', '2026-08-14T23:52:19.000', N'81063774', NULL, NULL);
INSERT INTO #PVC VALUES (11740, N'81062454', N'81062454', N'tool box labels', 1, N'Others/Outros', N'always have to open multiple droors to find the right tool', N'make easier to find tools', N'0', N'01 - Imagens/01 - Antes/11740.jpeg', N'hard to find tools quickly', N'01 - Imagens/02 - Depois/11740.jpeg', N'easier to find tools quickly', NULL, N'yes.  labels work', N'labels make things easier to find', 0, NULL, N'Automatizar a coleta de dados dos sensores Dynamox nas escavadeiras PC5500, eliminando a necessidade de sincronização manual, aumentando a disponibilidade das informações de monitoramento e melhorando a confiabilidade da manutenção preditiva.', '2026-08-14T00:00:00.000', '2026-08-15T09:42:27.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11741, N'81022747', N'81013220', N'suporte De manegueira', 3, N'Others/Outros', N'MANGUEIRA FICAVAM JOGADAS DE FORMA DESORGANIZADA', N'Organização', N'10144', N'01 - Imagens/01 - Antes/11741.jpeg', N'Antes era exposto no chão', N'01 - Imagens/02 - Depois/11741.jpeg', N'fabricado um suporte
INSERT INTO #PVC VALUES (11742, N'81062687', N'81062687', N'221 Sat Lab Cleanliness', 3, N'Others/Outros', N'The floor of the 221 Sat Lab regularly gets dirty/littered with debris with no tools on hand to clean up. Easy access to a broom and dustpan would remediate this.', N'To provide tools to help maintain cleanliness of the sat lab', N'0', N'01 - Imagens/01 - Antes/11742.jpeg', N'Small bits of debris/trash can accumulate on the floor that are too big to be washed down the floor grate, and it would be ergonomically unsafe to have to kneel down and pick up each little piece. There are no tools readily available to clean this up.', N'01 - Imagens/02 - Depois/11742.jpeg', N'Now there is a broom and dustpan immediately available, tucked away behind the door (without interfering with regular door function), and any mess on the floor can be easily cleaned up in an ergonomically safe manner.', NULL, N'Having easy access to clearly labelled, i.e. 5S compliant, tools will improve the cleanliness of the 221 Sat Lab without causing ergonomic discomfort to employees.', N'Having the right tools for the job where they are needed helps to both get the job done, and avoid employee discomfort.', 0, NULL, N'Automatizar a coleta de dados dos sensores Dynamox nas escavadeiras PC5500, eliminando a necessidade de sincronização manual, aumentando a disponibilidade das informações de monitoramento e melhorando a confiabilidade da manutenção preditiva.', '2026-08-15T00:00:00.000', '2026-08-16T02:44:55.000', N'81062687', NULL, NULL);
INSERT INTO #PVC VALUES (11743, N'81037761', N'81037761', N'Alarme Crítico Preventivo de Vazão Baixa Bombeamento de Água Recuperada Salobo III', 1, N'No Replication/Sem replicação', N'Anteriormente, não havia um alerta preventivo na tela do supervisório da Moagem para indicar condições de baixa vazão no Sistema de Bombeamento de Água Recuperada. Como a tela específica desse sistema possuía caráter secundário, seu monitoramento não era realizado continuamente pela operação da sala de controle, reduzindo a eficiência na detecção de falhas e no acompanhamento do processo. O técnico de sala só iria visualizar a redução do tanque de Água Recuperada quando subisse o alerta de nível menor que 75%.', N'Identificação rápida e proteção para evitar redução do nível do tanque de Água Recuperada Salobo III e prevenir interrupções ou cortes de alimentação na usina.', N'10025', N'01 - Imagens/01 - Antes/11743.jpeg', N'Anteriormente, não havia um alerta preventivo na tela do supervisório da Moagem para indicar condições de baixa vazão no Sistema de Bombeamento de Água Recuperada. Como a tela específica desse sistema era considerada secundária, seu monitoramento pelos técnicos da sala de controle não ocorria de forma contínua, reduzindo a agilidade na identificação de falhas. Dessa forma, a redução do nível do tanque de Água Recuperada normalmente só era percebida quando era gerado o alarme de nível inferior a 75%, o que podia atrasar a atuação da equipe e aumentar o risco de impactos no abastecimento de água da usina podendo levar a cortes de alimentação.', N'01 - Imagens/02 - Depois/11743.jpeg', N'Foi implementado um alerta preventivo na tela do supervisório da Moagem para sinalizar condições de baixa vazão no Sistema de Bombeamento de Água Recuperada. Com essa melhoria, a ocorrência passou a ser identificada de forma imediata pelos técnicos da sala de controle, mesmo sem o acompanhamento contínuo da tela específica de Água Recuperada. Dessa forma, houve aumento da eficiência no monitoramento, maior rapidez na tomada de decisão e maior confiabilidade operacional do sistema, reduzindo tanto o risco de impactos no abastecimento de água da usina quanto cortes de alimentação.', NULL, N'Alarme funcional e com visibilidade na tela dos moinhos no supervisório da sala de controle toda vez que acontece a redução da vazão do Bombeamento de Água Recuperada.', N'A importância de evitar redução no nível do tanque de Água Recuperada e cortes de alimentação da usina, garantindo maior segurança dos equipamentos, estabilidade operacional e produtividade.', 0, NULL, N'Automatizar a coleta de dados dos sensores Dynamox nas escavadeiras PC5500, eliminando a necessidade de sincronização manual, aumentando a disponibilidade das informações de monitoramento e melhorando a confiabilidade da manutenção preditiva.', '2026-08-15T00:00:00.000', '2026-08-16T03:32:47.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11744, N'81022747', N'81006480', N'MELHORIA NO  SISTEMA DE ABASTECIMENTO', 3, N'Others/Outros', N'Antes não tinha eficiência no sistema de abastecimento.', N'Melhorar a eficiencia', N'10144', N'01 - Imagens/01 - Antes/11744.jpeg', N'Sem eficiência no processo.', N'01 - Imagens/02 - Depois/11744.jpeg', N'MELHORIA NO  Sistema DE ABASTECIMENTO DO OLEO 15W40   COM ISSO GARANTINDO QUALIDADE E EFICIÊNCIA NO ABASTECIMENTO.', NULL, N'MELHORIA NO  SiSTEMA DE ABASTECIMENTO DO OLEO 15W40   COM ISSO GARANTINDO QUALIDADE E EFICIÊNCIA NO ABASTECIMENTO.', N'Melhoria', 0, NULL, N'Detectar precocemente falhas de lubrificação nos olhais da estrutura de ligação da caçamba da WE1850 por meio do monitoramento contínuo de temperatura, reduzindo o risco de desgaste prematuro, falhas corretivas, paradas não programadas e aumentando a confiabilidade operacional do equipamento.', '2026-08-15T00:00:00.000', '2026-08-16T11:44:57.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11745, N'81046537', N'81063692', N'Implementação de Suporte Metálico para Armazenamento de Caixas de Ferramentas', 3, N'Others/Outros', N'Durante realização do programa 5S, foi identificada uma não conformidade no armazenamento das caixas de ferramentas individuais dos técnicos. As caixas estavam dispostas diretamente sobre um palete de madeira posicionado no piso da área operacional.', N'Armazenamento de Caixas de Ferramentas para organização e cumprimento do 5S diário.', N'10150', N'01 - Imagens/01 - Antes/11745.jpeg', N'Durante realização do programa 5S, foi identificada uma não conformidade no armazenamento das caixas de ferramentas individuais dos técnicos. As caixas estavam dispostas diretamente sobre um palete de madeira posicionado no piso da área operacional. A baixa altura do palete obrigava os colaboradores a realizarem flexões excessivas de coluna e agachamentos repetitivos para acessar as ferramentas, aumentando o risco de LER/DORT e lesões lombares. A ausência de um local definido ("um lugar para cada coisa") resultava em disposição aleatória das caixas, dificultando a identificação e o acesso rápido. O palete no chão configurava um obstáculo físico, além de as caixas poderem deslizar ou cair devido à instabilidade da madeira. O contato direto com o piso (umidade, poeira, óleos) acelerava a deterioração das caixas e das ferramentas internas.', N'01 - Imagens/02 - Depois/11745.jpeg', N'Providenciado um Suporte Metálico de Armazenamento (Rack Organizadores), utilizando cantoneiras de aço soldadas dando forma a uma estruturadas para suportar a carga das caixas. O suporte foi confeccionado em perfis metálicos (cantoneiras), garantindo robustez e durabilidade, com pintura amarelo para identificação visual. O suporte eleva as caixas para uma altura média respeitando a zona de conforto ergonômico. Foram instaladas guias/cantoneiras inclinadas nas prateleiras, criando "baias" individuais. Isso impede que as caixas deslizem e mantém o alinhamento visual, facilitando a conferência de inventário. O rack verticaliza o armazenamento, liberando área de piso  para circulação e outras atividades.
INSERT INTO #PVC VALUES (11746, N'81046537', N'81063692', N' Substituição de fixação com abraçadeiras plásticas por suporte metálico parafusado', 1, N'Others/Outros', N'Durante inspeção técnica no sistema da escada de acesso principal, foi identificada uma não conformidade na fixação da chave fim de curso (limit switch) do circuito de elevação da escada. O componente eletrônico (Micro Switch LSYAB1A – Heavy Duty Limit Switch) estava fixado à estrutura utilizando abraçadeiras plásticas.', N'Fixação eficaz de suporte.', N'10150', N'01 - Imagens/01 - Antes/11746.jpeg', N'O componente eletrônico estava fixado à estrutura utilizando abraçadeiras plásticas. As abraçadeiras plásticas perdem resistência mecânica e ruptura precoce. A vibração causa afrouxamento das abraçadeiras, gerando folga no posicionamento do fim de curso. O desalinhamento do atuador (rolete) em relação à chapa de acionamento pode impedir o funcionamento correto do fim de curso, comprometendo a parada segura da escada no limite e ângulo correto.', N'01 - Imagens/02 - Depois/11746.jpeg', N'Instalado um suporte em chapa de aço, dimensionado para acomodar o corpo do limit switch com precisão dimensional, garantindo o alinhamento correto do atuador (rolete) com a chapa de acionamento da escada. A limit switch foi fixada à estrutura metálica mediante parafusos e porcas de travamento, impedindo o afrouxamento por vibração e garantindo estabilidade ao longo do tempo. O suporte permite ajuste milimétrico da posição do fim de curso, assegurando que o acionamento ocorra exatamente no ponto definido pelo projeto de segurança da escada.', NULL, N'Sim, Foi e instalado um suporte em chapa de aço (pintura amarela de segurança), dimensionado para acomodar o corpo do limit switch com precisão dimensional, garantindo o alinhamento correto do atuador (rolete) com a chapa de acionamento da escada.', N'Garantia de funcionamento e durabilidade dos equipamentos e seus componentes.', 0, NULL, N'Reduz o esforço operacional, a exposição a riscos e frequência no monitoramento do nível do reservatório.', '2026-08-10T00:00:00.000', '2026-08-16T16:50:36.000', N'81046537', NULL, NULL);
INSERT INTO #PVC VALUES (11747, N'81042755', N'81042755', N'Mill Motor Excitors SCR monitoring ', 1, N'Concentration/Concentração', N'Long life equipment and power electronics do eventually require replacement. 
INSERT INTO #PVC VALUES (11748, N'81006667', N'545267', N'ANL - Acordo de Nível de Limpeza', 3, N'Others/Outros', N'Após conclusão das atividades sempre era solicitado que refizessem a limpeza por falta de padronização no momento da validação. ', N'Evitar retrabalho de atividades de limpeza', N'10054', N'01 - Imagens/01 - Antes/11748.jpeg', N'Antes após conclusão das atividades sempre era solicitado que refizessem a limpeza por falta de padronização no momento da validação. ', N'01 - Imagens/02 - Depois/11748.jpeg', N'Criado formulário de validação de entrega das atividades de limpeza, dessa forma evitando retrabalho uma vez que o solicitante após recebimento do ativo deve assinar o formulário como Acordo de Nível de Limpeza. Procedimento atualizado no SISPAV.', NULL, N'Atingimos a meta inicial com a padronização do processo.', N'Sempre padronizar seus processos.', 0, NULL, N'Minimize spills ', '2026-08-04T00:00:00.000', '2026-08-17T09:23:26.000', N'81006667', NULL, NULL);
INSERT INTO #PVC VALUES (11749, N'81042856', N'81042856', N'EC14 - Instalação de Gateway Dynamox nas Escavadeiras Elétricas 7495', 1, N'Others/Outros', N'Atualmente, a coleta dos dados dos sensores Dynamox instalados nas escavadeiras elétricas 7495 depende da proximidade de dispositivos móveis ou de atividades manuais em campo, resultando em atrasos na obtenção das informações, perda de dados históricos e menor agilidade na identificação de anomalias. A ausência de transmissão automática limita o potencial da manutenção preditiva e aumenta o risco de falhas não detectadas em tempo hábil.', N'Implementar gateways Dynamox nas escavadeiras 7495 para viabilizar a coleta automática e contínua dos dados de vibração dos sensores, aumentando a confiabilidade do monitoramento preditivo, reduzindo a necessidade de coleta manual e possibilitando a identificação antecipada de falhas nos componentes críticos.', N'10015', N'01 - Imagens/01 - Antes/11749.jpeg', N'As escavadeiras elétricas 7495 possuíam sensores Dynamox instalados para monitoramento de condição, porém a coleta dos dados era realizada de forma manual, exigindo deslocamento da equipe até o equipamento para sincronização via dispositivo móvel. Essa condição ocasionava atrasos na obtenção das informações, possibilidade de perda de dados, baixa frequência de análise e maior exposição dos empregados em atividades de campo. Além disso, a indisponibilidade de dados em tempo real dificultava a identificação precoce de falhas em componentes críticos, reduzindo a efetividade da manutenção preditiva e aumentando os riscos de intervenções corretivas não planejadas.', N'01 - Imagens/02 - Depois/11749.jpeg', N'Foi realizada a instalação e configuração dos gateways Dynamox nas escavadeiras elétricas 7495, permitindo a transmissão automática dos dados coletados pelos sensores de monitoramento de condição para a plataforma online. Com a solução implementada, as informações passaram a ser disponibilizadas de forma contínua e remota, eliminando a necessidade de deslocamentos frequentes para sincronização manual dos dispositivos.', NULL, N'SIM, o problema foi resolvido. Com a instalação dos gateways Dynamox nas escavadeiras 7495, os dados dos sensores passaram a ser transmitidos automaticamente para a plataforma de monitoramento, eliminando a dependência da coleta manual. A solução proporcionou maior disponibilidade das informações, redução de deslocamentos para inspeções, maior rapidez na identificação de anomalias e aumento da confiabilidade do processo de manutenção preditiva, atendendo ao objetivo definido no Kaizen.', N'A instalação dos gateways Dynamox demonstrou que a transmissão automática dos dados aumenta significativamente a efetividade do monitoramento preditivo. O projeto evidenciou a importância do correto posicionamento dos gateways, validação da cobertura de comunicação e alinhamento entre as equipes de manutenção, automação e operação para garantir a confiabilidade da solução.', 0, NULL, N'O problema foi tratado por meio da criação e divulgação do Alerta de Segurança contendo orientações operacionais e de manutenção, identificação das principais causas de desgaste da corrente e definição das rotinas de inspeção, lubrificação, limpeza e controle operacional. A ação permitiu aumentar a conscientização das equipes e estabelecer medidas preventivas para reduzir a probabilidade de falhas, danos ao equipamento', '2026-08-06T00:00:00.000', '2026-08-17T09:39:30.000', N'81042856', NULL, NULL);
INSERT INTO #PVC VALUES (11750, N'81042856', N'81042856', N'EC18 - Instalação de Gateway Dynamox nas Escavadeiras Elétricas 7495', 1, N'Others/Outros', N'Atualmente, a coleta dos dados dos sensores Dynamox instalados nas escavadeiras elétricas 7495 depende da proximidade de dispositivos móveis ou de atividades manuais em campo, resultando em atrasos na obtenção das informações, perda de dados históricos e menor agilidade na identificação de anomalias. A ausência de transmissão automática limita o potencial da manutenção preditiva e aumenta o risco de falhas não detectadas em tempo hábil.', N'Implementar gateways Dynamox nas escavadeiras 7495 para viabilizar a coleta automática e contínua dos dados de vibração dos sensores, aumentando a confiabilidade do monitoramento preditivo, reduzindo a necessidade de coleta manual e possibilitando a identificação antecipada de falhas nos componentes críticos.', N'10015', N'01 - Imagens/01 - Antes/11750.jpeg', N'As escavadeiras elétricas 7495 possuíam sensores Dynamox instalados para monitoramento de condição, porém a coleta dos dados era realizada de forma manual, exigindo deslocamento da equipe até o equipamento para sincronização via dispositivo móvel. Essa condição ocasionava atrasos na obtenção das informações, possibilidade de perda de dados, baixa frequência de análise e maior exposição dos empregados em atividades de campo. Além disso, a indisponibilidade de dados em tempo real dificultava a identificação precoce de falhas em componentes críticos, reduzindo a efetividade da manutenção preditiva e aumentando os riscos de intervenções corretivas não planejadas.', N'01 - Imagens/02 - Depois/11750.jpeg', N'Foi realizada a instalação e configuração dos gateways Dynamox nas escavadeiras elétricas 7495, permitindo a transmissão automática dos dados coletados pelos sensores de monitoramento de condição para a plataforma online. Com a solução implementada, as informações passaram a ser disponibilizadas de forma contínua e remota, eliminando a necessidade de deslocamentos frequentes para sincronização manual dos dispositivos.', NULL, N'SIM, o problema foi resolvido. Com a instalação dos gateways Dynamox nas escavadeiras 7495, os dados dos sensores passaram a ser transmitidos automaticamente para a plataforma de monitoramento, eliminando a dependência da coleta manual. A solução proporcionou maior disponibilidade das informações, redução de deslocamentos para inspeções, maior rapidez na identificação de anomalias e aumento da confiabilidade do processo de manutenção preditiva, atendendo ao objetivo definido no Kaizen.', N'A instalação dos gateways Dynamox demonstrou que a transmissão automática dos dados aumenta significativamente a efetividade do monitoramento preditivo. O projeto evidenciou a importância do correto posicionamento dos gateways, validação da cobertura de comunicação e alinhamento entre as equipes de manutenção, automação e operação para garantir a confiabilidade da solução.', 0, NULL, N'visibilidade dos principais indicadores, desvios e oportunidades de melhoria, monitoramento contínuo da performance, tomada de decisão baseada em dados e maior direcionamento das ações para o alcance dos objetivos estratégicos da gerência.', '2026-08-05T00:00:00.000', '2026-08-17T09:43:18.000', N'81042856', NULL, NULL);
INSERT INTO #PVC VALUES (11751, N'81006667', N'545267', N'Padronização CCB Moagem', 2, N'Others/Outros', N'Único CCB para atender as demandas da moagem, flotação e utilidades, com isso ocasionava alguns erros de bloqueio, tais como equivoco de TAG''s de equipamentos.', N'Redução da probabilidade de equívocos com relação as TAG''s dos equipamentos.', N'10054', N'01 - Imagens/01 - Antes/11751.jpeg', N'Antes tinha um único CCB para atender as demandas da moagem, flotação e utilidades, com isso ocasionava alguns erros de bloqueio, tais como equivoco de TAG''s de equipamentos.', N'01 - Imagens/02 - Depois/11751.jpeg', N'Instalado na usina ao lado do SAG um CCB exclusivo para os bloqueios da moagem, assim reduzindo o tempo de deslocamento no momento da realização dos bloqueios, reduzindo a probabilidade de equívocos com relação as TAG''s dos equipamentos, uma vez que o atendimento é por circuito.', NULL, N'Meta superada', N'Solicitações de bloqueios e atendimento devem ser realizadas por circuitos diferente.', 0, NULL, N'Redução no tempo para definição de massa acumulada do dia', '2026-07-31T00:00:00.000', '2026-08-17T09:49:08.000', N'81006667', NULL, NULL);
INSERT INTO #PVC VALUES (11752, N'81006667', N'545267', N'Padronização CCB Flotação', 2, N'Others/Outros', N'Único CCB para atender as demandas da moagem, flotação e utilidades, com isso ocasionava alguns erros de bloqueio, tais como equivoco de TAG''s de equipamentos.', N'Redução da probabilidade de equívocos com relação as TAG''s dos equipamentos.', N'10054', N'01 - Imagens/01 - Antes/11752.jpeg', N'Antes era um único CCB para atender as demandas da moagem, flotação e utilidades, com isso ocasionava alguns erros de bloqueio, tais como equivoco de TAG''s de equipamentos.', N'01 - Imagens/02 - Depois/11752.jpeg', N'Instalado um contêiner ao lado da subestação na flotação, assim reduzindo o tempo de deslocamento no momento da realização dos bloqueios, reduzindo a probabilidade de equívocos com relação as TAG''s dos equipamentos, uma vez que o atendimento é por circuito.
INSERT INTO #PVC VALUES (11753, N'81042856', N'81042856', N'EC13 - Instalação de Gateways Dynamox nas Escavadeiras Hidráulicas PC5500', 1, N'Others/Outros', N'Atualmente, a coleta de dados dos sensores Dynamox instalados nas escavadeiras hidráulicas PC5500 depende da aproximação manual de um dispositivo móvel para sincronização das informações. Essa atividade demanda tempo da equipe de manutenção preditiva, gera risco de perda de dados devido a falhas na coleta e reduz a agilidade na identificação de falhas potenciais. A ausência de transmissão automática dificulta o monitoramento contínuo da condição dos ativos e pode impactar a tomada de decisão para intervenções planejadas.', N'Implementar Gateways Dynamox em 100% das escavadeiras hidráulicas PC5500, garantindo coleta automática e contínua dos dados dos sensores de vibração e temperatura, aumentando a confiabilidade do monitoramento preditivo, reduzindo inspeções manuais e aumentando a disponibilidade física dos ativos.', N'10015', N'01 - Imagens/01 - Antes/11753.jpeg', N'As escavadeiras hidráulicas PC5500 possuem sensores Dynamox instalados para monitoramento preditivo de componentes críticos. Entretanto, a coleta dos dados era realizada manualmente por meio da aproximação de dispositivo móvel aos sensores durante as rotas de inspeção.
INSERT INTO #PVC VALUES (11754, N'81042856', N'81042856', N'EC24 - Instalação de Gateways Dynamox nas Escavadeiras Hidráulicas PC5500', 1, N'Others/Outros', N'Atualmente, a coleta de dados dos sensores Dynamox instalados nas escavadeiras hidráulicas PC5500 depende da aproximação manual de um dispositivo móvel para sincronização das informações. Essa atividade demanda tempo da equipe de manutenção preditiva, gera risco de perda de dados devido a falhas na coleta e reduz a agilidade na identificação de falhas potenciais. A ausência de transmissão automática dificulta o monitoramento contínuo da condição dos ativos e pode impactar a tomada de decisão para intervenções planejadas.', N'Implementar Gateways Dynamox em 100% das escavadeiras hidráulicas PC5500, garantindo coleta automática e contínua dos dados dos sensores de vibração e temperatura, aumentando a confiabilidade do monitoramento preditivo, reduzindo inspeções manuais e aumentando a disponibilidade física dos ativos.', N'10015', N'01 - Imagens/01 - Antes/11754.jpeg', N'As escavadeiras hidráulicas PC5500 possuem sensores Dynamox instalados para monitoramento preditivo de componentes críticos. Entretanto, a coleta dos dados era realizada manualmente por meio da aproximação de dispositivo móvel aos sensores durante as rotas de inspeção.
