SELECT t.ID_KAIZEN, t.ID_USUARIO_LIDER, t.NM_HIERARQUIA_N1, t.NM_HIERARQUIA_N2, t.NM_HIERARQUIA_N3, t.NM_HIERARQUIA_N4, t.NM_HIERARQUIA_N5, t.NM_HIERARQUIA_N6, t.NM_HIERARQUIA_N7, t.NM_HIERARQUIA_N8, t.DT_ATUALIZACAO FROM #T t
WHERE EXISTS (SELECT 1 FROM #PVC p WHERE p.ID_KAIZEN = t.ID_KAIZEN);
PRINT '  KZN_HIST_KAIZEN_HIERARQUIA: ' + CAST(@@ROWCOUNT AS VARCHAR(10)) + ' linha(s).';
DROP TABLE #T;

/* =====================================================================
   E6 - Desperdicios
   ===================================================================== */
CREATE TABLE #T (ID_KAIZEN INT, ID_DESPERDICIO INT, DT_ATUALIZACAO DATETIME2(3));
SELECT t.ID_KAIZEN, t.ID_DESPERDICIO, t.DT_ATUALIZACAO FROM #T t
WHERE EXISTS (SELECT 1 FROM #PVC p WHERE p.ID_KAIZEN = t.ID_KAIZEN);
PRINT '  KZN_HIST_KAIZEN_DESPERDICIO: ' + CAST(@@ROWCOUNT AS VARCHAR(10)) + ' linha(s).';
DROP TABLE #T;

/* =====================================================================
   E7 - Pendencias (antes do COMMIT)
   ===================================================================== */
SELECT  PROBLEMA = 'REPLICACAO sem correspondencia em CI.KZN_REPLICACAO',
        TEXTO_DA_PLANILHA = p.TX_REPLICACAO, QT_KAIZENS = COUNT(*)
FROM    #PVC p
JOIN    CI.KZN_HIST_PEDRAVISAOCONSOLIDADA h ON h.ID_KAIZEN = p.ID_KAIZEN
WHERE   h.ID_REPLICACAO IS NULL AND p.TX_REPLICACAO IS NOT NULL
GROUP BY p.TX_REPLICACAO;

SELECT  PROBLEMA = 'ID_APROVADOR nao numerico -> gravado NULL',
        QT_KAIZENS = COUNT(*)
FROM    #PVC WHERE TX_APROVADOR IS NOT NULL AND TRY_CONVERT(INT, TX_APROVADOR) IS NULL;

DROP TABLE #PVC;

COMMIT TRANSACTION;
PRINT 'Carga concluida.';

END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    PRINT 'ERRO - nada foi gravado (rollback aplicado): ' + ERROR_MESSAGE();
    THROW;
END CATCH
GO

/* =====================================================================
   E8 - CONFERENCIA
   ===================================================================== */
SELECT TABELA='KZN_HIST_PEDRAVISAOCONSOLIDADA', LINHAS=COUNT(*) FROM CI.KZN_HIST_PEDRAVISAOCONSOLIDADA WHERE ID_KAIZEN BETWEEN 7281 AND 12267
UNION ALL SELECT 'KZN_HIST_MEMBROS_EQUIPE',     COUNT(*) FROM CI.KZN_HIST_MEMBROS_EQUIPE      WHERE ID_KAIZEN BETWEEN 7281 AND 12267
UNION ALL SELECT 'KZN_HIST_RESULTADO_KAIZEN',   COUNT(*) FROM CI.KZN_HIST_RESULTADO_KAIZEN    WHERE ID_KAIZEN BETWEEN 7281 AND 12267
UNION ALL SELECT 'KZN_HIST_KAIZEN_HIERARQUIA',  COUNT(*) FROM CI.KZN_HIST_KAIZEN_HIERARQUIA   WHERE ID_KAIZEN BETWEEN 7281 AND 12267
UNION ALL SELECT 'KZN_HIST_KAIZEN_DESPERDICIO', COUNT(*) FROM CI.KZN_HIST_KAIZEN_DESPERDICIO  WHERE ID_KAIZEN BETWEEN 7281 AND 12267;
GO
